['Here is a C code implementation for a thread-safe, scalable logging framework that supports multiple output destinations with different severity levels:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_MESSAGE 1024

typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    char message[MAX_LOG_MESSAGE];
    time_t timestamp;
    pthread_mutex_t lock;
} LogEntry;

LogEntry logQueue[256]; // Adjust size based on expected load.
int queueSize = 0;
pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condVar = PTHREAD_COND_INITIALIZER;

void initLoggingSystem() {
    for (int i = 0; i < sizeof(logQueue) / sizeof(LogEntry); i++) {
        pthread_mutex_init(&logQueue[i].lock, NULL);
    }
}

void deinitLoggingSystem() {
    for (int i = 0; i < sizeof(logQueue) / sizeof(LogEntry); i++) {
        pthread_mutex_destroy(&logQueue[i].lock);
    }
    pthread_mutex_destroy(&queueMutex);
    pthread_cond_destroy(&condVar);
}

static void logToFile(const char *filename, const LogEntry *entry) {
    FILE *file = fopen(filename, "a");
    if (file != NULL) {
        fprintf(file, "[%s] %s\n", entry->message, ctime((const time_t *)&entry->timestamp));
        fclose(file);
    }
}

static void logToConsole(const LogEntry *entry) {
    printf("[%s] %s\n", entry->message, ctime((const time_t *)&entry->timestamp));
}

void enqueueLog(LogLevel level, const char *format, va_list args) {
    pthread_mutex_lock(&queueMutex);

    while (queueSize == sizeof(logQueue) / sizeof(LogEntry)) {
        pthread_cond_wait(&condVar, &queueMutex);
    }

    LogEntry entry;
    entry.level = level;
    entry.timestamp = time(NULL);
    vsnprintf(entry.message, MAX_LOG_MESSAGE, format, args);

    logQueue[queueSize++] = entry;

    pthread_mutex_unlock(&queueMutex);
    pthread_cond_signal(&condVar);
}

void* loggingThread(void *arg) {
    const char *filename = (const char *)arg;
    while (1) {
        pthread_mutex_lock(&queueMutex);

        while (queueSize == 0) {
            pthread_cond_wait(&condVar, &queueMutex);
        }

        LogEntry entry = logQueue[0];
        memmove(logQueue, logQueue + 1, (--queueSize) * sizeof(LogEntry));

        pthread_mutex_unlock(&queueMutex);

        if (entry.level <= LOG_LEVEL_ERROR || entry.level == LOG_LEVEL_DEBUG) {
            logToConsole(&entry);
            logToFile(filename, &entry);
        }
    }

    return NULL;
}

void startLogging(const char *filename) {
    pthread_t threadId;
    pthread_create(&threadId, NULL, loggingThread, (void *)filename);
}

void log(LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);

    enqueueLog(level, format, args);

    va_end(args);
}
```

### Usage

1. Initialize the logging system with `initLoggingSystem()`.
2. Start a logging thread using `startLogging("logfile.txt")` where `"logfile.txt"` is your desired log file.
3. Use `log(LOG_LEVEL_ERROR, "Error occurred: %s", errorDetail)` to log messages at different severity levels.

This implementation provides:
- Thread safety using mutexes and condition variables.
- Separate handling for console and file output with dynamic configuration potential.
- A mechanism to manage concurrency and optimize performance under load.
- Scalability through multiple logging threads or processes.']

['Below is an example implementation in C that demonstrates how you might create a flexible encryption framework supporting AES, ChaCha20, and XChaCha20 algorithms with various modes of operation (CBC, GCM, CTR). The function accepts algorithm parameters through a configuration structure.

```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the configuration structure for encryption settings.
typedef struct {
    const char *algorithm; // "AES", "ChaCha20", or "XChaCha20"
    const char *mode;      // "CBC", "GCM", or "CTR"
    int key_len;           // Key length in bits
    int iv_len;            // IV/nonce length in bytes
} EncryptionConfig;

// Function to initialize the encryption based on configuration.
EVP_CIPHER_CTX* init_encryption(EncryptionConfig config, const unsigned char *key, 
                                const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = NULL;
    int cipher_type;

    // Initialize OpenSSL algorithms and error strings
    if (!OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CRYPTO_STRINGS | OPENSSL_INIT_ADD_ALL_CIPHERS, NULL)) {
        fprintf(stderr, "OpenSSL initialization failed\n");
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context\n");
        goto cleanup;
    }

    // Select the cipher based on algorithm and mode
    if (strcmp(config.algorithm, "AES") == 0) {
        if (strcmp(config.mode, "CBC") == 0) {
            cipher_type = EVP_aes_128_cbc();
        } else if (strcmp(config.mode, "GCM") == 0) {
            cipher_type = EVP_aes_256_gcm(); // Default to AES-256-GCM
        } else if (strcmp(config.mode, "CTR") == 0) {
            cipher_type = EVP_aes_128_ctr();
        } else {
            fprintf(stderr, "Unsupported mode for AES\n");
            goto cleanup;
        }
    } else if (strcmp(config.algorithm, "ChaCha20") == 0) {
        if (strcmp(config.mode, "CTR") == 0) { // ChaCha20 is inherently a stream cipher
            cipher_type = EVP_chacha20();
        } else {
            fprintf(stderr, "Unsupported mode for ChaCha20\n");
            goto cleanup;
        }
    } else if (strcmp(config.algorithm, "XChaCha20") == 0) {
        if (strcmp(config.mode, "CTR") == 0) { // XChaCha20 is inherently a stream cipher
            cipher_type = EVP_xchacha20();
        } else {
            fprintf(stderr, "Unsupported mode for XChaCha20\n");
            goto cleanup;
        }
    } else {
        fprintf(stderr, "Unsupported algorithm\n");
        goto cleanup;
    }

    // Initialize the encryption context with the chosen cipher
    if (EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv) != 1) {
        fprintf(stderr, "Encryption initialization failed\n");
        goto cleanup;
    }

    return ctx;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    ERR_print_errors_fp(stderr);
    return NULL;
}

int main() {
    // Example configuration
    EncryptionConfig config = {"AES", "GCM", 256, 12};
    unsigned char key[32];     // AES-256 requires a 32-byte key
    unsigned char iv[12];      // GCM typically uses a 12-byte nonce

    // Example key and IV initialization (in practice, use secure random values)
    memset(key, 0x01, sizeof(key));
    memset(iv, 0x00, sizeof(iv));

    EVP_CIPHER_CTX *ctx = init_encryption(config, key, iv);
    if (ctx == NULL) {
        fprintf(stderr, "Failed to initialize encryption\n");
        return EXIT_FAILURE;
    }

    // Use the context for encryption/decryption...

    EVP_CIPHER_CTX_free(ctx);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Initialization**: The function initializes OpenSSL and creates an `EVP_CIPHER_CTX` based on the provided configuration.
- **Cipher Selection**: It selects the appropriate cipher algorithm and mode using string comparisons.
- **Error Handling**: Proper error handling is implemented, with cleanup in case of failure.
- **Flexibility**: The function can be easily extended to support additional algorithms or modes by modifying the `EncryptionConfig` structure and adding corresponding logic.

This code provides a basic framework for flexible encryption. Depending on your specific requirements, you may need to extend it further, especially regarding performance optimizations and integration with existing systems.']

['Below is a Java implementation that addresses the given requirements:

```java
import java.util.*;
import java.util.concurrent.*;
import java.net.http.*;
import java.net.URI;
import com.fasterxml.jackson.databind.ObjectMapper;

class Pokemon {
    private String name;
    private List<String> types;

    // Constructor, getters, and setters
}

class PokemonReport {
    private String growthRate;
    private int hatchSteps;
    private Map<String, List<String>> weaknessesResistancesImmunities;

    // Constructor, getters, and setters
}

public class PokemonService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/%s";
    private static final long CACHE_EXPIRY_TIME_MS = 60000; // Cache expiry time in milliseconds

    private final Map<String, PokemonReport> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService cacheCleaner = Executors.newScheduledThreadPool(1);
    private final ExecutorService apiExecutor = Executors.newFixedThreadPool(10); // Thread pool for API calls
    private final HttpClient httpClient = HttpClient.newHttpClient();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public PokemonService() {
        // Schedule a task to clear expired cache entries
        cacheCleaner.scheduleAtFixedRate(this::clearExpiredCache, CACHE_EXPIRY_TIME_MS, CACHE_EXPIRY_TIME_MS, TimeUnit.MILLISECONDS);
    }

    public void generateReport(Pokemon pokemon) {
        if (pokemon == null || pokemon.getTypes() == null || pokemon.getTypes().isEmpty()) {
            System.err.println("Invalid Pokemon data.");
            return;
        }

        String pokemonName = pokemon.getName();
        PokemonReport report = cache.computeIfAbsent(pokemonName, this::fetchAndCachePokemonData);

        // Use the report to generate a detailed output
        System.out.println("Growth Rate: " + report.getGrowthRate());
        System.out.println("Hatch Steps: " + report.getHatchSteps());
        System.out.println("Weaknesses: " + report.getWeaknessesResistancesImmunities().getOrDefault("weaknesses", Collections.emptyList()));
    }

    private PokemonReport fetchAndCachePokemonData(String pokemonName) {
        try {
            CompletableFuture.supplyAsync(() -> callApi(pokemonName), apiExecutor)
                    .thenApply(this::parseApiResponse)
                    .exceptionally(ex -> {
                        System.err.println("Failed to fetch data for " + pokemonName + ": " + ex.getMessage());
                        return new PokemonReport();
                    })
                    .join();

            // Return cached data
            return cache.get(pokemonName);
        } catch (Exception e) {
            System.err.println("Error generating report: " + e.getMessage());
            return new PokemonReport();
        }
    }

    private String callApi(String pokemonName) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(String.format(API_URL, pokemonName)))
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() != 200) {
            throw new RuntimeException("Failed to fetch data: " + response.body());
        }

        return response.body();
    }

    private PokemonReport parseApiResponse(String jsonResponse) throws Exception {
        Map<String, Object> apiData = objectMapper.readValue(jsonResponse, Map.class);

        String growthRate = (String) apiData.get("growth_rate");
        int hatchSteps = (int) ((Map<String, Object>) apiData.get("egg_groups")).get(0); // Assuming first egg group

        List<String> types = Arrays.asList((List<String>) apiData.get("types"));
        Map<String, List<String>> weaknessesResistancesImmunities = determineWeaknessesResistancesImmunities(types);

        return new PokemonReport(growthRate, hatchSteps, weaknessesResistancesImmunities);
    }

    private Map<String, List<String>> determineWeaknessesResistancesImmunities(List<String> types) {
        // Example strategy pattern or map-based approach
        Map<String, Function<List<String>, List<String>>> typeEffects = new HashMap<>();
        typeEffects.put("fire", this::getFireTypeEffect);
        // Add more type effects as needed

        Map<String, List<String>> result = new HashMap<>();
        for (String type : types) {
            for (Map.Entry<String, Function<List<String>, List<String>>> entry : typeEffects.entrySet()) {
                if (entry.getKey().equals(type)) {
                    result.merge("weaknesses", entry.getValue().apply(types), (a, b) -> a);
                    result.merge("resistances", entry.getValue().apply(types), (a, b) -> a);
                    // Handle immunities similarly
                }
            }
        }

        return result;
    }

    private List<String> getFireTypeEffect(List<String> types) {
        // Example logic for fire type weaknesses/resistances/immunities
        List<String> effect = new ArrayList<>();
        if (!types.contains("water")) effect.add("water");
        if (!types.contains("rock")) effect.add("rock");
        return effect;
    }

    private void clearExpiredCache() {
        long currentTime = System.currentTimeMillis();
        cache.entrySet().removeIf(entry -> (currentTime - entry.getValue().getTimestamp()) > CACHE_EXPIRY_TIME_MS);
    }
}
```

### Key Points:
- **Concurrency**: Uses `ConcurrentHashMap` for thread-safe caching and an `ExecutorService` for managing API calls.
- **Caching**: Implements a simple cache with expiry to minimize API calls.
- **Error Handling**: Gracefully handles null values, invalid inputs, and network failures.
- **Extensibility**: Designed to accommodate new types or data fields easily.
- **Performance**: Optimizes for latency and memory usage while maintaining scalability.']

['Below is a C code outline implementing the described modular architecture for cryptographic functions using dynamic loading, threading, configuration files, logging, and plugin support. This example leverages POSIX APIs and external libraries such as `dlopen`, `pthread`, and `json-c` for JSON parsing.

```c
#include <stdio.h>
#include <stdlib.h>
import <dlfcn.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h>  // JSON-C library for configuration handling

// Define a structure to hold function pointers and names
typedef struct {
    void* handle;
    char* name;
    double (*function)(const unsigned char *data, size_t data_len);
} CryptoFunction;

#define MAX_FUNCTIONS 10
static CryptoFunction hash_functions[MAX_FUNCTIONS];
static CryptoFunction cipher_functions[MAX_FUNCTIONS];

// Mutexes for thread safety
pthread_mutex_t mutex_hash = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_cipher = PTHREAD_MUTEX_INITIALIZER;

// Function to load a dynamic library and return function pointer
void* load_library_function(const char* lib_path, const char* func_name) {
    void *handle = dlopen(lib_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Cannot open library: %s\n", dlerror());
        exit(1);
    }

    // Reset errors
    dlerror();

    // Load the symbol
    void* func_ptr = dlsym(handle, func_name);
    const char *dlsym_error = dlerror();
    if (dlsym_error) {
        fprintf(stderr, "Cannot load symbol: %s\n", dlsym_error);
        dlclose(handle);
        exit(1);
    }

    return handle;
}

// Function to unload a dynamic library
void unload_library(void *handle) {
    if (!dlclose(handle)) {
        fprintf(stderr, "Cannot close library\n");
        exit(1);
    }
}

// Load configuration from JSON file
int load_configuration(const char* config_file) {
    json_error_t error;
    json_t *root = json_load_file(config_file, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    // Parse enabled hash functions
    const char* hash_list_path = "/hash_functions";
    json_t *hash_functions_json = json_object_get(root, hash_list_path);

    size_t index;
    json_t *value;

    json_array_foreach(hash_functions_json, index, value) {
        if (!json_is_string(value)) continue;

        // Load each function dynamically
        char* func_name = json_string_value(value);
        void* handle = load_library_function(func_name, "hash_func");
        hash_functions[index].handle = handle;
        hash_functions[index].name = strdup(func_name);
    }

    // Parse enabled cipher functions similarly...

    json_decref(root);
    return 0;
}

// Performance measurement function
double measure_performance(void* func_ptr, const unsigned char *data, size_t data_len) {
    clock_t start = clock();
    double result = ((double(*)(const unsigned char *, size_t))func_ptr)(data, data_len);
    clock_t end = clock();

    return (double)(end - start) / CLOCKS_PER_SEC + result;
}

// Logging function
void log_usage(const char* func_name, double execution_time) {
    // Append to a log file or use syslog
    printf("Function %s executed in %f seconds\n", func_name, execution_time);
}

// Validate cryptographic output (example placeholder)
int validate_output(const unsigned char *output, size_t output_len) {
    // Implement validation logic here
    return 1; // Placeholder
}

// Main function to demonstrate the architecture
int main(int argc, char* argv[]) {
    if (load_configuration("config.json") != 0) {
        fprintf(stderr, "Failed to load configuration\n");
        return EXIT_FAILURE;
    }

    // Example usage of a hash function
    pthread_mutex_lock(&mutex_hash);
    for (size_t i = 0; i < MAX_FUNCTIONS; ++i) {
        if (hash_functions[i].handle) {
            const unsigned char data[] = "sample data";
            double execution_time = measure_performance(hash_functions[i].function, data, sizeof(data));
            log_usage(hash_functions[i].name, execution_time);
            validate_output((const unsigned char*)&execution_time, sizeof(execution_time));

            // Unload when done
            unload_library(hash_functions[i].handle);
        }
    }
    pthread_mutex_unlock(&mutex_hash);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Loading**: Uses `dlopen` and `dlsym` to dynamically load cryptographic functions at runtime.
- **Configuration Handling**: Loads settings from a JSON configuration file, allowing for flexible specification of enabled algorithms.
- **Thread Safety**: Ensures safe concurrent access with mutexes (`pthread_mutex_t`).
- **Performance Measurement**: Captures the execution time of each function using `clock()`.
- **Logging and Validation**: Logs performance data and includes a placeholder for output validation.

This code provides a framework, but requires actual cryptographic function implementations to be compiled as shared libraries (e.g., `.so` files) with `hash_func()` exported. Additionally, error handling can be expanded based on specific application needs.']

