}

// Load shared library dynamically
void* load_library(const char *library_name) {
    void **handles = malloc(sizeof(void *));
    if (!handles) return NULL;

    handles[0] = dlopen(library_name, RTLD_LAZY);
    if (!handles[0]) {
        free(handles);
        return NULL;
    }

    pthread_mutex_lock(&lib_cache_lock);
    lib_cache.handles = realloc(lib_cache.handles, sizeof(void *) * (lib_cache.count + 1));
    lib_cache.handles[lib_cache.count++] = handles[0];
    pthread_mutex_unlock(&lib_cache_lock);

    return handles[0];
}

// Create cipher object
CipherObject* create_cipher_object(CipherConfig *config) {
    CipherObject *cipher_obj = malloc(sizeof(CipherObject));
    if (!cipher_obj) return NULL;

    void *library_handle = dlopen(config->cipher_type, RTLD_LAZY);
    if (!library_handle) {
        free(cipher_obj);
        return NULL;
    }

    cipher_obj->handle = library_handle;
    cipher_obj->init = dlsym(library_handle, "init");
    cipher_obj->cleanup = dlsym(library_handle, "cleanup");

    if (!cipher_obj->init || !cipher_obj->cleanup) {
        dlclose(cipher_handle);
        free(cipher_obj);
        return NULL;
    }

    // Initialize the cipher object
    if (cipher_obj->init(cipher_obj, config->key, config->iv_length, config->mode) != 0) {
        dlclose(library_handle);
        free(cipher_obj);
        return NULL;
    }

    cipher_obj->cipher_type = strdup(config->cipher_type);

    return cipher_obj;
}

// Free cipher object
void free_cipher_object(CipherObject **cipher) {
    if (!cipher || !*cipher) return;

    pthread_mutex_lock(&lib_cache_lock);
    for (size_t i = 0; i < lib_cache.count; ++i) {
        if (lib_cache.handles[i] == (*cipher)->handle) {
            dlclose(lib_cache.handles[i]);
            memmove(&lib_cache.handles[i], &lib_cache.handles[i + 1],
                    sizeof(void *) * (lib_cache.count - i - 1));
            lib_cache.count--;
            break;
        }
    }
    pthread_mutex_unlock(&lib_cache_lock);

    if ((*cipher)->cleanup) {
        (*cipher)->cleanup(*cipher);
    }

    free((*cipher)->cipher_type);
    free(*cipher);
    *cipher = NULL;
}

// Log error (stub)
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
