using System.Threading.Tasks;

public class SearchQueryProcessor
{
    public async Task<IDataReader> ProcessSearchAsync(
        List<string> searchTerms, 
        SqlConnection connection, 
        string baseSqlCommand)
    {
        if (connection == null) throw new ArgumentNullException(nameof(connection));
        if (string.IsNullOrWhiteSpace(baseSqlCommand)) throw new ArgumentException("Base SQL command cannot be null or empty.", nameof(baseSqlCommand));

        try
        {
            // Ensure the connection is open
            if (connection.State != ConnectionState.Open)
                await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = BuildDynamicSqlCommand(baseSqlCommand, searchTerms);

                var parameterIndex = 1;
                foreach (var term in searchTerms.Where(t => !string.IsNullOrWhiteSpace(t)))
                {
                    command.Parameters.AddWithValue($"@param{parameterIndex++}", $"%{term}%");
                }

                // Execute the query and fetch results
                using (var reader = await command.ExecuteReaderAsync())
                {
                    return reader;
                }
            }
        }
        catch (SqlException ex)
        {
            throw new Exception("An error occurred while executing the search query.", ex);
        }
    }

    private string BuildDynamicSqlCommand(string baseCommand, List<string> terms)
    {
        if (string.IsNullOrWhiteSpace(baseCommand))
            return baseCommand;

        var whereClause = terms
            .Where(t => !string.IsNullOrWhiteSpace(t))
            .Select((term, index) => $"Column LIKE @param{index + 1}")
            .ToList();

        if (!whereClause.Any())
            return baseCommand; // No search terms to filter

        return $"{baseCommand} WHERE {string.Join(" OR ", whereClause)}";
    }

    public async Task<string> FetchAdditionalMetadataAsync(string searchTerm)
    {
        // Simulate an API call to fetch metadata
        await Task.Delay(100); // Simulated latency

        // This would be replaced with actual logic to call a third-party API.
        return $"Metadata for {searchTerm}";
    }
}
