using System;
using System.Collections.Concurrent;
using System.IO;
using System.Text.Json;
using System.Threading.Tasks;

namespace GameConfigManager
{
    public class ConfigManager : IDisposable
    {
        private readonly string _configFilePath;
        private readonly ConcurrentDictionary<string, dynamic> _cache = new();
        private readonly object _lockObj = new();
        private Timer _reloadTimer;

        public ConfigManager(string configFilePath)
        {
            _configFilePath = configFilePath;
            LoadConfigAsync().Wait();
            SetupReloadTimer();
        }

        private async Task LoadConfigAsync()
        {
            lock (_lockObj)
            {
                var jsonText = await File.ReadAllTextAsync(_configFilePath);
                var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                var config = JsonSerializer.Deserialize<JsonDocument>(jsonText, options).RootElement;

                foreach (var property in config.EnumerateObject())
                {
                    _cache[property.Name] = property.Value;
                }
            }
        }

        private void SetupReloadTimer()
        {
            _reloadTimer = new Timer(async _ => await LoadConfigAsync(), null, TimeSpan.FromMinutes(1), TimeSpan.FromMinutes(1));
        }

        public dynamic GetSetting(string key)
        {
            if (_cache.TryGetValue(key, out var value))
            {
                return value;
            }
            return null; // or handle missing setting case
        }

        public async Task RefreshConfigAsync()
        {
            await LoadConfigAsync();
        }

        public void Dispose()
        {
            _reloadTimer?.Dispose();
        }
    }

    public class CacheDistributor<T>
    {
        private readonly ConcurrentDictionary<string, T> _distributedCache = new();

        public void UpdateCache(string key, T value)
        {
            _distributedCache[key] = value;
        }

        public T GetFromCache(string key)
        {
            return _distributedCache.TryGetValue(key, out var value) ? value : default;
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            string configFilePath = "path_to_config.json";

            using var configManager = new ConfigManager(configFilePath);
            dynamic settingValue = configManager.GetSetting("someKey");

            Console.WriteLine($"Config Value: {settingValue}");

