using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;
using System.Collections.Concurrent;

public class XmlDirectoryManager
{
    private static readonly object LockObject = new object();

    public string ProcessXmlAndManageDirectories(string xmlContent, string elementName)
    {
        ConcurrentQueue<string> logMessages = new ConcurrentQueue<string>();
        try
        {
            // Parse the XML document using XPath
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.LoadXml(xmlContent);
            XPathNavigator navigator = xmlDoc.CreateNavigator();

            // Identify first matching element
            XPathNodeIterator nodes = navigator.Select($"//{elementName}");

            if (nodes.Count == 0)
                throw new Exception($"No elements found with the name '{elementName}'.");

            if (nodes.Count > 1)
                throw new Exception($"Multiple elements found with the name '{elementName}'. Only one expected.");

            XPathNavigator firstNode = nodes.Current;

            // Manage configuration directory
            string envVar = "APP_CONFIG_DIR";
            string configDirectory = Environment.GetEnvironmentVariable(envVar);

            if (string.IsNullOrEmpty(configDirectory))
            {
                configDirectory = CreateAndSetConfigDirectory(envVar, logMessages);
            }
            else if (!Directory.Exists(configDirectory))
            {
                configDirectory = RecreateConfigDirectory(envVar, configDirectory, logMessages);
            }

            // Process the firstNode content as needed...
            // Example action: simply logging its value
            string nodeValue = firstNode.Value;
            logMessages.Enqueue($"Processed element '{elementName}' with value: {nodeValue}");

            return string.Join(Environment.NewLine, logMessages);
        }
        catch (Exception ex)
        {
            logMessages.Enqueue($"Error: {ex.Message}");
            return string.Join(Environment.NewLine, logMessages);
        }
    }

    private string CreateAndSetConfigDirectory(string envVar, ConcurrentQueue<string> logs)
    {
        lock (LockObject)
        {
            string newDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Config");
            if (!Directory.Exists(newDir))
                Directory.CreateDirectory(newDir);

            Environment.SetEnvironmentVariable(envVar, newDir);
            logs.Enqueue($"Created and set environment variable '{envVar}' to directory: {newDir}");
            return newDir;
        }
    }

    private string RecreateConfigDirectory(string envVar, string existingDir, ConcurrentQueue<string> logs)
    {
        lock (LockObject)
        {
            try
            {
                if (Directory.Exists(existingDir))
                    Directory.Delete(existingDir, true);

                Directory.CreateDirectory(existingDir);
                Environment.SetEnvironmentVariable(envVar, existingDir);
                logs.Enqueue($"Recreated and updated environment variable '{envVar}' to directory: {existingDir}");
                return existingDir;
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to recreate directory '{existingDir}': {ex.Message}", ex);
            }
        }
    }
}
