    private readonly IMemoryCache _cache;
    private readonly ILogger<HtmlUpdateService> _logger;

    public HtmlUpdateService(IHtmlContentUpdater htmlContentUpdater, IMemoryCache cache, ILogger<HtmlUpdateService> logger)
    {
        _htmlContentUpdater = htmlContentUpdater ?? throw new ArgumentNullException(nameof(htmlContentUpdater));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
