    public async Task ProcessHttpPostRequestAsync(string pageSectionId, string elementId, string newHtmlContent)
    {
        if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId))
            throw new ArgumentException("Page section ID and element ID must not be null or empty.");

        if (!IsValidHtml(newHtmlContent))
            throw new ArgumentException("Malformed HTML content provided.");

        var cacheKey = $"{pageSectionId}:{elementId}";

        await _cache.GetOrCreateAsync(cacheKey, async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);

            bool updateSuccessful = false;
            int retryCount = 0;

            while (!updateSuccessful && retryCount < 3)
            {
                try
                {
                    await _htmlContentUpdater.UpdateHtmlAsync(pageSectionId, elementId, newHtmlContent);
                    updateSuccessful = true;
                    NotifyClients(pageSectionId, elementId);

                    _logger.LogInformation("Successfully updated HTML content for section '{PageSectionId}' and element '{ElementId}'.", pageSectionId, elementId);
                }
                catch (Exception ex)
                {
                    retryCount++;
                    _logger.LogWarning(ex, "Failed to update HTML content on attempt {Attempt}. Retrying...", retryCount);

                    if (retryCount == 3)
                        throw;

                    await Task.Delay(1000); // Delay before retrying
