// Configure services in Startup.cs or Program.cs
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Add Identity services with customizable policies
        services.AddIdentity<CustomUser, IdentityRole>(options =>
        {
            options.Password.RequiredLength = 8; // Customize password policy
            options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(15);
            options.Lockout.MaxFailedAccessAttempts = 5;
            options.User.RequireUniqueEmail = true;

            // Add more policies as needed
        })
        .AddEntityFrameworkStores<ApplicationDbContext>()
        .AddDefaultTokenProviders();

        // Configure email service for password reset notifications
        services.AddTransient<IEmailSender, CustomEmailSender>();

        // Register UserManager and SignInManager for dependency injection
        services.AddScoped<UserManager<CustomUser>>();
        services.AddScoped<SignInManager<CustomUser>>();

        // Add other necessary services here
    }

    public void Configure(IApplicationBuilder app)
    {
        app.UseAuthentication();
        app.UseAuthorization();

        // Additional middleware configuration
    }
}

// Custom user class extending IdentityUser
public class CustomUser : IdentityUser
{
    // Extend with additional properties as needed
}

// Implementing a custom email sender for notifications
public interface IEmailSender
{
    Task SendEmailAsync(string email, string subject, string message);
}

public class CustomEmailSender : IEmailSender
{
    public async Task SendEmailAsync(string email, string subject, string message)
    {
        // Integrate with an external email service (e.g., SendGrid, SMTP)
        Console.WriteLine($"Sending email to {email}: {subject} - {message}");
        await Task.CompletedTask;
    }
}

// Token generation for password reset
public class PasswordResetTokenService : IPasswordResetTokenService
{
    private readonly UserManager<CustomUser> _userManager;

    public PasswordResetTokenService(UserManager<CustomUser> userManager)
    {
        _userManager = userManager;
    }

    public async Task<string> GeneratePasswordResetTokenAsync(CustomUser user, int tokenLifetimeMinutes = 30)
    {
        var options = new IdentityOptions();
        return await _userManager.GeneratePasswordResetTokenAsync(user);
    }

    public async Task<bool> ValidatePasswordResetTokenAsync(string userId, string token, int tokenLifetimeMinutes = 30)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null) return false;

        var now = DateTime.UtcNow;
        var result = await _userManager.VerifyUserTokenAsync(user, "Custom", "ResetPassword", token);

        // Ensure the token is within its valid lifetime
        return result && (now - user.PasswordHashChangedTime).TotalMinutes <= tokenLifetimeMinutes;
    }
}

// Interface for password reset token service
public interface IPasswordResetTokenService
{
    Task<string> GeneratePasswordResetTokenAsync(CustomUser user, int tokenLifetimeMinutes);
    Task<bool> ValidatePasswordResetTokenAsync(string userId, string token, int tokenLifetimeMinutes);
}
