const fs = require('fs').promises;
const path = require('path');
const util = require('util');
const glob = util.promisify(require('glob'));
const os = require('os');

async function processFiles(dir, options) {
  const logMessage = (message) => console.log(`[${new Date().toISOString()}] ${message}`);

  try {
    // Fetch all files in the directory
    const filePaths = await glob(path.join(dir, '**/*'), { nodir: true });

    for (const filePath of filePaths) {
      try {
        const stats = await fs.stat(filePath);

        // Filter by creation date and size
        if (!passesFilters(stats, options)) continue;

        logMessage(`Processing file: ${filePath}`);

        let metadata;
        try {
          metadata = await extractMetadata(filePath);
        } catch (err) {
          logMessage(`Error extracting metadata for ${filePath}: ${err.message}`);
          continue; // Skip this file on error
        }

        processFile(filePath, metadata);

      } catch (error) {
        logMessage(`I/O Error processing ${filePath}: ${error.message}`);
      }
    }
  } catch (error) {
    logMessage(`Error reading directory ${dir}: ${error.message}`);
  }
}

function passesFilters(stats, options) {
  const now = Date.now();

  if (options.creationDate && new Date(stats.birthtime).getTime() < options.creationDate) {
    return false;
  }

  if (options.sizeThreshold && stats.size > options.sizeThreshold) {
    return false;
  }

  return true;
}

async function extractMetadata(filePath) {
  const fileExtension = path.extname(filePath);

  // Example: Extendable to support new formats
  switch (fileExtension) {
    case '.txt':
      return await extractTextMetadata(filePath);
    case '.jpg':
    case '.png':
      return await fetchImageMetadataFromService(filePath);
    default:
      return {};
  }
}

async function extractTextMetadata(filePath) {
  const data = await fs.readFile(filePath, 'utf8');

  // Example: Basic metadata extraction
  return { length: data.length };
}

async function fetchImageMetadataFromService(filePath) {
  try {
    // Simulate a call to an external service
    logMessage(`Fetching metadata from service for ${filePath}`);

    // Simulating delay and potential network issues
    await new Promise((resolve, reject) => setTimeout(resolve, 1000));

    return { width: 800, height: 600 }; // Dummy response
  } catch (error) {
    throw new Error(`Failed to fetch metadata for ${filePath}: ${error.message}`);
  }
}

function processFile(filePath, metadata) {
  // Implement file processing logic here
  logMessage(`Processed file: ${filePath} with metadata:`, metadata);
}

// Usage example:
processFiles('./data', { creationDate: Date.now() - 30 * 24 * 60 * 60 * 1000, sizeThreshold: 1024 * 1024 });
