from flask import Flask, request, jsonify
import re
from functools import lru_cache
from threading import Lock
import logging

app = Flask(__name__)

# Configure logging
logging.basicConfig(level=logging.INFO)

# In-memory storage for supported languages and frameworks
languages_and_frameworks = {
    'python': ['django', 'flask'],
    'javascript': ['react', 'vue'],
    # Add more as needed
}

# Lock for thread-safe updates
lock = Lock()

@app.route('/submit-text', methods=['POST'])
def analyze_text():
    content_type = request.headers.get('Content-Type')
    text = extract_plain_text(request.data.decode(), content_type)

    try:
        results = extract_mentions(text)
        return jsonify(results), 200
    except Exception as e:
        logging.error(f"Error processing text: {e}")
        return jsonify({"error": "Failed to process the input."}), 500

def extract_plain_text(data, content_type):
    if 'html' in content_type.lower():
        # Strip HTML tags (simplified version)
        text = re.sub(r'<[^>]+>', '', data)
    elif 'markdown' in content_type.lower() or content_type == 'text/plain':
        # Simplified Markdown stripping
        text = re.sub(r'(\*\*|__)(.*?)\1', r'\2', data)  # Bold/italic
    else:
        text = data

    return text

@lru_cache(maxsize=128)
def extract_mentions(text):
    mentions = {}
    for language, frameworks in languages_and_frameworks.items():
        if re.search(rf"\b{language}\b", text, re.IGNORECASE):
            mentions[language] = []
            for framework in frameworks:
                if re.search(rf"\b{framework}\b", text, re.IGNORECASE):
                    mentions[language].append(framework)
    return mentions

@app.route('/admin/add', methods=['POST'])
def add_language_or_framework():
    new_data = request.json
    language = new_data.get('language').strip().lower()
    framework = new_data.get('framework').strip().lower()

    with lock:
        if not languages_and_frameworks.get(language):
            languages_and_frameworks[language] = []

        if framework and framework not in languages_and_frameworks[language]:
            languages_and_frameworks[language].append(framework)

    # Invalidate cache to reflect the new additions
    extract_mentions.cache_clear()

    return jsonify({"message": "Language/framework added successfully."}), 200

if __name__ == '__main__':
    app.run(debug=True)
