['```javascript
function generateFooter(scripts, options = {}) {
    const { className, id } = options;

    // Helper to create a unique identifier for each script based on type and charset
    const scriptKey = (script) => {
        return typeof script === 'string' 
            ? `code:${script}` 
            : `${script.type}:${script.charset || ''}`;
    };

    let includedScripts = new Set();

    // Template literal to build the footer HTML
    let footerHTML = `
        <footer
            ${className ? `class="${className}"` : ''}
            ${id ? `id="${id}"` : ''}
        >
    `;

    scripts.forEach(script => {
        const key = scriptKey(script);

        if (!includedScripts.has(key)) {
            includedScripts.add(key);

            let scriptTag;
            if (typeof script === 'string') {
                scriptTag = `<script>${script}</script>`;
            } else {
                scriptTag = `
                    <script
                        type="${script.type}"
                        ${script.charset ? `charset="${script.charset}"` : ''}
                        src="${script.src}"
                    ></script>
                `;
            }

            footerHTML += scriptTag;
        }
    });

    footerHTML += `</footer>`;

    return footerHTML;
}
