angular.module('dialogApp', [])
  .controller('DialogController', ['$scope', '$http', function($scope, $http) {
    $scope.dialogFields = [
      { name: 'field1' },
      { name: 'field2' },
      { name: 'field3' }
    ];

    // Main function to refresh dialog fields
    $scope.refreshDialogFields = function(resourceId, url, fieldNamesToRefresh) {
      fieldNamesToRefresh.forEach(function(fieldName) {
        const index = findFieldIndex($scope.dialogFields, fieldName);
        if (index !== -1) {
          refreshField(resourceId, url, fieldName)
            .then(response => {
              insertOrAppendResult($scope.dialogFields, index + 1, response.data);
            })
            .catch(error => console.error('Error refreshing field:', error));
        }
      });
    };

    // Helper function to find the first occurrence of a field name
    function findFieldIndex(fields, fieldName) {
      return fields.findIndex(field => field.name === fieldName);
    }

    // Function to refresh field data and send message to parent window
    function refreshField(resourceId, url, fieldName) {
      const fullUrl = `${url}/${resourceId}`;
      return $http.get(fullUrl).then(response => {
        window.parent.postMessage({ action: 'refresh', fieldName: fieldName }, '*');
        return response;
      });
    }

    // Helper function to insert or append result
    function insertOrAppendResult(fields, index, result) {
      if (index < fields.length) {
        fields.splice(index, 0, { name: result });
      } else {
        fields.push({ name: result });
      }
    }

    // Example usage
    $scope.refreshDialogFields('123', 'https://api.example.com/resource', ['field1', 'field3']);
  }]);
