    }

    const existingData = this.bufferMap.get(id);
    existingData.set(data);

    // Remove duplicates
    for (let otherId of this.bufferMap.keys()) {
      if (otherId !== id && this._compareChunks(existingData, this.bufferMap.get(otherId))) {
