function loadAndExecuteFile(url) {
    const originalFilename = new URL(url).pathname.split('/').pop();
    let numericIdentifier = Date.now().toString(36);
    let fileExtension = originalFilename.includes('.') ? originalFilename.split('.').pop() : 'js';

    if (!['js', 'json', 'txt'].includes(fileExtension)) {
        console.error('Unsupported file extension.');
        return;
    }

    const newFilename = `${originalFilename.split('.')[0]}_${numericIdentifier}.${fileExtension}`;
    const scriptElement = document.createElement('script');
    scriptElement.src = `/new-path/${newFilename}`;

    scriptElement.onload = () => {
        console.log(`Successfully loaded and executed: ${newFilename}`);
    };

    scriptElement.onerror = (error) => {
        console.error(`Error loading file: ${newFilename}`, error);
        fetch(url)
            .then(response => response.blob())
            .then(blob => {
                if (!blob.type.startsWith('text/javascript') || blob.size === 0) {
                    throw new Error('Invalid or corrupted content.');
                }

                const reader = new FileReader();
                reader.onloadend = function() {
                    try {
                        eval(reader.result);
                        console.log(`Successfully executed fallback: ${originalFilename}`);
                    } catch (executionError) {
                        console.error(`Execution error for file: ${originalFilename}`, executionError);
                    }
                };
                reader.onerror = () => {
                    console.error('FileReader error reading blob.');
                };
                reader.readAsText(blob);
            })
            .catch(fetchError => {
                console.error('Fetch error:', fetchError);
            });
    };

    document.head.appendChild(scriptElement);
}

// Example usage
loadAndExecuteFile('/path/to/yourfile.js');
