import org.yaml.snakeyaml.Yaml;

// ServiceInstance class representing each instance
class ServiceInstance implements Runnable {
    private final String id;
    private final ExecutorService executorService = Executors.newSingleThreadExecutor();

    public ServiceInstance(String id) {
        this.id = id;
    }

    @Override
    public void run() {
        try {
            // Simulate service work
            System.out.println("Service " + id + " started.");
            Thread.sleep(2000);  // Simulated processing time
            System.out.println("Service " + id + " completed.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            shutdownAndNotify(id);
        }
    }

    private void shutdownAndNotify(String id) {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        } finally {
            sendShutdownMessage(id);
        }
    }

    private void sendShutdownMessage(String id) {
        // Simulate sending a message to an external broker
        System.out.println("Sending shutdown message for service " + id);
        // Implement reliable async communication here
    }
}

// ServiceManager class handling dynamic scaling and scheduling
public class ServiceManager {

    private final BlockingQueue<ServiceInstance> activeServices = new LinkedBlockingQueue<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final int minInstances;
    private final int maxInstances;

    public ServiceManager(int minInstances, int maxInstances) {
        this.minInstances = minInstances;
        this.maxInstances = maxInstances;
    }

    public void start() {
        loadConfiguration();
        scheduleServiceScaling();
    }

    private void loadConfiguration() {
        // Load configuration from YAML
        Yaml yaml = new Yaml();
        try {
            Map<String, Object> config = yaml.load(Files.newBufferedReader(Paths.get("config.yaml")));
            minInstances = (int) config.getOrDefault("minInstances", 10);
            maxInstances = (int) config.getOrDefault("maxInstances", 200);
            // Load additional configuration as needed
        } catch (IOException e) {
            System.err.println("Error loading configuration: " + e.getMessage());
        }
    }

    private void scheduleServiceScaling() {
        scheduler.scheduleAtFixedRate(this::adjustServiceScale, 0, 5, TimeUnit.SECONDS);
    }

    private void adjustServiceScale() {
        int currentLoad = getCurrentSystemLoad();
        int targetInstances = Math.min(maxInstances, Math.max(minInstances, calculateTargetInstances(currentLoad)));

        while (activeServices.size() < targetInstances) {
            String id = UUID.randomUUID().toString();
            ServiceInstance instance = new ServiceInstance(id);
            activeServices.add(instance);
            Executors.newSingleThreadExecutor().execute(instance);
        }

        while (activeServices.size() > targetInstances) {
            ServiceInstance service = activeServices.poll();
            if (service != null) {
                service.run();  // Initiate shutdown
            }
        }
    }

    private int getCurrentSystemLoad() {
        // Simulate system load calculation
        return new Random().nextInt(100);
    }

    private int calculateTargetInstances(int currentLoad) {
        // Example policy: more instances for higher loads
        return minInstances + (currentLoad / 10);
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager(10, 200);
        manager.start();
    }
}
```

### Key Points:
- **ServiceInstance**: Represents a service that runs in its own thread. It includes logic for graceful shutdown and message sending.
- **ServiceManager**: Manages the lifecycle of `ServiceInstance` objects, scaling up or down based on load conditions.
- **Configuration**: Loads parameters from an external YAML file to adjust behavior dynamically.
- **Scheduling**: Uses a scheduled executor to periodically check and adjust the number of active services.

This code provides a foundational structure. You will need to expand it with actual messaging broker integration, robust error handling, and performance optimizations as per your requirements.']

