use Psr\Cache\CacheItemPoolInterface;
use Symfony\Component\Cache\Adapter\FilesystemAdapter;

require 'vendor/autoload.php';

class ConfigLoader {
    private $cache;

    public function __construct(CacheItemPoolInterface $cache) {
        $this->cache = $cache;
    }

    private function getEnvironment() {
        if (isset($_SERVER['HTTP_X_APP_ENV'])) {
            return $_SERVER['HTTP_X_APP_ENV'];
        }

        return 'production'; // default environment
    }

    private function loadConfigFile($env) {
        $configFilePath = __DIR__ . "/config/{$env}.php";
        if (file_exists($configFilePath)) {
            return require $configFilePath;
        } else {
            throw new Exception("Configuration file for {$env} not found.");
        }
    }

    private function fetchRemoteConfig() {
        // Placeholder logic to fetch remote configuration
        try {
            $response = file_get_contents('https://api.example.com/config');
            if ($response === FALSE) {
                throw new Exception("Failed to retrieve remote config");
            }
            return json_decode($response, true);
        } catch (Exception $e) {
            // Log the error or handle it as necessary
            return null;
        }
    }

    public function getConfig() {
        $env = $this->getEnvironment();

        $cacheKey = 'config_' . md5($env);

        $item = $this->cache->getItem($cacheKey);

        if (!$item->isHit()) {
            try {
                $config = $this->loadConfigFile($env);

                // Optionally merge with remote config
                $remoteConfig = $this->fetchRemoteConfig();
                if ($remoteConfig) {
                    $config = array_merge($config, $remoteConfig);
                }

                $item->set($config);
                $item->expiresAfter(3600); // Cache for 1 hour

            } catch (Exception $e) {
                // Handle error: e.g., revert to default config or fail gracefully
                return [];
            }

            $this->cache->save($item);
        }

        return $item->get();
    }
}

$loader = new ConfigLoader(new FilesystemAdapter());

$config = $loader->getConfig();

