<?php

function updateUsersProfile(PDO $pdo, array $usersData)
{
    try {
        // Start transaction to ensure atomicity
        $pdo->beginTransaction();

        foreach ($usersData as $userData) {
            $userId = $userData['id'];
            $newContactInfo = [
                'email' => $userData['email'],
                'phone' => $userData['phone']
            ];
            $lastLoginIP = $userData['last_login_ip'];
            $lastLoginTime = date('Y-m-d H:i:s');

            // Fetch current user data for logging purposes
            $stmt = $pdo->prepare("SELECT email, phone FROM users WHERE id = ?");
            $stmt->execute([$userId]);
            $currentUserData = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($currentUserData) {
                // Update user profile
                $updateStmt = $pdo->prepare(
                    "UPDATE users SET 
                        email = :email, 
                        phone = :phone, 
                        last_login_ip = :lastLoginIP,
                        last_login_time = :lastLoginTime 
                     WHERE id = :id"
                );
                $updateStmt->execute([
                    ':email' => $newContactInfo['email'],
                    ':phone' => $newContactInfo['phone'],
                    ':lastLoginIP' => $lastLoginIP,
                    ':lastLoginTime' => $lastLoginTime,
                    ':id' => $userId
                ]);

                // Log changes in audit trail table
                $auditStmt = $pdo->prepare(
                    "INSERT INTO audit_trail (user_id, old_email, new_email, old_phone, new_phone, changed_at) 
                     VALUES (:user_id, :old_email, :new_email, :old_phone, :new_phone, NOW())"
                );

                $auditStmt->execute([
                    ':user_id' => $userId,
                    ':old_email' => $currentUserData['email'],
                    ':new_email' => $newContactInfo['email'],
                    ':old_phone' => $currentUserData['phone'],
                    ':new_phone' => $newContactInfo['phone']
                ]);
            } else {
                throw new Exception("User not found with ID: $userId");
            }
        }

        // Commit transaction
        $pdo->commit();

    } catch (Exception $e) {
        // Rollback transaction in case of error
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }

        // Handle potential network latency and retry logic
        echo "Error: " . $e->getMessage() . ". Retrying...";
        sleep(1);
        updateUsersProfile($pdo, $usersData);  // Retry once
    }
}

function batchProcess(PDO $pdo, array $allUserData, int $batchSize = 100)
{
    $totalRecords = count($allUserData);

    for ($offset = 0; $offset < $totalRecords; $offset += $batchSize) {
        $batchData = array_slice($allUserData, $offset, $batchSize);
        updateUsersProfile($pdo, $batchData);
    }
}

// Example usage:
try {
    $dsn = 'mysql:host=localhost;dbname=testdb;charset=utf8mb4';
    $options = [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    ];

    $pdo = new PDO($dsn, 'username', 'password', $options);

    // Simulating user data
    $allUserData = [
        ['id' => 1, 'email' => 'new_email_1@example.com', 'phone' => '1234567890', 'last_login_ip' => '192.168.1.1'],
        // More user data...
    ];

    batchProcess($pdo, $allUserData);

} catch (PDOException $e) {
    echo "Database error: " . $e->getMessage();
}
