<?php

class DynamicContentGenerator {
    private $hashAlgorithms = [
        'bcrypt' => PASSWORD_BCRYPT,
        'argon2i' => PASSWORD_ARGON2I,
        'argon2id' => PASSWORD_ARGON2ID,
    ];

    /**
     * Generates a random string of the specified length using the given character set.
     *
     * @param int $length The desired length of the string.
     * @param string $charset The character set to use for generating the string.
     * @return string A randomly generated string.
     */
    public function generateRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        if ($length <= 0) {
            throw new InvalidArgumentException('Length must be greater than zero.');
        }

        $randomString = '';
        $maxIndex = mb_strlen($charset, '8bit') - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[random_int(0, $maxIndex)];
        }

        return $randomString;
    }

    /**
     * Hashes a given password using the specified algorithm and parameters.
     *
     * @param string $password The password to hash.
     * @param string $algorithm The hashing algorithm to use ('bcrypt', 'argon2i', 'argon2id').
     * @param int|null $cost The cost parameter for bcrypt (optional).
     * @return string|false The hashed password or false on failure.
     */
    public function hashPassword($password, $algorithm = 'bcrypt', $cost = null) {
        if (!isset($this->hashAlgorithms[$algorithm])) {
            throw new InvalidArgumentException('Unsupported hashing algorithm.');
        }

        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, $this->hashAlgorithms['bcrypt'], ['cost' => $cost ?: 10]);
            case 'argon2i':
            case 'argon2id':
                $options = [
                    'memory_cost' => $cost ?? PASSWORD_ARGON2_DEFAULT_MEMORY_COST,
                    'time_cost'   => $cost ?? PASSWORD_ARGON2_DEFAULT_TIME_COST,
                    'threads'     => $cost ?? PASSWORD_ARGON2_DEFAULT_THREADS
                ];
                return password_hash($password, $this->hashAlgorithms[$algorithm], $options);
        }
    }

    /**
     * Checks if a given hash matches the provided password.
     *
     * @param string $password The password to verify.
     * @param string $hash The hash to compare against.
     * @return bool True if the password matches the hash, false otherwise.
     */
    public function checkPassword($password, $hash) {
        return password_verify($password, $hash);
    }
}

