class ResourceLoader {
    constructor(directoryPath) {
        this.directoryPath = directoryPath;
    }

    /**
     * Loads a configuration file from the specified directory and returns its content as an object.
     *
     * @param {string} fileName The name of the configuration file to load (e.g., 'config.json').
     * @returns {Object|null} The parsed contents of the configuration file or null if an error occurs.
     */
    loadConfig(fileName) {
        const filePath = `${this.directoryPath}/${fileName}`;

        try {
            const fs = require('fs');

            // Check if the file exists
            if (!fs.existsSync(filePath)) {
                throw new Error(`File not found: ${filePath}`);
            }

            // Read and parse the JSON content of the file
            const fileContent = fs.readFileSync(filePath, 'utf-8');
            return JSON.parse(fileContent);
        } catch (error) {
            console.error('Error loading configuration:', error.message);
            return null;
        }
    }
}

module.exports = ResourceLoader;

```

**Notes:**
- The `DynamicContentGenerator` PHP class provides methods for generating random strings and hashing passwords with configurable algorithms.
- It includes error handling for unsupported hash algorithms and invalid string lengths.
- The `ResourceLoader` JavaScript class reads configuration files from a specified directory, gracefully handles errors such as missing files or parsing issues, and returns the parsed JSON object."]

