    const privateKeyName = 'privateKey';
    const certificateName = 'certificate';

    let isPaused = false;
    let bufferPool = [];

    async function fetchFromStorage(key) {
        try {
            return await storageServiceClient.retrieveSecureData(key);
        } catch (error) {
            console.error(`Error fetching ${key}:`, error);
            throw new Error(`Failed to retrieve data for key: ${key}`);
        }
    }

    async function authenticate() {
        try {
            await storageServiceClient.authenticate();
        } catch (error) {
            console.error('Authentication failed:', error);
            throw new Error('Failed to authenticate with secure storage service');
        }
    }

    async function fetchPrivateData() {
        const [privateKey, certificate] = await Promise.all([
            fetchFromStorage(privateKeyName),
            fetchFromStorage(certificateName)
        ]);

        return { privateKey, certificate };
    }

    async function processStreamChunk(chunk) {
        // Logic to handle the stream chunk
        console.log('Processing chunk:', chunk);
        // Example: append to buffer pool
        bufferPool.push(chunk);
        if (bufferPool.length >= BUFFER_SIZE / 2) {
            await flushBufferPool();
        }
    }

    async function flushBufferPool() {
        const dataToProcess = bufferPool.join('');
        console.log('Flushing buffer pool:', dataToProcess);

        // Process the combined data
        bufferPool = []; // Reset buffer pool after processing
    }

    (async () => {
        await authenticate();

        for await (const chunk of stream) {
            if (isPaused) continue;

            try {
                const { privateKey, certificate } = await fetchPrivateData();

                const pemCertificate = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;

                console.log('Generated PEM Certificate:', pemCertificate);

                await processStreamChunk(chunk);

            } catch (error) {
                console.error('Error processing stream:', error);
            }
        }

        if (bufferPool.length > 0) {
            await flushBufferPool();
        }
    })();

    return {
        pause: () => { isPaused = true; },
        resume: async () => { isPaused = false; }
    };
}
