#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <curl/curl.h>

#define CONFIG_SERVICE_URL "https://config-service.example.com"
#define DEFAULT_CONFIG_VALUE "default_value"

typedef struct {
    char *access_token;
} session_t;

typedef enum {
    SUCCESS = 0,
    DNS_ERROR,
    CONFIG_ERROR,
    AUTH_ERROR,
    UNKNOWN_ERROR
} error_code_t;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[*((size_t*)userp + 1)] += size * nmemb;
    memcpy(((char*)userp) + *((size_t*)userp), contents, size * nmemb);
    return size * nmemb;
}

error_code_t fetch_config(const char *url, char **config_value, size_t *value_len) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) {
        return CONFIG_ERROR;
    }

    *value_len = 0;
    *config_value = malloc(256); // Assume a maximum buffer size
    if (*config_value == NULL) {
        curl_easy_cleanup(curl);
        return CONFIG_ERROR;
    }

    char initial_buffer[1] = {0};
    *((size_t*)initial_buffer + 1) = sizeof(*config_value);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, initial_buffer);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        free(*config_value);
        *config_value = NULL;
        return CONFIG_ERROR;
    }

    strcpy(*config_value, initial_buffer);
    *value_len = strlen(*config_value);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    if (*value_len == 0) {
        free(*config_value);
        *config_value = strdup(DEFAULT_CONFIG_VALUE);
        return SUCCESS;
    }

    return SUCCESS;
}

error_code_t authenticate_user(const char *client_id, const char *client_secret, session_t *session) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) {
        return AUTH_ERROR;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");

    char auth_url[256];
    snprintf(auth_url, sizeof(auth_url), "https://oauth2.example.com/token?grant_type=client_credentials&client_id=%s&client_secret=%s", client_id, client_secret);

    curl_easy_setopt(curl, CURLOPT_URL, auth_url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    char response[256];
    size_t res_len = 0;
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return AUTH_ERROR;
    }

    // Extract access token from response
    char *token_start = strstr(response, "access_token\":\"");
    if (!token_start) {
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return AUTH_ERROR;
    }
    token_start += strlen("access_token\":\"");
    char *token_end = strchr(token_start, '\"');
    if (!token_end) {
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return AUTH_ERROR;
    }

    size_t token_len = token_end - token_start;
    session->access_token = malloc(token_len + 1);
    strncpy(session->access_token, token_start, token_len);
    session->access_token[token_len] = '\0';

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return SUCCESS;
}

error_code_t resolve_hostname(const char *hostname, u_char ip_buffer[16]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return DNS_ERROR;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), (char*)ip_buffer, INET_ADDRSTRLEN);
        break;
    }

    freeaddrinfo(res);

    if (p == NULL) {
        return DNS_ERROR;
    }

    return SUCCESS;
}

error_code_t main_function(const char *hostname) {
    u_char ip_buffer[16];
    session_t session = {0};
    char *config_value = NULL;
    size_t config_len = 0;

    // Fetch user-specific configuration
    if (fetch_config(CONFIG_SERVICE_URL, &config_value, &config_len) != SUCCESS) {
        return CONFIG_ERROR;
    }

    // Authenticate user via OAuth
    if (authenticate_user("client_id", "client_secret", &session) != SUCCESS) {
        free(config_value);
        return AUTH_ERROR;
    }

    // Resolve hostname to IP address
    error_code_t result = resolve_hostname(hostname, ip_buffer);

    free(config_value);
    free(session.access_token);

    return result;
}
