#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for sensor data points
typedef struct {
    double latitude;
    double longitude;
    time_t timestamp;
    float energy_consumption;
} SensorData;

// Define a structure to hold location-specific statistics
typedef struct {
    double latitude;
    double longitude;
    float max_energy_consumption;
    time_t max_energy_timestamp;
    float total_energy;
    int count;
    time_t first_entry_time;
    time_t last_entry_time;
} LocationStats;

#define SLIDING_WINDOW_SIZE 1000 // Size of sliding window
#define PROXIMITY_THRESHOLD 0.001 // Spatial proximity threshold (in degrees)
#define TIMESTAMP_RANGE 60 // Time range for aggregation in seconds

// Function to check spatial proximity between two locations
int is_proximate(double lat1, double lon1, double lat2, double lon2) {
    return fabs(lat1 - lat2) < PROXIMITY_THRESHOLD && fabs(lon1 - lon2) < PROXIMITY_THRESHOLD;
}

// Function to process sensor data stream
void process_sensor_data_stream(SensorData *data_points, int num_points,
                                LocationStats **result_location_stats, int *num_result_locations) {
    if (data_points == NULL || result_location_stats == NULL || num_result_locations == NULL)
        return;

    // Temporary storage for location statistics within the sliding window
    LocationStats temp_storage[SLIDING_WINDOW_SIZE];
    memset(temp_storage, 0, sizeof(temp_storage));
    int active_locations = 0;

    for (int i = 0; i < num_points; ++i) {
        SensorData current_data = data_points[i];

        // Initialize a new location if it doesn't exist in the sliding window
        int found_location = -1;
        for (int j = 0; j < active_locations; ++j) {
            if (is_proximate(temp_storage[j].latitude, temp_storage[j].longitude,
                             current_data.latitude, current_data.longitude)) {
                found_location = j;
                break;
            }
        }

        if (found_location == -1) { // New location
            if (active_locations < SLIDING_WINDOW_SIZE) {
                found_location = active_locations++;
            } else {
                // Remove oldest entry to make room for new one
                int min_index = 0;
                time_t earliest_time = temp_storage[0].last_entry_time;
                for (int j = 1; j < active_locations; ++j) {
                    if (temp_storage[j].last_entry_time < earliest_time) {
                        earliest_time = temp_storage[j].last_entry_time;
                        min_index = j;
                    }
                }
                found_location = min_index;
            }

            // Initialize new location statistics
            temp_storage[found_location].latitude = current_data.latitude;
            temp_storage[found_location].longitude = current_data.longitude;
            temp_storage[found_location].max_energy_consumption = current_data.energy_consumption;
            temp_storage[found_location].max_energy_timestamp = current_data.timestamp;
            temp_storage[found_location].first_entry_time = current_data.timestamp;
        }

        // Update statistics for the found location
        LocationStats *location_stats = &temp_storage[found_location];
        location_stats->total_energy += current_data.energy_consumption;
        ++location_stats->count;

        if (current_data.energy_consumption > location_stats->max_energy_consumption) {
            location_stats->max_energy_consumption = current_data.energy_consumption;
            location_stats->max_energy_timestamp = current_data.timestamp;
        }

        location_stats->last_entry_time = current_data.timestamp;

        // Remove locations outside of the time range
        for (int j = 0; j < active_locations; ++j) {
            if (difftime(location_stats[j].last_entry_time, location_stats[j].first_entry_time) > TIMESTAMP_RANGE) {
                memmove(&temp_storage[j], &temp_storage[j + 1], 
                        sizeof(LocationStats) * (active_locations - j - 1));
                --active_locations;
                --j; // Check the same index again after move
            }
        }
    }

    // Prepare result for locations within sliding window
    *num_result_locations = active_locations;
    *result_location_stats = malloc(sizeof(LocationStats) * active_locations);
    memcpy(*result_location_stats, temp_storage, sizeof(LocationStats) * active_locations);

    // Find the location with highest average energy consumption
    int max_avg_index = 0;
    float max_avg_energy = 0.0f;

    for (int i = 0; i < active_locations; ++i) {
        float avg_energy = temp_storage[i].total_energy / temp_storage[i].count;
        if (avg_energy > max_avg_energy) {
            max_avg_energy = avg_energy;
            max_avg_index = i;
        }
    }

    printf("Location with highest average energy consumption:\n");
    printf("Latitude: %.6f, Longitude: %.6f\n", 
           (*result_location_stats)[max_avg_index].latitude,
           (*result_location_stats)[max_avg_index].longitude);
    printf("Time range: %ld to %ld\n",
           (*result_location_stats)[max_avg_index].first_entry_time,
           (*result_location_stats)[max_avg_index].last_entry_time);
}

int main() {
    // Example usage
    int num_data_points = 100;
    SensorData *data_stream = malloc(sizeof(SensorData) * num_data_points);

    // Populate data_stream with sensor data (omitted for brevity)

    LocationStats *result_locations = NULL;
    int result_count = 0;

    process_sensor_data_stream(data_stream, num_data_points, &result_locations, &result_count);

    free(result_locations);
    free(data_stream);

    return 0;
}
```']

