    struct Character {
        int id;
        std::chrono::time_point<Clock> lastAttackTime;
    };

    std::vector<std::thread> workers;
    std::mutex cooldownMutex;
    std::map<int, Character> characters;
    std::queue<std::function<void()>> tasks;
    std::condition_variable cv;
    bool stop = false;

    // Atomic variables for concurrency control
    std::atomic<int> maxSimultaneousRequests{MAX_ATTACK_REQUESTS};
    std::atomic<int> currentRequestCount{0};

public:
    AttackManager(size_t numThreads) {
        for (size_t i = 0; i < numThreads; ++i)
            workers.emplace_back([this] { this->workerThread(); });
    }

    ~AttackManager() {
        stopWork();
        for (auto &worker : workers)
            if (worker.joinable())
                worker.join();
    }

    void scheduleAttack(int characterId) {
        auto task = [this, characterId]() { handleAttack(characterId); };
        {
            std::unique_lock<std::mutex> lock(cooldownMutex);
            tasks.push(task);

            cv.notify_one();
        }
    }

private:
    void workerThread() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(this->cooldownMutex);
                this->cv.wait(lock, [this] { return !this->tasks.empty() || this->stop; });

                if (this->stop && this->tasks.empty())
                    return;

                task = std::move(this->tasks.front());
                this->tasks.pop();
            }

            executeTask(task);
        }
    }

    void handleAttack(int characterId) {
        bool success = false;
        auto timeoutTime = Clock::now() + TIMEOUT_DURATION;

        while (currentRequestCount >= maxSimultaneousRequests && Clock::now() < timeoutTime) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }

        if (Clock::now() > timeoutTime) {
            log("Timeout reached for character " + std::to_string(characterId) + ". Fallback attack initiated.");
            performAttack(characterId, 2); // Fallback attack
            return;
        }

        currentRequestCount++;
        std::unique_lock<std::mutex> lock(cooldownMutex);

        if (canPerformAttack(characterId)) {
            int attack = selectRandomAttack();
            performAttack(characterId, attack);
            success = true;
        }
        currentRequestCount--;

        log("Character " + std::to_string(characterId) + " - Attack: " + std::to_string(success ? 1 : 2));
    }

    bool canPerformAttack(int characterId) {
        auto now = Clock::now();
        if (characters.find(characterId) == characters.end()) {
            characters[characterId] = {characterId, now};
            return true;
        }

        Character &ch = characters[characterId];
        if (now - ch.lastAttackTime >= COOLDOWN_PERIOD)
            ch.lastAttackTime = now;

        return now - ch.lastAttackTime >= COOLDOWN_PERIOD;
    }

    int selectRandomAttack() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 2);
        return dis(gen);
    }

    void performAttack(int characterId, int attack) {
        // Simulate external data fetching and integration
        log("Character " + std::to_string(characterId) + " executed Attack #" + std::to_string(attack));
    }

    void executeTask(std::function<void()> task) {
        try {
            task();
        } catch (...) {
            log("Error executing attack task");
        }
    }

    void stopWork() {
        {
            std::unique_lock<std::mutex> lock(cooldownMutex);
            stop = true;
        }
        cv.notify_all();
    }

    void log(const std::string &message) {
        // Optimized logging mechanism
        std::cout << message << std::endl; // Placeholder for actual logging system
    }

public:
    void updateMaxRequests(int newLimit) {
        maxSimultaneousRequests.store(newLimit);
    }
};

int main() {
    AttackManager manager(4);

    // Simulate concurrent attack requests
    for (int i = 0; i < 1000; ++i)
        manager.scheduleAttack(i % 100); // Reuse character ids for demonstration

    std::this_thread::sleep_for(std::chrono::seconds(10));
    return 0;
}
```

This code sets up a thread pool to handle attack requests concurrently, uses atomic operations and mutexes for safe concurrency management, and includes a fallback mechanism. It logs attacks and cooldown status, maintains performance by limiting concurrent requests, and is designed to be extensible for future expansions.']

