using UnityEngine;
using System.Globalization;

public class ValueGenerator
{
    private float minValue;
    private float maxValue;
    private readonly IDataSource dataSource;

    public ValueGenerator(float min, float max, IDataSource dataSource)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }

        minValue = min;
        maxValue = max;
        this.dataSource = dataSource;
    }

    public float GenerateValue(bool includeMax = false)
    {
        if (!includeMax && minValue == maxValue)
        {
            return minValue;
        }

        // Fetch any additional constraints from external data source
        var additionalConstraints = dataSource.GetAdditionalConstraints();

        // Handle potential latency in data source responses
        if (additionalConstraints == null || additionalConstraints.IsLatent)
        {
            // Implement a fallback mechanism to ensure timely value generation
            return UnityEngine.Random.Range(minValue, includeMax ? maxValue : maxValue - 0.0001f);
        }

        return UnityEngine.Random.Range(minValue, additionalConstraints.MaxValue);
    }

    public int GenerateDiscreteValue(bool includeMax = false)
    {
        if (!includeMax && minValue == maxValue)
        {
            return Mathf.RoundToInt(minValue);
        }

        var additionalConstraints = dataSource.GetAdditionalConstraints();

        if (additionalConstraints == null || additionalConstraints.IsLatent)
        {
            return UnityEngine.Random.Range(Mathf.FloorToInt(minValue), includeMax ? (int)maxValue : (int)maxValue - 1);
        }

        return UnityEngine.Random.Range(Mathf.FloorToInt(minValue), additionalConstraints.DiscreteMaxValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue})";
    }
}

// Example of an external data source interface
public interface IDataSource
{
    DataConstraints GetAdditionalConstraints();
}

// Example data constraints returned by the data source
public class DataConstraints
{
    public bool IsLatent { get; set; }
    public float MaxValue { get; set; }
    public int DiscreteMaxValue { get; set; }
}
