const async = require('async');
const { promisify } = require('util');

// Simulate fetching metadata from an external source
const fetchMetadataAsync = promisify((number, callback) => {
  setTimeout(() => {
    // Randomly simulate failures
    if (Math.random() < 0.1) {
      return callback(new Error('Failed to fetch metadata'));
    }
    callback(null, { meta: `metadata for ${number}` });
  }, Math.random() * 200); // Simulate variable latency
});

function customAsyncReduce(numbers, initialValue, callbackFn, config = {}) {
  const { maxConcurrency = 100 } = config;
  const resultsQueue = [];
  let currentIndex = 0;

  function processNextBatch(callback) {
    if (currentIndex >= numbers.length && resultsQueue.length === 0) {
      return callback(null);
    }

    async.mapLimit(
      Array.from({ length: Math.min(maxConcurrency, numbers.length - currentIndex) }, (_, i) => 
        currentIndex + i
      ),
      maxConcurrency,
      async (index, innerCallback) => {
        const number = numbers[index];

        // Retry logic for fetching metadata
        let attempt = 0;
        const fetchWithRetry = () =>
          new Promise((resolve, reject) => {
            fetchMetadataAsync(number)
              .then(resolve)
              .catch(error => {
                if (attempt < 3) {
                  attempt++;
                  return setTimeout(fetchWithRetry, 100); // Retry with delay
                }
                reject(error);
              });
          });

        try {
          const metadata = await fetchWithRetry();
          resultsQueue.push(metadata);
          innerCallback(null);
        } catch (error) {
          innerCallback(error);
        }
      },
      callback
    );

    currentIndex += maxConcurrency;
  }

  async function reduce(callback) {
    let accumulator = initialValue;

    while (currentIndex < numbers.length || resultsQueue.length > 0) {
      try {
        processNextBatch((err) => {
          if (err) return callback(err);

          // Perform the reduction operation
          const batchResults = resultsQueue.splice(0, maxConcurrency).map(res => res.meta);
          const nextValue = await promisify(callbackFn)(accumulator, batchResults);
          accumulator = nextValue;

        });
      } catch (error) {
        return callback(error);
      }
    }

    callback(null, accumulator);
  }

  reduce((err, result) => {
    if (err) {
      console.error('Reduction failed:', err.message);
    }
    return result;
  });
}

// Example usage
const numbers = Array.from({ length: 1000 }, (_, i) => i + 1);

customAsyncReduce(
  numbers,
  0, 
  async (acc, batch) => {
    // Dummy reduction logic; sum of metadata length for example purposes
    return acc + batch.reduce((sum, meta) => sum + meta.length, 0);
  },
  { maxConcurrency: 10 }
).then(result => console.log('Final result:', result));

// Unit tests (example)
const assert = require('assert');

(async () => {
  // Test with empty array
  const resultEmpty = await customAsyncReduce([], 0, async (acc, batch) => acc);
  assert.strictEqual(resultEmpty, 0);

  // Test with non-numeric values and validation logic
  const numbersWithNonNumeric = [1, '2', 3];
  let errorOccurred = false;
  try {
    await customAsyncReduce(
      numbersWithNonNumeric,
      0,
      async (acc, batch) => acc + batch.reduce((sum, meta) => sum + Number(meta), 0),
      { maxConcurrency: 10 }
    );
  } catch (err) {
    errorOccurred = true;
  }
  assert.strictEqual(errorOccurred, true);

  // Test with large data set
  const resultLargeSet = await customAsyncReduce(
    Array.from({ length: 10000 }, (_, i) => i + 1),
    0,
    async (acc, batch) => acc + batch.reduce((sum, meta) => sum + Number(meta), 0)
  );
  assert.strictEqual(resultLargeSet > 0, true);
})();
