#include <string.h>

typedef struct {
    // Define your context structure with necessary members.
    // For example:
    char* cache;
    void* networkClient;
} Context;

typedef int (*FilterCallback)(const char*, size_t);

typedef struct DOMNode {
    const char* tag;
    char** attributes; // null-terminated array of key-value pairs
    struct DOMNode** children;
    size_t numChildren;
} DOMNode;

static char* processAndLimitStringHelper(DOMNode* node, int sizeLimit, FilterCallback callback,
                                         Context* context, size_t* processedCount) {
    if (!node || !callback) return NULL;

    char* result = NULL;
    size_t totalLength = 0;

    // Base case: leaf node
    if (node->numChildren == 0) {
        int valid = callback(node->tag, strlen(node->tag));
        if (valid) {
            *processedCount += 1;
            totalLength += strlen(node->tag);

            size_t neededSize = totalLength + 1; // for null terminator
            char* tempResult = realloc(result, neededSize);
            if (!tempResult) return NULL;

            result = tempResult;
            strcat(result, node->tag);
        }
    } else {
        // Recursively process each child
        *processedCount = 0;
        for (size_t i = 0; i < node->numChildren; ++i) {
            char* childResult = processAndLimitStringHelper(node->children[i], sizeLimit, callback,
                                                             context, processedCount);
            if (!childResult) return NULL;

            size_t childLength = strlen(childResult);
            totalLength += childLength;

            // Check size limit
            if (totalLength + 1 > sizeLimit) {
                free(result);
                free(childResult);
                return NULL;
            }

            char* tempResult = realloc(result, totalLength + 1); // for null terminator
            if (!tempResult) return NULL;

            result = tempResult;
            strcat(result, childResult);

            free(childResult);
        }
    }

    // Append processed count to the string if within size limit
    if (totalLength < sizeLimit - 2) { // account for "-x" and null terminator
        int lenWithCount = snprintf(NULL, 0, "%s-%zu", result, *processedCount);
        char* finalResult = realloc(result, totalLength + lenWithCount + 1); // +1 for '\0'
        if (!finalResult) return NULL;

        snprintf(finalResult, totalLength + lenWithCount + 1, "%s-%zu", result, *processedCount);

        result = finalResult;
    }

    return result;
}

char* processAndLimitString(DOMNode* root, int sizeLimit, FilterCallback callback, Context* context) {
    if (!root || !callback) return NULL;

    size_t processedCount = 0;
    char* result = processAndLimitStringHelper(root, sizeLimit, callback, context, &processedCount);

    if (strlen(result) > sizeLimit) {
        free(result);
        return NULL;
    }

    return result;
}
