#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    uint16_t extra_samples;
} ImageInfo;

typedef struct {
    ImageInfo image_info;
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    int error_code; // 0 for success, non-zero for errors
    char error_message[256];
} TIFFResult;

TIFFResult process_tiff(const char *filename) {
    TIFFResult result = {0};
    FILE *file = fopen(filename, "rb");
    if (!file) {
        snprintf(result.error_message, sizeof(result.error_message), "Failed to open file: %s", filename);
        result.error_code = 1;
        return result;
    }

    uint8_t *buffer = NULL;
    long filesize = 0;

    // Get the file size
    fseek(file, 0, SEEK_END);
    filesize = ftell(file);
    fseek(file, 0, SEEK_SET);

    buffer = (uint8_t *)malloc(filesize);
    if (!buffer) {
        snprintf(result.error_message, sizeof(result.error_message), "Memory allocation failed");
        result.error_code = 2;
        fclose(file);
        return result;
    }

    // Read the entire file
    size_t read_size = fread(buffer, 1, filesize, file);
    if (read_size != filesize) {
        snprintf(result.error_message, sizeof(result.error_message), "Failed to read complete file");
        result.error_code = 3;
        free(buffer);
        fclose(file);
        return result;
    }
    fclose(file);

    // Create TIFF object
    TIFF *tiff = TIFFClientOpen("file", filename, NULL, NULL, 0);
    if (!tiff) {
        snprintf(result.error_message, sizeof(result.error_message), "Failed to open TIFF file");
        result.error_code = 4;
        free(buffer);
        return result;
    }

    // Extract image info
    uint16_t bitsPerSample, samplesPerPixel, extraSamples;
    TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetFieldDefaulted(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetFieldDefaulted(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples);

    result.image_info.bits_per_sample = bitsPerSample;
    result.image_info.samples_per_pixel = samplesPerPixel;
    result.image_info.extra_samples = extraSamples;

    // Compute MD5 hash
    MD5((unsigned char *)buffer, filesize, result.md5_hash);

    TIFFClose(tiff);
    free(buffer);

    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <tiff_filename>\n", argv[0]);
        return 1;
    }

    TIFFResult result = process_tiff(argv[1]);

    if (result.error_code == 0) {
        printf("Bits per Sample: %d\n", result.image_info.bits_per_sample);
        printf("Samples per Pixel: %d\n", result.image_info.samples_per_pixel);
        printf("Extra Samples: %d\n", result.image_info.extra_samples);

        printf("MD5 Hash: ");
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            printf("%02x", result.md5_hash[i]);
        }
        printf("\n");
    } else {
        fprintf(stderr, "Error (%d): %s\n", result.error_code, result.error_message);
    }

    return 0;
}
```

### Explanation:

- **TIFF and OpenSSL Libraries**: The code uses the `libtiff` library for TIFF file handling and `OpenSSL` for MD5 hashing.
- **ImageInfo Struct**: Holds bits per sample, samples per pixel, and extra samples.
- **TIFFResult Struct**: Contains image info, MD5 hash, error code, and message.
- **Error Handling**: Checks for file open/read errors, memory allocation failures, and TIFF parsing issues.
- **MD5 Hashing**: Computes the hash of the entire file content.
- **Resource Management**: Ensures files and allocated memory are properly closed/freed.

### Dependencies:

- Ensure `libtiff` and `OpenSSL` are installed in your environment.
- Compile with `-ltiff -lssl -lcrypto`.

This code is designed to be integrated into a larger system, considering efficient resource use and error handling.']

