// Function to serialize the object back using JNI
int serialize(JNIEnv *env, jobject objectOutputStream, jobject obj, unsigned char **byteArray, size_t *length) {
    // Serialize the object
    jclass classStream = (*env)->GetObjectClass(env, objectOutputStream);
    jmethodID midWriteObject = (*env)->GetMethodID(env, classStream, "writeObject", "(Ljava/io/ObjectOutputStream;Ljava/lang/Object;)V");
    if (midWriteObject == NULL) return 1;

    if ((*env)->CallVoidMethodA(env, objectOutputStream, midWriteObject, &obj) != JNI_OK) {
        return 1;
    }

    // Retrieve the serialized byte array
    jmethodID midToByteArray = (*env)->GetMethodID(env, classStream, "toByteArray", "()[B");
    if (midToByteArray == NULL) return 1;

    jbyteArray javaByteArray = (jbyteArray)(*env)->CallObjectMethodA(env, objectOutputStream, midToByteArray);
    *length = (*env)->GetArrayLength(env, javaByteArray);

    *byteArray = malloc(*length);
    if (*byteArray == NULL) return 1;

    (*env)->GetByteArrayRegion(env, javaByteArray, 0, *length, (jbyte *)*byteArray);

    // Clean up
    (*env)->DeleteLocalRef(env, javaByteArray);

    return 0;
}

