#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <errno.h>

#define MAX_COMMANDS 10000

typedef struct {
    char **command;
    char **env_vars;
    char *stdin_file;
    char *stdout_file;
    char *stderr_file;
} Command;

void handle_sigchld(int sig) {
    int saved_errno = errno;
    while (waitpid((pid_t)(-1), 0, WNOHANG) > 0);
    errno = saved_errno;
}

int execute_commands(Command commands[], size_t num_commands) {
    if (signal(SIGCHLD, handle_sigchld) == SIG_ERR) {
        perror("Error setting signal handler");
        return 0;
    }

    pid_t pgrp = getpid();

    for (size_t i = 0; i < num_commands; ++i) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("Fork failed");
            return 0;
        } else if (pid == 0) { // Child process
            if (setpgid(0, pgrp) == -1) {
                perror("Failed to set process group ID");
                exit(EXIT_FAILURE);
            }

            if (commands[i].stdin_file != NULL) {
                freopen(commands[i].stdin_file, "r", stdin);
            }
            if (commands[i].stdout_file != NULL) {
                freopen(commands[i].stdout_file, "w", stdout);
            }
            if (commands[i].stderr_file != NULL) {
                freopen(commands[i].stderr_file, "w", stderr);
            }

            execvpe(commands[i].command[0], commands[i].command, commands[i].env_vars);
            perror("Exec failed");
            exit(EXIT_FAILURE);
        } else { // Parent process
            setpgid(pid, pgrp);
        }
    }

    int status = 1;
    for (size_t i = 0; i < num_commands; ++i) {
        if (waitpid(-pgrp, &status, WUNTRACED | WCONTINUED) == -1) {
            perror("Wait failed");
            return 0;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            status = 0;
        }
    }

    return status;
}

int main() {
    Command commands[MAX_COMMANDS] = {
        // Initialize with your commands
        // Example:
        // { .command = (char*[]){"ls", "-l", NULL}, .env_vars = (char*[]){"PATH=/usr/bin", NULL}, .stdin_file = NULL, .stdout_file = "output.txt", .stderr_file = "error.log" }
    };

    size_t num_commands = 0; // Set this to the actual number of commands

