public class SiteManager
{
    private const int MaxRetries = 3;
    private readonly TimeSpan InitialDelay = TimeSpan.FromSeconds(1);

    public async Task<Process> AddAndStartSiteAsync(string directoryPath, string siteName, SiteConfiguration config)
    {
        try
        {
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                Logger.LogError($"Web.config not found in {directoryPath}");
                return null;
            }

            if (!HasSufficientPermissions(directoryPath))
            {
                Logger.LogError($"Insufficient permissions for {directoryPath}");
                return null;
            }

            return await TryStartProcessWithRetriesAsync(directoryPath, siteName, config);
        }
        catch (Exception ex)
        {
            Logger.LogError($"An unexpected error occurred: {ex.Message}");
            return null;
        }
    }

    private bool HasSufficientPermissions(string path)
    {
        try
        {
            // Check for read/write/execute permissions.
            var accessControl = new FileIOPermission(FileIOPermissionAccess.Write | 
                                                     FileIOPermissionAccess.Read |
                                                     FileIOPermissionAccess.PathDiscovery, path);
            accessControl.Demand();
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }

    private async Task<Process> TryStartProcessWithRetriesAsync(string directoryPath, string siteName, SiteConfiguration config)
    {
        int attempt = 0;
        TimeSpan delay = InitialDelay;

        while (attempt < MaxRetries)
        {
            try
            {
                var process = new Process
                {
                    StartInfo = new ProcessStartInfo
                    {
                        FileName = "YourCommand.exe", // Replace with actual command to start the site.
                        Arguments = $"{directoryPath} {siteName}", // Adjust arguments as needed.
                        WorkingDirectory = directoryPath,
                        UseShellExecute = false,
                        RedirectStandardOutput = true,
                        CreateNoWindow = true
                    }
                };

                process.Start();
                Logger.LogInfo($"Started site '{siteName}' at attempt {attempt + 1}");
                return process;
            }
            catch (Exception ex)
            {
                Logger.LogError($"Failed to start the site on attempt {attempt + 1}: {ex.Message}");

                if (++attempt < MaxRetries)
                {
                    await Task.Delay(delay);
                    delay *= 2; // Exponential backoff
                }
            }
        }

        Logger.LogError("Exceeded maximum retries. Site could not be started.");
        return null;
    }
}
