#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h> // JSON library
#include <errno.h>
#include <unistd.h>

// Supported log levels
const char *supported_log_levels[] = {"DEBUG", "INFO", "WARN", "ERROR"};

// Configuration cache
typedef struct {
    int server_port;
    int max_concurrent_requests;
    int timeout;
    char ssl_cert_path[256];
    const char *log_level;
} ConfigCache;

ConfigCache config_cache;

// Function to check if a string is a valid log level
int is_valid_log_level(const char *level) {
    for (size_t i = 0; i < sizeof(supported_log_levels) / sizeof(supported_log_levels[0]); ++i) {
        if (strcmp(level, supported_log_levels[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to validate the configuration
int validate_config(json_t *json_obj, ConfigCache *cache) {
    json_error_t error;

    // Validate server_port
    json_t *server_port_json = json_object_get(json_obj, "server_port");
    if (!json_is_integer(server_port_json)) {
        fprintf(stderr, "Error: server_port must be a positive integer.\n");
        return 0;
    }
    int server_port = json_integer_value(server_port_json);
    if (server_port <= 0) {
        fprintf(stderr, "Error: server_port must be greater than zero.\n");
        return 0;
    }

    // Validate max_concurrent_requests
    json_t *max_reqs_json = json_object_get(json_obj, "max_concurrent_requests");
    if (!json_is_integer(max_reqs_json)) {
        fprintf(stderr, "Error: max_concurrent_requests must be a non-negative integer.\n");
        return 0;
    }
    int max_concurrent_requests = json_integer_value(max_reqs_json);
    if (max_concurrent_requests < 0) {
        fprintf(stderr, "Error: max_concurrent_requests cannot be negative.\n");
        return 0;
    }

    // Validate timeout
    json_t *timeout_json = json_object_get(json_obj, "timeout");
    if (!json_is_integer(timeout_json)) {
        fprintf(stderr, "Error: timeout must be a positive integer.\n");
        return 0;
    }
    int timeout = json_integer_value(timeout_json);
    if (timeout <= 0) {
        fprintf(stderr, "Error: timeout must be greater than zero.\n");
        return 0;
    }

    // Validate ssl_cert_path
    json_t *ssl_cert_json = json_object_get(json_obj, "ssl_cert_path");
    if (!json_is_string(ssl_cert_json)) {
        fprintf(stderr, "Error: ssl_cert_path must be a valid string path.\n");
        return 0;
    }
    strncpy(cache->ssl_cert_path, json_string_value(ssl_cert_json), sizeof(cache->ssl_cert_path) - 1);
    if (access(cache->ssl_cert_path, F_OK) != 0) {
        fprintf(stderr, "Error: ssl_cert_path does not point to a valid file.\n");
        return 0;
    }

    // Validate log_level
    json_t *log_level_json = json_object_get(json_obj, "log_level");
    if (!json_is_string(log_level_json)) {
        fprintf(stderr, "Error: log_level must be a valid string.\n");
        return 0;
    }
    const char *log_level = json_string_value(log_level_json);
    if (!is_valid_log_level(log_level)) {
        fprintf(stderr, "Error: log_level is not supported. Supported levels are DEBUG, INFO, WARN, ERROR.\n");
        return 0;
    }

    // Cache the configuration
    cache->server_port = server_port;
    cache->max_concurrent_requests = max_concurrent_requests;
    cache->timeout = timeout;
    cache->log_level = log_level;

    return 1;
}

// Function to load and validate configuration from a file
int load_and_validate_config(const char *file_path) {
    json_error_t error;
    json_t *json_obj = json_load_file(file_path, 0, &error);
    if (!json_obj) {
        fprintf(stderr, "Error parsing JSON config: %s\n", error.text);
        return 0;
    }

    int valid = validate_config(json_obj, &config_cache);

    json_decref(json_obj);
    return valid;
}

// Example usage
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *config_file = argv[1];
    if (!load_and_validate_config(config_file)) {
        return EXIT_FAILURE;
    }

    printf("Configuration loaded successfully:\n");
    printf("Server Port: %d\n", config_cache.server_port);
    printf("Max Concurrent Requests: %d\n", config_cache.max_concurrent_requests);
    printf("Timeout: %d\n", config_cache.timeout);
    printf("SSL Certificate Path: %s\n", config_cache.ssl_cert_path);
    printf("Log Level: %s\n", config_cache.log_level);

    return EXIT_SUCCESS;
}
