    private async Task SendMessageToQueueAsync(byte[] data, string queueConnectionString)
    {
        try
        {
            using (var buffer = BufferPool.Shared.Rent(data.Length))
            {
                Array.Copy(data, buffer.Memory.Span);
                // Simulate sending message to a queue with retry logic and error handling
                await Task.Delay(100); // Simulated delay for network operations
                _logger.LogInformation("Message sent to queue.");
                BufferPool.Shared.Return(buffer);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to send message to queue.");
            throw;
        }
    }

    private async Task SaveToFileStorageServiceAsync(byte[] data, string fileServiceUrl)
    {
        try
        {
            using (var buffer = BufferPool.Shared.Rent(data.Length))
            {
                Array.Copy(data, buffer.Memory.Span);
                // Simulate saving to a file storage service with retry logic and error handling
                await Task.Delay(100); // Simulated delay for network operations
                _logger.LogInformation("Data saved to file storage.");
                BufferPool.Shared.Return(buffer);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to save data to file storage.");
            throw;
        }
    }

    private async Task StoreInDatabaseAsync(byte[] data, string dbConnectionString)
    {
        try
        {
            using (var buffer = BufferPool.Shared.Rent(data.Length))
            {
                Array.Copy(data, buffer.Memory.Span);
                // Simulate storing in a database with retry logic and error handling
                await Task.Delay(100); // Simulated delay for network operations
                _logger.LogInformation("Data stored in database.");
                BufferPool.Shared.Return(buffer);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to store data in the database.");
            throw;
        }
    }
}

public static class BufferPool
{
    private static readonly ArrayPool<byte> Shared = ArrayPool<byte>.Shared;

    public static MemoryHandle Rent(int minimumLength) => Shared.Rent(minimumLength);

    public static void Return(MemoryHandle buffer, bool clearArray = false)
    {
        var arraySegment = (ArraySegment<byte>)buffer;
        Shared.Return(arraySegment.Array!, arraySegment.Offset, clearArray);
    }
}
