using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DecryptionService
{
    private static readonly string LogFilePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "decryption_log.txt");

    public async Task<string> DecryptMessageAsync(string base64EncodedInput, int keyLength)
    {
        try
        {
            if (!IsValidBase64(base64EncodedInput))
                throw new ArgumentException("Invalid Base64 input.");

            var (encryptedData, key, iv) = ParseInput(base64EncodedInput);

            string decryptedMessage;
            using (var algorithm = CreateAesAlgorithm(keyLength, key, iv))
            {
                decryptedMessage = Decrypt(encryptedData, algorithm);
            }

            await LogDecryptionAttemptAsync(true, null);
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            await LogDecryptionAttemptAsync(false, ex.Message);
            throw new InvalidOperationException("Decryption failed.", ex);
        }
    }

    private bool IsValidBase64(string base64EncodedInput)
    {
        Span<byte> buffer = new Span<byte>(new byte[base64EncodedInput.Length]);
        return Convert.TryFromBase64String(base64EncodedInput, buffer, out _, leaveOpen: false);
    }

    private (byte[], byte[], byte[]) ParseInput(string base64EncodedInput)
    {
        var parts = base64EncodedInput.Split(',');
        if (parts.Length != 3) throw new ArgumentException("Invalid input format.");

        return (
            Convert.FromBase64String(parts[0]),
            Convert.FromBase64String(parts[1]),
            Convert.FromBase64String(parts[2])
        );
    }

    private SymmetricAlgorithm CreateAesAlgorithm(int keyLength, byte[] key, byte[] iv)
    {
        if (key.Length != 7 && key.Length != 14) throw new ArgumentException("Invalid key length.");

        var aes = Aes.Create();
        aes.KeySize = keyLength * 8;
        aes.Key = key;
        aes.IV = iv;

        return aes;
    }

    private string Decrypt(byte[] encryptedData, SymmetricAlgorithm algorithm)
    {
        using (var ms = new MemoryStream(encryptedData))
        using (var cs = new CryptoStream(ms, algorithm.CreateDecryptor(), CryptoStreamMode.Read))
        using (var sr = new StreamReader(cs))
        {
            return sr.ReadToEnd();
        }
    }

    private async Task LogDecryptionAttemptAsync(bool success, string errorMessage)
    {
        var logMessage = $"{DateTime.UtcNow}: Success={success}, Error={errorMessage ?? "None"}";

        await File.AppendAllTextAsync(LogFilePath, logMessage + Environment.NewLine);
    }
}

