using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly PaddingMode _paddingScheme;

    public AesCbcDecryptor(byte[] key, byte[] iv, PaddingMode paddingScheme)
    {
        if (key == null || key.Length != 16 && key.Length != 24 && key.Length != 32)
            throw new ArgumentException("Key must be 128, 192, or 256 bits.");

        if (iv == null || iv.Length != 16)
            throw new ArgumentException("IV must be 128 bits.");

        _key = key;
        _iv = iv;
        _paddingScheme = paddingScheme;
    }

    public async Task<byte[]> DecryptAsync(Stream cipherStream, Stream plainStream, int bufferSize = 4096)
    {
        if (cipherStream == null || plainStream == null)
            throw new ArgumentNullException("Cipher and plain streams cannot be null.");

        using var aes = Aes.Create();
        aes.Key = _key;
        aes.IV = _iv;
        aes.Mode = CipherMode.CBC;
        aes.Padding = _paddingScheme;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var cryptoStream = new CryptoStream(plainStream, decryptor, CryptoStreamMode.Write);

        byte[] buffer = new byte[bufferSize];
        int bytesRead;

        try
        {
            while ((bytesRead = await cipherStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                await cryptoStream.WriteAsync(buffer, 0, bytesRead);
            }
        }
        catch (CryptographicException ex)
        {
            LogError($"Decryption failed: {ex.Message}");
            throw new InvalidOperationException("The provided data could not be decrypted.", ex);
        }

        return plainStream.ToArray();
    }

    public byte[] Decrypt(Stream cipherStream, Stream plainStream, int bufferSize = 4096)
    {
        if (cipherStream == null || plainStream == null)
            throw new ArgumentNullException("Cipher and plain streams cannot be null.");

        using var aes = Aes.Create();
        aes.Key = _key;
        aes.IV = _iv;
        aes.Mode = CipherMode.CBC;
        aes.Padding = _paddingScheme;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var cryptoStream = new CryptoStream(plainStream, decryptor, CryptoStreamMode.Write);

        byte[] buffer = new byte[bufferSize];
        int bytesRead;

        try
        {
            while ((bytesRead = cipherStream.Read(buffer, 0, buffer.Length)) > 0)
            {
                cryptoStream.Write(buffer, 0, bytesRead);
            }
        }
        catch (CryptographicException ex)
        {
            LogError($"Decryption failed: {ex.Message}");
            throw new InvalidOperationException("The provided data could not be decrypted.", ex);
        }

        return plainStream.ToArray();
    }

    private void LogError(string message)
    {
        // Implement logging mechanism, e.g., write to a file or use a logging framework
        Console.Error.WriteLine($"{DateTime.UtcNow}: {message}");
    }
}
