        : resolver_(ioc), socket_(ioc), stream_(std::make_shared<http::response_parser<http::dynamic_body>>()) {}

    void connect() {
        asio::async_connect(socket_, endpoints_,
            [self = shared_from_this()](auto ec, auto) {
                if (!ec) self->do_request();
            });
    }

private:
