        : graph_db_(db), interface_table_(interfaceTable) {}

    void manageGraph() {
        boost::uuids::random_generator generator;
        std::string vertex_id = boost::uuids::to_string(generator());
        std::map<std::string, std::string> properties{{"property", "value"}};
        graph_db_.addVertex(vertex_id, properties);

        // Add edges and other management logic here
    }

private:
    GraphDatabase& graph_db_;
    InterfaceTableTestDouble* interface_table_;
};

int main() {
    try {
        asio::io_context ioc;
        tcp::resolver resolver(ioc);
        auto endpoints = resolver.resolve("example.com", "http");

        HttpClient client(ioc, endpoints);
