use anyhow::{Context, Result};
use serde::Deserialize;
use std::env;
use tokio::time::{sleep, Duration};

#[derive(Deserialize)]
struct ApiResponse {
    // Define response structure based on the actual API
}

async fn fetch_data(api_endpoint: &str) -> Result<ApiResponse> {
    let client = reqwest::Client::new();
    let mut retries = 0;
    const MAX_RETRIES: u8 = 5;

    loop {
        match client.get(api_endpoint).send().await {
            Ok(response) => {
                if response.status().is_success() {
                    return response.json::<ApiResponse>().await.context("Failed to parse JSON");
                }
            }
            Err(e) => {
                eprintln!("Error fetching data: {:?}", e);
            }
        }

        retries += 1;
        if retries > MAX_RETRIES {
            break;
        }

        let delay = Duration::from_secs(2u64.pow(retries as u32));
        sleep(delay).await;
    }

    Err(anyhow::anyhow!("Failed to fetch data after {} attempts", MAX_RETRIES))
}

async fn process_argument(api_endpoint: &str) -> Result<()> {
    match fetch_data(api_endpoint).await {
        Ok(response) => {
            // Process response
            println!("Successfully processed: {:?}", response);
        }
        Err(err) => {
            eprintln!("Failed to process {}: {}", api_endpoint, err);
        }
    }
    Ok(())
}

async fn main_task(args: Vec<String>) -> Result<()> {
    let mut handles = vec![];

    for arg in args.iter().skip(1) { // Skip the first argument (program name)
        let handle = tokio::spawn(async move {
            if let Err(err) = process_argument(arg).await {
                eprintln!("Task failed with error: {:?}", err);
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.await??;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: {} <API_ENDPOINT_1> [API_ENDPOINT_2] ...", args[0]);
        return Ok(());
    }

    // Log configuration setup for different environments
    let log_level = match std::env::var("LOG_LEVEL").unwrap_or_else(|_| "info".to_string()) {
        "debug" => tracing_subscriber::filter::LevelFilter::DEBUG,
        _ => tracing_subscriber::filter::LevelFilter::INFO,
    };

    tracing_subscriber::fmt()
        .with_max_level(log_level)
        .init();

    main_task(args).await
}
```

