#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pcu_list(int num) {
    if (num <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL; // Allocation failed

    for (int i = 0; i < num; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        list[i].RNTI = rand() % 5000;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    }

    return list;
}

