    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListElement {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListElement* next;
} ListElement;

typedef struct DynamicList {
    ListElement* head;
    pthread_rwlock_t rwlock;
} DynamicList;

// Error logging function
void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        log_error("Memory allocation failed for DynamicList.");
        return NULL;
    }
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->rwlock);

    ListElement *current = list->head;
    while (current) {
        ListElement* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    ListElement* new_elem = (ListElement*)malloc(sizeof(ListElement));
    if (!new_elem) {
        log_error("Memory allocation failed for ListElement.");
        return -2;
    }

    memcpy(&new_elem->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_elem->next = NULL;

    pthread_rwlock_wrlock(&list->rwlock);
    new_elem->next = list->head;
    list->head = new_elem;
    pthread_rwlock_unlock(&list->rwlock);

    return 0;
}

int remove_element(DynamicList* list, unsigned int rnti) {
    if (!list) return -1;

    pthread_rwlock_wrlock(&list->rwlock);

    ListElement *current = list->head, *prev = NULL;
    while (current && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->rwlock);
        return -2; // Element not found
    }

    if (prev == NULL) { // Head element
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

// Placeholder for performance monitoring logic
