void resize_crypto_library(CryptoLibrary *lib) {
    size_t new_capacity = lib->capacity * GROWTH_FACTOR;
    CryptoRecord *new_records = (CryptoRecord *)realloc(lib->records, sizeof(CryptoRecord) * new_capacity);
    if (!new_records) {
