        perror("Failed to allocate memory for CRCList");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Destroy a CRCList
void destroy_list(CRCList** list) {
    if (list && *list) {
        Node* current = (*list)->head;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&(*list)->mutex);
        free(*list);
        *list = NULL;
    }
}

// Add a PDU to the list
int add_pdu_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for Node");
        return -1;
    }

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Remove a PDU from the list by RX_UE_INFORMATION_TAG
void remove_pdu_from_list(CRCList* list, int RX_UE_INFORMATION_TAG) {
    if (!list) return;

    Node *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->mutex);
    while (current && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (prev) {
            prev->next = current->next;
        } else {
            list->head = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->mutex);
}
