#include <iostream>
#include <memory>
#include <vector>
#include <random>
#include <openssl/evp.h>
#include <mutex>

// Error handling class for OpenSSL errors
class CryptoError : public std::exception {
public:
    explicit CryptoError(const char* message) : msg_(message) {}

    const char* what() const noexcept override {
        return msg_;
    }

private:
    const char* msg_;
};

// Utility function to handle OpenSSL errors
void HandleOpenSSLErrors() {
    unsigned long err_code;
    while ((err_code = ERR_get_error()) != 0) {
        std::cerr << "OpenSSL error: " << ERR_error_string(err_code, nullptr) << '\n';
    }
}

// Base class for cryptographic operations
class CryptographicOperation {
public:
    virtual ~CryptographicOperation() = default;
    virtual void Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) = 0;
    virtual void Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) = 0;

protected:
    EVP_CIPHER_CTX* ctx_;

    CryptographicOperation() {
        ctx_ = EVP_CIPHER_CTX_new();
        if (!ctx_) throw CryptoError("Failed to create OpenSSL cipher context.");
    }

    virtual ~CryptographicOperation() {
        EVP_CIPHER_CTX_free(ctx_);
    }
};

// Concrete class for ECB mode
class EcbMode : public CryptographicOperation {
public:
    explicit EcbMode(const std::string& key) {
        if (!EVP_EncryptInit_ex(ctx_, EVP_aes_256_ecb(), nullptr, reinterpret_cast<const uint8_t*>(key.data()), nullptr)) {
            throw CryptoError("Failed to initialize ECB cipher.");
        }
    }

    void Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override;
    void Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override;

private:
    const EVP_CIPHER* cipher_ = EVP_aes_256_ecb();
};

void EcbMode::Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) {
    if (!EVP_EncryptUpdate(ctx_, nullptr, nullptr, nullptr, 0)) throw CryptoError("Failed to encrypt.");
    output.resize(input.size() + EVP_CIPHER_block_size(cipher_));
    int out_len;
    if (!EVP_EncryptUpdate(ctx_, output.data(), &out_len, input.data(), input.size())) {
        throw CryptoError("Encryption failed in ECB mode.");
    }
    output.resize(out_len);
}

void EcbMode::Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) {
    if (!EVP_DecryptInit_ex(ctx_, cipher_, nullptr, nullptr, nullptr)) throw CryptoError("Failed to decrypt.");
    output.resize(input.size());
    int out_len;
    if (!EVP_DecryptUpdate(ctx_, output.data(), &out_len, input.data(), input.size())) {
        throw CryptoError("Decryption failed in ECB mode.");
    }
    output.resize(out_len);
}

// Concrete class for EDE3 mode (using Triple DES)
class Edede3Mode : public CryptographicOperation {
public:
    explicit Edede3Mode(const std::string& key) {
        if (!EVP_EncryptInit_ex(ctx_, EVP_des_ede3_cbc(), nullptr, reinterpret_cast<const uint8_t*>(key.data()), nullptr)) {
            throw CryptoError("Failed to initialize EDE3 cipher.");
        }
    }

    void Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override;
    void Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override;

private:
    const EVP_CIPHER* cipher_ = EVP_des_ede3_cbc();
};

void Edede3Mode::Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) {
    if (!EVP_EncryptUpdate(ctx_, nullptr, nullptr, nullptr, 0)) throw CryptoError("Failed to encrypt.");
    output.resize(input.size() + EVP_CIPHER_block_size(cipher_));
    int out_len;
    if (!EVP_EncryptUpdate(ctx_, output.data(), &out_len, input.data(), input.size())) {
        throw CryptoError("Encryption failed in EDE3 mode.");
    }
    output.resize(out_len);
}

void Edede3Mode::Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) {
    if (!EVP_DecryptInit_ex(ctx_, cipher_, nullptr, nullptr, nullptr)) throw CryptoError("Failed to decrypt.");
    output.resize(input.size());
    int out_len;
    if (!EVP_DecryptUpdate(ctx_, output.data(), &out_len, input.data(), input.size())) {
        throw CryptoError("Decryption failed in EDE3 mode.");
    }
    output.resize(out_len);
}

// Utility class for random number generation
class RandomGenerator {
public:
    static std::mt19937& GetRandomEngine() {
        static thread_local std::random_device rd;
        static thread_local std::mt19937 engine(rd());
        return engine;
    }

    static uint8_t GenerateByte() {
        std::uniform_int_distribution<uint8_t> dist(0, 255);
        return dist(GetRandomEngine());
    }
};

// Null encryption for testing purposes
class NullEncryption : public CryptographicOperation {
public:
    void Encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override {
        output = input;
    }

    void Decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) override {
        output = input;
    }
};

// Factory class for creating cryptographic operations
class CryptoFactory {
public:
    static std::unique_ptr<CryptographicOperation> CreateCipherMode(std::string mode, const std::string& key) {
        if (mode == "ECB") return std::make_unique<EcbMode>(key);
        if (mode == "EDE3") return std::make_unique<Edede3Mode>(key);
        // Add more modes as needed
        return nullptr;
    }
};

// Logging utility
class Logger {
public:
    static void Log(const std::string& message) {
        std::cout << "[LOG] " << message << '\n';
    }

    static void Error(const std::string& error_message) {
        std::cerr << "[ERROR] " << error_message << '\n';
    }
};

int main() {
