        auto cipher = CryptoFactory::CreateCipherMode("ECB", "0123456789abcdef0123456789abcdef");
        if (!cipher) throw CryptoError("Cipher mode not supported.");

        std::vector<uint8_t> plaintext = { 'H', 'e', 'l', 'l', 'o' };
        std::vector<uint8_t> ciphertext;
        cipher->Encrypt(plaintext, ciphertext);

        Logger::Log("Encryption successful");

        std::vector<uint8_t> decryptedtext;
        cipher->Decrypt(ciphertext, decryptedtext);
