import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StringProcessor {

    private static final Logger LOGGER = Logger.getLogger(StringProcessor.class.getName());
    private static final int TIMEOUT_MILLIS = 5000; // 5 seconds timeout for processing each string

    public Map<String, String> processStrings(List<String> strings) {
        Map<String, String> resultMap = new HashMap<>();
        if (strings == null) return resultMap;

        try {
            for (String str : strings) {
                if (str != null && !resultMap.containsKey(str)) {
                    // Attempt to compute MD5 hash with timeout
                    String md5Hash = computeMD5WithTimeout(str);
                    if (md5Hash != null) {
                        resultMap.put(str, md5Hash);
                    }
                }
            }
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error processing strings", e);
            return new HashMap<>(); // Return empty map in case of failure
        }

        return resultMap;
    }

    private String computeMD5WithTimeout(String input) {
        try {
            long startTime = System.currentTimeMillis();
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());

            if (System.currentTimeMillis() - startTime > TIMEOUT_MILLIS) {
                throw new RuntimeException("Processing timeout exceeded for string: " + input);
            }

            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();

        } catch (NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "MD5 algorithm not found", e);
        } catch (RuntimeException e) {
            LOGGER.log(Level.WARNING, e.getMessage());
        }

        return null; // Return null if MD5 computation fails or times out
    }
}
