// Assuming AngularJS application setup
app.service('DialogFieldRefresher', ['$http', '$q', function($http, $q) {
    const config = {
        fieldsToRefresh: ['field1', 'field2'], // Example field names to refresh
        timeoutDuration: 5000,
        maxConcurrentRequests: 5,
        cache: new Map() // Simple in-memory caching
    };

    async function fetchFieldData(resourceId, url) {
        const cacheKey = `${resourceId}-${url}`;
        if (config.cache.has(cacheKey)) {
            return config.cache.get(cacheKey);
        }

        try {
            const response = await $http({
                method: 'GET',
                url,
                timeout: config.timeoutDuration
            }).$promise;

            config.cache.set(cacheKey, response.data);
            return response.data;
        } catch (error) {
            console.error('Error fetching field data:', error);
            return null; // Handle network errors gracefully
        }
    }

    function refreshDialogFields(resourceId, dialogFields) {
        const queue = [];
        const semaphore = new Semaphore(config.maxConcurrentRequests);

        dialogFields.forEach(field => {
            if (config.fieldsToRefresh.includes(field.name)) {
                queue.push(async () => {
                    await semaphore.acquire();
                    try {
                        const data = await fetchFieldData(resourceId, field.url);
                        window.parent.postMessage({ type: 'update-field', fieldName: field.name, data }, '*');
                    } finally {
                        semaphore.release();
                    }
                });
            }
        });

        return Promise.all(queue.map(task => task()));
    }

    function Semaphore(maxConcurrent) {
        this.count = maxConcurrent;
        this.waiting = [];

        this.acquire = () => new Promise(resolve => {
            if (this.count > 0) {
                this.count--;
                resolve();
            } else {
                this.waiting.push(resolve);
            }
        });

        this.release = () => {
            const resolve = this.waiting.shift();
            if (resolve) {
                resolve();
                this.count--;
            } else {
                this.count++;
            }
        };
    }

    return {
        refreshDialogFields
    };
}]);

// Usage example in a controller or component
