#define MAX_HOSTS 10

typedef struct {
    char *address;
    int port;
    float latency;
} Host;

typedef struct {
    char *service_name;
    int timeout;
    int secure_connection; // Use int for boolean: 0 = false, 1 = true
    Host *hosts[MAX_HOSTS];
    size_t host_count;
    pthread_mutex_t lock;
} Config;

// Function prototypes
int initializeConfig(Config **config);
void freeConfig(Config *config);
int addHost(Config *config, const char *address, int port, float latency);
int validateUserInput(const char *service_name, int timeout, int secure_connection);

int initializeConfig(Config **config) {
    if (!config || !(*config = (Config *)malloc(sizeof(Config)))) return -1;

    (*config)->service_name = NULL;
    (*config)->timeout = 0;
    (*config)->secure_connection = 0;
    (*config)->host_count = 0;
    pthread_mutex_init(&(*config)->lock, NULL);

    return 0; // Success
}

void freeConfig(Config *config) {
    if (!config) return;

    pthread_mutex_lock(&config->lock);

    if (config->service_name) free(config->service_name);
    for (size_t i = 0; i < config->host_count; ++i) {
        if (config->hosts[i]->address) free(config->hosts[i]->address);
        free(config->hosts[i]);
    }
    pthread_mutex_unlock(&config->lock);

    pthread_mutex_destroy(&config->lock);
    free(config);
}

int addHost(Config *config, const char *address, int port, float latency) {
    if (!config || !address || strlen(address) == 0 || config->host_count >= MAX_HOSTS)
        return -1;

    pthread_mutex_lock(&config->lock);

    for (size_t i = 0; i < config->host_count; ++i) {
        if (strcmp(config->hosts[i]->address, address) == 0) {
            pthread_mutex_unlock(&config->lock);
            return -2; // Duplicate address
        }
    }

    Host *new_host = (Host *)malloc(sizeof(Host));
    if (!new_host) {
        pthread_mutex_unlock(&config->lock);
        return -3; // Memory allocation failure
    }

    new_host->address = strdup(address);
    if (!new_host->address) {
        free(new_host);
        pthread_mutex_unlock(&config->lock);
        return -4; // Memory allocation failure
    }

    new_host->port = port;
    new_host->latency = latency;

    config->hosts[config->host_count++] = new_host;

    pthread_mutex_unlock(&config->lock);

    // Integrate with external services (pseudo-code)
    // authenticateUser();
    // logConfigurationChange(config);

    return 0; // Success
}

int validateUserInput(const char *service_name, int timeout, int secure_connection) {
    if (!service_name || strlen(service_name) == 0 || timeout <= 0 || 
        (secure_connection != 0 && secure_connection != 1))
        return -1;

    return 0; // Valid input
}

// Example usage:
int main() {
    Config *config = NULL;

    if (initializeConfig(&config) != 0) {
        fprintf(stderr, "Failed to initialize configuration\n");
        return EXIT_FAILURE;
    }

    char service_name[256];
    int timeout;
    int secure_connection;

    printf("Enter service name: ");
    scanf("%255s", service_name);

    printf("Enter timeout (seconds): ");
