    if (validateUserInput(service_name, timeout, secure_connection) != 0) {
        fprintf(stderr, "Invalid user input\n");
        freeConfig(config);
        return EXIT_FAILURE;
    }

    pthread_mutex_lock(&config->lock);
    config->service_name = strdup(service_name);
    config->timeout = timeout;
    config->secure_connection = secure_connection;
