    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int readIntegersAndFindMax(FILE *stream, int **maxIntegers, size_t *count) {
    if (!stream || !maxIntegers || !count) return 0;

    int number;
    size_t index = 0;
    size_t capacity = 10;
    *maxIntegers = malloc(capacity * sizeof(int));
    if (*maxIntegers == NULL) return 0;

    int max = INT_MIN;
    while (fscanf(stream, "%d", &number) != EOF) {
        if (index >= capacity) {
            capacity *= 2;
            *maxIntegers = realloc(*maxIntegers, capacity * sizeof(int));
            if (*maxIntegers == NULL) return 0;
        }
        (*maxIntegers)[index++] = number;
        if (number > max) max = number;
    }

    *count = index;
    fclose(stream);
    return max;
}

int executeCommandAndProcessData(const char *command, FILE *stream) {
    pid_t pid;
    int status;

    // Fork process
    pid = fork();
    if (pid < 0) {
        perror("fork failed");
        return 0;
    }

    if (pid == 0) { // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        perror("execlp failed");
        exit(EXIT_FAILURE);
    } else { // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Command execution failed\n");
            return 0;
        }
    }

    int *maxIntegers = NULL;
    size_t count = 0;
    int maxNumber = readIntegersAndFindMax(stream, &maxIntegers, &count);
    if (maxNumber == 0) {
        fprintf(stderr, "Failed to process data\n");
        free(maxIntegers);
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfapiList = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapiList) {
        perror("Memory allocation failed for nfapiList");
        free(maxIntegers);
        return 0;
    }

    for (size_t i = 0; i < count; ++i) {
        nfapiList[i].RX_UE_INFORMATION_TAG = maxIntegers[i];
        nfapiList[i].RNTI = rand() % 10000;
        nfapiList[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    free(maxIntegers);
    free(nfapiList);

    return 1;
}
