#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <omp.h>
#include <time.h>

// Configuration structure to hold encryption parameters
typedef struct {
    const char *algorithm;
    const char *mode;
} EncryptionConfig;

// Function to initialize the cipher based on configuration
EVP_CIPHER_CTX* init_cipher(const EncryptionConfig *config, unsigned char *key, int key_len, unsigned char *iv, int iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    const EVP_CIPHER *cipher;
    if (strcmp(config->algorithm, "AES") == 0 && strcmp(config->mode, "CBC") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(config->algorithm, "ChaCha20") == 0) {
        cipher = EVP_chacha20();
    } else if (strcmp(config->algorithm, "XChaCha20") == 0) {
        cipher = EVP_xchacha20();
    } else {
        fprintf(stderr, "Unsupported algorithm or mode\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to encrypt data
int encrypt_data(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, int plaintext_len, 
                 unsigned char *ciphertext, unsigned char *tag) {
    int len;
    int ciphertext_len;

    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        return -1;
    }
    ciphertext_len += len;

    // Get the tag length
    int tag_len = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    return ciphertext_len;
}

// Function to perform encryption on a file
void encrypt_file(const char *filename, const EncryptionConfig *config) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Could not open %s\n", filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    unsigned char *plaintext = malloc(fsize);
    fread(plaintext, 1, fsize, file);
    fclose(file);

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    // Generate random key and IV
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX *ctx = init_cipher(config, key, sizeof(key), iv, sizeof(iv));
    if (!ctx) {
        free(plaintext);
        return;
    }

    unsigned char ciphertext[fsize + EVP_MAX_BLOCK_LENGTH];
    unsigned char tag[EVP_MAX_MD_SIZE];

    int len = encrypt_data(ctx, plaintext, fsize, ciphertext, tag);
    if (len >= 0) {
        printf("Encryption successful for %s\n", filename);
        // Save or process encrypted data
    } else {
        fprintf(stderr, "Encryption failed for %s\n", filename);
    }

    EVP_CIPHER_CTX_free(ctx);
    free(plaintext);
}

// Main function to demonstrate batch processing of files
int main() {
    EncryptionConfig config = {"AES", "CBC"};

    const char *files[] = {"file1.txt", "file2.txt", "file3.txt"};
    int num_files = sizeof(files) / sizeof(files[0]);

    #pragma omp parallel for
    for (int i = 0; i < num_files; ++i) {
        encrypt_file(files[i], &config);
    }

    return 0;
}
```

