// Assuming existence of an external logging library
void log_message(const char *message);
double start_timer();
double end_timer(double start);

typedef struct {
    int value;
} record;

#define LOG_ALLOCATION(duration, message) \
    do { \
        double time_taken = end_timer(start); \
        log_message(message); \
        log_message("Time taken: "); \
        printf("%f\n", time_taken); \
    } while (0)

pthread_mutex_t lock; // Mutex for synchronizing access

void *realloc_if_needed(void *ptr, size_t current_size, size_t new_size, const char *name) {
    pthread_mutex_lock(&lock);
    if (new_size > current_size) {
        void *new_ptr = realloc(ptr, new_size * sizeof(*(char *)ptr));
        LOG_ALLOCATION(start_timer(), name " allocation resized");
        if (!new_ptr) {
            log_message("Reallocation failed.");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        ptr = new_ptr;
    }
    pthread_mutex_unlock(&lock);
    return ptr;
}

bool contains(int *array, int size, int key) {
    for (int i = 0; i < size; ++i) {
        if (array[i] == key)
            return true;
    }
    return false;
}

void manage_memory(size_t offsets_size, size_t keys_size, int range_min, int range_max) {
    pthread_mutex_init(&lock, NULL);

    long *offsets = malloc(offsets_size * sizeof(long));
    int *keys = malloc(keys_size * sizeof(int));

    if (!offsets || !keys) {
        log_message("Initial allocation failed.");
        return;
    }

    size_t max_size = offsets_size > keys_size ? offsets_size : keys_size;
    record *records = malloc(max_size * sizeof(record));

    double start;

    // Initialize offsets
    start = start_timer();
    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = i;
    }
    LOG_ALLOCATION(start, "Offset");

    // Populate keys ensuring no duplicates
    srand(time(NULL));  // Seed the random number generator

    int added_keys = 0;
    start = start_timer();
    while (added_keys < keys_size) {
        int key = rand() % (10000);  // Arbitrary range for demonstration
        if (!contains(keys, added_keys, key)) {
            keys[added_keys++] = key;
        }
    }
    LOG_ALLOCATION(start, "Keys");

    // Initialize records with random values
    start = start_timer();
    for (size_t i = 0; i < max_size; ++i) {
        int rand_val = range_min + rand() % (range_max - range_min + 1);
        records[i].value = rand_val;
    }
    LOG_ALLOCATION(start, "Records");

    // Example of resizing
    size_t new_offsets_size = offsets_size * 2;  // Just an example resizing
    offsets = realloc_if_needed(offsets, offsets_size, new_offsets_size, "Offsets");

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&lock);

    log_message("Memory management completed.");
}

int main() {
    size_t offsets_size = 10;
    size_t keys_size = 15;
    int range_min = 1, range_max = 100;

    manage_memory(offsets_size, keys_size, range_min, range_max);

    return 0;
}
