status_t create_data_structures(long* offset_count, int* key_count, long** offsets, int** keys, record*** records_ptr, record** pointers_to_records) {
    if (!offset_count || !key_count || !offsets || !keys || !records_ptr || !pointers_to_records) {
        return MEMORY_ERROR;
    }

    // Allocate memory for the offset and key arrays
    *offsets = (long*)malloc(*offset_count * sizeof(long));
    *keys = (int*)malloc(*key_count * sizeof(int));

    if (*offsets == NULL || *keys == NULL) {
        free(*offsets);
        free(*keys);
        return MEMORY_ERROR;
    }

    // Random number setup
