    long records_size = (*offset_count > 0 && *key_count > 0) ? (*offset_count + *key_count) : 1; // Ensure at least one record

    // Allocate memory for the array of records and pointers to records
    *records_ptr = (record**)malloc(records_size * sizeof(record*));
    *pointers_to_records = (record*)malloc(records_size * sizeof(record));

    if (*records_ptr == NULL || *pointers_to_records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records_ptr);
        free(*pointers_to_records);
        return MEMORY_ERROR;
    }

    // Initialize records with random values, ensuring no consecutive duplicates
