static pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;
static int max_threads;
static char log_level[10] = DEFAULT_LOG_LEVEL;

// Logger function to write errors to a file
void log_error(const char *message) {
    FILE *log_file = fopen("error.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T* init_list(int n);
void free_list(NFAPI_CRC_INDICATION_PDU_T *list);
int add_pdu(NFAPI_CRC_INDICATION_PDU_T **list, int *size, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T* get_pdu_by_index(const NFAPI_CRC_INDICATION_PDU_T *list, int size, int index);

// Configuration loader
void load_configuration() {
