    if (getenv("MAX_THREADS") != NULL) {
        strncpy(max_threads_env, getenv("MAX_THREADS"), sizeof(max_threads_env));
    } else {
        snprintf(max_threads_env, sizeof(max_threads_env), "%d", DEFAULT_MAX_THREADS);
    }
    max_threads = atoi(max_threads_env);

    char log_level_env[10];
    if (getenv("LOG_LEVEL") != NULL) {
        strncpy(log_level_env, getenv("LOG_LEVEL"), sizeof(log_level_env));
    } else {
        strcpy(log_level_env, DEFAULT_LOG_LEVEL);
    }
    strncpy(log_level, log_level_env, sizeof(log_level));
}

// Initialize the list
NFAPI_CRC_INDICATION_PDU_T* init_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_error("Memory allocation failed for list initialization");
        return NULL;
    }
    pthread_rwlock_wrlock(&list_lock);
    memset(list, 0, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_rwlock_unlock(&list_lock);
    return list;
}

// Free the list
void free_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        pthread_rwlock_wrlock(&list_lock);
        free(list);
        pthread_rwlock_unlock(&list_lock);
    }
}

// Add a PDU to the list
int add_pdu(NFAPI_CRC_INDICATION_PDU_T **list, int *size, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (*size == 0 || (*list)[*size - 1].RX_UE_INFORMATION_TAG != 0) {
        return -1; // Invalid state
    }

    pthread_rwlock_wrlock(&list_lock);
    int current_size = *size;
    if (current_size >= *size) {
        int new_size = current_size + 10; // Increment size in chunks for efficiency
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(*list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_rwlock_unlock(&list_lock);
            log_error("Memory allocation failed while expanding list");
            return -1;
        }
        *list = new_list;
        (*size) = new_size;
    }

    (*list)[current_size] = pdu;
    pthread_rwlock_unlock(&list_lock);
    return 0;
}

// Retrieve a PDU by index
NFAPI_CRC_INDICATION_PDU_T* get_pdu_by_index(const NFAPI_CRC_INDICATION_PDU_T *list, int size, int index) {
