    if (!result) {
        pthread_rwlock_unlock(&list_lock);
        log_error("Memory allocation failed while retrieving PDU");
        return NULL;
    }
    memcpy(result, &list[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_rwlock_unlock(&list_lock);

