#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/ecdsa.h>
#include <openssl/bn.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

#define AES_KEY_SIZE 32 // Using AES-256
#define AES_BLOCK_SIZE 16
#define HMAC_KEY_SIZE 32

void process_data_stream(const unsigned char *raw_data, size_t data_len,
                         unsigned char **processed_buffer, size_t *processed_len) {
    EVP_CIPHER_CTX *aes_ctx;
    HMAC_CTX *hmac_ctx;
    ECDSA_SIG *ecdsa_sig;
    EC_KEY *ec_key;
    BIGNUM *r, *s;

    // Initialize AES context
    aes_ctx = EVP_CIPHER_CTX_new();
    unsigned char aes_key[AES_KEY_SIZE];
    RAND_bytes(aes_key, sizeof(aes_key));

    // Initialize HMAC context
    hmac_ctx = HMAC_CTX_new();
    unsigned char hmac_key[HMAC_KEY_SIZE];
    RAND_bytes(hmac_key, sizeof(hmac_key));

    // Initialize ECDSA key
    ec_key = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
    EC_KEY_generate_key(ec_key);

    // Calculate segment size and number of segments (example: 1024 bytes per segment)
    size_t segment_size = 1024;
    size_t num_segments = (data_len + segment_size - 1) / segment_size;

    *processed_buffer = malloc(data_len + data_len / 2); // Extra space for HMAC, AES padding, and signature
    if (!*processed_buffer) {
        EVP_CIPHER_CTX_free(aes_ctx);
        HMAC_CTX_free(hmac_ctx);
        EC_KEY_free(ec_key);
        return;
    }

    unsigned char *buf_ptr = *processed_buffer;

    for (size_t i = 0; i < num_segments; ++i) {
        size_t current_segment_size = data_len - i * segment_size > segment_size ? segment_size : data_len - i * segment_size;

        // AES Encryption
        EVP_EncryptInit_ex(aes_ctx, EVP_aes_256_gcm(), NULL, aes_key, NULL);
        unsigned char iv[AES_BLOCK_SIZE];
        RAND_bytes(iv, sizeof(iv));
        memcpy(buf_ptr, iv, sizeof(iv));
        buf_ptr += sizeof(iv);

        int len;
        EVP_EncryptUpdate(aes_ctx, buf_ptr, &len, raw_data + i * segment_size, current_segment_size);
        buf_ptr += len;

        unsigned char tag[AES_BLOCK_SIZE];
        EVP_EncryptFinal_ex(aes_ctx, buf_ptr, &len);
        buf_ptr += len;

        EVP_CIPHER_CTX_ctrl(aes_ctx, EVP_CTRL_GCM_GET_TAG, AES_BLOCK_SIZE, tag);
        memcpy(buf_ptr, tag, sizeof(tag));
        buf_ptr += sizeof(tag);

        // HMAC
        HMAC_Init_ex(hmac_ctx, hmac_key, sizeof(hmac_key), EVP_sha256(), NULL);
        HMAC_Update(hmac_ctx, *processed_buffer, (buf_ptr - *processed_buffer) + AES_BLOCK_SIZE);
        unsigned char mac[EVP_MAX_MD_SIZE];
        unsigned int mac_len;
        HMAC_Final(hmac_ctx, mac, &mac_len);
        memcpy(buf_ptr, mac, mac_len);
        buf_ptr += mac_len;

        // ECDSA Signature
        ecdsa_sig = ECDSA_do_sign(*processed_buffer + sizeof(iv), (buf_ptr - *processed_buffer) - AES_BLOCK_SIZE - mac_len, ec_key);

        r = BN_new();
        s = BN_new();
        ECDSA_SIG_get0(ecdsa_sig, &r, &s);

        // Serialize the signature
        size_t sig_size = BN_num_bytes(r) + BN_num_bytes(s);
        unsigned char *signature = malloc(sig_size);
        if (!signature) {
            EVP_CIPHER_CTX_free(aes_ctx);
            HMAC_CTX_free(hmac_ctx);
            EC_KEY_free(ec_key);
            return;
        }

        BN_bn2binpad(r, signature, BN_num_bytes(r));
        memcpy(signature + BN_num_bytes(r), s->d, BN_num_bytes(s));

        memcpy(buf_ptr, signature, sig_size);
        buf_ptr += sig_size;

        free(signature);

        // Cleanup
        ECDSA_SIG_free(ecdsa_sig);
    }

    *processed_len = (buf_ptr - *processed_buffer);

    // Clean up
    EVP_CIPHER_CTX_free(aes_ctx);
    HMAC_CTX_free(hmac_ctx);
    EC_KEY_free(ec_key);
}
