    ListElement* current = list->head;
    while (current != NULL) {
        if (current->data.CRC_INDICATION_REL8_TAG == crc_indicator) {
            pthread_rwlock_unlock(&list->rwlock);
            return 0; // Duplicate found
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->rwlock);
    return 1; // Unique
