int addElement(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!isValidRX_UE_INFORMATION_TAG(element.RX_UE_INFORMATION_TAG)) return -1;
    if (!isValidRNTI(element.RNTI)) return -2;

    pthread_rwlock_wrlock(&list->rwlock);
    if (isUniqueCRCIndicator(list, element.CRC_INDICATION_REL8_TAG) == 0) {
        pthread_rwlock_unlock(&list->rwlock);
        return -3; // Duplicate CRC indicator
    }

    ListElement* new_element = malloc(sizeof(ListElement));
    if (!new_element) {
        pthread_rwlock_unlock(&list->rwlock);
        return -4; // Memory allocation failed
    }

    memcpy(&new_element->data, &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->next = list->head;
    list->head = new_element;
    list->size++;

    if (list->size > MAX_LIST_SIZE) {
        // Handle overflow scenario
        ListElement* to_free = list->head;
        list->head = to_free->next;
        free(to_free);
        list->size--;
    }

    pthread_rwlock_unlock(&list->rwlock);
    return 0; // Success
}

void clearList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    ListElement* current = list->head;
    while (current != NULL) {
        ListElement* to_free = current;
        current = current->next;
        free(to_free);
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void initializeList(CRCList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
}

void resetList(CRCList* list) {
