['Below is a C implementation of the specified task using POSIX threads and semaphores for concurrency control. This example assumes the presence of some necessary headers like `pthread.h`, `semaphore.h`, and others needed for logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define LOG_FILE "error_log.txt"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32]; // Adjust size as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t capacity;
    size_t count;
    sem_t semaphore;
} PDU_Manager;

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

PDU_Manager* initialize_pdu_manager(size_t initial_capacity) {
    PDU_Manager* manager = malloc(sizeof(PDU_Manager));
    if (!manager) {
        log_error("Failed to allocate memory for PDU Manager");
        return NULL;
    }

    manager->pdu_list = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        free(manager);
        log_error("Failed to allocate memory for PDU list");
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    if (sem_init(&manager->semaphore, 0, 1)) { // Use binary semaphore
        free(manager->pdu_list);
        free(manager);
        log_error("Failed to initialize semaphore");
        return NULL;
    }

    return manager;
}

void deallocate_pdu_manager(PDU_Manager* manager) {
    if (manager) {
        sem_destroy(&manager->semaphore);
        free(manager->pdu_list);
        free(manager);
    }
}

int add_pdu_entry(PDU_Manager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager) return -1;

    if (sem_wait(&manager->semaphore)) {
        log_error("Semaphore wait failed");
        return -1;
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_list = realloc(manager->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp_list) {
            sem_post(&manager->semaphore);
            log_error("Failed to reallocate memory for PDU list");
            return -1;
        }
        manager->pdu_list = temp_list;
        manager->capacity = new_capacity;
    }

    manager->pdu_list[manager->count++] = pdu;

    if (sem_post(&manager->semaphore)) {
        log_error("Semaphore post failed");
        return -1;
    }

    return 0;
}

int get_pdu_entry(PDU_Manager* manager, size_t index, NFAPI_CRC_INDICATION_PDU_T* out_pdu) {
    if (!manager || !out_pdu || index >= manager->count) return -1;

    if (sem_wait(&manager->semaphore)) {
        log_error("Semaphore wait failed");
        return -1;
    }

    *out_pdu = manager->pdu_list[index];

    if (sem_post(&manager->semaphore)) {
        log_error("Semaphore post failed");
        return -1;
    }

    return 0;
}

// Example usage
int main() {
    PDU_Manager* pdu_manager = initialize_pdu_manager(10);
    if (!pdu_manager) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, "Sample CRC" };
    if (add_pdu_entry(pdu_manager, pdu) != 0) {
        log_error("Failed to add PDU entry");
    }

    NFAPI_CRC_INDICATION_PDU_T retrieved_pdu;
    if (get_pdu_entry(pdu_manager, 0, &retrieved_pdu) == 0) {
        printf("Retrieved PDU: RX_TAG=%d, RNTI=%d, CRC='%s'\n",
               retrieved_pdu.RX_UE_INFORMATION_TAG,
               retrieved_pdu.RNTI,
               retrieved_pdu.CRC_INDICATION_REL8_TAG);
    } else {
        log_error("Failed to retrieve PDU entry");
    }

    deallocate_pdu_manager(pdu_manager);

    return EXIT_SUCCESS;
}
```

### Explanation of Key Parts:
- **Semaphore Initialization and Cleanup**: The semaphore is initialized with a value of 1 for binary locking. It is destroyed in `deallocate_pdu_manager`.

- **Error Handling and Logging**: Errors are logged to a file, making it easier to debug issues related to memory allocation or semaphore operations.

- **Thread Safety**: All modifications to the list (additions and retrievals) use semaphores to ensure thread safety.

- **Dynamic Memory Management**: The `pdu_list` is dynamically resized as needed, doubling in capacity when full. This balances between performance and memory fragmentation.']

