#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    uint8_t CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_PDUS 1000

pthread_mutex_t pdu_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pdu_pool[MAX_PDUS];
