// Memory pool allocation function
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pdu_lock);

    if (current_size < MAX_PDUS) {
        for (size_t i = 0; i < MAX_PDUS; ++i) {
            if (pdu_pool[i] == NULL) {
                pdu_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pdu_pool[i]) {
                    log_error("Memory allocation failed");
                    pthread_mutex_unlock(&pdu_lock);
                    return NULL;
                }
                ++current_size;
                pthread_mutex_unlock(&pdu_lock);
                return pdu_pool[i];
            }
        }
    } else {
        pthread_mutex_unlock(&pdu_lock);
        log_error("No available slots for PDU allocation");
        return NULL;
    }

    pthread_mutex_unlock(&pdu_lock);
    return NULL; // Should not reach here
}

// Release memory of a specific PDU back to the pool
void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL && current_size > 0) {
        pthread_mutex_lock(&pdu_lock);

        for (size_t i = 0; i < MAX_PDUS; ++i) {
            if (pdu_pool[i] == pdu) {
                free(pdu);
                pdu_pool[i] = NULL;
                --current_size;
                break;
            }
        }

        pthread_mutex_unlock(&pdu_lock);
    }
}

// Populate PDU with valid data
int populate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rx_ue_info_tag, uint16_t rnti) {
    if (pdu == NULL) {
        return -1;
    }

    pdu->tag.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->tag.RNTI = rnti;

    // Set CRCFLAG to a random value
    pdu->CRCFLAG = rand() % 2; // 0 or 1

    return 0;
}

// Function to create and populate N PDUs
int create_pdus(size_t n) {
    size_t success_count = 0;

    for (size_t i = 0; i < n; ++i) {
        uint32_t rx_ue_info_tag = rand(); // Generate a random valid tag
        uint16_t rnti = rand() % 65536;   // Random RNTI

        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
        if (pdu == NULL) {
            log_error("Failed to create PDU");
            continue;
        }

        if (populate_pdu(pdu, rx_ue_info_tag, rnti) != 0) {
            free_pdu(pdu);
            log_error("Failed to populate PDU");
            continue;
        }

        success_count++;
    }

    printf("Successfully created %zu PDUs\n", success_count);
    return (int)success_count;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed the random number generator

    create_pdus(100); // Create and populate 100 PDUs

    // Clean up allocated memory before exiting
    for (size_t i = 0; i < MAX_PDUS; ++i) {
        if (pdu_pool[i] != NULL) {
            free_pdu(pdu_pool[i]);
        }
    }

    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses `pthread_mutex` to manage concurrent access.
- **Memory Management:** Implements a custom allocation strategy with a fixed-size pool for reusing memory efficiently, reducing overhead from frequent allocations and deallocations.
- **Error Handling:** Logs errors when allocation or population fails due to insufficient resources.
- **Modularity & Extensibility:** Designed to be easily updated for future changes in network protocols.']

