        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}

int add_pdu(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Error: Array is full\n");
        return -2;
    }

    manager->array[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

