    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[index];
    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

size_t get_count(CRC_Indication_Manager *manager) {
    if (!manager) return 0;

    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

