typedef struct DynamicArray {
    NFAPI_RRC_MESSAGE_T **messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->capacity = initial_capacity;
    array->size = 0;
    array->messages = (NFAPI_RRC_MESSAGE_T**)calloc(initial_capacity, sizeof(NFAPI_RRC_MESSAGE_T*));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->messages[i]->commands);
        free(array->messages[i]);
    }
    free(array->messages);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_if_needed(DynamicArray *array) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        NFAPI_RRC_MESSAGE_T **new_messages = (NFAPI_RRC_MESSAGE_T**)realloc(array->messages, new_capacity * sizeof(NFAPI_RRC_MESSAGE_T*));
        if (!new_messages) {
            // Handle memory allocation failure
            return;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
}

void add_message(DynamicArray *array, NFAPI_RRC_MESSAGE_T *message) {
    pthread_mutex_lock(&array->lock);
    resize_if_needed(array);
    array->messages[array->size++] = message;
    pthread_mutex_unlock(&array->lock);
}

void remove_message(DynamicArray *array, size_t index) {
    if (index >= array->size) return;

    pthread_mutex_lock(&array->lock);

    free(array->messages[index]->commands);
    free(array->messages[index]);

    for (size_t i = index; i < array->size - 1; ++i) {
        array->messages[i] = array->messages[i + 1];
    }

    --array->size;
    pthread_mutex_unlock(&array->lock);
}

void update_message(DynamicArray *array, size_t index, NFAPI_RRC_MESSAGE_T *new_message) {
    if (index >= array->size) return;

    pthread_mutex_lock(&array->lock);

    free(array->messages[index]->commands);
    array->messages[index] = new_message;

    pthread_mutex_unlock(&array->lock);
}

int main() {
    // Example usage
    DynamicArray *dynamic_array = create_dynamic_array(10);

    NFAPI_RRC_MESSAGE_T *message1 = (NFAPI_RRC_MESSAGE_T*)malloc(sizeof(NFAPI_RRC_MESSAGE_T));
    message1->num_commands = 2;
    message1->commands = (RRC_RECONFIGURATION_COMMAND_T*)malloc(2 * sizeof(RRC_RECONFIGURATION_COMMAND_T));

    add_message(dynamic_array, message1);

    // Further operations...

    free_dynamic_array(dynamic_array);
    return 0;
}
