void log_error(const char *error_message) {
    static FILE *log_file = NULL;
    static size_t log_size = 0;

    if (!log_file) {
        log_file = fopen("errors.log", "a");
        if (!log_file) return;
    }

    fprintf(log_file, "%s\n", error_message);
    log_size += strlen(error_message) + 1; // +1 for newline

    if (log_size >= MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = NULL;
        log_size = 0;
    }
}

uint32_t create_nfa_crc_indication_pdu_list(size_t n, DynamicArray *array) {
    uint32_t checksum = 0;
    size_t rnti_set[10000] = {0}; // Bitset for up to 10,000 unique RNTIs
    srand((unsigned int)time(NULL));

    init_dynamic_array(array);

    while (array->size < n) {
        if (!resize_dynamic_array(array, array->capacity * 2)) {
            log_error("Failed to resize dynamic array");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Random valid tag
        uint16_t rnti;

        do {
            rnti = (uint16_t)rand();
        } while (rnti_set[rnti]);

        pdu.RNTI = rnti;
        pdu.CRCFLAG = rand() & 1; // Random CRCFLAG (0 or 1)
        checksum ^= pdu.CRCFLAG;

        array->data[array->size++] = pdu;
        rnti_set[rnti] = 1; // Mark RNTI as used
    }

    return checksum;
}

int main() {
    DynamicArray pdu_list;
    uint32_t final_checksum = create_nfa_crc_indication_pdu_list(10000, &pdu_list);
    printf("Final Checksum: %u\n", final_checksum);

    free_dynamic_array(&pdu_list);
    return 0;
}
