#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Example fields for MAC_HEADER
    unsigned char mac_header[6];
} MAC_HEADER;

typedef struct {
    // Example fields for PHY_RX_PACKET
    unsigned char phy_rx_packet[256];
} PHY_RX_PACKET;

typedef struct {
    MAC_HEADER header;
    PHY_RX_PACKET packet;
    int valid;  // Metadata indicating if the message is valid
    int processed;  // Metadata to indicate processing status
} MAC_RX_MESSAGE_T;

typedef struct Node {
    MAC_RX_MESSAGE_T* message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t count;
    int error_count;
} MessageList;

// Function prototypes
void initMessageList(MessageList* list);
void freeMessageList(MessageList* list);
int addMessage(MessageList* list, MAC_RX_MESSAGE_T* message);
MAC_RX_MESSAGE_T* getMessage(MessageList* list);
void processMessages(MessageList* list);

void initMessageList(MessageList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->count = 0;
    list->error_count = 0;
}

void freeMessageList(MessageList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

int addMessage(MessageList* list, MAC_RX_MESSAGE_T* message) {
    pthread_mutex_lock(&list->mutex);

    if (message == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;  // Invalid message
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        list->error_count++;
        pthread_mutex_unlock(&list->mutex);
        return -2;  // Memory allocation failure
    }

    newNode->message = message;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;  // Success
}

MAC_RX_MESSAGE_T* getMessage(MessageList* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    Node* node = list->head;
    MAC_RX_MESSAGE_T* message = node->message;

    list->head = node->next;
    free(node);
    list->count--;

    pthread_mutex_unlock(&list->mutex);
    return message;
}

void processMessages(MessageList* list) {
    while (1) {
        MAC_RX_MESSAGE_T* message = getMessage(list);

        if (!message) {
            // No more messages to process
            break;
        }

        if (!message->valid || !processPacket(message)) {
            printf("Error processing packet\n");
            list->error_count++;
        }

        free(message);  // Free the memory after processing
    }
}

int processPacket(MAC_RX_MESSAGE_T* message) {
    // Dummy implementation for processing a packet
    // In practice, this would involve various checks and operations
    return message->valid;
}
