```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets; // Dynamic array of offsets
    int *keys;     // Array of keys
    record **records; // Secondary array of pointers to records
    size_t capacity;  // Total allocated capacity for records
    size_t count;     // Current number of records
} DataStructure;

// Function to initialize the data structure
DataStructure* initDataStructure(size_t initialCapacity) {
    if (initialCapacity == 0) return NULL;

    DataStructure *ds = malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offsets = calloc(initialCapacity, sizeof(long));
    if (!ds->offsets) {
        free(ds);
        return NULL;
    }

    ds->keys = calloc(initialCapacity, sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = malloc(sizeof(record*) * initialCapacity);
    if (!ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        ds->records[i] = NULL;
    }

    ds->capacity = initialCapacity;
    ds->count = 0;

    return ds;
}

// Function to add a new record with unique random value
int addRecord(DataStructure *ds, int minVal, int maxVal) {
    if (!ds || ds->count >= ds->capacity) {
        // Resize the arrays if necessary
        size_t newCapacity = (ds->capacity == 0) ? 1 : ds->capacity * 2;

        long *newOffsets = realloc(ds->offsets, sizeof(long) * newCapacity);
        int *newKeys = realloc(ds->keys, sizeof(int) * newCapacity);
        record **newRecords = realloc(ds->records, sizeof(record*) * newCapacity);

        if (!newOffsets || !newKeys || !newRecords) {
            printf("Memory allocation failed\n");
            return -1;
        }

        ds->offsets = newOffsets;
        ds->keys = newKeys;
        ds->records = newRecords;

        for (size_t i = ds->capacity; i < newCapacity; ++i) {
            ds->records[i] = NULL;
        }

        ds->capacity = newCapacity;
    }

    int uniqueValue = rand() % (maxVal - minVal + 1) + minVal;
    while ((ds->count > 0) && (uniqueValue == ds->records[ds->count - 1]->value)) {
        uniqueValue = rand() % (maxVal - minVal + 1) + minVal; // Ensure uniqueness
    }

    record *newRecord = malloc(sizeof(record));
    if (!newRecord) {
        printf("Memory allocation failed\n");
        return -1;
    }

    newRecord->value = uniqueValue;
    ds->records[ds->count] = newRecord;

    ds->keys[ds->count] = rand(); // Assign a random key
    ds->offsets[ds->count] = (long) newRecord; // Store the pointer offset

    ++(ds->count);

    return 0;
}

// Function to safely deallocate all memory
void freeDataStructure(DataStructure *ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]);
        }
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    DataStructure *ds = initDataStructure(10);
    if (!ds) return 1;

    for (size_t i = 0; i < 20; ++i) { // Add more records than initial capacity
        if (addRecord(ds, 1, 100) != 0) {
            break;
        }
    }

    printf("Total Records: %zu\n", ds->count);

    freeDataStructure(ds);
    return 0;
}
```

This code defines a `DataStructure` that manages dynamic arrays for offsets, keys, and records. It supports adding new records with unique random values within a specified range, ensuring no duplicates among consecutive entries. The data structure resizes as necessary to accommodate additional records while maintaining performance efficiency. Memory is managed safely, with appropriate error handling for allocation failures.']

