// Global variables for thread safety and resource management
pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
size_t pdu_count = 0;
char default_theme_directory[256] = "default_theme_dir";
char theme_cache_root[256];
unsigned char last_used_bitmap_timestamps[1024]; // Example size

