void recycle_theme_bitmap(void* bitmap);
EVP_CIPHER_CTX* initiate_aes_256_cbc(const char* password);

// Initialize list of NFAPI_CRC_INDICATION_PDU_T structures
void initialize_pdu_list(size_t n) {
    pthread_mutex_lock(&pdu_list_mutex);
    if (pdu_list != NULL) {
        free(pdu_list);
    }
    pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory for PDU list");
        pthread_mutex_unlock(&pdu_list_mutex);
        return;
    }

    // Initialize PDUs with random values
    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 10000; // Example range
