    struct {
        // Add relevant fields here
    } RX_UE_INFORMATION_TAG;
    struct {
        // Add relevant fields here
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    size_t count;
} DynamicList;

// Function prototypes
DynamicList* create_list(void);
void destroy_list(DynamicList* list, FILE* log_file);
int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry, FILE* log_file);
NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(DynamicList* list, uint16_t rnti);
void remove_entry_by_rnti(DynamicList* list, uint16_t rnti, FILE* log_file);
uint32_t calculate_checksum(DynamicList* list);
void log_error(const char* message, FILE* log_file);

DynamicList* create_list(void) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_rwlock_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_list(DynamicList* list, FILE* log_file) {
    if (pthread_rwlock_wrlock(&list->lock) != 0) {
        log_error("Failed to acquire write lock", log_file);
    }

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
    free(list);

    if (log_file && !feof(log_file)) {
        fclose(log_file);
    }
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry, FILE* log_file) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for node", log_file);
        return -1;
    }

    if (pthread_rwlock_wrlock(&list->lock) != 0) {
        free(new_node);
        log_error("Failed to acquire write lock", log_file);
        return -1;
    }

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(DynamicList* list, uint16_t rnti) {
    if (pthread_rwlock_rdlock(&list->lock) != 0) {
        perror("Failed to acquire read lock");
        return NULL;
    }

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_rwlock_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

void remove_entry_by_rnti(DynamicList* list, uint16_t rnti, FILE* log_file) {
    if (pthread_rwlock_wrlock(&list->lock) != 0) {
        log_error("Failed to acquire write lock", log_file);
        return;
    }

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->count--;
            pthread_rwlock_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

uint32_t calculate_checksum(DynamicList* list) {
    uint32_t checksum = 0;

    if (pthread_rwlock_rdlock(&list->lock) != 0) {
        perror("Failed to acquire read lock");
        return 0;
    }

    Node* current = list->head;
    while (current) {
        // Simplified checksum calculation
        checksum += current->data.RNTI; 
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return checksum;
}

void log_error(const char* message, FILE* log_file) {
    if (!log_file) return;

    fprintf(log_file, "ERROR: %s\n", message);

    // Implement logic to limit log file size here
}

int main(void) {
    DynamicList* list = create_list();
    if (!list) return EXIT_FAILURE;

    FILE* log_file = fopen("error_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        destroy_list(list, NULL);
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T entry = {1234}; // Add relevant data here
    add_entry(list, entry, log_file);

    uint32_t checksum = calculate_checksum(list);
    printf("Checksum: %u\n", checksum);

    destroy_list(list, log_file);
    return EXIT_SUCCESS;
}
```

