#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct {
    int message_id;
    char *message_data;
} RRC_MESSAGE;

typedef struct {
    RRC_MESSAGE connection_complete;
    RRC_MESSAGE reconfiguration_commands[10];
    int num_reconfig_commands;
    RRC_MESSAGE reconfiguration_complete_reason;
} NFAPI_RRC_MESSAGE_T;

typedef struct {
    NFAPI_RRC_MESSAGE_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
DynamicArray* initializeDynamicArray();
int addElement(DynamicArray *dyn_array, NFAPI_RRC_MESSAGE_T element);
int removeElement(DynamicArray *dyn_array, int index);
void updateElement(DynamicArray *dyn_array, int index, NFAPI_RRC_MESSAGE_T element);
void freeDynamicArray(DynamicArray *dyn_array);

// SQL related functions
void executeSQLQuery(int supervisor_id, const char *username, const char *password);

// Initialize dynamic array
DynamicArray* initializeDynamicArray() {
    DynamicArray *dyn_array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->size = 0;
    dyn_array->capacity = 10; // Initial capacity
    dyn_array->array = (NFAPI_RRC_MESSAGE_T *)calloc(dyn_array->capacity, sizeof(NFAPI_RRC_MESSAGE_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    pthread_mutex_init(&dyn_array->lock, NULL);
    return dyn_array;
}

// Add element to dynamic array
int addElement(DynamicArray *dyn_array, NFAPI_RRC_MESSAGE_T element) {
    if (pthread_mutex_lock(&dyn_array->lock) != 0) return -1;

    if (dyn_array->size == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_RRC_MESSAGE_T *new_array = (NFAPI_RRC_MESSAGE_T *)realloc(dyn_array->array, new_capacity * sizeof(NFAPI_RRC_MESSAGE_T));
        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1;
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    dyn_array->array[dyn_array->size++] = element;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

// Remove element from dynamic array
int removeElement(DynamicArray *dyn_array, int index) {
    if (pthread_mutex_lock(&dyn_array->lock) != 0 || index < 0 || index >= dyn_array->size) {
        pthread_mutex_unlock(&dyn_array->lock);
        return -1;
    }

    for (size_t i = index; i < dyn_array->size - 1; ++i) {
        dyn_array->array[i] = dyn_array->array[i + 1];
    }
    --dyn_array->size;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

// Update element in dynamic array
void updateElement(DynamicArray *dyn_array, int index, NFAPI_RRC_MESSAGE_T element) {
    if (pthread_mutex_lock(&dyn_array->lock) != 0 || index < 0 || index >= dyn_array->size) {
        pthread_mutex_unlock(&dyn_array->lock);
        return;
    }

    dyn_array->array[index] = element;

    pthread_mutex_unlock(&dyn_array->lock);
}

// Free dynamic array
void freeDynamicArray(DynamicArray *dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_lock(&dyn_array->lock);
    for (size_t i = 0; i < dyn_array->size; ++i) {
        // Assuming message_data needs to be freed
        free(dyn_array->array[i].connection_complete.message_data);
        for (int j = 0; j < dyn_array->array[i].num_reconfig_commands; ++j) {
            free(dyn_array->array[i].reconfiguration_commands[j].message_data);
        }
        free(dyn_array->array[i].reconfiguration_complete_reason.message_data);
    }

    free(dyn_array->array);
    pthread_mutex_unlock(&dyn_array->lock);
    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array);
}

// Execute SQL query to retrieve employee details
void executeSQLQuery(int supervisor_id, const char *username, const char *password) {
    sqlite3 *db;
    sqlite3_stmt *stmt;
    const char *sql = "SELECT Name, City, Address FROM Employees WHERE SupervisorID = ?";

    if (sqlite3_open("employees.db", &db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return;
    }

