### PHP Code: `updateUserProfile` in a DAO Class

```php
class UserProfileDAO {
    private $pdo;

    public function __construct($pdo) {
        $this->pdo = $pdo;
    }

    public function updateUserProfile($userId, $name, $email, $phoneNumber) {
        if (!$this->validateName($name) || !$this->validateEmail($email) || !$this->validatePhoneNumber($phoneNumber)) {
            throw new InvalidArgumentException("Invalid input data.");
        }

        try {
            $this->pdo->beginTransaction();

            // Check for duplicate email
            $stmt = $this->pdo->prepare("SELECT COUNT(*) FROM users WHERE email = ? AND id != ?");
            $stmt->execute([$email, $userId]);
            if ($stmt->fetchColumn() > 0) {
                throw new RuntimeException("Email already exists.");
            }

            // Update user profile
            $stmt = $this->pdo->prepare("UPDATE users SET name = ?, email = ?, phone_number = ? WHERE id = ?");
            $stmt->execute([$name, $email, $phoneNumber, $userId]);

            $this->pdo->commit();
        } catch (Exception $e) {
            $this->pdo->rollBack();
            throw new RuntimeException("Failed to update user profile: " . $e->getMessage());
        }
    }

    private function validateName($name) {
        return ctype_alnum(str_replace(' ', '', $name));
    }

    private function validateEmail($email) {
        return filter_var($email, FILTER_VALIDATE_EMAIL);
    }

    private function validatePhoneNumber($phoneNumber) {
        // Example validation for US phone numbers
        return preg_match('/^\+1[2-9]\d{2}[2-9](?!11)\d{6}$/', $phoneNumber);
    }
}
```

