typedef struct {
    char uei[20];
    int servingCellIdentity;
    float measurements[10]; // Assuming there are 10 measurement types
} UE;

typedef struct {
    pthread_mutex_t lock;
    UE *ue_list;
    size_t count;
    size_t capacity;
    int success_count;
    int failure_count;
} UEManager;

void log_warning(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void* load_ues_from_xml(void* arg) {
    UEManager *manager = (UEManager*)arg;
    xmlDocPtr doc;
    xmlNodePtr root, cur;

    // Load XML
    doc = xmlReadFile("config.xml", NULL, 0);
    if (doc == NULL) {
        log_error("Failed to parse XML file.");
        return NULL;
    }

    root = xmlDocGetRootElement(doc);

    pthread_mutex_lock(&manager->lock);

    for (cur = root->children; cur != NULL; cur = cur->next) {
        if (xmlStrcmp(cur->name, (const xmlChar *)"UE") == 0) {
            UE ue;
            memset(&ue, 0, sizeof(UE));
            xmlAttr *attr;

            // Parse attributes
            for (attr = cur->properties; attr != NULL; attr = attr->next) {
                if (xmlStrcmp(attr->name, (const xmlChar *)"uei") == 0) {
                    strncpy(ue.uei, (char *)xmlNodeListGetString(doc, attr->children, 1), sizeof(ue.uei));
                } else if (xmlStrcmp(attr->name, (const xmlChar *)"servingCellIdentity") == 0) {
                    ue.servingCellIdentity = atoi((char *)xmlNodeListGetString(doc, attr->children, 1));
                }
            }

            // Assume measurements are stored in child nodes
            for (cur = cur->children; cur != NULL; cur = cur->next) {
                if (xmlStrcmp(cur->name, (const xmlChar *)"measurement") == 0) {
                    int index;
                    float value;

                    if (cur->properties != NULL) {
                        xmlAttr *attr = cur->properties;
                        while (attr != NULL) {
                            if (xmlStrcmp(attr->name, (const xmlChar *)"index") == 0) {
                                index = atoi((char *)xmlNodeListGetString(doc, attr->children, 1));
                            } else if (xmlStrcmp(attr->name, (const xmlChar *)"value") == 0) {
                                value = atof((char *)xmlNodeListGetString(doc, attr->children, 1));
                            }
                            attr = attr->next;
                        }

                        if (index >= 0 && index < 10) {
                            ue.measurements[index] = value;
                        } else {
                            log_warning("Measurement index out of bounds.");
                        }
                    }
                }
            }

            // Ensure capacity
            if (manager->count == manager->capacity) {
                manager->capacity *= 2;
                manager->ue_list = realloc(manager->ue_list, manager->capacity * sizeof(UE));
                if (!manager->ue_list) {
                    log_error("Failed to reallocate memory for UE list.");
                    pthread_mutex_unlock(&manager->lock);
                    return NULL;
                }
            }

            // Add UE to list
            memcpy(&manager->ue_list[manager->count], &ue, sizeof(UE));
            manager->count++;
            manager->success_count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    xmlFreeDoc(doc);

    return NULL;
}

void export_ue_data_to_json(const char *output_dir) {
    json_t *root = json_array();
    if (!root) {
        log_error("Failed to create JSON root array.");
        return;
    }

    pthread_mutex_lock(&manager.lock);
    for (size_t i = 0; i < manager.count; ++i) {
        json_t *ue_obj = json_object();

        json_object_set_new(ue_obj, "uei", json_string(manager.ue_list[i].uei));
        json_object_set_new(ue_obj, "servingCellIdentity", json_integer(manager.ue_list[i].servingCellIdentity));

        json_t *measurements_array = json_array();
        for (int j = 0; j < 10; ++j) {
            if (manager.ue_list[i].measurements[j] != 0) { // Assuming 0 as a default or missing value
                json_array_append_new(measurements_array, json_real(manager.ue_list[i].measurements[j]));
            }
        }

        json_object_set_new(ue_obj, "measurements", measurements_array);
        json_array_append_new(root, ue_obj);
    }
    pthread_mutex_unlock(&manager.lock);

    // Write JSON to file
    char output_path[256];
    snprintf(output_path, sizeof(output_path), "%s/ue_data.json", output_dir);

    FILE *file = fopen(output_path, "w");
    if (!file) {
        log_error("Failed to open output file.");
        json_decref(root);
        return;
    }

    char *json_str = json_dumps(root, JSON_INDENT(4));
    if (!json_str) {
        fclose(file);
        log_error("JSON serialization failed.");
        json_decref(root);
        return;
    }

    fwrite(json_str, 1, strlen(json_str), file);
    free(json_str);
    fclose(file);

    json_decref(root);
}

int manage_ue_list() {
    UEManager manager = { .lock = PTHREAD_MUTEX_INITIALIZER, .ue_list = NULL, .count = 0, .capacity = 10,
                          .success_count = 0, .failure_count = 0 };

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, load_ues_from_xml, &manager) != 0) {
        log_error("Failed to create thread for XML loading.");
        return 1;
    }

    pthread_join(thread_id, NULL);

    export_ue_data_to_json("./output");

    free(manager.ue_list);
    printf("Successful operations: %d\n", manager.success_count);
    printf("Failed operations: %d\n", manager.failure_count);

    return (manager.failure_count > 0) ? 1 : 0;
}

int main() {
    int result = manage_ue_list();
    if (result != 0) {
        log_error("Critical error occurred during UE management.");
    }
    return result;
}
