#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TOTAL_MEMORY_USAGE 1000000 // Example threshold for total memory usage
#define MAX_BUFFER_MEMORY_USAGE 500000 // Example maximum for buffer allocation
#define INT_VALUE_RANGE_MIN 1
#define INT_VALUE_RANGE_MAX 100
#define TOTAL_INT_SUM_LIMIT 10000

typedef struct {
    int value;
    char *buffer;
} Record;

typedef struct {
    long *offsets;
    size_t offset_count;
    int *keys;
    size_t key_count;
    Record *records;
    size_t record_count;
    pthread_mutex_t lock; // For thread-safe operations
} MemoryManager;

// Function to initialize memory for offsets and keys with over-allocation
void init_memory(MemoryManager *manager, size_t offset_size, size_t key_size) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->offset_count = offset_size;
    manager->keys_count = key_size;

    // Over-allocate to accommodate dynamic resizing
    manager->offsets = (long *)malloc(manager->offset_count * sizeof(long) * 1.5);
    if (!manager->offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    manager->keys = (int *)malloc(manager->key_count * sizeof(int) * 1.5);
    if (!manager->keys) {
        free(manager->offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    memset(manager->offsets, 0, manager->offset_count * sizeof(long));
    memset(manager->keys, 0, manager->key_count * sizeof(int));
}

// Function to allocate and initialize records with constraints
void init_records(MemoryManager *manager, size_t record_size) {
    // Calculate memory for records considering future growth
    size_t estimated_record_memory = record_size * sizeof(Record);
    if (estimated_record_memory > MAX_TOTAL_MEMORY_USAGE / 2) {
        fprintf(stderr, "Memory usage exceeds limits\n");
        exit(EXIT_FAILURE);
    }

    manager->record_count = record_size;
    manager->records = (Record *)malloc(manager->record_count * sizeof(Record));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Populate records with random values and initialize buffers
    int total_sum = 0, buffer_memory_usage = 0;
    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < manager->record_count && total_sum <= TOTAL_INT_SUM_LIMIT; ++i) {
        int value = rand() % (INT_VALUE_RANGE_MAX - INT_VALUE_RANGE_MIN + 1) + INT_VALUE_RANGE_MIN;
        if (total_sum + value > TOTAL_INT_SUM_LIMIT) break;

        // Allocate buffer based on the key size
        int key_size = manager->keys[i % manager->key_count];
        char *buffer = (char *)malloc(key_size);
        if (!buffer) {
            perror("Failed to allocate buffer memory");
            exit(EXIT_FAILURE);
        }

        manager->records[i].value = value;
        manager->records[i].buffer = buffer;

        total_sum += value;
        buffer_memory_usage += key_size;

        if (buffer_memory_usage > MAX_BUFFER_MEMORY_USAGE) {
            fprintf(stderr, "Buffer memory usage exceeds limits\n");
            exit(EXIT_FAILURE);
        }
    }

    // Monitor and log the current state
    printf("Total allocated memory for records: %zu bytes\n", manager->record_count * sizeof(Record));
    printf("Total buffer memory used: %d bytes\n", buffer_memory_usage);
}

// Function to clean up resources
void cleanup(MemoryManager *manager) {
    pthread_mutex_destroy(&manager->lock);

    free(manager->offsets);
    free(manager->keys);

    for (size_t i = 0; i < manager->record_count; ++i) {
        if (manager->records[i].buffer) {
            free(manager->records[i].buffer);
        }
    }

    free(manager->records);
}

// Example unit test function
void run_unit_tests() {
    MemoryManager manager;
    init_memory(&manager, 1000, 500);
    init_records(&manager, 200);

    // Add more tests for validation here

    cleanup(&manager);
}

int main() {
    run_unit_tests();
    return 0;
}
