#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
    // Add more fields as necessary for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int compare_rnti(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T *)a)->rnti - ((NFAPI_CRC_INDICATION_PDU_T *)b)->rnti;
}

unsigned int generate_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

int add_element(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size) {
    if (*size >= MAX_ELEMENTS) {
        fprintf(stderr, "Error: Reached maximum capacity.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, ((*size) + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    new_array[*size].rnti = rand() % (UINT_MAX); // Simulate RNTI assignment
    while (binary_search(*array, *size, &new_array[*size])) { // Check for duplicates
        new_array[*size].rnti = rand() % (UINT_MAX);
    }

    new_array[*size].ue_info_tag.RNTI = new_array[*size].rnti;
    new_array[*size].crc_indication_rel8_tag.CRCFLAG = generate_random_crcflag();

    qsort(new_array, (*size) + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    *array = new_array;
    (*size)++;
    return 0;
}

int binary_search(NFAPI_CRC_INDICATION_PDU_T *array, size_t size, NFAPI_CRC_INDICATION_PDU_T *target) {
    int left = 0;
    int right = (int)size - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (array[mid].rnti == target->rnti)
            return 1; // Found duplicate
        else if (array[mid].rnti < target->rnti)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return 0; // No duplicate found
}

int main() {
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t size = 0;

    for (size_t i = 0; i < MAX_ELEMENTS; i++) {
        if (add_element(&array, &size) != 0) break;
    }

    printf("Successfully added %zu elements.\n", size);

    free(array);
    return 0;
}
