    pthread_cond_t not_full;
} NFAPIListManager;

void init_list_manager(NFAPIListManager *manager) {
    manager->size = 0;
    manager->capacity = INITIAL_SIZE;
    manager->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->capacity);
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->not_full, NULL);
}

void destroy_list_manager(NFAPIListManager *manager) {
    free(manager->list);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->not_full);
}

int resize_list_if_needed(NFAPIListManager *manager) {
    if (manager->size >= manager->capacity && manager->capacity < MAX_SIZE) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(manager->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_list == NULL) {
            perror("Failed to resize list");
            return -1;
        }
        manager->list = new_list;
        manager->capacity = new_capacity;
    }
    return 0;
}

void log_error(const char *message, size_t current_size) {
    time_t now = time(NULL);
    printf("[%s] ERROR: %s. Current list size: %zu\n", ctime(&now), message, current_size);
}

int insert_pdu(NFAPIListManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    if (resize_list_if_needed(manager) != 0) {
        log_error("Memory allocation failed", manager->size);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (manager->size >= manager->capacity) {
        pthread_cond_wait(&manager->not_full, &manager->lock);
        if (resize_list_if_needed(manager) != 0) {
            log_error("Memory allocation failed after waiting", manager->size);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->list[manager->size] = pdu;
    manager->size++;

    pthread_cond_signal(&manager->not_full);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

