            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }

        manager->size = 0; // Reset list size after processing

        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

int main() {
    NFAPIListManager manager;
    init_list_manager(&manager);

    pthread_t producer, consumer;

    if (pthread_create(&producer, NULL, producer_thread, &manager) != 0) {
        perror("Failed to create producer thread");
        exit(1);
    }

    if (pthread_create(&consumer, NULL, consumer_thread, &manager) != 0) {
        perror("Failed to create consumer thread");
        pthread_cancel(producer);
        exit(1);
    }

    pthread_join(producer, NULL);
    pthread_join(consumer, NULL);

