#include <pthread.h>

#define MAX_ELEMENTS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMENTS];
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray* dyn_array) {
    pthread_mutex_init(&dyn_array->mutex, NULL);
}

int add_element(DynamicArray* dyn_array, int rx_ue_info_tag, int rnti, int crc_ind_rel8_tag) {
    pthread_mutex_lock(&dyn_array->mutex);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (dyn_array->array[i] == NULL) {
            NFAPI_CRC_INDICATION_PDU_T* new_elem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_elem) {
                pthread_mutex_unlock(&dyn_array->mutex);
                return -1; // Memory allocation failure
            }

            for (int j = 0; j < MAX_ELEMENTS; ++j) {
                if (dyn_array->array[j] != NULL && dyn_array->array[j]->RNTI == rnti) {
                    free(new_elem);
                    pthread_mutex_unlock(&dyn_array->mutex);
                    return -2; // RNTI already exists
                }
            }

            new_elem->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
            new_elem->RNTI = rnti;
            new_elem->CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
            dyn_array->array[i] = new_elem;

            pthread_mutex_unlock(&dyn_array->mutex);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&dyn_array->mutex);
    return -3; // Array is full
}

void reset_dynamic_array(DynamicArray* dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (dyn_array->array[i] != NULL) {
            free(dyn_array->array[i]);
            dyn_array->array[i] = NULL;
        }
    }

    pthread_mutex_unlock(&dyn_array->mutex);
}

void destroy_dynamic_array(DynamicArray* dyn_array) {
    reset_dynamic_array(dyn_array);
    pthread_mutex_destroy(&dyn_array->mutex);
}

// Example usage
int main() {
    DynamicArray dyn_array;
    init_dynamic_array(&dyn_array);

    int result = add_element(&dyn_array, 1, 101, 5);
    if (result == 0) {
        printf("Element added successfully.\n");
    } else {
        printf("Failed to add element. Error code: %d\n", result);
    }

    reset_dynamic_array(&dyn_array);
    destroy_dynamic_array(&dyn_array);

    return 0;
}
