#define INITIAL_CAPACITY 10
#define MAX_SESSIONS 1000

typedef struct {
    int SessionID;
    char ClientIP[16];
    char ServerIP[16];
    unsigned long BytesTransferred;
} NetworkSession;

typedef struct {
    NetworkSession *sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    unsigned long bandwidthLimit;
    unsigned long totalBytesTransferred;
} SessionManager;

unsigned int hash_function(int sessionID) {
    return sessionID % 101; // Simple modulus-based hash
}

int check_duplicate(SessionManager *manager, int sessionID) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].SessionID == sessionID)
            return 1;
    }
    return 0;
}

void resize_array(SessionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NetworkSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(NetworkSession));
    if (new_sessions) {
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    } else {
        perror("Failed to resize session array");
        exit(EXIT_FAILURE);
    }
}

void purge_old_sessions(SessionManager *manager) {
    // Implement a simple time-based purging strategy
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->size; ++i) {
        if (difftime(current_time, manager->sessions[i].timestamp) > 3600) { // Purge sessions older than an hour
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->size - i - 1) * sizeof(NetworkSession));
            --manager->size;
        }
    }
}

void log_failure(const char *message) {
    printf("LOG: %s\n", message);
}

void add_session(SessionManager *manager, int sessionID, const char *clientIP, const char *serverIP, unsigned long bytesTransferred) {
    pthread_mutex_lock(&manager->mutex);

    if (check_duplicate(manager, sessionID)) {
        log_failure("Duplicate SessionID detected");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    if (manager->totalBytesTransferred + bytesTransferred > manager->bandwidthLimit) {
        log_failure("Bandwidth limit exceeded");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    if (manager->size >= manager->capacity) {
        resize_array(manager);
    }

    NetworkSession *session = &manager->sessions[manager->size++];
    session->SessionID = sessionID;
    strncpy(session->ClientIP, clientIP, sizeof(session->ClientIP));
    strncpy(session->ServerIP, serverIP, sizeof(session->ServerIP));
    session->BytesTransferred = bytesTransferred;
    manager->totalBytesTransferred += bytesTransferred;

    pthread_mutex_unlock(&manager->mutex);
}

void initialize_manager(SessionManager *manager, unsigned long bandwidthLimit) {
    manager->sessions = malloc(INITIAL_CAPACITY * sizeof(NetworkSession));
    if (!manager->sessions) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->bandwidthLimit = bandwidthLimit;
    manager->totalBytesTransferred = 0;
}

void cleanup_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->mutex);
}

int main() {
    SessionManager manager;
    initialize_manager(&manager, 10000000); // Set a bandwidth limit

    // Simulate adding sessions
    for (int i = 0; i < 50; ++i) {
        char clientIP[16] = "192.168.1.";
        sprintf(clientIP + 9, "%d", rand() % 255);
        add_session(&manager, rand(), clientIP, "10.0.0.1", rand() % 1000);
    }

    // Periodically purge old sessions
    purge_old_sessions(&manager);

    cleanup_manager(&manager);
    return 0;
}
```

