    LTE_PHY_Metric *newMetrics = realloc(array->metrics, newCapacity * sizeof(LTE_PHY_Metric));
    if (!newMetrics) return -1;

    array->metrics = newMetrics;
    array->capacity = newCapacity;

    return 0;
}

