    free(array);
}

int addMetric(MetricArray *array, int frameNumber, double timestamp, int rssi[MAX_ANTENNAS]) {
    if (array->count == array->capacity) {
        if (resizeMetricArray(array, array->capacity * 2) != 0)
            return -1;
    }

    LTE_PHY_Metric newMetric = {frameNumber, timestamp};
    for (int i = 0; i < MAX_ANTENNAS; ++i) {
        newMetric.rssi[i] = rssi[i];
    }

    if (array->count > 0 && isDuplicate(&array->metrics[array->count - 1], &newMetric)) {
        // Handle duplicate entry, e.g., log or ignore
        return -2;
    }

    array->metrics[array->count++] = newMetric;

    return 0;
}

static int isDuplicate(LTE_PHY_Metric *lastMetric, LTE_PHY_Metric *currentMetric) {
    if (abs(lastMetric->frameNumber - currentMetric->frameNumber) <= RSSI_THRESHOLD_DIFFERENCE) {
        for (int i = 0; i < MAX_ANTENNAS; ++i) {
            if (abs(lastMetric->rssi[i] - currentMetric->rssi[i]) > RSSI_THRESHOLD_DIFFERENCE)
                return 0;
        }
        return 1;
    }

    return 0;
}

