    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_records = realloc(list->records, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->records = new_records;
    void **new_index_map = realloc(list->index_map, new_capacity * sizeof(void *));
    if (!new_index_map) {
        free(list->records);
        fprintf(stderr, "Memory reallocation for index map failed\n");
        exit(EXIT_FAILURE);
    }
    list->index_map = new_index_map;
    memset(&list->index_map[list->capacity], 0, (new_capacity - list->capacity) * sizeof(void *));
    list->capacity = new_capacity;
}

