['Below is a C implementation of a dynamic array for `NFAPI_CRC_INDICATION_PDU_T` structures with thread-safe operations and bounds checking:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    // Define the structure fields as needed
    int example_field;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *dyn_array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->size = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);
    memset(dyn_array->array, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_ELEMENTS);

    return dyn_array;
}

int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&dyn_array->lock);
        fprintf(stderr, "Error: Array is full.\n");
        return -1;
    }

    dyn_array->array[dyn_array->size++] = element;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

int remove_element(DynamicArray *dyn_array, size_t index) {
    pthread_mutex_lock(&dyn_array->lock);

    if (index >= dyn_array->size) {
        pthread_mutex_unlock(&dyn_array->lock);
        fprintf(stderr, "Error: Index out of bounds.\n");
        return -1;
    }

    free(dyn_array->array[index]);
    memmove(&dyn_array->array[index], &dyn_array->array[index + 1],
            (dyn_array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    dyn_array->size--;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < dyn_array->size; ++i) {
        free(dyn_array->array[i]);
    }

    pthread_mutex_unlock(&dyn_array->lock);
    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array);
}

int main() {
    DynamicArray *dyn_array = create_dynamic_array();
    if (!dyn_array) return -1;

    // Example usage
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_element->example_field = i;
        if (add_element(dyn_array, new_element) != 0) {
            free(new_element);
        }
    }

    // Clean up
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        remove_element(dyn_array, i);
    }

    free_dynamic_array(dyn_array);

    return 0;
}
