#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_POOL_SIZE 1024

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint8_t additional_data[128]; // Example placeholder
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t element_size;
    void* memory_pool;
    unsigned int free_count;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t element_size, size_t total_elements) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->element_size = element_size;
    pool->memory_pool = malloc(element_size * total_elements);
    if (!pool->memory_pool) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pool->free_count = total_elements;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->free_count > 0) {
        void* element_ptr = pool->memory_pool + (--pool->free_count) * pool->element_size;
        pthread_mutex_unlock(&pool->lock);
        return element_ptr;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL; // Out of memory
}

void deallocate_to_pool(MemoryPool* pool, void* ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&pool->lock);

    unsigned int index = ((char*)ptr - (char*)pool->memory_pool) / pool->element_size;
    ((uint8_t*)pool->memory_pool)[index * pool->element_size] = 1; // Mark as free
    pool->free_count++;

    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_papi_crc_indication_pdu_list(size_t count, MemoryPool* memory_pool) {
    if (count > MAX_POOL_SIZE) {
        fprintf(stderr, "Requested number exceeds maximum pool size\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * count);
    if (!pdu_list) {
        perror("Failed to allocate list");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(memory_pool);
        if (!pdu) {
            fprintf(stderr, "Failed to allocate memory from pool for element %zu\n", i);
            while (--i >= 0) { // Free previously allocated elements
                deallocate_to_pool(memory_pool, pdu_list[i]);
            }
            free(pdu_list);
            return NULL;
        }

        // Simulate data population
        pdu->ue_info_tag.RNTI = rand() % 65536; // Random RNTI example
        pdu->ue_info_tag.crc_indication_rel8_tag.CRCFLAG = rand() & 0x1; // Random CRCFLAG

        pdu_list[i] = *pdu;
    }

    return pdu_list;
}

int main() {
    srand(time(NULL));

    MemoryPool pool;
    init_memory_pool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_POOL_SIZE);

    size_t count = 10; // Example count
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_nfa_papi_crc_indication_pdu_list(count, &pool);

    if (pdu_list) {
        for (size_t i = 0; i < count; ++i) {
            printf("RNTI: %u, CRCFLAG: %u\n", 
                   pdu_list[i].ue_info_tag.RNTI,
                   pdu_list[i].ue_info_tag.crc_indication_rel8_tag.CRCFLAG);
        }

        for (size_t i = 0; i < count; ++i) {
            deallocate_to_pool(&pool, &pdu_list[i]);
        }

        free(pdu_list);
    }

    destroy_memory_pool(&pool);

    return 0;
}
