            interfaces[i].ports[j].port = (int)json_integer_value(json_object_get(json_port, "port"));

            const char *traffic_type = json_string_value(json_object_get(json_port, "traffic_type"));
            strncpy(interfaces[i].ports[j].traffic_type, traffic_type, sizeof(interfaces[i].ports[j].traffic_type));
        }

        // Extract other fields similarly
        interfaces[i].interface_name[0] = '\0';
        strcpy(interfaces[i].interface_name,
               json_string_value(json_object_get(root, "interface_name")));

        strcpy(interfaces[i].ip_address,
               json_string_value(json_object_get(root, "ip_address")));

        strcpy(interfaces[i].subnet_mask,
               json_string_value(json_object_get(root, "subnet_mask")));

        strcpy(interfaces[i].gateway_address,
               json_string_value(json_object_get(root, "gateway_address")));

        json_decref(root);
        pthread_mutex_unlock(&lock);
    }

    // Serialize and deserialize example (omitted for brevity)

