#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int frameNumber;
    time_t timestamp;
    float rssi[4];  // Assuming 4 antennas for simplicity
} LTE_PHY_Metric;

typedef struct {
    LTE_PHY_Metric *metrics;
    size_t capacity;
    size_t size;
} LTE_PHY_Array;

void initLTE_PHY_Array(LTE_PHY_Array *array, size_t initialSize) {
    array->capacity = initialSize;
    array->size = 0;
    array->metrics = (LTE_PHY_Metric *)malloc(initialSize * sizeof(LTE_PHY_Metric));
    if (!array->metrics) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

void resizeLTE_PHY_Array(LTE_PHY_Array *array, size_t newSize) {
    LTE_PHY_Metric *newMetrics = (LTE_PHY_Metric *)realloc(array->metrics, newSize * sizeof(LTE_PHY_Metric));
    if (!newMetrics) {
        perror("Failed to reallocate memory");
        free(array->metrics);
        exit(EXIT_FAILURE);
    }
    array->capacity = newSize;
    array->metrics = newMetrics;
}

void addMetric(LTE_PHY_Array *array, int frameNumber, time_t timestamp, float rssi[4]) {
    if (array->size >= array->capacity) {
        resizeLTE_PHY_Array(array, array->capacity * 2);
    }

    LTE_PHY_Metric lastValid = {0};
    if (array->size > 0) {
        lastValid = array->metrics[array->size - 1];
    }

    // Check for duplicate based on RSSI threshold
    float rssiThreshold = 0.5;  // Example threshold value
    int isDuplicate = 0;
    if (array->size > 0) {
        for (int i = 0; i < 4; ++i) {
            if (fabs(rssi[i] - lastValid.rssi[i]) <= rssiThreshold) {
                isDuplicate = 1;
                break;
            }
        }
    }

    if (!isDuplicate || timestamp != lastValid.timestamp) { // Handle disconnection
        array->metrics[array->size].frameNumber = frameNumber;
        array->metrics[array->size].timestamp = timestamp;
        memcpy(array->metrics[array->size].rssi, rssi, sizeof(float) * 4);
        ++array->size;
    }
}

void handleDisconnection(LTE_PHY_Array *array) {
    if (array->size > 0) {
        // Preserving last valid data point
        printf("Handling disconnection: preserving frame %d at timestamp %ld\n",
               array->metrics[array->size - 1].frameNumber,
               array->metrics[array->size - 1].timestamp);
    }
}

void freeLTE_PHY_Array(LTE_PHY_Array *array) {
    free(array->metrics);
    array->metrics = NULL;
    array->capacity = 0;
    array->size = 0;
}

int main() {
    LTE_PHY_Array metricsArray;
    initLTE_PHY_Array(&metricsArray, 10);

    int frameNumber = 1;
    time_t timestamp = time(NULL);
    float rssi[4] = { -70.0, -75.0, -72.5, -71.0 };

    addMetric(&metricsArray, frameNumber++, timestamp, rssi);

    // Simulate intermittent disconnection
    handleDisconnection(&metricsArray);

    // Add more metrics as needed

    freeLTE_PHY_Array(&metricsArray);
    return 0;
}
