// Initialize the NICP list based on current network conditions
void initialize_nicp_list(int initial_count) {
    pthread_mutex_lock(&nicp_list_lock);

    for (int i = 0; i < initial_count; ++i) {
        NICP* new_node = (NICP*)malloc(sizeof(NICP));
        if (!new_node) {
            perror("Failed to allocate memory for NICP");
            exit(EXIT_FAILURE);
