            new_node->MAC_ADDRESS[j] = rand() % 256;

        new_node->VLAN_ID = rand() % 4096;
        new_node->VLAN_PRIORITY = rand() % 8;
        new_node->NICP_STATUS_FLAG = 1; // Initially active
        new_node->next = nicp_list_head;
        nicp_list_head = new_node;
    }

    pthread_mutex_unlock(&nicp_list_lock);
}

// Function to adjust NICP statuses based on load conditions
void adjust_nicp_statuses() {
    int current_load = get_current_network_load();
    pthread_mutex_lock(&nicp_list_lock);

    NICP* node = nicp_list_head;
    while (node) {
        if (current_load > 80) { // High load threshold
            node->NICP_STATUS_FLAG = 0; // Deactivate under high load
        } else {
            node->NICP_STATUS_FLAG = 1; // Activate otherwise
        }
        node = node->next;
    }

    pthread_mutex_unlock(&nicp_list_lock);
}

// Graceful shutdown function to free resources
void shutdown_nicp_manager() {
    pthread_mutex_lock(&nicp_list_lock);

    NICP* current = nicp_list_head;
    while (current) {
        NICP* next_node = current->next;
        free(current);
        current = next_node;
    }

    nicp_list_head = NULL;
    pthread_mutex_unlock(&nicp_list_lock);
}

int main() {
    initialize_nicp_list(10); // Start with 10 NICP configurations
    adjust_nicp_statuses();   // Adjust statuses based on simulated load

    shutdown_nicp_manager();  // Clean up resources before exiting
    return 0;
}
