#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 1000
#define ERROR_INSUFFICIENT_MEMORY -1
#define ERROR_INVALID_INPUT -2
#define ERROR_OVERFLOW -3

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRC_Indication_Manager;

static int generate_random_crcflag() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

int crc_indication_manager_init(CRC_Indication_Manager* manager) {
    if (!manager) return ERROR_INVALID_INPUT;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) return ERROR_INSUFFICIENT_MEMORY;

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    srand((unsigned int)time(NULL)); // Seed the random number generator

    return 0;
}

int crc_indication_manager_add(CRC_Indication_Manager* manager, uint32_t rx_ue_tag, uint16_t rnti) {
    if (!manager || manager->size >= (size_t)manager->capacity) return ERROR_OVERFLOW;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return ERROR_INVALID_INPUT;
        }
    }

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return ERROR_INSUFFICIENT_MEMORY;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &manager->array[manager->size++];
    element->RX_UE_INFORMATION_TAG = rx_ue_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int crc_indication_manager_free(CRC_Indication_Manager* manager) {
    if (!manager) return ERROR_INVALID_INPUT;

    pthread_mutex_lock(&manager->lock);

    free(manager->array);
    manager->array = NULL;
    manager->capacity = 0;
    manager->size = 0;

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    return 0;
}

// Example usage
int main() {
    CRC_Indication_Manager manager;
    if (crc_indication_manager_init(&manager) != 0) {
        fprintf(stderr, "Failed to initialize manager\n");
        return 1;
    }

    for (uint16_t i = 1; i <= 10000; ++i) {
        int result = crc_indication_manager_add(&manager, rand(), i);
        if (result == ERROR_INSUFFICIENT_MEMORY || result == ERROR_OVERFLOW) {
            fprintf(stderr, "Failed to add element: %d\n", result);
            break;
        }
    }

    crc_indication_manager_free(&manager);

    return 0;
}
