    pthread_mutex_unlock(&lock);
}

// Function to delete a specific resource via HTTP DELETE method simulation
void http_delete_resource(int index) {
    pthread_mutex_lock(&lock);

    if (index < 0 || index >= resource_count) {
        fprintf(stderr, "Invalid index.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Replace with default values
    memset(&resources[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = index; i < resource_count - 1; ++i) {
        resources[i] = resources[i + 1];
    }
    resource_count--;

    pthread_mutex_unlock(&lock);
}

// Function to integrate with an external data source and handle failures
void fetch_external_data(int *data) {
    int retries = 0;
    while (retries < 5) {
        // Simulate network call
        int success = rand() % 2;

        if (success) {
            *data = rand() % 100; // Fetch data successfully
            return;
        }

        usleep((1 << retries) * 1000);
        retries++;
    }

    // Fallback to local cache or heuristic approximation
    *data = -1; // Indicate fallback usage
}

int main() {
    init_resources(10);

    http_put_update(2, 123, 456, 789);
    http_delete_resource(5);

    int external_data;
    fetch_external_data(&external_data);
    printf("External data: %d\n", external_data);

    return 0;
}
```

### Key Points:
- **Initialization and Population**: The `init_resources` function populates the structures with random values, considering memory limits.
- **Resource Updates**: `http_put_update` simulates an HTTP PUT request with retry logic for robustness.
- **Resource Deletion**: `http_delete_resource` ensures deleted resources are replaced with default values to maintain consistency.
- **Dependency Management**: `fetch_external_data` implements a retry mechanism and fallback strategy.
- **Concurrency Control**: Mutex locks ensure thread-safe operations, crucial for concurrent access.
- **Scalability and Maintainability**: The code is structured modularly to accommodate future growth and changes.']

