['Below is a C code implementation of a thread-safe semaphore that supports dynamic initial values, reinitialization, and detailed diagnostics. It integrates with a logging framework and uses pthreads for concurrency management.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int value;
    int initialized;
    int successful_acquisitions;
} CustomSemaphore;

// Initialize the semaphore with a given initial value
int custom_semaphore_init(CustomSemaphore *sem, int init_value) {
    if (pthread_mutex_init(&sem->mutex, NULL) != 0 ||
        pthread_cond_init(&sem->cond, NULL) != 0) {
        return -1;
    }

    sem->value = init_value;
    sem->initialized = 1;
    sem->successful_acquisitions = 0;

    return 0;
}

// Destroy the semaphore
void custom_semaphore_destroy(CustomSemaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->initialized) {
        sem->initialized = 0;
        pthread_cond_broadcast(&sem->cond); // Release any waiting threads
    }
    pthread_mutex_unlock(&sem->mutex);

    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

// Reinitialize the semaphore with a new value
int custom_semaphore_reinit(CustomSemaphore *sem, int new_value) {
    if (!sem->initialized) return -1;

    pthread_mutex_lock(&sem->mutex);
    sem->value = new_value;
    pthread_mutex_unlock(&sem->mutex);

    return 0;
}

// Acquire the semaphore
int custom_semaphore_wait(CustomSemaphore *sem) {
    pthread_mutex_lock(&sem->mutex);

    while (sem->value <= 0) {
        if (!sem->initialized) {
            pthread_mutex_unlock(&sem->mutex);
            return -1; // Semaphore not initialized
        }
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }

    sem->value--;
    sem->successful_acquisitions++;

    pthread_mutex_unlock(&sem->mutex);

    return 0;
}

// Release the semaphore
void custom_semaphore_signal(CustomSemaphore *sem) {
    pthread_mutex_lock(&sem->mutex);

    if (sem->initialized) {
        sem->value++;
        pthread_cond_broadcast(&sem->cond);
    }

    pthread_mutex_unlock(&sem->mutex);
}

// Retrieve diagnostic information
const char* custom_semaphore_diagnostics(const CustomSemaphore *sem) {
    static char report[256];

    pthread_mutex_lock((pthread_mutex_t*)&sem->mutex);
    snprintf(report, sizeof(report), 
             "Initialized: %d, Current Value: %d, Successful Acquisitions: %d",
             sem->initialized, sem->value, sem->successful_acquisitions);
    pthread_mutex_unlock((pthread_mutex_t*)&sem->mutex);

    return report;
}

// Example logging function (integrate with your logging framework)
void log_message(const char *message) {
    // Replace this with actual logging implementation
    printf("%s\n", message);
}

int main() {
    CustomSemaphore sem;

    if (custom_semaphore_init(&sem, 5) != 0) {
        log_message("Failed to initialize semaphore");
        return EXIT_FAILURE;
    }

    // Example usage: spawn threads to acquire and release the semaphore
    // Ensure proper error handling in a real-world scenario

    custom_semaphore_destroy(&sem);

    return EXIT_SUCCESS;
}
```

### Key Considerations:
- **Thread Safety**: Mutexes and condition variables ensure thread-safe operations.
- **Reinitialization**: Allows dynamic adjustment of the initial value.
- **Diagnostics**: Provides detailed reports on semaphore state.
- **Logging**: Placeholder function for integration with a logging framework.
- **Modularity**: Design allows easy extension for future enhancements.

This implementation is designed to be efficient and handle high concurrency, minimizing race conditions.']

