#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Definition of data structures.
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef unsigned long RNTI;

typedef struct {
    RNTI rnti;
    int rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the collection structure.
typedef struct Collection {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} Collection;

// Initialize a new collection.
Collection* init_collection(size_t initial_capacity) {
    Collection *collection = (Collection *)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->array) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

// Add an element to the collection.
int add_element(Collection *collection, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    if (!collection || collection->size >= collection->capacity) return -1;

    pthread_mutex_lock(&collection->collection->lock);

    // Check for duplicate RNTI
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->array[i].rnti == new_pdu.rnti) {
            pthread_mutex_unlock(&collection->lock);
            return -2;
        }
    }

    // Resize array if necessary.
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(collection->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->lock);
            return -3;
        }
        collection->capacity = new_capacity;
        collection->array = new_array;
    }

    // Add the element.
    collection->array[collection->size] = new_pdu;
    ++(collection->size);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Free resources allocated for the collection.
void free_collection(Collection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->array);
        free(collection);
    }
}
