```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAMES 100

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long rnti;
    unsigned long rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    // Example frame structure
    int id;
} LTE_DL_FRAME;

typedef struct {
    int cellId;
    int frequencyBand;
    LTE_DL_FRAME frames[MAX_FRAMES];
    int frameCount;
    NFAPI_CRC_INDICATION_PDU_T crcIndicationPdus[MAX_FRAMES];
} UE_CONTEXT;

typedef struct {
    UE_CONTEXT* contexts;
    size_t size;
    size_t capacity;
    unsigned long totalFrames;
    pthread_mutex_t lock;
} LTE_MANAGEMENT_SYSTEM;

void initializeSystem(LTE_MANAGEMENT_SYSTEM* system) {
    system->contexts = NULL;
    system->size = 0;
    system->capacity = 0;
    system->totalFrames = 0;
    pthread_mutex_init(&system->lock, NULL);
}

int resizeContexts(LTE_MANAGEMENT_SYSTEM* system, size_t newCapacity) {
    UE_CONTEXT* newContexts = realloc(system->contexts, newCapacity * sizeof(UE_CONTEXT));
    if (!newContexts) return -1;

    if (newCapacity > system->capacity) {
        memset(newContexts + system->capacity, 0, (newCapacity - system->capacity) * sizeof(UE_CONTEXT));
    }
    system->contexts = newContexts;
    system->capacity = newCapacity;
    return 0;
}

int addUeContext(LTE_MANAGEMENT_SYSTEM* system, int cellId, int frequencyBand, LTE_DL_FRAME frames[], int frameCount) {
    pthread_mutex_lock(&system->lock);

    if (frameCount > MAX_FRAMES || frameCount <= 0) {
        pthread_mutex_unlock(&system->lock);
        fprintf(stderr, "Error: Frame count must be between 1 and %d\n", MAX_FRAMES);
        return -1;
    }

    if (resizeContexts(system, system->size + 1) != 0) {
        pthread_mutex_unlock(&system->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    UE_CONTEXT* context = &system->contexts[system->size++];
    context->cellId = cellId;
    context->frequencyBand = frequencyBand;
    memcpy(context->frames, frames, frameCount * sizeof(LTE_DL_FRAME));
    context->frameCount = frameCount;

    for (int i = 0; i < frameCount; ++i) {
        context->crcIndicationPdus[i].rnti = rand();
        context->crcIndicationPdus[i].rxUeInformationTag = rand();
        context->crcIndicationPdus[i].crcIndicationRel8Tag.crcFlag = rand() % 2;
    }

    system->totalFrames += frameCount;

    pthread_mutex_unlock(&system->lock);
    return 0;
}

int removeUeContext(LTE_MANAGEMENT_SYSTEM* system, int index) {
    pthread_mutex_lock(&system->lock);

    if (index < 0 || index >= system->size) {
        pthread_mutex_unlock(&system->lock);
        fprintf(stderr, "Error: Invalid context index\n");
        return -1;
    }

    system->totalFrames -= system->contexts[index].frameCount;

    memmove(&system->contexts[index], &system->contexts[index + 1],
            (system->size - index - 1) * sizeof(UE_CONTEXT));
    --system->size;

    pthread_mutex_unlock(&system->lock);
    return 0;
}

const UE_CONTEXT* getUeContext(const LTE_MANAGEMENT_SYSTEM* system, int index) {
    if (index < 0 || index >= system->size) return NULL;
    return &system->contexts[index];
}

void resetTotalFrames(LTE_MANAGEMENT_SYSTEM* system) {
    pthread_mutex_lock(&system->lock);
    system->totalFrames = 0;
    pthread_mutex_unlock(&system->lock);
}

void cleanupSystem(LTE_MANAGEMENT_SYSTEM* system) {
    free(system->contexts);
    pthread_mutex_destroy(&system->lock);
}

// Additional functions for data synchronization and caching would be implemented here.

int main() {
    LTE_MANAGEMENT_SYSTEM system;
    initializeSystem(&system);

    // Example usage
    LTE_DL_FRAME frames[10];
    memset(frames, 0, sizeof(frames)); // Initialize frames with dummy data

    addUeContext(&system, 1, 20, frames, 10);
    const UE_CONTEXT* context = getUeContext(&system, 0);

    if (context) {
        printf("UE Context Cell ID: %d\n", context->cellId);
    }

    resetTotalFrames(&system);
    removeUeContext(&system, 0);
    cleanupSystem(&system);

    return 0;
}
```

This code provides a basic implementation of the requirements. For full functionality, you would need to expand on data synchronization, caching, and error handling mechanisms as described in the task.']

['Below is a C code implementation for managing dynamically allocated arrays of LTE UE Context structures as described in the task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FRAMES 100
#define UE_CONTEXT_INIT_COUNT 10

typedef struct {
    int crcFlag;
    // Additional CRC indication fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int frequencyBand;
    int cellID;
    NFAPI_CRC_INDICATION_PDU_T *crcIndications;
    size_t crcCount;
    // Additional frame-related fields...
} LTE_DL_FRAME;

typedef struct {
    int cellID;
    int frequencyBand;
    LTE_DL_FRAME frames[MAX_FRAMES];
    size_t frameCount;
    pthread_mutex_t lock;  // For synchronization
} UE_Context;

typedef struct {
    UE_Context *contexts;
    size_t count;
    pthread_mutex_t globalLock;  // Protects access to contexts array
    unsigned long totalFrameCount;
} UE_Context_Manager;

// Function Prototypes
UE_Context_Manager* initializeManager(size_t initialCapacity);
void freeManager(UE_Context_Manager *manager);
int addOrUpdateUEContext(UE_Context_Manager *manager, int cellID, int frequencyBand);
void deleteUEContext(UE_Context_Manager *manager, int cellID);
LTE_DL_FRAME* getFrameFromUEContext(UE_Context_Manager *manager, int cellID, size_t frameIndex);
void updateFrequencyBandsAndCellIDs(UE_Context_Manager *manager, const int *frequencyBands, size_t frequencyCount, const int *cellIDs, size_t cellIDCount);
unsigned long getTotalFrameCount(const UE_Context_Manager *manager);
void resetTotalFrameCount(UE_Context_Manager *manager);

// Internal Helper Functions
static void initializeUEContext(UE_Context *ueContext, int cellID, int frequencyBand);
static void freeUEContext(UE_Context *ueContext);
static int findContextIndex(UE_Context_Manager *manager, int cellID);
static void logError(const char* message);

// Implementations

UE_Context_Manager* initializeManager(size_t initialCapacity) {
    UE_Context_Manager *manager = malloc(sizeof(UE_Context_Manager));
    if (!manager) {
        logError("Failed to allocate memory for manager");
        return NULL;
    }

    pthread_mutex_init(&manager->globalLock, NULL);
    manager->contexts = calloc(initialCapacity, sizeof(UE_Context));
    if (!manager->contexts) {
        free(manager);
        logError("Failed to allocate memory for UE contexts array");
        return NULL;
    }

    manager->count = 0;
    manager->totalFrameCount = 0;

    return manager;
}

void freeManager(UE_Context_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->globalLock);
    for (size_t i = 0; i < manager->count; ++i) {
        freeUEContext(&manager->contexts[i]);
    }
    pthread_mutex_unlock(&manager->globalLock);

    free(manager->contexts);
    pthread_mutex_destroy(&manager->globalLock);
    free(manager);
}

int addOrUpdateUEContext(UE_Context_Manager *manager, int cellID, int frequencyBand) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->globalLock);

    int index = findContextIndex(manager, cellID);

    if (index == -1) {  // Context not found
        if (manager->count >= UE_CONTEXT_INIT_COUNT) {
            logError("UE context array is full. Needs resizing.");
            pthread_mutex_unlock(&manager->globalLock);
            return -1;
        }

        initializeUEContext(&manager->contexts[manager->count], cellID, frequencyBand);
        index = manager->count++;
    } else {  // Update existing
        pthread_mutex_lock(&manager->contexts[index].lock);
        manager->contexts[index].frequencyBand = frequencyBand;
        pthread_mutex_unlock(&manager->contexts[index].lock);
    }

    pthread_mutex_unlock(&manager->globalLock);

    return 0;  // Success
}

void deleteUEContext(UE_Context_Manager *manager, int cellID) {
    if (!manager) return;

    pthread_mutex_lock(&manager->globalLock);

    int index = findContextIndex(manager, cellID);
    if (index != -1) {
        freeUEContext(&manager->contexts[index]);

        // Shift contexts to fill the gap
        memmove(&manager->contexts[index], &manager->contexts[index + 1],
                (manager->count - index - 1) * sizeof(UE_Context));
        manager->count--;
    }

    pthread_mutex_unlock(&manager->globalLock);
}

LTE_DL_FRAME* getFrameFromUEContext(UE_Context_Manager *manager, int cellID, size_t frameIndex) {
    if (!manager || frameIndex >= MAX_FRAMES) return NULL;

    pthread_mutex_lock(&manager->globalLock);

    int index = findContextIndex(manager, cellID);
    if (index == -1) {
        pthread_mutex_unlock(&manager->globalLock);
        return NULL;
    }

    pthread_mutex_lock(&manager->contexts[index].lock);

    LTE_DL_FRAME *frame = &manager->contexts[index].frames[frameIndex];
    pthread_mutex_unlock(&manager->contexts[index].lock);

    pthread_mutex_unlock(&manager->globalLock);

    return frame;
}

void updateFrequencyBandsAndCellIDs(UE_Context_Manager *manager, const int *frequencyBands, size_t frequencyCount, const int *cellIDs, size_t cellIDCount) {
    if (!manager) return;

    // Lock all UE contexts to ensure consistency
    pthread_mutex_lock(&manager->globalLock);

    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&manager->contexts[i].lock);

        int foundCellID = 0;
        for (size_t j = 0; j < cellIDCount && !foundCellID; ++j) {
            if (manager->contexts[i].cellID == cellIDs[j]) {
                foundCellID = 1;

                // Update frequency band
                for (size_t k = 0; k < frequencyCount; ++k) {
                    if (frequencyBands[k] != manager->contexts[i].frequencyBand) {
                        manager->contexts[i].frequencyBand = frequencyBands[k];
                    }
                }
            }
        }

        if (!foundCellID) {
            // Remove context as it's not in the updated list
            freeUEContext(&manager->contexts[i]);

            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->count - i - 1) * sizeof(UE_Context));
            manager->count--;
        }

        pthread_mutex_unlock(&manager->contexts[i].lock);
    }

    pthread_mutex_unlock(&manager->globalLock);
}

unsigned long getTotalFrameCount(const UE_Context_Manager *manager) {
    if (!manager) return 0;

    unsigned long totalFrames = 0;

    pthread_mutex_lock(&manager->globalLock);

    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&manager->contexts[i].lock);
        totalFrames += manager->contexts[i].frameCount;
        pthread_mutex_unlock(&manager->contexts[i].lock);
    }

    pthread_mutex_unlock(&manager->globalLock);

    return totalFrames;
}

void resetTotalFrameCount(UE_Context_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->globalLock);
    manager->totalFrameCount = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&manager->contexts[i].lock);
        manager->contexts[i].frameCount = 0;
        pthread_mutex_unlock(&manager->contexts[i].lock);
    }
    pthread_mutex_unlock(&manager->globalLock);
}

// Internal Helper Implementations

static void initializeUEContext(UE_Context *ueContext, int cellID, int frequencyBand) {
    ueContext->cellID = cellID;
    ueContext->frequencyBand = frequencyBand;
    memset(ueContext->frames, 0, sizeof(ueContext->frames));
    ueContext->frameCount = 0;

    pthread_mutex_init(&ueContext->lock, NULL);

    // Initialize CRC indications
    ueContext->crcIndications = malloc(MAX_FRAMES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ueContext->crcIndications) {
        logError("Failed to allocate memory for CRC indications");
    }

    for (size_t i = 0; i < MAX_FRAMES; ++i) {
        ueContext->crcIndications[i].RX_UE_INFORMATION_TAG = rand(); // Random example
        ueContext->crcIndications[i].RNTI = rand() % 65535;
        ueContext->crcIndications[i].tag.crcFlag = rand() & 1; // Random CRC flag
    }
    ueContext->crcCount = MAX_FRAMES;
}

static void freeUEContext(UE_Context *ueContext) {
    pthread_mutex_destroy(&ueContext->lock);
    if (ueContext->crcIndications) {
        free(ueContext->crcIndications);
    }
}

static int findContextIndex(UE_Context_Manager *manager, int cellID) {
    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&manager->contexts[i].lock);

        if (manager->contexts[i].cellID == cellID) {
            pthread_mutex_unlock(&manager->contexts[i].lock);
            return i;
        }

        pthread_mutex_unlock(&manager->contexts[i].lock);
    }
    return -1;  // Not found
}

static void logError(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}
```

### Key Points:
- **Thread Safety**: Each UE context has its own mutex for fine-grained locking. A global lock is used to manage access to the array of contexts.
- **Dynamic Memory Management**: Handles memory allocation and deallocation with checks to prevent leaks.
- **Graceful Error Handling**: Logs errors when memory allocation fails.
- **Modular Design**: Functions are modular, facilitating future enhancements like adding new attributes or features.

This implementation provides a foundation for managing LTE UE Contexts efficiently while ensuring thread safety, optimal memory usage, and ease of integration with other systems.']

