class RandomGenerator {
public:
    static thread_local std::mt19937 rng;
    static std::mutex mtx; // Mutex for managing global state in multi-threaded environments

    explicit RandomGenerator(unsigned long seed = 0) : seed_(seed ? seed : getCurrentTimeSeed()) {
        if (!rng.seed(seed_)) {
            throw std::runtime_error("Failed to initialize random number generator with seed.");
        }
    }

    ~RandomGenerator() {
        // Destructor for cleanup (if necessary)
    }

    int getRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx); // Ensuring thread-safe access
        std::uniform_int_distribution<int> dist(min, max);
        return dist(rng);
    }

    double getRandomDouble(double min, double max) {
        std::lock_guard<std::mutex> lock(mtx); // Ensuring thread-safe access
        std::uniform_real_distribution<double> dist(min, max);
        return dist(rng);
    }

private:
    unsigned long seed_;

    static unsigned long getCurrentTimeSeed() {
        auto now = std::chrono::system_clock::now();
        auto duration = now.time_since_epoch();
        auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(duration).count();
        return static_cast<unsigned long>(millis);
    }
};

// Initialize static members
std::mt19937 RandomGenerator::rng(RandomGenerator::getCurrentTimeSeed());
std::mutex RandomGenerator::mtx;

void createProjectDirectoryAndSetConfigPath(const std::string& projectName) {
    const char* envVar = "PROJECT_CONFIG_PATH";
    char* existingValue = std::getenv(envVar);

    if (existingValue != nullptr) {
        std::cout << "Environment variable " << envVar
                  << " is already set to: " << existingValue << "\n";
    } else {
        fs::path projectPath = "./" + projectName;
        try {
            if (!fs::exists(projectPath)) {
                fs::create_directories(projectPath);
                std::cout << "Created directory: " << projectPath << "\n";

                // Set the environment variable
                int result = setenv(envVar, projectPath.c_str(), 1);
                if (result != 0) {
                    throw std::runtime_error("Failed to set environment variable.");
                }
            } else {
                std::cout << "Directory already exists: " << projectPath << "\n";
            }

        } catch (const fs::filesystem_error& e) {
            std::cerr << "Filesystem error: " << e.what() << '\n';
        } catch (const std::exception& e) {
            std::cerr << "Exception: " << e.what() << '\n';
        }
    }
}

int main() {
    RandomGenerator rng;
    int randomInt = rng.getRandomInt(1, 100);
    double randomDouble = rng.getRandomDouble(0.0, 1.0);

    std::cout << "Random Int: " << randomInt << "\n";
