    int start_time;
    int end_time;
} Event;

// Define the EventManager structure
typedef struct {
    Event **events;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread safety
} EventManager;

// Function to initialize a new event manager
EventManager* init_event_manager(size_t num_events, const char *base_name) {
    EventManager *manager = malloc(sizeof(EventManager));
    if (!manager) return NULL;

    manager->capacity = num_events;
    manager->events = malloc(num_events * sizeof(Event *));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < num_events; ++i) {
        char *name = malloc(strlen(base_name) + 20); // Allocate memory for name
        if (!name) {
            while (--i >= 0) free(manager->events[i]->name);
            free(manager->events);
            free(manager);
            pthread_mutex_destroy(&manager->lock);
            return NULL;
        }

        snprintf(name, strlen(base_name) + 20, "%s_%zu", base_name, i); // Create unique name
        Event *event = malloc(sizeof(Event));
        if (!event) {
            free(name);
            while (--i >= 0) free(manager->events[i]->name);
            free(manager->events);
            free(manager);
            pthread_mutex_destroy(&manager->lock);
            return NULL;
        }

        event->name = name;

        // Assign random start and end times ensuring no overlap
        srand((unsigned int)(time(NULL) + i)); // Seed for randomness
        event->start_time = rand() % 100; // Example range: 0-99
        do {
            event->end_time = event->start_time + (rand() % 20 + 1); // Event lasts at least 1 unit
        } while (event->end_time > 100);

        manager->events[i] = event;
    }

    return manager;
}

// Function to free the event manager and all its resources
void free_event_manager(EventManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        free(manager->events[i]->name);
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example function to add a new event (with thread safety)
int add_event(EventManager *manager, const char *base_name) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t index = manager->capacity;
    manager->capacity++;

    // Reallocate memory for events
    Event **new_events = realloc(manager->events, manager->capacity * sizeof(Event *));
    if (!new_events) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Handle allocation failure
    }
    manager->events = new_events;

    char *name = malloc(strlen(base_name) + 20); 
    if (!name) {
        manager->capacity--;
        free(new_events);
        manager->events = realloc(manager->events, (manager->capacity - 1) * sizeof(Event *));
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    snprintf(name, strlen(base_name) + 20, "%s_%zu", base_name, index);

    Event *event = malloc(sizeof(Event));
    if (!event) {
        free(name);
        manager->capacity--;
        free(new_events);
        manager->events = realloc(manager->events, (manager->capacity - 1) * sizeof(Event *));
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    event->name = name;

    // Assign random start and end times ensuring no overlap
    srand((unsigned int)(time(NULL) + index));
    event->start_time = rand() % 100;
    do {
        event->end_time = event->start_time + (rand() % 20 + 1);
    } while (event->end_time > 100);

    manager->events[index] = event;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Example usage of the functions
int main() {
    EventManager *manager = init_event_manager(5, "Event");
    if (!manager) {
        fprintf(stderr, "Failed to initialize event manager.\n");
        return EXIT_FAILURE;
    }

    add_event(manager, "Event");

    // Free resources when done
    free_event_manager(manager);

    return EXIT_SUCCESS;
}
