    ctx->cell_id = cell_id;
    ctx->frequency_band = frequency_band;
    ctx->frame_count = 0;
    pthread_mutex_init(&ctx->lock, NULL);
}

void free_ue_context(LTE_UE_CONTEXT *ctx) {
    pthread_mutex_destroy(&ctx->lock);
}

int insert_frame(UE_CONTEXT_MANAGER *manager, int cell_id, const LTE_DL_FRAME *new_frame) {
    pthread_mutex_lock(&manager->context_lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_UE_CONTEXT *ctx = &manager->ue_contexts[i];

        if (pthread_mutex_trylock(&ctx->lock) == 0 && ctx->cell_id == cell_id) {
            if (ctx->frame_count < MAX_FRAMES_PER_UE) {
                memcpy(&ctx->frames[ctx->frame_count], new_frame, sizeof(LTE_DL_FRAME));
                ctx->frame_count++;

                NFAPI_CRC_INDICATION_PDU_T *pdu = &ctx->crc_indications[ctx->frame_count - 1];
                pdu->rnti = rand(); // Simulated RNTI
                pdu->rx_ue_information_tag = rand();
                pdu->crc_indication_rel8_tag.crc_flag = rand() % 2; // Random CRC flag

                pthread_mutex_lock(&manager->frame_count_lock);
                manager->total_frames++;
                pthread_mutex_unlock(&manager->frame_count_lock);

                pthread_mutex_unlock(&ctx->lock);
                pthread_mutex_unlock(&manager->context_lock);
                return 0;
            }

            pthread_mutex_unlock(&ctx->lock);
        }
    }

    pthread_mutex_unlock(&manager->context_lock);
    return -1; // Failed to insert
}

void remove_frame(UE_CONTEXT_MANAGER *manager, int cell_id, int frame_id) {
    pthread_mutex_lock(&manager->context_lock);

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_UE_CONTEXT *ctx = &manager->ue_contexts[i];

        if (pthread_mutex_trylock(&ctx->lock) == 0 && ctx->cell_id == cell_id) {
            for (size_t j = 0; j < ctx->frame_count; ++j) {
                if (ctx->frames[j].frame_id == frame_id) {
                    memmove(&ctx->frames[j], &ctx->frames[j + 1], sizeof(LTE_DL_FRAME) * (ctx->frame_count - j - 1));
                    ctx->frame_count--;

                    pthread_mutex_lock(&manager->frame_count_lock);
                    manager->total_frames--;
                    pthread_mutex_unlock(&manager->frame_count_lock);

                    pthread_mutex_unlock(&ctx->lock);
                    pthread_mutex_unlock(&manager->context_lock);
                    return;
                }
            }

            pthread_mutex_unlock(&ctx->lock);
        }
    }

    pthread_mutex_unlock(&manager->context_lock);
}

int get_total_frames(UE_CONTEXT_MANAGER *manager, size_t *total_frames) {
    if (!total_frames) return -1;

    pthread_mutex_lock(&manager->frame_count_lock);
    *total_frames = manager->total_frames;
    pthread_mutex_unlock(&manager->frame_count_lock);

    return 0;
}

void reset_total_frame_count(UE_CONTEXT_MANAGER *manager) {
    pthread_mutex_lock(&manager->frame_count_lock);
    manager->total_frames = 0;
    pthread_mutex_unlock(&manager->frame_count_lock);
}

int create_ue_context_manager(UE_CONTEXT_MANAGER **manager, size_t initial_capacity) {
    if (!manager || !initial_capacity) return -1;

    *manager = (UE_CONTEXT_MANAGER *)malloc(sizeof(UE_CONTEXT_MANAGER));
    if (!*manager) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    (*manager)->ue_contexts = (LTE_UE_CONTEXT *)calloc(initial_capacity, sizeof(LTE_UE_CONTEXT));
    if (!(*manager)->ue_contexts) {
        free(*manager);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    (*manager)->count = 0;
    (*manager)->capacity = initial_capacity;
    (*manager)->total_frames = 0;

    pthread_mutex_init(&(*manager)->context_lock, NULL);
    pthread_mutex_init(&(*manager)->frame_count_lock, NULL);

    return 0;
}

void destroy_ue_context_manager(UE_CONTEXT_MANAGER *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free_ue_context(&manager->ue_contexts[i]);
    }

    free(manager->ue_contexts);
    pthread_mutex_destroy(&manager->context_lock);
    pthread_mutex_destroy(&manager->frame_count_lock);
    free(manager);
}

void periodic_service(UE_CONTEXT_MANAGER *manager) {
    while (1) {
        sleep(rand() % 5 + 1); // Simulate variable service duration

        int status = insert_frame(manager, rand() % 10, &(LTE_DL_FRAME){.frame_id = rand()});
        if (status == -1) {
