}

int main() {
    UE_CONTEXT_MANAGER *manager;
    create_ue_context_manager(&manager, 10);

    pthread_t service_thread;
    pthread_create(&service_thread, NULL, (void *(*)(void *))periodic_service, manager);
    pthread_join(service_thread, NULL);

    destroy_ue_context_manager(manager);

    return 0;
}
