#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_MEMORY_PER_THREAD_KB 4
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define MAX_STRUCTS ((MAX_MEMORY_PER_THREAD_KB * 1024) / STRUCT_SIZE)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t max_size;
    size_t current_usage;
    pthread_mutex_t lock;
    void* pool;
    struct MemoryPool* next;
} MemoryPool;

MemoryPool *global_pool_head = NULL;
pthread_mutex_t global_pool_lock = PTHREAD_MUTEX_INITIALIZER;

void init_memory_pool() {
    if (global_pool_head == NULL) {
        global_pool_head = malloc(sizeof(MemoryPool));
        pthread_mutex_init(&global_pool_head->lock, NULL);
        global_pool_head->max_size = MAX_MEMORY_PER_THREAD_KB * 1024;
        global_pool_head->current_usage = 0;
        global_pool_head->pool = malloc(global_pool_head->max_size);
        global_pool_head->next = NULL;
    }
}

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&global_pool_lock);

    MemoryPool *pool = global_pool_head;

    while (pool != NULL) {
        pthread_mutex_lock(&pool->lock);

        if (size + pool->current_usage <= pool->max_size) {
            void *allocated_ptr = (char *)pool->pool + pool->current_usage;
            pool->current_usage += size;
            pthread_mutex_unlock(&pool->lock);

            pthread_mutex_unlock(&global_pool_lock);
            return allocated_ptr;
        }

        pthread_mutex_unlock(&pool->lock);
        pool = pool->next;
    }

    // Allocate a new memory block if no existing block can fit the allocation
    MemoryPool *new_pool = malloc(sizeof(MemoryPool));
    pthread_mutex_init(&new_pool->lock, NULL);
    new_pool->max_size = MAX_MEMORY_PER_THREAD_KB * 1024;
    new_pool->current_usage = size;
    new_pool->pool = malloc(new_pool->max_size);
    new_pool->next = global_pool_head;

    pthread_mutex_unlock(&global_pool_lock);

    return new_pool->pool;
}

void* free_memory(void* ptr) {
    // This is a simplified version. A more complex implementation would
    // involve tracking allocations and freeing them properly.
    pthread_mutex_lock(&global_pool_lock);

    MemoryPool *prev = NULL, *current = global_pool_head;

    while (current != NULL) {
        pthread_mutex_lock(&current->lock);

        if ((char *)current->pool <= ptr && 
            (char *)(current->pool + current->max_size) > ptr) {

            // Assuming deallocation can be handled by resetting the pointer
            size_t offset = (char*)ptr - (char*)current->pool;
            current->current_usage -= STRUCT_SIZE;

            pthread_mutex_unlock(&current->lock);

            if (current->next == NULL && current->current_usage == 0) {
                // Free memory pool that is now empty and unused
                free(current->pool);
                if (prev != NULL) {
                    prev->next = NULL;
                } else {
                    global_pool_head = NULL;
                }
                pthread_mutex_unlock(&global_pool_lock);
                free(current);

                return ptr; // Return the original pointer
            }

            pthread_mutex_unlock(&current->lock);
            break;
        }

        pthread_mutex_unlock(&current->lock);

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&global_pool_lock);
    return NULL; // If deallocation logic is more complex, handle accordingly
}

void* create_nfa_crc_indication_pdu_array(size_t num_elements) {
    if (num_elements == 0 || num_elements > MAX_STRUCTS)
        return NULL;

    size_t total_size = num_elements * STRUCT_SIZE;
    NFAPI_CRC_INDICATION_PDU_T *array = 
        (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(total_size);

    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomize CRC flag
    }

    return (void*)array;
}

// Function to simulate thread function calls and allocation requests
void* thread_function(void* arg) {
    size_t num_elements = *(size_t*)arg;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = 
        create_nfa_crc_indication_pdu_array(num_elements);

    if (pdu_array != NULL) {
        printf("Allocated array with %zu elements\n", num_elements);

        // Simulate processing
        sleep(1); 

        free_memory(pdu_array);
    }

    return NULL;
}

int main() {
    init_memory_pool();

    size_t num_threads = 5;
    pthread_t threads[num_threads];
    size_t array_sizes[] = {100, 200, 150, 250, 300};

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &array_sizes[i]);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    MemoryPool *current_pool = global_pool_head;
    while (current_pool != NULL) {
        MemoryPool *next_pool = current_pool->next;

        free(current_pool->pool);
        free(current_pool);
        current_pool = next_pool;
    }

    return 0;
}
