typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    uint16_t rnti;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
} RNTIHashTable;

// Thread-safe hash table functions
RNTIHashTable* create_rnti_hash_table(size_t bucket_count) {
    RNTIHashTable* ht = malloc(sizeof(RNTIHashTable));
    ht->buckets = calloc(bucket_count, sizeof(Node*));
    ht->bucket_count = bucket_count;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void free_rnti_hash_table(RNTIHashTable* ht) {
    for (size_t i = 0; i < ht->bucket_count; ++i) {
        Node* node = ht->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

unsigned int rnti_hash(uint16_t rnti, size_t bucket_count) {
    return (rnti & 0xFFFF) % bucket_count;
}

int insert_rnti(RNTIHashTable* ht, uint16_t rnti) {
    unsigned int index = rnti_hash(rnti, ht->bucket_count);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    pthread_mutex_lock(&ht->lock);

    // Check for duplicate RNTI
    Node* node = ht->buckets[index];
    while (node) {
        if (node->rnti == rnti) {
            free(new_node);
            pthread_mutex_unlock(&ht->lock);
            return 0; // Already exists
        }
        node = node->next;
    }

    new_node->rnti = rnti;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;

    pthread_mutex_unlock(&ht->lock);
    return 1;
}

// Function to generate a unique RNTI
uint16_t generate_unique_rnti(RNTIHashTable* ht) {
    uint16_t rnti;
    int success;
    do {
        rnti = rand() % (1 << RNTI_BITS); // Random RNTI in 16-bit range
        pthread_mutex_lock(&ht->lock);
        success = insert_rnti(ht, rnti);
        pthread_mutex_unlock(&ht->lock);
    } while (!success);

    return rnti;
}

// Function to populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void* populate_nfa_crc_indication(void* arg) {
    size_t num_connections = *(size_t*)arg;
    RNTIHashTable* ht = create_rnti_hash_table(1 << 10); // Example bucket count for hash table

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(num_connections * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        free_rnti_hash_table(ht);
        return NULL;
    }

    for (size_t i = 0; i < num_connections; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % (1 << 16); // Random RX_UE tag
        pdu_list[i].RNTI = generate_unique_rnti(ht);
        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0x01; // Random CRC flag
    }

    free_rnti_hash_table(ht);
    return (void*)pdu_list;
}

int main() {
    const size_t num_connections = 10000; // Example number of connections

    pthread_t threads[MAX_THREADS];
    void* results[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        size_t connections_per_thread = num_connections / MAX_THREADS;
        pthread_create(&threads[i], NULL, populate_nfa_crc_indication, &connections_per_thread);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], &results[i]);
    }

    // Results can be accessed and processed further as needed
    return 0;
}
```']

