// Union-Find data structure for disjoint set management
typedef struct {
    int *parent;
    size_t size;
} UnionFind;

UnionFind* create_union_find(size_t n) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->parent = calloc(n, sizeof(int));
    uf->size = n;
    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }
    return uf;
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        uf->parent[rootY] = rootX;
    }
}

void free_union_find(UnionFind *uf) {
    free(uf->parent);
    free(uf);
