['Below is a C function that initializes a dynamic array of `MAC_PDU_T` structures, each containing a valid `MAC_HEADER` and `MAC_PAYLOAD`. The payload is populated with random bytes ensuring no two consecutive bytes are the same. A checksum validation mechanism is also included.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_PDUS 10000
#define PAYLOAD_SIZE 256

typedef struct {
    uint8_t length;
    // Add other header fields as needed
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    uint8_t payload[PAYLOAD_SIZE];
} MAC_PDU_T;

uint16_t calculate_checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i += 2) {
        uint16_t word = data[i] << 8;
        if (i + 1 < len) {
            word |= data[i + 1];
        }
        sum += word;
        while (sum >> 16) {
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
    }
    return ~sum;
}

int validate_checksum(const MAC_PDU_T *pdu) {
    uint8_t data_to_check[PAYLOAD_SIZE];
    memcpy(data_to_check, pdu->payload, PAYLOAD_SIZE);
    // Assuming checksum is at the end of payload for simplicity
    uint16_t received_checksum = *(uint16_t *)(data_to_check + PAYLOAD_SIZE - 2);
    uint16_t calculated_checksum = calculate_checksum(data_to_check, PAYLOAD_SIZE - 2);
    return received_checksum == calculated_checksum;
}

void populate_payload_with_random_bytes(uint8_t *payload, size_t len) {
    if (len < 1) return;

    payload[0] = rand() % 256;
    for (size_t i = 1; i < len; ++i) {
        uint8_t byte;
        do {
            byte = rand() % 256;
        } while (byte == payload[i - 1]);
        payload[i] = byte;
    }
}

MAC_PDU_T* initialize_pdus(int num_pdus, size_t payload_size) {
    if (num_pdus <= 0 || num_pdus > MAX_PDUS || payload_size > PAYLOAD_SIZE) {
        fprintf(stderr, "Invalid number of PDUs or payload size.\n");
        return NULL;
    }

    MAC_PDU_T *pdus = malloc(num_pdus * sizeof(MAC_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].header.length = payload_size;

        populate_payload_with_random_bytes(pdus[i].payload, payload_size);

        uint16_t checksum = calculate_checksum(pdus[i].payload, payload_size - 2);
        memcpy((uint8_t *)pdus[i].payload + payload_size - 2, &checksum, sizeof(checksum));

        if (!validate_checksum(&pdus[i])) {
            fprintf(stderr, "Checksum validation failed for PDU %d\n", i);
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}

void free_pdus(MAC_PDU_T *pdus) {
    free(pdus);
}
```

### Key Points:
- **Memory Management**: The function uses `malloc` for dynamic memory allocation and ensures to free it with `free_pdus`.
- **Random Byte Generation**: Ensures no two consecutive bytes are the same in the payload.
- **Checksum Calculation and Validation**: Uses a simple checksum mechanism to ensure data integrity.
- **Error Handling**: Checks for invalid input parameters, memory allocation failures, and checksum validation errors.']

