    return manager;
}

void destroy_context_manager(UEContextManager* manager) {
    if (manager) {
        UEContext *current, *next;
        pthread_mutex_lock(&manager->lock);

        current = manager->head;
        while (current) {
            next = current->next;
            free(current);
            current = next;
        }

        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_context(UEContextManager* manager, UEContext* new_context) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate RNTI
    UEContext *current = manager->head;
    while (current) {
        if (current->rnti == new_context->rnti) {
            pthread_mutex_unlock(&manager->lock);
            return 0; // RNTI already exists
        }
        current = current->next;
    }

    new_context->next = manager->head;
    manager->head = new_context;

    pthread_mutex_unlock(&manager->lock);
    log_context_change("Added", new_context->rnti); // Log the change
    return 1; // Success
}

int remove_context_by_rnti(UEContextManager* manager, int rnti) {
    pthread_mutex_lock(&manager->lock);

    UEContext **current = &manager->head;
    while (*current) {
        if ((*current)->rnti == rnti) {
            UEContext *temp = *current;
            *current = (*current)->next;
            free(temp);
            log_context_change("Removed", rnti); // Log the change
            pthread_mutex_unlock(&manager->lock);
            return 1; // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Not found
}

int update_srb1_config(UEContextManager* manager, int rnti, SRB1Config new_config) {
    pthread_mutex_lock(&manager->lock);

    UEContext *current = manager->head;
    while (current) {
        if (current->rnti == rnti) {
            // Assuming we have a function to copy the configuration
            current->srb1_config = new_config; 
            log_context_change("Updated SRB1", rnti); // Log the change
            pthread_mutex_unlock(&manager->lock);
            return 1; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Not found
}

int set_paging_priority(UEContextManager* manager, int rnti, PagingPriority new_priority) {
    pthread_mutex_lock(&manager->lock);

    UEContext *current = manager->head;
    while (current) {
        if (current->rnti == rnti) {
            current->paging_priority.priority = new_priority.priority;
            log_context_change("Set Priority", rnti); // Log the change
            pthread_mutex_unlock(&manager->lock);
            return 1; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Not found
}

// Placeholder for logging mechanism
void log_context_change(const char* action, int rnti) {
    printf("%s context with RNTI: %d\n", action, rnti);
}
```

### Explanation of the Code:

- **Data Structures**: The `UEContext` structure represents a UE context. The `UEContextManager` holds the dynamic array (linked list) and a mutex for thread-safe operations.

- **Concurrency Control**: A mutex (`pthread_mutex_t`) is used to ensure safe concurrent access to the linked list of contexts.

- **Memory Management**: Memory is dynamically allocated using `malloc` and freed with `free`. The code checks for existing RNTI before adding new contexts to avoid duplicates.

- **Logging**: Each modification (add, remove, update) logs its action for historical records, ensuring synchronization with context changes via the mutex lock.

This implementation balances concurrency, memory efficiency, and logging needs while providing a foundation for future scalability.']

