#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Configuration settings
typedef struct {
    int max_structures;
    unsigned long seed;
} Config;

// Thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Config read_config(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    Config config;
    fscanf(file, "%d %lu", &config.max_structures, &config.seed);

    fclose(file);
    return config;
}

void generate_crc_flag(unsigned char *crcflag) {
    static unsigned int a = 1103515245;
    static unsigned int c = 12345;
    static unsigned long seed;

    pthread_mutex_lock(&mutex);
    seed = (a * seed + c) & 0x7fffffff; // Linear congruential generator
    pthread_mutex_unlock(&mutex);

    *crcflag = (unsigned char)(seed % 256); // Example CRCFLAG generation
}

NFAPI_CRC_INDICATION_PDU_T* generate_structures(const Config *config, size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    srand(config->seed); // Initialize random number generator with seed
    pthread_mutex_unlock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rand() % 10000;
        generate_crc_flag(&structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T *structures) {
    if (structures) {
        free(structures);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config config = read_config(argv[1]);

    // Limit the count to either the requested number or maximum allowed
    size_t structure_count = config.max_structures > 0 && config.max_structures <= MAX_STRUCTURES ? 
                             config.max_structures : MAX_STRUCTURES;

    NFAPI_CRC_INDICATION_PDU_T *structures = generate_structures(&config, structure_count);

    // Example usage of structures
    for (size_t i = 0; i < structure_count; ++i) {
        printf("Structure %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
               i, structures[i].RX_UE_INFORMATION_TAG, structures[i].RNTI,
               structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    free_structures(structures);

    return EXIT_SUCCESS;
}
```

### Key Points:
