using System;
using System.Xml;

public class ConfigurationLoader
{
    private int tileSize = 32;
    private int worldWidth = 1000;
    private int worldHeight = 500;
    private float cameraSpeed = 10.0f;

    public void LoadConfiguration(string filePath)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(filePath);

            XmlNode tileNode = doc.SelectSingleNode("/configuration/tileSize");
            if (tileNode != null && int.TryParse(tileNode.InnerText, out int tileSizeValue))
                this.tileSize = tileSizeValue;

            XmlNode widthNode = doc.SelectSingleNode("/configuration/worldWidth");
            if (widthNode != null && int.TryParse(widthNode.InnerText, out int worldWidthValue))
                this.worldWidth = worldWidthValue;

            XmlNode heightNode = doc.SelectSingleNode("/configuration/worldHeight");
            if (heightNode != null && int.TryParse(heightNode.InnerText, out int worldHeightValue))
                this.worldHeight = worldHeightValue;

            XmlNode speedNode = doc.SelectSingleNode("/configuration/cameraSpeed");
            if (speedNode != null && float.TryParse(speedNode.InnerText, out float cameraSpeedValue))
                this.cameraSpeed = cameraSpeedValue;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            // Handle parsing errors or file not found gracefully
        }
    }

    public int GetTileSize() => tileSize;
    public int GetWorldWidth() => worldWidth;
    public int GetWorldHeight() => worldHeight;
    public float GetCameraSpeed() => cameraSpeed;

    static void Main(string[] args)
    {
        ConfigurationLoader configLoader = new ConfigurationLoader();
        configLoader.LoadConfiguration("config.xml");

        Console.WriteLine($"Tile Size: {configLoader.GetTileSize()}");
        Console.WriteLine($"World Width: {configLoader.GetWorldWidth()}");
        Console.WriteLine($"World Height: {configLoader.GetWorldHeight()}");
        Console.WriteLine($"Camera Speed: {configLoader.GetCameraSpeed()}");
    }
}
