typedef struct {
    char *interface_name;
    unsigned long packet_count;
    unsigned long byte_count;
    time_t last_updated_timestamp;
} NetworkInterfaceStats;

typedef struct Node {
    NetworkInterfaceStats data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_node(Node *node) {
    if (node) {
        free(node->data.interface_name);
        free(node);
    }
}

NetworkInterfaceStats* find_interface(DynamicArray *array, const char *interface_name) {
    Node *current = array->head;
    while (current) {
        if (strcmp(current->data.interface_name, interface_name) == 0) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void add_or_update_interface(DynamicArray *array, const char *interface_name,
                             unsigned long packet_count, unsigned long byte_count) {
    pthread_mutex_lock(&array->lock);

    NetworkInterfaceStats *stats = find_interface(array, interface_name);
    Node *current = array->head;

    if (stats) {
        stats->packet_count += packet_count;
        stats->byte_count += byte_count;
        stats->last_updated_timestamp = time(NULL);
    } else {
        Node *new_node = malloc(sizeof(Node));
        new_node->data.interface_name = strdup(interface_name);
        new_node->data.packet_count = packet_count;
        new_node->data.byte_count = byte_count;
        new_node->data.last_updated_timestamp = time(NULL);
        new_node->next = array->head;
        array->head = new_node;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_dynamic_array(DynamicArray *array) {
    Node *current = array->head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

unsigned long get_total_packet_count(DynamicArray *array) {
    unsigned long total_packets = 0;
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current) {
        total_packets += current->data.packet_count;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return total_packets;
}

unsigned long get_total_byte_count(DynamicArray *array) {
    unsigned long total_bytes = 0;
    pthread_mutex_lock(&array->lock);

    Node *current = array->head;
    while (current) {
        total_bytes += current->data.byte_count;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return total_bytes;
}
```

