```c
#include <stdio.h>
#include <stdlib.h>
import <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_PACKETS 1024

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint8_t protocol_type;
    size_t payload_size;
} PacketHeader;

// Custom memory pool for PacketHeaders
typedef struct {
    pthread_mutex_t lock;
    PacketHeader *pool;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->lock = PTHREAD_MUTEX_INITIALIZER;
    mp->pool = (PacketHeader*)aligned_alloc(64, capacity * sizeof(PacketHeader)); // 64-byte alignment
    mp->capacity = capacity;
    mp->used = 0;
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

PacketHeader* allocate_packet_header(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used < mp->capacity) {
        PacketHeader *header = &mp->pool[mp->used++];
        pthread_mutex_unlock(&mp->lock);
        return header;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // No available memory
}

void free_packet_header(MemoryPool *mp, PacketHeader *header) {
    size_t index = (uint8_t*)header - (uint8_t*)mp->pool;
    if (index < mp->used) {
        pthread_mutex_lock(&mp->lock);
        memmove(&mp->pool[index], &mp->pool[mp->used - 1], sizeof(PacketHeader));
        --mp->used;
        pthread_mutex_unlock(&mp->lock);
    }
}

void process_packet(MemoryPool *mp, int socket_fd) {
    char buffer[1024];
    ssize_t bytes_read;

    while ((bytes_read = read(socket_fd, buffer, sizeof(buffer))) > 0) {
        PacketHeader *header = allocate_packet_header(mp);
        if (header != NULL) {
            // Simulate reading data from the network socket into the packet header
            memcpy(&header->src_ip, buffer, 4);
            memcpy(&header->dst_ip, buffer + 4, 4);
            header->protocol_type = buffer[8];
            header->payload_size = bytes_read - 9;

            // Process the packet (e.g., enqueue for further processing)
            printf("Packet: src=%u dst=%u proto=%d size=%zu\n",
                   header->src_ip, header->dst_ip, header->protocol_type, header->payload_size);

            free_packet_header(mp, header);
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Memory pool exhausted\n");
            break;
        }
    }

    if (bytes_read < 0) {
        perror("Read error");
    }
}

int main(int argc, char *argv[]) {
    int socket_fd = /* obtain your network socket fd */;
    MemoryPool *mp = create_memory_pool(MAX_PACKETS);

    process_packet(mp, socket_fd);

    destroy_memory_pool(mp);
    return 0;
}
```

### Key Components:
- **Memory Pool:** A fixed-size memory pool is created to minimize fragmentation and optimize allocation/deallocation performance.
- **Thread Safety:** `pthread_mutex_t` ensures thread-safe access to the memory pool.
