    EventType eventType;
    time_t timestamp;
    void *payload;
    size_t payloadSize;
    unsigned int refCount;
    struct DeviceEvent *prev;
    struct DeviceEvent *next;
} DeviceEvent;

typedef struct {
    DeviceEvent *head;
