DeviceEvent* create_device_event(EventType type);
void free_device_event(DeviceEvent *event);
int add_event(EventList *list, DeviceEvent *newEvent);
void remove_event(EventList *list, DeviceEvent *event);
DeviceEvent* find_next_event(EventList *list, DeviceEvent *current);
void decrement_ref_count_and_free_if_needed(DeviceEvent *event);

// Implementation
DeviceEvent* create_device_event(EventType type) {
    DeviceEvent *event = (DeviceEvent *)malloc(sizeof(DeviceEvent));
    if (!event) return NULL;

    event->eventType = type;
    time(&event->timestamp);
    event->payload = NULL;
    event->payloadSize = 0;
    event->refCount = 1; // Starts with one reference
    event->prev = event->next = NULL;

    switch (type) {
        case EVENT_TYPE_A:
            event->payloadSize = 16; // Example size for type A
            break;
        case EVENT_TYPE_B:
            event->payloadSize = 32; // Example size for type B
            break;
        // Add more cases as needed
    }

    if (event->payloadSize > 0) {
        event->payload = malloc(event->payloadSize);
        if (!event->payload) {
            free(event);
            return NULL;
        }
        srand(time(NULL));
        unsigned char *data = (unsigned char *)event->payload;
        for (size_t i = 0; i < event->payloadSize; ++i) {
            data[i] = rand() % 256;
        }
    }

    return event;
}

void free_device_event(DeviceEvent *event) {
    if (!event) return;

    decrement_ref_count_and_free_if_needed(event);
}

int add_event(EventList *list, DeviceEvent *newEvent) {
    pthread_mutex_lock(&list->mutex);

    if (!list->head || newEvent->timestamp < list->head->timestamp) {
        newEvent->next = list->head;
        if (list->head) list->head->prev = newEvent;
        list->head = newEvent;
    } else {
        DeviceEvent *current = list->head;
        while (current->next && current->next->timestamp < newEvent->timestamp) {
            current = current->next;
        }
        newEvent->next = current->next;
        if (current->next) current->next->prev = newEvent;
        current->next = newEvent;
        newEvent->prev = current;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void remove_event(EventList *list, DeviceEvent *event) {
    pthread_mutex_lock(&list->mutex);

    if (event->prev) event->prev->next = event->next;
    if (event->next) event->next->prev = event->prev;
    if (list->head == event) list->head = event->next;

    free_device_event(event);

    pthread_mutex_unlock(&list->mutex);
}

DeviceEvent* find_next_event(EventList *list, DeviceEvent *current) {
    pthread_mutex_lock(&list->mutex);

    DeviceEvent *next = current ? current->next : list->head;
    pthread_mutex_unlock(&list->mutex);
    return next;
}

void decrement_ref_count_and_free_if_needed(DeviceEvent *event) {
    if (!event) return;

    event->refCount--;
    if (event->refCount == 0) {
        free(event->payload);
        free(event);
    }
}

// Example usage
int main() {
    EventList list = {NULL};
    pthread_mutex_init(&list.mutex, NULL);

    DeviceEvent *event1 = create_device_event(EVENT_TYPE_A);
    add_event(&list, event1);

    DeviceEvent *next = find_next_event(&list, NULL);
    while (next) {
        printf("Next event timestamp: %ld\n", next->timestamp);
        next = find_next_event(&list, next);
    }

    remove_event(&list, event1);

    pthread_mutex_destroy(&list.mutex);
    return 0;
}
```

