    pthread_mutex_lock(&list_lock);

    DeviceEvent* new_event = create_device_event(type, timestamp, payload_size);
    if (!new_event) {
        fprintf(stderr, "Failed to allocate memory for new event\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    Node** current = &head;
    while (*current && (*current)->event.timestamp < timestamp) {
        if ((*current)->next && !validate_consecutive_events(type, (*current)->next->event.type)) {
            destroy_device_event(new_event);
            fprintf(stderr, "Consecutive events of the same type detected\n");
            pthread_mutex_unlock(&list_lock);
            return;
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        destroy_device_event(new_event);
        fprintf(stderr, "Failed to allocate memory for node\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    new_node->event = *new_event;
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&list_lock);
}

void remove_events_by_type(EventType type) {
    pthread_mutex_lock(&list_lock);

    Node **current = &head;
    while (*current) {
        if ((*current)->event.type == type) {
            Node* to_delete = *current;
            *current = (*current)->next;
            destroy_device_event(&(to_delete->event));
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }

