    pthread_mutex_lock(&list_mutex);

    if (is_valid_crc_tag(&new_pdu.crc_tag)) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            LOG_WARNING("Memory allocation failed for new node");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        new_node->data = new_pdu;
        new_node->next = NULL;

        // Truncate list if exceeds max size
        if (list_size >= MAX_LIST_SIZE) {
            Node* temp = head;
            while (temp && temp->next) {
                temp = temp->next;
            }

            free(head);
            head = temp ? temp : NULL;
            LOG_WARNING("List truncated. Max size exceeded.");
            list_size--;
        }

        if (!head) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }

        LOG_INFO("Added PDU with RNTI: %u", new_pdu.RNTI);
        list_size++;
    } else {
        LOG_WARNING("Invalid CRC_INDICATION_REL8_TAG for RNTI: %u", new_pdu.RNTI);
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;
    list_size = 0;

    LOG_INFO("Freed all nodes in the list");
    pthread_mutex_unlock(&list_mutex);
}
