}

int should_resize(CRCManager *manager, size_t growth_rate) {
    // Implement logic to decide if resizing is needed based on memory usage and growth rate
    return (growth_rate > (manager->max_size / 2)) && manager->count >= manager->capacity;
}

void resize_array(CRCManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message(1, "Memory allocation failed during resize");
        exit(EXIT_FAILURE); // Handle appropriately in real scenarios
    }

    manager->array = new_array;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->lock);
}

void add_pdu(CRCManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    if (should_resize(manager, manager->count)) {
        resize_array(manager, manager->capacity * 2); // Example: double the size
    }

    manager->array[manager->count++] = pdu;

    log_message(3, "Added a new PDU");

    pthread_mutex_unlock(&manager->lock);
}

void clear_pdus(CRCManager *manager) {
    if (should_clear(manager)) {
        pthread_mutex_lock(&manager->lock);

        for (size_t i = 0; i < manager->count; ++i) {
            memset(&manager->array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        manager->count = 0;
        manager->last_clear_time = time(NULL);

        log_message(2, "Cleared all PDUs");

        pthread_mutex_unlock(&manager->lock);
    }
}

void cleanup(CRCManager *manager) {
    if (manager->array) {
        free(manager->array);
        manager->array = NULL;
        manager->capacity = 0;
        manager->count = 0;
    }

    pthread_mutex_destroy(&manager->lock);
    log_message(1, "Resources cleaned up");
}

void* manager_thread(void *arg) {
