// TCP_CONNECTION_STATS.c

#include "TCP_CONNECTION_STATS.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

void init_connection_stats_manager(ConnectionStatsManager *manager) {
    manager->stats = NULL;
    manager->count = 0;
    manager->capacity = 10; // Initial capacity
    pthread_mutex_init(&manager->lock, NULL);

    manager->stats = malloc(manager->capacity * sizeof(TCP_CONNECTION_STATS));
}

void resize_stats_array(ConnectionStatsManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    TCP_CONNECTION_STATS *new_stats = realloc(manager->stats, new_capacity * sizeof(TCP_CONNECTION_STATS));
    if (new_stats) {
        manager->stats = new_stats;
        manager->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to resize connection stats array\n");
    }
}

void add_connection_stat(ConnectionStatsManager *manager, const TCP_CONNECTION_STATS *stat) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_stats_array(manager);
    }

    memcpy(&manager->stats[manager->count], stat, sizeof(TCP_CONNECTION_STATS));
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

void update_connection_stat(ConnectionStatsManager *manager, int connection_id, unsigned long bytes_transmitted, unsigned long bytes_received) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].connection_id == connection_id) {
            manager->stats[i].bytes_transmitted += bytes_transmitted;
            manager->stats[i].bytes_received += bytes_received;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

TCP_CONNECTION_STATS* get_connection_stat(ConnectionStatsManager *manager, int connection_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->stats[i].connection_id == connection_id) {
            TCP_CONNECTION_STATS *stat = &manager->stats[i];
            pthread_mutex_unlock(&manager->lock);
            return stat;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void flush_stats_to_logging_service(ConnectionStatsManager *manager) {
    // Implementation for flushing data to a remote logging service with fallback mechanism
    // This is a placeholder and should be implemented based on the specific logging service API.
}

void cleanup_connection_stats_manager(ConnectionStatsManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->stats);
}
