```cpp
// ConnectionStats.cpp

#include "ConnectionStats.h"
#include <algorithm>
#include <iostream>

ConnectionStats::ConnectionStats() {
    pthread_mutex_init(&lock, NULL);
}

ConnectionStats::~ConnectionStats() {
    pthread_mutex_destroy(&lock);
}

void ConnectionStats::addStat(const TCP_CONNECTION_STATS &stat) {
    std::lock_guard<std::mutex> guard(lock);

    if (stats.size() == stats.capacity()) {
        stats.reserve(stats.capacity() * 2);
    }

    indexMap[stat.connection_id] = stats.size();
    stats.push_back(stat);
}

void ConnectionStats::updateStat(int connectionId, unsigned long bytesTransmitted, unsigned long bytesReceived) {
    std::lock_guard<std::mutex> guard(lock);

    auto it = indexMap.find(connectionId);
    if (it != indexMap.end()) {
        size_t idx = it->second;
        stats[idx].bytes_transmitted += bytesTransmitted;
        stats[idx].bytes_received += bytesReceived;
    }
}

const TCP_CONNECTION_STATS* ConnectionStats::getStat(int connectionId) const {
    std::lock_guard<std::mutex> guard(lock);

    auto it = indexMap.find(connectionId);
    if (it != indexMap.end()) {
        return &stats[it->second];
    }

    return nullptr;
}
