    uint64_t bytes_transmitted;
    uint64_t bytes_received;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crc_list;

    void populate_crc_list(size_t N) {
        std::random_device rd;
        std::mt19937 gen(rd());
        for (size_t i = 0; i < N; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu = {gen(), gen(), gen() % 2 == 0};
            crc_list.push_back(pdu);
        }
    }
};

class ConnectionManager {
public:
    ConnectionManager() : flush_interval_(10), shutdown_flag_(false) {}

    void add_connection(const std::string& connection_id, uint64_t bytes_transmitted, uint64_t bytes_received) {
        std::unique_lock lock(mutex_);
        TCP_CONNECTION_STATS stats = {connection_id, std::chrono::steady_clock::now(), bytes_transmitted, bytes_received};
        stats.populate_crc_list(10); // Example size for the list
        connections_[connection_id] = std::move(stats);
