        if (flush_thread_.joinable()) {
            flush_cv_.notify_all();
            flush_thread_.join();
        }
    }

private:
    void periodic_flush() {
        while (!shutdown_flag_) {
            std::unique_lock lock(flush_mutex_);
            flush_cv_.wait_for(lock, std::chrono::seconds(flush_interval_), [this]() { return shutdown_flag_; });

            if (shutdown_flag_)
                break;

            log_to_remote_service();
        }
