        std::cerr << "Failed to log connection: " << connection_id << ", using fallback\n";
        // Fallback logic here (e.g., retry, queue for later)
    }

private:
    std::unordered_map<std::string, TCP_CONNECTION_STATS> connections_;
    mutable std::shared_mutex mutex_;
    mutable std::mutex flush_mutex_;
    std::condition_variable flush_cv_;
    std::thread flush_thread_;
    int flush_interval_;
    std::atomic<bool> shutdown_flag_;
};

