['```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    time_t cooldowns[3]; // 0: fire, 1: dash, 2: heal
    int action_flags; // bit mask for available actions
} GameClientState;

#define FIRE_COOLDOWN 5
#define DASH_COOLDOWN 7
#define HEAL_COOLDOWN 10

pthread_mutex_t client_states_mutex = PTHREAD_MUTEX_INITIALIZER;
GameClientState *client_states = NULL;
int client_count = 0;

void initialize_client_state(GameClientState *state) {
    pthread_mutex_init(&state->mutex, NULL);
    state->cooldowns[0] = time(NULL) - FIRE_COOLDOWN;
    state->cooldowns[1] = time(NULL) - DASH_COOLDOWN;
    state->cooldowns[2] = time(NULL) - HEAL_COOLDOWN;
    state->action_flags = (1 << 3) - 1; // All actions available
}

void cleanup_client_state(GameClientState *state) {
    pthread_mutex_destroy(&state->mutex);
}

int is_action_available(GameClientState *state, int action_index) {
    time_t current_time = time(NULL);
    return (current_time >= state->cooldowns[action_index] + 
            (action_index == 0 ? FIRE_COOLDOWN : action_index == 1 ? DASH_COOLDOWN : HEAL_COOLDOWN));
}

void update_cooldown(GameClientState *state, int action_index) {
    time_t current_time = time(NULL);
    state->cooldowns[action_index] = current_time;
}

NFAPI_CRC_INDICATION_PDU_T* populateNfarpcPduWithGameAction(uint16_t rx_ue_information_tag, uint16_t rnti) {
    pthread_mutex_lock(&client_states_mutex);

    // Find or create client state
    GameClientState *state = NULL;
    for (int i = 0; i < client_count; ++i) {
        if (client_states[i].RX_UE_INFORMATION_TAG == rx_ue_information_tag) {
            state = &client_states[i];
            break;
        }
    }

    if (!state) {
        // Allocate new client state
        GameClientState *new_client_state = realloc(client_states, sizeof(GameClientState) * (client_count + 1));
        if (!new_client_state) {
            pthread_mutex_unlock(&client_states_mutex);
            return NULL; // Allocation failed
        }
        client_states = new_client_state;
        state = &client_states[client_count++];
        state->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
        initialize_client_state(state);
    }

    pthread_mutex_lock(&state->mutex);

    int action_index = -1;
    if (is_action_available(state, 0)) {
        action_index = 0; // fire
    } else if (is_action_available(state, 1)) {
        action_index = 1; // dash
    } else if (is_action_available(state, 2)) {
        action_index = 2; // heal
    }

    if (action_index != -1) {
        update_cooldown(state, action_index);
        state->action_flags &= ~(1 << action_index); // Mark action as used
    }

    pthread_mutex_unlock(&state->mutex);

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        pthread_mutex_unlock(&client_states_mutex);
        return NULL; // Allocation failed
    }
    pdu->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    pdu->RNTI = rnti;
    srand(time(NULL) ^ (intptr_t)pthread_self());
    pdu->crc_tag.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&client_states_mutex);
    return pdu;
}

void disconnect_client(uint16_t rx_ue_information_tag) {
    pthread_mutex_lock(&client_states_mutex);

    for (int i = 0; i < client_count; ++i) {
        if (client_states[i].RX_UE_INFORMATION_TAG == rx_ue_information_tag) {
            cleanup_client_state(&client_states[i]);
            // Shift remaining states
            memmove(&client_states[i], &client_states[i + 1], sizeof(GameClientState) * (client_count - i - 1));
            client_count--;
            break;
        }
    }

    pthread_mutex_unlock(&client_states_mutex);
}
