['Below is a C function implementation for managing a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures, adhering to the given constraints:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NUM_STRUCTURES 100

typedef struct {
    int crc_value;
    // Other fields related to radio communication data
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *structures[MAX_NUM_STRUCTURES];
static size_t count = 0;

int validate_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (!structure) return -1;

    // Example validation: CRC value should be non-negative
    if (structure->crc_value < 0) {
        printf("Data corruption detected in structure.\n");
        return -1;
    }
    return 0;
}

void validate_all_structures() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        if (validate_structure(structures[i]) != 0) {
            printf("Structure %zu is corrupted.\n", i);
            // Handle corruption, e.g., reset or log
        }
    }
    pthread_mutex_unlock(&lock);
}

int add_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (!structure || count >= MAX_NUM_STRUCTURES) return -1;

    pthread_mutex_lock(&lock);
    structures[count++] = structure;
    pthread_mutex_unlock(&lock);

    return 0;
}

void remove_structure(size_t index) {
    if (index >= count) return;

    pthread_mutex_lock(&lock);
    free(structures[index]);
    for (size_t i = index; i < count - 1; ++i) {
        structures[i] = structures[i + 1];
    }
    structures[--count] = NULL;
    pthread_mutex_unlock(&lock);
}

void cleanup() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        free(structures[i]);
    }
    count = 0;
    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

// Example usage
int main() {
    // Add structures
    NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_structure) {
        new_structure->crc_value = 123; // Set valid CRC value
        add_structure(new_structure);
    } else {
        printf("Memory allocation failed.\n");
    }

    // Validate structures periodically
    validate_all_structures();

    // Remove a structure when done
    remove_structure(0);

    // Cleanup resources before exiting
    cleanup();

    return 0;
}
```

