#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_SIZE 10

typedef struct {
    int LAI;          // Location Area Identity
    int PLMN_ID;      // Public Land Mobile Network Identifier
    int CELL_ID;      // Cell Identifier
} MAC_CONTEXT;

typedef struct {
    MAC_CONTEXT *contexts;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} MAC_CONTEXT_LIST;

MAC_CONTEXT_LIST* create_mac_context_list() {
    MAC_CONTEXT_LIST *list = malloc(sizeof(MAC_CONTEXT_LIST));
    list->size = 0;
    list->capacity = INITIAL_SIZE;
    list->contexts = malloc(list->capacity * sizeof(MAC_CONTEXT));
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_mac_context_list(MAC_CONTEXT_LIST *list) {
    free(list->contexts);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_or_update_mac_context(MAC_CONTEXT_LIST *list, int LAI, int PLMN_ID, int CELL_ID) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i].LAI == LAI && list->contexts[i].PLMN_ID == PLMN_ID) {
            list->contexts[i].CELL_ID = CELL_ID;
            pthread_mutex_unlock(&list->mutex);
            return 0; // Updated
        }
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        MAC_CONTEXT *new_contexts = realloc(list->contexts, new_capacity * sizeof(MAC_CONTEXT));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    MAC_CONTEXT new_context = {LAI, PLMN_ID, CELL_ID};
    list->contexts[list->size++] = new_context;

    pthread_mutex_unlock(&list->mutex);
    return 1; // Added
}

void* consistency_check(void *arg) {
    MAC_CONTEXT_LIST *list = (MAC_CONTEXT_LIST *)arg;
    while (1) {
        sleep(10); // Periodic check every 10 seconds

        pthread_mutex_lock(&list->mutex);

        for (size_t i = 0; i < list->size; ++i) {
            if (!is_valid_mac_context(list->contexts[i])) {
                fprintf(stderr, "Inconsistent MAC context found: LAI=%d, PLMN_ID=%d\n",
                        list->contexts[i].LAI, list->contexts[i].PLMN_ID);
                // Handle inconsistency
            }
        }

        pthread_mutex_unlock(&list->mutex);
    }
    return NULL;
}

int is_valid_mac_context(MAC_CONTEXT context) {
    // Implement validation logic for MAC parameters
    return 1; // Assume valid for demonstration purposes
}

void start_consistency_checker(MAC_CONTEXT_LIST *list) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, consistency_check, list)) {
        fprintf(stderr, "Error creating consistency check thread\n");
    }
}

int main() {
    MAC_CONTEXT_LIST *mac_list = create_mac_context_list();
    start_consistency_checker(mac_list);

    add_or_update_mac_context(mac_list, 123, 456, 789);
    add_or_update_mac_context(mac_list, 124, 457, 790);

    free_mac_context_list(mac_list);
    return 0;
}
