        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::bernoulli_distribution d(0.5);
        CRCFLAG = d(gen);
    }
};

struct TCP_CONNECTION_STATS {
    uint64_t connectionID;
    std::chrono::system_clock::time_point timestamp;
    size_t bytesTransmitted;
    size_t bytesReceived;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;

    TCP_CONNECTION_STATS(uint64_t id)
        : connectionID(id), timestamp(std::chrono::system_clock::now()),
          bytesTransmitted(0), bytesReceived(0) {}
};

class ConnectionManager {
public:
    void addConnectionStat(uint64_t connectionID, size_t bytesTransmitted, size_t bytesReceived);
    void updateSessionState(uint64_t connectionID, const std::string& stateChange);
    void flushStats();

private:
    std::unordered_map<uint64_t, TCP_CONNECTION_STATS> statsMap;
    mutable std::shared_mutex mapMutex;

    void periodicFlushTask();
    void handleNetworkPartition();

public:
    ConnectionManager() {
        auto flusher = [this]() { this->periodicFlushTask(); };
        std::thread(std::move(flusher)).detach();
    }

    ~ConnectionManager() {
        stopFlushing();
    }

private:
    bool isStopping = false;
    void stopFlushing() {
        {
            std::unique_lock<std::mutex> lock(flushMutex);
            isStopping.store(true);
            flushCV.notify_all();
        }
        if (flushThread.joinable()) {
            flushThread.join();
        }
    }

    void flushToRemoteService(const TCP_CONNECTION_STATS& stats);

    // Synchronization for periodic task
    std::mutex flushMutex;
    std::condition_variable flushCV;
    bool flushReady = false;
    std::thread flushThread;

};

void ConnectionManager::addConnectionStat(uint64_t connectionID, size_t bytesTransmitted, size_t bytesReceived) {
    std::unique_lock<std::shared_mutex> lock(mapMutex);
    auto it = statsMap.find(connectionID);
    if (it == statsMap.end()) {
        // New connection
        statsMap.emplace(connectionID, TCP_CONNECTION_STATS(connectionID));
    }

    // Update existing entry
    auto& stats = statsMap[connectionID];
    stats.bytesTransmitted += bytesTransmitted;
    stats.bytesReceived += bytesReceived;

    lock.unlock();

    updateSessionState(connectionID, "updated");  // Notify server of state change
}

void ConnectionManager::updateSessionState(uint64_t connectionID, const std::string& stateChange) {
    // Implement sending an update notification to the server here
    // This can include serialization and communication logic
}

void ConnectionManager::flushStats() {
    while (true) {
        {
            std::unique_lock<std::mutex> lock(flushMutex);
            flushCV.wait(lock, [this]() { return flushReady || isStopping; });

            if (isStopping && !statsMap.empty()) {
                for (const auto& pair : statsMap) {
                    flushToRemoteService(pair.second);
                }
                break;
            }

            if (!flushReady)
                continue;

            // Reset flag
            flushReady = false;
        }

        try {
            std::unique_lock<std::shared_mutex> mapLock(mapMutex);
            for (const auto& pair : statsMap) {
                flushToRemoteService(pair.second);
            }
        } catch (...) {
            handleNetworkPartition();  // Handle any network issues
        }
    }
}

void ConnectionManager::periodicFlushTask() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::minutes(5));
        {
            std::unique_lock<std::mutex> lock(flushMutex);
            flushReady = true;
            flushCV.notify_one();
        }

        if (isStopping)
            break;
    }
}

void ConnectionManager::flushToRemoteService(const TCP_CONNECTION_STATS& stats) {
    // Implement the logic to send data to a remote logging service
    // This would include network communication, error handling and retry mechanisms
}

void ConnectionManager::handleNetworkPartition() {
