#define MAX_CONFIG_UPDATE_DELAY 5

typedef struct {
    int channel_id;
    char config_data[256];
} TRANSPORT_CHANNEL_CONFIG;

typedef unsigned long SUBSCRIPTION_ID;

typedef struct LTE_TRANSPORT_CONTEXT {
    TRANSPORT_CHANNEL_CONFIG transport_channel_config;
    SUBSCRIPTION_ID subscription_id;
    bool valid; // Indicates if the context is currently valid
} LTE_TRANSPORT_CONTEXT;

typedef struct Node {
    LTE_TRANSPORT_CONTEXT *context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    size_t count;
    size_t capacity;
} DynamicList;

// Function declarations
void init_dynamic_list(DynamicList* list, size_t initial_capacity);
void destroy_dynamic_list(DynamicList* list);
bool add_context(DynamicList* list, LTE_TRANSPORT_CONTEXT* context);
LTE_TRANSPORT_CONTEXT* get_context_by_id(DynamicList* list, SUBSCRIPTION_ID id);
void update_external_config(DynamicList* list);

// Thread functions for updating config and handling contexts
static void* external_config_updater(void* arg);
static void* context_manager(void* arg);

DynamicList global_list;
bool stop_threads = false;

void init_dynamic_list(DynamicList* list, size_t initial_capacity) {
    list->head = NULL;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->count = 0;
    list->capacity = initial_capacity;
}

void destroy_node(Node* node) {
    if (node != NULL) {
        free(node->context);
        destroy_node(node->next);
        free(node);
    }
}

void destroy_dynamic_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    destroy_node(list->head);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

bool add_context(DynamicList* list, LTE_TRANSPORT_CONTEXT* context) {
    if (pthread_mutex_trylock(&list->mutex) != 0) return false;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    new_node->context = malloc(sizeof(LTE_TRANSPORT_CONTEXT));
    if (!new_node->context) {
        free(new_node);
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    *new_node->context = *context;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

LTE_TRANSPORT_CONTEXT* get_context_by_id(DynamicList* list, SUBSCRIPTION_ID id) {
    LTE_TRANSPORT_CONTEXT* result = NULL;

    if (pthread_mutex_trylock(&list->mutex) != 0) return NULL;

    Node* current = list->head;
    while (current != NULL) {
        if (current->context->subscription_id == id && current->context->valid) {
            result = current->context;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return result;
}

static void* external_config_updater(void* arg) {
    while (!stop_threads) {
        update_external_config((DynamicList*)arg);

        // Sleep for N seconds, handling potential network interruptions gracefully
        sleep(MAX_CONFIG_UPDATE_DELAY);
    }
    return NULL;
}

void update_external_config(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        // Simulate fetching updated configuration data and invalidating if necessary
        // For demonstration purposes, we'll just toggle the valid flag
        current->context->valid = !current->context->valid;

        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);

    printf("External config update applied.\n");
}

static void* context_manager(void* arg) {
    // Manage contexts, simulate processing and handling of incoming data
    while (!stop_threads) {
        // Context management logic goes here
        sleep(1);
    }
    return NULL;
}

int main() {
    size_t max_contexts = 100; // Configurable parameter M

    init_dynamic_list(&global_list, max_contexts);

    pthread_t updater_thread, manager_thread;

    if (pthread_create(&updater_thread, NULL, external_config_updater, &global_list) != 0 ||
        pthread_create(&manager_thread, NULL, context_manager, NULL) != 0) {

        fprintf(stderr, "Failed to create threads.\n");
        destroy_dynamic_list(&global_list);
        return EXIT_FAILURE;
    }

    // Simulate adding contexts
    for (size_t i = 0; i < max_contexts; ++i) {
        LTE_TRANSPORT_CONTEXT* context = malloc(sizeof(LTE_TRANSPORT_CONTEXT));
        if (!context) continue;

        context->subscription_id = i;
        snprintf(context->transport_channel_config.config_data, sizeof(context->transport_channel_config.config_data), "Config %zu", i);
        context->valid = true;

        add_context(&global_list, context);
    }

    // Join threads after some time or condition
    sleep(10);  // Run for a duration before stopping

    stop_threads = true;
    pthread_join(updater_thread, NULL);
    pthread_join(manager_thread, NULL);

    destroy_dynamic_list(&global_list);
    return EXIT_SUCCESS;
}
