int generate_offsets(long *offsets, size_t count, long min_range, long max_range) {
    if (count < 1 || min_range >= max_range)
        return -1;

    offsets[0] = rand() % (max_range - min_range + 1) + min_range;

    for (size_t i = 1; i < count; ++i) {
        long lower_bound = offsets[i-1] + 100;
        long upper_bound = max_range;

        if (lower_bound > upper_bound)
            return -1;

        long valid_value = rand() % (upper_bound - lower_bound + 1) + lower_bound;

        while ((valid_value <= offsets[i-1] + 99 || 
                (i > 1 && valid_value == offsets[i-2])) &&
               valid_value <= upper_bound) {
            valid_value++;
        }

        if (valid_value > upper_bound)
            return -1;

        offsets[i] = valid_value;
    }

    return 0;
}

int generate_keys(int *keys, size_t count, int *predefined_list, size_t list_size) {
