        if (!used_keys[predefined_list[i]]) {
            keys[keys_set++] = predefined_list[i];
            used_keys[predefined_list[i]] = 1;
        }
    }

    if (keys_set < count)
        return -1;

    return 0;
}

int generate_records(record *records, size_t count) {
