    records[0].value = last_value;

    for (size_t i = 1; i < count; ++i) {
        int new_value;
        do {
            new_value = rand() % 100; // Example range
        } while (new_value == last_value);

        records[i].value = new_value;
        last_value = new_value;
    }

    return 0;
}

int allocate_and_initialize_data(
    size_t offsets_count, long min_offset_range, long max_offset_range,
    size_t keys_count, int *predefined_list, size_t list_size,
    size_t records_count
) {
