#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Assume these are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set flag
} NFAPI_CRC_INDICATION_PDU_T;

void third_party_session_validate(int session_id);
int db_update_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu);

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_pdu_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = malloc(sizeof(Node));
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    // Log addition
    printf("Added PDU with RX_UE_INFORMATION_TAG: %d\n", pdu.RX_UE_INFORMATION_TAG);
}

void update_pdu_in_db(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (third_party_session_validate(current->data.RX_UE_INFORMATION_TAG)) {
            int db_result = db_update_pdu(&current->data);
            if (db_result == 0) {
                printf("PDU with RNTI: %d updated in DB\n", current->data.RNTI);
            } else {
                fprintf(stderr, "DB update failed for PDU with RNTI: %d\n", current->data.RNTI);
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(List* list) {
    Node *current, *tmp;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        tmp = current;
        current = current->next;
        free(tmp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void* pdu_handler_thread(void *arg) {
    List* list = (List*) arg;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Simulate receiving a PDU from network interface
        srand(time(NULL));
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu.CRCFLAG = rand() & 1;

        add_pdu_to_list(list, pdu);

        // Simulate processing time
        sleep(1);
    }

    return NULL;
}

int main() {
    List* list = create_list();

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, pdu_handler_thread, (void*)list) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    update_pdu_in_db(list);

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_list(list);
    return 0;
}
