import java.io.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StateLoader {

    private static final Logger logger = Logger.getLogger(StateLoader.class.getName());
    private final ConcurrentHashMap<String, MoSTState> cache;
    private final int maxCacheSize;
    private int successfulLoads = 0;
    private int failedLoads = 0;

    public StateLoader(int initialMaxCacheSize) {
        this.maxCacheSize = initialMaxCacheSize;
        this.cache = new ConcurrentHashMap<>();
    }

    public MoSTState loadStateFromFile(String filePath) {
        long startTime = System.nanoTime();

        if (cache.containsKey(filePath)) {
            MoSTState cachedObject = cache.get(filePath);
            logger.log(Level.INFO, "Cache hit for file: {0}", filePath);
            successfulLoads++;
            return cachedObject;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object object = ois.readObject();
            if (object instanceof MoSTState) {
                cache.putIfAbsent(filePath, (MoSTState) object);
                manageCacheSize();
                successfulLoads++;
                return (MoSTState) object;
            } else {
                failedLoads++;
                logger.log(Level.WARNING, "Loaded object is not an instance of MoSTState for file: {0}", filePath);
            }
        } catch (IOException | ClassNotFoundException e) {
            failedLoads++;
            logger.log(Level.SEVERE, "Failed to load state from file: " + filePath, e);
        }

        long endTime = System.nanoTime();
        logger.log(Level.INFO, "Load operation took {0} ms", (endTime - startTime) / 1_000_000);

        return null;
    }

    private void manageCacheSize() {
        if (cache.size() > maxCacheSize) {
            // Implement LRU eviction
            String oldestKey = null;
            long oldestAccessTime = Long.MAX_VALUE;

            for (Map.Entry<String, MoSTState> entry : cache.entrySet()) {
                // Assuming each state object has a timestamp field to track access time
                long currentTime = System.nanoTime();
                if (entry.getValue().getLastAccessed() < oldestAccessTime) {
                    oldestKey = entry.getKey();
                    oldestAccessTime = entry.getValue().getLastAccessed();
                }
            }

            if (oldestKey != null) {
                cache.remove(oldestKey);
            }
        }
    }

    public void updateCacheSize(int newSize) {
        this.maxCacheSize = newSize;
        manageCacheSize(); // Adjust the cache immediately to respect new size
    }

    public int getSuccessfulLoads() {
        return successfulLoads;
    }

    public int getFailedLoads() {
        return failedLoads;
    }
}

// Mock of MoSTState class with a method to track last accessed time.
class MoSTState implements Serializable {

    private static final long serialVersionUID = 1L;

    // Mock field for last access timestamp
    private transient long lastAccessedTime;

    public void setLastAccessed() {
        this.lastAccessedTime = System.nanoTime();
    }

    public long getLastAccessed() {
        return lastAccessedTime;
    }
}
