    private readonly ILogger<BatchHttpPostProcessor> _logger;
    private const int MaxSectionId = 1000; // Example permissible range
    private const int MaxElementId = 500;  // Example permissible range
    private const int MaxHtmlContentSize = 1024 * 10; // 10 KB size limit

    public BatchHttpPostProcessor(ILogger<BatchHttpPostProcessor> logger)
    {
        _logger = logger;
    }

    public async Task ProcessUpdatesAsync(string jsonPayload)
    {
        var updateRequest = JsonConvert.DeserializeObject<UpdateRequest>(jsonPayload);

        if (updateRequest?.Updates == null || !updateRequest.Updates.Any())
            throw new ArgumentException("Invalid payload: No updates found.");

        var validatedUpdates = ValidateAndPrepareUpdates(updateRequest.Updates);

        var tasks = validatedUpdates.Select(ProcessSingleUpdateAsync).ToArray();
        await Task.WhenAll(tasks);

        _logger.LogInformation("Processed {0} updates.", updateRequest.Updates.Count);
    }

    private IEnumerable<PageUpdate> ValidateAndPrepareUpdates(List<PageUpdate> updates)
    {
