    for (int attempt = 0; attempt < 3; ++attempt) {
        sessions = (NFAPI_CRC_INDICATION_PDU_T *)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (sessions != NULL) {
            printf("Successfully allocated memory for %zu sessions.\n", n);
            break;
        } else {
