} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
} DynamicList;

DynamicList list = {NULL, 0, 0};

// Function to initialize the dynamic list
void init_list(DynamicList* list) {
    pthread_mutex_lock(&list_mutex);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS);
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = MAX_ELEMENTS;
    pthread_mutex_unlock(&list_mutex);
}

// Function to resize the dynamic list
void resize_list(DynamicList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!temp) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->data = temp;
    list->capacity = new_capacity;
}

// Function to add an element to the dynamic list
void add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list_mutex);

    if (list->size == list->capacity) {
        resize_list(list, list->capacity * 2);
    }

    list->data[list->size++] = element;

    pthread_mutex_unlock(&list_mutex);
}

// Function to update an element in the dynamic list
void update_element(DynamicList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    list->data[index] = element;
    pthread_mutex_unlock(&list_mutex);
}

// Function to retrieve an element from the dynamic list
NFAPI_CRC_INDICATION_PDU_T get_element(DynamicList* list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T element = list->data[index];
    pthread_mutex_unlock(&list_mutex);

    return element;
}

// Background thread function to verify consistency
void* consistency_check(void* arg) {
    while (1) {
        sleep(5);  // Check every 5 seconds

        pthread_mutex_lock(&list_mutex);

        for (size_t i = 0; i < list.size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T element = list.data[i];

            if (!element.rx_ue_info_tag.valid || element.crc_indication_rel8_tag.CRCFLAG < 0) {
                fprintf(stderr, "Inconsistent data found at index %zu\n", i);
            }
        }

        pthread_mutex_unlock(&list_mutex);
    }
}

// Function to start the background consistency checker
void start_consistency_checker() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, consistency_check, NULL) != 0) {
        perror("Failed to create consistency check thread");
        exit(EXIT_FAILURE);
    }

    // Detach the thread to allow it to run independently
    pthread_detach(thread_id);
}

// Function to simulate external data feed integration
void integrate_external_data_feed() {
    while (1) {
        sleep(10);  // Simulate periodic updates every 10 seconds

        pthread_mutex_lock(&list_mutex);

        for (size_t i = 0; i < list.size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T element = list.data[i];

            // Randomly update CRCFLAG to simulate external data feed
            element.crc_indication_rel8_tag.CRCFLAG = rand() % 2;
            list.data[i] = element;
        }

        pthread_mutex_unlock(&list_mutex);
