    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
}

// Cleanup the NFAPIDataList
void cleanupNFAPIDataList(NFAPIDataList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

// Add or update an NFAPI indication
int addOrUpdateNFAPIIndication(NFAPIDataList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    int retry = 0;
    while (retry < MAX_RETRIES) {
        pthread_mutex_lock(&list->lock);

        // Check if update is needed
        for (size_t i = 0; i < list->size; ++i) {
            if (list->data[i].RNTI == pdu.RNTI) {
                list->data[i] = pdu;
                pthread_mutex_unlock(&list->lock);
                return 1; // Updated existing entry
            }
        }

        // Add new entry
        if (list->size >= list->capacity) {
            size_t new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_data) {
                pthread_mutex_unlock(&list->lock);
                retry++;
                sleep(1 << retry); // Exponential backoff
                continue;
            }
            list->data = new_data;
            list->capacity = new_capacity;
        }

        list->data[list->size++] = pdu;
        pthread_mutex_unlock(&list->lock);
        return 0; // Added new entry
    }
    return -1; // Failed after retries
}

// Get the size of the data
size_t getNFAPIDataSize(const NFAPIDataList *list) {
    pthread_mutex_lock((pthread_mutex_t *)&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
    return size;
}

// Export data to file
void exportDataToFile(const NFAPIDataList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// Import data from file
int importDataFromFile(NFAPIDataList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t new_size = list->size; // Read existing data into a temp buffer
    NFAPI_CRC_INDICATION_PDU_T *temp_data = malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) {
        fclose(file);
        return -1;
    }

    fread(temp_data, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    fclose(file);

    pthread_mutex_lock(&list->lock);
    list->data = realloc(list->data, (new_size + INITIAL_CAPACITY) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(temp_data);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(list->data, temp_data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = new_size;
    list->capacity += INITIAL_CAPACITY;
    pthread_mutex_unlock(&list->lock);

    free(temp_data);
    return 0; // Success
}

int main() {
    NFAPIDataList list;
    initNFAPIDataList(&list);

    // Start background consistency check thread
    pthread_t tid;
    if (pthread_create(&tid, NULL, consistencyCheckThread, &list) != 0) {
        perror("Failed to create consistency check thread");
        cleanupNFAPIDataList(&list);
        return EXIT_FAILURE;
    }

    // Example usage: Add or update entries
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 1234, rand() % 2};
    addOrUpdateNFAPIIndication(&list, pdu);

    // Export to file
    exportDataToFile(&list, "nfa_data.bin");

    // Import from file
    importDataFromFile(&list, "nfa_data.bin");

    // Clean up
    cleanupNFAPIDataList(&list);
    pthread_cancel(tid); // Terminate the background thread

    return EXIT_SUCCESS;
}
