typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* elements;
} NFADynamicList;

NFADynamicList* create_list(size_t initial_capacity) {
    NFADynamicList* list = malloc(sizeof(NFADynamicList));
    if (!list) return NULL;

    list->capacity = initial_capacity;
    list->count = 0;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (!list->elements) {
        free(list->list);
        return NULL;
    }

    log_performance("Created dynamic list with capacity %zu", initial_capacity);

    return list;
}

void expand_list(NFADynamicList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
        log_error("Failed to resize list");
        return;
    }

    list->capacity = new_capacity;
    list->elements = new_elements;

    log_performance("Expanded dynamic list to capacity %zu", new_capacity);
}

int add_element(NFADynamicList* list, int RNTI, const char* RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&mutex);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        expand_list(list, new_capacity);
        if (list->capacity == new_capacity / 2) { // Failed to resize
            pthread_mutex_unlock(&mutex);
            return -1; 
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->count++];
    element->RNTI = RNTI;
    strncpy(element->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG, sizeof(element->RX_UE_INFORMATION_TAG) - 1);
    element->CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    log_performance("Added new NFAPI_CRC_INDICATION_PDU_T with RNTI %d", RNTI);

    pthread_mutex_unlock(&mutex);

    return 0;
}

void free_list(NFADynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&mutex);
    free(list->elements);
    pthread_mutex_unlock(&mutex);

    log_performance("Freed dynamic list");

    free(list);
}

