```c
#include <stdio.h>
#include <stdlib.h>
import "lte_types.h" // Assume this header defines LTE_DL_FRAMEINFO and related structures

#define MAX_FRAMES 10000
#define FRAME_DATA_FILE "frame_data.bin"
#define MEMORY_LIMIT (1 * 1024 * 1024 * 1024) // 1GB

typedef struct {
    LTE_DL_FRAMEINFO* frames;
    size_t capacity;
    size_t count;
} FrameManager;

static void load_frame_data(FrameManager* manager);
static int save_frame_data(FrameManager* manager);

FrameManager* create_frame_manager() {
    FrameManager* manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->capacity = 100; // Initial capacity
    manager->count = 0;
    manager->frames = calloc(manager->capacity, sizeof(LTE_DL_FRAMEINFO));

    load_frame_data(manager);
    return manager;
}

void destroy_frame_manager(FrameManager* manager) {
    if (!manager) return;

    save_frame_data(manager);
    free(manager->frames);
    free(manager);
}

int add_frame(FrameManager* manager, const LTE_DL_FRAMEINFO* frame_info) {
    if (!manager || !frame_info) return -1;

    // Validate the frame data
    if (!validate_frame(frame_info)) return -2; 

    // Resize array if necessary
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_DL_FRAMEINFO* new_frames = realloc(manager->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));

        if (!new_frames || ((size_t)new_frames + new_capacity * sizeof(LTE_DL_FRAMEINFO)) > MEMORY_LIMIT) {
            return -3; // Memory limit exceeded or failed to allocate
        }

        manager->capacity = new_capacity;
        manager->frames = new_frames;
    }

    manager->frames[manager->count++] = *frame_info;
    save_frame_data(manager); // Save after every write for persistence

    return 0;
}

static void load_frame_data(FrameManager* manager) {
    FILE* file = fopen(FRAME_DATA_FILE, "rb");
    if (!file) return;

    fread(&manager->capacity, sizeof(size_t), 1, file);
    fread(&manager->count, sizeof(size_t), 1, file);

    manager->frames = realloc(manager->frames, manager->capacity * sizeof(LTE_DL_FRAMEINFO));
    fread(manager->frames, sizeof(LTE_DL_FRAMEINFO), manager->count, file);

    fclose(file);
}

static int save_frame_data(FrameManager* manager) {
    FILE* file = fopen(FRAME_DATA_FILE, "wb");
    if (!file) return -1;

    fwrite(&manager->capacity, sizeof(size_t), 1, file);
    fwrite(&manager->count, sizeof(size_t), 1, file);
