typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    uint32_t rollingChecksum;
} List;

void initializeList(List *list) {
    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->data = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) exit(EXIT_FAILURE);
    list->rollingChecksum = 0;
}

void freeList(List *list) {
    free(list->data);
    list->size = 0;
    list->capacity = 0;
}

int checkRNTIUnique(List *list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == rnti) return 0;
    }
    return 1;
}

void resizeListIfNeeded(List *list) {
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) exit(EXIT_FAILURE);
        list->data = newData;
        list->capacity = newCapacity;
    }
}

void addEntry(List *list, uint32_t tag, uint16_t rnti, int crcflag) {
    resizeListIfNeeded(list);

    if (checkRNTIUnique(list, rnti)) {
        NFAPI_CRC_INDICATION_PDU_T entry = {tag, rnti, {crcflag}};
        list->data[list->size++] = entry;
        // Simple rolling checksum calculation
        list->rollingChecksum += crcflag; 
    }
}

int readIntegersFromFile(FILE *file, int **array, size_t *count) {
    *count = 0;
    int bufferSize = 100;
    *array = malloc(bufferSize * sizeof(int));

    if (!*array) exit(EXIT_FAILURE);

    while (fscanf(file, "%d", &(*array)[*count]) == 1) {
        (*count)++;
        if (*count >= bufferSize) {
            bufferSize *= 2;
            int *tempArray = realloc(*array, bufferSize * sizeof(int));
            if (!tempArray) exit(EXIT_FAILURE);
            *array = tempArray;
        }
    }

    return 0; // Success
}

int findLargestInteger(int *array, size_t count) {
    if (count == 0) return -1; // Or other error code
    int largest = array[0];
    for (size_t i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    List list;
    initializeList(&list);

    // Simulate adding entries
    addEntry(&list, 12345, 6789, rand() % 2);
    addEntry(&list, 54321, 9876, rand() % 2);

    printf("Rolling Checksum: %u\n", list.rollingChecksum);

    FILE *file = stdin;
    int *integers;
    size_t count;

    if (readIntegersFromFile(file, &integers, &count) == 0) {
        int largest = findLargestInteger(integers, count);
        printf("Largest Integer: %d\n", largest);
        free(integers);
    }

    freeList(&list);

    return 0;
}
