#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct CacheNode *next;
} CacheNode;

CacheNode *cache_head = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pi_list(int n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    // Try to fetch from cache first
    pthread_mutex_lock(&cache_lock);
    for (CacheNode **curr = &cache_head; *curr != NULL;) {
        CacheNode *node = *curr;
        if ((*curr)->data && (*curr)->data[0].RX_UE_INFORMATION_TAG == -1) { // Marked as free
            array = node->data;
            *curr = node->next;
            pthread_mutex_unlock(&cache_lock);
            goto populate_data;
        }
        curr = &node->next;
    }
    pthread_mutex_unlock(&cache_lock);

    // Allocate memory if not found in cache
    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL;
    }

populate_data:
    for (int i = 0; i < n; ++i) {
        // Populate structure with pseudo-random CRCFLAG
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        array[i].RNTI = rand() % 1000000 + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2; // Pseudo-random binary value

        // Simple integrity check (e.g., non-zero values)
        if (array[i].RX_UE_INFORMATION_TAG <= 0 || 
            array[i].RNTI <= 0 || 
            array[i].CRC_INDICATION_REL8_TAG < 0 ||
            (array[i].CRCFLAG != 0 && array[i].CRCFLAG != 1)) {
            // Handle memory cleanup on failure
            free(array);
            pthread_mutex_lock(&cache_lock);
            CacheNode *new_node = (CacheNode *)malloc(sizeof(CacheNode));
            if (new_node) {
                new_node->data = array;
                new_node->next = cache_head;
                cache_head = new_node;
            }
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }
    }

    // Cache the newly allocated memory for future use
    pthread_mutex_lock(&cache_lock);
    CacheNode *new_cache_node = (CacheNode *)malloc(sizeof(CacheNode));
    if (new_cache_node) {
        new_cache_node->data = array;
        new_cache_node->next = cache_head;
        cache_head = new_cache_node;

        // Mark the first element as free for reuse
        array[0].RX_UE_INFORMATION_TAG = -1; 
    }
    pthread_mutex_unlock(&cache_lock);

    return array;
}

void cleanup_cache() {
    pthread_mutex_lock(&cache_lock);
    CacheNode *current = cache_head, *next_node;
    while (current) {
        next_node = current->next;
        free(current->data);
        free(current);
        current = next_node;
    }
    cache_head = NULL;
    pthread_mutex_unlock(&cache_lock);
}

int main() {
    int n = 10; // Example input
    NFAPI_CRC_INDICATION_PDU_T *result = allocate_nfa_pi_list(n);

    if (result) {
        for (int i = 0; i < n; ++i) {
            printf("Entry %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
                   i, result[i].RX_UE_INFORMATION_TAG, result[i].RNTI,
                   result[i].CRC_INDICATION_REL8_TAG, result[i].CRCFLAG);
        }
    } else {
        printf("Memory allocation failed.\n");
    }

    // Cleanup after use
    free(result);

    // Ensure cleanup of cache
    atexit(cleanup_cache);

    return 0;
}
```

This code defines a function `allocate_nfa_pi_list` that dynamically allocates memory for an array of structures based on the user input. It includes error handling, caching to optimize frequent allocations, and integrity checks to ensure data validity after population. The cache is designed to be thread-safe using mutex locks, ensuring safe concurrent access.']

