} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* init_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node* node) {
    free(node);
}

void clear_and_free_all_memory(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void populate_randomly(Node* node) {
    node->data.RX_UE_INFORMATION_TAG = rand() % 1000;
    node->data.RNTI = rand() % 500;
    node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}

Node* create_node() {
    Node* new_node = malloc(sizeof(Node));
    populate_randomly(new_node);
    return new_node;
}

void insert(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node();
    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

int get_list_size(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    int size = 0;
    Node* current = list->head;
    while (current != NULL) {
        ++size;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return size;
}

void update_resource(LinkedList* list, unsigned int RNTI, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            memcpy(&current->data, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_resource(LinkedList* list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->current->next;
    }

    if (current != NULL) { // Found the node to delete
        if (prev == NULL) { // Node is head
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free_node(current);
    }

    pthread_mutex_unlock(&list->lock);
}

int fetch_from_external_source(int attempt) {
    // Simulate fetching from an external source with exponential backoff
    if (attempt > RETRY_MAX_ATTEMPTS) return -1;

    // Random failure simulation for demonstration purposes
    int success = rand() % 2;
    if (!success && attempt < RETRY_MAX_ATTEMPTS) {
        int delay = pow(2, attempt);
        sleep(delay); // Exponential backoff
        return fetch_from_external_source(attempt + 1);
    }

    return success ? 0 : -1; // Return success or failure
}

void put_resource_with_retries(LinkedList* list, unsigned int RNTI, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (fetch_from_external_source(0) == 0) {
        update_resource(list, RNTI, new_data);
    } else {
        // Fallback: Use local cache or heuristic
        printf("External source unavailable, using fallback.\n");
    }
}

void delete_and_validate(LinkedList* list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (current == NULL) { // Resource not found
        printf("Resource with RNTI %u does not exist.\n", RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* to_delete = current;
    if (to_delete->data.RX_UE_INFORMATION_TAG != 0) { // Validation check
        delete_resource(list, RNTI); 
    } else {
        printf("Resource validation failed. Deletion aborted.\n");
    }

    pthread_mutex_unlock(&list->lock);
}

