int isValidDomain(const char* domain, const char* allowed_domains[], int count) {
    for (int i = 0; i < count; ++i) {
        if (strcmp(domain, allowed_domains[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

void logResolutionAttempt(const char* hostname, const char* ip_address, int success) {
