int resolveHostname(const char* hostname, HostnameResolutionResult* result, 
                    ConcurrencyControl* control, const char* allowed_domains[], int retries) {
    if (!isValidDomain(hostname, allowed_domains, ALLOWED_DOMAINS_COUNT)) {
        return -1;
    }

    pthread_mutex_lock(&control->lock);
    while (control->active_requests >= MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&control->cond, &control->lock);
    }
    control->active_requests++;
    pthread_mutex_unlock(&control->lock);

    int status = resolveHostnameAsync(result, control, allowed_domains, retries);

    pthread_mutex_lock(&control->lock);
    control->active_requests--;
    pthread_cond_signal(&control->cond);
    pthread_mutex_unlock(&control->lock);

    return status;
}

int resolveHostnameAsync(HostnameResolutionResult* result, ConcurrencyControl* control,
                         const char* allowed_domains[], int retries) {
    struct addrinfo hints = {0};
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    for (int attempt = 0; attempt <= retries; ++attempt) {
        status = getaddrinfo(result->hostname, NULL, &hints, &res);
        if (status == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                void *addr;
                if (p->ai_family == AF_INET) { // IPv4
                    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                    addr = &(ipv4->sin_addr);
                } else { // IPv6
                    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                    addr = &(ipv6->sin6_addr);
                }
                inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
                strncpy(result->ip_address, ipstr, INET6_ADDRSTRLEN - 1);
                result->valid = 1;

                logResolutionAttempt(result->hostname, result->ip_address, 1);
                freeaddrinfo(res);
                return 0;
            }
        } else {
            if (attempt == retries) {
                logResolutionAttempt(result->hostname, "N/A", 0);
            }
        }
    }

    result->valid = 0;
    freeaddrinfo(res);
    return -1;
}

void manageNFAPIDescriptions(NFAPI_CRC_INDICATION_PDU_T* pduList, size_t numPdus,
                             const char** hostnames, size_t numHostnames) {
    ConcurrencyControl control = {PTHREAD_MUTEX_INITIALIZER, 0, PTHREAD_COND_INITIALIZER};
    HostnameResolutionResult results[numHostnames];

    const char* allowed_domains[ALLOWED_DOMAINS_COUNT] = {"allowed.com", "anotherallowed.com"};

    for (size_t i = 0; i < numHostnames; ++i) {
        strncpy(results[i].hostname, hostnames[i], sizeof(results[i].hostname) - 1);
        results[i].valid = 0;
        resolveHostname(hostnames[i], &results[i], &control, allowed_domains, MAX_RETRIES);
    }

    // Clean up
    pthread_mutex_destroy(&control.lock);
    pthread_cond_destroy(&control.cond);

    for (size_t i = 0; i < numHostnames; ++i) {
        if (results[i].valid) {
            printf("Resolved %s to %s\n", results[i].hostname, results[i].ip_address);
        }
    }
}
