#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define structure for CRC Indication PDU
typedef struct {
    int16_t RX_UE_INFORMATION_TAG; // assuming 2-byte tag
    uint8_t RNTI[5];               // assuming 5-byte RNTI, adjust as needed
    struct {
        uint32_t CRC_INDICATION_REL8_TAG;
        uint8_t CRCFLAG;           // Randomly set flag
    } crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to manage dynamic list of records
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t totalRecords;
    size_t capacity;
    pthread_mutex_t lock;
    void **pointerArray; // Secondary array for efficient pointer-based access
} RecordManager;

// Hash function to generate unique identifiers
uint32_t hashRecord(const NFAPI_CRC_INDICATION_PDU_T *record) {
    uint32_t hash = 0;
    // Simple hash based on RNTI and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < 5; ++i) {
        hash ^= record->RNTI[i];
    }
    hash ^= record->crcTag.CRC_INDICATION_REL8_TAG;
    return hash;
}

// Initialize the RecordManager
void initRecordManager(RecordManager *manager, size_t initialCapacity) {
    if (initialCapacity == 0) {
        fprintf(stderr, "Error: Initial capacity cannot be zero.\n");
        exit(EXIT_FAILURE);
    }

    manager->records = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    manager->pointerArray = malloc(initialCapacity * sizeof(void *));
    if (!manager->pointerArray) {
        perror("Failed to allocate memory for pointer array");
        free(manager->records);
        exit(EXIT_FAILURE);
    }

    manager->totalRecords = 0;
    manager->capacity = initialCapacity;

    pthread_mutex_init(&manager->lock, NULL);

    printf("RecordManager initialized with capacity %zu\n", initialCapacity);
}

// Resize the RecordManager when needed
void resizeRecordManager(RecordManager *manager) {
    size_t newCapacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newRecords = realloc(manager->records, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    void **newPointerArray = realloc(manager->pointerArray, newCapacity * sizeof(void *));

    if (!newRecords || !newPointerArray) {
        perror("Failed to reallocate memory for records or pointer array");
        // Graceful deallocation
        free(manager->records);
        free(manager->pointerArray);
        pthread_mutex_destroy(&manager->lock);
        exit(EXIT_FAILURE);
    }

    manager->records = newRecords;
    manager->pointerArray = newPointerArray;
    manager->capacity = newCapacity;

    printf("RecordManager resized to capacity %zu\n", newCapacity);
}

// Add a record to the RecordManager
void addRecord(RecordManager *manager, const NFAPI_CRC_INDICATION_PDU_T *record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->totalRecords >= manager->capacity) {
        resizeRecordManager(manager);
    }

    // Check for duplicates using hash function
    uint32_t recordHash = hashRecord(record);
    for (size_t i = 0; i < manager->totalRecords; ++i) {
        if (hashRecord(&manager->records[i]) == recordHash) {
            printf("Duplicate record detected. Skipping insertion.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    // Copy new record and set random CRCFLAG
    manager->records[manager->totalRecords] = *record;
    manager->records[manager->totalRecords].crcTag.CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    // Update pointer array for quick access
    manager->pointerArray[manager->totalRecords] = &manager->records[manager->totalRecords];

    ++manager->totalRecords;

    pthread_mutex_unlock(&manager->lock);
}

// Free the resources used by RecordManager
void freeRecordManager(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->records);
    free(manager->pointerArray);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    // Example usage:
    RecordManager manager;
    initRecordManager(&manager, 10); // Start with initial capacity of 10

    NFAPI_CRC_INDICATION_PDU_T exampleRecord = {{.RX_UE_INFORMATION_TAG = 1}, {0x01, 0x02, 0x03, 0x04, 0x05}, {.CRC_INDICATION_REL8_TAG = 123456}};

    addRecord(&manager, &exampleRecord);

    // Add more records as needed...

    freeRecordManager(&manager);

    return 0;
}
