#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG; // Randomly set between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define MAX_SIZE 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ListManager;

ListManager* list_manager_create() {
    ListManager *manager = (ListManager*)malloc(sizeof(ListManager));
    manager->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void list_manager_resize(ListManager *manager) {
    if (manager->count >= manager->capacity && manager->capacity < MAX_SIZE) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list) {
            manager->list = new_list;
            manager->capacity = new_capacity;
        }
    }
}

void list_manager_cleanup(ListManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->list);
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    pthread_mutex_unlock(&manager->lock);
}

int add_pdu(ListManager *manager, int RX_UE_INFO_TAG, int RNTI) {
    pthread_mutex_lock(&manager->lock);

    list_manager_resize(manager);

    if (manager->count < manager->capacity) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = RX_UE_INFO_TAG;
        pdu.RNTI = RNTI;
        pdu.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        manager->list[manager->count++] = pdu;

        pthread_mutex_unlock(&manager->lock);
        return 0; // Success
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Failure, list is full
}

void list_manager_destroy(ListManager *manager) {
    list_manager_cleanup(manager);
    free(manager);
    pthread_mutex_destroy(&manager->lock);
}
