#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

typedef struct {
    record *records;
    long *offsets;
    int *keys;
    size_t capacity;
    pthread_mutex_t lock;
} memory_manager;

void init_random() {
    srand((unsigned)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

memory_manager* create_memory_manager(size_t initial_size) {
    if (initial_size == 0) initial_size = INITIAL_SIZE;

    memory_manager *mm = malloc(sizeof(memory_manager));
    if (!mm) return NULL;

    mm->records = aligned_alloc(64, sizeof(record) * initial_size);
    mm->offsets = aligned_alloc(64, sizeof(long) * initial_size);
    mm->keys = aligned_alloc(64, sizeof(int) * initial_size);

    if (!mm->records || !mm->offsets || !mm->keys) {
        free(mm->records);
        free(mm->offsets);
        free(mm->keys);
        free(mm);
        return NULL;
    }

    mm->capacity = initial_size;
    pthread_mutex_init(&mm->lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        mm->records[i].value = random_int(1, 100);
        mm->records[i].offset_ptr = &mm->offsets[i];
        mm->records[i].key_ptr = &mm->keys[i];
    }

    return mm;
}

int resize_memory_manager(memory_manager *mm, size_t new_size) {
    pthread_mutex_lock(&mm->lock);

    if (new_size <= mm->capacity) {
        pthread_mutex_unlock(&mm->lock);
        return 0; // No resizing needed
    }

    record *new_records = aligned_alloc(64, sizeof(record) * new_size);
    long *new_offsets = aligned_alloc(64, sizeof(long) * new_size);
    int *new_keys = aligned_alloc(64, sizeof(int) * new_size);

    if (!new_records || !new_offsets || !new_keys) {
        free(new_records);
        free(new_offsets);
        free(new_keys);
        pthread_mutex_unlock(&mm->lock);
        return -1;
    }

    memcpy(new_records, mm->records, sizeof(record) * mm->capacity);
    memcpy(new_offsets, mm->offsets, sizeof(long) * mm->capacity);
    memcpy(new_keys, mm->keys, sizeof(int) * mm->capacity);

    for (size_t i = mm->capacity; i < new_size; ++i) {
        new_records[i].value = random_int(1, 100);
        new_records[i].offset_ptr = &new_offsets[i];
        new_records[i].key_ptr = &new_keys[i];
    }

    free(mm->records);
    free(mm->offsets);
    free(mm->keys);

    mm->records = new_records;
    mm->offsets = new_offsets;
    mm->keys = new_keys;
    mm->capacity = new_size;

    pthread_mutex_unlock(&mm->lock);
    return 0;
}

void serialize_records(memory_manager *mm, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&mm->capacity, sizeof(size_t), 1, file);

    for (size_t i = 0; i < mm->capacity; ++i) {
        fwrite(&(mm->records[i].value), sizeof(int), 1, file);
        fwrite(mm->records[i].offset_ptr, sizeof(long), 1, file);
        fwrite(mm->records[i].key_ptr, sizeof(int), 1, file);
    }

    fclose(file);
}

int deserialize_records(memory_manager *mm, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    if (resize_memory_manager(mm, new_size) != 0) {
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < mm->capacity; ++i) {
        fread(&(mm->records[i].value), sizeof(int), 1, file);
        fread(mm->records[i].offset_ptr, sizeof(long), 1, file);
        fread(mm->records[i].key_ptr, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

void free_memory_manager(memory_manager *mm) {
    pthread_mutex_lock(&mm->lock);

    free(mm->records);
    free(mm->offsets);
    free(mm->keys);

    pthread_mutex_unlock(&mm->lock);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}
```

### Key Points:
- **Memory Alignment**: Uses `aligned_alloc` for cache optimization.
- **Random Number Generation**: Uses a simple `rand()` function, suitable for non-critical sections. Consider more sophisticated RNGs like PCG if needed.
- **Dynamic Resizing**: Efficiently handles resizing with minimal data loss.
- **Serialization/Deserialization**: Implements binary format to balance efficiency and simplicity.
- **Thread Safety**: Utilizes mutexes to ensure safe concurrent access.
- **Error Handling**: Gracefully manages memory allocation failures.']

