    if(ptr != NULL) {
        pthread_rwlock_wrlock(&list_lock);
        *(NFAPI_CRC_INDICATION_PDU_T*)ptr = (NFAPI_CRC_INDICATION_PDU_T){0};
        pool_index--;
        pthread_rwlock_unlock(&list_lock);
    }
}

// Validation function
