    if (!pdu || pdu->ue_info.rnti < 0) { // Simplistic check example
        log_error("Structure validation failed");
    }
}

// Add node to list (thread-safe)
void add_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = allocate_pool();
    if (!new_node) return; // Memory allocation failure

    memcpy(&new_node->data, &data, sizeof(data));

    pthread_rwlock_wrlock(&list_lock);
    new_node->next = head;
    head = new_node;
    pthread_rwlock_unlock(&list_lock);

    validate_structure(&data);  // Validate each structure added
}

// Remove node from list (thread-safe)
void remove_node(int rnti) {
    pthread_rwlock_wrlock(&list_lock);
    Node *current = head, *prev = NULL;

    while (current != NULL && current->data.ue_info.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Not found
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    if (prev == NULL) { // Head node
        head = current->next;
    } else {
        prev->next = current->next;
    }

    deallocate_pool(current);

    pthread_rwlock_unlock(&list_lock);
}

// Clean up resources
void cleanup_list() {
    pthread_rwlock_wrlock(&list_lock);
    Node *current = head, *next;

    while (current != NULL) {
        next = current->next;
        deallocate_pool(current);
        current = next;
    }
    head = NULL;

    pool_index = 0; // Reset pool
    pthread_rwlock_unlock(&list_lock);
}

// Initialize logging framework (could be more sophisticated)
void init_logging() {
