#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfo;
    CRC_INDICATION_REL8_TAG crcTag;
    // Add other necessary fields if needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
size_t currentSize = 0;

bool isRNTIUnique(int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.ueInfo.RNTI == rnti) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void logIssue(const char* message) {
    fprintf(stderr, "%s\n", message);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void addNode(NFAPI_CRC_INDICATION_PDU_T data) {
    if (currentSize >= MAX_LIST_SIZE) {
        logIssue("Maximum list size reached. Cannot add more nodes.");
        return;
    }

    if (!isRNTIUnique(data.ueInfo.RNTI)) {
        char message[100];
        sprintf(message, "Duplicate RNTI %d detected. Skipping node.", data.ueInfo.RNTI);
        logIssue(message);
        return;
    }

    Node* newNode = createNode(data);
    if (!newNode) {
        return; // Memory allocation failed
    }

    newNode->next = head;
    head = newNode;
    currentSize++;
}

void freeList() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    currentSize = 0;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.RNTI = 100}, {.CRCFLAG = rand() % 2}};
    addNode(pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{.RNTI = 101}, {.CRCFLAG = rand() % 2}};
    addNode(pdu2);

    NFAPI_CRC_INDICATION_PDU_T pdu3 = {{.RNTI = 100}, {.CRCFLAG = rand() % 2}}; // Duplicate RNTI
    addNode(pdu3);

    freeList();
    return 0;
}
