#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_CACHE_SIZE 1000 // Define this externally or via configuration

// Cache item to be used in the LRU cache
typedef struct CacheItem {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CacheItem* next;
    struct CacheItem* prev;
} CacheItem;

// Global variables for caching and logging
CacheItem *cache_head = NULL, *cache_tail = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
size_t max_cache_size = MAX_CACHE_SIZE;
int cache_hits = 0, total_allocations = 0, allocations_since_last_log = 0;

// Helper function to initialize a new cache item
CacheItem* create_cache_item() {
    CacheItem* item = (CacheItem*)malloc(sizeof(CacheItem));
    if (!item) return NULL;
    return item;
}

// Function to add an item to the front of the LRU list
void push_front(CacheItem* item) {
    pthread_mutex_lock(&cache_lock);

    item->next = cache_head;
    item->prev = NULL;

    if (cache_head != NULL) {
        cache_head->prev = item;
    }

    cache_head = item;

    if (cache_tail == NULL) {
        cache_tail = item;
    }

    pthread_mutex_unlock(&cache_lock);
}

// Function to remove an item from the LRU list
void pop_back() {
    pthread_mutex_lock(&cache_lock);

    if (cache_tail != NULL) {
        CacheItem* temp = cache_tail;

        if (cache_head == cache_tail) {
            cache_head = NULL;
        } else {
            cache_tail->prev->next = NULL;
        }
        cache_tail = cache_tail->prev;

        free(temp);
    }

    pthread_mutex_unlock(&cache_lock);
}

// Function to move an item to the front of the LRU list
void move_to_front(CacheItem* item) {
    if (item == cache_head) return;

    if (item->prev != NULL) {
        item->prev->next = item->next;
    }

    if (item->next != NULL) {
        item->next->prev = item->prev;
    }

    if (cache_tail == item) {
        cache_tail = item->prev;
    }

    item->prev = NULL;
    item->next = cache_head;
    cache_head->prev = item;

    cache_head = item;
}

// Function to get an item from the LRU list
CacheItem* get_cache_item() {
    pthread_mutex_lock(&cache_lock);

    if (cache_tail) {
        CacheItem* item = cache_tail;
        pop_back();
        push_front(item);
        return item;
    }

    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// Function to manage NFAPI_CRC_INDICATION_PDU_T dynamically
int manage_nfaapi_crc_indications(size_t n, uint32_t rnti_min, uint32_t rnti_max, NFAPI_CRC_INDICATION_PDU_T** result) {
    size_t allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T* data = NULL;

    pthread_mutex_lock(&cache_lock);
    while (allocated < n && cache_tail != NULL) {
        CacheItem* item = get_cache_item();

        if (!item) break;

        data[allocated++] = item->data;
        total_allocations++;
        allocations_since_last_log++;

        if (allocations_since_last_log >= 10) { // Log every 10 allocations
            printf("Cache hits: %d, Total allocations: %d\n", cache_hits, total_allocations);
            allocations_since_last_log = 0;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    data = realloc(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (allocated + n));

    if (!data) {
        for (size_t i = 0; i < allocated; ++i) {
            free_cache_item((CacheItem*)&data[i]);
        }
        return -1;
    }

    srand(time(NULL)); // Seed random number generator

    bool* rnti_map = calloc(rnti_max + 1, sizeof(bool));

    for (size_t i = allocated; i < n; ++i) {
        uint32_t rnti;
        do {
            rnti = rand() % (rnti_max - rnti_min + 1) + rnti_min;
        } while (rnti_map[rnti]);

        data[i].RX_UE_INFORMATION_TAG = rand(); // Random value for example
        data[i].RNTI = rnti;
        data[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF; // Random byte
        data[i].CRCFLAG = rand() % 2;

        rnti_map[rnti] = true;
    }

    free(rnti_map);

    *result = data;
    return allocated + n;
}

// Function to release all cached items
void release_cache() {
    pthread_mutex_lock(&cache_lock);
    while (cache_head != NULL) {
        CacheItem* temp = cache_head;
        cache_head = cache_head->next;
        free(temp);
    }
    cache_tail = NULL;
    pthread_mutex_unlock(&cache_lock);
}

// Function to release a single cache item
void free_cache_item(CacheItem* item) {
    pthread_mutex_lock(&cache_lock);

    if (item == cache_head) {
        pop_back();
    } else if (item->prev != NULL) {
        item->prev->next = item->next;
    }

    if (item->next != NULL) {
        item->next->prev = item->prev;
    }

    if (cache_tail == item) {
        cache_tail = item->prev;
    }

    pthread_mutex_unlock(&cache_lock);
    free(item);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
    size_t num_structures = 1000; // Example number of structures to manage

    if (manage_nfaapi_crc_indications(num_structures, 1, 65535, &structures) == -1) {
        fprintf(stderr, "Memory allocation failed\n");
    } else {
        printf("Successfully managed %zu NFAPI_CRC_INDICATION_PDU_T structures\n", num_structures);
        // Do something with the structures

        release_cache();
    }

    free(structures);

    return 0;
}
```

