AuthTokenCacheEntry authTokenCache[MAX_TOKENS];
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
int cacheCount = 0;

// Dummy function to mimic external authentication
char* authenticateUser(const char* username) {
    // Simulate network delay and token generation
    time.sleep(1);
    char *token = malloc(50); 
    snprintf(token, 50, "token-%s", username);
    return token;
}

// Function to get or create a user access token from cache
char* getUserAccessToken(const char* username) {
    pthread_mutex_lock(&cacheMutex);

    // Check if the token is in the cache and valid
    for (int i = 0; i < cacheCount; ++i) {
        if (strcmp(authTokenCache[i].username, username) == 0 && 
            time(NULL) < authTokenCache[i].expiry) {
            pthread_mutex_unlock(&cacheMutex);
            return authTokenCache[i].token;
        }
    }

    // Not found or expired, authenticate and cache the new token
    char* token = authenticateUser(username);

    if (cacheCount < MAX_TOKENS) {
        authTokenCache[cacheCount++] = (AuthTokenCacheEntry){ .username = strdup(username), 
                                                             .token = token,
                                                             .expiry = time(NULL) + TOKEN_EXPIRY_SECONDS };
    } else {
        // Simple eviction policy: remove the first entry (could be improved)
        free(authTokenCache[0].username);
        free(authTokenCache[0].token);
        for (int i = 1; i < MAX_TOKENS; ++i) {
            authTokenCache[i - 1] = authTokenCache[i];
        }
        authTokenCache[MAX_TOKENS - 1] = (AuthTokenCacheEntry){ .username = strdup(username), 
                                                               .token = token, 
                                                               .expiry = time(NULL) + TOKEN_EXPIRY_SECONDS };
    }

    pthread_mutex_unlock(&cacheMutex);
    return token;
}

