    uint32_t RNTI;
} UniqueRNTI;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduList;

static thread_safe_hash_table_t rnti_table;
static atomic_bool config_update_pending = ATOMIC_VAR_INIT(false);

void initialize_system() {
    pthread_mutex_init(&rnti_table.mutex, NULL);
}

uint32_t generate_unique_rnti() {
    uint32_t rnti;
    do {
        rnti = rand() % MAX_RNTI;
    } while (!thread_safe_hash_table_try_insert(&rnti_table, &rnti));
    return rnti;
}

bool allocate_pdu_list(PduList *list, size_t initial_capacity) {
    list->pdus = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) return false;
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    return true;
}

void free_pdu_list(PduList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
}

bool add_pdu(PduList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void update_configuration() {
    if (atomic_load(&config_update_pending)) {
        // Fetch and apply configuration changes from the database
        atomic_store(&config_update_pending, false);
    }
}

void* manage_pdus(void *arg) {
    PduList list;
    if (!allocate_pdu_list(&list, CACHE_SIZE)) return NULL;

    while (true) {
        update_configuration();

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = generate_unique_rnti();
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!add_pdu(&list, pdu)) {
            logging_framework_log("Failed to add PDU.");
        }
    }

    free_pdu_list(&list);
    return NULL;
}

int main() {
    srand(time(NULL));
    initialize_system();

    pthread_t threads[100];
    for (int i = 0; i < 100; ++i) {
        pthread_create(&threads[i], NULL, manage_pdus, NULL);
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
