    int count;
    pthread_mutex_t lock;
} PduManager;

// Initialize PDU Manager
void initPduManager(PduManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Add a new MAC PDU to the list
int addMacPdu(PduManager *manager, MacPduType type, size_t bufferSize) {
    if (manager->count >= MAX_PDUS) return -1; // No space left

    pthread_mutex_lock(&manager->lock);

    LteMacPdu *pdu = &manager->pdus[manager->count++];
    pdu->type = type;
    pdu->bufferSize = bufferSize;

    pdu->buffer = (uint8_t *)malloc(bufferSize);
    if (!pdu->buffer) {
        // Handle memory allocation failure
        manager->count--;
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failed
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Remove a MAC PDU from the list by index
int removeMacPdu(PduManager *manager, int index) {
    if (index < 0 || index >= manager->count) return -1; // Invalid index

    pthread_mutex_lock(&manager->lock);

    free(manager->pdus[index].buffer);
    memmove(&manager->pdus[index], &manager->pdus[index + 1],
            (manager->count - index - 1) * sizeof(LteMacPdu));
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Free all allocated memory and reset the PDU manager
void freePduManager(PduManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->pdus[i].buffer);
    }
    pthread_mutex_destroy(&manager->lock);
}
