#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include "network_management_api.h"
#include "database_api.h"
#include "logging_framework.h"

#define MAX_RNTI 1048575 // Example max RNTI value for LTE

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t RRC_UE_Information;
    uint16_t RNTI;
    uint8_t CRC_Indication;
    uint8_t CRCFlag;
} LTE_Uplink_RRC_Indication;

// Hash table for RNTI uniqueness checks
typedef struct RntiNode {
    uint16_t rnti;
    struct RntiNode* next;
} RntiNode;

RntiNode* hashTable[1048576] = { NULL };
pthread_mutex_t mutexes[256]; // Separate mutex for each bucket

// Helper function to initialize mutexes
void initMutexes() {
    for (int i = 0; i < 256; i++) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

uint32_t hashRNTI(uint16_t rnti) {
    return rnti % 1048576;
}

int isUniqueRNTI(uint16_t rnti) {
    uint32_t index = hashRNTI(rnti);
    pthread_mutex_lock(&mutexes[index & 255]);

    RntiNode* node = hashTable[index];
    while (node != NULL) {
        if (node->rnti == rnti) {
            pthread_mutex_unlock(&mutexes[index & 255]);
            return 0;
        }
        node = node->next;
    }

    // Insert new RNTI
    RntiNode* newNode = malloc(sizeof(RntiNode));
    if (!newNode) {
        pthread_mutex_unlock(&mutexes[index & 255]);
        log_error("Memory allocation failed for RNTI hash table.");
        return -1;
    }
    newNode->rnti = rnti;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;

    pthread_mutex_unlock(&mutexes[index & 255]);
    return 1;
}

void freeHashTable() {
    for (int i = 0; i < 1048576; i++) {
        RntiNode* node = hashTable[i];
        while (node != NULL) {
            RntiNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
}

