typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PduList;

PduList* create_pdu_list(size_t max_size) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->capacity = max_size;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_pdu(PduList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !list) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdus[i].rnti == pdu->rnti) {
            pthread_mutex_unlock(&list->lock);
            return -3; // Duplicate RNTI
        }
    }

    if (!validate_crc_indication(&(pdu->crc_indication_rel8_tag))) {
        pthread_mutex_unlock(&list->lock);
        return -4; // Invalid CRC_INDICATION_REL8_TAG
    }

    list->pdus[list->count++] = *pdu;
    log_creation(pdu);

    pthread_mutex_unlock(&list->lock);
    output_to_protocol(pdu);

    return 0;
}

void destroy_pdu_list(PduList* list) {
    if (!list) return;

    free(list->pdus);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
