// Definitions for structures
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Configuration structure for cryptographic settings
typedef struct {
    const char* cipher_mode;
    size_t key_size;
} CryptoConfig;

// Function prototypes
Node* create_nfa_list(size_t n);
void free_nfa_list(Node* head);
CryptoConfig configure_crypto(const char* mode, size_t key_size);

// Main function to implement the task
Node* create_and_configure_nfa_list(size_t n, const char* cipher_mode, size_t key_size) {
    Node* head = create_nfa_list(n);
    CryptoConfig config = configure_crypto(cipher_mode, key_size);

    // Print configuration for demonstration purposes
    printf("Cipher Mode: %s, Key Size: %zu bytes\n", config.cipher_mode, config.key_size);

    return head;
}

// Function to dynamically create and populate the list
Node* create_nfa_list(size_t n) {
    Node* head = NULL;
    Node* tail = NULL;

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < n; ++i) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            free_nfa_list(head);
            return NULL;
        }

        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        newNode->data.RNTI = rand() % 10000; // Example value
        newNode->data.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG

        newNode->next = NULL;

        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}

// Function to free the list
void free_nfa_list(Node* head) {
    Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Configuration function for cryptographic settings
CryptoConfig configure_crypto(const char* mode, size_t key_size) {
    CryptoConfig config;
    strcpy(config.cipher_mode, mode);
    config.key_size = key_size;

    return config;
}

// Example serialization and deserialization functions (simple representation)
void serialize_node(Node* node, FILE* file) {
    while (node) {
        fwrite(&node->data.RX_UE_INFORMATION_TAG, sizeof(node->data.RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&node->data.RNTI, sizeof(node->data.RNTI), 1, file);
        fwrite(&node->data.CRC_INDICATION_REL8_TAG, sizeof(node->data.CRC_INDICATION_REL8_TAG), 1, file);
        node = node->next;
    }
}

void deserialize_node(Node** head, FILE* file) {
    size_t size_RXT = sizeof(NFAPI_CRC_INDICATION_PDU_T.RX_UE_INFORMATION_TAG);
    size_t size_RNTI = sizeof(NFAPI_CRC_INDICATION_PDU_T.RNTI);
    size_t size_CRC = sizeof(NFAPI_CRC_INDICATION_PDU_T.CRC_INDICATION_REL8_TAG);

    Node* head_ref = NULL;
    Node* tail_ref = NULL;

    while (!feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (fread(&data.RX_UE_INFORMATION_TAG, size_RXT, 1, file) == 1 &&
            fread(&data.RNTI, size_RNTI, 1, file) == 1 &&
            fread(&data.CRC_INDICATION_REL8_TAG, size_CRC, 1, file) == 1) {

            Node* newNode = malloc(sizeof(Node));
            if (!newNode) {
                fprintf(stderr, "Memory allocation failed\n");
                free_nfa_list(head_ref);
                break;
            }

            newNode->data = data;
            newNode->next = NULL;

            if (!head_ref) {
                head_ref = tail_ref = newNode;
            } else {
                tail_ref->next = newNode;
                tail_ref = newNode;
            }
        }
    }

    *head = head_ref;
}

int main() {
    size_t n = 10; // Number of nodes
    Node* list = create_and_configure_nfa_list(n, "ECB", 8);

    FILE* file = fopen("nfa_data.bin", "wb");
    if (file) {
        serialize_node(list, file);
        fclose(file);
    }

    Node* deserialized_head = NULL;
    file = fopen("nfa_data.bin", "rb");
    if (file) {
        deserialize_node(&deserialized_head, file);
        fclose(file);
    }

    free_nfa_list(list);
    free_nfa_list(deserialized_head);

    return 0;
}
