#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MESSAGES 1000

typedef struct {
    int sender_id;
    time_t timestamp;
    size_t payload_size;
    char *payload;
} Message;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

Message* initialize_messages(int num_messages, const char **log_errors) {
    if (num_messages <= 0 || num_messages > MAX_MESSAGES) {
        if (log_errors) {
            *log_errors = "Number of messages must be positive and less than or equal to MAX_MESSAGES.";
        }
        return NULL;
    }

    Message *messages = malloc(num_messages * sizeof(Message));
    if (!messages) {
        if (log_errors) {
            *log_errors = "Failed to allocate memory for message array.";
        }
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_messages; ++i) {
        messages[i].sender_id = rand() % 1000 + 1; // Random sender ID between 1 and 1000
        messages[i].timestamp = time(NULL);
        messages[i].payload_size = rand() % 1024 + 1; // Payload size between 1 and 1024 bytes

        messages[i].payload = malloc(messages[i].payload_size);
        if (!messages[i].payload) {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Failed to allocate memory for message payload at index %d.", i);
            log_error(error_message);

            // Free previously allocated messages
            for (int j = 0; j < i; ++j) {
                free(messages[j].payload);
            }
            free(messages);
            if (log_errors) {
                *log_errors = error_message;
            }
            return NULL;
        }

        // Fill payload with random data
        for (size_t j = 0; j < messages[i].payload_size; ++j) {
            messages[i].payload[j] = rand() % 256; // Random byte between 0 and 255
        }
    }

    return messages;
}

void free_messages(Message *messages, int num_messages) {
    if (!messages) {
        return;
    }

    for (int i = 0; i < num_messages; ++i) {
        free(messages[i].payload);
    }

    free(messages);
}
```

