typedef struct {
    int id;
    char **bearer_ids; // Array of active radio bearer IDs
    size_t num_bearers;
} QoSConfig;

typedef struct {
    int ue_id;
    QoSConfig qos_config;
} LTEUEContext;

typedef struct {
    LTEUEContext *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} UEContextManager;

// Function prototypes
int initialize_manager(UEContextManager *manager);
void cleanup_manager(UEContextManager *manager);
int add_ue_context(UEContextManager *manager, int ue_id, QoSConfig qos_config);
int update_ue_context_qos(UEContextManager *manager, int ue_id, QoSConfig new_qos_config);
int delete_ue_context(UEContextManager *manager, int ue_id);

// Initialize the context manager
int initialize_manager(UEContextManager *manager) {
    if (!manager) return -1;

    manager->contexts = malloc(INITIAL_CAPACITY * sizeof(LTEUEContext));
    if (!manager->contexts) return -1;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

// Cleanup resources
void cleanup_manager(UEContextManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i].qos_config.bearer_ids);
    }

    free(manager->contexts);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Add a new UE context
int add_ue_context(UEContextManager *manager, int ue_id, QoSConfig qos_config) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTEUEContext *new_contexts = realloc(manager->contexts, new_capacity * sizeof(LTEUEContext));

        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    LTEUEContext context = {ue_id, qos_config};
    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update QoS configuration for a specific UE
int update_ue_context_qos(UEContextManager *manager, int ue_id, QoSConfig new_qos_config) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            free(manager->contexts[i].qos_config.bearer_ids);
            manager->contexts[i].qos_config = new_qos_config;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // UE ID not found
}

// Delete a specific UE context
int delete_ue_context(UEContextManager *manager, int ue_id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            free(manager->contexts[i].qos_config.bearer_ids);

            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->count - i - 1) * sizeof(LTEUEContext));

            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // UE ID not found
}

// Example usage
int main() {
    UEContextManager manager;

    if (initialize_manager(&manager) != 0) {
        fprintf(stderr, "Failed to initialize context manager\n");
        return EXIT_FAILURE;
    }

    QoSConfig qos_config = { .id = 1, .bearer_ids = malloc(2 * sizeof(char*)), .num_bearers = 2 };
    strcpy(qos_config.bearer_ids[0], "Bearer_1");
    strcpy(qos_config.bearer_ids[1], "Bearer_2");

    add_ue_context(&manager, 12345, qos_config);

    QoSConfig new_qos_config = { .id = 2, .bearer_ids = malloc(3 * sizeof(char*)), .num_bearers = 3 };
    strcpy(new_qos_config.bearer_ids[0], "Bearer_1");
    strcpy(new_qos_config.bearer_ids[1], "Bearer_2");
    strcpy(new_qos_config.bearer_ids[2], "Bearer_3");

    update_ue_context_qos(&manager, 12345, new_qos_config);

    delete_ue_context(&manager, 12345);

    cleanup_manager(&manager);

    return EXIT_SUCCESS;
}
```

This implementation provides a basic structure for managing LTE UE contexts with considerations for memory usage, concurrency, and performance. The use of `pthread_mutex_t` ensures thread-safe operations, and dynamic allocation allows the manager to scale as needed.']

