} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t rnti;
    pthread_mutex_t lock;
} HashEntry;

HashEntry hashTable[HASH_TABLE_SIZE];

// Initialize hash table
void initHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_init(&hashTable[i].lock, NULL);
    }
}

uint16_t hashFunction(uint16_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

// Function to log errors
void logError(const char* message) {
    FILE* logFile = fopen("error_log.txt", "a");
    if (logFile) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
}

// Check and insert RNTI in hash table
int checkAndInsertRNTI(uint16_t rnti) {
    uint16_t index = hashFunction(rnti);

    pthread_mutex_lock(&hashTable[index].lock);
    if (hashTable[index].rnti == 0 || hashTable[index].rnti == rnti) {
        hashTable[index].rnti = rnti;
        pthread_mutex_unlock(&hashTable[index].lock);
        return 1;
    } else {
        pthread_mutex_unlock(&hashTable[index].lock);
        return 0; // Duplicate RNTI found
    }
}

void removeRNTI(uint16_t rnti) {
    uint16_t index = hashFunction(rnti);

    pthread_mutex_lock(&hashTable[index].lock);
    hashTable[index].rnti = 0;
    pthread_mutex_unlock(&hashTable[index].lock);
}

NFAPI_CRC_INDICATION_PDU_T* createNode(RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNode) {
        logError("Memory allocation failed for new node");
        return NULL;
    }

    newNode->ue_info_tag = ue_info_tag;
    newNode->RNTI = rnti;
    newNode->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;

    return newNode;
}

NFAPI_CRC_INDICATION_PDU_T* manageList(NFAPI_CRC_INDICATION_PDU_T** head, int max_size) {
    initHashTable();

    pthread_mutex_t listLock;
    pthread_mutex_init(&listLock, NULL);

    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    int size = 0;

    while (current != NULL && size < MAX_LIST_SIZE) {
        RX_UE_INFORMATION_TAG ue_info_tag = current->ue_info_tag;
        uint16_t rnti = current->RNTI;

        if (!checkAndInsertRNTI(rnti)) {
            logError("Duplicate RNTI detected");
            removeRNTI(rnti); // Clean up
        } else {
            size++;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;

        pthread_mutex_lock(&listLock);
        if (size < max_size) {
            free(temp);
        }
        pthread_mutex_unlock(&listLock);

        // Example synchronization logic with external API
        // Handle network latency and transient issues
    }

    pthread_mutex_destroy(&listLock);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&hashTable[i].lock);
    }

    return *head;
}

// Example use case, should be called within a larger application context.
void exampleUsage() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    // Populate the list with some initial data
    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        RX_UE_INFORMATION_TAG ue_info_tag = {.RNTI = i};
        NFAPI_CRC_INDICATION_PDU_T* newNode = createNode(ue_info_tag, i);

        if (newNode != NULL) {
            newNode->next = head;
            head = newNode;
        }
    }

    // Manage list with a maximum size constraint
    manageList(&head, MAX_LIST_SIZE);
}
