typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
} SharedData;

pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_unique_rnti(SharedData* shared, uint16_t rnti) {
    for (size_t i = 0; i < shared->count; ++i) {
        if (shared->pdu_list[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pseudo_indications(size_t N, SharedData* shared) {
    if (N > MAX_SIZE_LIMIT || N < 1) {
        fprintf(stderr, "Error: Requested size exceeds maximum limit or is invalid.\n");
        return NULL;
    }

    pthread_mutex_lock(&global_mutex);

    // Initialize the pseudo-random number generator
    srand((unsigned int)time(NULL));

    shared->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!shared->pdu_list) {
        pthread_mutex_unlock(&global_mutex);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        shared->pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1; // Example range
