#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDU_COUNT 100
#define CACHE_EXPIRY_TIME 60 // seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    int CRCFLAG; // Assume this is a simple integer for demonstration purposes.
} NFAPI_CRC_INDICATION_PDU_T;

// A simple cache structure for user session data
typedef struct {
    int RNTI;
    time_t expiry_time;
    pthread_mutex_t lock;
} SessionCacheEntry;

SessionCacheEntry session_cache[MAX_PDU_COUNT];
int cache_initialized = 0;

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_session_cache() {
    if (!cache_initialized) {
        for (int i = 0; i < MAX_PDU_COUNT; ++i) {
            pthread_mutex_init(&session_cache[i].lock, NULL);
        }
        cache_initialized = 1;
    }
}

SessionCacheEntry* get_cached_session(int RNTI) {
    initialize_session_cache();
    time_t current_time = time(NULL);

    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        pthread_mutex_lock(&session_cache[i].lock);
        if (session_cache[i].RNTI == RNTI && 
            difftime(current_time, session_cache[i].expiry_time) < CACHE_EXPIRY_TIME) {

            pthread_mutex_unlock(&session_cache[i].lock);
            return &session_cache[i];
        }
        pthread_mutex_unlock(&session_cache[i].lock);
    }

    // Cache miss
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        pthread_mutex_lock(&session_cache[i].lock);
        if (session_cache[i].RNTI == 0) { // Empty slot
            session_cache[i].RNTI = RNTI;
            session_cache[i].expiry_time = current_time + CACHE_EXPIRY_TIME;
            pthread_mutex_unlock(&session_cache[i].lock);
            return &session_cache[i];
        }
        pthread_mutex_unlock(&session_cache[i].lock);
    }

    // No empty slot found
    return NULL;
}

void authenticate_user(int RNTI) {
    // Simulated external authentication call
    printf("Authenticating user with RNTI: %d\n", RNTI);
    // Implement actual authentication logic here.
}

NFAPI_CRC_INDICATION_PDU_T* generateNfadPduList(size_t count, int *error_code) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        *error_code = -1; // Memory allocation error
        return NULL;
    }

    pthread_mutex_lock(&global_lock);

    for (size_t i = 0; i < count; ++i) {
        int RNTI = rand() % 10000 + 1; // Simulate generation of a valid RNTI
        int RX_UE_INFORMATION_TAG = rand() % 100 + 1; // Simulated tag

        SessionCacheEntry *cache_entry = get_cached_session(RNTI);
        if (!cache_entry) {
            authenticate_user(RNTI); // Refresh session data if not in cache or expired
            cache_entry = get_cached_session(RNTI);
            if (!cache_entry) {
                free(pdu_list);
                pthread_mutex_unlock(&global_lock);
                *error_code = -2; // Session caching error
                return NULL;
            }
        }

        pdu_list[i].crc_tag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_list[i].crc_tag.RNTI = RNTI;
        pdu_list[i].CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1
    }

    pthread_mutex_unlock(&global_lock);

    *error_code = 0; // Success
    return pdu_list;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int error_code;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = generateNfadPduList(10, &error_code);

    if (pdu_list && error_code == 0) {
        for (int i = 0; i < 10; ++i) {
