                   i + 1, pdu_list[i].crc_tag.RX_UE_INFORMATION_TAG,
                   pdu_list[i].crc_tag.RNTI, pdu_list[i].CRCFLAG);
        }
    } else {
        printf("Failed to generate PDU list with error code: %d\n", error_code);
    }

    free(pdu_list);
    return 0;
}
