#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <string.h>

// Error handling function for OpenSSL errors
void handle_openssl_error() {
    ERR_print_errors_fp(stderr);
    abort();
}

// Function to generate a random key
int generate_key(unsigned char *key, size_t length) {
    if (!RAND_bytes(key, length)) {
        handle_openssl_error();
        return 0;
    }
    return 1;
}

// Initialize cipher context for AES-256-GCM or ChaCha20-Poly1305
int init_cipher_context(EVP_CIPHER_CTX *ctx, const char *cipher_name, unsigned char *key, size_t key_len) {
    if (!EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(cipher_name), NULL, key, NULL)) {
        handle_openssl_error();
        return 0;
    }
    return 1;
}

// Encrypt function
int encrypt(EVP_CIPHER_CTX *ctx, const unsigned char *plaintext, int plaintext_len,
            unsigned char *ciphertext, int *len, unsigned char *iv) {
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv)) {
        handle_openssl_error();
        return 0;
    }
    if (!EVP_EncryptUpdate(ctx, ciphertext, len, plaintext, plaintext_len)) {
        handle_openssl_error();
        return 0;
    }
    int plaintext_final_len = 0;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + *len, &plaintext_final_len)) {
        handle_openssl_error();
        return 0;
    }
    *len += plaintext_final_len;
    return 1;
}

// Decrypt function
int decrypt(EVP_CIPHER_CTX *ctx, const unsigned char *ciphertext, int ciphertext_len,
            unsigned char *plaintext, int *len, unsigned char *iv) {
    if (!EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, iv)) {
        handle_openssl_error();
        return 0;
    }
    if (!EVP_DecryptUpdate(ctx, plaintext, len, ciphertext, ciphertext_len)) {
        handle_openssl_error();
        return 0;
    }
    int ciphertext_final_len = 0;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + *len, &ciphertext_final_len)) {
        handle_openssl_error();
        return 0;
    }
    *len += ciphertext_final_len;
    return 1;
}

// RSA-PSS signature generation
int generate_signature(RSA *rsa, const unsigned char *message, size_t message_len,
                       unsigned char **signature, size_t *signature_len) {
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    if (!EVP_SignInit_ex(md_ctx, EVP_sha256(), NULL)) {
        handle_openssl_error();
        return 0;
    }
    if (!EVP_SignUpdate(md_ctx, message, message_len)) {
        handle_openssl_error();
        return 0;
    }
    *signature = OPENSSL_malloc(EVP_PKEY_size(rsa));
    if (*signature == NULL) {
        handle_openssl_error();
        return 0;
    }
    if (!EVP_SignFinal(md_ctx, *signature, signature_len, rsa)) {
        handle_openssl_error();
        return 0;
    }
    EVP_MD_CTX_free(md_ctx);
    return 1;
}

// RSA-PSS signature verification
int verify_signature(RSA *rsa, const unsigned char *message, size_t message_len,
                     const unsigned char *signature, size_t signature_len) {
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    if (!EVP_VerifyInit_ex(md_ctx, EVP_sha256(), NULL)) {
        handle_openssl_error();
        return 0;
    }
    if (!EVP_VerifyUpdate(md_ctx, message, message_len)) {
        handle_openssl_error();
        return 0;
    }
    int result = EVP_VerifyFinal(md_ctx, signature, signature_len, rsa);
    EVP_MD_CTX_free(md_ctx);
    return result == 1 ? 1 : 0;
}

// Example usage
int main() {
    // Initialize OpenSSL
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();

    // Key generation for AES-256-GCM
    unsigned char aes_key[32];
    if (!generate_key(aes_key, sizeof(aes_key))) return -1;

    // Encryption context setup
    EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
    if (!init_cipher_context(aes_ctx, "aes-256-gcm", aes_key, sizeof(aes_key))) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return -1;
    }

    unsigned char iv[12]; // GCM nonce
    generate_key(iv, sizeof(iv));

    const char *plaintext = "Hello, World!";
    unsigned char ciphertext[128];
    int len;

    if (!encrypt(aes_ctx, (unsigned char *)plaintext, strlen(plaintext),
                 ciphertext, &len, iv)) {
        EVP_CIPHER_CTX_free(aes_ctx);
        return -1;
    }

    unsigned char decryptedtext[128];
    EVP_CIPHER_CTX *aes_decrypt_ctx = EVP_CIPHER_CTX_new();
    if (!init_cipher_context(aes_decrypt_ctx, "aes-256-gcm", aes_key, sizeof(aes_key))) {
        EVP_CIPHER_CTX_free(aes_ctx);
        EVP_CIPHER_CTX_free(aes_decrypt_ctx);
        return -1;
    }

    if (!decrypt(aes_decrypt_ctx, ciphertext, len, decryptedtext, &len, iv)) {
        EVP_CIPHER_CTX_free(aes_ctx);
        EVP_CIPHER_CTX_free(aes_decrypt_ctx);
        return -1;
    }
    decryptedtext[len] = '\0';

    printf("Decrypted text: %s\n", decryptedtext);

    // RSA key generation for signature
    RSA *rsa = RSA_new();
    BIGNUM *bn = BN_new();
    if (!BN_set_word(bn, RSA_F4)) {
        handle_openssl_error();
        return -1;
    }
    if (RSA_generate_key_ex(rsa, 2048, bn, NULL) != 1) {
        handle_openssl_error();
        return -1;
    }

    unsigned char *signature;
    size_t signature_len;

    if (!generate_signature(rsa, (unsigned char *)plaintext, strlen(plaintext),
                            &signature, &signature_len)) {
        RSA_free(rsa);
        return -1;
    }

    if (!verify_signature(rsa, (unsigned char *)plaintext, strlen(plaintext),
                          signature, signature_len)) {
        printf("Signature verification failed\n");
    } else {
        printf("Signature verified successfully\n");
    }

    // Clean up
    OPENSSL_free(signature);
    RSA_free(rsa);
    EVP_CIPHER_CTX_free(aes_ctx);
    EVP_CIPHER_CTX_free(aes_decrypt_ctx);

    return 0;
}
