} LTE_UeContext;

typedef struct Node {
    LTE_UeContext ue_context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} UeContextList;

UeContextList* create_ue_list() {
    UeContextList* list = (UeContextList*)malloc(sizeof(UeContextList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
