    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_ue_context(UeContextList* list, LTE_UeContext ue_context) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    memcpy(&new_node->ue_context, &ue_context, sizeof(LTE_UeContext));
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

LTE_UeContext* retrieve_ue_context(UeContextList* list, int cell_id) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        if (current->ue_context.cell_id == cell_id) {
            pthread_mutex_unlock(&list->lock);
            return &current->ue_context;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int delete_ue_context(UeContextList* list, int cell_id) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->ue_context.cell_id == cell_id) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free(current->ue_context.dl_frames);
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;
}

int main() {
    UeContextList* ue_list = create_ue_list();
    if (!ue_list) {
        fprintf(stderr, "Failed to create UE context list\n");
        return EXIT_FAILURE;
    }

    // Simulate adding, retrieving, and deleting UE contexts
    LTE_UeContext ue_context = { .cell_id = 1, .frequency_band = 1800 };
    DLFrame* dl_frames = malloc(10 * sizeof(DLFrame)); // Example allocation
    if (!dl_frames) {
        fprintf(stderr, "Failed to allocate memory for DL frames\n");
        destroy_ue_list(ue_list);
        return EXIT_FAILURE;
    }
    ue_context.dl_frames = dl_frames;
    ue_context.frame_count = 10;

    insert_ue_context(ue_list, ue_context);

    LTE_UeContext* retrieved_context = retrieve_ue_context(ue_list, 1);
    if (retrieved_context) {
        printf("Retrieved UE context with cell_id: %d\n", retrieved_context->cell_id);
    }

    delete_ue_context(ue_list, 1);

    destroy_ue_list(ue_list);
    return EXIT_SUCCESS;
}
```

