// Destroy the dynamic list and free memory
void destroyDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Add or update a node in the dynamic list
int addOrUpdateNode(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node** ptr = &list->head;
    while (*ptr != NULL && (*ptr)->data.rnti != data.rnti) {
        ptr = &(*ptr)->next;
    }

    if (*ptr == NULL) { // Add new node
        *ptr = (Node*)malloc(sizeof(Node));
        if (!*ptr) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        (*ptr)->data = data;
        (*ptr)->next = NULL;
        list->size++;
    } else { // Update existing node
        (*ptr)->data.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Background thread function to verify consistency of the structures
