    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);

    fwrite(&list->size, sizeof(size_t), 1, file);
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Import the dynamic list from a file
int importFromStorage(const char* filename, DynamicList* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    destroyDynamicList(list); // Clear existing list

    while (size--) {
        NFAPI_CRC_INDICATION_PDU_T data;
        fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        addOrUpdateNode(list, data);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

