    pthread_create(&verifyThread, NULL, verifyConsistency, &list);
    pthread_detach(verifyThread); // Detach to run independently

    // Simulate application logic...

    // Export and import example
    exportToStorage("data.bin", &list);
    importFromStorage("data.bin", &list);

    destroyDynamicList(&list);
    return 0;
}
