        if (current->data.CRC_INDICATION_REL8_TAG >= 256) {
            fprintf(stderr, "Validation failed at node %d\n", i);
            exit(EXIT_FAILURE);
        }
        current = current->next;
    }
}

void free_linked_list(Node* head) {
    Node* temp;
    pthread_mutex_lock(&list_mutex);

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

