#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void probabilistic_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if ((rand() % 100) < 5) { // ~5% chance
        pdu->CRCFLAG = 1; // Incorrect CRCFLAG setting
    } else {
        pdu->CRCFLAG = 0;
    }
}

int add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= MAX_NODES) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    probabilistic_crc_flag(&data);
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void validate_list(LinkedList* list) {
    Node* current = list->head;

    while (current) {
        if (current->data.CRCFLAG == 1) { // Simulate validation logic
            printf("Invalid CRCFLAG detected at node\n");
        }
        current = current->next;
    }
}

void log_performance_metrics(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    printf("Current Node Count: %zu\n", list->count);
    pthread_mutex_unlock(&list->lock);

    // Additional metrics can be logged here
}

int main() {
    srand(time(NULL));
    LinkedList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize linked list.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < MAX_NODES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, rand(), rand() % 256, 0};
        if (add_node(list, pdu) != 0) {
            fprintf(stderr, "Failed to add node: memory allocation error or max capacity reached.\n");
            break;
        }
    }

    validate_list(list);
    log_performance_metrics(list);

    free_list(list);
    return EXIT_SUCCESS;
}
