        return DNS_RESOLUTION_ERROR;
    }

    addr = (struct sockaddr_in *) he->h_addr_list[0];
    inet_ntop(AF_INET, &addr->sin_addr, (char *)&ip_length, INET_ADDRSTRLEN);

