    EVENT_TYPE_ERROR
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    char message[MAX_EVENT_SIZE];
} NetworkEventLogEntry;

typedef struct {
    NetworkEventLogEntry *entries;
    size_t capacity;
    size_t count;
    size_t max_size;
} LogManager;

// Function prototypes
void init_log_manager(LogManager *manager, size_t initial_capacity, size_t max_size);
void free_log_manager(LogManager *manager);

int insert_event(LogManager *manager, const NetworkEventLogEntry *entry);
NetworkEventLogEntry* get_event(LogManager *manager, size_t index);
void compress_logs_if_needed(LogManager *manager);

// Helper functions
static void resize_entries(LogManager *manager, size_t new_capacity);

// Initialize the LogManager
void init_log_manager(LogManager *manager, size_t initial_capacity, size_t max_size) {
    manager->entries = (NetworkEventLogEntry *)malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->max_size = max_size;
}

// Free the LogManager resources
void free_log_manager(LogManager *manager) {
    free(manager->entries);
    manager->entries = NULL;
    manager->capacity = 0;
    manager->count = 0;
}

// Insert a new event into the log
int insert_event(LogManager *manager, const NetworkEventLogEntry *entry) {
    if (manager->count >= manager->max_size) {
        return -1; // Max size reached
    }

    if (manager->count == manager->capacity) {
        resize_entries(manager, manager->capacity * 2);
    }

    manager->entries[manager->count++] = *entry;
    compress_logs_if_needed(manager);

    return 0;
}

// Retrieve an event by index
NetworkEventLogEntry* get_event(LogManager *manager, size_t index) {
    if (index >= manager->count) {
        return NULL; // Index out of bounds
    }

    return &manager->entries[index];
}

// Compress logs when memory usage exceeds 75% of available RAM
void compress_logs_if_needed(LogManager *manager) {
    // Placeholder for actual compression logic
    size_t used_memory = manager->count * sizeof(NetworkEventLogEntry);
    size_t total_memory = manager->capacity * sizeof(NetworkEventLogEntry);

    if (used_memory > 0.75 * total_memory) {
        // Implement compression algorithm here
        printf("Compressing logs...\n");
        // For example, reduce capacity and discard older entries
        resize_entries(manager, manager->count);
    }
}

// Resize the internal storage array
static void resize_entries(LogManager *manager, size_t new_capacity) {
    NetworkEventLogEntry *new_entries = (NetworkEventLogEntry *)realloc(manager->entries, new_capacity * sizeof(NetworkEventLogEntry));
    if (new_entries) {
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize log entries.\n");
    }
}

// Example usage
int main() {
    LogManager manager;
    init_log_manager(&manager, INITIAL_CAPACITY, 100);

    NetworkEventLogEntry entry1 = {time(NULL), EVENT_TYPE_INFO, "Network connection established"};
    insert_event(&manager, &entry1);

    NetworkEventLogEntry *retrieved_entry = get_event(&manager, 0);
    if (retrieved_entry) {
        printf("Retrieved Event: %s\n", retrieved_entry->message);
    }

    free_log_manager(&manager);
    return 0;
}
