}

void addEvent(TrafficEvent* event) {
    if (!eventsArray || eventCount >= maxEvents)
        return;

    size_t index = event->id % maxEvents; // Simple hash function for distribution
    eventsArray[index] = event;
    eventCount++;
}

TrafficEvent* removeEventById(int id) {
    if (!eventsArray) return NULL;

    size_t index = id % maxEvents;
    TrafficEvent* removedEvent = eventsArray[index];
    if (removedEvent && removedEvent->id == id) {
        eventsArray[index] = removedEvent->next;  // Move next event in chain
        free(removedEvent);
        eventCount--;
    }
    return removedEvent;
}

TrafficEvent* getLatestEventBefore(time_t timestamp) {
    TrafficEvent* latestEvent = NULL;

    for (size_t i = 0; i < maxEvents && eventCount > 0; ++i) {
        TrafficEvent* current = eventsArray[i];
        while (current != NULL) {
            if (current->timestamp < timestamp &&
                (!latestEvent || current->timestamp > latestEvent->timestamp)) {
                latestEvent = current;
            }
            current = current->next;
        }
    }

    return latestEvent;
}

void cleanupEvents() {
    for (size_t i = 0; i < maxEvents; ++i) {
        TrafficEvent* current = eventsArray[i];
        while (current != NULL) {
            TrafficEvent* toDelete = current;
            current = current->next;
            free(toDelete);
        }
        eventsArray[i] = NULL;
    }
    free(eventsArray);
    eventsArray = NULL;
    eventCount = 0;
}

