    uint64_t total_memory_freed;
    int error_logged;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_DATA;

void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

int populate_crc_array(NFAPI_CRC_INDICATION_PDU_DATA* data, size_t n, unsigned int seed, int use_pattern) {
    if (n == 0) return -1;

    pthread_mutex_init(&data->lock, NULL);

    srand(seed);
    uint8_t crc_flag = rand() % 2; // Random CRCFLAG for first entry
    data->total_memory_allocated = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    data->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(data->total_memory_allocated);

    if (!data->array) {
        log_error("Memory allocation failed");
        pthread_mutex_destroy(&data->lock);
        return -1;
    }

    data->count = n;

    #define THREAD_FUNC(thread_id, start_idx, end_idx) \
    for (size_t i = start_idx; i < end_idx; ++i) { \
        int rx_ue_tag = rand(); // Simulated value \
        int rnti = rand(); // Simulated value \
        if (use_pattern) crc_flag = (crc_flag + thread_id) % 2; // Predefined pattern based on thread ID \
        data->array[i].RX_UE_INFORMATION_TAG = rx_ue_tag; \
        data->array[i].RNTI = rnti; \
        data->array[i].crc_indication_rel8_tag.CRCFLAG = crc_flag; \
    }

    size_t threads_count = 4;
    pthread_t threads[threads_count];
    size_t chunk_size = n / threads_count;

    for (size_t t = 0; t < threads_count; ++t) {
        size_t start_idx = t * chunk_size;
        size_t end_idx = (t == threads_count - 1) ? n : start_idx + chunk_size;
        pthread_create(&threads[t], NULL, (void*(*)(void*))THREAD_FUNC, (void*)(intptr_t)t);
    }

    for (size_t t = 0; t < threads_count; ++t) {
        pthread_join(threads[t], NULL);
    }

    // Validate CRCFLAG consistency
    for (size_t i = 1; i < n; ++i) {
        if (data->array[i].crc_indication_rel8_tag.CRCFLAG != crc_flag) {
            log_error("CRCFLAG inconsistency detected");
            free(data->array);
            data->total_memory_freed += data->total_memory_allocated;
            pthread_mutex_destroy(&data->lock);
            return -1;
        }
    }

    printf("Memory usage: Allocated = %lu, Freed = %lu\n", data->total_memory_allocated, data->total_memory_freed);

    return 0;
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_DATA* data) {
    if (data->array) {
        free(data->array);
        data->total_memory_freed += data->total_memory_allocated;
        pthread_mutex_destroy(&data->lock);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_DATA data = {0};
    int result = populate_crc_array(&data, 1000, 42, 0);

    if (result == 0) {
        printf("Array populated successfully.\n");
    } else {
        printf("Failed to populate array.\n");
    }

    free_crc_array(&data);
    return 0;
}
