typedef struct CacheEntry {
    int rx_ue_info_tag;
    int rnti;
    time_t timestamp;
    struct CacheEntry* next;
} CacheEntry;

#define CACHE_SIZE 10

CacheEntry* cache_head = NULL;
CacheEntry* cache_tail = NULL;

void add_to_cache(int rx_ue_info_tag, int rnti) {
    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    if (!new_entry) {
        perror("Failed to allocate memory for cache entry");
        return;
    }

    new_entry->rx_ue_info_tag = rx_ue_info_tag;
    new_entry->rnti = rnti;
    new_entry->timestamp = time(NULL);
    new_entry->next = NULL;

    if (cache_tail) {
        cache_tail->next = new_entry;
    } else {
        cache_head = new_entry;
    }
    cache_tail = new_entry;
}

void evict_cache() {
    if (!cache_head) return;

    CacheEntry* temp = cache_head;
    cache_head = cache_head->next;
    free(temp);
    if (cache_head == NULL) {
        cache_tail = NULL;
    }
}

int get_cached_data(int* rx_ue_info_tag, int* rnti) {
    CacheEntry* current = cache_head;

    while (current != NULL) {
        *rx_ue_info_tag = current->rx_ue_info_tag;
        *rnti = current->rnti;

        // Evict based on a simple LRU policy
        if (cache_tail == current) {
            cache_tail = current->next;
        }

        CacheEntry* temp = current;
        current = current->next;
        free(temp);

        return 1; // Successfully retrieved from cache
    }

    return 0; // No data in cache
}

int allocate_and_populate_nfaapi_crc_array(int N, NFAPI_CRC_INDICATION_PDU_T** array) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of entries: %d\n", N);
        return -1;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("Failed to allocate memory for the array");
        return -1;
    }

    srand(time(NULL)); // For testing purposes only; use a fixed seed in production

    for (int i = 0; i < N; ++i) {
        int rx_ue_info_tag, rnti;

        if (!get_cached_data(&rx_ue_info_tag, &rnti)) {
            // Fetch from external source
            rx_ue_info_tag = fetch_rx_ue_information_tag();
            rnti = fetch_rnti();

            // Handle missing or invalid data here

            add_to_cache(rx_ue_info_tag, rnti);

            if (cache_tail && cache_tail->next) evict_cache();  // Simple LRU eviction
        }

        (*array)[i].RX_UE_INFORMATION_TAG = rx_ue_info_tag;
        (*array)[i].RNTI = rnti;
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG value
    }

    return 0;
}

void free_nfaapi_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }

    while (cache_head) {
        CacheEntry* temp = cache_head;
        cache_head = cache_head->next;
        free(temp);
    }
}

int main() {
