    LTE_RRC_MESSAGE_TYPE_UPLINK_NASTI ul_nasti_array;
} LTE_RRC_MESSAGE_TYPE_UE_CONTEXT;

typedef struct {
    LTE_RRC_MESSAGE_TYPE_UE_CONTEXT* contexts[MAX_UES];
    size_t count;
    pthread_mutex_t lock;
} UECtxManager;

void init_configuration(RRC_CONFIGURATION* config) {
    memset(config, 0, sizeof(*config));
    // Initialize with default parameters
}

UECtxManager* create_ue_ctx_manager() {
    UECtxManager* manager = (UECtxManager*)malloc(sizeof(UECtxManager));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    for (size_t i = 0; i < MAX_UES; ++i) {
        manager->contexts[i] = NULL;
    }
    return manager;
}

int add_ue_context(UECtxManager* manager, int rrc_ue_id) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_UES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space left
    }

    LTE_RRC_MESSAGE_TYPE_UE_CONTEXT* context = (LTE_RRC_MESSAGE_TYPE_UE_CONTEXT*)malloc(sizeof(LTE_RRC_MESSAGE_TYPE_UE_CONTEXT));
    if (!context) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    context->rrc_ue_id = rrc_ue_id;
    init_configuration(&context->config);

    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

LTE_RRC_MESSAGE_TYPE_UE_CONTEXT* find_ue_context(UECtxManager* manager, int rrc_ue_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i] && manager->contexts[i]->rrc_ue_id == rrc_ue_id) {
            LTE_RRC_MESSAGE_TYPE_UE_CONTEXT* result = manager->contexts[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

void filter_ue_contexts(UECtxManager* manager, int (*filter_func)(RRC_CONFIGURATION*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i] && filter_func(&(manager->contexts[i]->config))) {
            // Process the context that matches the filter criteria
