['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Structure definitions
typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Linked list structure with thread safety mechanisms
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
CRCList* create_list();
void destroy_list(CRCList* list);
void add_to_list(CRCList* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, unsigned int seed, uint16_t rnti_min, uint16_t rnti_max);
void update_crcflags(CRCList* list, uint32_t condition);
void cleanup_list(CRCList* list);

// Helper function to generate pseudo-random number based on a seed
uint16_t generate_pseudorandom_crcflag(unsigned int seed) {
    // Simple linear congruential generator (LCG)
    const unsigned int a = 1664525;
    const unsigned int c = 1013904223;
    static unsigned int last_seed = 0;

    if (seed != last_seed) {
        last_seed = seed;
    }
    seed = (a * last_seed + c);
    return (uint16_t)(seed % 65536); // CRCFLAG is a 16-bit value
}

// Create a new linked list with mutex lock initialized
CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

// Destroy the linked list and free resources
void destroy_list(CRCList* list) {
    if (list) {
        ListNode* current = list->head;
        while (current) {
            ListNode* temp = current;
            current = current->next;
            free(temp);
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Add a new node to the linked list in a thread-safe manner
void add_to_list(CRCList* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, unsigned int seed, uint16_t rnti_min, uint16_t rnti_max) {
    if (RNTI < rnti_min || RNTI > rnti_max) return; // Ensure RNTI is within range

    pthread_mutex_lock(&list->lock);

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node) {
        new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_node->data.RNTI = RNTI;
        new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_pseudorandom_crcflag(seed);

        new_node->next = list->head;
        list->head = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Update CRC flags based on additional conditions
void update_crcflags(CRCList* list, uint32_t condition) {
    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current) {
        // Example condition: If the RX_UE_INFORMATION_TAG matches, update the CRCFLAG
        if ((condition & current->data.RX_UE_INFORMATION_TAG) != 0) {
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG ^= 1; // Flip the least significant bit
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup obsolete elements from the list (simple version)
void cleanup_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head, *prev = NULL;
    while (current != NULL) {
        // Example cleanup condition: Remove nodes with even CRCFLAG
        if ((current->data.CRC_INDICATION_REL8_TAG.CRCFLAG & 1) == 0) {
            ListNode* temp = current;
            if (prev == NULL) { // Node to be deleted is the head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
