        free(privateKey);
        free(certificate);
        return;
    }

    printf("Generated PEM Certificate:\n%s\n", pemCertificate);

    BufferPool *bufferPool = createBufferPool(10);
    if (bufferPool == NULL) {
        fprintf(stderr, "Failed to create buffer pool\n");
        free(pemCertificate);
        free(privateKey);
        free(certificate);
        return;
    }

    for (int i = 0; i < listSize; ++i) {
        int crcFlag = rand() % 2; // Randomly generate CRCFLAG
        pduList[i].CRCFLAG = crcFlag;

        char *buffer = acquireBuffer(bufferPool);
        if (buffer == NULL) {
            fprintf(stderr, "No available buffer\n");
            break;
        }

        snprintf(buffer, BUFFER_SIZE, "PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d",
                 pduList[i].RX_UE_INFORMATION_TAG, pduList[i].RNTI, crcFlag);

        printf("Processing PDU: %s\n", buffer);
        releaseBuffer(bufferPool, buffer);
    }

    // Cleanup
    for (int i = 0; i < bufferPool->size; ++i) {
        free(bufferPool->buffers[i]);
    }
    free(bufferPool->buffers);
    free(bufferPool);

    free(pemCertificate);
    free(privateKey);
    free(certificate);
}

