#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define maximum size for linked list and payload
#define MAX_LIST_SIZE 1000
#define PAYLOAD_MAX_SIZE 2048

// MAC_HEADER and PHY_HEADER definitions
typedef struct {
    unsigned int dest_address;
    unsigned int src_address;
} MAC_HEADER;

typedef struct {
    unsigned char modulation_type;
    unsigned short frequency;
} PHY_HEADER;

// TX_PACKET_T structure with doubly-linked list pointers
typedef struct TX_PACKET_NODE {
    MAC_HEADER mac_header;
    PHY_HEADER phy_header;
    unsigned char *payload_buffer;
    size_t payload_size;
    struct TX_PACKET_NODE *prev;
    struct TX_PACKET_NODE *next;
} TX_PACKET_T;

// Doubly linked list and its control variables
TX_PACKET_T *head = NULL, *tail = NULL;
int list_count = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_headers(TX_PACKET_T *packet);
unsigned char* allocate_payload(size_t size);
void deallocate_packet(TX_PACKET_T *packet);
TX_PACKET_T* create_packet(MAC_HEADER mac_header, PHY_HEADER phy_header, size_t payload_size);
void add_to_list(TX_PACKET_T *packet);
void remove_from_list(TX_PACKET_T *packet);
void iterate_and_update(void (*update_func)(TX_PACKET_T *));
void update_payload(TX_PACKET_T *packet);

// Function to initialize MAC and PHY headers
void initialize_headers(TX_PACKET_T *packet) {
    packet->mac_header.dest_address = 0; // Default value or fetch from external source
    packet->mac_header.src_address = 0;  // Default value or fetch from external source
    packet->phy_header.modulation_type = 1; // Default value
    packet->phy_header.frequency = 2400;   // Default frequency in MHz
}

// Function to allocate a payload buffer with error handling for memory allocation failures
unsigned char* allocate_payload(size_t size) {
    if (size > PAYLOAD_MAX_SIZE) return NULL;
    unsigned char *buffer = malloc(size);
    if (!buffer) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return buffer;
}

// Function to deallocate a TX_PACKET_T node
void deallocate_packet(TX_PACKET_T *packet) {
    free(packet->payload_buffer);
    free(packet);
}

// Function to create a new packet with headers initialized and payload allocated
TX_PACKET_T* create_packet(MAC_HEADER mac_header, PHY_HEADER phy_header, size_t payload_size) {
    TX_PACKET_T *packet = malloc(sizeof(TX_PACKET_T));
    if (!packet) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    packet->mac_header = mac_header;
    packet->phy_header = phy_header;
    packet->payload_buffer = allocate_payload(payload_size);
    packet->payload_size = payload_size;
    packet->prev = NULL;
    packet->next = NULL;

    return packet;
}

// Function to add a new packet to the list
void add_to_list(TX_PACKET_T *packet) {
    pthread_mutex_lock(&list_mutex);

    if (list_count >= MAX_LIST_SIZE) {
        // Handle overflow: remove oldest element or reject addition
        TX_PACKET_T *old_packet = head;
        if (old_packet) {
            head = old_packet->next;
            if (head) {
                head->prev = NULL;
            } else {
                tail = NULL;  // List becomes empty
            }
            deallocate_packet(old_packet);
            list_count--;
        }
    }

    if (!tail) {
        // Empty list case
        head = tail = packet;
    } else {
        tail->next = packet;
        packet->prev = tail;
        tail = packet;
    }
    list_count++;

    pthread_mutex_unlock(&list_mutex);
}

// Function to remove a packet from the list
void remove_from_list(TX_PACKET_T *packet) {
    pthread_mutex_lock(&list_mutex);

    if (packet->prev) {
        packet->prev->next = packet->next;
    } else {
        head = packet->next;  // This was the head
    }

    if (packet->next) {
        packet->next->prev = packet->prev;
    } else {
        tail = packet->prev;  // This was the tail
    }

    deallocate_packet(packet);
    list_count--;

    pthread_mutex_unlock(&list_mutex);
}

// Function to iterate over the list and update each packet's payload buffer conditionally
void iterate_and_update(void (*update_func)(TX_PACKET_T *)) {
    TX_PACKET_T *current = head;

    while (current) {
        update_func(current);
        current = current->next;
    }
}

// Example function for updating a packet's payload based on its headers
void update_payload(TX_PACKET_T *packet) {
    // Example conditional logic to modify the payload buffer
    if (packet->phy_header.modulation_type == 1 && packet->mac_header.dest_address != 0) {
        memset(packet->payload_buffer, 0xAA, packet->payload_size);  // Dummy update
    }
}

// Example usage of create_packet and add_to_list
void example_usage() {
    MAC_HEADER mac_header = { .dest_address = 1234, .src_address = 5678 };
    PHY_HEADER phy_header = { .modulation_type = 1, .frequency = 2400 };

    TX_PACKET_T *packet = create_packet(mac_header, phy_header, 512);
    add_to_list(packet);

    // Iterate and update the list
    iterate_and_update(update_payload);
}
