#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example maximum memory usage in bytes
#define MAX_BUFFER_SIZE 1024         // Maximum size for each buffer
#define INT_RANGE_MIN 1              // Minimum value for random int generation
#define INT_RANGE_MAX 100            // Maximum value for random int generation
#define RECORDS_COUNT 100            // Number of records to create

typedef struct {
    int rnti;
    char rx_ue_information_tag[256];
    unsigned char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int key;
    int value;
    char *buffer;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t allocated) {
    printf("Memory allocated: %zu bytes\n", allocated);
}

int random_weighted_int(int min, int max, float weight) {
    // Implement a simple weighted distribution
    return min + (rand() / (float)(RAND_MAX / (max - min))) * (1.0 - weight) + weight * (max - min);
}

void free_resources(long *long_array, size_t long_count, int *int_keys, size_t int_count, Record *records, size_t record_count) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].buffer);
    }
    free(long_array);
    free(int_keys);
    free(records);
    pthread_mutex_unlock(&lock);
}

void* manage_resources(void *arg) {
    long *long_offsets = malloc(RECORDS_COUNT * sizeof(long));
    int *int_keys = malloc(RECORDS_COUNT * sizeof(int));
    Record *records = malloc(RECORDS_COUNT * sizeof(Record));

    if (!long_offsets || !int_keys || !records) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    size_t total_allocated = 0;

    srand(time(NULL));
    int sum_values = 0;
    for (size_t i = 0; i < RECORDS_COUNT; ++i) {
        long_offsets[i] = rand();
        int_keys[i] = random_weighted_int(INT_RANGE_MIN, INT_RANGE_MAX, 0.5);

        records[i].value = int_keys[i];
        sum_values += records[i].value;

        size_t buffer_size = (size_t)int_keys[i] <= MAX_BUFFER_SIZE ? int_keys[i] : MAX_BUFFER_SIZE;
        records[i].buffer = malloc(buffer_size * sizeof(char));

        if (!records[i].buffer) {
            fprintf(stderr, "Failed to allocate memory for buffer\n");
            free_resources(long_offsets, RECORDS_COUNT, int_keys, RECORDS_COUNT, records, i);
            return NULL;
        }

        total_allocated += buffer_size;

        pthread_mutex_lock(&lock);
        log_memory_usage(total_allocated);
        if (total_allocated > MAX_MEMORY_USAGE || sum_values > INT_RANGE_MAX * RECORDS_COUNT) {
            fprintf(stderr, "Memory usage exceeded limits\n");
            free_resources(long_offsets, RECORDS_COUNT, int_keys, RECORDS_COUNT, records, i + 1);
            return NULL;
        }
        pthread_mutex_unlock(&lock);

        NFAPI_CRC_INDICATION_PDU_T pdu = { .rnti = rand(), .crc_flag = rand() % 2 };
        snprintf(records[i].buffer, buffer_size, "PDU: RNTI=%d", pdu.rnti);
    }

    free_resources(long_offsets, RECORDS_COUNT, int_keys, RECORDS_COUNT, records, RECORDS_COUNT);

    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, manage_resources, NULL) != 0 ||
        pthread_create(&thread2, NULL, manage_resources, NULL) != 0) {
        fprintf(stderr, "Failed to create threads\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return EXIT_SUCCESS;
}
