#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define RNTI_MIN 0x0001
#define RNTI_MAX 0xFFFE

typedef struct CRC_INDICATION_REL8_TAG {
    int32_t CRCFLAG;
} CRC_INDICATION_REL8_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_T crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    pthread_mutex_t list_mutex;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->list_mutex, NULL);
    return list;
}

uint32_t pseudo_random(uint32_t seed) {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

void add_pdu(DoublyLinkedList* list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, CRC_INDICATION_REL8_T crc_tag) {
    if (RNTI < RNTI_MIN || RNTI > RNTI_MAX) return;

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return;

    pthread_mutex_lock(&list->list_mutex);

    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->crc_tag = crc_tag;
    new_pdu->next = NULL;
    new_pdu->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_pdu;
    } else {
        list->head = new_pdu;
    }
    list->tail = new_pdu;

    pthread_mutex_unlock(&list->list_mutex);
}

void cleanup_list(DoublyLinkedList* list, uint32_t seed) {
    pthread_mutex_lock(&list->list_mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        if (pseudo_random(seed) % 2 == 0) { // Random cleanup condition
            NFAPI_CRC_INDICATION_PDU_T* to_delete = current;
            current = current->next;

            if (to_delete->prev) {
                to_delete->prev->next = current;
            } else {
                list->head = current;
            }
            if (current) {
                current->prev = to_delete->prev;
            } else {
                list->tail = to_delete->prev;
            }

            free(to_delete);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->list_mutex);
}

void flush_to_disk(DoublyLinkedList* list) {
