void randomize_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu);

// Mutex for thread-safe operations
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t initial_size) {
    pthread_mutex_lock(&list_mutex);
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Failed to initialize list");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&list_mutex);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t size) {
    pthread_mutex_lock(&list_mutex);
    free(list);
    pthread_mutex_unlock(&list_mutex);
}

bool add_pdu(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, size_t *capacity, unsigned short RNTI) {
    pthread_mutex_lock(&list_mutex);

    if (*size >= *capacity || !is_unique_rnti(*list, *size, RNTI)) {
        log_duplicate(RNTI);
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand(); // Placeholder for actual logic
    pdu.RNTI = RNTI;
    pdu.CRC_INDICATION_REL8_TAG = rand(); // Placeholder for actual logic
    randomize_crcflag(&pdu);

    if (*size == *capacity) {
        resize_list(list, size, capacity);
    }

    (*list)[*size] = pdu;
    (*size)++;
    pthread_mutex_unlock(&list_mutex);
    return true;
}

bool remove_pdu(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, unsigned short RNTI) {
    pthread_mutex_lock(&list_mutex);

    for (size_t i = 0; i < *size; i++) {
        if ((*list)[i].RNTI == RNTI) {
            memmove(&(*list)[i], &(*list)[i + 1], (*size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*size)--;
            pthread_mutex_unlock(&list_mutex);
            return true;
        }
    }

    pthread_mutex_unlock(&list_mutex);
    return false;
}

void resize_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, size_t *capacity) {
    *capacity *= 2;
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, *capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
