    size_t count;
    pthread_mutex_t mutex;
} NFACollection;

// Initialize the collection
int nfac_init(NFACollection* collection) {
    if (collection == NULL) return -1;

    collection->elements = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (collection->elements == NULL) return -1;

    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return 0;
}

// Deinitialize the collection
void nfac_destroy(NFACollection* collection) {
    if (collection == NULL) return;

    free(collection->elements);
    pthread_mutex_destroy(&collection->mutex);
}

// Add an element to the collection
int nfac_add_element(NFACollection* collection, NFAPI_CRC_INDICATION_PDU_T newElement) {
    if (collection == NULL || collection->count >= MAX_ELEMENTS)
        return -1;

    if (newElement.rnti < MIN_RNTI || newElement.rnti > MAX_RNTI)
        return -1;

    pthread_mutex_lock(&collection->mutex);

    // Initialize CRCFLAG based on criteria
    newElement.crcIndicationRel8Tag.CRCFLAG = (/* some condition */)? 1 : 0;

    collection->elements[collection->count++] = newElement;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

// Retrieve an element by index
int nfac_get_element(const NFACollection* collection, size_t index, NFAPI_CRC_INDICATION_PDU_T* outElement) {
    if (collection == NULL || outElement == NULL || index >= collection->count)
        return -1;

    pthread_mutex_lock(&collection->mutex);

    *outElement = collection->elements[index];

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

// Example usage
