#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_THRESHOLD 1024 * 1024 // 1MB for example
#define PAGING_CONTROL_INFO_SIZE sizeof(unsigned int)
#define CRC_FLAG_SIZE sizeof(uint8_t)

typedef struct {
    uint8_t flag;
    uint8_t *buffer;
} LteMacPdu;

typedef struct {
    unsigned int pagingControlInfo;
    unsigned int pagingIdentity;
    uint8_t crcIndicator;
} DL_CCCH_Message;

typedef struct {
    unsigned int *identifiers;
    long *offsets;
    size_t identifier_count;
    size_t offset_count;
    pthread_mutex_t mutex; // for concurrency control
} DynamicArray;

// Utility function to get a random number with weighted distribution
unsigned int getRandomWeighted(unsigned int max) {
    return rand() % (max + 1);
}

void initialize_random_generator() {
    srand(time(NULL));
}

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->identifiers = calloc(initial_size, sizeof(unsigned int));
    array->offsets = calloc(initial_size, sizeof(long));
    array->identifier_count = 0;
    array->offset_count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    free(array->identifiers);
    free(array->offsets);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

DL_CCCH_Message* allocate_dl_ccch_messages(size_t count) {
    DL_CCCH_Message *messages = malloc(count * sizeof(DL_CCCH_Message));
    for (size_t i = 0; i < count; ++i) {
        messages[i].pagingControlInfo = getRandomWeighted(100);
        messages[i].pagingIdentity = getRandomWeighted(1000);
        messages[i].crcIndicator = getRandomWeighted(1); // random CRC
    }
    return messages;
}

LteMacPdu* allocate_ltemac_pdus(size_t max_count, size_t *allocated_count) {
    LteMacPdu *pdus = malloc(max_count * sizeof(LteMacPdu));
    *allocated_count = 0;
    uint8_t total_flags = 0;

    for (size_t i = 0; i < max_count; ++i) {
        if (total_flags >= 255) break;

        pdus[i].flag = getRandomWeighted(1); // weighted random flag
        total_flags += pdus[i].flag;
        pdus[i].buffer = malloc(sizeof(uint8_t)); // allocate minimal buffer

        (*allocated_count)++;
    }

    return pdus;
}

void manage_dl_ccch_messages(DynamicArray *array, size_t message_count) {
    pthread_mutex_lock(&array->mutex);

    if ((message_count * sizeof(DL_CCCH_Message)) > MAX_MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded. Using fallback strategy.\n");
        // Fallback logic here
    }

    DL_CCCH_Message *messages = allocate_dl_ccch_messages(message_count);
    size_t pdu_max_count = (MAX_MEMORY_THRESHOLD - message_count * sizeof(DL_CCCH_Message)) / sizeof(LteMacPdu);

    size_t allocated_pdu_count;
    LteMacPdu *pdus = allocate_ltemac_pdus(pdu_max_count, &allocated_pdu_count);

    // Populate DynamicArray
    for (size_t i = 0; i < message_count && i < array->identifier_count + message_count; ++i) {
        array->identifiers[i] = messages[i].pagingIdentity;
    }
    for (size_t i = 0; i < allocated_pdu_count && i < array->offset_count + allocated_pdu_count; ++i) {
        array->offsets[i] = (long)(pdus[i].buffer - pdus);
    }

    free(messages);
    for (size_t i = 0; i < allocated_pdu_count; ++i) {
        free(pdus[i].buffer); // cleanup
    }
    free(pdus);

    pthread_mutex_unlock(&array->mutex);
}

void test_manage_dl_ccch_messages() {
    DynamicArray *array = create_dynamic_array(10);
    manage_dl_ccch_messages(array, 5); // Test with small batch

    printf("Test completed.\n");

    free_dynamic_array(array);
}

int main() {
    initialize_random_generator();
    test_manage_dl_ccch_messages();

    return 0;
}
