['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    char interfaceID[20];
    char ipAddress[16];
    char subnetMask[16];
    char gateway[16];
} NetworkConfig;

typedef struct {
    NetworkConfig *configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConfigManager;

// Function prototypes
int isValidIP(const char *ip);
int isValidSubnetMask(const char *subnet);
void addOrUpdateConfiguration(ConfigManager *manager, const NetworkConfig *config);
NetworkConfig* getConfigurationByID(ConfigManager *manager, const char *interfaceID);
void freeConfigManager(ConfigManager *manager);

// Initialize ConfigManager
void initConfigManager(ConfigManager *manager) {
    manager->configs = (NetworkConfig *)malloc(INITIAL_CAPACITY * sizeof(NetworkConfig));
    if (!manager->configs) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
}

// Validate IP address
int isValidIP(const char *ip) {
    int parts[4];
    return sscanf(ip, "%d.%d.%d.%d", &parts[0], &parts[1], &parts[2], &parts[3]) == 4 &&
           parts[0] >= 0 && parts[0] <= 255 &&
           parts[1] >= 0 && parts[1] <= 255 &&
           parts[2] >= 0 && parts[2] <= 255 &&
           parts[3] >= 0 && parts[3] <= 255;
}

// Validate Subnet Mask
int isValidSubnetMask(const char *subnet) {
    int parts[4];
    if (sscanf(subnet, "%d.%d.%d.%d", &parts[0], &parts[1], &parts[2], &parts[3]) != 4)
        return 0;
    int mask = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3];
    // Check if the subnet is a valid contiguous block
    for (int i = 31; i >= 0; --i) {
        int bit = mask & (1 << i);
        if (bit && !(mask & (1 << (i - 1)))) return 0;
        if (!bit && mask & (1 << (i - 1))) return 0;
    }
    return 1;
}

// Add or update configuration
void addOrUpdateConfiguration(ConfigManager *manager, const NetworkConfig *config) {
    pthread_mutex_lock(&manager->lock);

    if (!isValidIP(config->ipAddress) || !isValidSubnetMask(config->subnetMask)) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Invalid IP address or subnet mask\n");
        return;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i].interfaceID, config->interfaceID) == 0) {
            memcpy(&manager->configs[i], config, sizeof(NetworkConfig));
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        NetworkConfig *newConfigs = realloc(manager->configs, newCapacity * sizeof(NetworkConfig));
        if (!newConfigs) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&manager->lock);
            exit(EXIT_FAILURE);
        }
        manager->configs = newConfigs;
        manager->capacity = newCapacity;
    }

    memcpy(&manager->configs[manager->count], config, sizeof(NetworkConfig));
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve configuration by interface ID
NetworkConfig* getConfigurationByID(ConfigManager *manager, const char *interfaceID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i].interfaceID, interfaceID) == 0) {
            NetworkConfig *configCopy = malloc(sizeof(NetworkConfig));
            memcpy(configCopy, &manager->configs[i], sizeof(NetworkConfig));
            pthread_mutex_unlock(&manager->lock);
            return configCopy;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Free ConfigManager resources
void freeConfigManager(ConfigManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->configs);
    manager->configs = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    ConfigManager manager;
    initConfigManager(&manager);

    NetworkConfig config1 = {"eth0", "192.168.1.1", "255.255.255.0", "192.168.1.254"};
    addOrUpdateConfiguration(&manager, &config1);

    NetworkConfig *retrievedConfig = getConfigurationByID(&manager, "eth0");
    if (retrievedConfig) {
        printf("Retrieved Config: %s\n", retrievedConfig->ipAddress);
        free(retrievedConfig);
