#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

typedef struct {
    char *command;
    char *context;
} MAC_COMMAND;

typedef struct {
    int id;
    float value;
} L2_CONTEXT;

typedef struct {
    MAC_COMMAND mac_command;
    L2_CONTEXT *l2_context;
} L2_MESSAGE;

// Configuration parameters
static unsigned int processing_interval = 5; // seconds

void set_processing_interval(unsigned int interval) {
    processing_interval = interval;
}

void send_completion_message() {
    printf("Processing halted. Completion message sent.\n");
}

L2_MESSAGE* create_l2_message(const char *command) {
    L2_MESSAGE *message = (L2_MESSAGE *)malloc(sizeof(L2_MESSAGE));
    if (!message) return NULL;

    message->mac_command.command = strdup(command);
    if (!message->mac_command.command) {
        free(message);
        return NULL;
    }

    message->l2_context = (L2_CONTEXT *)malloc(sizeof(L2_CONTEXT));
    if (!message->l2_context) {
        free(message->mac_command.command);
        free(message);
        return NULL;
    }

    message->l2_context->id = rand() % 1000; // Example random ID
    message->l2_context->value = (float)(rand() % 100) / 10.0f; // Example random value

    return message;
}

void free_l2_message(L2_MESSAGE *message) {
    if (!message) return;

    free(message->mac_command.command);
    free(message->l2_context);
    free(message);
}

void process_messages(L2_MESSAGE **messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Process each message
        printf("Processing L2_MESSAGE %zu: Command=%s, Context(ID=%.1f, Value=%.1f)\n", 
            i, messages[i]->mac_command.command,
            messages[i]->l2_context->id,
            messages[i]->l2_context->value);
    }
}

void* processing_loop(void *arg) {
    L2_MESSAGE **messages = (L2_MESSAGE **)arg;
    size_t count = 0;

    while (1) {
        sleep(processing_interval);

        // Simulate dynamic message creation
        for (size_t i = 0; i < 5; ++i) {  // Example fixed number of messages to process per interval
            L2_MESSAGE *message = create_l2_message("COMMAND");
            if (!message) {
                fprintf(stderr, "Failed to allocate memory for new message.\n");
                continue;
            }

            messages[count++] = message;

            // Simulate processing delay
            usleep(100000);
        }

        process_messages(messages, count);

        // Free resources after processing
        for (size_t i = 0; i < count; ++i) {
            free_l2_message(messages[i]);
        }
        memset(messages, 0, sizeof(L2_MESSAGE *) * count);
        count = 0;
    }

    return NULL;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    pthread_t thread_id;
    const size_t max_messages = 10;
    L2_MESSAGE *messages[max_messages] = {0};

    if (pthread_create(&thread_id, NULL, processing_loop, messages)) {
        fprintf(stderr, "Error creating processing thread.\n");
        return EXIT_FAILURE;
    }

    // Example of changing the interval during runtime
    sleep(10);
    set_processing_interval(3);

    pthread_join(thread_id, NULL); // Never actually reaches here in this example

    send_completion_message();

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Memory Management**: Allocates and deallocates memory for `L2_MESSAGE` structures.
- **Configurable Interval**: Allows runtime adjustment of the processing interval.
- **Concurrency**: Uses a single thread to simulate message creation and processing; can be extended with multiple threads if needed.
- **Robustness**: Handles allocation failures gracefully, ensuring resources are freed properly.
- **Logging**: Basic logging for debugging purposes using `printf`.
- **Simulation**: Demonstrates behavior under high-load by creating messages in each loop iteration.']

