// Helper function to resolve DNS and cache the result
static u_char* dns_resolve_with_cache(const char* hostname, size_t* ip_length) {
    static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
    static struct hostent *cached_hostent = NULL;

    // Mutex lock for thread safety
    pthread_mutex_lock(&cache_lock);

    if (cached_hostent != NULL && strcmp(hostname, cached_hostent->h_name) == 0) {
        inet_pton(AF_INET, inet_ntoa(*(struct in_addr *)cached_hostent->h_addr), ip_length);
        pthread_mutex_unlock(&cache_lock);
        return (u_char*)inet_ntoa(*(struct in_addr *)cached_hostent->h_addr);
    }

    struct hostent *host = gethostbyname(hostname);
    if (!host) {
        pthread_mutex_unlock(&cache_lock);
        perror("DNS resolution failed");
        return NULL;
    }

    // Cache the resolved host
    cached_hostent = host;

    *ip_length = strlen(inet_ntoa(*(struct in_addr *)host->h_addr)) + 1;
    u_char* ip_address = malloc(*ip_length);
    if (ip_address) {
        inet_pton(AF_INET, inet_ntoa(*(struct in_addr *)host->h_addr), ip_address);
    }

    pthread_mutex_unlock(&cache_lock);
    return ip_address;
}

// Core function logic
