    static pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *list_head = NULL; // Assume initialized elsewhere

    size_t ip_length;
    u_char *ip_address = dns_resolve_with_cache(hostname, &ip_length);
    if (!ip_address) {
        return -1;  // Error code for DNS resolution failure
    }

    pthread_rwlock_wrlock(&list_lock);

    // Allocate and initialize a new structure
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        free(ip_address);
        pthread_rwlock_unlock(&list_lock);
        return -1;  // Error code for memory allocation failure
    }

    new_node->RX_UE_INFORMATION_TAG = rand();  // Example initialization
    new_node->RNTI = rand();
    new_node->CRC_INDICATION_REL8_TAG = rand();
    new_node->CRCFLAG = rand() % 2;  // Randomly set

    // Insert into list - assume a simple linked-list for illustration
    new_node->next = list_head;
    list_head = new_node;

    pthread_rwlock_unlock(&list_lock);

    printf("Resolved IP: ");
    for (size_t i = 0; i < ip_length; ++i) {
        printf("%u.", ip_address[i]);
