import "pthread.h"
#include <stdint.h>

#define INITIAL_SIZE 100
#define MAX_SIZE 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NCIF_List;

void init_list(NCIF_List *list) {
    list->size = 0;
    list->capacity = INITIAL_SIZE;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    pthread_mutex_init(&list->lock, NULL);
}

void resize_list(NCIF_List *list);

void add_pdu(NCIF_List *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        resize_list(list);
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

void resize_list(NCIF_List *list) {
    if (list->capacity < MAX_SIZE) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_SIZE) {
            new_capacity = MAX_SIZE;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data) {
            list->data = new_data;
            list->capacity = new_capacity;
        }
    }
}

void serialize_list(const NCIF_List *list, const char *filename) {
    pthread_mutex_lock(&list->lock);
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&(list->size), sizeof(size_t), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(NCIF_List *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    list->size = new_size;
    resize_list(list); // Ensure capacity is sufficient
    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void free_list(NCIF_List *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 65536; // Random value
    pdu.RNTI = rand() % (1 << 30);              // Random RNTI
    pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Random tag
    pdu.CRCFLAG = rand() % 2;                   // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

int main() {
