const int maxIMSIValuesPerSession = 10000; // Example limit

void initSessions() {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        pthread_mutex_init(&sessions[i].lock, NULL);
        sessions[i].ueCount = 0;
    }
    pthread_mutex_init(&imsiLock, NULL);
}

int getSessionIndex() {
    pthread_mutex_lock(&imsiLock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].ueCount < MAX_UE_PER_SESSION) {
            int index = i;
            pthread_mutex_unlock(&imsiLock);
            return index;
        }
    }
    pthread_mutex_unlock(&imsiLock);
    return -1; // No available session
}

int isUniqueIMSI(const char *imsi) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].ueCount > 0) {
            pthread_mutex_lock(&sessions[i].lock);
            for (int j = 0; j < sessions[i].ueCount; ++j) {
                if (strcmp(sessions[i].contexts[j]->imsi, imsi) == 0) {
                    pthread_mutex_unlock(&sessions[i].lock);
                    return 0;
                }
            }
            pthread_mutex_unlock(&sessions[i].lock);
        }
    }
    pthread_mutex_lock(&imsiLock);
    int totalIMSI = totalIMSICount + 1;
    if (totalIMSI > maxIMSIValuesPerSession) {
        pthread_mutex_unlock(&imsiLock);
        return -1; // Exceeded IMSI limit
    }
    totalIMSICount = totalIMSI;
    pthread_mutex_unlock(&imsiLock);
    return 1;
}

int populateUEContexts(int sessionId, int ueCount, int minQoSFlows, int maxQoSFlows) {
    if (sessionId < 0 || sessionId >= MAX_SESSIONS || ueCount > MAX_UE_PER_SESSION) {
        return -1; // Invalid session or UE count
    }

    pthread_mutex_lock(&sessions[sessionId].lock);

    for (int i = 0; i < ueCount; ++i) {
        char imsiBuffer[IMSI_LENGTH];
        snprintf(imsiBuffer, IMSI_LENGTH, "12345678901234%d", totalIMSICount + i);

        int imsiCheck = isUniqueIMSI(imsiBuffer);
        if (imsiCheck == 0) continue; // Duplicate IMSI
        if (imsiCheck == -1) {
            pthread_mutex_unlock(&sessions[sessionId].lock);
            return -2; // Exceeded total IMSI limit
        }

        int qosFlowCount = rand() % (maxQoSFlows - minQoSFlows + 1) + minQoSFlows;
        UEContext *context = malloc(sizeof(UEContext) + sizeof(int) * qosFlowCount);

        strcpy(context->imsi, imsiBuffer);
        context->servingCellID = rand() % 1000; // Example serving cell ID
        for (int j = 0; j < qosFlowCount; ++j) {
            context->qosFlowIDs[j] = rand() % 256;
        }

        sessions[sessionId].contexts[sessions[sessionId].ueCount++] = context;
    }

    pthread_mutex_unlock(&sessions[sessionId].lock);
    return 0; // Success
}

void freeSession(int sessionId) {
    if (sessionId < 0 || sessionId >= MAX_SESSIONS) {
        return;
    }

    pthread_mutex_lock(&sessions[sessionId].lock);

    for (int i = 0; i < sessions[sessionId].ueCount; ++i) {
        free(sessions[sessionId].contexts[i]);
    }

    sessions[sessionId].ueCount = 0;

    pthread_mutex_unlock(&sessions[sessionId].lock);
}

void cleanupSessions() {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].ueCount > 0) {
            freeSession(i);
        }
        pthread_mutex_destroy(&sessions[i].lock);
    }
    pthread_mutex_destroy(&imsiLock);
}
