    unsigned char crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    FILE* log_file;
} CRCList;

void init_logger(CRCList* list, const char* filename) {
    list->log_file = fopen(filename, "a");
    if (!list->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void log_message(CRCList* list, const char* message) {
    pthread_mutex_lock(&list->lock);
    fprintf(list->log_file, "%s\n", message);
    fflush(list->log_file);
    pthread_mutex_unlock(&list->lock);
}

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        log_message(NULL, "Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    init_logger(list, "error.log");
    return list;
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    if (list->log_file) {
        fclose(list->log_file);
    }
    free(list);
}

int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message(list, "Failed to allocate memory for node");
        return -1;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void sort_list(CRCList* list, int (*comparator)(const NFAPI_CRC_INDICATION_PDU_T*, const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !comparator) return;

    pthread_mutex_lock(&list->lock);
    Node *i, *j;
    for (i = list->head; i != NULL; i = i->next) {
        for (j = i->next; j != NULL; j = j->next) {
            if (comparator(&(i->data), &(j->data)) > 0) {
                NFAPI_CRC_INDICATION_PDU_T temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int compare_by_rnti(const NFAPI_CRC_INDICATION_PDU_T* a, const NFAPI_CRC_INDICATION_PDU_T* b) {
    return (a->rnti > b->rnti) - (a->rnti < b->rnti);
}

void filter_list(CRCList* list, int (*filter_func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !filter_func) return;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    Node *prev = NULL;
    while (current != NULL) {
        if (!filter_func(&(current->data))) {
            if (prev == NULL) {
                list->head = current->next;
                free(current);
                current = list->head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int is_valid_crc(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return pdu->crc_indication_rel8_tag == 0; // Example condition
}

void async_operation(CRCList* list, void (*operation)(CRCList*)) {
    if (!list || !operation) return;

    pthread_t thread;
    pthread_create(&thread, NULL, (void*(*)(void*))operation, (void*)list);
    pthread_detach(thread);
}

// Unit tests and additional functions would be added here

int main() {
    // Example usage
    CRCList* list = create_list();
    if (!list) return EXIT_FAILURE;

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 12345, 0};
    add_pdu(list, pdu);

    sort_list(list, compare_by_rnti);
    filter_list(list, is_valid_crc);

    async_operation(list, (void(*)(CRCList*))sort_list); // Example async operation

    destroy_list(list);
    return EXIT_SUCCESS;
}
