#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 1000000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    atomic_int count;
    pthread_mutex_t lock;
} PDU_Manager;

PDU_Manager manager = {NULL, ATOMIC_VAR_INIT(0), PTHREAD_MUTEX_INITIALIZER};

void initialize_manager(PDU_Manager *manager) {
    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_STRUCTURES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void reset_manager(PDU_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    atomic_store(&manager->count, 0);
    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        manager->pdus[i].RX_UE_INFORMATION_TAG = -1;
    }
    pthread_mutex_unlock(&manager->lock);
}

int is_tag_unique(PDU_Manager *manager, int tag) {
    for (int i = 0; i < atomic_load(&manager->count); ++i) {
        if (manager->pdus[i].RX_UE_INFORMATION_TAG == tag) {
            return 0;
        }
    }
    return 1;
}

int add_pdu(PDU_Manager *manager, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&manager->lock);

    if (!is_tag_unique(manager, RX_UE_INFORMATION_TAG)) {
        fprintf(stderr, "Duplicate tag detected: %d\n", RX_UE_INFORMATION_TAG);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    int index = atomic_fetch_add(&manager->count, 1);

    if (index >= MAX_STRUCTURES) {
        perror("Maximum capacity reached");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->pdus[index].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->pdus[index].RNTI = RNTI;

    // Set CRC_INDICATION_REL8_TAG with a random CRCFLAG
    manager->pdus[index].CRC_INDICATION_REL8_TAG[3] = rand() % 2; // Random CRCFLAG

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void cleanup_manager(PDU_Manager *manager) {
    free(manager->pdus);
    manager->pdus = NULL;
}

int main() {
    initialize_manager(&manager);

    // Example usage
    for (int i = 0; i < 1000000; ++i) {
        if (add_pdu(&manager, i, rand()) != 0) {
            fprintf(stderr, "Failed to add PDU\n");
        }
    }

    reset_manager(&manager);

    cleanup_manager(&manager);
    return 0;
