#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct {
    unsigned int rnti;
    int crcflag;
    // Add other fields as per the NFAPI_CRC_INDICATION_PDU_T definition
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    pthread_mutex_t mutex;
    unsigned int unique_rnti_count;
} NFAPICRCManager;

// Function to initialize the manager
int nfapi_crc_manager_init(NFAPICRCManager *manager) {
    if (!manager) return -1;

    memset(manager->structures, 0, sizeof(manager->structures));
    pthread_mutex_init(&manager->mutex, NULL);
    manager->unique_rnti_count = 0;

    return 0;
}

// Function to free the manager
void nfapi_crc_manager_free(NFAPICRCManager *manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        free(manager->structures[i]);
    }
    pthread_mutex_destroy(&manager->mutex);
}

// Function to add a new structure
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_manager_add(NFAPICRCManager *manager, unsigned int rnti, int crcflag) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (!manager->structures[i]) {
            NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_structure) {
                pthread_mutex_unlock(&manager->mutex);
                return NULL;
            }

            new_structure->rnti = rnti;
            new_structure->crcflag = crcflag;

            // Ensure no two consecutive structures share the same RNTI
            if (i > 0 && manager->structures[i - 1] &&
                manager->structures[i - 1]->rnti == rnti) {
                free(new_structure);
                pthread_mutex_unlock(&manager->mutex);
                return NULL;
            }

            // Validate CRCFLAG accuracy according to the LTE specification
            if (!validate_crcflag(crcflag)) {
                free(new_structure);
                log_discrepancy(rnti, crcflag);
                pthread_mutex_unlock(&manager->mutex);
                return NULL;
            }

            manager->structures[i] = new_structure;

            // Track unique RNTI values
            unsigned int existing_rntis[MAX_STRUCTURES] = {0};
            unsigned int found = 0;
            for (int j = 0; j < i + 1; ++j) {
                if (manager->structures[j]) {
                    for (int k = 0; k < MAX_STRUCTURES; ++k) {
                        if (existing_rntis[k] == manager->structures[j]->rnti) {
                            found = 1;
                            break;
                        }
                    }
                    if (!found) {
                        existing_rntis[manager->unique_rnti_count++] = manager->structures[j]->rnti;
                    }
                }
            }

            pthread_mutex_unlock(&manager->mutex);
            return new_structure;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;  // No space to add a new structure
}

// Placeholder for CRCFLAG validation function according to LTE spec
int validate_crcflag(int crcflag) {
    // Implement the actual validation logic here
    return crcflag == 1 || crcflag == 0;
}

// Log discrepancies between CRC indications and packet integrity
void log_discrepancy(unsigned int rnti, int crcflag) {
    printf("Discrepancy detected: RNTI %u, CRCFLAG %d\n", rnti, crcflag);
}

int main() {
    NFAPICRCManager manager;
    nfapi_crc_manager_init(&manager);

    for (unsigned int i = 0; i < MAX_STRUCTURES; ++i) {
        unsigned int rnti = rand() % 1000000; // Random RNTI value
        int crcflag = rand() % 2;              // Random CRCFLAG value

        NFAPI_CRC_INDICATION_PDU_T *structure = nfapi_crc_manager_add(&manager, rnti, crcflag);
        if (!structure) {
            printf("Failed to add structure for RNTI %u\n", rnti);
        }
    }

    printf("Unique RNTI Count: %u\n", manager.unique_rnti_count);

    nfapi_crc_manager_free(&manager);
    return 0;
}
