#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_HOSTNAMES 10
#define MAX_RETRIES 3
#define ALLOWED_DOMAIN ".example.com"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];
} DNSResolutionResult;

pthread_mutex_t dns_lock = PTHREAD_MUTEX_INITIALIZER;
int active_dns_requests = 0;

void log_attempt(const char *hostname, int success) {
    printf("DNS resolution for %s: %s\n", hostname, success ? "SUCCESS" : "FAILURE");
}

int resolve_hostname(char *hostname, DNSResolutionResult *result) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if (pthread_mutex_lock(&dns_lock) != 0) {
        perror("Mutex lock");
        return -1;
    }

    active_dns_requests++;
    pthread_mutex_unlock(&dns_lock);

    status = getaddrinfo(hostname, NULL, &hints, &res);

    int retry_count = 0;
    while (status != 0 && retry_count < MAX_RETRIES) {
        sleep(1); // Wait before retrying
        status = getaddrinfo(hostname, NULL, &hints, &res);
        retry_count++;
    }

    if (status == 0) {
        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }
            inet_ntop(p->ai_family, addr, result->ip_address, sizeof(result->ip_address));
            break;
        }
    }

    freeaddrinfo(res);

    if (pthread_mutex_lock(&dns_lock) != 0) {
        perror("Mutex lock");
        return -1;
    }

    active_dns_requests--;
    pthread_mutex_unlock(&dns_lock);

    log_attempt(hostname, status == 0);
    return status == 0 ? 0 : -1;
}

int is_allowed_domain(const char *hostname) {
    return strstr(hostname, ALLOWED_DOMAIN) != NULL;
}

int find_largest(int *array, int size) {
    if (size <= 0) return INT_MIN;

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
    return largest;
}

int manage_nfaapi_list_and_dns(NFAPI_CRC_INDICATION_PDU_T *nfaapi_list, int nfaapi_count, char hostnames[][256], int hostname_count) {
    int array_size = 0;
    int *array = NULL;

    while (scanf("%d", &array_size) == 1) {
        array = realloc(array, sizeof(int) * array_size);
        if (!array) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }

        for (int i = 0; i < array_size; i++) {
            scanf("%d", &array[i]);
        }

        find_largest(array, array_size);
    }

    free(array);

    DNSResolutionResult results[hostname_count];
    int success_count = 0;

    for (int i = 0; i < hostname_count; i++) {
        if (!is_allowed_domain(hostnames[i])) {
            printf("Invalid domain: %s\n", hostnames[i]);
            continue;
        }

        while (active_dns_requests >= MAX_HOSTNAMES) {
            usleep(100000); // Sleep for 100ms
        }

        if (resolve_hostname(hostnames[i], &results[i]) == 0) {
            success_count++;
        }
    }

    printf("Successful DNS resolutions: %d\n", success_count);
    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T nfaapi_list[5]; // Example list
    char hostnames[MAX_HOSTNAMES][256] = {"example1.example.com", "example2.example.com"};

    manage_nfaapi_list_and_dns(nfaapi_list, 5, hostnames, 2);
    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses a mutex to ensure thread-safe access to the `active_dns_requests` counter.
- **DNS Resolution:** Manages concurrent DNS requests with a limit and retries failed resolutions.
- **Hostname Validation:** Checks if hostnames belong to allowed domains before resolving them.
- **Logging:** Logs each DNS resolution attempt, indicating success or failure.
- **Memory Management:** Dynamically allocates memory for the integer array and frees it after use.']

