typedef struct CRC_Indication_Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct CRC_Indication_Node* next;
} CRC_Indication_Node;

typedef struct {
    CRC_Indication_Node* head;
    pthread_mutex_t lock;
    int entry_count; // For logging purposes
} CRC_List;

CRC_List* create_crc_list() {
    CRC_List* list = (CRC_List*)malloc(sizeof(CRC_List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->entry_count = 0;
    return list;
}

int validate_rx_ue_information_tag(RX_UE_INFORMATION_TAG tag) {
    // Placeholder for external module validation
    return 1; // Assume valid for demonstration
}

void add_crc_entry(CRC_List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!validate_rx_ue_information_tag(entry.RX_UE_INFORMATION_TAG)) return;

    pthread_mutex_lock(&list->lock);

    CRC_Indication_Node* new_node = (CRC_Indication_Node*)malloc(sizeof(CRC_Indication_Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure gracefully
    }

    new_node->data = entry;
    new_node->timestamp = time(NULL);
    new_node->next = list->head;
    list->head = new_node;

    list->entry_count++;

    printf("Added %d entries\n", list->entry_count);

    pthread_mutex_unlock(&list->lock);
}

void* periodic_cleanup(void* arg) {
    CRC_List* list = (CRC_List*)arg;
    time_t ttl = 60; // Example TTL in seconds

    while (1) {
        sleep(30); // Cleanup interval

        pthread_mutex_lock(&list->lock);

        CRC_Indication_Node *current = list->head, *prev = NULL;

        while (current) {
            if (time(NULL) - current->timestamp > ttl) {
                CRC_Indication_Node* to_delete = current;
                if (prev) prev->next = current->next;
                else list->head = current->next;

                free(to_delete);
                list->entry_count--;

                printf("Removed 1 entry, total %d entries\n", list->entry_count);

                current = current->next;
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

void start_cleanup_thread(CRC_List* list) {
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, list)) {
        fprintf(stderr, "Error creating cleanup thread\n");
        exit(1);
    }
    pthread_detach(cleanup_thread); // Detach since it runs indefinitely
}

void free_crc_list(CRC_List* list) {
    pthread_mutex_lock(&list->lock);

    CRC_Indication_Node* current = list->head;
    while (current) {
        CRC_Indication_Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Usage example
int main() {
    CRC_List* list = create_crc_list();
    if (!list) return 1;

    start_cleanup_thread(list);

    // Add entries to the list...

    // Cleanup and exit
    free_crc_list(list);
    return 0;
}
