    Node* head;
    pthread_mutex_t lock;
    unsigned long current_sequence_number;
    size_t list_size_limit;
    time_t last_update_time;
    const double inactivity_timeout_seconds;
} CRCListManager;

void initialize_crc_list_manager(CRCListManager* manager, size_t size_limit, double timeout) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->current_sequence_number = 0;
    manager->list_size_limit = size_limit;
    manager->last_update_time = time(NULL);
    manager->inactivity_timeout_seconds = timeout;
}

void cleanup_crc_list_manager(CRCListManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete);
    }
    pthread_mutex_destroy(&manager->lock);
}

void reset_crc_list_if_stale(CRCListManager* manager) {
    time_t now = time(NULL);
    if (difftime(now, manager->last_update_time) > manager->inactivity_timeout_seconds) {
        cleanup_crc_list_manager(manager);
        initialize_crc_list_manager(manager, manager->list_size_limit, manager->inactivity_timeout_seconds);
    }
}

int is_valid_rnti(int rnti) {
    // Implement your RNTI validation logic here
    return (rnti >= 0 && rnti <= 65535); // Example condition for valid RNTI
}

void add_crc_indication(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T indication) {
    if (!is_valid_rnti(indication.rnti)) {
        fprintf(stderr, "Invalid RNTI value: %d\n", indication.rnti);
        return;
    }

    pthread_mutex_lock(&manager->lock);

    reset_crc_list_if_stale(manager);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    memcpy(&new_node->data, &indication, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->timestamp = time(NULL);
    new_node->sequence_number = manager->current_sequence_number++;

    new_node->next = NULL;

    if (manager->head == NULL) {
        manager->head = new_node;
    } else {
        Node* current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    size_t list_size = 0;
    for (Node* traverse = manager->head; traverse != NULL; traverse = traverse->next) {
        ++list_size;
    }

    if (list_size > manager->list_size_limit) {
        Node* to_delete = manager->head;
        manager->head = manager->head->next;
        free(to_delete);
    }

    manager->last_update_time = time(NULL);

    pthread_mutex_unlock(&manager->lock);
}

void update_crc_flag(CRCListManager* manager, int rnti, int new_flag_value) {
    pthread_mutex_lock(&manager->lock);

    for (Node* node = manager->head; node != NULL; node = node->next) {
        if (node->data.rnti == rnti) {
            node->data.crc_indication_rel8_tag = new_flag_value;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void reset_crc_list(CRCListManager* manager) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete);
    }

    manager->head = NULL;
    manager->current_sequence_number = 0;

    pthread_mutex_unlock(&manager->lock);
}

// Usage example
int main() {
    CRCListManager crc_manager;
    initialize_crc_list_manager(&crc_manager, MAX_LIST_SIZE, 60.0); // 60 seconds inactivity timeout

    NFAPI_CRC_INDICATION_PDU_T sample_pdu = {1, 1234, 5678};
    add_crc_indication(&crc_manager, sample_pdu);

    update_crc_flag(&crc_manager, 1234, 9);

    reset_crc_list(&crc_manager);

    cleanup_crc_list_manager(&crc_manager);
    return 0;
}
