enum class AttackType {
    MELEE,
    RANGE,
    CAST
};

class Strategy {
public:
    int id;
    unsigned int cooldownPeriod;
    AttackType attackType;

    Strategy(int id, unsigned int cooldownPeriod, AttackType attackType)
        : id(id), cooldownPeriod(cooldownPeriod), attackType(attackType) {}
};

class ResourceMonitor {
private:
    std::unordered_map<int, unsigned int> cooldowns;
    std::mutex mtx;

public:
    bool isAvailable(const Strategy& strategy) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cooldowns.find(strategy.id);
        if (it != cooldowns.end()) {
            return it->second == 0;
        }
        return true;
    }

    void updateCooldown(const Strategy& strategy, unsigned int timeElapsed) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cooldowns.find(strategy.id);
        if (it != cooldowns.end()) {
            it->second = std::max(0u, it->second - timeElapsed);
        }
    }

    void setCooldown(const Strategy& strategy) {
        std::lock_guard<std::mutex> lock(mtx);
        cooldowns[strategy.id] = strategy.cooldownPeriod;
    }
};

void selectAndExecuteStrategy(std::vector<Strategy>& strategies, ResourceMonitor& monitor) {
    static std::vector<std::unique_ptr<Strategy>> activeStrategies;

    // Resize the active strategies pool if necessary
    activeStrategies.resize(strategies.size());

    for (size_t i = 0; i < strategies.size(); ++i) {
        const auto& strategy = strategies[i];
        if (monitor.isAvailable(strategy)) {
            std::cout << "Executing Strategy ID: " << strategy.id 
                      << ", Type: " << static_cast<int>(strategy.attackType) << std::endl;

            // Execute the selected strategy
            monitor.setCooldown(strategy);

            // Store in active strategies pool (simulating allocation)
            if (!activeStrategies[i]) {
                activeStrategies[i] = std::make_unique<Strategy>(strategy.id, strategy.cooldownPeriod, strategy.attackType);
            }
        } else {
            if (activeStrategies[i]) {
                const auto& activeStrategy = *activeStrategies[i];
                // Update cooldown status for active strategies
                monitor.updateCooldown(activeStrategy, 1); // Assume a time unit has passed
            }
        }
    }
}

// Example usage
int main() {
    std::vector<Strategy> strategies = {
        {1, 3, AttackType::MELEE},
        {2, 5, AttackType::RANGE},
        {3, 2, AttackType::CAST}
    };

    ResourceMonitor monitor;

    // Simulate strategy selection and execution
    selectAndExecuteStrategy(strategies, monitor);
    selectAndExecuteStrategy(strategies, monitor);

    return 0;
}
