void add_crc_indication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->mutex);

    if (list->list_size >= list->max_size) {
        // Truncate the oldest element
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->list_size--;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        logger_log("Memory allocation failed for CRC indication.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;
    list->list_size++;
    list->allocated_count++;
    time(&list->last_access_time);

