    pthread_mutex_lock(&list->mutex);

    if (difftime(current_time, list->last_access_time) > 3600) { // Reset after an hour of inactivity
        Node* temp;
        while (list->head != NULL) {
            temp = list->head;
            list->head = list->head->next;
            free(temp);
            list->allocated_count--;
        }
        list->list_size = 0;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Garbage collection for unused or expired structures
void garbage_collect(CRCList* list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;
    time_t current_time;
    time(&current_time);

    while (current != NULL) {
        if (difftime(current_time, list->last_access_time) > 300) { // Expire entries older than 5 minutes
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->allocated_count--;
            list->list_size--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Self-healing mechanism to reinitialize the memory pool
void self_heal(CRCList* list) {
    if (list->allocated_count == 0) {
        init_crc_list(list, list->max_size);
        logger_log("Memory pool reinitialized.");
    }
}

// Destructor for CRC List
void free_crc_list(CRCList* list) {
