    pthread_mutex_lock(&pq->lock);
    destroy_priority_queue(pq);
    *pq = (PriorityQueue){NULL, PTHREAD_MUTEX_INITIALIZER, 0, time(NULL)};
    pthread_mutex_unlock(&pq->lock);
}

int enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T pdu, int priority) {
    if (pdu.RNTI == INVALID_RNTI) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    new_node->priority = priority;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);
    if (pq->head == NULL || pq->head->priority < priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pq->size++;
    if (pq->size > MAX_LIST_SIZE) {
        Node* temp = pq->head;
        pq->head = pq->head->next;
        free(temp);
        pq->size--;
    }
    pq->last_activity = time(NULL);

    pthread_mutex_unlock(&pq->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);
    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){INVALID_RNTI};
    }

    Node* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T pdu = temp->data;
    pq->head = pq->head->next;
    free(temp);

    pq->size--;
    if (pq->size == 0) {
        reset_priority_queue(pq);
    }

    pthread_mutex_unlock(&pq->lock);
    return pdu;
}

void log_performance(PriorityQueue* pq) {
    printf("Current queue size: %d\n", pq->size);
    // Additional logging can be implemented here
}

// Example usage
int main() {
    PriorityQueue* pq = create_priority_queue();

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 2, time(NULL), 0};
    enqueue(pq, pdu, 5);

    if (is_stale(pq, 60)) {
        reset_priority_queue(pq);
    }

    NFAPI_CRC_INDICATION_PDU_T result = dequeue(pq);
    printf("Dequeued RNTI: %d\n", result.RNTI);

    log_performance(pq);

    destroy_priority_queue(pq);
    return 0;
}
```

