    char* UE_info;
    int CRC_value;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Memory allocation failed
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

int insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* current = *head;

    // Check for duplicate RNTI
    while (current != NULL) {
        if (current->data.RNTI == pdu.RNTI) return -1;  // Duplicate found
        current = current->next;
    }

    // Insert at the beginning of the list for efficiency
    Node* new_node = create_node(pdu);
    if (!new_node) return -2; // Memory allocation failed

    new_node->next = *head;
    *head = new_node;

    return 0; // Success
}

int delete_node(Node** head, int RNTI) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return -1; // Not found

    if (previous == NULL) { // Head node needs to be deleted
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    return 0; // Success
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RNTI: %d, UE Info: %s, CRC Value: %d\n", 
               current->data.RNTI, current->data.UE_info, current->data.CRC_value);
        current = current->next;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    *head = NULL;
}

int main() {
    Node* list_head = NULL;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {101, "UE1", 123};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {102, "UE2", 456};

    insert_node(&list_head, pdu1);
    insert_node(&list_head, pdu2);

    traverse_list(list_head);

    delete_node(&list_head, 101);

    traverse_list(list_head);

    free_list(&list_head);

    return 0;
}
