#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set value
    int reference_count;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu);
void destroy_list(Node** head);
int insert_at_tail(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu);
int insert_at_head(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_by_rnti(Node** head, unsigned int rnti);
Node* merge_lists(Node* list1, Node* list2);
void serialize_list(Node* head, FILE* file);
Node* deserialize_list(FILE* file);
void remove_duplicates(Node** head);

// Function implementations
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = pdu;
    new_node->prev = NULL;
    new_node->next = NULL;
    new_node->data.reference_count = 1; // Initialize reference count
    return new_node;
}

void destroy_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int insert_at_tail(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = create_node(pdu);
    if (!new_node) return -1;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* tail = *head;
        while (tail->next != NULL) {
            tail = tail->next;
        }
        tail->next = new_node;
        new_node->prev = tail;
    }
    return 0;
}

int insert_at_head(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = create_node(pdu);
    if (!new_node) return -1;

    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
    return 0;
}

int remove_by_rnti(Node** head, unsigned int rnti) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;
            if (current == *head) *head = current->next;

            free(current);
            return 0; // Successfully removed
        }
        current = current->next;
    }
    return -1; // RNTI not found
}

Node* merge_lists(Node* list1, Node* list2) {
    if (!list1) return list2;
    if (!list2) return list1;

    Node dummy;
    Node* tail = &dummy;
    dummy.next = list1;
    dummy.prev = NULL;

    while (list1 && list2) {
        if (list1->data.RNTI < list2->data.RNTI) {
            tail->next = list1;
            list1->prev = tail;
            list1 = list1->next;
        } else {
            tail->next = list2;
            list2->prev = tail;
            list2 = list2->next;
        }
        tail = tail->next;
    }

    if (list1) tail->next = list1;
    if (list2) tail->next = list2;

    if (tail->next) tail->next->prev = tail;

    return dummy.next;
}

void serialize_list(Node* head, FILE* file) {
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

Node* deserialize_list(FILE* file) {
    Node dummy;
    Node* tail = &dummy;
    dummy.next = NULL;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = create_node(pdu);
        if (!new_node) continue;

        tail->next = new_node;
        new_node->prev = tail;
        tail = new_node;
    }

    return dummy.next;
}

void remove_duplicates(Node** head) {
    if (!head || !*head) return;

    Node* current = *head;
    while (current != NULL) {
        Node* runner = current->next;
        while (runner != NULL) {
            if (current->data.RNTI == runner->data.RNTI) {
                if (runner->prev) runner->prev->next = runner->next;
                if (runner->next) runner->next->prev = runner->prev;

                Node* temp = runner;
                runner = runner->next;
                free(temp);
            } else {
                runner = runner->next;
            }
        }
        current = current->next;
    }
}

// Example usage
int main() {
    Node* head = NULL;
    for (int i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = rand(), .CRC_INDICATION_REL8_TAG = i, .CRCFLAG = rand() % 2 };
        insert_at_tail(&head, pdu);
    }

    // Example of removing a node by RNTI
    if (head) remove_by_rnti(&head, head->data.RNTI);

    // Serialize and deserialize example
    FILE* file = fopen("list.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    file = fopen("list.bin", "rb");
    Node* new_head = deserialize_list(file);
    fclose(file);

    destroy_list(&head);
    destroy_list(&new_head);

    return 0;
}
