#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define VALID_RNTI_RANGE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint8_t CRCFLAG;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;
int successful_allocations_count = 0;

bool is_valid_rnti(uint16_t rnti) {
    return (rnti >= 0 && rnti < VALID_RNTI_RANGE);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_crc_pdu_array(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid size parameter: %zu\n", N);
        return NULL;
    }

    pthread_mutex_lock(&allocation_mutex);

    // Initial allocation attempt
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    // Random number generator for CRCFLAG
    srand((unsigned int)time(NULL));

    size_t i;
    for (i = 0; i < N; ++i) {
        pdu_array[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand() & 0xFFFF; // Example initialization

        uint16_t rnti = rand() % VALID_RNTI_RANGE;
        if (!is_valid_rnti(rnti)) {
            free(pdu_array);
            fprintf(stderr, "Failed to find a valid RNTI\n");
            pthread_mutex_unlock(&allocation_mutex);
            return NULL;
        }
        pdu_array[i].crc_indication_rel8_tag.RNTI = rnti;

        pdu_array[i].CRCFLAG = rand() & 1; // Randomly setting CRCFLAG

        successful_allocations_count++;
    }

    pthread_mutex_unlock(&allocation_mutex);
    return pdu_array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

int main() {
    size_t N = 10; // Example size
    NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_and_initialize_crc_pdu_array(N);

    if (pdus) {
        printf("Successfully allocated and initialized %zu structures.\n", successful_allocations_count);
        free_crc_pdu_array(pdus);
    } else {
        printf("Failed to allocate or initialize the array.\n");
    }

    return 0;
}
