#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define LONG_ARRAY_SIZE 1000
#define INT_ARRAY_SIZE 500
#define RECORD_ARRAY_SIZE 200
#define INT_VALUE_LIMIT 1000000
#define BUFFER_SIZE_LIMIT 50000

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    NFAPI_CRC_INDICATION_PDU_T CRC_INDICATION_REL8_TAG;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    Record *records;
    int count;
    int capacity;
} RecordList;

RecordList *init_record_list() {
    RecordList *list = (RecordList *)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record *)calloc(MAX_ELEMENTS, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->capacity = MAX_ELEMENTS;

    return list;
}

void destroy_record_list(RecordList *list) {
    if (list) {
        free(list->records);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_record_safely(RecordList *list, unsigned long RX_UE_INFORMATION_TAG, unsigned short RNTI, int CRCFLAG) {
    if (!list || list->count >= list->capacity) return -1;

    pthread_mutex_lock(&list->mutex);

    if (list->count < list->capacity) {
        Record new_record;
        new_record.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        new_record.RNTI = RNTI;
        new_record.CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;

        list->records[list->count++] = new_record;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void populate_random_data(RecordList *list) {
    srand(time(NULL));
    for (int i = 0; i < RECORD_ARRAY_SIZE && i + list->count < MAX_ELEMENTS; ++i) {
        unsigned long tag = rand() % LONG_ARRAY_SIZE;
        unsigned short rnti = rand() % INT_ARRAY_SIZE;
        int crcflag = rand() % 2;

        if (add_record_safely(list, tag, rnti, crcflag) != 0)
            break;
    }
}

int main() {
    RecordList *list = init_record_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize record list.\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))populate_random_data, (void *)list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Total records added: %d\n", list->count);

    destroy_record_list(list);
    return EXIT_SUCCESS;
}
```

### Explanation:

- **Concurrency:** The code uses a `pthread_mutex_t` to ensure that operations on the shared record list are thread-safe. This provides mutual exclusion and prevents race conditions during updates.

- **Dynamic Memory Allocation:** The record list is initialized with enough capacity for 10,000 elements. It starts with zero records and dynamically grows up to its capacity.

- **Random Data Generation:** Random data is generated using `srand` and `rand`. A function (`populate_random_data`) populates the list in a thread-safe manner by acquiring a lock before modifying the shared list structure.

- **Thread Management:** The main function creates multiple threads that concurrently populate the record list, demonstrating concurrent access handling. Each thread calls `populate_random_data`.

- **Resource Cleanup:** Proper cleanup of resources is ensured with `destroy_record_list`, which frees allocated memory and destroys mutexes to prevent leaks.

This implementation provides a foundational approach for managing shared data structures in a multi-threaded environment while considering performance and safety trade-offs. Adjustments might be needed based on specific use cases, especially concerning dynamic resizing and advanced lock-free techniques.']

