// Memory pool configuration
#define POOL_SIZE 1024 // Example size, adjust based on profiling results

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
} PduPoolItem;

typedef struct {
    PduPoolItem* items[POOL_SIZE];
    pthread_mutex_t lock;
} MemoryPool;

// Initialize the memory pool
void init_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool->items[i] = NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
}

// Acquire a structure from the pool
PduPoolItem* acquire_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->items[i] == NULL) {
            pool->items[i] = malloc(sizeof(PduPoolItem));
            pthread_mutex_unlock(&pool->lock);
            return pool->items[i];
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Pool exhausted
}

// Release a structure back to the pool
void release_to_pool(MemoryPool* pool, PduPoolItem* item) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->items[i] == NULL) {
            pool->items[i] = item;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to populate the list of NFAPI_CRC_INDICATION_PDU_T structures
