        item->pdu.rnti = generate_random_rnti();
        item->pdu.crc_indication_rel8_tag.crcflag = rand() % 2;

        pdu_list[success_count++] = *item;
        release_to_pool(pool, item);
    }

    log_info("Successfully processed %d elements", success_count);

    if (success_count != num_pdus) {
        log_warning("%d elements could not be processed due to pool exhaustion",
                    num_pdus - success_count);
    }

    return pdu_list;
}

// Example usage of logging
