NFAPI_CRC_INDICATION_PDU_T* resize_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t *current_size) {
    *current_size *= 2;
    array = realloc(array, (*current_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return array;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input> [file|port]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input = argv[1];
    int is_port;

    if (sscanf(argv[2], "%d", &is_port) == 1 && is_port > 0) {
        handle_network(is_port);
    } else {
        handle_file(input);
    }

    return EXIT_SUCCESS;
}

void handle_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    int line_count = 0;

    while (fgets(line, sizeof(line), file)) {
        line_count++;
    }

    printf("Number of lines: %d\n", line_count);

    fclose(file);
}

void handle_network(int port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serveraddr;
    memset(&serveraddr, 0, sizeof(serveraddr));
    serveraddr.sin_family = AF_INET;
    serveraddr.sin_addr.s_addr = INADDR_ANY;
    serveraddr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr *)&serveraddr, sizeof(serveraddr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    struct sockaddr_in clientaddr;
    socklen_t len = sizeof(clientaddr);
    size_t data_size = BUFFER_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(data_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        perror("Failed to allocate memory");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    int count = 0;
    while (1) {
        ssize_t n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&clientaddr, &len);

        if (n < 0) {
            perror("Receive failed");
            break;
        }

        process_data(&array, &count);

        // Adjust buffer size based on throughput and latency
        // This is a placeholder for dynamic adjustment logic.
    }

    free(array);
    close(sockfd);
}

int process_data(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size) {
    static int index = 0;
    if (index >= *size) {
        *array = resize_array(*array, size);
    }

    (*array)[index].RX_UE_INFORMATION_TAG = rand() % 1000;
    (*array)[index].RNTI = rand() % 10000;
    (*array)[index].CRC_INDICATION_REL8_TAG = rand() % 500;
    (*array)[index].CRCFLAG = 'Y'; // Randomly set CRCFLAG for demonstration

    index++;

    return 0;
}
