['Below is a C implementation of a function that manages a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures as described:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RNTI;
    unsigned char data[256]; // Example size, adjust as necessary
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    time_t timestamp;
    struct Node* next;
} Node;

// Global head pointer and mutex for thread-safe access
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Custom logging mechanism
FILE* log_file = NULL;
void initialize_logging(const char* filename) {
    if (log_file) fclose(log_file);
    log_file = fopen(filename, "a");
}

void log_message(const char* message) {
    if (!log_file) return;
    pthread_mutex_lock(&lock); // Ensure thread-safe logging
    fprintf(log_file, "%s\n", message);
    fflush(log_file); // Minimize I/O operations bottleneck
    pthread_mutex_unlock(&lock);
}

// Function to add a PDU to the linked list
void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    time_t current_time;
    Node *new_node, *current, *prev = NULL;

    // Acquire lock for thread safety
    pthread_mutex_lock(&lock);

    new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return;
    }

    memcpy(&new_node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current_time = time(NULL); // Get the current timestamp

    // Check for duplicates
    current = head;
    while (current) {
        if (current->pdu.RNTI == pdu->RNTI) {
            new_node->timestamp = current_time; // Assign unique timestamp
            break;
        }
        prev = current;
        current = current->next;
    }

    // Append new node at the end or before duplicates
    if (!current || current->pdu.RNTI != pdu->RNTI) {
        new_node->timestamp = time(NULL);
        new_node->next = head;
        head = new_node;
    } else {
        prev->next = new_node;
        new_node->next = current;
    }

    pthread_mutex_unlock(&lock);
}

// Function to free the linked list
void free_list() {
    Node *current = head, *temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}
```

### Key Points:
- **Thread Safety:** Mutex locks ensure safe concurrent access to the linked list and logging mechanism.
- **Memory Management:** Dynamically allocates nodes for the linked list, freeing them in `free_list()`.
- **Logging:** Custom logging writes messages to a file with minimized I/O operations by using `fflush()` immediately after writing.
- **Handling Duplicates:** Checks for duplicate RNTI values and appends unique timestamps.
- **Resource Management:** Ensure appropriate initialization and cleanup of resources like the log file.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct NR_CELL_INFO_T {
    int CELL_ID;
    int PCI;
    int RSRP_LEVEL;
    char timestamp[20]; // To handle duplicate PCI values
    struct NR_CELL_INFO_T *prev;
    struct NR_CELL_INFO_T *next;
} NR_CELL_INFO_T;

typedef struct {
    NR_CELL_INFO_T *head;
    NR_CELL_INFO_T *tail;
    pthread_mutex_t lock;
    int entry_count;
    FILE *log_file;
} ThreadSafeDoublyLinkedList;

// Function prototypes
int init_list(ThreadSafeDoublyLinkedList *list, const char *log_filename);
void destroy_list(ThreadSafeDoublyLinkedList *list);
int add_cell_info(ThreadSafeDoublyLinkedList *list, int cell_id, int pci, int rsrp_level);
void sort_list(ThreadSafeDoublyLinkedList *list, int ascending);

// Initialize the list
int init_list(ThreadSafeDoublyLinkedList *list, const char *log_filename) {
    if (!list || !log_filename) return -1;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->entry_count = 0;

    list->log_file = fopen(log_filename, "a");
    if (!list->log_file) return -1;

    fprintf(list->log_file, "List initialized.\n");
    fflush(list->log_file);

    return 0;
}

// Destroy the list
void destroy_list(ThreadSafeDoublyLinkedList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NR_CELL_INFO_T *current = list->head;
    while (current) {
        NR_CELL_INFO_T *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    if (list->log_file) fclose(list->log_file);

    fprintf(list->log_file, "List destroyed.\n");
    fflush(list->log_file);
}

// Add a new cell info
int add_cell_info(ThreadSafeDoublyLinkedList *list, int cell_id, int pci, int rsrp_level) {
    if (!list || cell_id < 0 || pci < 0 || rsrp_level < -140) return -1;

    pthread_mutex_lock(&list->lock);

    NR_CELL_INFO_T *current = list->head;
    while (current) {
        if (current->PCI == pci) {
            time_t now = time(NULL);
            strftime(current->timestamp, sizeof(current->timestamp), "%Y%m%d%H%M%S", localtime(&now));
            fprintf(list->log_file, "Duplicate PCI detected: %d\n", pci);
            fflush(list->log_file);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    NR_CELL_INFO_T *new_node = (NR_CELL_INFO_T *)malloc(sizeof(NR_CELL_INFO_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->CELL_ID = cell_id;
    new_node->PCI = pci;
    new_node->RSRP_LEVEL = rsrp_level;
    time_t now = time(NULL);
    strftime(new_node->timestamp, sizeof(new_node->timestamp), "%Y%m%d%H%M%S", localtime(&now));

    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->entry_count++;

    fprintf(list->log_file, "Cell info added: CELL_ID=%d, PCI=%d\n", cell_id, pci);
    fflush(list->log_file);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Sort the list based on RSRP_LEVEL
void sort_list(ThreadSafeDoublyLinkedList *list, int ascending) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    int swapped;
    NR_CELL_INFO_T *current;
    NR_CELL_INFO_T *last = NULL;

    do {
        swapped = 0;
        current = list->head;

        while (current->next != last) {
            if ((ascending && current->RSRP_LEVEL > current->next->RSRP_LEVEL) ||
                (!ascending && current->RSRP_LEVEL < current->next->RSRP_LEVEL)) {

                NR_CELL_INFO_T *temp = current->next;
                current->next = temp->next;
                temp->next = current;

                if (current == list->head) {
                    list->head = temp;
                } else {
                    current->prev->next = temp;
                }
                temp->prev = current->prev;
                current->prev = temp;

                swapped = 1;
            }
            current = current->next;
        }
        last = current;
    } while (swapped);

    pthread_mutex_unlock(&list->lock);

    fprintf(list->log_file, "List sorted. Entries: %d\n", list->entry_count);
    fflush(list->log_file);
}

// Example usage
int main() {
    ThreadSafeDoublyLinkedList list;
    if (init_list(&list, "cell_info.log") != 0) return -1;

    add_cell_info(&list, 1, 100, -90);
    add_cell_info(&list, 2, 101, -85);
    add_cell_info(&list, 3, 100, -95); // Duplicate PCI

    sort_list(&list, 1); // Sort ascending

    destroy_list(&list);

    return 0;
}
```

This code defines a thread-safe doubly linked list to manage `NR_CELL_INFO_T` structures. It uses mutexes for concurrency control and logs operations to a file. The list is initialized, populated with data, sorted by `RSRP_LEVEL`, and then destroyed while logging each step. Duplicate PCI values are appended with a timestamp-based unique identifier.']

