DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void resize_if_needed(DynamicArray *array) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data != NULL) {
            pthread_mutex_lock(&array->mutex);
            array->data = new_data;
            array->capacity = new_capacity;
            pthread_mutex_unlock(&array->mutex);
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Memory reallocation failed\n");
        }
    }
}

void add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    resize_if_needed(array);

    array->data[array->size] = element;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

int update_element_by_RNTI(DynamicArray *array, int RNTI, NFAPI_CRC_INDICATION_PDU_T updated_element) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == RNTI) {
            array->data[i] = updated_element;
            pthread_mutex_unlock(&array->mutex);
            return 1; // Success
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return 0; // Not found
}

int remove_element_by_RNTI(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == RNTI) {
            memmove(&array->data[i], &array->data[i + 1],
                    (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->size--;
            pthread_mutex_unlock(&array->mutex);
            return 1; // Success
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return 0; // Not found
}

void validate_data(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (!fetch_RNTI_from_db(array->data[i].RNTI)) {
            fprintf(stderr, "Invalid RNTI at index %zu\n", i);
            // Handle invalid data
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

