SimpleCache cache;

void initialize_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache.key[i] = NULL;
        cache.value[i] = NULL;
        cache.usage[i] = -1;
    }
}

char* get_from_cache(const char* key) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.key[i] && strcmp(cache.key[i], key) == 0) {
            cache.usage[i] = 0;
            for (int j = 0; j < CACHE_SIZE - 1; ++j) {
                if (cache.usage[j] > cache.usage[j + 1]) {
                    // Swap
                    char* temp_key = cache.key[j];
                    cache.key[j] = cache.key[j + 1];
                    cache.key[j + 1] = temp_key;

                    char* temp_value = cache.value[j];
                    cache.value[j] = cache.value[j + 1];
                    cache.value[j + 1] = temp_value;

                    int temp_usage = cache.usage[j];
                    cache.usage[j] = cache.usage[j + 1];
                    cache.usage[j + 1] = temp_usage;
                }
            }
            return cache.value[i];
        }
    }
    return NULL;
}

void add_to_cache(const char* key, const char* value) {
    int least_used_index = -1;
    int max_usage = INT_MIN;

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.usage[i] > max_usage) {
            max_usage = cache.usage[i];
            least_used_index = i;
        }
    }

    if (least_used_index != -1) {
        free(cache.key[least_used_index]);
        free(cache.value[least_used_index]);

        cache.key[least_used_index] = strdup(key);
        cache.value[least_used_index] = strdup(value);
        cache.usage[least_used_index] = 0;
    } else {
        for (int i = 0; i < CACHE_SIZE - 1; ++i) {
            if (cache.usage[i] >= 0) {
                free(cache.key[i]);
                free(cache.value[i]);

                cache.key[i] = strdup(key);
                cache.value[i] = strdup(value);
                cache.usage[i] = 0;
            }
        }
    }

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.usage[i] >= 0) {
            cache.usage[i]++;
        }
    }
}

