typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *nfa_list = NULL;
size_t nfa_count = 0;

// Function prototypes
int create_and_populate_nfa_list(size_t num_elements, uint8_t crc_threshold, uint8_t min_crcflag);
void free_nfa_list();

// Helper function to generate a random RNTI
uint16_t generate_random_rnti() {
    return rand() % (MAX_RNTI + 1);
}

// Function to create and populate the list
int create_and_populate_nfa_list(size_t num_elements, uint8_t crc_threshold, uint8_t min_crcflag) {
    pthread_mutex_lock(&mutex);

    // Reallocate memory if needed
    nfa_list = realloc(nfa_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (!nfa_list) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    uint8_t crc_sum = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &nfa_list[i];

        do {
            pdu->RX_UE_INFORMATION_TAG = rand();
            pdu->RNTI = generate_random_rnti();
            pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
        } while (check_rnti_exists(pdu->RNTI));

        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        if (pdu->CRCFLAG >= min_crcflag) {
            crc_sum += pdu->CRCFLAG;
        }

        if (crc_sum > crc_threshold) {
            free_nfa_list();
            pthread_mutex_unlock(&mutex);
            return -1; // Exceeded CRC threshold
        }
    }

    nfa_count = num_elements;
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to check if RNTI exists in the list
int check_rnti_exists(uint16_t rnti) {
    for (size_t i = 0; i < nfa_count; ++i) {
        if (nfa_list[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

// Function to free the allocated list
void free_nfa_list() {
    pthread_mutex_lock(&mutex);
    free(nfa_list);
    nfa_list = NULL;
    nfa_count = 0;
    pthread_mutex_unlock(&mutex);
}
