['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 50000

typedef struct {
    unsigned char L2_ADDR[6];
    int sequence_number;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T *array;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
    char log_buffer[1024];
    size_t log_pos;
    pthread_mutex_t log_lock;
} DynamicArrayManager;

DynamicArrayManager* create_manager(const char* log_filename) {
    DynamicArrayManager* manager = malloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    manager->array = calloc(MAX_ENTRIES, sizeof(MAC_CONTEXT_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        free(manager->array);
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->log_pos = 0;
    pthread_mutex_init(&manager->log_lock, NULL);

    return manager;
}

void log_message(DynamicArrayManager* manager, const char *message) {
    size_t len = snprintf(manager->log_buffer + manager->log_pos, sizeof(manager->log_buffer) - manager->log_pos, "%s\n", message);
    if (len >= sizeof(manager->log_buffer) - manager->log_pos) {
        pthread_mutex_lock(&manager->log_lock);
        fwrite(manager->log_buffer, 1, manager->log_pos, manager->log_file);
        manager->log_pos = 0;
        pthread_mutex_unlock(&manager->log_lock);

        log_message(manager, message); // Retry logging
    } else {
        manager->log_pos += len;
        if (manager->log_pos >= sizeof(manager->log_buffer) / 2) { // Flush periodically
            pthread_mutex_lock(&manager->log_lock);
            fwrite(manager->log_buffer, 1, manager->log_pos, manager->log_file);
            manager->log_pos = 0;
            pthread_mutex_unlock(&manager->log_lock);
        }
    }
}

int add_mac_context(DynamicArrayManager* manager, const unsigned char *L2_ADDR) {
    if (!manager || !manager->array) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (memcmp(manager->array[i].L2_ADDR, L2_ADDR, sizeof(L2_ADDR)) == 0) {
            manager->array[i].sequence_number++;
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Duplicate L2_ADDR found, sequence number updated to %d", manager->array[i].sequence_number);
            log_message(manager, log_msg);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space
    }

    memcpy(manager->array[manager->count].L2_ADDR, L2_ADDR, sizeof(L2_ADDR));
    manager->array[manager->count].sequence_number = 0;
    manager->count++;

    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Added MAC context: %02x:%02x:%02x:%02x:%02x:%02x",
             L2_ADDR[0], L2_ADDR[1], L2_ADDR[2],
             L2_ADDR[3], L2_ADDR[4], L2_ADDR[5]);
    log_message(manager, log_msg);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void destroy_manager(DynamicArrayManager* manager) {
    if (manager) {
        free(manager->array);
        fclose(manager->log_file);
        pthread_mutex_destroy(&manager->lock);
        pthread_mutex_destroy(&manager->log_lock);
        free(manager);
    }
}
```

This code defines a `DynamicArrayManager` for managing up to 50,000 MAC context entries. It ensures thread safety using mutexes and provides a logging mechanism with buffered writes to minimize disk I/O operations. The function handles duplicate `L2_ADDR` values by updating sequence numbers and logs these events efficiently.']

['Below is an implementation of a C function designed to manage a dynamic array of `NFAPI_RX_PDU_T` structures in a high-performance mobile network base station environment.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    // Example fields
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    float signal_strength;
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T *sessions;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// Initialize the session manager
int initSessionManager(SessionManager *manager) {
    manager->sessions = NULL;
    manager->count = 0;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        return -1; // Failed to initialize mutex
    }
    return 0;
}

// Add a new session
int addSession(SessionManager *manager, NFAPI_RX_PDU_T session) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Max sessions reached
    }

    manager->sessions = realloc(manager->sessions, sizeof(NFAPI_RX_PDU_T) * (manager->count + 1));
    if (!manager->sessions) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update a session by RNTI
int updateSession(SessionManager *manager, int rnti, float new_signal_strength) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].RNTI == rnti) {
            manager->sessions[i].signal_strength = new_signal_strength;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

// Remove a session by RNTI
int removeSession(SessionManager *manager, int rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].RNTI == rnti) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    sizeof(NFAPI_RX_PDU_T) * (manager->count - i - 1));
            manager->count--;
            manager->sessions = realloc(manager->sessions, sizeof(NFAPI_RX_PDU_T) * manager->count);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Removed
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

// Free resources and clean up
void freeSessionManager(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->sessions);
    manager->count = 0;

    if (pthread_mutex_destroy(&manager->lock) != 0) {
        // Handle error
    }

    pthread_mutex_unlock(&manager->lock);
}

// Monitor and log memory usage or performance issues (Placeholder for actual implementation)
void monitorPerformance(SessionManager *manager) {
    // Implement monitoring logic here
}
```

### Key Points:
- **Concurrency**: The use of `pthread_mutex_t` ensures thread-safe access to the session data.
- **Dynamic Memory Management**: Sessions are stored in a dynamically allocated array, resized as needed.
- **Error Handling**: Functions return error codes for conditions like max sessions reached or memory allocation failures.
- **Scalability**: Efficiently handles up to 10,000 sessions with minimal latency by using `realloc` and `memmove`.
- **Monitoring**: Placeholder function `monitorPerformance` for real-time performance monitoring.

This implementation provides a robust foundation for managing UE sessions in a mobile network environment.']

