    new_node->data = result;
    new_node->next = NULL;
    return new_node;
}

void add_measurement(MeasurementList* list, LTE_MEASUREMENT_RESULT result) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(result);

    if (list->head == NULL || list->head->data.TIMESTAMP > result.TIMESTAMP) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->data.TIMESTAMP <= result.TIMESTAMP) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);

