    while (current != NULL && current->data.CELL_ID != cell_id) {
        current = current->next;
    }

    if (current != NULL) {
        current->data = new_result;
    }

    pthread_mutex_unlock(&list->lock);
}

void validate_data(MeasurementList* list) {
