#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int session_id;
    uint64_t rx_data_bytes;
    uint64_t tx_data_bytes;
    uint64_t rx_packets;
    uint64_t tx_packets;
    uint64_t rx_errors;
} UE_Session_Stats;

typedef struct Node {
    UE_Session_Stats data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_or_update_session(DynamicArray* array, UE_Session_Stats stats) {
    pthread_mutex_lock(&array->lock);

    Node** current = &array->head;
    while (*current != NULL) {
        if ((*current)->data.session_id == stats.session_id) {
            // Update existing session
            (*current)->data = stats;
            pthread_mutex_unlock(&array->lock);
            return 1; // Updated
        }
        current = &(*current)->next;
    }

    // Add new session
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Out of memory
    }
    new_node->data = stats;
    new_node->next = NULL;
    *current = new_node;

    pthread_mutex_unlock(&array->lock);
    return 0; // Added
}

uint64_t get_total_data_transfer(DynamicArray* array) {
    uint64_t total_rx = 0, total_tx = 0;

    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        total_rx += current->data.rx_data_bytes;
        total_tx += current->data.tx_data_bytes;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return total_rx + total_tx;
}

// Example usage
int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array.\n");
        return 1;
    }

    UE_Session_Stats stats1 = {1, 1000, 2000, 10, 20, 1};
    add_or_update_session(array, stats1);

    UE_Session_Stats stats2 = {2, 3000, 4000, 30, 40, 2};
    add_or_update_session(array, stats2);

    uint64_t total_data_transfer = get_total_data_transfer(array);
    printf("Total Data Transfer: %llu\n", total_data_transfer);

    destroy_dynamic_array(array);
    return 0;
}
