#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 100000
#define RETENTION_PERIOD_DAYS 30

typedef enum { ACTIVE, INACTIVE } SessionStatus;
typedef struct {
    char session_id[36];
    int user_id;
    time_t start_time;
    time_t end_time;
    SessionStatus status;
    char device_type[50];
    char location[100];
    time_t duration; // in seconds
} User_Session_Record;

typedef struct Node {
    User_Session_Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SessionList;

SessionList sessions = {NULL, PTHREAD_MUTEX_INITIALIZER};

void log_external_service(const char *message) {
    // Placeholder for external logging service integration
    printf("Log: %s\n", message);
}

Node* create_node(User_Session_Record record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    memcpy(&new_node->record, &record, sizeof(User_Session_Record));
    new_node->next = NULL;
    return new_node;
}

void add_session_record(User_Session_Record record) {
    pthread_mutex_lock(&sessions.lock);

    Node* current = sessions.head;
    Node* prev = NULL;

    while (current && strcmp(current->record.session_id, record.session_id) != 0) {
        prev = current;
        current = current->record.next;
    }

    if (current) { // Update existing
        memcpy(&current->record, &record, sizeof(User_Session_Record));
    } else { // Add new
        Node* new_node = create_node(record);
        if (!new_node) {
            pthread_mutex_unlock(&sessions.lock);
            return;
        }
        if (prev) {
            prev->next = new_node;
        } else {
            sessions.head = new_node;
        }
    }

    pthread_mutex_unlock(&sessions.lock);
}

void cleanup_old_records() {
    time_t now = time(NULL);
    time_t cutoff = now - (RETENTION_PERIOD_DAYS * 24 * 60 * 60);

    pthread_mutex_lock(&sessions.lock);

    Node* current = sessions.head;
    Node* prev = NULL;

    while (current) {
        if (current->record.start_time < cutoff) {
            Node* to_delete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                sessions.head = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->record.next;
        }
    }

    pthread_mutex_unlock(&sessions.lock);

    log_external_service("Old records cleaned up.");
}

long get_total_active_duration(int user_id) {
    long total_duration = 0;

    pthread_mutex_lock(&sessions.lock);

    Node* current = sessions.head;

    while (current) {
        if (current->record.user_id == user_id && current->record.status == ACTIVE) {
            total_duration += current->record.duration;
        }
        current = current->record.next;
    }

    pthread_mutex_unlock(&sessions.lock);

    return total_duration;
}

void* session_update_worker(void* arg) {
    User_Session_Record record = *(User_Session_Record*)arg;
    add_session_record(record);
    free(arg); // Free the dynamically allocated memory for the argument
    return NULL;
}

void handle_concurrent_updates(User_Session_Record* records, int count) {
    pthread_t threads[count];

    for (int i = 0; i < count; ++i) {
        User_Session_Record* record_copy = malloc(sizeof(User_Session_Record));
        if (!record_copy) continue;

        memcpy(record_copy, &records[i], sizeof(User_Session_Record));
        pthread_create(&threads[i], NULL, session_update_worker, record_copy);
    }

    for (int i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void periodic_cleanup() {
    while (1) {
        sleep(60); // Run cleanup every minute
        cleanup_old_records();
    }
}

// Example usage
int main() {
    // Start the periodic cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, (void*)periodic_cleanup, NULL);

    User_Session_Record record = {"1", 1001, time(NULL), time(NULL) + 3600, ACTIVE, "Mobile", "USA", 3600};
    handle_concurrent_updates(&record, 1);

    printf("Total active duration: %ld seconds\n", get_total_active_duration(1001));

    pthread_join(cleanup_thread, NULL); // This example won't reach here normally
    return 0;
}
