// Global variables for configuration
static int max_concurrent_threads = 10; // Default value, can be set via environment variable
static int lock_contention_threshold = 5; // Default value, configurable

// Logger function to log errors and messages
void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_rwlock_t lock; // Reader-writer lock for concurrent access
} NFAPICRCList;

// Function to initialize the list
NFAPICRCList* nfapi_crc_list_init(size_t initial_size) {
    NFAPICRCList *list = malloc(sizeof(NFAPICRCList));
    if (!list) {
        log_error("Failed to allocate memory for NFAPICRCList");
        return NULL;
    }

    list->pdus = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        log_error("Failed to allocate memory for PDU array");
        return NULL;
    }

    pthread_rwlock_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

// Function to add a new PDU
int nfapi_crc_list_add(NFAPICRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !pdu) return -1;

    pthread_rwlock_wrlock(&list->lock);
    size_t new_count = list->count + 1;

    // Resize array if needed
    if (new_count > list->pdus) { 
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(list->pdus, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_rwlock_unlock(&list->lock);
            log_error("Failed to reallocate memory for PDU array");
            return -1;
        }
        list->pdus = new_pdus;
    }

    // Add the new PDU
    list->pdus[list->count] = pdu;
    list->count = new_count;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Function to free the list resources
void nfapi_crc_list_free(NFAPICRCList *list) {
    if (list) {
        pthread_rwlock_wrlock(&list->lock);
        free(list->pdus);
        pthread_rwlock_unlock(&list->lock);

        pthread_rwlock_destroy(&list->lock);
        free(list);
    }
}

// Function to determine the largest integer in a list
void find_largest_integer() {
    int *numbers = NULL;
    size_t capacity = 0, count = 0;

    printf("Enter integers (end with non-integer input):\n");

    while (1) {
        char input[256];
        if (!fgets(input, sizeof(input), stdin)) break; // End of input

        int number;
        if (sscanf(input, "%d", &number) == 1) {
            if (count >= capacity) {
                size_t new_capacity = capacity ? capacity * 2 : 4;
                int *new_numbers = realloc(numbers, new_capacity * sizeof(int));
                if (!new_numbers) {
                    log_error("Failed to reallocate memory for numbers array");
                    free(numbers);
                    return;
                }
                numbers = new_numbers;
                capacity = new_capacity;
            }
            numbers[count++] = number;
        } else {
            break; // Non-integer input encountered
        }
    }

    if (count == 0) {
        printf("No valid integers entered.\n");
        free(numbers);
        return;
    }

    int largest = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
