#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

// Assuming LTE specification structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node definition for linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Record structure with an integer value and a character buffer
typedef struct {
    int value;
    char *buffer;
} Record;

// Function prototypes
ListNode* populateLinkedList(int count);
void freeLinkedList(ListNode* head);
Record* initializeRecords(int size, int max_value, long sum_limit, long buffer_size_limit);
void freeRecords(Record* records, int size);

int main() {
    // Example usage
    ListNode* list = populateLinkedList(10000);
    Record* records = initializeRecords(1000, 100, 500000, 1000000);

    // Free resources
    freeLinkedList(list);
    freeRecords(records, 1000);

    return 0;
}

// Function to dynamically create and link NFAPI_CRC_INDICATION_PDU_T structures in a linked list
ListNode* populateLinkedList(int count) {
    if (count <= 0) return NULL;

    ListNode *head = NULL, *tail = NULL, *current = NULL;
    int prevRNTI = -1; // To ensure no two consecutive structures have the same RNTI

    for (int i = 0; i < count; ++i) {
        current = (ListNode*)malloc(sizeof(ListNode));
        if (!current) {
            perror("Failed to allocate memory");
            freeLinkedList(head);
            return NULL;
        }

        current->data.RX_UE_INFORMATION_TAG = rand(); // Unique tag
        do {
            current->data.RNTI = rand() % 1000; // Example range, modify as needed
        } while (current->data.RNTI == prevRNTI);

        current->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (!head) {
            head = current;
        } else {
            tail->next = current;
        }
        tail = current;
        prevRNTI = current->data.RNTI;

        current->next = NULL;
    }

    return head;
}

// Function to free the linked list
void freeLinkedList(ListNode* head) {
    ListNode *current = head, *nextNode;
    while (current) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }
}

// Function to initialize records with random values and dynamic buffers
Record* initializeRecords(int size, int max_value, long sum_limit, long buffer_size_limit) {
    if (size <= 0) return NULL;

    Record *records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    long current_sum = 0;
    long current_buffer_size = 0;

    for (int i = 0; i < size; ++i) {
        int value = rand() % max_value + 1;

        if (current_sum + value > sum_limit || 
            current_buffer_size + value * sizeof(char) > buffer_size_limit) {
            fprintf(stderr, "Cannot allocate more records without exceeding limits\n");
            freeRecords(records, i);
            return NULL;
        }

        records[i].value = value;
        records[i].buffer = (char*)malloc(value * sizeof(char));
        if (!records[i].buffer) {
            perror("Failed to allocate buffer");
            freeRecords(records, i + 1);
            return NULL;
        }
        current_sum += value;
        current_buffer_size += value * sizeof(char);
    }

    return records;
}

// Function to free the allocated records and their buffers
void freeRecords(Record* records, int size) {
    if (!records) return;

    for (int i = 0; i < size; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
```

### Key Points:

- **Dynamic Allocation:** Memory is dynamically allocated using `malloc` and freed appropriately to prevent leaks.

- **Memory Management:** The linked list and records are managed separately, with checks for allocation failures.

- **Unique RNTI:** Ensures no two consecutive nodes in the linked list have the same `RNTI`.

- **Random Values:** Uses `rand()` to generate random values within specified constraints.

- **Error Handling:** Includes error handling for memory allocation failures and ensures graceful degradation.

- **Concurrency Considerations:** While this code does not implement concurrency, it sets up structures that could be adapted for thread-safe operations using mutexes or atomic operations as needed.

This implementation provides a foundation for further development, including integration with LTE signaling libraries and additional performance optimizations.']

