#include <stdio.h>
#include <stdlib.h>
import threading

#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char *timestamp;
    int log_level;
    char *message;
    char *metadata_id;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread-safe operations
    size_t pool_size;
    void** memory_pool;
} LogList;

// Initialize a dynamic log list with a memory pool
LogList* initialize_log_list(size_t initial_capacity) {
    LogList* list = (LogList*)malloc(sizeof(LogList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->pool_size = initial_capacity;
    list->memory_pool = (void**)calloc(initial_capacity, sizeof(void*));

    if (!list->memory_pool) {
        free(list);
        return NULL;
    }

    return list;
}

// Custom memory allocator using a memory pool
void* allocate_from_pool(LogList* list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->pool_size; ++i) {
        if (!list->memory_pool[i]) {
            void* block = malloc(sizeof(Node));
            if (!block) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            list->memory_pool[i] = block;
            pthread_mutex_unlock(&list->lock);
            return block;
        }
    }

    // Pool is full; expand the pool
    size_t new_size = list->pool_size * 2;
    void** new_pool = (void**)realloc(list->memory_pool, new_size * sizeof(void*));
    if (!new_pool) {
        fprintf(stderr, "Failed to resize memory pool\n");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    list->memory_pool = new_pool;
    for (size_t i = list->pool_size; i < new_size; ++i) {
        list->memory_pool[i] = NULL;
    }

    void* block = malloc(sizeof(Node));
    if (!block) {
        fprintf(stderr, "Memory allocation failed after pool expansion\n");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    list->memory_pool[new_size - 1] = block;
    list->pool_size = new_size;

    pthread_mutex_unlock(&list->lock);
    return block;
}

// Add a log entry to the dynamic list
void add_log_entry(LogList* list, LogEntry entry) {
    if (!list) return;

    Node* new_node = (Node*)allocate_from_pool(list);
    if (!new_node) return;

    new_node->entry = entry;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    // Add to the front of the list for O(1) complexity
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Parse a log file and add entries to the dynamic list
void parse_log_file(LogList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        LogEntry entry;
        // Simplified parsing logic
        sscanf(line, "%ms %d %[^\n]s %ms", &entry.timestamp, &entry.log_level, &entry.message, &entry.metadata_id);

        add_log_entry(list, entry);
    }

    fclose(file);
}

// Cleanup and free the log list resources
void cleanup_log_list(LogList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->entry.timestamp);
        free(current->entry.message);
        free(current->entry.metadata_id);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);

    free(list->memory_pool);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    LogList* log_list = initialize_log_list(10);
    if (!log_list) return 1;

    parse_log_file(log_list, "logfile.txt");

    // Further processing of the log list

    cleanup_log_list(log_list);

    return 0;
}
