int initialize_structures(int long_array_size, int key_array_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *crcArray = NULL;
    long *longArray = NULL;
    int *keyArray = NULL;
    record_t *recordArray = NULL;

    // Calculate the size of the largest array
    int max_array_size = (long_array_size > key_array_size) ? long_array_size : key_array_size;

    // Allocate memory for structures
    crcArray = malloc(max_array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    longArray = malloc(long_array_size * sizeof(long));
    keyArray = calloc(key_array_size, sizeof(int));  // Initialize to zero

    if (!crcArray || !longArray || !keyArray) {
        log_error("Memory allocation failed");
        free(crcArray);
        free(longArray);
        free(keyArray);
        return -1;
    }

    // Populate CRC array with random data
    srand(time(NULL));
    for (int i = 0; i < max_array_size; ++i) {
        crcArray[i].RX_UE_INFORMATION_TAG = rand();
        crcArray[i].RNTI = rand();
        crcArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
    }

    // Populate long array with random data
    for (int i = 0; i < long_array_size; ++i) {
        longArray[i] = rand();
    }

    // Populate key array ensuring no duplicates
    int unique_keys = 0;
    while (unique_keys < key_array_size) {
        int new_key = rand() % KEY_RANGE;
        if (!keyArray[new_key]) {
            keyArray[new_key] = 1; // Mark as used
            ++unique_keys;
        }
    }

    // Allocate and populate record array
    recordArray = malloc(max_array_size * sizeof(record_t));
    if (!recordArray) {
        log_error("Memory allocation failed for record array");
        free(crcArray);
        free(longArray);
        free(keyArray);
        return -1;
    }

    int unique_value = 0;
    while (unique_value < max_array_size) {
        int new_value = rand() % KEY_RANGE;
        pthread_mutex_lock(&mutex); // Ensure thread-safe access
        if (!keyArray[new_value]) { // Check for uniqueness using keyArray as a tracker
            keyArray[new_value] = 1; // Mark as used
            recordArray[unique_value].value = new_value;
            ++unique_value;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Cleanup and return success
    free(crcArray);
    free(longArray);
    free(keyArray);
    free(recordArray);

    pthread_mutex_destroy(&mutex);
    return 0; // Success
}

int main() {
