NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_crc_pdu_array(size_t num_entries) {
    if (num_entries == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        return NULL;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Temporary array to track RNTIs for validation
    uint32_t *rnti_tracker = malloc(num_entries * sizeof(uint32_t));
    if (!rnti_tracker) {
        log_error("Memory allocation failed for RNTI tracker");
        free(array);
        return NULL;
    }

    memset(rnti_tracker, 0, num_entries * sizeof(uint32_t));

    for (size_t i = 0; i < num_entries; ++i) {
        array[i].RX_UE_INFORMATION_TAG = (uint16_t)i + 1; // Unique tag
        uint32_t rnti;
        do {
            rnti = rand() % UINT32_MAX + 1; // Random RNTI, avoiding zero
        } while (rnti_tracker[rnti % num_entries] != 0);

        array[i].RNTI = rnti;

        if (!rnti_tracker[rnti % num_entries]) {
            rnti_tracker[rnti % num_entries] = rnti;
        } else {
            log_error("Duplicate RNTI detected");
            free(array);
            free(rnti_tracker);
            return NULL;
        }

        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag
    }

    free(rnti_tracker);
    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
