['Below is a C implementation for managing a dynamic array of `LTE_ENBCONFIG_T` structures that address the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int CI; // Cell Identity
    int BWP; // Bandwidth Part configuration
    char *DCI; // Downlink Control Information buffer
} LTE_ENBCONFIG_T;

typedef struct {
    LTE_ENBCONFIG_T **configs;
    size_t count;
    size_t capacity;
} LTE_CONFIG_MANAGER;

// Function prototypes
LTE_CONFIG_MANAGER* create_manager(size_t initial_capacity);
void destroy_manager(LTE_CONFIG_MANAGER *manager);
int add_or_update_entry(LTE_CONFIG_MANAGER *manager, int CI, int BWP, const char *DCI_data);
int remove_entry_by_CI(LTE_CONFIG_MANAGER *manager, int CI);

// Internal helper functions
static LTE_ENBCONFIG_T* find_entry(LTE_CONFIG_MANAGER *manager, int CI);
static void resize_manager_if_needed(LTE_CONFIG_MANAGER *manager);

LTE_CONFIG_MANAGER* create_manager(size_t initial_capacity) {
    LTE_CONFIG_MANAGER *manager = (LTE_CONFIG_MANAGER*)malloc(sizeof(LTE_CONFIG_MANAGER));
    if (!manager) return NULL;

    manager->configs = (LTE_ENBCONFIG_T**)calloc(initial_capacity, sizeof(LTE_ENBCONFIG_T*));
    manager->count = 0;
    manager->capacity = initial_capacity;

    return manager;
}

void destroy_manager(LTE_CONFIG_MANAGER *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configs[i]->DCI);
        free(manager->configs[i]);
    }
    free(manager->configs);
    free(manager);
}

int add_or_update_entry(LTE_CONFIG_MANAGER *manager, int CI, int BWP, const char *DCI_data) {
    LTE_ENBCONFIG_T *entry = find_entry(manager, CI);

    if (!entry) { // Entry not found, add new
        resize_manager_if_needed(manager);

        entry = (LTE_ENBCONFIG_T*)malloc(sizeof(LTE_ENBCONFIG_T));
        if (!entry) return -1; // Memory allocation failed

        manager->configs[manager->count++] = entry;
    }

    // Update or allocate DCI buffer
    size_t dci_size = strlen(DCI_data) + 1;
    char *new_dci_buffer = (char*)malloc(dci_size);
    if (!new_dci_buffer) return -1; // Memory allocation failed

    free(entry->DCI); // Free old buffer if exists
    entry->DCI = new_dci_buffer;
    strcpy(entry->DCI, DCI_data);

    // Update BWP configuration
    entry->BWP = BWP;

    return 0; // Success
}

int remove_entry_by_CI(LTE_CONFIG_MANAGER *manager, int CI) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i]->CI == CI) {
            free(manager->configs[i]->DCI);
            free(manager->configs[i]);

            // Shift remaining entries
            memmove(&manager->configs[i], &manager->configs[i + 1], 
                    (manager->count - i - 1) * sizeof(LTE_ENBCONFIG_T*));

            manager->count--;
            return 0; // Success
        }
    }
    return -1; // Entry not found
}

static LTE_ENBCONFIG_T* find_entry(LTE_CONFIG_MANAGER *manager, int CI) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->configs[i]->CI == CI) {
            return manager->configs[i];
        }
    }
    return NULL;
}

static void resize_manager_if_needed(LTE_CONFIG_MANAGER *manager) {
    if (manager->count >= manager->capacity) { // Time to resize
        size_t new_capacity = manager->capacity * 2;
        LTE_ENBCONFIG_T **new_configs = (LTE_ENBCONFIG_T**)realloc(manager->configs, 
                    new_capacity * sizeof(LTE_ENBCONFIG_T*));

        if (!new_configs) return; // Handle allocation failure gracefully

        memset(new_configs + manager->capacity, 0, 
               (new_capacity - manager->capacity) * sizeof(LTE_ENBCONFIG_T*));

        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }
}
```

