    if (!list || !memory_pool || pool_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTS) {
        fprintf(stderr, "Initialization failed due to invalid parameters or insufficient memory.\n");
        return -1;
    }

    memset(list->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_STRUCTS);
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

int add_structure(NFAPI_CRC_LIST *list, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    if (!list || !memory_pool || pool_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTS) {
        fprintf(stderr, "Add failed due to invalid parameters or insufficient memory.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory pool limit reached. Cannot add more structures.\n");
        return -2;
    }

    size_t required_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void *ptr = (char*)memory_pool + list->count * required_size;

    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)ptr;
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->tag_rel8.CRC_INDICATION_REL8_TAG = 0; // Initialize with a default value
    new_struct->tag_rel8.CRCFLAG = calculate_crcflag(RNTI);

    list->data[list->count++] = new_struct;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int get_structure_count(const NFAPI_CRC_LIST *list) {
    if (!list) {
        fprintf(stderr, "Invalid list pointer.\n");
        return -1;
    }

    int count = -1;
    pthread_mutex_lock(&list->lock);
    count = (int)list->count;
    pthread_mutex_unlock(&list->lock);

    return count;
}

// Example usage in a multi-threaded environment
void* thread_function(void *arg) {
    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST*)arg;
    for (int i = 0; i < 100; ++i) {
        add_structure(list, i, i + 1);
    }
    return NULL;
}

int main() {
