    pool_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTS;
    memory_pool = malloc(pool_size);

    if (!memory_pool) {
        fprintf(stderr, "Failed to allocate memory pool.\n");
        return -1;
    }

    NFAPI_CRC_LIST list;
    initialize_list(&list);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &list)) {
            fprintf(stderr, "Error creating thread\n");
            return -1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Total structures added: %d\n", get_structure_count(&list));

    free(memory_pool);
    return 0;
}
