        ConnectionEntry *new_entries = (ConnectionEntry *)realloc(list->entries, new_capacity * sizeof(ConnectionEntry));
        if (!new_entries) return -1; // Memory allocation failed

        memset(new_entries + list->capacity, 0, list->capacity * sizeof(ConnectionEntry)); // Initialize new entries
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    ConnectionEntry *entry = &list->entries[list->count++];
    entry->rrc_message = *rrc_message; // Assuming shallow copy is sufficient

    if (data_size > 0) {
        entry->data_payload = malloc(data_size);
        if (!entry->data_payload) return -1; // Memory allocation failed
        entry->data_size = data_size;
    } else {
        entry->data_payload = NULL;
        entry->data_size = 0;
    }

    return 0;
}

void free_connection_list(NFAPIConnectionList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].data_payload);
    }
    free(list->entries);
    free(list);
}

const ConnectionEntry* get_entry(const NFAPIConnectionList *list, size_t index) {
    if (index >= list->count) return NULL;
    return &list->entries[index];
}
