    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
} NFAPIList;

void logError(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

int isValidRNTI(uint16_t rnti) {
    return (rnti >= 0 && rnti <= 65535);
}

NFAPIList* createNFAPIList() {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) {
        logError("Memory allocation failed for list structure.");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

void addElement(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || !isValidRNTI(element.RNTI)) {
        logError("Invalid RNTI or null list.");
        return;
    }

    if (list->size >= MAX_ELEMENTS) {
        logError("Maximum capacity exceeded.");
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        logError("Memory allocation failed for new node.");
        return;
    }

    memcpy(&newNode->data, &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    newNode->next = list->head;
    list->head = newNode;
    list->size++;
}

void iterateAndPrint(NFAPIList* list) {
    if (!list || !list->head) return;

    Node* current = list->head;
    while (current) {
        printf("RNTI: %u\n", current->data.RNTI);
        // Print other fields as needed
        current = current->next;
    }
}

void freeNFAPIList(NFAPIList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

int main() {
    srand(time(NULL));

    NFAPIList* nfaPIList = createNFAPIList();
    if (!nfaPIList) return EXIT_FAILURE;

    for (size_t i = 0; i < MAX_ELEMENTS + 10; ++i) { // Test exceeding capacity
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 65536;

        addElement(nfaPIList, pdu);
    }

    iterateAndPrint(nfaPIList);

    freeNFAPIList(nfaPIList);
    return EXIT_SUCCESS;
}
