#define MAX_RETRIES 3

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_datasets(LTE_Uplink_NRCGF_Dataset **datasets, size_t count) {
    if (!datasets || !count) return;

    // Allocate memory for datasets
    *datasets = malloc(count * sizeof(LTE_Uplink_NRCGF_Dataset));
    if (*datasets == NULL) {
        log_error("Memory allocation failed for datasets");
        return;
    }

    pthread_t threads[count];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Initialize each dataset
    for (size_t i = 0; i < count; ++i) {
        LTE_Uplink_NRCGF_Dataset *dataset = &(*datasets)[i];

        pthread_mutex_lock(&mutex);
        dataset->rnti = rand();  // Unique RNTI

        pthread_attr_destroy(&attr);

        pthread_create(&threads[i], NULL, fetch_ue_information, (void *)(intptr_t)i);

        // Allocate nr_crgf_metrics
        dataset->nr_crgf_metrics = malloc(sizeof(LTE_Nrcgf_Metrics));
        if (dataset->nr_crgf_metrics == NULL) {
            log_error("Memory allocation failed for nr_crgf_metrics");
            continue;
        }

        dataset->nr_crgf_metrics->precision = rand() % 10; // Varying precision
        dataset->nr_crgf_metrics->resolution = rand() % 100; // Varying resolution

        pthread_mutex_unlock(&mutex);
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_datasets(LTE_Uplink_NRCGF_Dataset *datasets, size_t count) {
    if (!datasets || !count) return;

    for (size_t i = 0; i < count; ++i) {
        LTE_Uplink_NRCGF_Dataset *dataset = &datasets[i];

        free(dataset->nr_crgf_metrics);
        dataset->nr_crgf_metrics = NULL;
        if (dataset->ue_information != NULL) {
            free(dataset->ue_information);
            dataset->ue_information = NULL;
        }
    }

    free(datasets);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    // Further logging mechanisms can be added here.
}

void *fetch_ue_information(void *arg) {
    size_t index = (size_t)(intptr_t)arg;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Simulate fetching ue_information from an external data source
        char *ue_info = malloc(128);
        if (ue_info != NULL) {
            snprintf(ue_info, 128, "UE Information for RNTI %u", index + 1); // Example placeholder

            pthread_mutex_lock(&mutex);
            LTE_Uplink_NRCGF_Dataset *dataset = &datasets[index];
            dataset->ue_information = ue_info;
            pthread_mutex_unlock(&mutex);

            break;  // Success
        }

        retries++;
    }

    if (retries == MAX_RETRIES) {
        log_error("Failed to fetch UE information after maximum retries");
    }

    return NULL;
}
