void dynamic_array_init(DynamicArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->length = 0;
    array->dataset = malloc(sizeof(LTE_Uplink_NRCGF_Dataset) * initial_capacity);
    if (!array->dataset) {
        perror("Failed to allocate memory for LTE_Uplink_NRCGF_Datasets");
        exit(EXIT_FAILURE);
    }
    threading.Lock_Init(&array->lock);
}

void dynamic_array_free(DynamicArray *array) {
    free(array->dataset);
    array->dataset = NULL;
    array->capacity = 0;
    array->length = 0;
}

int dynamic_array_add(DynamicArray *array, LTE_Uplink_NRCGF_Dataset dataset) {
    threading.Lock_Acquire(&array->lock);

    if (array->length == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uplink_NRCGF_Dataset* new_dataset =
            realloc(array->dataset, sizeof(LTE_Uplink_NRCGF_Dataset) * new_capacity);

        if (!new_dataset) {
            perror("Failed to reallocate memory for DynamicArray");
            threading.Lock_Release(&array->lock);
            return -1;
        }
        array->dataset = new_dataset;
        array->capacity = new_capacity;
    }

    array->dataset[array->length++] = dataset;

    threading.Lock_Release(&array->lock);
    return 0; // Success
}

