#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define constants for maximum packet size and linked list node count.
#define MAX_PACKET_SIZE 65535
#define MAX_PAYLOAD_SIZE (MAX_PACKET_SIZE - sizeof(PacketHeader))
#define LIST_NODE_COUNT 10

typedef struct {
    unsigned char version : 4;
    unsigned char ihl : 4; // Header length in 32-bit words
    unsigned char tos;     // Type of service
    uint16_t total_length;
    uint16_t identification;
    unsigned char flags : 3;
    unsigned char frag_offset : 13;
    unsigned char ttl;      // Time to live
    unsigned char protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dest_ip;
    uint16_t src_port;
    uint16_t dest_port;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    char *payload;
    size_t payload_size;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* init_packet_list() {
    pthread_mutex_lock(&list_mutex);

    Node* head = NULL;
    for (int i = 0; i < LIST_NODE_COUNT; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            // Handle memory allocation failure
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp->payload);
                free(temp);
            }
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        node->header.version = 4;           // IPv4
        node->header.ihl = 5;               // Header length of 20 bytes (5x32 bits)
        node->header.tos = 0;
        node->header.total_length = sizeof(PacketHeader) + MAX_PAYLOAD_SIZE;
        node->header.identification = i;    // Unique ID for each packet
        node->header.flags = 0;
        node->header.frag_offset = 0;
        node->header.ttl = 64;              // Standard TTL value
        node->header.protocol = 6;          // TCP protocol (can be changed)
        node->header.checksum = 0;          // Placeholder, needs proper calculation

        // Example IP addresses and ports
        node->header.src_ip = inet_addr("192.168.1.2");
        node->header.dest_ip = inet_addr("192.168.1.3");
        node->header.src_port = htons(12345);
        node->header.dest_port = htons(80);

        node->payload_size = MAX_PAYLOAD_SIZE;
        node->payload = malloc(node->payload_size);
        if (!node->payload) {
            // Handle memory allocation failure
            free(node);
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp->payload);
                free(temp);
            }
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        memset(node->payload, 0xAB, node->payload_size); // Populate payload with dummy data
        node->next = head;    // Insert at the beginning of the list
        head = node;
    }

    pthread_mutex_unlock(&list_mutex);

    return head;
}

void free_packet_list(Node* head) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current->payload);
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list_mutex);
}
```

In this code, we define a `PacketHeader` structure representing an IP packet header. The `Node` structure contains the header and its payload data, along with pointers to create a linked list. We initialize the linked list of these nodes in `init_packet_list`, considering potential memory allocation failures and ensuring thread safety using a mutex. Each node is populated with example values for demonstration purposes. Lastly, we provide a function `free_packet_list` to safely deallocate the resources associated with the list.']

