void perform_logging(const char *event, size_t allocation_size, size_t current_count) {
    if (!log_file) return;

    time_t now;
    time(&now);
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%s - %s | Size: %zu bytes | Count: %zu\n", 
             ctime(&now), event, allocation_size, current_count);

    fwrite(buffer, 1, strlen(buffer), log_file);
    total_log_size += strlen(buffer);

    if (total_log_size >= MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = NULL;
    }
}

