    if (!structures) {
        error_callback("Memory allocation failed");
        return NULL;
    }

    size_t current_max_allocated = initial_size;
    perform_logging("Allocation", initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), initial_size);

    // Simulate memory growth strategy
    while (current_max_allocated < get_available_resources() / 2) {
        size_t new_size = current_max_allocated + initial_size; // Doubling the allocation

        NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(structures, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structures) {
            free(structures);
            error_callback("Memory reallocation failed");
            return NULL;
        }

        structures = new_structures;
        current_max_allocated = new_size;

        perform_logging("Reallocation", new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size);

        if (current_max_allocated > *max_ever_allocated) {
            *max_ever_allocated = current_max_allocated;
        }
    }

    // Reset max ever allocated if below 50% of resources
