#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEMENTS 1000 // Default maximum elements; adjust as needed

typedef struct {
    int id;
    char data[256]; // Example fields, modify as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t mutex;
    pthread_spinlock_t spin_lock; // For minimizing contention
} CRCListManager;

CRCListManager* crc_list_manager_init(size_t max_elements) {
    if (max_elements > MAX_ELEMENTS) return NULL;

    CRCListManager *manager = malloc(sizeof(CRCListManager));
    if (!manager) return NULL;

    memset(manager->elements, 0, sizeof(manager->elements));
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_spin_init(&manager->spin_lock, PTHREAD_PROCESS_PRIVATE);

    return manager;
}

void crc_list_manager_destroy(CRCListManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->elements[i]);
    }

    pthread_mutex_destroy(&manager->mutex);
    pthread_spin_destroy(&manager->spin_lock);
    free(manager);
}

int crc_list_manager_add(CRCListManager *manager, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!manager || manager->count >= MAX_ELEMENTS) return -1;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_spin_lock(&manager->spin_lock);
        if (!manager->elements[i]) {
            manager->elements[i] = element;
            manager->count++;
            pthread_spin_unlock(&manager->spin_lock);
            break;
        }
        pthread_spin_unlock(&manager->spin_lock);
    }

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void crc_list_manager_clear(CRCListManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->elements[i]);
        manager->elements[i] = NULL;
    }
    manager->count = 0;

    pthread_mutex_unlock(&manager->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* crc_list_manager_iterate(CRCListManager *manager, size_t index) {
    if (!manager || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->mutex);

    NFAPI_CRC_INDICATION_PDU_T *element = manager->elements[index];

    pthread_mutex_unlock(&manager->mutex);

    return element;
}

void evaluate_data_structure_impact() {
    // Documented evaluation of data structure impact on performance

    /*
     * 1. Arrays:
     *    - Pros: Good cache locality, fast iteration.
     *    - Cons: Fixed size limits flexibility; resizing is costly.
     *
     * 2. Linked Lists:
     *    - Pros: Dynamic sizing, less memory waste for varying sizes.
     *    - Cons: Poor cache locality, higher overhead per element.
     *
     * Choice justification:
     * - The array-based approach was selected for its balance between cache efficiency
     *   and performance under concurrent access due to minimal pointer chasing compared
     *   to linked lists. Spinlocks and mutexes are used strategically to minimize contention.
     */
}
