void clear_nfa_crc_indication_array_after_timeout(NFAPI_CRC_INDICATION_Array *array, time_t timeout) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if ((current_time - array->pdus[i].pdu_id) > timeout) { // Assuming pdu_id is a timestamp
            memmove(&array->pdus[i], &array->pdus[i + 1],
                    (array->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->size;
            --i; // Recheck the same index after moving elements
        }
    }
    pthread_mutex_unlock(&array->lock);
}

