CacheEntry* tokenCache = NULL;

void generateNfadPduList(size_t count, NFAPI_CRC_INDICATION_PDU_T** pduList, ConfigParams config) {
    *pduList = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduList) {
        logMessage("Memory allocation failed");
        return;
    }

    pthread_t threads[count];
    for (size_t i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, fetchDataFromExternalSource, &((*pduList)[i]));
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

static void* fetchDataFromExternalSource(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;

    // Simulate fetching user information based on RNTI
    char userId[64];
    snprintf(userId, sizeof(userId), "user_%u", pdu->ueInfo.rnti);

    // Authentication and caching
    char accessToken[256];
    time_t expiryTime;
    if (authenticateUser(userId, accessToken, sizeof(accessToken), &expiryTime)) {
        cacheAccessToken(userId, accessToken, expiryTime);
    }

    // Retrieve data with retry mechanism
    int attempt = 0;
    while (++attempt) {
        handleNetworkFailure(attempt - 1);

        // Simulate network call to fetch user information
        // If successful:
        break;

        // On failure, log and continue retrying
        if (attempt > config.retryDelay / 1000) {
            snprintf(accessToken, sizeof(accessToken), "default_access_token");
            expiryTime = time(NULL) + 3600; // 1 hour validity
            cacheAccessToken(userId, accessToken, expiryTime);
            break;
        }
    }

    // Populate the PDU structure with fetched data
    pdu->ueInfo.rxUeInformationTag[0] = '\0';
    snprintf(pdu->ueInfo.rxUeInformationTag, sizeof(pdu->ueInfo.rxUeInformationTag), "FetchedDataForRNTI_%u", pdu->ueInfo.rnti);
    pdu->crcIndication.crcFlag = rand() % 2; // Randomly set CRC flag

    return NULL;
}

static int authenticateUser(const char* userId, char* accessToken, size_t tokenSize, time_t* expiryTime) {
    // Placeholder for authentication logic
    snprintf(accessToken, tokenSize, "access_token_for_%s", userId);
    *expiryTime = time(NULL) + 3600; // Token valid for 1 hour
    return 1;
}

static void cacheAccessToken(const char* userId, const char* accessToken, time_t expiryTime) {
    pthread_mutex_lock(&cacheMutex);

    CacheEntry* entry = tokenCache;
    while (entry) {
        if (strcmp(entry->accessToken, accessToken) == 0 && entry->expiryTime > time(NULL)) {
            // Token already cached and valid
            pthread_mutex_unlock(&cacheMutex);
            return;
        }
        entry = entry->next;
    }

    // Add new cache entry
    CacheEntry* newEntry = malloc(sizeof(CacheEntry));
    if (newEntry) {
        strncpy(newEntry->accessToken, accessToken, sizeof(newEntry->accessToken));
        newEntry->expiryTime = expiryTime;
        newEntry->next = tokenCache;
        tokenCache = newEntry;
    }

    pthread_mutex_unlock(&cacheMutex);
}

static char* getCachedAccessToken(const char* userId) {
    pthread_mutex_lock(&cacheMutex);

    CacheEntry* entry = tokenCache;
    while (entry) {
        if (strcmp(entry->accessToken, "access_token_for_%s", userId) == 0 && entry->expiryTime > time(NULL)) {
            pthread_mutex_unlock(&cacheMutex);
            return strdup(entry->accessToken);
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cacheMutex);
    return NULL;
}

static void logMessage(const char* message) {
    // Placeholder for logging implementation
    printf("%s\n", message);
}

static void handleNetworkFailure(int attempt) {
    if (attempt > 0) {
        int delay = 1 << attempt; // Exponential backoff
        logMessage("Network failure, retrying in ");
        logMessage(delay > 1000 ? "greater than 1 second" : "less than 1 second");
        sleep(delay / 1000);
    }
}

// Main function for testing
int main() {
    ConfigParams config = {5000, 5000, 3000, 10};
    NFAPI_CRC_INDICATION_PDU_T* pduList;
    generateNfadPduList(5, &pduList, config);

    // Cleanup
    free(pduList);
    return 0;
}
