// Define structures
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} UE_INFORMATION;

typedef struct {
    unsigned char CRCFLAG;
    // Other fields can be added here as necessary
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFORMATION ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_LIST;

// Function prototypes
void init_list(NFAPI_LIST *list, size_t initial_capacity);
void destroy_list(NFAPI_LIST *list);
int add_pdu(NFAPI_LIST *list, const NFAPI_CRC_INDICATION_PDU_T *pdu);
int update_pdu(NFAPI_LIST *list, unsigned int rnti, const NFAPI_CRC_INDICATION_PDU_T *pdu);
size_t get_list_size(const NFAPI_LIST *list);
void consistency_check_thread(void *arg);
void *consistency_check(void *arg);
void export_data_to_file(const char *filename, const NFAPI_LIST *list);
int import_data_from_file(const char *filename, NFAPI_LIST *list);
void log_modification(const char *message);
void *logging_thread(void *arg);

// Initialize the list
void init_list(NFAPI_LIST *list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
}

// Destroy the list
void destroy_list(NFAPI_LIST *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Add a new PDU to the list
int add_pdu(NFAPI_LIST *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = *pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Update an existing PDU in the list by RNTI
int update_pdu(NFAPI_LIST *list, unsigned int rnti, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].ue_info.RNTI == rnti) {
            list->data[i] = *pdu;
            log_modification("Updated PDU");
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

// Get the current size of the list
size_t get_list_size(const NFAPI_LIST *list) {
    pthread_mutex_lock((pthread_mutex_t *)&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);
    return size;
}

// Consistency check thread function
void *consistency_check(void *arg) {
    NFAPI_LIST *list = (NFAPI_LIST *)arg;

    while (1) {
        sleep(10); // Check every 10 seconds

        pthread_mutex_lock(&list->lock);
        for (size_t i = 0; i < list->size; ++i) {
            if (!validate_pdu(list->data[i])) {
                log_modification("Inconsistency found");
                // Handle inconsistency
            }
        }
        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

// Export data to a file
void export_data_to_file(const char *filename, const NFAPI_LIST *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t *)&list->lock);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    pthread_mutex_unlock((pthread_mutex_t *)&list->lock);

    fclose(file);
}

// Import data from a file
int import_data_from_file(const char *filename, NFAPI_LIST *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fseek(file, 0, SEEK_END);
    new_size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    pthread_mutex_lock(&list->lock);
    list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    list->size = new_size;
    list->capacity = new_size;
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Log modifications
void log_modification(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock((pthread_mutex_t *)&log_lock);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    pthread_mutex_unlock((pthread_mutex_t *)&log_lock);
}

// Logging thread function
void *logging_thread(void *arg) {
    while (1) {
        sleep(5); // Flush logs every 5 seconds
        fflush(log_file);
    }
    return NULL;
}

// Main function to demonstrate usage
int main() {
    NFAPI_LIST list;
    init_list(&list, 10);

    pthread_t check_thread, log_thread;

    pthread_create(&check_thread, NULL, consistency_check, &list);
    pthread_create(&log_thread, NULL, logging_thread, NULL);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {{.RX_UE_INFORMATION_TAG = 1, .RNTI = 123}, {.CRCFLAG = rand() % 2}};
    add_pdu(&list, &pdu);

