void stop_service();

// Helper functions
static void generate_crc_indications(LTE_UE_Context* context) {
    srand(time(NULL));
    for (size_t i = 0; i < context->frame_count; ++i) {
        context->crc_indications[i].RX_UE_INFORMATION_TAG = rand();
        context->crc_indications[i].RNTI = rand() % 10000;
        context->crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        context->crc_indications[i].CRCFLAG = rand() % 2;
    }
}

void init_ue_context_manager(UEContextManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->total_frames = 0;
}

void destroy_ue_context_manager(UEContextManager* manager) {
    UEContextNode* current = manager->head;
    while (current != NULL) {
        UEContextNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
}

int insert_ue_context(UEContextManager* manager, LTE_UE_Context context) {
    if (context.frame_count == 0 || context.frame_count > MAX_FRAMES) {
        return -1; // Invalid frame count
    }

    generate_crc_indications(&context);

    pthread_mutex_lock(&manager->lock);
    UEContextNode* new_node = (UEContextNode*)malloc(sizeof(UEContextNode));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    new_node->ue_context = context;
    new_node->next = manager->head;
    manager->head = new_node;

    manager->total_frames += context.frame_count;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int delete_ue_context(UEContextManager* manager, int cell_ID) {
    pthread_mutex_lock(&manager->lock);
    UEContextNode *current = manager->head, *prev = NULL;

    while (current != NULL && current->ue_context.cell_ID != cell_ID) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Not found
    }

    manager->total_frames -= current->ue_context.frame_count;

    if (prev == NULL) {
        manager->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

LTE_UE_Context* retrieve_ue_context(UEContextManager* manager, int cell_ID) {
    pthread_mutex_lock(&manager->lock);
    UEContextNode* current = manager->head;

    while (current != NULL) {
        if (current->ue_context.cell_ID == cell_ID) {
            pthread_mutex_unlock(&manager->lock);
            return &current->ue_context;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

void reset_total_frames(UEContextManager* manager) {
    pthread_mutex_lock(&manager->lock);
    manager->total_frames = 0;
    pthread_mutex_unlock(&manager->lock);
}

// Simulated service functions
