int generateRandomCRCFlag() {
    return rand() % 2; // Assuming CRCFLAG is binary for simplicity
}

// Function to create a new node
Node* createNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data.crc_tag_rel8.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.crc_tag_rel8.RNTI = RNTI;
    newNode->data.crc_tag_rel8.CRCFLAG = generateRandomCRCFlag();
    newNode->next = NULL;
    return newNode;
}

// Function to check for unique RNTIs
int isUniqueRNTI(LinkedList* list, int RNTI) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.crc_tag_rel8.RNTI == RNTI)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

// Function to add a node with unique RNTI
void addNode(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (!isUniqueRNTI(list, RNTI)) return;

    Node* newNode = createNode(RX_UE_INFORMATION_TAG, RNTI);
    if (newNode) {
        newNode->next = list->head;
        list->head = newNode;
        list->size++;
    }
}

// Function to verify CRC flags against precomputed checksums
void verifyCRCFlags(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        int expectedChecksum = 0; // Replace with actual precomputed value logic
        if (expectedChecksum != current->data.crc_tag_rel8.CRCFLAG) {
            fprintf(stderr, "Error: CRC checksum mismatch for RNTI %d\n", 
                    current->data.crc_tag_rel8.RNTI);
            // Handle corrupted entry gracefully
            Node* toDelete = current;
            current = current->next;
            free(toDelete);
            list->size--;
        } else {
            current = current->next;
        }
    }
}

// Function to serialize the linked list to disk
void serializeList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize the linked list from disk
void deserializeList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        addNode(list, data.crc_tag_rel8.RX_UE_INFORMATION_TAG, data.crc_tag_rel8.RNTI);
    }

    fclose(file);
}

// Function to free the linked list
void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
    list->head = NULL;
    list->size = 0;
}

int main() {
    LinkedList list = {NULL, 0};

    // Add nodes to the linked list
    addNode(&list, 1, 100);
    addNode(&list, 2, 200);

    // Verify CRC flags and handle any errors
    verifyCRCFlags(&list);

    // Serialize the list to disk
    serializeList(&list, "linked_list.dat");

    // Clear the current list and deserialize it from disk
    freeList(&list);
    deserializeList(&list, "linked_list.dat");

    // Free the linked list after use
    freeList(&list);

    return 0;
}
