```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAMES 100

typedef struct {
    int frequencyBand;
    int cellID;
} UEContext;

typedef struct {
    int rnti;
    int rxUEInfoTag;
    int crcFlag; // Randomly set
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
} LTE_DL_FRAME;

typedef struct {
    UEContext ueContext;
    LTE_DL_FRAME frames[MAX_FRAMES];
    int frameCount;
} NFAPI_CRC_INDICATION_PDU_T;

// External data source simulation
typedef struct {
    int* availableCellIDs;
    size_t cellIDCount;
    int* frequencyBands;
    size_t bandCount;
} DataSource;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
UEContext* ueArray = NULL;
size_t ueSize = 0;
size_t capacity = 0;
long totalFrames = 0;

void initDataSource(DataSource* ds) {
    // Simulated initialization
    ds->availableCellIDs = (int[]) {1, 2, 3};
    ds->cellIDCount = sizeof(ds->availableCellIDs) / sizeof(int);
    ds->frequencyBands = (int[]) {700, 800, 1800};
    ds->bandCount = sizeof(ds->frequencyBands) / sizeof(int);
}

void updateUEContexts(DataSource* ds) {
    pthread_mutex_lock(&lock);

    // Update logic: remove outdated contexts
    for(size_t i = 0; i < ueSize; ++i) {
        int found = 0;
        for(size_t j = 0; j < ds->cellIDCount; ++j) {
            if(ueArray[i].cellID == ds->availableCellIDs[j]) {
                found = 1;
                break;
            }
        }
        if(!found) {
            // Remove this UE context
            memmove(&ueArray[i], &ueArray[i + 1], (ueSize - i - 1) * sizeof(UEContext));
            ueSize--;
            totalFrames -= ueArray[i].frames[0].frameCount;
            --i; // Adjust index after removal
        }
    }

    pthread_mutex_unlock(&lock);
}

int addUEContext(int cellID, int frequencyBand) {
    pthread_mutex_lock(&lock);

    if(ueSize >= capacity) {
        size_t newCapacity = (capacity == 0 ? 1 : capacity * 2);
        UEContext* newArray = realloc(ueArray, newCapacity * sizeof(UEContext));
        if(!newArray) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
        ueArray = newArray;
        capacity = newCapacity;
    }

    for(size_t i = 0; i < ueSize; ++i) {
        if(ueArray[i].cellID == cellID)
            goto done; // Cell ID already exists
    }

    UEContext* context = &ueArray[ueSize++];
    context->cellID = cellID;
    context->frequencyBand = frequencyBand;

    for(int i = 0; i < MAX_FRAMES; ++i) {
        LTE_DL_FRAME* frame = &context->frames[i];
        frame->tag.crcFlag = rand() % 2; // Random CRC flag
        if(frame->tag.crcFlag == 1)
            break;
    }

    totalFrames += context->frameCount;

done:
    pthread_mutex_unlock(&lock);
    return 0;
}

void deleteUEContext(int cellID) {
    pthread_mutex_lock(&lock);

    for(size_t i = 0; i < ueSize; ++i) {
        if(ueArray[i].cellID == cellID) {
            memmove(&ueArray[i], &ueArray[i + 1], (ueSize - i - 1) * sizeof(UEContext));
            totalFrames -= ueArray[i].frames[0].frameCount;
            --ueSize;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void resetFrameCount() {
    pthread_mutex_lock(&lock);

    totalFrames = 0;
    for(size_t i = 0; i < ueSize; ++i) {
        UEContext* context = &ueArray[i];
        for(int j = 0; j < MAX_FRAMES && context->frames[j].tag.crcFlag == 1; ++j);
        context->frameCount = j;
        totalFrames += j;
    }

    pthread_mutex_unlock(&lock);
}

void simulatedService() {
    while(1) {
        sleep(rand() % 5 + 1); // Random interval

        pthread_mutex_lock(&lock);

        // Simulate a stop message
        printf("Simulated service stopped.\n");

        pthread_mutex_unlock(&lock);

        break;
    }
}

int main() {
    srand(time(NULL));

    initDataSource(NULL);

    addUEContext(1, 700); // Example UE context addition

    simulatedService();

    resetFrameCount();

    deleteUEContext(1);

    free(ueArray);
    ueSize = capacity = 0;

    return 0;
}
