    // Frame data
} LTE_DL_FRAME;

typedef struct LTE_UE_CONTEXT {
    int cell_id;
    int frequency_band;
    LTE_DL_FRAME *frames[MAX_FRAMES];
    size_t frame_count;
    pthread_mutex_t mutex;
} LTE_UE_CONTEXT;

typedef struct UE_Context_List {
    LTE_UE_CONTEXT *contexts;
    size_t count;
    size_t capacity;
    size_t total_frames;
    pthread_mutex_t list_mutex;
} UE_Context_List;

// Global variables
ExternalData external_data_source;
pthread_mutex_t data_source_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t data_updated = PTHREAD_COND_INITIALIZER;
int data_needs_update = 1;

UE_Context_List *create_ue_context_list(size_t initial_capacity) {
    UE_Context_List *list = malloc(sizeof(UE_Context_List));
    if (!list) return NULL;

    list->contexts = malloc(initial_capacity * sizeof(LTE_UE_CONTEXT));
    if (!list->contexts) {
        free(list);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&list->contexts[i].mutex, NULL);
    }

    list->count = 0;
    list->capacity = initial_capacity;
    list->total_frames = 0;

    pthread_mutex_init(&list->list_mutex, NULL);

    return list;
}

void free_ue_context_list(UE_Context_List *list) {
    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_destroy(&list->contexts[i].mutex);
        for (size_t j = 0; j < list->contexts[i].frame_count; ++j) {
            free(list->contexts[i].frames[j]);
        }
    }

    free(list->contexts);
    pthread_mutex_destroy(&list->list_mutex);
    free(list);
}

void update_external_data() {
    while (1) {
        // Simulate fetching new data
        pthread_mutex_lock(&data_source_mutex);
        external_data_source.frequency_band = rand() % 100;
        external_data_source.cell_id = rand() % 1000;
        data_needs_update = 0;
        pthread_cond_signal(&data_updated);
        pthread_mutex_unlock(&data_source_mutex);

        sleep(CACHE_UPDATE_INTERVAL);
    }
}

void *ue_context_manager(void *arg) {
    UE_Context_List *list = (UE_Context_List *)arg;

    while (1) {
        // Wait for external data update
        pthread_mutex_lock(&data_source_mutex);
        while (!data_needs_update) {
            pthread_cond_wait(&data_updated, &data_source_mutex);
        }
        pthread_mutex_unlock(&data_source_mutex);

        pthread_mutex_lock(&list->list_mutex);

        // Check and reconcile UE contexts with updated external data
        for (size_t i = 0; i < list->count; ++i) {
            pthread_mutex_lock(&list->contexts[i].mutex);
            if (list->contexts[i].frequency_band != external_data_source.frequency_band ||
                list->contexts[i].cell_id != external_data_source.cell_id) {
                // Handle discrepancies, e.g., remove or update context
            }
            pthread_mutex_unlock(&list->contexts[i].mutex);
        }

        pthread_mutex_unlock(&list->list_mutex);

        sleep(1);  // Simulate periodic checks
    }
}

int main() {
    srand(time(NULL));

    UE_Context_List *context_list = create_ue_context_list(10);
    if (!context_list) {
        fprintf(stderr, "Failed to initialize UE context list\n");
        return EXIT_FAILURE;
    }

    pthread_t data_thread, manager_thread;

    // Start external data update thread
    pthread_create(&data_thread, NULL, (void *)update_external_data, NULL);

    // Start UE context management thread
    pthread_create(&manager_thread, NULL, ue_context_manager, context_list);

    // Join threads (in practice, you'd have a mechanism to gracefully stop these)
    pthread_join(data_thread, NULL);
    pthread_join(manager_thread, NULL);

    free_ue_context_list(context_list);

    return EXIT_SUCCESS;
}
