#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 5 * 1024 * 1024 // 5 MB
#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t current_size;
} LinkedList;

void log_event(const char *message) {
    // Placeholder for external logging system integration
    printf("%s\n", message);
}

LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_event("Memory allocation failed for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->current_size = 0;
    return list;
}

int insert_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || list->current_size >= MAX_ELEMENTS) {
        log_event("Insertion failed: List is full or invalid");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == element.RNTI) {
            char warning_msg[256];
            snprintf(warning_msg, sizeof(warning_msg), "Duplicate RNTI %u detected. Skipping insertion.", element.RNTI);
            log_event(warning_msg);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&new_node->data, &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Inserted element with RNTI %u", element.RNTI);
    log_event(log_msg);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(LinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!element) return;

    srand(time(NULL));
    element->CRCFLAG = rand() % 256;
}

// Usage example
int main() {
    LinkedList* list = init_list();
    if (!list) return -1;

    for (unsigned int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() % 1024, .CRC_INDICATION_REL8_TAG = rand() % 256 };
        generate_random_crcflag(&element);
        insert_element(list, element);
    }

    free_list(list);
    return 0;
}
