NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_pdu_array(int n, int max_retries) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int attempts = 0;

    while (attempts < max_retries) {
        array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
