typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 1023

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int validate_rnti(uint16_t rnti) {
    return (rnti <= MAX_RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_pdu_array(size_t N, size_t *count) {
    if (N == 0 || count == NULL) {
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t allocated_size = N;

    array = malloc(allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        fprintf(stderr, "Initial memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        // Simulating external RNTI validation
        uint16_t rnti = rand() % (MAX_RNTI + 1);

        if (!validate_rnti(rnti)) {
            free(array);
            array = NULL;
            fprintf(stderr, "RNTI validation failed.\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Populate the structure
        array[i].RX_UE_INFORMATION_TAG = (void*)(uintptr_t)rnti;  // Example tag assignment
        array[i].tag.CRCFLAG = rand() % 2;

        if (++*count < allocated_size) continue;

        // If realloc needed, double the allocation size and try again
        allocated_size *= 2;
        NFAPI_CRC_INDICATION_PDU_T *temp_array = realloc(array, allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp_array) {
            free(array);
            fprintf(stderr, "Memory reallocation failed.\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        array = temp_array;
    }

    // Trim the allocation to fit the exact number of filled elements
    NFAPI_CRC_INDICATION_PDU_T *trimmed_array = realloc(array, (*count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (trimmed_array) {
        array = trimmed_array;
    } else {
        fprintf(stderr, "Trimming reallocation failed.\n");
        free(array);
        array = NULL;
    }

    pthread_mutex_unlock(&lock);

    return array;
}

void free_nfaapi_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
