#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Assuming definitions for NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, etc.
typedef struct {
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG RX_UE_INFO_TAG;
    CRC_INDICATION_REL8_TAG* REL8TAGS;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and manage a dynamically allocated array
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int tag_count = 0;

    while (tag_count < N) {
        int rnti = rand() % 10000; // Example RNTI generation
        RX_UE_INFORMATION_TAG rx_tag = { .RNTI = rnti }; // Assuming structure definition for RX_UE_INFORMATION_TAG

        // Check if this tag is unique
        int is_unique = 1;
        for (int i = 0; i < tag_count; ++i) {
            if (array[i].RX_UE_INFO_TAG.RNTI == rx_tag.RNTI) {
                is_unique = 0;
                break;
            }
        }

        if (!is_unique) continue;

        // Allocate memory for REL8TAGS and set CRCFLAG randomly
        array[tag_count].REL8TAGS = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!array[tag_count].REL8TAGS) {
            fprintf(stderr, "Memory allocation failed for REL8TAGS\n");
            // Handle partial failure: Free previously allocated memory
            for (int i = 0; i < tag_count; ++i) {
                free(array[i].REL8TAGS);
            }
            free(array);
            return NULL;
        }

        array[tag_count].RX_UE_INFO_TAG = rx_tag;
        array[tag_count].REL8TAGS->RNTI = rnti;
        array[tag_count].REL8TAGS->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        tag_count++;
    }

    return array;
}

// Function to free the allocated memory
void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (!array) return;

    for (int i = 0; i < N; ++i) {
        if (array[i].REL8TAGS) {
            free(array[i].REL8TAGS);
        }
