extern void log_error(const char* error_message);

typedef struct {
    atomic_size_t count;
    atomic_size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    pthread_mutex_t mutex; // For protecting dynamic resizing
} PduList;

// Function prototypes
void initialize_pdu_list(PduList *list, size_t initial_capacity);
int add_pdu_to_list(PduList *list, const NFAPI_CRC_INDICATION_PDU_T *pdu);
char* serialize_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu);
int resize_pdu_list(PduList *list);
void destroy_pdu_list(PduList *list);

// Function implementations
void initialize_pdu_list(PduList *list, size_t initial_capacity) {
    list->count = 0;
    list->capacity = initial_capacity;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity *
                                                      sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        log_error("Failed to allocate memory for PDU list");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->mutex, NULL);
}

int add_pdu_to_list(PduList *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    size_t new_count = atomic_load_explicit(&list->count, memory_order_acquire);
    if (new_count >= list->capacity) {
        if (!resize_pdu_list(list)) return -1;
    }

    pthread_mutex_lock(&list->mutex);
    list->pdus[atomic_fetch_add_explicit(&list->count, 1, memory_order_release)] = *pdu;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

char* serialize_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    static char buffer[128];
    snprintf(buffer, sizeof(buffer), "RNTI: %u, CRC Value: %u", pdu->rnti, pdu->crc_indication_rel8_tag.crc_value);
    return buffer;
}

int resize_pdu_list(PduList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, 
                                                                                  new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        log_error("Failed to reallocate memory for PDU list");
        return 0;
    }

    pthread_mutex_lock(&list->mutex);
    list->pdus = new_pdus;
    atomic_store_explicit(&list->capacity, new_capacity, memory_order_release);
    pthread_mutex_unlock(&list->mutex);

    return 1;
}

void destroy_pdu_list(PduList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
}
```

