    METADATA metadata;
} NFAPI_RX_FRAME;

// Define the dynamic collection structure
typedef struct {
    NFAPI_RX_FRAME** frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;  // For read-write access management
} FRAME_COLLECTION;

#define INITIAL_CAPACITY 10

// Function declarations
FRAME_COLLECTION* create_frame_collection();
void destroy_frame_collection(FRAME_COLLECTION* collection);
int add_frame(FRAME_COLLECTION* collection, NFAPI_RX_FRAME* frame);
NFAPI_RX_FRAME* get_frame_by_sequence_number(FRAME_COLLECTION* collection, uint16_t sequence_number);
void resize_frame_collection(FRAME_COLLECTION* collection);

// Create a new FRAME_COLLECTION
FRAME_COLLECTION* create_frame_collection() {
    FRAME_COLLECTION* collection = (FRAME_COLLECTION*)malloc(sizeof(FRAME_COLLECTION));
    if (!collection) return NULL;

    collection->frames = (NFAPI_RX_FRAME**)calloc(INITIAL_CAPACITY, sizeof(NFAPI_RX_FRAME*));
    if (!collection->frames) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    pthread_rwlock_init(&collection->rwlock, NULL);

    return collection;
}

// Destroy an existing FRAME_COLLECTION
void destroy_frame_collection(FRAME_COLLECTION* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->frames[i]->rrc_pdu.pdu_data);
        free(collection->frames[i]);
    }
    free(collection->frames);

    pthread_mutex_destroy(&collection->lock);
    pthread_rwlock_destroy(&collection->rwlock);
    free(collection);
}

// Add a frame to the collection
int add_frame(FRAME_COLLECTION* collection, NFAPI_RX_FRAME* frame) {
    if (!collection || !frame) return -1;

    pthread_rwlock_wrlock(&collection->rwlock);

    // Resize if necessary
    if (collection->count >= collection->capacity) {
        resize_frame_collection(collection);
    }

    // Add the frame to the next available position
    size_t index = 0;
    for (; index < collection->count; ++index) {
        if (collection->frames[index]->metadata.RRC_SEQUENCE_NUMBER == frame->metadata.RRC_SEQUENCE_NUMBER) {
            pthread_rwlock_unlock(&collection->rwlock);
            return -1; // Duplicate sequence number, do not add
        }
    }

    collection->frames[collection->count++] = frame;

    pthread_rwlock_unlock(&collection->rwlock);
    return 0;
}

// Retrieve a frame by its sequence number
NFAPI_RX_FRAME* get_frame_by_sequence_number(FRAME_COLLECTION* collection, uint16_t sequence_number) {
    if (!collection) return NULL;

    pthread_rwlock_rdlock(&collection->rwlock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->frames[i]->metadata.RRC_SEQUENCE_NUMBER == sequence_number) {
            NFAPI_RX_FRAME* frame = collection->frames[i];
            pthread_rwlock_unlock(&collection->rwlock);
            return frame;
        }
    }

    pthread_rwlock_unlock(&collection->rwlock);
    return NULL; // Frame not found
}

// Resize the FRAME_COLLECTION if necessary
void resize_frame_collection(FRAME_COLLECTION* collection) {
    size_t new_capacity = collection->capacity * 2;

    NFAPI_RX_FRAME** new_frames = (NFAPI_RX_FRAME**)realloc(collection->frames, new_capacity * sizeof(NFAPI_RX_FRAME*));
    if (!new_frames) return; // Memory allocation failed

    collection->frames = new_frames;
    collection->capacity = new_capacity;
}
```

### Key Points:
