typedef struct {
    Message *messages;
    size_t capacity;
    size_t count;
} MessageArray;

// Function prototypes
void initMessageArray(MessageArray *array, size_t initialCapacity);
int addOrUpdateMessage(MessageArray *array, int message_id, time_t timestamp, size_t payload_length);
Message* getMessageById(MessageArray *array, int message_id);
void logChange(const char *action, int message_id);

// Initialize the dynamic array with a given capacity.
void initMessageArray(MessageArray *array, size_t initialCapacity) {
    if (!array) return;
    array->messages = (Message *)calloc(initialCapacity, sizeof(Message));
    array->capacity = initialCapacity;
    array->count = 0;

    // Check allocation success
    if (!array->messages) {
        fprintf(stderr, "Failed to allocate memory for messages\n");
        exit(EXIT_FAILURE);
    }
}

// Add a new message or update an existing one by its ID.
int addOrUpdateMessage(MessageArray *array, int message_id, time_t timestamp, size_t payload_length) {
    if (!array || !array->messages) return -1;

    // Check for existing message to update
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].message_id == message_id) {
            array->messages[i].timestamp = timestamp;
            array->messages[i].payload_length = payload_length;

            logChange("Updated", message_id);
            return 0; // Success
        }
    }

    // Check for capacity and resize if necessary
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        Message *newMessages = (Message *)realloc(array->messages, newCapacity * sizeof(Message));

        if (!newMessages) {
            fprintf(stderr, "Failed to reallocate memory for messages\n");
            return -1; // Memory allocation failure
        }

        array->messages = newMessages;
        array->capacity = newCapacity;
    }

    // Add new message
    Message newMessage = {timestamp, message_id, payload_length};
    array->messages[array->count++] = newMessage;

    logChange("Added", message_id);
    return 0; // Success
}

// Retrieve a message by its ID.
Message* getMessageById(MessageArray *array, int message_id) {
    if (!array || !array->messages) return NULL;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].message_id == message_id) {
            return &array->messages[i];
        }
    }

    // Message not found
    return NULL;
}

// Log changes to the external logging service.
