    pthread_mutex_lock(&fc->lock);

    if (frame.metadata.RX_TIMESTAMP == 0 || frame.metadata.RRC_SEQUENCE_NUMBER == 0) {
        pthread_mutex_unlock(&fc->lock);
        return -1; // Invalid metadata
    }

    for (size_t i = 0; i < fc->count; ++i) {
        FrameNode* node = fc->frames[i];
        if (node && 
            node->frame.metadata.RX_TIMESTAMP == frame.metadata.RX_TIMESTAMP &&
            node->frame.metadata.RRC_SEQUENCE_NUMBER == frame.metadata.RRC_SEQUENCE_NUMBER) {
            // Update existing frame
            node->frame = frame;
            pthread_mutex_unlock(&fc->lock);
            return 0;
        }
    }

    if (fc->count >= fc->capacity) {
        resizeFrameCollection(fc);
    }

    FrameNode* newNode = malloc(sizeof(FrameNode));
    if (!newNode) {
        pthread_mutex_unlock(&fc->lock);
        return -1; // Memory allocation failure
    }

    newNode->frame = frame;
    newNode->next = NULL;
    fc->frames[fc->count++] = newNode;

    pthread_mutex_unlock(&fc->lock);
    return 0;
}

