    size_t new_capacity = fc->capacity * 2;
    FrameNode** new_frames = calloc(new_capacity, sizeof(FrameNode*));

    if (!new_frames) {
        // Handle allocation failure
        pthread_mutex_unlock(&fc->lock);
        return;
    }

    memcpy(new_frames, fc->frames, fc->count * sizeof(FrameNode*));
    free(fc->frames);
    fc->frames = new_frames;
    fc->capacity = new_capacity;

    pthread_cond_signal(&fc->cond); // Notify waiting threads about resize
