int add_crc_indication(CRCManager *manager, unsigned int tag, unsigned int rnti) {
    if (!manager || !manager->array) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RX_UE_INFORMATION_TAG == tag) {
            pthread_mutex_unlock(&manager->lock);
            return 0; // Tag already exists
