typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure for efficient memory management
typedef struct MemoryPool {
    size_t element_size;
    void* elements;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* create_pool(size_t element_size, size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->capacity = initial_capacity;
    pool->used = 0;

    pool->elements = malloc(element_size * initial_capacity);
    if (!pool->elements) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* pool_alloc(MemoryPool* pool) {
    if (pool->used >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        void* new_elements = realloc(pool->elements, pool->element_size * new_capacity);
        if (!new_elements) return NULL;

        pool->elements = new_elements;
        pool->capacity = new_capacity;
    }

    void* element = (char*)pool->elements + (pool->used * pool->element_size);
    pool->used++;
    return element;
}

void destroy_pool(MemoryPool* pool) {
    free(pool->elements);
    free(pool);
}

// Function to manage CRC indications
NFAPI_CRC_INDICATION_PDU_T* manageCRCIndications(int N, MemoryPool** pool) {
