        for (int j = 0; j < i; ++j) {
            if (tags[j] == tags[i]) {
                --i;
                break;
            }
        }
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = tags[i];
        indications[i].RNTI = rand() % MAX_RNTI + 1;
        indications[i].CRCFLAG = rand() % 2;
    }

    return (*pool)->elements;
}

// Recursive DOM traversal in JavaScript
function traverseDOM(node, selector, testFn) {
    let result = [];

    function walk(currentNode) {
        if (!currentNode) return;

        if (testFn(currentNode)) {
            if (currentNode.matches(selector)) {
                result.push(currentNode);
            }
        }

        for (let child of currentNode.children) {
            walk(child);
        }
    }

    walk(node);

    return result;
}
