// Define the structures
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int* RX_UE_INFORMATION_POOL;
    size_t pool_size;
    int* RNTI_POOL;
    size_t rnti_pool_size;
} ResourcePool;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to log messages
void log_message(const char *message) {
    printf("%s\n", message);
}

// Validate resource pool integrity
int validate_resource_pool(ResourcePool* pool) {
    if (pool == NULL || pool->RX_UE_INFORMATION_POOL == NULL || pool->RNTI_POOL == NULL ||
        pool->pool_size <= 0 || pool->rnti_pool_size <= 0) {
        log_message("Invalid resource pool");
        return 0;
    }
    return 1;
}

// Function to generate the list of structures
NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCIndications(size_t N, int seed, ResourcePool* pool, size_t max_memory_usage) {
    if (!validate_resource_pool(pool)) return NULL;

    pthread_mutex_lock(&lock);

    srand(seed);
    size_t memory_usage_per_structure = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = N * memory_usage_per_structure;

    if (total_memory_required > max_memory_usage) {
        log_message("Insufficient memory for allocation");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(total_memory_required);
    if (!result) {
        log_message("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int used_rx_tags[pool->pool_size] = {0};
    int used_rntis[pool->rnti_pool_size] = {0};

    size_t true_count = 0;
    for (size_t i = 0; i < N; ++i) {
        int rx_tag_index, rnti_index;
        do {
            rx_tag_index = rand() % pool->pool_size;
        } while (used_rx_tags[rx_tag_index] == 1);

        do {
            rnti_index = rand() % pool->rnti_pool_size;
        } while (used_rntis[rnti_index] == 1);

        used_rx_tags[rx_tag_index] = 1;
        used_rntis[rnti_index] = 1;

        result[i].RX_UE_INFORMATION_TAG = pool->RX_UE_INFORMATION_POOL[rx_tag_index];
        result[i].RNTI = pool->RNTI_POOL[rnti_index];

        // Ensure no more than 50% CRCFLAG set to true
        if (true_count < N / 2 && rand() % 2 == 0) {
            result[i].CRCFLAG = 1;
            ++true_count;
        } else {
            result[i].CRCFLAG = 0;
        }
    }

    // Validation step: Ensure all structures are valid
    for (size_t i = 0; i < N; ++i) {
        if (!used_rx_tags[result[i].RX_UE_INFORMATION_TAG - pool->RX_UE_INFORMATION_POOL[0]] ||
            !used_rntis[result[i].RNTI - pool->RNTI_POOL[0]]) {
            log_message("Validation failed: Duplicate or invalid tags");
            free(result);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    log_message("NFAPI_CRC_INDICATION_PDU_T structures generated successfully");

    pthread_mutex_unlock(&lock);

    return result;
}

// Example of using the function
int main() {
    ResourcePool pool = {
        .RX_UE_INFORMATION_POOL = (int[]){1, 2, 3, 4, 5},
        .pool_size = 5,
        .RNTI_POOL = (int[]){101, 102, 103, 104, 105},
        .rnti_pool_size = 5
    };

    size_t N = 10;
    int seed = 42;
    size_t max_memory_usage = 1024; // Example value

    NFAPI_CRC_INDICATION_PDU_T* structures = generateNFAPICRCIndications(N, seed, &pool, max_memory_usage);
    if (structures) {
        for (size_t i = 0; i < N; ++i) {
            printf("Structure %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
                   i, structures[i].RX_UE_INFORMATION_TAG,
                   structures[i].RNTI, structures[i].CRCFLAG);
        }
        free(structures);
    }

    return 0;
}
