#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1048576 // Example maximum memory usage in bytes
#define INITIAL_SIZE 10          // Initial size for dynamic arrays

typedef struct {
    int PCI;
    int frequency_band;
} PAGING_PARTITION_T;

typedef struct {
    PAGING_PARTITION_T* paging_partitions;
    size_t num_paging_partitions;
} LTE_ENB_SIB1_TDL;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(long** long_array, int** int_keys, LTE_ENB_SIB1_TDL** sib1_array, size_t initial_size) {
    *long_array = malloc(initial_size * sizeof(long));
    if (*long_array == NULL) {
        perror("Failed to allocate memory for long array");
        exit(EXIT_FAILURE);
    }

    *int_keys = malloc(initial_size * sizeof(int));
    if (*int_keys == NULL) {
        perror("Failed to allocate memory for int keys");
        free(*long_array);
        exit(EXIT_FAILURE);
    }

    *sib1_array = calloc(initial_size, sizeof(LTE_ENB_SIB1_TDL));
    if (*sib1_array == NULL) {
        perror("Failed to allocate memory for SIB1 array");
        free(*long_array);
        free(*int_keys);
        exit(EXIT_FAILURE);
    }
}

void resize_sib1_array(LTE_ENB_SIB1_TDL** sib1_array, size_t* current_size) {
    pthread_mutex_lock(&memory_lock);

    size_t new_size = *current_size * 2;
    LTE_ENB_SIB1_TDL* temp = realloc(*sib1_array, new_size * sizeof(LTE_ENB_SIB1_TDL));
    if (temp == NULL) {
        perror("Failed to resize SIB1 array");
        pthread_mutex_unlock(&memory_lock);
        exit(EXIT_FAILURE);
    }

    *sib1_array = temp;
    *current_size = new_size;

    pthread_mutex_unlock(&memory_lock);
}

void populate_sib1_structure(LTE_ENB_SIB1_TDL* sib1, size_t num_partitions) {
    sib1->paging_partitions = malloc(num_partitions * sizeof(PAGING_PARTITION_T));
    if (sib1->paging_partitions == NULL) {
        perror("Failed to allocate memory for paging partitions");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_partitions; ++i) {
        sib1->paging_partitions[i].PCI = rand() % 504;
        sib1->paging_partitions[i].frequency_band = rand() % 100;
    }
    sib1->num_paging_partitions = num_partitions;
}

void manage_lte_enb_sib1_array(size_t initial_size) {
    long* long_array;
    int* int_keys;
    LTE_ENB_SIB1_TDL* sib1_array;
    size_t current_size = initial_size;

    initialize_arrays(&long_array, &int_keys, &sib1_array, initial_size);

    for (size_t i = 0; i < current_size; ++i) {
        if (i * sizeof(LTE_ENB_SIB1_TDL) + current_size * sizeof(PAGING_PARTITION_T) > MAX_MEMORY_USAGE) {
            resize_sib1_array(&sib1_array, &current_size);
        }
        populate_sib1_structure(&sib1_array[i], 5); // Example number of partitions
    }

    printf("Arrays initialized and populated successfully.\n");

    free(long_array);
    free(int_keys);
    for (size_t i = 0; i < current_size; ++i) {
        free(sib1_array[i].paging_partitions);
    }
    free(sib1_array);
}

int main() {
    manage_lte_enb_sib1_array(INITIAL_SIZE);
    return 0;
}
