#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "crc_indication_pdu.h"  // Assume this header defines NFAPI_CRC_INDICATION_PDU_T

// External configuration and memory management stubs
#define MAX_RNTI 65535
extern int get_default_crcflag(void);
extern unsigned short* load_rnti_range(const char *filename, size_t *size);

typedef struct CRCNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CRCNode *next;
} CRCNode;

// Thread-safe linked list management
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_list(CRCNode **head, unsigned int count, unsigned int seed) {
    pthread_mutex_lock(&list_mutex);

    CRCNode *current = NULL;
    for (unsigned int i = 0; i < count; ++i) {
        CRCNode *new_node = malloc(sizeof(CRCNode));
        if (!new_node && !current) {  // Fallback allocation strategy
            fprintf(stderr, "Primary memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        if (new_node) {
            new_node->data.rnti = rand_r(&seed) % MAX_RNTI + 1;
            new_node->data.crcflag = rand_r(&seed) & 0x01; // Random CRCFLAG

            while (current && current->next) {
                if (new_node->data.rnti == current->next->data.rnti) {
                    free(new_node);
                    --i;
                    break;
                }
                current = current->next;
            }

            new_node->next = *head;
            *head = new_node;

        } else {
            // Handle allocation failure for existing nodes
            while (*head) {
                CRCNode *temp = *head;
                *head = (*head)->next;
                free(temp);
            }
            break;  // Exit loop on memory exhaustion
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void iterate_list(CRCNode *head, void (*operation)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list_mutex);

    CRCNode *current = head;
    while (current) {
        operation(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void serialize_list(CRCNode *head, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    CRCNode *current = head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list_mutex);
}

void deserialize_list(CRCNode **head, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T data;
    CRCNode *current = NULL;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        CRCNode *new_node = malloc(sizeof(CRCNode));
        if (!new_node) {  // Handle memory failure during deserialization
            fprintf(stderr, "Memory allocation failed during deserialization.\n");
            while (current) {
                CRCNode *temp = current;
                current = current->next;
                free(temp);
            }
            break;
        }

        new_node->data = data;
        new_node->next = NULL;

        if (!*head) {
            *head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
    }

    fclose(file);
    pthread_mutex_unlock(&list_mutex);
}

void example_operation(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Example operation, e.g., updating a field
    data->crcflag ^= 1; // Toggle the CRCFLAG for demonstration
}
