void log_message(const char *message) {
    static char log_buffer[LOG_BUFFER_SIZE];
    snprintf(log_buffer, LOG_BUFFER_SIZE, "%s", message);
    printf("%s\n", log_buffer);
}

PDU_Array* allocate_pdu_array(size_t N) {
    if (N > MAX_STRUCTURES) {
        log_message("Error: Exceeded maximum allowable structures.");
        return NULL;
    }

    PDU_Array* pdu_array = malloc(sizeof(PDU_Array));
    if (!pdu_array) {
        log_message("Memory allocation failed for PDU_Array struct.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    pdu_array->array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array->array) {
        free(pdu_array);
        log_message("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array.");
        return NULL;
    }
    pthread_mutex_unlock(&mutex);

    pdu_array->num_elements = N;

    for (size_t i = 0; i < N; ++i) {
        pdu_array->array[i].RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG();
        pdu_array->array[i].RNTI = fetch_RNTI();
        pdu_array->array[i].CRCFLAG = rand() & 1;
    }

    log_message("PDU array allocation and initialization successful.");
    return pdu_array;
}

size_t serialize_pdu_array(const PDU_Array* pdu_array, uint8_t** buffer) {
    if (!pdu_array || !buffer) return 0;

    size_t required_size = pdu_array->num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = malloc(required_size);

    if (!(*buffer)) {
        log_message("Buffer allocation failed during serialization.");
        return 0;
    }

    memcpy(*buffer, pdu_array->array, required_size);
    log_message("Serialization successful.");

    return required_size;
}

int deserialize_pdu_array(const uint8_t* buffer, size_t buffer_size, PDU_Array* pdu_array) {
    if (!buffer || !pdu_array) return -1;

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(buffer_size);
    if (!array) {
        log_message("Memory allocation failed during deserialization.");
        return -1;
    }

    memcpy(array, buffer, buffer_size);

    pdu_array->num_elements = buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pdu_array->array = array;

    log_message("Deserialization successful.");

    return 0;
}

void free_pdu_array(PDU_Array* pdu_array) {
    if (pdu_array) {
        free(pdu_array->array);
        free(pdu_array);
        log_message("PDU array memory deallocation successful.");
    }
}
