```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB
#define MAX_INT_SUM 1000000
#define RECORD_COUNT 1000

typedef struct {
    int int_value;
    char *buffer;
} Record;

typedef struct {
    atomic_int64_t int_key;
    Record record;
    pthread_mutex_t lock; // Mutex for each record to ensure thread safety
} ConcurrentRecord;

int weighted_random(int min, int max) {
    static const double alpha = 0.5; // Weighted distribution factor
    double u = ((double)rand() / RAND_MAX);
    int range = max - min + 1;
    int result = (int)(min + pow(u, alpha) * (range - 1));
    return result < min ? min : result > max ? max : result;
}

void initialize_records(ConcurrentRecord **records, size_t record_count, int key_min, int key_max, int value_range) {
    size_t total_int_sum = 0;

    for (size_t i = 0; i < record_count; ++i) {
        ConcurrentRecord *record = &records[i];
        pthread_mutex_init(&record->lock, NULL);

        int random_key = weighted_random(key_min, key_max);
        atomic_store(&record->int_key, random_key);

        // Calculate buffer size and allocate memory
        char *buffer = (char *)malloc(random_key);
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            exit(EXIT_FAILURE);
        }
        record->record.buffer = buffer;

        int random_value;
        do {
            random_value = weighted_random(1, value_range);
        } while (total_int_sum + random_value > MAX_INT_SUM);

        total_int_sum += random_value;
        record->record.int_value = random_value;
    }
}

int main() {
    srand(time(NULL));

    // Determine the maximum number of records based on memory usage constraints
    size_t max_records = MAX_MEMORY_USAGE / 128; // Estimate average size per record, adjust as needed

    ConcurrentRecord *records = (ConcurrentRecord *)calloc(max_records, sizeof(ConcurrentRecord));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array\n");
        return EXIT_FAILURE;
    }

    int key_min = 64; // Minimum buffer size
    int key_max = 256; // Maximum buffer size
    int value_range = 1000; // Range of integer values

    initialize_records(records, max_records, key_min, key_max, value_range);

    // Example logging
    printf("Initialized %zu records with constraints applied.\n", max_records);

    // Clean up resources
    for (size_t i = 0; i < max_records; ++i) {
        pthread_mutex_destroy(&records[i].lock);
        free(records[i].record.buffer);
    }
    free(records);

    return EXIT_SUCCESS;
}
