typedef struct {
    int id;
    char name[50];
    // Other fields...
} LTE_PHY_TransportChannelInfo;

#define INITIAL_CAPACITY 10
#define REALLOC_THRESHOLD 0.75

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_warning(const char *message) {
    fprintf(stdout, "Warning: %s\n", message);
}

// Function to initialize a LTE_PHY_TransportChannelInfo structure
int init_transport_channel_info(LTE_PHY_TransportChannelInfo *info) {
    // Simulate external data source initialization
    if (info == NULL) return -1;

    // Validate and set default values
    info->id = rand() % 1000; // Example ID assignment
    snprintf(info->name, sizeof(info->name), "Channel_%d", info->id);

    // Return success or failure
    return 0;
}

// Function to manage a dynamically allocated array of structures
int manage_transport_channels(LTE_PHY_TransportChannelInfo **channels, size_t *size) {
    if (channels == NULL || size == NULL) return -1;

    static size_t capacity = INITIAL_CAPACITY;
    if (*channels == NULL) {
        *channels = malloc(capacity * sizeof(LTE_PHY_TransportChannelInfo));
        if (*channels == NULL) {
            log_error("Failed to allocate initial memory");
            return -1;
        }
        *size = 0; // Initialize size
    }

    for (size_t i = 0; i < *size; ++i) {
        if (init_transport_channel_info(&(*channels)[i]) != 0) {
            log_warning("Failed to initialize channel info");
        }
    }

    return 0;
}

// Function to add a new LTE_PHY_TransportChannelInfo structure
int add_transport_channel(LTE_PHY_TransportChannelInfo **channels, size_t *size) {
    if (channels == NULL || size == NULL || *channels == NULL) return -1;

    static size_t capacity = INITIAL_CAPACITY;

    // Check if we need to reallocate memory
    if (*size >= capacity * REALLOC_THRESHOLD) {
        size_t new_capacity = capacity * 2; // Double the capacity for growth
        LTE_PHY_TransportChannelInfo *new_channels = realloc(*channels, new_capacity * sizeof(LTE_PHY_TransportChannelInfo));

        if (new_channels == NULL) {
            log_error("Failed to reallocate memory");
            return -1;
        }

        *channels = new_channels;
        capacity = new_capacity; // Update the static capacity
    }

    LTE_PHY_TransportChannelInfo *channel_info = &(*channels)[*size];

    if (init_transport_channel_info(channel_info) != 0) {
        log_warning("Failed to initialize new channel info");
        return -1;
    }

    (*size)++;
    return 0;
}

// Function to free the allocated memory
void free_transport_channels(LTE_PHY_TransportChannelInfo **channels) {
    if (channels && *channels) {
        free(*channels);
        *channels = NULL; // Avoid dangling pointer
    }
}
