#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    int *data;
    size_t count;
} Node;

typedef struct NodeEntry {
    char *key;
    Node node;
    struct NodeEntry *next;
} NodeEntry;

typedef struct {
    NodeEntry *head;
    pthread_mutex_t lock;
} NodeCollection;

NodeCollection* create_collection() {
    NodeCollection *collection = malloc(sizeof(NodeCollection));
    if (!collection) return NULL;
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int add_node(NodeCollection *collection, const char *key, int *data, size_t count) {
    if (!collection || !key || !data) return -1;

    pthread_mutex_lock(&collection->lock);

    // Check for duplicate keys
    NodeEntry *current = collection->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Duplicate key error code
        }
        current = current->next;
    }

    NodeEntry *entry = malloc(sizeof(NodeEntry));
    if (!entry) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Memory allocation failure
    }

    entry->key = strdup(key);
    if (!entry->key) {
        free(entry);
        pthread_mutex_unlock(&collection->lock);
        return -3;
    }

    int *data_copy = malloc(count * sizeof(int));
    if (!data_copy) {
        free(entry->key);
        free(entry);
        pthread_mutex_unlock(&collection->lock);
        return -3;
    }

    memcpy(data_copy, data, count * sizeof(int));

    entry->node.key = entry->key;
    entry->node.data = data_copy;
    entry->node.count = count;
    entry->next = collection->head;
    collection->head = entry;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

Node* find_node(NodeCollection *collection, const char *key) {
    if (!collection || !key) return NULL;

    pthread_mutex_lock(&collection->lock);

    NodeEntry *current = collection->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&collection->lock);
            return &current->node;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Not found
}

void free_collection(NodeCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    NodeEntry *current = collection->head;
    while (current) {
        NodeEntry *next = current->next;
        free(current->node.data);
        free(current->key);
        free(current);
        current = next;
    }

    collection->head = NULL;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    NodeCollection *collection = create_collection();
    if (!collection) return -1;

    int data[] = {1, 2, 3, 4, 5};
    add_node(collection, "example", data, 5);

    Node *node = find_node(collection, "example");
    if (node) {
        printf("Key: %s, Data: ", node->key);
        for (size_t i = 0; i < node->count; ++i) {
            printf("%d ", node->data[i]);
        }
        printf("\n");
    }

    free_collection(collection);

    return 0;
}
```

### Explanation

- **Concurrency**: The `pthread_mutex_lock` and `pthread_mutex_unlock` functions are used to protect critical sections, ensuring that the collection is accessed by only one thread at a time.

- **Error Handling**: The function returns error codes for different failure scenarios like duplicate keys or memory allocation failures.

- **Memory Management**: Each node's data array and key string are dynamically allocated. When freeing the collection, all associated resources are released to prevent leaks.

- **Edge Cases**: Handles null pointers gracefully and checks for duplicate keys before insertion.

This implementation ensures thread safety and efficient management of a dynamic collection of nodes with integer arrays, while also considering memory usage and performance.']

