// Memory pool for efficient allocations
NFAPI_CRC_INDICATION_PDU_T* memory_pool[MAX_STRUCTURES];
int pool_index = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    if (pool_index < MAX_STRUCTURES) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
