    for (size_t i = 0; i < num_interfaces; ++i) {
        json_t *interface_obj = json_object();

        json_object_set_new(interface_obj, "name", json_string(interfaces[i].name));
        json_object_set_new(interface_obj, "ip_address", json_string(interfaces[i].ip_address));
        json_object_set_new(interface_obj, "subnet_mask", json_string(interfaces[i].subnet_mask));
        json_object_set_new(interface_obj, "gateway_address", json_string(interfaces[i].gateway_address));

        json_t *ports_array = json_array();
        for (size_t j = 0; j < interfaces[i].num_ports; ++j) {
