        const char *subnet_mask = json_string_value(json_object_get(interface_obj, "subnet_mask"));
        const char *gateway_address = json_string_value(json_object_get(interface_obj, "gateway_address"));

        size_t ports_count = json_array_size(json_object_get(interface_obj, "ports"));
        interfaces[i].num_ports = ports_count;
        interfaces[i].ports = malloc(ports_count * sizeof(PortConfig));

        for (size_t j = 0; j < ports_count; ++j) {
