            const char *protocol = json_string_value(json_object_get(port_obj, "protocol"));
            interfaces[i].ports[j].port = json_integer_value(json_object_get(port_obj, "port"));

            const char *traffic_type = json_string_value(json_object_get(port_obj, "traffic_type"));

            snprintf(interfaces[i].ports[j].protocol, sizeof(interfaces[i].ports[j].protocol), "%s", protocol);
            snprintf(interfaces[i].ports[j].traffic_type, sizeof(interfaces[i].ports[j].traffic_type), "%s", traffic_type);
        }

        strncpy(interfaces[i].name, name, sizeof(interfaces[i].name) - 1);
        strncpy(interfaces[i].ip_address, ip_address, sizeof(interfaces[i].ip_address) - 1);
        strncpy(interfaces[i].subnet_mask, subnet_mask, sizeof(interfaces[i].subnet_mask) - 1);
        strncpy(interfaces[i].gateway_address, gateway_address, sizeof(interfaces[i].gateway_address) - 1);
    }

    json_decref(root);
    return interfaces;
}

