#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

void initList(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int isValidRNTI(unsigned short rnti) {
    return (rnti >= 1 && rnti <= 65535);
}

void addNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!isValidRNTI(data.RNTI)) {
        fprintf(stderr, "Invalid RNTI value.\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "List is full.\n");
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    // Randomize CRCFLAG
    srand(time(NULL) ^ pthread_self());
    newNode->data.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
}

void clearList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void traverseList(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void freeList(LinkedList* list) {
    clearList(list);
    pthread_mutex_destroy(&list->lock);
}

// Example callback function
void printNodeData(NFAPI_CRC_INDICATION_PDU_T* data) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG, data->CRCFLAG);
}

int main() {
    LinkedList list;
    initList(&list);

    NFAPI_CRC_INDICATION_PDU_T exampleData = {1, 12345, 6789, 0};
    addNode(&list, exampleData);

    traverseList(&list, printNodeData);

    freeList(&list);
    return 0;
}
```

