// Add a new packet to the list ensuring timestamps are monotonically increasing
int add_packet(DataPacket** head, const char* source_ip, const char* dest_ip, uint64_t timestamp) {
    if (!head || !source_ip || !dest_ip) return -1;

    // Get current max timestamp in list to ensure monotonicity
    DataPacket *current = *head;
    uint64_t max_timestamp = 0;

    while (current != NULL) {
        if (current->Timestamp > max_timestamp) {
            max_timestamp = current->Timestamp;
        }
        current = current->next;
    }

    // Ensure new timestamp is monotonically increasing
    if (timestamp <= max_timestamp) {
        timestamp = get_system_time();  // Adjust to system time or other source for correct sequencing
    }

    // Allocate memory for a new packet
    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) return -2; // Memory allocation failure

    // Initialize the new packet with provided data
    new_packet->Timestamp = timestamp;
    strncpy(new_packet->SourceIP, source_ip, sizeof(new_packet->SourceIP) - 1);
    new_packet->SourceIP[sizeof(new_packet->SourceIP) - 1] = '\0';
    strncpy(new_packet->DestinationIP, dest_ip, sizeof(new_packet->DestinationIP) - 1);
    new_packet->DestinationIP[sizeof(new_packet->DestinationIP) - 1] = '\0';

    // Assign a unique PacketID based on position in the list
    new_packet->PacketID = (*head ? (*head)->PacketID + 1 : 1);

    // Insert the new packet at the head of the list for fast insertion
    new_packet->next = *head;
    *head = new_packet;

    return 0; // Success
}

// Free all allocated memory in the linked list
void free_packet_list(DataPacket* head) {
    DataPacket* current = head;
    while (current != NULL) {
        DataPacket* next = current->next;
        free(current);
        current = next;
    }
