DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
    list->elements_added = 0;
    list->elements_removed = 0;

    return list;
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);

    printf("List destroyed. Elements added: %d, removed: %d\n",
           list->elements_added, list->elements_removed);
}

int add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (data.RNTI < 1 || data.RNTI > 65535) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;

    list->elements_added++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_node(DoublyLinkedList* list) {
