    list->head = node->next;

    if (list->head) {
        list->head->prev = NULL;
    } else {
        list->tail = NULL;
    }

    free(node_to_remove);
    list->size--;

    list->elements_removed++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void update_rnti_values(DoublyLinkedList* list, uint16_t new_rnti_value) {
    if (new_rnti_value < 1 || new_rnti_value > 65535) return;

    pthread_rwlock_wrlock(&list->rwlock);

    Node* current = list->head;
    while (current) {
        current->data.RNTI = new_rnti_value;
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

