    threading.Lock_acquire(&list->lock);
    if (list->count < MAX_LIST_SIZE) {
        list->elements[list->count++] = pdu;
        if (pdu->crcTag.CRCFLAG) {
            list->processedCount++;
        }
    } else {
        fprintf(stderr, "List is full. Cannot add new element.\n");
    }
    threading.Lock_release(&list->lock);
}

