    threading.Lock_acquire(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = (index < list->count) ? list->elements[index] : NULL;
    threading.Lock_release(&list->lock);
    return pdu;
}

void remove_pdu(DynamicList* list, size_t index) {
    threading.Lock_acquire(&list->lock);
    if (index < list->count) {
        free(list->elements[index]);
        for (size_t i = index; i < list->count - 1; i++) {
            list->elements[i] = list->elements[i + 1];
        }
        list->elements[--list->count] = NULL;
    } else {
        fprintf(stderr, "Index out of bounds. Cannot remove element.\n");
    }
    threading.Lock_release(&list->lock);
}

