    Message *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageList;

void initialize_message_list(MessageList *list) {
    list->count = 0;
    list->capacity = 100; // initial capacity
    list->messages = (Message *)malloc(sizeof(Message) * list->capacity);
    if (!list->messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void add_message(MessageList *list, Message message) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Message *new_messages = (Message *)realloc(list->messages, sizeof(Message) * new_capacity);
        if (!new_messages) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }

    list->messages[list->count++] = message;

    pthread_mutex_unlock(&list->lock);
}

int compare_priority(const void *a, const void *b) {
    Message *msgA = (Message *)a;
    Message *msgB = (Message *)b;
    return msgB->priority_level - msgA->priority_level; // descending order
}

void sort_messages(MessageList *list) {
    pthread_mutex_lock(&list->lock);
    qsort(list->messages, list->count, sizeof(Message), compare_priority);
    pthread_mutex_unlock(&list->lock);
}

void process_messages(MessageList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        // Process each message
        printf("Processing Message: %zu, %ld, %d\n", 
               list->messages[i].payload_size, list->messages[i].timestamp,
               list->messages[i].priority_level);
    }

    pthread_mutex_unlock(&list->lock);
}

void free_message_list(MessageList *list) {
    free(list->messages);
    pthread_mutex_destroy(&list->lock);
}

// Mock function to simulate reading messages from external streams
void read_from_stream(MessageList *list, size_t num_messages) {
    for (size_t i = 0; i < num_messages; ++i) {
        Message message;
        message.payload_size = rand() % 1024 + 1; // Random payload size between 1 and 1024
        message.timestamp = time(NULL); // Current timestamp
        message.priority_level = rand() % 10 + 1; // Priority level between 1 and 10

        add_message(list, message);
    }
}

int main() {
    MessageList list;
    initialize_message_list(&list);

    const size_t num_messages_per_second = MAX_MESSAGES_PER_SECOND;

    for (size_t i = 0; i < 5; ++i) { // Simulate reading messages for 5 seconds
        read_from_stream(&list, num_messages_per_second);
        sort_messages(&list);
        process_messages(&list);
    }

    free_message_list(&list);

    return 0;
}
