#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkEvent {
    time_t timestamp;
    char eventType[50];
} NetworkEvent;

typedef struct TCPConnection {
    int id;
    time_t lastCommunication;
    NetworkEvent* events;
    size_t eventCount;
    pthread_mutex_t mutex;
} TCPConnection;

typedef struct ConnectionNode {
    TCPConnection* connection;
    struct ConnectionNode* next;
} ConnectionNode;

typedef struct ConnectionManager {
    ConnectionNode* head;
    pthread_rwlock_t rwlock;
} ConnectionManager;

// Initialize the connection manager
void init_connection_manager(ConnectionManager* cm) {
    cm->head = NULL;
    pthread_rwlock_init(&cm->rwlock, NULL);
}

// Clean up the connection manager
void cleanup_connection_manager(ConnectionManager* cm) {
    ConnectionNode* current = cm->head;
    while (current != NULL) {
        TCPConnection* conn = current->connection;
        free(conn->events);
        pthread_mutex_destroy(&conn->mutex);
        ConnectionNode* temp = current;
        current = current->next;
        free(conn);
        free(temp);
    }
    pthread_rwlock_destroy(&cm->rwlock);
}

// Create a new connection
TCPConnection* create_connection(int id) {
    TCPConnection* conn = (TCPConnection*)malloc(sizeof(TCPConnection));
    if (!conn) return NULL;

    conn->id = id;
    time(&(conn->lastCommunication));

    pthread_mutex_init(&conn->mutex, NULL);
    conn->events = NULL;
    conn->eventCount = 0;

    return conn;
}

// Insert a connection into the manager
void insert_connection(ConnectionManager* cm, TCPConnection* conn) {
    pthread_rwlock_wrlock(&cm->rwlock);

    ConnectionNode* newNode = (ConnectionNode*)malloc(sizeof(ConnectionNode));
    if (!newNode) {
        pthread_rwlock_unlock(&cm->rwlock);
        return;
    }

    newNode->connection = conn;
    newNode->next = cm->head;
    cm->head = newNode;

    pthread_rwlock_unlock(&cm->rwlock);
}

// Retrieve a connection by ID
TCPConnection* get_connection(ConnectionManager* cm, int id) {
    pthread_rwlock_rdlock(&cm->rwlock);

    ConnectionNode* current = cm->head;
    while (current != NULL) {
        TCPConnection* conn = current->connection;

        pthread_mutex_lock(&conn->mutex);
        if (conn->id == id) {
            pthread_mutex_unlock(&conn->mutex);
            pthread_rwlock_unlock(&cm->rwlock);
            return conn;
        }
        pthread_mutex_unlock(&conn->mutex);

        current = current->next;
    }

    pthread_rwlock_unlock(&cm->rwlock);
    return NULL;
}

// Remove a connection by ID
void remove_connection(ConnectionManager* cm, int id) {
    pthread_rwlock_wrlock(&cm->rwlock);

    ConnectionNode *current = cm->head, *prev = NULL;

    while (current != NULL) {
        TCPConnection* conn = current->connection;

        pthread_mutex_lock(&conn->mutex);
        if (conn->id == id) {
            if (prev == NULL)
                cm->head = current->next;
            else
                prev->next = current->next;

            free(conn->events);
            pthread_mutex_destroy(&conn->mutex);
            free(current->connection);
            free(current);

            pthread_rwlock_unlock(&cm->rwlock);
            return;
        }
        pthread_mutex_unlock(&conn->mutex);

        prev = current;
        current = current->next;
    }

    pthread_rwlock_unlock(&cm->rwlock);
}

// Add an event to a connection
void add_event(ConnectionManager* cm, int id, const char* eventType) {
    TCPConnection* conn = get_connection(cm, id);

    if (conn) {
        pthread_mutex_lock(&conn->mutex);

        time_t now;
        time(&now);

        conn->events = realloc(conn->events, sizeof(NetworkEvent) * (conn->eventCount + 1));
        if (!conn->events) {
            pthread_mutex_unlock(&conn->mutex);
            return;
        }

        NetworkEvent* newEvents = conn->events;
        newEvents[conn->eventCount].timestamp = now;
        strncpy(newEvents[conn->eventCount].eventType, eventType, sizeof(newEvents[conn->eventCount].eventType) - 1);

        conn->eventCount++;
        pthread_mutex_unlock(&conn->mutex);
    }
}

// Filter connections by last communication timestamp
void filter_connections(ConnectionManager* cm, time_t threshold) {
    pthread_rwlock_rdlock(&cm->rwlock);

    ConnectionNode* current = cm->head;
    while (current != NULL) {
        TCPConnection* conn = current->connection;

        pthread_mutex_lock(&conn->mutex);
        if (difftime(time(NULL), conn->lastCommunication) > threshold) {
            printf("Connection ID: %d\n", conn->id);
        }
        pthread_mutex_unlock(&conn->mutex);

        current = current->next;
    }

    pthread_rwlock_unlock(&cm->rwlock);
}

// Example usage
int main() {
    ConnectionManager cm;
    init_connection_manager(&cm);

    TCPConnection* conn1 = create_connection(1);
    insert_connection(&cm, conn1);

    add_event(&cm, 1, "Connected");
    filter_connections(&cm, 3600); // Filter connections inactive for more than an hour

    remove_connection(&cm, 1);
    cleanup_connection_manager(&cm);

    return 0;
}
