#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simple checksum function for integrity validation
uint32_t calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += data[i].RX_UE_INFORMATION_TAG + data[i].RNTI + data[i].CRCFLAG;
    }
    return checksum;
}

int manage_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* num_elements, size_t new_count) {
    if (new_count == 0 || new_count > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid number of elements requested.\n");
        return -1; // Error code for invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(*array, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(*array);
        return -1; // Error code for memory allocation failure
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < new_count; ++i) {
        temp_array[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        temp_array[i].RNTI = (uint16_t)(rand() % 65536); // Random RNTI
        temp_array[i].CRCFLAG = rand() & 0xFF; // Random CRCFLAG

        // Validate data integrity using checksum
        uint32_t checksum = calculate_checksum(temp_array, i + 1);
        if (checksum != (i + 1) * (temp_array[i].RX_UE_INFORMATION_TAG + temp_array[i].RNTI + temp_array[i].CRCFLAG)) {
            fprintf(stderr, "Data integrity check failed.\n");
            free(temp_array);
            return -2; // Error code for data integrity failure
        }
    }

    *array = temp_array;
    if (num_elements) {
        *num_elements = new_count;
    }

    return 0; // Success
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* num_elements) {
    if (array && *array) {
        free(*array);
        *array = NULL;
        if (num_elements) {
            *num_elements = 0;
        }
    }
}
