#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 100000

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
} LinkedList;

uint16_t precomputed_checksum[NMAX_ENTRIES];

// Function to generate a random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Hash function for RNTI uniqueness check
unsigned int hash_rnti(uint16_t rnti) {
    return rnti;
}

// Create new linked list node
NFAPI_CRC_INDICATION_PDU_T* create_node(uint16_t rnti, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->ue_info.RNTI = rnti;
    new_node->crc_indication_rel8.CRCFLAG = crcflag;
    new_node->next = NULL;
    return new_node;
}

// Check for unique RNTI
int is_unique_rnti(LinkedList *list, uint16_t rnti) {
    unsigned int hash_index = hash_rnti(rnti);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        if (hash_rnti(current->ue_info.RNTI) == hash_index &&
            current->ue_info.RNTI == rnti) {
            return 0; // RNTI is not unique
        }
        current = current->next;
    }
    return 1; // RNTI is unique
}

// Add node to linked list, ensuring uniqueness of RNTI
void add_node(LinkedList *list, uint16_t rnti) {
    if (!is_unique_rnti(list, rnti)) {
        fprintf(stderr, "Duplicate RNTI detected: %u\n", rnti);
        return;
    }

    int crcflag = generate_random_crcflag();
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(rnti, crcflag);

    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return;
    }

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

// Verify the integrity of the linked list
void verify_integrity(LinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        unsigned int index = hash_rnti(current->ue_info.RNTI) % MAX_ENTRIES;
        if (precomputed_checksum[index] != current->crc_indication_rel8.CRCFLAG) {
            fprintf(stderr, "Checksum mismatch detected for RNTI: %u\n", current->ue_info.RNTI);
            // Handle the corrupted entry gracefully
            NFAPI_CRC_INDICATION_PDU_T *to_delete = current;
            current = current->next;

            pthread_mutex_lock(&list->mutex);
            if (list->head == to_delete) {
                list->head = current;
            }

            free(to_delete);
            pthread_mutex_unlock(&list->mutex);
        } else {
            current = current->next;
        }
    }
}

// Serialize the linked list to disk
void serialize_list(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    fclose(file);
}

// Deserialize the linked list from disk
void deserialize_list(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T node;
        size_t read_size = fread(&node, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (read_size != 1) break; // EOF or error

        NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(node.ue_info.RNTI, node.crc_indication_rel8.CRCFLAG);

        new_node->next = current;
        current = new_node;
    }

    list->head = current;

    pthread_mutex_unlock(&list->mutex);
    fclose(file);
}

// Initialize linked list
void init_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Free linked list
void free_list(LinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *to_free = current;
        current = current->next;
        free(to_free);
    }

    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    LinkedList list;
    init_list(&list);

    // Add nodes to the linked list
    for (uint16_t rnti = 0; rnti < 1000; ++rnti) {
        add_node(&list, rnti);
    }

    // Verify integrity
    verify_integrity(&list);

    // Serialize and deserialize example
    serialize_list(&list, "list_data.bin");
    free_list(&list); // Clear current list
    init_list(&list); // Reinitialize
    deserialize_list(&list, "list_data.bin");

    // Free resources
    free_list(&list);
    return 0;
}
