#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG; // Assuming a single byte flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    pthread_mutex_t lock;
} NFALIST_T;

// Initialize list with dynamic memory allocation
void initialize_list(NFALIST_T *list, size_t initial_size) {
    if (initial_size > MAX_STRUCTURES) {
        fprintf(stderr, "Initial size exceeds maximum allowed structures\n");
        return;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for NFALIST_T data");
        exit(EXIT_FAILURE);
    }
    list->size = initial_size;
    pthread_mutex_init(&list->lock, NULL);
}

// Resize the list
void resize_list(NFALIST_T *list, size_t new_size) {
    if (new_size > MAX_STRUCTURES) {
        fprintf(stderr, "Requested size exceeds maximum allowed structures\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        perror("Failed to resize memory for NFALIST_T data");
        exit(EXIT_FAILURE);
    }
    list->data = temp;
    list->size = new_size;
}

// Function to initialize and manage the list
void manage_nfa_list(NFALIST_T *list, size_t num_structures) {
    pthread_mutex_lock(&list->lock);

    if (num_structures > MAX_STRUCTURES) {
        fprintf(stderr, "Number of structures exceeds maximum allowed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    resize_list(list, num_structures);

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_structures; ++i) {
        list->data[i].RX_UE_INFORMATION_TAG = rand(); // Randomly set
        list->data[i].RNTI = rand() & 0xFFFF;         // Ensure RNTI is within valid range
        list->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)
    }

    pthread_mutex_unlock(&list->lock);
}

// Clean up resources
void cleanup_list(NFALIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    list->data = NULL;
    list->size = 0;
}

int main() {
    NFALIST_T nfaList;
    initialize_list(&nfaList, 100); // Initial size
    manage_nfa_list(&nfaList, 5000); // Manage with 5000 structures

    cleanup_list(&nfaList);
    return 0;
}
