// Dynamic list structure
typedef struct {
    ListNode* head;
    int size;
} NFAPICRCList;

// Function prototypes
int addOrUpdateElement(NFAPICRCList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T element);
