// Add or update an element by RNTI
int addOrUpdateElement(NFAPICRCList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || !filename) return ERROR_INVALID_INPUT;

    ListNode** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            // Update existing
            (*current)->data = element;
            return SUCCESS;
        }
        current = &(*current)->next;
    }

    // Add new element
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return ERROR_MEMORY_ALLOCATION;

    newNode->data = element;
    newNode->next = NULL;
    *current = newNode;
    list->size++;

    return SUCCESS;
}

// Remove an element by RNTI
int removeElementByRNTI(NFAPICRCList* list, int RNTI) {
    if (!list || !filename) return ERROR_INVALID_INPUT;

    ListNode** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == RNTI) {
            ListNode* toDelete = *current;
            *current = (*current)->next;
            free(toDelete);
            list->size--;
            return SUCCESS;
        }
        current = &(*current)->next;
    }

    return ERROR_NOT_FOUND;
}

// Serialize the list to a binary file
void serializeListToFile(const NFAPICRCList* list, const char* filename) {
    if (!list || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->size, sizeof(int), 1, file);
    ListNode* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Deserialize the list from a binary file
NFAPICRCList* deserializeListFromFile(const char* filename) {
    if (!filename) return NULL;

    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) {
        fclose(file);
        return NULL;
    }
    list->head = NULL;
    list->size = 0;

    fread(&list->size, sizeof(int), 1, file);
    NFAPI_CRC_INDICATION_PDU_T element;
    for (int i = 0; i < list->size; ++i) {
        fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        addOrUpdateElement(list, element.RNTI, element);
    }

    fclose(file);
    return list;
}

// Free the entire list
void freeList(NFAPICRCList* list) {
    if (!list) return;

    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Example usage
int main() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return ERROR_MEMORY_ALLOCATION;

    list->head = NULL;
    list->size = 0;

    NFAPI_CRC_INDICATION_PDU_T element = {1, 100, 200, 0xFF};
    addOrUpdateElement(list, 100, element);

    serializeListToFile(list, "list.bin");
    NFAPICRCList* loadedList = deserializeListFromFile("list.bin");

    removeElementByRNTI(loadedList, 100);
    freeList(list);
    freeList(loadedList);

    return SUCCESS;
}
