    struct Node* left;
    struct Node* right;
    unsigned char height;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    node->height = 1;
    return node;
}

int height(Node* N) {
    if (N == NULL)
        return 0;
    return N->height;
}

Node* right_rotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = (height(y->left) > height(y->right) ? height(y->left) : height(y->right)) + 1;
    x->height = (height(x->left) > height(x->right) ? height(x->left) : height(x->right)) + 1;

    return x;
}

Node* left_rotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = (height(x->left) > height(x->right) ? height(x->left) : height(x->right)) + 1;
    y->height = (height(y->left) > height(y->right) ? height(y->left) : height(y->right)) + 1;

    return y;
}

int get_balance(Node* N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

Node* insert(Node* node, NFAPI_CRC_INDICATION_PDU_T data) {
    if (node == NULL)
        return create_node(data);

    if (data.RNTI < node->data.RNTI)
        node->left = insert(node->left, data);
    else if (data.RNTI > node->data.RNTI)
        node->right = insert(node->right, data);
    else
        return node;

    node->height = 1 + (height(node->left) > height(node->right) ? height(node->left) : height(node->right));

    int balance = get_balance(node);

    if (balance > 1 && data.RNTI < node->left->data.RNTI)
        return right_rotate(node);
    if (balance < -1 && data.RNTI > node->right->data.RNTI)
        return left_rotate(node);
    if (balance > 1 && data.RNTI > node->left->data.RNTI) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }
    if (balance < -1 && data.RNTI < node->right->data.RNTI) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

Node* minValueNode(Node* node) {
    Node* current = node;

    while (current->left != NULL)
        current = current->left;

    return current;
}

Node* delete_node(Node* root, uint16_t RNTI) {
    if (root == NULL)
        return root;

    if (RNTI < root->data.RNTI)
        root->left = delete_node(root->left, RNTI);
    else if (RNTI > root->data.RNTI)
        root->right = delete_node(root->right, RNTI);
    else {
        if ((root->left == NULL) || (root->right == NULL)) {
            Node* temp = root->left ? root->left : root->right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp;
            free(temp);
        } else {
            Node* temp = minValueNode(root->right);

            root->data = temp->data;
            root->right = delete_node(root->right, temp->data.RNTI);
        }
    }

    if (root == NULL)
        return root;

    root->height = 1 + (height(root->left) > height(root->right) ? height(root->left) : height(root->right));

    int balance = get_balance(root);

    if (balance > 1 && get_balance(root->left) >= 0)
        return right_rotate(root);
    if (balance > 1 && get_balance(root->left) < 0) {
        root->left = left_rotate(root->left);
        return right_rotate(root);
    }
    if (balance < -1 && get_balance(root->right) <= 0)
        return left_rotate(root);
    if (balance < -1 && get_balance(root->right) > 0) {
        root->right = right_rotate(root->right);
        return left_rotate(root);
    }

    return root;
}

