// Function implementations
UE_Context_Manager* create_ue_context_manager(size_t initial_capacity) {
    UE_Context_Manager* manager = (UE_Context_Manager*)malloc(sizeof(UE_Context_Manager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for UE_Context_Manager\n");
        return NULL;
    }

    manager->contexts = (UE_Context*)calloc(initial_capacity, sizeof(UE_Context));
    if (!manager->contexts) {
        free(manager);
        fprintf(stderr, "Failed to allocate memory for UE contexts\n");
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->total_frames = 0;

    pthread_mutex_init(&manager->lock, NULL);

    // Initialize cache and other attributes...

    return manager;
}

void destroy_ue_context_manager(UE_Context_Manager* manager) {
    if (manager) {
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_ue_context(UE_Context_Manager* manager, int cell_id, int frequency_band) {
    pthread_mutex_lock(&manager->lock);

    // Check for existing context with the same cell ID
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].cell_id == cell_id) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Context already exists
        }
    }

    // Resize array if necessary
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UE_Context* new_contexts = (UE_Context*)realloc(manager->contexts, new_capacity * sizeof(UE_Context));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(stderr, "Failed to reallocate memory for UE contexts\n");
            return -1;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    // Add new context
    UE_Context* new_context = &manager->contexts[manager->size++];
    new_context->cell_id = cell_id;
    new_context->frequency_band = frequency_band;
    new_context->frame_count = 0;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int delete_ue_context(UE_Context_Manager* manager, int cell_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].cell_id == cell_id) {
            // Shift contexts to fill the gap
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    (manager->size - i - 1) * sizeof(UE_Context));
            manager->size--;
            manager->total_frames -= manager->contexts[i].frame_count;

            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Context not found
}

LTE_DL_FRAME* get_frame(UE_Context_Manager* manager, int cell_id, int frame_index) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].cell_id == cell_id) {
            if (frame_index >= 0 && frame_index < manager->contexts[i].frame_count) {
                pthread_mutex_unlock(&manager->lock);
                return &manager->contexts[i].frames[frame_index];
            }
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Context or frame not found
}

void reset_total_frames_count(UE_Context_Manager* manager) {
    pthread_mutex_lock(&manager->lock);
    manager->total_frames = 0;

    for (size_t i = 0; i < manager->size; ++i) {
        manager->total_frames += manager->contexts[i].frame_count;
    }

    pthread_mutex_unlock(&manager->lock);
}

