#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the PacketMetadata structure
typedef struct {
    time_t timestamp;
    char *packet_id;
    size_t payload_size;
    void *payload; // Variable-length payload
} PacketMetadata;

// Node for linked list and hashtable entry
typedef struct PacketNode {
    PacketMetadata metadata;
    struct PacketNode *next;  // For collision resolution in hash table or linked list chaining
} PacketNode;

// Hash table bucket definition
#define HASH_TABLE_SIZE 1024

PacketNode *hash_table[HASH_TABLE_SIZE] = { NULL };

unsigned int hash_function(const char *packet_id) {
    unsigned long hash = 5381;
    int c;
    while ((c = *packet_id++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % HASH_TABLE_SIZE;
}

// Function to add or update a packet in the dynamic list
void add_or_update_packet(const char *packet_id, time_t timestamp, size_t payload_size, const void *payload_data) {
    unsigned int index = hash_function(packet_id);

    // Search for existing node with same packet_id
    PacketNode *current = hash_table[index];
    while (current != NULL) {
        if (strcmp(current->metadata.packet_id, packet_id) == 0) {
            // Update existing entry
            current->metadata.timestamp = timestamp;
            free(current->metadata.payload);
            current->metadata.payload_size = payload_size;
            current->metadata.payload = malloc(payload_size);
            if (current->metadata.payload != NULL) {
                memcpy(current->metadata.payload, payload_data, payload_size);
            }
            return;
        }
        current = current->next;
    }

    // Create new node
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    if (!new_node) {
        perror("Failed to allocate memory for new packet");
        exit(EXIT_FAILURE);
    }

    new_node->metadata.packet_id = strdup(packet_id);
    new_node->metadata.timestamp = timestamp;
    new_node->metadata.payload_size = payload_size;
    new_node->metadata.payload = malloc(payload_size);

    if (new_node->metadata.payload != NULL) {
        memcpy(new_node->metadata.payload, payload_data, payload_size);
    } else {
        free(new_node->metadata.packet_id);
        free(new_node);
        perror("Failed to allocate memory for packet payload");
        exit(EXIT_FAILURE);
    }

    // Insert into hash table
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

// Function to retrieve packets based on time interval
PacketNode **retrieve_packets(time_t start_time, time_t end_time, size_t *count) {
    static PacketNode *result[MAX_PACKETS]; // Adjust MAX_PACKETS as per expected maximum
    *count = 0;

    for (int i = 0; i < HASH_TABLE_SIZE && *count < MAX_PACKETS; ++i) {
        PacketNode *current = hash_table[i];
        while (current != NULL && *count < MAX_PACKETS) {
            if (current->metadata.timestamp >= start_time && current->metadata.timestamp <= end_time) {
                result[(*count)++] = current;
            }
            current = current->next;
        }
    }

    return result; // Caller must handle deallocation of this static buffer
}

// Cleanup function to free all allocated memory
void cleanup() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        PacketNode *current = hash_table[i];
        while (current != NULL) {
            PacketNode *temp = current;
            current = current->next;
            free(temp->metadata.packet_id);
            free(temp->metadata.payload);
            free(temp);
        }
    }
}

int main() {
    // Example usage
    time_t now = time(NULL);

    add_or_update_packet("packet1", now, 10, "data12345");
    size_t packet_count;
    PacketNode **packets = retrieve_packets(now - 60, now + 60, &packet_count);

    for (size_t i = 0; i < packet_count; ++i) {
        printf("Packet ID: %s, Timestamp: %ld\n", packets[i]->metadata.packet_id, packets[i]->metadata.timestamp);
    }

    cleanup();
    return 0;
}
```

### Key Considerations:
1. **Hash Table**: Provides average-case O(1) complexity for insertions and lookups.
2. **Collision Handling**: Linked list chaining is used to handle hash collisions.
3. **Memory Management**: Carefully allocates and deallocates memory to prevent leaks and fragmentation.
4. **Concurrency & Scalability**: The current implementation does not include concurrency mechanisms; consider using mutexes or other synchronization primitives in a multi-threaded environment.
5. **Batch Processing/Asynchronous Handling**: Not implemented but can be added by introducing task queues or worker threads for processing packets.']

