        array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].RNTI = i + 1; // Ensure unique RNTI
        array[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        array[i].CRCFLAG = rand() % 2; // Simulate error rate
    }

    return array;
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T **array, int *current_size) {
    pthread_mutex_lock(&resize_lock);
    int new_size = (*current_size) * RESIZE_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) {
        failed_allocations++;
        pthread_mutex_unlock(&resize_lock);
        return; // Handle allocation failure gracefully
    }
    successful_allocations++;
    resizes++;

    for (int i = *current_size; i < new_size; ++i) {
        new_array[i].RX_UE_INFORMATION_TAG = rand() % 100;
        new_array[i].RNTI = i + 1; // Ensure unique RNTI
        new_array[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        new_array[i].CRCFLAG = rand() % 2; // Simulate error rate
    }

    *array = new_array;
    *current_size = new_size;
    pthread_mutex_unlock(&resize_lock);
}

void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (array && *array) {
        free(*array);
        *array = NULL;
    }
}

