typedef struct NFAPI_CRC_INDICATION_PDU_T_ {
    UE_INFORMATION ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct NFAPI_CRC_INDICATION_PDU_T_* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe linked list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} ConcurrentList;

// Custom memory allocator
typedef struct {
    size_t block_size;
    void** free_list;
    int num_blocks;
    pthread_mutex_t alloc_lock;
} CustomAllocator;

void* custom_alloc(CustomAllocator* allocator) {
    pthread_mutex_lock(&allocator->alloc_lock);
    if (allocator->free_list && *allocator->free_list) {
        void* ptr = *(allocator->free_list);
        *(allocator->free_list) = *((void**)ptr);
        pthread_mutex_unlock(&allocator->alloc_lock);
        return (char*)ptr + sizeof(void*);
    }
    pthread_mutex_unlock(&allocator->alloc_lock);

    // Fallback to standard malloc
    return malloc(allocator->block_size);
}

void custom_free(CustomAllocator* allocator, void* ptr) {
    if (!ptr) return;
    pthread_mutex_lock(&allocator->alloc_lock);
    *(void**)ptr = allocator->free_list;
    allocator->free_list = (void**)ptr;
    pthread_mutex_unlock(&allocator->alloc_lock);
}

// Function to create and populate the linked list
ConcurrentList* create_nfa_crc_indication_pdu_list(int count, CustomAllocator* allocator) {
    ConcurrentList* list = (ConcurrentList*)custom_alloc(allocator);
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;

    pthread_t threads[10];  // Example thread pool size
    int max_threads = count < 10 ? count : 10;

    for (int i = 0; i < max_threads; ++i) {
        pthread_create(&threads[i], NULL, (void* (*)(void*))create_and_link_pdu, list);
    }

    for (int i = 0; i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return list;
}

void* create_and_link_pdu(void* arg) {
    ConcurrentList* list = (ConcurrentList*)arg;

    srand(time(NULL) ^ pthread_self()); // Seed with time and thread ID

    for (int i = 0; i < 100; ++i) {  // Example division of workload
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(allocator);
        if (!node) continue;

        pthread_mutex_lock(&list->lock);

        node->ue_info.RX_UE_INFORMATION_TAG = rand() % 1000;
        node->ue_info.RNTI = rand() % 10000;
        node->crc_indication.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
        node->next = list->head;
        list->head = node;

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

// Usage Example (assuming CustomAllocator is initialized elsewhere)
