            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
            new_node->prev = current;
        }

        processed_count++;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double time_elapsed = end.tv_sec - start.tv_sec + (end.tv_nsec - start.tv_nsec) / 1e9;

    log_performance_metrics("Processed: ");
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%u elements in %.2f seconds\n", processed_count, time_elapsed);
    log_performance_metrics(buffer);

    pthread_mutex_unlock(&list_mutex);

