    if (!validate_pdu(pdu)) {
        fprintf(stderr, "Invalid PDU data\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    resize_array_if_needed(array);

    if (array->count >= array->capacity) {
        fprintf(stderr, "Failed to add PDU: Array is at full capacity\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->data[array->count++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Resize the dynamic array if needed
void resize_array_if_needed(DynamicArray* array) {
    double load_factor = (double)array->count / array->capacity;
    if (load_factor > RESIZE_THRESHOLD) {
        size_t new_capacity = array->capacity * 2; // Double capacity for growth
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

// Example usage of the dynamic array
int main() {
    DynamicArray* pdu_array = create_dynamic_array(INITIAL_SIZE);
    if (!pdu_array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 25; ++i) { // Example loop to add PDUs
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % 1000,
            .CRC_INDICATION_REL8_TAG = {.CRCFLAG = rand() % 2}
        };

        if (add_pdu_to_array(pdu_array, pdu) != 0) {
            fprintf(stderr, "Failed to add PDU #%zu\n", i);
        }
    }

    free_dynamic_array(pdu_array);
    return EXIT_SUCCESS;
}
```

### Explanation:

- **DynamicArray Structure**: Manages a dynamic array with a mutex for thread safety.
