void init_allocator(NFAPI_CRC_INDICATION_LIST* list, size_t pool_size) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->node_count = 0;
    list->free_list = (void**)malloc(pool_size * sizeof(void*));
    for (size_t i = 0; i < pool_size; ++i) {
        list->free_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->pool_size = pool_size;
    list->hash_table_size = 1024; // Example size
    list->rnti_table = (unsigned int*)calloc(list->hash_table_size, sizeof(unsigned int));
}

NFAPI_CRC_INDICATION_PDU_T* allocate_node(NFAPI_CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->lock);
    if (list->node_count < list->pool_size) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)list->free_list[list->node_count++];
        pthread_mutex_unlock(&list->lock);
        return node;
    }
    // Reuse from free list if available
    for (size_t i = 0; i < list->pool_size; ++i) {
        if (!((NFAPI_CRC_INDICATION_PDU_T*)list->free_list[i])->next) { // Check if unused
            NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)list->free_list[i];
            pthread_mutex_unlock(&list->lock);
            return node;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // No available node
}

void free_node(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list->lock);
    if (node && --list->node_count < list->pool_size) {
        size_t index = list->node_count;
        list->free_list[index] = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void insert_crc_indication(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !list) return;

    unsigned int hash_index = pdu->rnti % list->hash_table_size;
    pthread_mutex_lock(&list->lock);

    // Check for RNTI uniqueness
    if (list->rnti_table[hash_index] == pdu->rnti) {
        printf("RNTI already exists\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->rnti_table[hash_index] = pdu->rnti;

    // Insert node into linked list
    pdu->next = list->head;
    list->head = pdu;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(NFAPI_CRC_INDICATION_LIST* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current, *temp;
    current = list->head;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free_node(list, temp);
    }

    pthread_mutex_destroy(&list->lock);
    for (size_t i = 0; i < list->pool_size; ++i) {
        free(list->free_list[i]);
    }
    free(list->free_list);
    free(list->rnti_table);
}

void serialize_list(NFAPI_CRC_INDICATION_LIST* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    NFAPI_CRC_INDIGATION_PDU_T* current = list->head;
    while (current != NULL) {
        fwrite(&current->rnti, sizeof(current->rnti), 1, file);
        // Serialize other fields as needed
        current = current->next;
    }

    fclose(file);
}

void deserialize_list(NFAPI_CRC_INDICATION_LIST* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T* pdu;
    while (fread(&pdu->rnti, sizeof(pdu->rnti), 1, file)) {
        // Deserialize other fields as needed
        insert_crc_indication(list, pdu);
    }

    fclose(file);
}

void traverse_list(NFAPI_CRC_INDICATION_LIST* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        printf("RNTI: %u\n", current->rnti);
        // Traverse other fields as needed
        current = current->next;
    }
}

void* async_get_random_crcflag(void* arg) {
    int crcflag = get_random_crcflag();
    pthread_mutex_lock(&list->lock);
    ((NFAPI_CRC_INDICATION_PDU_T*)arg)->crc_indication_rel8_tag.CRCFLAG = crcflag;
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void process_batch(NFAPI_CRC_INDICATION_LIST* list, size_t batch_size) {
    NFAPI_CRC_INDICATION_PDU_T *pdu, pdu_array[batch_size];
    for (size_t i = 0; i < batch_size; ++i) {
        pdu = allocate_node(list);
        if (!pdu) break;
        pdu->rnti = rand() % 10000; // Example RNTI generation
        pthread_t thread;
        pthread_create(&thread, NULL, async_get_random_crcflag, (void*)pdu);
        pthread_join(thread, NULL);
        pdu_array[i] = *pdu;
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST list;
    init_allocator(&list, 1000);

    process_batch(&list, 50); // Process batch of size 50

    traverse_list(&list);

    serialize_list(&list, "nfaapi_crc_indications.bin");
    cleanup_list(&list);

    return 0;
}
```

