    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_crc_pdu(CRC_List *list, RX_UE_INFORMATION_TAG ue_info, int CRCFLAG) {
