    if (!new_node) return;

    new_node->ue_info.RNTI = ue_info.RNTI;
    new_node->crc_tag.CRCFLAG = CRCFLAG;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void delete_crc_pdu(CRC_List *list, unsigned long RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->ue_info.RNTI == RNTI) {
            if (current->prev) current->prev->next = current->next;
            else list->head = current->next;

            if (current->next) current->next->prev = current->prev;
            else list->tail = current->prev;

            free(current);
            list->count--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_reverse(CRC_List *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->tail;
    while (current) {
        callback(current);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void sample_callback(NFAPI_CRC_INDICATION_PDU_T *node) {
