    pthread_mutex_lock(&alloc->lock);
    if (alloc->pool_size >= alloc->block_size) {
        void* ptr = alloc->pool;
        alloc->pool += alloc->block_size;
        alloc->pool_size -= alloc->block_size;
        pthread_mutex_unlock(&alloc->lock);
        return (Node*)ptr;
    }
    pthread_mutex_unlock(&alloc->lock);
    return NULL; // Out of memory
