#include <string.h>
#include <pthread.h>

typedef struct {
    uint8_t* data;
    size_t length;
} L2_PDU_HEADER;

typedef struct {
    // Assume RRC_PDU is a placeholder for actual PDU structure
    int rrc_pdu_data; 
    L2_PDU_HEADER header;
} NFAPI_L2_PDU_T;

typedef struct {
    NFAPI_L2_PDU_T* pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PDU_Manager;

// Function prototypes
PDU_Manager* pdu_manager_init(size_t initial_capacity);
void pdu_manager_destroy(PDU_Manager* manager);
int pdu_manager_add_pdu(PDU_Manager* manager, NFAPI_L2_PDU_T* pdu);
int pdu_manager_update_pdu(PDU_Manager* manager, size_t index, NFAPI_L2_PDU_T* pdu);
void pdu_manager_iterate(PDU_Manager* manager, void (*operation)(NFAPI_L2_PDU_T*));

// Initialize PDU Manager
PDU_Manager* pdu_manager_init(size_t initial_capacity) {
    PDU_Manager* manager = (PDU_Manager*)malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->pdus = (NFAPI_L2_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_L2_PDU_T));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Destroy PDU Manager
void pdu_manager_destroy(PDU_Manager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdus[i].header.data);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->pdus);
    free(manager);
}

// Add PDU
int pdu_manager_add_pdu(PDU_Manager* manager, NFAPI_L2_PDU_T* pdu) {
    if (!manager || !pdu) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_L2_PDU_T* temp = realloc(manager->pdus, new_capacity * sizeof(NFAPI_L2_PDU_T));
        if (!temp) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }

        manager->pdus = temp;
        manager->capacity = new_capacity;
    }

    memcpy(manager->pdus + manager->count, pdu, sizeof(NFAPI_L2_PDU_T));
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Update PDU
int pdu_manager_update_pdu(PDU_Manager* manager, size_t index, NFAPI_L2_PDU_T* pdu) {
    if (!manager || !pdu || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);

    memcpy(manager->pdus + index, pdu, sizeof(NFAPI_L2_PDU_T));

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Iterate over PDUs
void pdu_manager_iterate(PDU_Manager* manager, void (*operation)(NFAPI_L2_PDU_T*)) {
    if (!manager || !operation) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        operation(manager->pdus + i);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example operation function
void example_operation(NFAPI_L2_PDU_T* pdu) {
    // Perform operations on each PDU, e.g., print data length
    printf("PDU Data Length: %zu\n", pdu->header.length);
}
