// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} CRCArray;

// Initialize the dynamic array
void crc_array_init(CRCArray *crc_array, size_t initial_capacity) {
    crc_array->capacity = initial_capacity;
    crc_array->count = 0;
    crc_array->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * crc_array->capacity);
    if (!crc_array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&crc_array->lock, NULL);
}

// Resize the dynamic array
void crc_array_resize(CRCArray *crc_array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(crc_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    crc_array->capacity = new_capacity;
    crc_array->array = new_array;
}

// Add a new element to the array
void crc_array_add(CRCArray *crc_array, double probability) {
    pthread_mutex_lock(&crc_array->lock);

    if (crc_array->count == crc_array->capacity) {
        crc_array_resize(crc_array, crc_array->capacity * 2);
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = {0};
    srand(time(NULL));
    if ((double)rand() / RAND_MAX < probability) {
        new_element.CRCFLAG = 1;
    } else {
        new_element.CRCFLAG = 0;
    }

    crc_array->array[crc_array->count] = new_element;
    crc_array->count++;
    pthread_mutex_unlock(&crc_array->lock);

    // Log the addition
    printf("Added element with CRCFLAG: %d\n", new_element.CRCFLAG);
}

// Update an existing element in the array
void crc_array_update(CRCArray *crc_array, size_t index, int new_crc_flag) {
    pthread_mutex_lock(&crc_array->lock);

    if (index >= crc_array->count) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&crc_array->lock);
        return;
    }

    crc_array->array[index].CRCFLAG = new_crc_flag;

    // Log the update
    printf("Updated element at index %zu with CRCFLAG: %d\n", index, new_crc_flag);

    pthread_mutex_unlock(&crc_array->lock);
}

// Free the memory used by the dynamic array
void crc_array_free(CRCArray *crc_array) {
    free(crc_array->array);
    pthread_mutex_destroy(&crc_array->lock);
}

int main() {
    CRCArray crc_array;
    crc_array_init(&crc_array, 100);

    // Example usage
    crc_array_add(&crc_array, 0.5); // Add with 50% probability for CRCFLAG = 1
    crc_array_update(&crc_array, 0, 1); // Update first element

    crc_array_free(&crc_array);
    return 0;
}
```

