    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(LinkedList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_node(LinkedList *list, int ue_id, uint16_t rnti, unsigned char crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return;

    new_node->rx_ue_info_tag.ue_id = ue_id;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag.crc_flag = crc_flag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;

    pthread_mutex_unlock(&list->lock);
}

int simulate_error() {
    return rand() / (RAND_MAX + 1.0) < ERROR_RATE;
}

void populate_list(LinkedList *list, int num_nodes) {
    srand(time(NULL));
    for (int i = 0; i < num_nodes; ++i) {
        unsigned char crc_flag = simulate_error() ? 0 : 1;
        insert_node(list, i, rand(), crc_flag);
    }
}

void validate_list(LinkedList *list) {
    int valid_count = 0;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->crc_indication_rel8_tag.crc_flag == 1 || simulate_error()) {
            valid_count++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

