#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_NODES 10000
#define ERROR_RATE 0.05
#define MEMORY_LIMIT_PERCENT 90
#define CONCURRENT_WRITES 50000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t node_count;
    double total_access_time;
    int access_count;
} LinkedList;

LinkedList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0.0, 0};

void initialize_node(Node** node) {
    *node = (Node*)malloc(sizeof(Node));
    if (*node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu.RNTI = rand() % 1000;
    pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu.CRCFLAG = (rand() / (double)RAND_MAX) < ERROR_RATE;
    return pdu;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = NULL;
    initialize_node(&new_node);
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_head_node(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    clock_t start = clock();
    NFAPI_CRC_INDICATION_PDU_T* data = &list->head->data;
    list->total_access_time += (double)(clock() - start) / CLOCKS_PER_SEC;
    list->access_count++;

    pthread_mutex_unlock(&list->lock);
    return data;
}

void validate_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (!current->data.CRCFLAG) {
            fprintf(stderr, "CRCFLAG error detected in node\n");
        }
        current = current->next;
    }
}

double get_average_access_time(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    double avg_time = (list->access_count > 0) ? list->total_access_time / list->access_count : 0.0;
    pthread_mutex_unlock(&list->lock);
    return avg_time;
}

void log_performance_metrics(LinkedList* list) {
    printf("Average Access Time: %.6f seconds\n", get_average_access_time(list));
    printf("Node Count: %zu\n", list->node_count);
}

int main() {
    srand(time(NULL));

    for (size_t i = 0; i < MAX_NODES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        insert_node(&list, pdu);
    }

    validate_list(&list);
    log_performance_metrics(&list);

    // Simulate concurrent operations
    pthread_t threads[CONCURRENT_WRITES];
    for (int i = 0; i < CONCURRENT_WRITES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        pthread_create(&threads[i], NULL, (void*(*)(void*))insert_node, &list);
    }
    for (int i = 0; i < CONCURRENT_WRITES; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_performance_metrics(&list);

    // Cleanup
    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list.lock);

    return 0;
}
