#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

// Assuming these are defined somewhere in the system headers.
typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Initialize a random seed
void initialize_random_seed() {
    srand((unsigned)time(NULL));
}

bool is_rnti_unique(Node* head, int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return false;
        current = current->next;
    }
    return true;
}

Node* create_node(int rnti, int rx_ue_info_tag, int crc_rel8_tag, bool crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        return NULL;
    }
    new_node->data.RNTI = rnti;
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    new_node->data.CRCFLAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

Node* manage_crc_list(int N) {
    if (N <= 0)
        return NULL;

    Node* head = NULL;
    for (int i = 0; i < N; ++i) {
        // Generate random RNTI, RX_UE_INFORMATION_TAG, CRC_INDICATION_REL8_TAG, and CRCFLAG
        int rnti = rand() % 10000 + 1; // Example range
        int rx_ue_info_tag = rand() % 100;
        int crc_rel8_tag = rand() % 100;
        bool crc_flag = (rand() % 2) == 0;

        if (!is_rnti_unique(head, rnti))
            continue;

        Node* new_node = create_node(rnti, rx_ue_info_tag, crc_rel8_tag, crc_flag);
        if (!new_node) {
            // If memory allocation fails, free already allocated nodes
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->next = head;
        head = new_node;
    }
    return head;
}

void clear_crc_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Example usage
int main() {
    initialize_random_seed();
    int N = 10; // Example size

    Node* list = manage_crc_list(N);

    if (!list)
        printf("Failed to create CRC indication list.\n");

    // Iterate over the list (if needed, e.g., for testing or further processing)

    clear_crc_list(list);

    return 0;
}
