typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList list = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    node->rx_ue_info.ue_id = rand() % 10000; // Simulating some data
    node->rnti.rnti_value = rand();
    node->crc_indication.crc_flag = (rand() / (RAND_MAX + 1.0)) > ERROR_RATE;
}

void add_node_to_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    initialize_node(new_node);

    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void validate_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    size_t count = 0;

    while (current) {
        printf("Node %zu: UE ID %d, RNTI %lu, CRC Flag %d\n",
               ++count,
               current->rx_ue_info.ue_id,
               current->rnti.rnti_value,
               current->crc_indication.crc_flag);

        if (current->next && current->next->prev != current) {
            fprintf(stderr, "List integrity error at node %zu\n", count);
        }

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void log_performance_metrics() {
    // Placeholder for logging performance metrics
    printf("Average access time: %f ms\n", 10.5); // Simulated value
    printf("Memory utilization: %f%%\n", 85.3);   // Simulated value
}

int main() {
    srand(time(NULL));

    for (size_t i = 0; i < MAX_NODES; ++i) {
        add_node_to_list(&list);
    }

    validate_list(&list);
    log_performance_metrics();

    free_list(&list);

    return 0;
}
