#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 100

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int resolve_hostname_to_ip(const char* hostname, char* ip) {
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(p->ai_family, addr, ip, sizeof(ip));
        break; // Return after the first address found
    }

    freeaddrinfo(res);
    return 0;
}

void* resolve_and_populate(void* arg) {
    char** hostnames = (char**)arg;
    NFAPI_CRC_INDICATION_PDU_T* result_list[MAX_STRUCTS];
    int index = 0;
    pthread_mutex_t lock;

    pthread_mutex_init(&lock, NULL);
    srand(time(NULL));

    for (int i = 0; hostnames[i] != NULL && index < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) break;

        char ip[INET6_ADDRSTRLEN];
        if (resolve_hostname_to_ip(hostnames[i], ip) == 0) {
            strcpy(pdu->ip, ip);
            pthread_mutex_lock(&lock);
            pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
            pdu->RNTI = rand() % 10000;
            pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            result_list[index++] = pdu;
            pthread_mutex_unlock(&lock);
        } else {
            free(pdu);
        }
    }

    pthread_mutex_destroy(&lock);
    return (void*)result_list;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <hostname1> <hostname2> ...", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_STRUCTS];
    NFAPI_CRC_INDICATION_PDU_T* result_list[MAX_STRUCTS];

    for (int i = 0; i < argc - 1 && i < MAX_STRUCTS; ++i) {
        if (pthread_create(&threads[i], NULL, resolve_and_populate, &argv[i + 1]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1 && i < MAX_STRUCTS; ++i) {
        if (pthread_join(threads[i], (void**)&result_list[i]) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - 1 && result_list[i] != NULL; ++i) {
        printf("IP: %s, RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n",
               result_list[i]->ip,
               result_list[i]->RX_UE_INFORMATION_TAG,
               result_list[i]->RNTI,
               result_list[i]->crc_indication_rel8_tag.CRCFLAG);
        free(result_list[i]);
    }

    return EXIT_SUCCESS;
}
