#include <string.h>
#include <pthread.h>

#define MAX_CONTEXTS 500
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    int UE_ID;
    unsigned short RNTI;
    char *SRB1_RRCConnectionControlMessage;
} NRUEContext;

typedef struct {
    NRUEContext *contexts[MAX_CONTEXTS];
    size_t count;
    pthread_mutex_t lock;
    size_t rollingChecksum;
} ContextPool;

// Predefined set of possible SRB1 messages
const char *srbs[5] = {
    "InitialContextSetup",
    "ConnectionUpdateComplete",
    "HandoverPreparation",
    "UplinkNASTransport",
    "SecurityModeCommand"
};

void init_context_pool(ContextPool *pool) {
    pool->count = 0;
    pool->rollingChecksum = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

int add_context(ContextPool *pool, int UE_ID, unsigned short RNTI) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= MAX_CONTEXTS) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->contexts[i]->RNTI == RNTI) {
            pthread_mutex_unlock(&pool->lock);
            return -2; // Duplicate RNTI
        }
    }

    NRUEContext *new_context = malloc(sizeof(NRUEContext));
    if (!new_context) {
        pthread_mutex_unlock(&pool->lock);
        return -3; // Memory allocation failure
    }

    new_context->UE_ID = UE_ID;
    new_context->RNTI = RNTI;

    size_t msg_index = rand() % 5;
    new_context->SRB1_RRCConnectionControlMessage = strdup(srbs[msg_index]);
    if (!new_context->SRB1_RRCConnectionControlMessage) {
        free(new_context);
        pthread_mutex_unlock(&pool->lock);
        return -4; // Memory allocation failure
    }

    pool->contexts[pool->count++] = new_context;
    pool->rollingChecksum += (unsigned char)new_context->SRB1_RRCConnectionControlMessage[0];

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void evict_inactive(ContextPool *pool) {
    pthread_mutex_lock(&pool->lock);

    // For demonstration, assume every context is inactive
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->contexts[i]->SRB1_RRCConnectionControlMessage);
        free(pool->contexts[i]);
    }
    pool->count = 0;

    pthread_mutex_unlock(&pool->lock);
}

void cleanup_context_pool(ContextPool *pool) {
    evict_inactive(pool);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    ContextPool pool;
    init_context_pool(&pool);

    // Example usage
    if (add_context(&pool, 1, 100) == 0) {
        printf("Context added successfully.\n");
    } else {
        printf("Failed to add context.\n");
    }

    cleanup_context_pool(&pool);
    return 0;
}
