        // Ensure unique EPS_Bearer_ID
        do {
            eps_bearer_id = rand() % EPS_BEARER_ID_MAX + 1;
        } while (used_ids[eps_bearer_id]);
        used_ids[eps_bearer_id] = 1;

        list->messages[i].eutran_cnas_message.has_valid_EUTRAN_CNAS_MESSAGE = 1; // Assuming valid message

        // Assign random NAS_MESSAGE_TYPE with probabilities
        int rand_value = rand() % 100;
        if (rand_value < 50) {
            list->messages[i].eps_bearer_context.nas_message_type = NAS_MESSAGE_TYPE_A;
        } else if (rand_value < 80) {
            list->messages[i].eps_bearer_context.nas_message_type = NAS_MESSAGE_TYPE_B;
        } else {
            list->messages[i].eps_bearer_context.nas_message_type = NAS_MESSAGE_TYPE_C;
        }

        // Assign EPS_Bearer_ID
        list->messages[i].eps_bearer_context.EPS_Bearer_ID = eps_bearer_id;

        // Update checksum (thread-safe update)
        pthread_mutex_lock(&list->lock);
        list->checksum += eps_bearer_id;
        pthread_mutex_unlock(&list->lock);
    }

    return 0; // Success
}

uint32_t calculate_checksum(uint16_t *ids, size_t count) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += ids[i];
    }
    return checksum;
}

void free_nas_message_list(NASMessageList *list) {
    if (list->messages) {
        free(list->messages);
        list->messages = NULL;
    }
    pthread_mutex_destroy(&list->lock);
}
```

This code defines a function `populate_nas_message_list` that dynamically allocates and populates an array of `LTE_ENB_API_NAS_Message` structures. It ensures unique EPS_Bearer_IDs, assigns random NAS_MESSAGE_TYPE with configurable probabilities, maintains thread safety using mutex locks, and calculates a checksum for data integrity verification. The function handles memory allocation failures gracefully by returning error codes. Additionally, it provides a `free_nas_message_list` to deallocate resources safely.']

