['Here's a C implementation of a thread-safe dynamic array to manage `NFAPI_CRC_INDICATION_PDU_T` structures with detailed logging, efficient memory management, and probabilistic CRC flag setting:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    int log_level;
} DynamicArray;

void initialize_random() {
    srand((unsigned)time(NULL));
}

unsigned char probabilistic_crc_flag() {
    // Simulate CRC flag based on a probability, e.g., 10% failure rate
    return (rand() % 100 < 10);
}

void dynamic_array_init(DynamicArray* da, int log_level) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_ADAPTIVE_NP);

    pthread_mutex_init(&da->mutex, &attr);
    pthread_mutexattr_destroy(&attr);

    da->array = NULL;
    da->size = 0;
    da->capacity = 0;

    if (log_level > 0) {
        printf("DynamicArray initialized with capacity %zu\n", da->capacity);
    }
}

void resize_array(DynamicArray* da, size_t new_capacity) {
    pthread_mutex_lock(&da->mutex);

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Failed to resize array\n");
        pthread_mutex_unlock(&da->mutex);
        return;
    }

    da->array = new_array;
    da->capacity = new_capacity;

    if (da->log_level > 0) {
        printf("DynamicArray resized to capacity %zu\n", da->capacity);
    }

    pthread_mutex_unlock(&da->mutex);
}

void add_pdu(DynamicArray* da, unsigned int rx_tag, unsigned int rnti, unsigned int crc_rel8_tag) {
    pthread_mutex_lock(&da->mutex);

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity == 0 ? INITIAL_CAPACITY : da->capacity * 2;
        resize_array(da, new_capacity);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &da->array[da->size];
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    pdu->CRCFLAG = probabilistic_crc_flag();

    if (da->log_level > 1) {
        printf("Added PDU: RX=%u, RNTI=%u, CRC=%u, FLAG=%d\n", 
               rx_tag, rnti, crc_rel8_tag, pdu->CRCFLAG);
    }

    da->size++;

    pthread_mutex_unlock(&da->mutex);
}

void free_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->mutex);

    if (da->array != NULL) {
        free(da->array);
        da->array = NULL;
        da->size = 0;
        da->capacity = 0;

        if (da->log_level > 0) {
            printf("DynamicArray memory freed\n");
        }
    }

    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

int main() {
    initialize_random();

    DynamicArray da;
    dynamic_array_init(&da, 2);

    for (unsigned int i = 0; i < 20; ++i) {
        add_pdu(&da, rand(), rand(), rand());
    }

    free_dynamic_array(&da);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex to protect the dynamic array operations ensuring thread safety.
- **Dynamic Resizing**: Automatically resizes when capacity is exceeded, doubling the size each time.
- **Probabilistic CRC Flag Setting**: Uses a random number generator to set `CRCFLAG` based on a simulated probability.
- **Logging**: Adjustable logging levels provide detailed debug information.
- **Error Handling**: Handles allocation errors gracefully and reports them.

This implementation balances efficiency with safety by using mutex locks for thread safety while keeping the code simple enough for high throughput scenarios.']

