    return pdu;
}

int validate_rnti(unsigned long rnti) {
    // Mock function to simulate external data source validation
    return (rnti % 1000 != 0); // Example condition
}

void log_reuse(int reuse_count) {
    printf("Cache Reused: %d times\n", reuse_count);
}

void evict_cache_item() {
    if (cache.count == 0 || cache.head == NULL) return;

    CacheNode *node_to_evict = cache.tail;
    if (node_to_evict != NULL) {
        pthread_mutex_lock(&cache.lock);
        if (cache.head == node_to_evict) {
            cache.head = node_to_evict->next;
        }
        if (cache.head) {
            cache.head->prev = NULL;
        }
        cache.tail = node_to_evict->prev;
        if (cache.tail) {
            cache.tail->next = NULL;
        }
        free(node_to_evict);
        cache.count--;
        pthread_mutex_unlock(&cache.lock);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_from_cache(unsigned long rnti, int *reuse_count) {
    pthread_mutex_lock(&cache.lock);
    CacheNode *current = cache.head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti && validate_rnti(rnti)) {
            // Move to front
            if (current == cache.head) {
                current->last_access_time = time(NULL);
            } else {
                if (current->prev) current->prev->next = current->next;
                if (current->next) current->next->prev = current->prev;
                if (cache.tail == current) cache.tail = current->prev;

                current->next = cache.head;
                current->prev = NULL;
                if (cache.head) cache.head->prev = current;
                cache.head = current;
                current->last_access_time = time(NULL);
            }
            (*reuse_count)++;
            pthread_mutex_unlock(&cache.lock);
            return &current->pdu;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

void add_pdu_to_cache(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (cache.count == MAX_CACHE_SIZE) {
        evict_cache_item();
    }

    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->pdu = *pdu;
    new_node->last_access_time = time(NULL);
    new_node->next = cache.head;
    new_node->prev = NULL;

    if (cache.head) {
        cache.head->prev = new_node;
    }
    cache.head = new_node;

    if (!cache.tail) {
        cache.tail = new_node;
    }

    cache.count++;
}

NFAPI_CRC_INDICATION_PDU_T* manage_pdu_array(int N) {
    int reuse_count = 0;

    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_pdu_from_cache(rand() % 100000, &reuse_count);
        if (!pdu) {
            pdu = get_random_pdu();
            add_pdu_to_cache(pdu);
        }
    }
    log_reuse(reuse_count);
    pthread_mutex_unlock(&cache.lock);

    return NULL; // This function just manages the cache and doesn't need to return anything
}

