uint16_t generate_unique_tag(uint16_t* used_tags, int max_tags) {
    uint16_t tag;
    do {
        tag = rand() % max_tags;
    } while (used_tags[tag] == 1);
    used_tags[tag] = 1;
    return tag;
}

bool is_crc_flag_needed(double probability_threshold) {
    double random_value = (double)rand() / RAND_MAX * 100.0;
    return random_value < probability_threshold;
}

void log_pdu_creation(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
