    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&list_mutex);

        // Generate unique RX_UE_INFORMATION_TAG and RNTI
        uint16_t rx_tag = generate_unique_tag(used_rx_tags, RX_UE_INFO_TAG_MAX);
        uint16_t rnti = generate_unique_tag(used_rntis, RNTI_MAX);

        // Populate CRC flag based on probability threshold
        pdu_list[i].rnti = rnti;
        pdu_list[i].crcIndicationRel8Tag.crcflag = is_crc_flag_needed(config.crc_probability_threshold) ? 1 : 0;

        pthread_mutex_unlock(&list_mutex);

        // Log creation with minimal overhead
        log_pdu_creation(&pdu_list[i]);

        (*success_count)++;
    }

    return pdu_list;
}

void validate_pdus(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int N) {
