// Define a network event notification structure
typedef struct {
    int eventType;
    time_t timestamp;
    int priority;
} NetworkEvent;

// Define the node structure for linked list
typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} Node;

// Define the dynamically resizable list structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} EventList;

// External logging service mock function
void log_event(const char* message) {
    printf("Logging: %s\n", message);
}

// Function to create a new event node
Node* create_node(int eventType, time_t timestamp, int priority) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->event.eventType = eventType;
    newNode->event.timestamp = timestamp;
    newNode->event.priority = priority;
    newNode->next = NULL;
    return newNode;
}

// Function to initialize the event list
EventList* init_event_list() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new event or update an existing one
void add_or_update_event(EventList* list, int eventType, time_t timestamp, int priority) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->event.eventType == eventType) {
            // Update existing event
            (*current)->event.timestamp = timestamp;
            (*current)->event.priority = priority;
            log_event("Event updated.");
            break;
        }
        current = &((*current)->next);
    }

    if (*current == NULL) {
        // Add new event
        Node* newNode = create_node(eventType, timestamp, priority);
        if (newNode) {
            newNode->next = list->head;
            list->head = newNode;
            log_event("Event added.");
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve events older than a specified duration
void get_old_events(EventList* list, time_t cutoff_time) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (difftime(cutoff_time, current->event.timestamp) > 0) {
            printf("Old Event - Type: %d, Timestamp: %ld, Priority: %d\n",
                   current->event.eventType,
                   current->event.timestamp,
                   current->event.priority);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to delete an event
void delete_event(EventList* list, int eventType) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->event.eventType == eventType) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            log_event("Event deleted.");
            break;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to gracefully handle logging service failures
void safe_log(const char* message) {
    if (log_event(message)) {  // Assuming log_event returns success/failure
        fprintf(stderr, "Logging failed for message: %s\n", message);
    }
}

int main() {
    EventList* list = init_event_list();
    time_t now = time(NULL);

    add_or_update_event(list, 1, now - 1000, 10);
    add_or_update_event(list, 2, now - 500, 5);
    add_or_update_event(list, 3, now, 8);

    printf("Events older than 600 seconds:\n");
    get_old_events(list, now - 600);

    delete_event(list, 1);

    // Cleanup
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);

    return 0;
}
