NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N, const unsigned int seed) {
    // Initialize random number generator
    srand(seed);

    if (N <= 0) {
        log_message("Invalid input: Number of elements must be positive.");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        log_message("Memory allocation failed.");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        // Initialize structure with random data
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;  // Example range
        pdu_array[i].RNTI = rand() % 10000;

        // Generate a random CRCFLAG
        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() % 256;

        // Validate the CRC_INDICATION_REL8_TAG
        unsigned int checksum = calculate_checksum(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI);
        if (crc_tag.CRCFLAG != checksum) {
            log_message("CRC validation failed for one or more elements.");
            free(pdu_array);
            return NULL;
        }
    }

    log_message("Memory allocation and CRC validation succeeded.");
    return pdu_array;
}

unsigned int calculate_checksum(int rx_ue_info_tag, int rnti) {
    // A simple checksum calculation (this is just an example)
    return (rx_ue_info_tag + rnti) & 0xFF;  // Ensure it's a single byte
}

void log_message(const char* message) {
    printf("%s\n", message);
}

