            printf("Element %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n",
                   i, pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI);
        }

        free(pdu_array);
    }

    return 0;
}
