struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    mem->memory = realloc(mem->memory, mem->size + realsize + 1);
    if (mem->memory == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = '\0';

    return realsize;
}

void* load_config_async(void *arg) {
    char *url = (char *)arg;
    CURL *curl_handle;
    struct MemoryStruct chunk;

    chunk.memory = malloc(1);
    if (!chunk.memory) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_ALL);

    curl_handle = curl_easy_init();
    if (curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, url);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&chunk);

        // Retry logic
        int retries = 3;
        CURLcode res;
        do {
            res = curl_easy_perform(curl_handle);
            if (res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                sleep(2); // Wait before retrying
            } else {
                break; // Success
            }
        } while (--retries > 0);

        if (res == CURLE_OK) {
            // Validate and parse the data here
            // Assuming validation and parsing logic is implemented
            printf("Data loaded successfully\n");
        } else {
            fprintf(stderr, "Failed to load configuration after retries\n");
        }

        curl_easy_cleanup(curl_handle);
    }
    curl_global_cleanup();

    free(chunk.memory);

    return NULL;
}

void load_nfaapi_crc_indication_pdu(const char *url) {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, load_config_async, (void *)url)) {
        fprintf(stderr, "Error creating thread\n");
        return;
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);
}
