#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG; // 0 or 1
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory allocator for efficient cache usage
static void* custom_alloc(size_t size) {
    return aligned_alloc(64, size); // Align to 64 bytes for cache efficiency
}

static void custom_free(void* ptr) {
    free(ptr);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
} NFAPICRCIndicationList;

NFAPICRCIndicationList* create_list(size_t initial_capacity) {
    NFAPICRCIndicationList* list = (NFAPICRCIndicationList*)custom_alloc(sizeof(NFAPICRCIndicationList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list\n");
        return NULL;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        custom_free(list);
        fprintf(stderr, "Memory allocation failed for data array\n");
        return NULL;
    }
    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

void free_list(NFAPICRCIndicationList* list) {
    if (list) {
        custom_free(list->data);
        custom_free(list);
    }
}

int add_pdu(NFAPICRCIndicationList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    // Ensure no two consecutive elements share the same RNTI
    if (list->count > 0 && list->data[list->count - 1].RNTI == pdu->RNTI) {
        fprintf(stderr, "Consecutive PDU with same RNTI not allowed\n");
        return -1;
    }

    // Resize array if necessary
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory allocation failed during resize\n");
            return -1;
        }
        memcpy(new_data, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        custom_free(list->data);
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Set random CRCFLAG
    pdu->crc_tag.CRCFLAG = rand() % 2;

    memcpy(&list->data[list->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;
    return 0;
}

int serialize_list(const NFAPICRCIndicationList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    // Write version header
    uint8_t version = 1;
    fwrite(&version, sizeof(version), 1, file);

    // Write count of PDUs
    fwrite(&list->count, sizeof(list->count), 1, file);

    // Write data
    size_t bytes_written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    if (bytes_written != list->count) {
        fprintf(stderr, "Failed to write all PDUs to file\n");
        fclose(file);
        return -1;
    }

    fclose(file);
