    FRAME_TYPE_LTE_PHY_RX,
    // Additional frame types can be added here
    FRAME_TYPE_UNKNOWN
} FrameType;

// Union of all supported frame structures for dynamic handling.
typedef union {
    NFAPI_CRC_INDICATION_PDU_T nfa_api_crc_indication_pdu;
    LTE_PHY_RX_FRAME_T lte_phy_rx_frame;
} FrameUnion;

// Structure to hold dynamic frames and their metadata.
typedef struct {
    FrameType type;
    FrameUnion data;
    double average_power_level; // To store calculated average power level
} DynamicFrame;

// Function to initialize a dynamic array of records with random values.
void init_random_records(int *records, size_t count, int min_val, int max_val) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i] = rand() % (max_val - min_val + 1) + min_val;
    }
}

// Function to calculate the average power level of a frame.
void calculate_average_power_level(DynamicFrame *frame, int *power_values, size_t value_count) {
    if (!frame || !power_values || value_count == 0) return;

    double sum = 0.0;
    for (size_t i = 0; i < value_count; ++i) {
        sum += power_values[i];
    }
    frame->average_power_level = sum / value_count;
}

// Function to create a new dynamic frame based on runtime parameters.
DynamicFrame* create_dynamic_frame(FrameType type, int *power_values, size_t value_count) {
    if (!power_values || value_count == 0) return NULL;

    DynamicFrame *frame = (DynamicFrame *)malloc(sizeof(DynamicFrame));
    if (!frame) return NULL; // Handle memory allocation failure

    frame->type = type;
    calculate_average_power_level(frame, power_values, value_count);

    switch (type) {
        case FRAME_TYPE_NFAPI_CRC_INDICATION:
            memset(&frame->data.nfa_api_crc_indication_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            // Populate with relevant data if available
            break;
        case FRAME_TYPE_LTE_PHY_RX:
            memset(&frame->data.lte_phy_rx_frame, 0, sizeof(LTE_PHY_RX_FRAME_T));
            // Populate with relevant data if available
            break;
        default:
            free(frame);
            return NULL; // Unsupported frame type
    }

    return frame;
}

// Function to safely delete a dynamic frame.
void delete_dynamic_frame(DynamicFrame *frame) {
    if (frame) {
        free(frame);
    }
}

int main() {
    const size_t record_count = 10;
    int power_values[record_count];

    // Initialize records with random values between 1 and 100
    init_random_records(power_values, record_count, 1, 100);

    DynamicFrame *frame = create_dynamic_frame(FRAME_TYPE_NFAPI_CRC_INDICATION, power_values, record_count);
    if (frame) {
        printf("Created frame of type %d with average power level: %.2f\n", 
                frame->type, frame->average_power_level);
        delete_dynamic_frame(frame);
    } else {
        fprintf(stderr, "Failed to create dynamic frame.\n");
    }

    return 0;
}
