}

void* custom_realloc(void *ptr, size_t size) {
    return realloc(ptr, size); // Replace with a more sophisticated reallocation strategy
}

// Function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
int manage_nfa_list(NFAPI_CRC_LIST *list, int new_rnti, int signal_strength, int timing_advance) {
    if (signal_strength < 0 || list->size > 0 && list->elements[list->size - 1].crc_indication_rel8_tag.RNTI == new_rnti) {
        return -1; // Invalid input or consecutive RNTI
    }

    size_t new_capacity = list->capacity;
    if (list->size >= list->capacity) {
        new_capacity *= 2;
        void *new_elements = custom_realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) return -1; // Out of memory
        list->elements = (NFAPI_CRC_INDICATION_PDU_T *)new_elements;
        list->capacity = new_capacity;
    }

    int cumulative_signal_strength = 0;
    for (size_t i = 0; i < list->size; ++i) {
        cumulative_signal_strength += list->elements[i].signal_strength;
    }
    if (cumulative_signal_strength + signal_strength > MAX_SIGNAL_STRENGTH) {
        return -1; // Exceeds signal strength threshold
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = { .ue_info_tag = { .valid = 1 }, 
                                              .crc_indication_rel8_tag = { .RNTI = new_rnti, .CRCFLAG = rand() % 2 },
                                              .signal_strength = signal_strength,
                                              .timing_advance = timing_advance };
    list->elements[list->size++] = new_element;
    return 0; // Success
}

// Serialize the list into a binary format
int serialize_nfa_list(const NFAPI_CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // Failed to open file

    size_t metadata_size = sizeof(size_t) + sizeof(int);
    fwrite(&metadata_size, sizeof(size_t), 1, file); // Write metadata size
    int threshold = MAX_SIGNAL_STRENGTH;
    fwrite(&threshold, sizeof(int), 1, file); // Write signal strength threshold

    size_t elements_size = list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fwrite(&elements_size, sizeof(size_t), 1, file); // Write elements count and size
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    fclose(file);
    return 0; // Success
}

// Initialize the NFAPI_CRC_LIST
void init_nfa_list(NFAPI_CRC_LIST *list) {
    list->size = 0;
    list->capacity = 4; // Initial capacity
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)custom_alloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) exit(EXIT_FAILURE); // Out of memory
}

// Free the NFAPI_CRC_LIST
void free_nfa_list(NFAPI_CRC_LIST *list) {
    custom_free(list->elements);
    list->size = 0;
    list->capacity = 0;
}

