#define MAX_THREADS 100
#define HASH_TABLE_SIZE 1024

typedef struct {
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RRC_UE_Information;
    int RNTI;
    uint8_t CRC_Indication;
} LTE_Uplink_RRC_Indication;

typedef struct HashNode {
    int key;
    struct HashNode *next;
} HashNode;

HashNode* hashTable[HASH_TABLE_SIZE];
pthread_mutex_t hashMutexes[HASH_TABLE_SIZE];

void initHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&hashMutexes[i], NULL);
    }
}

unsigned int hashFunction(int key) {
    return key % HASH_TABLE_SIZE;
}

int isRNTIUnique(int rnti) {
    unsigned int index = hashFunction(rnti);
    pthread_mutex_lock(&hashMutexes[index]);

    HashNode *node = hashTable[index];
    while (node) {
        if (node->key == rnti) {
            pthread_mutex_unlock(&hashMutexes[index]);
            return 0;
        }
        node = node->next;
    }

    HashNode *newNode = malloc(sizeof(HashNode));
    newNode->key = rnti;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;

    pthread_mutex_unlock(&hashMutexes[index]);
    return 1;
}

void freeHashTable() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hashTable[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&hashMutexes[i]);
    }
}

void generateRandomCRCFlag(uint8_t *crcFlag) {
    srand((unsigned int)time(NULL));
    *crcFlag = rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPI_CRC_INDICATION_PDU(int rnti, RX_UE_INFORMATION_TAG rxTag) {
    if (!isRNTIUnique(rnti)) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RNTI = rnti;
    pdu->CRCFLAG = 0;
    generateRandomCRCFlag(&pdu->CRCFLAG);

    // Additional logic to interface with external systems
    return pdu;
}

LTE_Uplink_RRC_Indication* createLTE_Uplink_RRC_Indication(int rrcInfo, int rnti) {
    if (!isRNTIUnique(rnti)) return NULL;

    LTE_Uplink_RRC_Indication *indication = malloc(sizeof(LTE_Uplink_RRC_Indication));
    indication->RRC_UE_Information = rrcInfo;
    indication->RNTI = rnti;
    generateRandomCRCFlag(&indication->CRC_Indication);

    // Additional logic to interface with external systems
    return indication;
}

int* readAndValidateRNTIs(int allowed[], int size, int *count) {
    int *rntis = malloc(sizeof(int) * MAX_THREADS);
    scanf("%d", count);

    for (int i = 0; i < *count; ++i) {
        scanf("%d", &rntis[i]);

        int isValid = 0;
        for (int j = 0; j < size; ++j) {
            if (rntis[i] == allowed[j]) {
                isValid = 1;
                break;
            }
        }

        if (!isValid) {
            fprintf(stderr, "Invalid RNTI: %d\n", rntis[i]);
            free(rntis);
            return NULL;
        }
    }

    return rntis;
}

