import "nfaapi_crc_indication_pdu_t.h"
import "external_logging_service.h"

#define CONFIG_FILE_PATH "/path/to/config/file"
#define BUFFER_SIZE 4096

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    pthread_mutex_t lock;
} NFA_LIST;

NFA_LIST* create_list() {
    NFA_LIST* list = malloc(sizeof(NFA_LIST));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_list(NFA_LIST *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU *tmp = current;
        current = current->next;
        free(tmp);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void* load_config_async(void *arg) {
    FILE *file = fopen(CONFIG_FILE_PATH, "r");
    if (!file) {
        log_error("Failed to open config file.");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    pthread_t thread_id = pthread_self();
    NFA_LIST *list = create_list();

    while (fgets(buffer, BUFFER_SIZE, file)) {
        // Parse and validate the line
        if (parse_line(buffer, &ue_info_tag, &rnti, &crc_rel8_tag) != 0) {
            log_error("Malformed config entry.");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!new_node) {
            log_error("Memory allocation failed.");
            fclose(file);
            destroy_list(list);
            return NULL;
        }

        new_node->ue_info_tag = ue_info_tag;
        new_node->rnti = rnti;
        crc_rel8_tag.crcflag = rand() % 2; // Random CRCFLAG
        new_node->crc_rel8_tag = crc_rel8_tag;
        new_node->next = NULL;

        pthread_mutex_lock(&list->lock);
        if (!list->head) {
            list->head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU *current = list->head;
            while (current->next) current = current->next;
            current->next = new_node;
        }
        pthread_mutex_unlock(&list->lock);
    }

    fclose(file);

    log_info("Config loaded successfully.");
    return (void*)list;
}

void async_load_configuration(NFA_LIST **out_list) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, load_config_async, NULL)) {
        log_error("Failed to create thread for loading config.");
        *out_list = NULL;
        return;
    }

    void *result;
    if (pthread_join(thread, &result)) {
        log_error("Failed to join thread after loading config.");
        *out_list = NULL;
        return;
    }

    *out_list = (NFA_LIST*) result;
}

int main() {
    NFA_LIST *list = NULL;

    async_load_configuration(&list);
    if (!list) {
        log_error("Configuration load failed. Using fallback.");
        // Implement fallback configuration logic here
    }

    // Use the list for further processing

    destroy_list(list);

    return 0;
}
