#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <memory>
#include <chrono>
#include <unordered_map>

// Versioning support for UE_EVENT_RECORD structure
enum class RecordVersion { V1 = 1, V2 = 2 };

struct UE_EVENT_RECORD {
    std::chrono::steady_clock::time_point timestamp;
    int cellID;
    int statusIndicator;
    RecordVersion version;

    UE_EVENT_RECORD(std::chrono::steady_clock::time_point ts, int cid, int si, RecordVersion ver)
        : timestamp(ts), cellID(cid), statusIndicator(si), version(ver) {}
};

class CustomAllocator {
public:
    static void* allocate(size_t size) {
        // Simulate custom memory allocation prioritizing cache locality
        return std::malloc(size);
    }

    static void deallocate(void* ptr, size_t size) {
        std::free(ptr);
    }
};

template<typename T>
using CustomAllocated = std::vector<T, CustomAllocator>;

class EventRecordManager {
private:
    struct RecordNode {
        UE_EVENT_RECORD record;
        std::shared_ptr<RecordNode> next;

        RecordNode(const UE_EVENT_RECORD& rec) : record(rec), next(nullptr) {}
    };

    std::mutex mtx_;
    std::condition_variable cv_;
    std::queue<std::shared_ptr<RecordNode>> records_queue_;
    std::unordered_map<int, std::shared_ptr<RecordNode>> cellID_to_record_;
    std::atomic<bool> shutdown_{false};
    CustomAllocated<UE_EVENT_RECORD> records_store_;

public:
    EventRecordManager(size_t initial_capacity) : records_store_(initial_capacity) {}

    void addRecord(const UE_EVENT_RECORD& record) {
        if (shutdown_.load()) return;

        std::unique_lock<std::mutex> lock(mtx_);
        cv_.wait(lock, [this] { return shutdown_.load() || cellID_to_record_.find(record.cellID) == cellID_to_record_.end(); });

        auto node = std::make_shared<RecordNode>(record);
        records_queue_.push(node);
        cellID_to_record_[record.cellID] = node;

        cv_.notify_all();
    }

    bool retrieveRecords(UE_EVENT_RECORD* out_records, size_t max_count) {
        std::unique_lock<std::mutex> lock(mtx_);
        while (records_queue_.empty() && !shutdown_.load()) {
            cv_.wait(lock);
        }

        if (shutdown_.load()) return false;

        size_t count = 0;
        while (!records_queue_.empty() && count < max_count) {
            auto node = records_queue_.front();
            out_records[count++] = node->record;
            cellID_to_record_.erase(node->record.cellID);
            records_queue_.pop();
        }
        return true;
    }

    void shutdown() {
        std::unique_lock<std::mutex> lock(mtx_);
        shutdown_ = true;
        cv_.notify_all();
