    // Start logging thread
    std::thread logger(loggingThread, std::ref(manager));

    // Simulate adding records concurrently
    for (int i = 0; i < 1000; ++i) {
        UE_EVENT_RECORD record(std::chrono::steady_clock::now(), i % 50 + 1, rand() % 10, RecordVersion::V1);
        manager.addRecord(record);
    }

    // Shutdown the manager
    manager.shutdown();
    logger.join();

    return 0;
}
