} PacketArray;

void initialize_packet(NetworkPacket *packet, uint32_t src_ip, uint32_t dst_ip) {
    packet->src_ip = src_ip;
    packet->dst_ip = dst_ip;
    memset(packet->header, 0, sizeof(packet->header));
    packet->payload_length = rand() % 1500 + 20; // Typical MTU size
    packet->checksum_valid = (rand() % 100) < 90; // 90% valid checksums
    packet->timestamp = time(NULL);
    packet->sequence_number = rand(); // Unique sequence number for simplicity
    pthread_mutex_init(&packet->lock, NULL);
}

PacketArray* create_packet_array(size_t initial_capacity) {
    PacketArray *array = malloc(sizeof(PacketArray));
    array->packets = calloc(initial_capacity, sizeof(NetworkPacket));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->array_lock, NULL);
    return array;
}

void resize_packet_array(PacketArray *array) {
    size_t new_capacity = array->capacity * 2;
    NetworkPacket *new_packets = realloc(array->packets, new_capacity * sizeof(NetworkPacket));

    if (new_packets != NULL) {
        pthread_mutex_lock(&array->array_lock);
        array->packets = new_packets;
        array->capacity = new_capacity;
        pthread_mutex_unlock(&array->array_lock);
    } else {
        fprintf(stderr, "Failed to resize packet array\n");
        exit(EXIT_FAILURE); // In real applications, handle error more gracefully
    }
}

void add_packet(PacketArray *array, uint32_t src_ip, uint32_t dst_ip) {
    pthread_mutex_lock(&array->array_lock);

    if (array->count >= array->capacity) {
        resize_packet_array(array);
    }

    initialize_packet(&array->packets[array->count], src_ip, dst_ip);

    array->count++;
    pthread_mutex_unlock(&array->array_lock);
}

void free_packet_array(PacketArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        pthread_mutex_destroy(&array->packets[i].lock);
    }

    free(array->packets);
    pthread_mutex_destroy(&array->array_lock);
    free(array);
}

int main() {
