    PacketArray *packet_array = create_packet_array(INITIAL_PACKET_COUNT);

    // Example usage
    for (int i = 0; i < 20; ++i) { 
        add_packet(packet_array, rand(), rand());
    }

    free_packet_array(packet_array);

    return 0;
}
