#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
} List;

void initList(List* list) {
    list->head = NULL;
    list->size = 0;
}

void addElement(List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure

    newNode->data = element;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
}

void removeElement(List* list, int RNTI) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return; // Element not found

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
}

void updateCRCFLAG(List* list, int condition) {
    Node* current = list->head;

    while (current != NULL) {
        if ((condition == 1 && current->data.CRC_INDICATION_REL8_TAG % 2 == 0) ||
            (condition == 2 && current->data.CRC_INDICATION_REL8_TAG % 2 != 0)) {
            current->data.CRCFLAG = rand() % 2;
        }
        current = current->next;
    }
}

void serializeList(const char* filename, List* list) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->size, sizeof(size_t), 1, file);
    Node* current = list->head;

    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserializeList(const char* filename, List* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    initList(list); // Reset the list

    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        addElement(list, element);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    List list;
    initList(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456, .CRC_INDICATION_REL8_TAG = 789 };
    addElement(&list, pdu);

    updateCRCFLAG(&list, 1);

    serializeList("nfa_list.bin", &list);

    List newList;
    deserializeList("nfa_list.bin", &newList);

    // Cleanup
    Node* current = list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    current = newList.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
