    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST;

// Function prototypes
NFAPI_CRC_INDICATION_LIST* create_list();
void destroy_list(NFAPI_CRC_INDICATION_LIST *list);
int add_pdu(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T item);
void check_unique_rntis(NFAPI_CRC_INDICATION_LIST *list);

// Create a new list
NFAPI_CRC_INDICATION_LIST* create_list() {
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(*list));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->items = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;

    return list;
}

// Destroy the list and free memory
void destroy_list(NFAPI_CRC_INDICATION_LIST *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->items);
        free(list);
    }
}

// Resize the internal array when necessary
static void ensure_capacity(NFAPI_CRC_INDICATION_LIST *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) return; // Handle error as needed
        list->items = new_items;
        list->capacity = new_capacity;
    }
}

// Add a PDU to the list and ensure RNTIs are unique
int add_pdu(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);
    ensure_capacity(list);

    // Check for duplicate RNTI
    for (size_t i = 0; i < list->size; ++i) {
        if (list->items[i].rnti == item.rnti) {
            fprintf(stderr, "Error: Duplicate RNTI detected (%u)\n", item.rnti);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->items[list->size++] = item;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Validate the integrity of the list by checking RNTI uniqueness
void check_unique_rntis(NFAPI_CRC_INDICATION_LIST *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        for (size_t j = i + 1; j < list->size; ++j) {
            if (list->items[i].rnti == list->items[j].rnti) {
                fprintf(stderr, "Error: Duplicate RNTI detected (%u)\n", list->items[i].rnti);
                pthread_mutex_unlock(&list->lock);
                exit(EXIT_FAILURE); // Graceful termination
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_LIST *list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) { // Simulate adding PDUs
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .ue_info_tag = {.RNTI = rand() % 1024},
            .rnti = rand() % 1024,
            .crc_indication_rel8 = {.CRCFLAG = rand() % 2}
        };

        if (add_pdu(list, pdu) != 0) {
            destroy_list(list);
            return EXIT_FAILURE;
        }
    }

    check_unique_rntis(list);

    // Cleanup
    destroy_list(list);

    return EXIT_SUCCESS;
}
