using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DynamicPduManager
{
    private readonly float _minValue;
    private readonly float _maxValue;
    private readonly int _minIntValue;
    private readonly int _maxIntValue;
    private readonly Random _random = new Random();
    private readonly ConcurrentQueue<NFAPI_CRC_INDICATION_PDU_T> _memoryPool = new ConcurrentQueue<NFAPI_CRC_INDICATION_PDU_T>();
    private readonly object _lockObject = new object();
    private readonly float _crcProbability;

    public DynamicPduManager(float minValue, float maxValue, int minIntValue, int maxIntValue, float crcProbability)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _minIntValue = minIntValue;
        _maxIntValue = maxIntValue;
        _crcProbability = crcProbability;
    }

    private float GenerateRandomFloat()
    {
        return (float)(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    private int GenerateRandomInt()
    {
        return _random.Next(_minIntValue, _maxIntValue + 1);
    }

    public List<NFAPI_CRC_INDICATION_PDU_T> CreatePdus(int n)
    {
        var pdus = new HashSet<Tuple<int, int>>(n); // To ensure uniqueness
        var result = new List<NFAPI_CRC_INDICATION_PDU_T>(n);

        while (pdus.Count < n)
        {
            int rxUeTag = GenerateRandomInt();
            int rnti = GenerateRandomInt();

            if (!pdus.Add(Tuple.Create(rxUeTag, rnti)))
                continue;

            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = rxUeTag,
                RNTI = rnti,
                CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG
                {
                    CRCFLAG = _random.NextDouble() < _crcProbability
                }
            };

            result.Add(pdu);
        }

        return result;
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}] for floats and [{_minIntValue}, {_maxIntValue}] for integers";
    }

    private NFAPI_CRC_INDICATION_PDU_T AllocatePdu()
    {
        if (_memoryPool.TryDequeue(out var pdu))
            return pdu;

        return new NFAPI_CRC_INDICATION_PDU_T();
    }

    public void ReleasePdus(IEnumerable<NFAPI_CRC_INDICATION_PDU_T> pdus)
    {
        foreach (var pdu in pdus)
        {
            _memoryPool.Enqueue(pdu);
        }
    }

    private bool ValidatePdu(NFAPI_CRC_INDICATION_PDU_T pdu)
    {
        return pdu != null &&
               pdu.RX_UE_INFORMATION_TAG >= _minIntValue && pdu.RX_UE_INFORMATION_TAG <= _maxIntValue &&
               pdu.RNTI >= _minIntValue && pdu.RNTI <= _maxIntValue;
    }

    public void ValidateGeneratedPdus(IEnumerable<NFAPI_CRC_INDICATION_PDU_T> pdus)
    {
        foreach (var pdu in pdus)
        {
            if (!ValidatePdu(pdu))
                throw new InvalidOperationException("Invalid PDU detected");
        }
    }
}

public class NFAPI_CRC_INDICATION_PDU_T
{
    public int RX_UE_INFORMATION_TAG { get; set; }
    public int RNTI { get; set; }
    public CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG { get; set; }
}

public class CRC_INDICATION_REL8_TAG
{
    public bool CRCFLAG { get; set; }
}
