    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        free(used_ids);
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        used_ids[i] = generate_unique_id(used_ids, i);
        array[i].RX_UE_INFORMATION_TAG = used_ids[i];
        array[i].RNTI = generate_unique_id(used_ids, i + 1);
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = rand() % 2;

        if (!validate_structure(&array[i])) {
            free(array);
            free(used_ids);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    free(used_ids);
    pthread_mutex_unlock(&lock);
    return array;
}

int* read_integers(size_t *capacity) {
    int *array = malloc(INITIAL_CAPACITY * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for integer array\n");
        return NULL;
    }

    size_t count = 0;
    size_t current_capacity = INITIAL_CAPACITY;

    while (1) {
        if (count >= current_capacity) {
            current_capacity *= 2;
            int *new_array = realloc(array, current_capacity * sizeof(int));
            if (!new_array) {
                free(array);
                fprintf(stderr, "Memory reallocation failed\n");
                return NULL;
            }
            array = new_array;
        }

        int value;
        if (scanf("%d", &value) != 1) break;

        array[count++] = value;
    }

    *capacity = count;
    return array;
}

int find_largest_integer(const int *array, size_t capacity) {
    if (!array || capacity == 0) return -1;

    int largest = array[0];
    for (size_t i = 1; i < capacity; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int main() {
    size_t integer_capacity;
    int *integer_array = read_integers(&integer_capacity);

    if (!integer_array) {
        fprintf(stderr, "Failed to read integers\n");
        return EXIT_FAILURE;
    }

    int largest_integer = find_largest_integer(integer_array, integer_capacity);
    printf("Largest Integer: %d\n", largest_integer);

    free(integer_array);

    size_t n = 10000; // Example value for NFAPI_CRC_INDICATION_PDU_T array size
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_array = allocate_nfaapi_crc_array(n);

    if (!nfaapi_crc_array) {
        fprintf(stderr, "Failed to allocate NFAPI_CRC_INDICATION_PDU_T array\n");
        return EXIT_FAILURE;
    }

    // Use nfaapi_crc_array as needed

    free(nfaapi_crc_array);

    return 0;
}
