    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    LTE_MAC_PDU_T* pdu = NULL;
    if (current) {
        pdu = &current->pdu;
    }

    pthread_mutex_unlock(&list->lock);

    return pdu;
}

void clear_pdu_list(PduList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free_pdu_node(temp);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_pdu_list(PduList** list_ptr) {
    if (!list_ptr || !*list_ptr) return;

    clear_pdu_list(*list_ptr);

