} LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T;

typedef struct {
    LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T **pdu_list;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock; // Read-write lock for thread-safe operations
} PDUListManager;

// Initialize the list manager
void init_pdu_list_manager(PDUListManager *manager, size_t initial_capacity) {
    manager->pdu_list = malloc(initial_capacity * sizeof(LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_rwlock_init(&manager->lock, NULL);
}

// Destroy the list manager and free all associated memory
void destroy_pdu_list_manager(PDUListManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdu_list[i]->user_data_buffer);
        free(manager->pdu_list[i]);
    }
    free(manager->pdu_list);
    pthread_rwlock_unlock(&manager->lock);
    pthread_rwlock_destroy(&manager->lock);
}

// Add a new PDU to the list
void add_pdu(PDUListManager *manager, LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *new_pdu) {
    pthread_rwlock_wrlock(&manager->lock);

    // Ensure capacity is sufficient, double the size if not
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T **new_list = realloc(manager->pdu_list, new_capacity * sizeof(LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *));
        if (!new_list) {
            pthread_rwlock_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->pdu_list = new_list;
        manager->capacity = new_capacity;
    }

    manager->pdu_list[manager->count++] = new_pdu;
    pthread_rwlock_unlock(&manager->lock);
}

// Update an existing PDU in the list
void update_pdu(PDUListManager *manager, int L1_tag, LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *updated_pdu) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->pdu_list[i]->L1_TELEMETRY_INDICATION_TAG == L1_tag) {
            free(manager->pdu_list[i]->user_data_buffer);
            manager->pdu_list[i]->L2_TELEMETRY_INDICATION_TAG = updated_pdu->L2_TELEMETRY_INDICATION_TAG;
            manager->pdu_list[i]->L3_TELEMETRY_INDICATION_TAG = updated_pdu->L3_TELEMETRY_INDICATION_TAG;

            // Reallocate buffer if necessary
            if (updated_pdu->buffer_size > manager->pdu_list[i]->buffer_size) {
                char *new_buffer = realloc(manager->pdu_list[i]->user_data_buffer, updated_pdu->buffer_size);
                if (!new_buffer) {
                    pthread_rwlock_unlock(&manager->lock);
                    return; // Handle memory allocation failure
                }
                manager->pdu_list[i]->user_data_buffer = new_buffer;
            }

            memcpy(manager->pdu_list[i]->user_data_buffer, updated_pdu->user_data_buffer, updated_pdu->buffer_size);
            manager->pdu_list[i]->buffer_size = updated_pdu->buffer_size;

            pthread_rwlock_unlock(&manager->lock);
            return;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

// Clear the list of PDUs
void clear_pdu_list(PDUListManager *manager) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->pdu_list[i]->user_data_buffer);
        free(manager->pdu_list[i]);
    }
    manager->count = 0;

    pthread_rwlock_unlock(&manager->lock);
}

// Create a new PDU with dynamic buffer allocation
LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *create_pdu(int L1_tag, int L2_tag, int L3_tag, size_t user_data_size) {
    LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T *pdu = malloc(sizeof(LTEPHYTLVE_NB1MMEE_NB1MM_PDU_T));
    if (!pdu) return NULL; // Handle memory allocation failure

    pdu->L1_TELEMETRY_INDICATION_TAG = L1_tag;
    pdu->L2_TELEMETRY_INDICATION_TAG = L2_tag;
    pdu->L3_TELEMETRY_INDICATION_TAG = L3_tag;

    size_t buffer_size = (user_data_size > INITIAL_BUFFER_SIZE) ? user_data_size : INITIAL_BUFFER_SIZE;
    pdu->user_data_buffer = malloc(buffer_size);
    if (!pdu->user_data_buffer) {
        free(pdu); // Clean up allocation failure
        return NULL; 
    }
    pdu->buffer_size = buffer_size;

    return pdu;
}
