#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int valid; // Assuming a simple integer flag for simplicity
} RX_UE_INFORMATION_TAG;

typedef unsigned short RNTI_TYPE;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI_TYPE rnti;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_unique(DynamicList* list, RNTI_TYPE rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return 0; // Not unique
        }
        current = current->next;
    }
    return 1; // Unique
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void insert_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.rnti)) {
        log_error("Duplicate RNTI detected. Skipping insertion.");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    if (list->size == MAX_LIST_SIZE) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);

        if (list->head == NULL) {
            list->tail = NULL;
        }
    }

    if (list->tail != NULL) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->tag.valid = 1; // Assuming valid for simplicity
    pdu->rnti = rand() % 65535;
    pdu->crcTag.CRCFLAG = rand() % 2;
}

void manage_list(DynamicList* list, int num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < num_pdus; ++i) {
        generate_random_pdu(&pdu);
        insert_pdu(list, pdu);
    }
}

// Example usage
int main() {
    DynamicList* list = create_list();
    manage_list(list, 10000); // Insert 10,000 PDUs
    destroy_list(list);
    return 0;
}
```

### Design Considerations

- **Efficiency**: The use of a linked list allows for efficient insertion and removal operations. However, checking for unique RNTIs is O(n) in complexity.
- **Usability**: The function provides clear error logging for duplicate RNTIs and handles memory allocation failures gracefully.
- **Maintainability**: The code is modular with functions handling specific tasks, making it easier to maintain and extend.
- **Scalability**: While the current implementation supports up to `MAX_LIST_SIZE` entries, this can be adjusted. For larger datasets, consider using a hash table for RNTI uniqueness checks to improve performance.']

