    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return -1;

    pthread_mutex_lock(&da->mutex);
    da->capacity = new_capacity;
    da->array = temp;
    pthread_mutex_unlock(&da->mutex);

    return 0;
}

// Function to add a structure
int addStructure(DynamicArray *da, unsigned long rnti) {
    pthread_mutex_lock(&da->mutex);

    if (da->count >= da->capacity && resizeDynamicArray(da, da->capacity == 0 ? 1 : da->capacity * 2)) {
