} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000

// Global dynamic list
NFAPI_CRC_INDICATION_PDU_T *dynamic_list = NULL;
size_t current_size = 0;

// Error logging function
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to initialize the dynamic list with a specific size
int init_dynamic_list(size_t initial_size) {
    if (initial_size > MAX_STRUCTURES) {
        initial_size = MAX_STRUCTURES;
    }

    dynamic_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_list) {
        log_error("Memory allocation failed during initialization.");
        return -1;
    }

    current_size = initial_size;
    return 0;
}

// Function to add a new structure
int add_structure(const RX_UE_INFORMATION_TAG *rx_tag, const RNTI *rnti, const CRC_INDICATION_REL8_TAG *crc_rel8_tag) {
    if (current_size >= MAX_STRUCTURES) {
        log_error("Reached maximum capacity of the dynamic list.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu = { .rx_ue_information_tag = *rx_tag, .rnti = *rnti, .crc_indication_rel8_tag = *crc_rel8_tag };

    // Randomly set CRCFLAG
    new_pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2; 

    dynamic_list[current_size++] = new_pdu;
    return 0;
}

// Function to remove a structure based on RNTI
int remove_structure_by_rnti(const RNTI *rnti) {
    for (size_t i = 0; i < current_size; ++i) {
        if (dynamic_list[i].rnti == *rnti) {
            // Shift elements to fill the gap
            memmove(&dynamic_list[i], &dynamic_list[i + 1], (current_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --current_size;
            return 0;
        }
    }

    log_error("RNTI not found.");
    return -1;
}

// Function to verify the integrity of the list
int verify_integrity() {
