typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG[2];
} NFAPI_CRC_INDICATION_PDU_T;

// Cache and configuration structures
#define MAX_CACHE_SIZE 100

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CacheNode *prev, *next;
} CacheNode;

CacheNode *cacheHead = NULL, *cacheTail = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
int maxCacheSize = MAX_CACHE_SIZE; // This would be read from a config file

void loadConfig() {
    FILE *file = fopen("config.txt", "r");
    if (file) {
        fscanf(file, "%d", &maxCacheSize);
        fclose(file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromCache(int rntiRangeMin, int rntiRangeMax) {
    pthread_mutex_lock(&cacheMutex);

    // Check cache for available node
    CacheNode *current = cacheHead;
    while (current != NULL) {
        if (current->data.RNTI >= rntiRangeMin && current->data.RNTI <= rntiRangeMax) {
            // Remove from cache and return
            NFAPI_CRC_INDICATION_PDU_T *result = &current->data;

            if (current == cacheHead)
                cacheHead = current->next;
            if (current == cacheTail)
                cacheTail = current->prev;

            if (cacheHead) cacheHead->prev = current->prev;
            if (cacheTail) cacheTail->next = current->next;

            free(current);
            pthread_mutex_unlock(&cacheMutex);

            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cacheMutex);
    return NULL;
}

void addToCache(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&cacheMutex);

    // Create new cache node
    CacheNode *node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) {
        perror("Failed to allocate memory for cache node");
        pthread_mutex_unlock(&cacheMutex);
        return;
    }
    memcpy(&node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add to tail
    node->prev = NULL;
    node->next = NULL;

    if (cacheTail) {
        cacheTail->next = node;
        node->prev = cacheTail;
    }
    cacheTail = node;

    if (!cacheHead)
        cacheHead = node;

    pthread_mutex_unlock(&cacheMutex);
}

void evictCacheIfNeeded() {
    pthread_mutex_lock(&cacheMutex);

    while (maxCacheSize && (cacheHead != NULL) && (getTotalCacheSize() > maxCacheSize)) {
        // Evict least recently used (head)
        CacheNode *temp = cacheHead;
        if (cacheHead == cacheTail)
            cacheHead = cacheTail = NULL;
        else
            cacheHead = cacheHead->next;

        free(temp);
    }

    pthread_mutex_unlock(&cacheMutex);
}

int getTotalCacheSize() {
    int size = 0;
    CacheNode *current = cacheHead;
    while (current) {
        size++;
        current = current->next;
    }
    return size;
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPDU(int N, int rntiRangeMin, int rntiRangeMax) {
    loadConfig();

    // Array of structures
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array)
        return NULL;

    for (int i = 0; i < N; ++i) {
        array[i] = *(allocateFromCache(rntiRangeMin, rntiRangeMax));

        // If not found in cache, create new
        if (!array[i].RNTI) {
            array[i].RX_UE_INFORMATION_TAG = rand();
            int validRNTI = -1;
            do {
                validRNTI = rntiRangeMin + rand() % (rntiRangeMax - rntiRangeMin + 1);
            } while (!validateRNTI(validRNTI));

            array[i].RNTI = validRNTI;
            array[i].CRC_INDICATION_REL8_TAG = rand();
            sprintf(array[i].CRCFLAG, "%c", (rand() % 2) ? '0' : '1');

            addToCache(&array[i]);
        }

        evictCacheIfNeeded();
    }

    return array;
}

int validateRNTI(int rnti) {
    // Simulate external data source validation
    time_t start = clock();

    // Randomly simulate delay or failure
    if (rand() % 10 < 2)
        return 0; 

    usleep(100000); // simulate network latency

    time_t end = clock();

    printf("RNTI validated: %d\n", rnti);
    printf("Validation took: %.3f ms\n", ((double)(end - start)) / CLOCKS_PER_SEC * 1000);

    return 1;
}
