#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_IDENTIFIER;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_IDENTIFIER ue_identifier;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_POOL_SIZE 100
#define POOL_GROWTH_FACTOR 2

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    FILE* log_file;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->pool = (Node**)calloc(INITIAL_POOL_SIZE, sizeof(Node*));
    if (!list->pool) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_POOL_SIZE;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Open log file
    list->log_file = fopen("dynamic_list_log.txt", "a");
    if (!list->log_file) {
        free(list->pool);
        free(list);
        return NULL;
    }

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (list) {
        for (size_t i = 0; i < list->capacity; ++i) {
            if (list->pool[i]) free(list->pool[i]);
        }
        free(list->pool);
        pthread_mutex_destroy(&list->lock);
        fclose(list->log_file);
        free(list);
    }
}

int find_node(DynamicList* list, UE_IDENTIFIER identifier) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->pool[i] && 
            list->pool[i]->data.ue_identifier.RX_UE_INFORMATION_TAG == identifier.RX_UE_INFORMATION_TAG &&
            list->pool[i]->data.ue_identifier.RNTI == identifier.RNTI) {
            return i;
        }
    }
    return -1;
}

void log_operation(DynamicList* list, const char* operation, double duration) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(list->log_file, "[%s] Operation: %s, Duration: %.6f seconds\n", buffer, operation, duration);
}

void* allocate_node(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    double start_time = (double)clock() / CLOCKS_PER_SEC;

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * POOL_GROWTH_FACTOR;
        Node** new_pool = (Node**)realloc(list->pool, new_capacity * sizeof(Node*));
        if (!new_pool) {
            pthread_mutex_unlock(&list->lock);
            return NULL;
        }
        memset(new_pool + list->capacity, 0, (new_capacity - list->capacity) * sizeof(Node*));
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->capacity; ++i) {
        if (!list->pool[i]) {
            Node* node = (Node*)malloc(sizeof(Node));
            if (!node) {
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            list->pool[i] = node;
            list->size++;

            double end_time = ((double)clock() / CLOCKS_PER_SEC) - start_time;
            log_operation(list, "Allocate Node", end_time);

            pthread_mutex_unlock(&list->lock);
            return &list->pool[i]->data;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_or_add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    double start_time = (double)clock() / CLOCKS_PER_SEC;

    int idx = find_node(list, entry.ue_identifier);
    if (idx != -1) {
        // Update existing node
        list->pool[idx]->data.crc_indication.CRCFLAG = rand() % 2; // Random CRCFLAG for demonstration

        double end_time = ((double)clock() / CLOCKS_PER_SEC) - start_time;
        log_operation(list, "Update Entry", end_time);

    } else {
        void* node_data_ptr = allocate_node(list);
        if (node_data_ptr) {
            NFAPI_CRC_INDICATION_PDU_T* node_data = (NFAPI_CRC_INDICATION_PDU_T*)node_data_ptr;
            *node_data = entry;
            node_data->crc_indication.CRCFLAG = rand() % 2; // Random CRCFLAG for demonstration

            double end_time = ((double)clock() / CLOCKS_PER_SEC) - start_time;
            log_operation(list, "Add Entry", end_time);

        } else {
            fprintf(stderr, "Failed to allocate memory for new entry.\n");
        }
    }
}

void integrate_with_network_interface(DynamicList* list) {
    // Pseudo-function call to illustrate integration with the network interface
    // This would typically involve calling an external function or API provided by the system
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->pool[i]) {
            // Register node with existing network interface management system
            // Example: register_node_with_network(list->pool[i]->data);

            log_operation(list, "Register Node", 0); // No time measurement for pseudo-operation
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize dynamic list.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T sample_entry = { .ue_identifier = {1234, 5678} };

    // Example: Adding and updating entries
    update_or_add_entry(list, sample_entry);
    sample_entry.ue_identifier.RX_UE_INFORMATION_TAG = 4321; // Different UE_IDENTIFIER for a new entry
    update_or_add_entry(list, sample_entry);

    integrate_with_network_interface(list);

    destroy_dynamic_list(list);

    return EXIT_SUCCESS;
}
