#define MAX_MEMORY_USAGE 1048576 // Max memory usage in bytes (e.g., 1MB)
#define RETRY_LIMIT 3

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static size_t total_memory_usage = 0;
static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

size_t get_structure_size() {
    return sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void log_error(const char *message, const char *filename) {
    FILE *file = fopen(filename, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t count, const char *error_log_file) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t structure_size = get_structure_size();
    size_t required_memory = count * structure_size;

    pthread_mutex_lock(&memory_mutex);

    if (total_memory_usage + required_memory > MAX_MEMORY_USAGE) {
        log_error("Insufficient memory for allocation", error_log_file);
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    int retry_count = 0;
    while (retry_count < RETRY_LIMIT) {
        array = malloc(required_memory);
        if (array != NULL) {
            total_memory_usage += required_memory;
            break;
        }
        log_error("Memory allocation failed, retrying...", error_log_file);
        retry_count++;
    }

    pthread_mutex_unlock(&memory_mutex);

    if (array == NULL) {
        log_error("Failed to allocate memory after retries", error_log_file);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 256;
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 65536;
    }

    return array;
}

void deallocate_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t count) {
    if (array != NULL) {
        pthread_mutex_lock(&memory_mutex);
        total_memory_usage -= count * get_structure_size();
        free(array);
        pthread_mutex_unlock(&memory_mutex);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    const char *log_file = "error_log.txt";

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_crc_pdu_array(100, log_file);
    if (pdu_array != NULL) {
        // Use pdu_array for processing...
        deallocate_crc_pdu_array(pdu_array, 100);
    }

    return 0;
}
