    printf("Deallocated: %zu elements\n", count);
}

int is_unique(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *capacity) {
    size_t new_capacity = (*capacity) * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_indication_pdu(size_t num_elements, size_t *allocated_count) {
    pthread_mutex_lock(&lock);

    static NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    static size_t capacity = 0;

    if (!array || (*allocated_count >= capacity)) {
        if (!array) {
            array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_CAPACITY);
            if (!array) {
                perror("Failed to allocate memory");
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            log_allocation(INITIAL_CAPACITY);
            capacity = INITIAL_CAPACITY;
        } else {
            resize_array(&array, &capacity);
            log_allocation(capacity / 2);
        }
    }

    for (size_t i = *allocated_count; i < num_elements && (*allocated_count) < capacity; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        uint16_t rnti;
        do {
            rnti = rand() % UINT16_MAX;
        } while (!is_unique(rnti, array, *allocated_count));
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() & 1;
        (*allocated_count)++;
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void deallocate_crc_indication_pdu(size_t *allocated_count) {
    pthread_mutex_lock(&lock);

    if (array && *allocated_count > 0) {
        free(array);
        log_deallocation(*allocated_count);
        array = NULL;
        capacity = 0;
        *allocated_count = 0;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    size_t allocated_count = 0;
    manage_crc_indication_pdu(10000, &allocated_count);

    // Example usage
    printf("Number of elements allocated: %zu\n", allocated_count);

    deallocate_crc_indication_pdu(&allocated_count);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex` to ensure thread safety.
- **Dynamic Resizing**: Doubles the array size when needed, ensuring memory constraints are respected.
- **Unique RNTI**: Ensures no duplicate `RNTI` values using a simple loop check.
- **Logging**: Provides logging for allocations and deallocations.
- **Graceful Handling**: Uses `realloc` to resize arrays safely and checks for allocation failures.']

