        fprintf(stderr, "Invalid number of packets requested.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NetworkPacket *packets = malloc(num_packets * sizeof(NetworkPacket));
    if (!packets) {
        perror("Failed to allocate memory for NetworkPackets");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char* base_payload_data = fetchDataFromExternalSource();
    size_t payload_length = strlen(base_payload_data);

    for (int i = 0; i < num_packets; ++i) {
        packets[i].header.sequence_number = i + 1;

        // Allocate and copy PayloadData
        packets[i].payload.data = malloc(payload_length);
        if (!packets[i].payload.data) {
            perror("Failed to allocate memory for PayloadData");
            while (--i >= 0) free(packets[i].payload.data); // Free allocated payloads
            free(packets);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        strncpy(packets[i].payload.data, base_payload_data, payload_length);
        packets[i].payload.length = payload_length;
    }

    pthread_mutex_unlock(&lock);

    return packets;
}

// Example usage
