    int num_packets = 5; // User-specified number of packets

    NetworkPacket* packets = initializeNetworkPackets(num_packets);

    if (packets) {
        for (int i = 0; i < num_packets; ++i) {
            printf("Packet %d: Sequence Number: %d, Payload Data: %s\n",
                   i + 1, packets[i].header.sequence_number, packets[i].payload.data);

            free(packets[i].payload.data); // Free dynamically allocated payload data
        }

        free(packets); // Free the array of NetworkPackets
    }

    return 0;
}
