int resolve_hostname_to_ip(const char* hostname, u_char *ip_array) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        struct addrinfo hints, *res, *p;
        int status;
        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_INET; // IPv4
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
            retries++;
            sleep(DNS_TIMEOUT);
            continue;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            struct sockaddr_in *h = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &(h->sin_addr), ip_array, INET_ADDRSTRLEN);
            freeaddrinfo(res);
            return 0;
        }
    }
    fprintf(stderr, "Failed to resolve hostname after %d retries.\n", MAX_RETRIES);
    return -1;
}

