```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // Example maximum memory in bytes
#define DEFAULT_MAX_STRUCTURES 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t count;
    size_t max_structures;
} StructureList;

// Mock external library function for CRC calculations
int external_crc_calculation() {
    return rand() % 2; // Randomly returns 0 or 1 for demonstration
}

void log_memory_usage(size_t used_bytes) {
    printf("Memory usage: %.2f KB\n", used_bytes / 1024.0);
}

void adjust_probability(float* probability, float adjustment_factor) {
    if (*probability < 0) *probability = 0;
    if (*probability > 1) *probability = 1;
    *probability *= adjustment_factor;
}

size_t calculate_max_structures(size_t max_memory) {
    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return (max_memory / structure_size);
}

int create_nfa_crc_indications(float crc_flag_probability, float probability_adjustment,
                               size_t max_structures, StructureList* list) {
    if (crc_flag_probability < 0 || crc_flag_probability > 1) {
        fprintf(stderr, "Invalid CRC flag probability. Adjusting to valid range.\n");
        adjust_probability(&crc_flag_probability, 1);
    }

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t available_structures = calculate_max_structures(MAX_MEMORY);

    if (max_structures > DEFAULT_MAX_STRUCTURES) {
        max_structures = DEFAULT_MAX_STRUCTURES;
    }

    list->max_structures = available_structures < max_structures ? available_structures : max_structures;
    if (list->max_structures == 0) {
        fprintf(stderr, "Max structures is set to zero or insufficient memory.\n");
        return -1;
    }

    size_t total_memory_needed = list->max_structures * structure_size;
    if (total_memory_needed > MAX_MEMORY) {
        fprintf(stderr, "Insufficient memory for even one structure.\n");
        return -2;
    }

    list->structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory_needed);
    if (!list->structures) {
        perror("Failed to allocate memory for structures");
        return -3;
    }
    list->count = 0;

    srand(time(NULL));

    for (size_t i = 0; i < list->max_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->structures[i];
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();

        // Use external library and adjust CRCFLAG based on probability
        int crc_result = external_crc_calculation();
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() / (float)RAND_MAX < crc_flag_probability || crc_result);

        list->count++;
    }

    log_memory_usage(total_memory_needed);
    return 0;
}

void free_structure_list(StructureList* list) {
    if (list && list->structures) {
        free(list->structures);
        list->structures = NULL;
        list->count = 0;
    }
}

int main() {
    StructureList list;
    float crc_flag_probability = 0.5; // Initial probability
    float probability_adjustment = 1.01; // Example adjustment factor

    int result = create_nfa_crc_indications(crc_flag_probability, probability_adjustment,
                                            DEFAULT_MAX_STRUCTURES, &list);

    if (result == 0) {
        printf("Successfully created %zu structures.\n", list.count);
    } else {
        fprintf(stderr, "Error creating structures: %d\n", result);
