#include <stdio.h>
#include <stdlib.h>
import threading
from time import sleep, monotonic

// Define network interface statistics structure
typedef struct {
    int packet_count;
    float error_rate;
    double timestamp; // For simplicity, using POSIX timestamps
} NetworkStats;

// Define list node structure for linked list
typedef struct Node {
    NetworkStats stats;
    struct Node* next;
} Node;

// Global head pointer for the list of network statistics
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function to create a new node with given stats
Node* create_node(NetworkStats ns) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->stats = ns;
    new_node->next = NULL;
    return new_node;
}

// Add node to the list
void add_stats_to_list(NetworkStats ns) {
    pthread_mutex_lock(&lock);

    Node* new_node = create_node(ns);
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Append to the end of the list
    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&lock);
}

// Simulated API call to retrieve network statistics
NetworkStats get_network_stats() {
    // Placeholder for actual API call logic
    NetworkStats ns;
    ns.packet_count = rand() % 1000; // Random packet count
    ns.error_rate = (float)rand() / RAND_MAX * 5.0; // Random error rate up to 5%
    ns.timestamp = monotonic(); // Current time
    return ns;
}

// Update network statistics periodically
void update_network_stats_periodically(int interval_seconds) {
    while (1) {
        NetworkStats ns = get_network_stats();

        add_stats_to_list(ns);

        // Log operational metrics for debugging purposes
        printf("Updated stats at timestamp: %.2f\n", ns.timestamp);

        sleep(interval_seconds);
    }
}

// Function to detect anomalies and trigger alerts
void detect_anomalies_and_alert() {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        if (temp->stats.packet_count > 900 || temp->stats.error_rate > 3.0) {
            printf("Alert: Anomaly detected in network interface\n");
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

// Thread function to periodically detect anomalies
void* anomaly_detection_thread(void* arg) {
    while (1) {
        detect_anomalies_and_alert();
        sleep(5); // Check every 5 seconds for this example
    }
}

int main() {
    int update_interval = 2; // Example interval of 2 seconds

    pthread_t update_thread, anomaly_thread;

    pthread_create(&update_thread, NULL, (void*)update_network_stats_periodically, (void*)&update_interval);
    pthread_create(&anomaly_thread, NULL, anomaly_detection_thread, NULL);

    pthread_join(update_thread, NULL);
    pthread_join(anomaly_thread, NULL);

    return 0;
}
```

