#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint64_t timestamp;
    size_t packet_size;
    int processing_status;
    char unique_id[16]; // Unique identifier for each packet
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} PacketArray;

PacketArray* create_packet_array() {
    PacketArray* array = (PacketArray*)malloc(sizeof(PacketArray));
    if (!array) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    return array;
}

void destroy_packet_array(PacketArray* array) {
    if (!array) return;
    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int insert_packet(PacketArray* array, DataPacket packet) {
    if (!array || !packet.unique_id) return -1;

    pthread_mutex_lock(&array->lock);

    Node** ptr = &array->head;
    while (*ptr) {
        Node* node = *ptr;
        if (strcmp(node->packet.unique_id, packet.unique_id) == 0) {
            // Update existing packet
            node->packet.timestamp = packet.timestamp;
            node->packet.packet_size = packet.packet_size;
            node->packet.processing_status = packet.processing_status;
            pthread_mutex_unlock(&array->lock);
            return 1; // Updated
        }
        ptr = &node->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Allocation failure
    }
    memcpy(&new_node->packet, &packet, sizeof(DataPacket));
    new_node->next = NULL;
    *ptr = new_node;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0; // Inserted
}

int remove_packet(PacketArray* array, const char* unique_id) {
    if (!array || !unique_id) return -1;

    pthread_mutex_lock(&array->lock);

    Node** ptr = &array->head;
    while (*ptr) {
        Node* node = *ptr;
        if (strcmp(node->packet.unique_id, unique_id) == 0) {
            *ptr = node->next;
            free(node);
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0; // Removed
        }
        ptr = &node->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Not found
}

DataPacket* find_packet(PacketArray* array, const char* unique_id) {
    if (!array || !unique_id) return NULL;

    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        if (strcmp(current->packet.unique_id, unique_id) == 0) {
            pthread_mutex_unlock(&array->lock);
            return &current->packet;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL; // Not found
}

size_t get_packet_count(PacketArray* array) {
    if (!array) return (size_t)-1;

    pthread_mutex_lock(&array->lock);

    size_t count = array->count;

    pthread_mutex_unlock(&array->lock);
    return count;
}

void monitor_performance(PacketArray* array, void (*callback)(size_t count)) {
    if (!array || !callback) return;

    pthread_mutex_lock(&array->lock);

    callback(array->count);

    pthread_mutex_unlock(&array->lock);
}
```

