```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    size_t packet_size;
    int processing_status;
    char source_ip[16];
    char destination_ip[16];
    uint16_t source_port;
    uint16_t dest_port;
    unsigned qos_settings; // Example metadata
} DataPacket;

typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode* next;
    int id; // Unique identifier for the packet
} PacketNode;

typedef struct {
    PacketNode** packets;
    size_t capacity;
    pthread_rwlock_t lock;
} DynamicPacketArray;

DynamicPacketArray* create_dynamic_packet_array(size_t initial_capacity) {
    DynamicPacketArray* array = (DynamicPacketArray*)malloc(sizeof(DynamicPacketArray));
    array->packets = (PacketNode**)calloc(initial_capacity, sizeof(PacketNode*));
    array->capacity = initial_capacity;
    pthread_rwlock_init(&array->lock, NULL);
    return array;
}

void free_dynamic_packet_array(DynamicPacketArray* array) {
    for (size_t i = 0; i < array->capacity; ++i) {
        PacketNode* node = array->packets[i];
        while (node != NULL) {
            PacketNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(array->packets);
    pthread_rwlock_destroy(&array->lock);
    free(array);
}

size_t hash_function(const DataPacket* packet) {
    // Simple hash function based on IP addresses and ports
    return ((hash_string(packet->source_ip) ^ hash_string(packet->destination_ip)) 
            ^ (packet->source_port ^ packet->dest_port));
}

int hash_string(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return (int)hash;
}

void resize_array_if_needed(DynamicPacketArray* array);

void insert_packet(DynamicPacketArray* array, DataPacket packet, int id) {
    pthread_rwlock_wrlock(&array->lock);
    size_t index = hash_function(&packet) % array->capacity;

    // Check for duplicates
    PacketNode* node = array->packets[index];
    while (node != NULL) {
        if (strcmp(node->packet.source_ip, packet.source_ip) == 0 &&
            strcmp(node->packet.destination_ip, packet.destination_ip) == 0 &&
            node->packet.source_port == packet.source_port &&
            node->packet.dest_port == packet.dest_port &&
            node->packet.packet_size == packet.packet_size) {
            // Duplicate found
            pthread_rwlock_unlock(&array->lock);
            return;
        }
        node = node->next;
    }

    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    memcpy(&new_node->packet, &packet, sizeof(DataPacket));
    new_node->id = id;
    new_node->next = array->packets[index];
    array->packets[index] = new_node;

    resize_array_if_needed(array);

    pthread_rwlock_unlock(&array->lock);
}

void remove_packet(DynamicPacketArray* array, int id) {
    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->capacity; ++i) {
        PacketNode **current = &array->packets[i], *temp;
        while (*current != NULL) {
            if ((*current)->id == id) {
                temp = *current;
                *current = (*current)->next;
                free(temp);
                break;
            }
            current = &(*current)->next;
        }
    }

    pthread_rwlock_unlock(&array->lock);
}

void update_packet(DynamicPacketArray* array, int id, DataPacket packet) {
    pthread_rwlock_wrlock(&array->lock);

    for (size_t i = 0; i < array->capacity; ++i) {
        PacketNode* node = array->packets[i];
        while (node != NULL) {
            if (node->id == id) {
                memcpy(&node->packet, &packet, sizeof(DataPacket));
                break;
            }
            node = node->next;
        }
    }

    pthread_rwlock_unlock(&array->lock);
}

void resize_array_if_needed(DynamicPacketArray* array) {
    // Example logic for resizing the hash table
    size_t new_capacity = array->capacity * 2;
    PacketNode** new_packets = (PacketNode**)calloc(new_capacity, sizeof(PacketNode*));

    for (size_t i = 0; i < array->capacity; ++i) {
        PacketNode* node = array->packets[i];
        while (node != NULL) {
            PacketNode* next_node = node->next;
            size_t new_index = hash_function(&node->packet) % new_capacity;

            node->next = new_packets[new_index];
            new_packets[new_index] = node;
            node = next_node;
        }
    }

    free(array->packets);
    array->packets = new_packets;
    array->capacity = new_capacity;
}

// Performance Monitoring (Simple Example)
void monitor_performance(DynamicPacketArray* array) {
    pthread_rwlock_rdlock(&array->lock);

    size_t used_slots = 0;
    for (size_t i = 0; i < array->capacity; ++i) {
        if (array->packets[i] != NULL) {
            used_slots++;
        }
    }

    double load_factor = (double)used_slots / array->capacity;

    printf("Load Factor: %.2f\n", load_factor);

    pthread_rwlock_unlock(&array->lock);
}

int main() {
    DynamicPacketArray* packet_array = create_dynamic_packet_array(16);

    DataPacket sample_packet = { .timestamp = 123456789, .packet_size = 1500,
                                 .processing_status = 1, .source_ip = "192.168.1.1",
                                 .destination_ip = "192.168.1.2", .source_port = 80,
                                 .dest_port = 8080, .qos_settings = 5 };

    insert_packet(packet_array, sample_packet, 1);
    monitor_performance(packet_array);

    free_dynamic_packet_array(packet_array);
    return 0;
}
