#include <stdatomic.h>

#define MAX_PACKETS 1000
#define MAX_MEMORY_USAGE 1048576 // 1 MB
#define INT_KEY_MAX_SIZE 256
#define CHAR_BUFFER_MAX_TOTAL_SIZE 8192
#define RECORD_COUNT 100
#define MAX_INT_VALUE_SUM 5000

typedef struct {
