} Record;

typedef struct {
    pthread_mutex_t mutex;
    size_t current_size;
    size_t max_size;
    DataPacket *packets;
    atomic_size_t total_memory_used;
} DynamicArrayManager;

// Function prototypes
void init_manager(DynamicArrayManager *manager);
int add_or_update_packet(DynamicArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T packet_info, uint64_t timestamp, size_t packet_size);
int remove_duplicate_packets(DynamicArrayManager *manager);
Record *init_records(int count, int max_value_sum, size_t max_buffer_total_size);
void free_records(Record *records, int count);

// Initialize the dynamic array manager
void init_manager(DynamicArrayManager *manager) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->current_size = 0;
    manager->max_size = MAX_PACKETS;
    manager->packets = malloc(sizeof(DataPacket) * manager->max_size);
    atomic_store(&manager->total_memory_used, sizeof(DynamicArrayManager));
    if (manager->packets == NULL) {
        fprintf(stderr, "Failed to allocate memory for packets\n");
    }
}

// Add or update a packet in the dynamic array
int add_or_update_packet(DynamicArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T packet_info, uint64_t timestamp, size_t packet_size) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->current_size; ++i) {
        if (/* condition to identify duplicate */) {
            manager->packets[i].timestamp = timestamp;
            manager->packets[i].packet_size = packet_size;
            pthread_mutex_unlock(&manager->mutex);
            return 0; // Packet updated
        }
    }

    if (manager->current_size < manager->max_size) {
        manager->packets[manager->current_size++] = (DataPacket){timestamp, packet_size, 0};
        pthread_mutex_unlock(&manager->mutex);
        return 1; // New packet added
    } else {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Array full
    }
}

// Remove duplicate packets from the array
int remove_duplicate_packets(DynamicArrayManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    size_t unique_count = 0;
    for (size_t i = 0; i < manager->current_size; ++i) {
        int is_duplicate = 0;
        for (size_t j = 0; j < unique_count; ++j) {
            if (/* condition to identify duplicate */) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            manager->packets[unique_count++] = manager->packets[i];
        }
    }

    manager->current_size = unique_count;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Initialize records with random values and buffers
Record *init_records(int count, int max_value_sum, size_t max_buffer_total_size) {
    Record *records = malloc(sizeof(Record) * count);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    int remaining_sum = max_value_sum;
    size_t total_allocated_size = 0;

    for (int i = 0; i < count; ++i) {
        int value = rand() % (remaining_sum + 1);
        if (value > remaining_sum) {
            value = remaining_sum;
        }
        remaining_sum -= value;

        records[i].key = value;
        size_t buffer_size = (rand() % INT_KEY_MAX_SIZE) + 1;
        if (total_allocated_size + buffer_size > max_buffer_total_size) {
            buffer_size = max_buffer_total_size - total_allocated_size;
        }

        records[i].buffer = malloc(buffer_size);
        if (records[i].buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for record buffer\n");
            free_records(records, i);
            return NULL;
        }
        total_allocated_size += buffer_size;
    }

    return records;
}

// Free allocated records
void free_records(Record *records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
