#include <string.h>
#include <pthread.h>

typedef struct {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRCArrayManager;

CRCArrayManager* create_crc_array_manager(size_t initial_capacity) {
    CRCArrayManager *manager = (CRCArrayManager*)malloc(sizeof(CRCArrayManager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_crc_array_manager(CRCArrayManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}

int resize_array_if_needed(CRCArrayManager *manager) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return -1;

        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    return 0;
}

int add_element(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (resize_array_if_needed(manager) != 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->array[manager->size++] = element;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_element(CRCArrayManager *manager, size_t index) {
    if (index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    memmove(&manager->array[index], &manager->array[index + 1], (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_element(CRCArrayManager *manager, size_t index, NFAPI_CRC_INDICATION_PDU_T new_value) {
    if (index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    manager->array[index] = new_value;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void compress_array(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size < 2) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    size_t write_index = 0;
    for (size_t i = 0; i < manager->size - 1; ++i) {
        manager->array[write_index++] = manager->array[i];
        while (i + 1 < manager->size && manager->array[i].RNTI == manager->array[i + 1].RNTI) {
            i++;
        }
    }

    if (write_index < manager->size) {
        manager->array[write_index] = manager->array[manager->size - 1];
    }

    manager->size = write_index + 1;

    pthread_mutex_unlock(&manager->lock);
}

void print_crc_array(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        printf("RNTI: %d\n", manager->array[i].RNTI);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    CRCArrayManager *manager = create_crc_array_manager(4);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {101};
    add_element(manager, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {102};
    add_element(manager, pdu2);

    NFAPI_CRC_INDICATION_PDU_T pdu3 = {101}; // Duplicate RNTI
    add_element(manager, pdu3);

    compress_array(manager);
    print_crc_array(manager);

    destroy_crc_array_manager(manager);
    return 0;
}
