#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

// Definitions for NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint8_t rnti;
    uint16_t rx_ue_information_tag;
    uint8_t crc_indication_rel8_tag;
    _Atomic int crcflag;  // Atomic variable for thread-safe CRCFLAG updates
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t element_size;
    void* free_list_head;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool crc_pdu_pool = {0};

// Function to initialize the memory pool
void init_memory_pool(size_t num_elements, size_t element_size) {
    // Calculate total pool size and allocate memory
    size_t total_size = num_elements * element_size;
    void* pool_memory = malloc(total_size);

    if (!pool_memory) {
        perror("Failed to allocate memory for the pool");
        exit(EXIT_FAILURE);
    }

    crc_pdu_pool.element_size = element_size;
    crc_pdu_pool.free_list_head = pool_memory;

    // Initialize free list
    uint8_t* current_free = (uint8_t*)pool_memory;
    for (size_t i = 0; i < num_elements - 1; ++i) {
        *(void**)current_free = (void*)(current_free + element_size);
        current_free += element_size;
    }
    *(void**)current_free = NULL;

    pthread_mutex_init(&crc_pdu_pool.lock, NULL);
}

// Function to allocate an NFAPI_CRC_INDICATION_PDU_T from the pool
NFAPI_CRC_INDICATION_PDU_T* alloc_nfa_crc_indication_pdu() {
    pthread_mutex_lock(&crc_pdu_pool.lock);

    void* element = crc_pdu_pool.free_list_head;
    if (!element) {
        pthread_mutex_unlock(&crc_pdu_pool.lock);
        return NULL; // Pool is exhausted
    }

    crc_pdu_pool.free_list_head = *(void**)element;

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)element;
    pthread_mutex_unlock(&crc_pdu_pool.lock);

    return pdu;
}

// Function to free an NFAPI_CRC_INDICATION_PDU_T back to the pool
void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    pthread_mutex_lock(&crc_pdu_pool.lock);
    *(void**)pdu = crc_pdu_pool.free_list_head;
    crc_pdu_pool.free_list_head = (uint8_t*)pdu;
    pthread_mutex_unlock(&crc_pdu_pool.lock);
}

// Function to populate and create a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_pdus(size_t num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory for PDU list");
        return NULL;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = alloc_nfa_crc_indication_pdu();
        if (!pdu) {
            perror("Failed to allocate memory from pool for PDU");
            free(pdu_list);
            return NULL;
        }

        // Populate the structure with random values
        pdu->rnti = rand() % 65536;              // Example RNTI value
        pdu->rx_ue_information_tag = rand();     // Example RX_UE_INFORMATION_TAG value
        pdu->crc_indication_rel8_tag = rand() & 0xFF; // Example CRC_INDICATION_REL8_TAG

        atomic_store(&pdu->crcflag, rand() % 2); // Randomly set CRCFLAG (0 or 1)

        pdu_list[i] = *pdu;
    }

    return pdu_list;
}

// Function to free the list of NFAPI_CRC_INDICATION_PDU_T structures
void destroy_nfa_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t num_pdus) {
    if (!pdu_list) return;

    for (size_t i = 0; i < num_pdus; ++i) {
        free_nfa_crc_indication_pdu(&pdu_list[i]);
    }

    free(pdu_list);
}

// Main function to demonstrate usage
int main() {
    const size_t pool_size = 100;
    init_memory_pool(pool_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    size_t num_pdus = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_nfa_crc_indication_pdus(num_pdus);

    if (pdu_list) {
        // Use the pdu_list as needed...

        destroy_nfa_crc_indication_pdus(pdu_list, num_pdus);
    }

    return 0;
}
