    pool->head = NULL;
    for (size_t i = 0; i < initial_size; ++i) {
        MemoryPoolNode* node = malloc(sizeof(MemoryPoolNode));
        if (!node) { perror("Failed to allocate memory"); exit(EXIT_FAILURE); }
        node->next = pool->head;
        pool->head = node;
    }
    pthread_mutex_init(&pool->lock, NULL);
    pool->pool_size = initial_size;
}

MemoryPoolNode* get_node_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->head == NULL) {
        size_t new_size = pool->pool_size * GROWTH_FACTOR;
        for (size_t i = 0; i < new_size; ++i) {
            MemoryPoolNode* node = malloc(sizeof(MemoryPoolNode));
            if (!node) { perror("Failed to allocate memory"); exit(EXIT_FAILURE); }
            node->next = pool->head;
            pool->head = node;
        }
        pool->pool_size *= GROWTH_FACTOR;
    }
    MemoryPoolNode* node = pool->head;
    pool->head = node->next;
    pthread_mutex_unlock(&pool->lock);
    return node;
}

void free_node_to_pool(MemoryPool* pool, MemoryPoolNode* node) {
    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);
