#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_PDU 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PDU_Manager;

PDU_Manager* initialize_pdu_manager(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_PDU) {
        return NULL; // Handle invalid input
    }

    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->pdus = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        free(manager);
        return NULL; // Handle allocation failure
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);

    srand((unsigned int)time(NULL)); // Seed for random number generation

    return manager;
}

int add_pdu(PDU_Manager *manager, uint32_t rx_tag, uint16_t rnti) {
    if (!manager || manager->count >= manager->capacity) {
        return -1; // Handle invalid input or capacity issue
    }

    pthread_mutex_lock(&manager->mutex);

    size_t index = manager->count++;
    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[index];
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void resize_pdu_manager(PDU_Manager *manager, size_t new_capacity) {
    if (!manager || new_capacity < manager->count || new_capacity > MAX_PDU) {
        return; // Handle invalid input or capacity overflow
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) return;

    pthread_mutex_lock(&manager->mutex);

    manager->pdus = new_pdus;
    manager->capacity = new_capacity;

    pthread_mutex_unlock(&manager->mutex);
}

void free_pdu_manager(PDU_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->pdus);
        free(manager);
    }
}
