import threading

typedef struct {
    unsigned int ue_id;
    unsigned short tac;
    unsigned char mci_tag;
    unsigned char last_cell_update_flag;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->array = malloc(initial_capacity * sizeof(LTE_UE_Context));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);

    if (!da || !da->array) {
        free(da);
        return NULL;
    }
    return da;
}

int resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    LTE_UE_Context *new_array = realloc(da->array, new_capacity * sizeof(LTE_UE_Context));

    if (!new_array) return -1;

    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_ue_context(DynamicArray *da, LTE_UE_Context ue_context) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity && resize_dynamic_array(da) != 0) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Memory allocation failure
    }

    da->array[da->size++] = ue_context;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int remove_ue_context(DynamicArray *da, unsigned int ue_id) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].ue_id == ue_id) {
            for (size_t j = i; j < da->size - 1; ++j) {
                da->array[j] = da->array[j + 1];
            }
            --da->size;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return -1; // UE not found
}

void iterate_ue_contexts(DynamicArray *da, void (*func)(LTE_UE_Context*)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        func(&(da->array[i]));
    }

    pthread_mutex_unlock(&da->lock);
}

void destroy_dynamic_array(DynamicArray *da) {
    if (!da) return;

    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}
```

