    NFAPI_CRC_INDICATION_PDU_T pdu = {ue_id, rnti, (ue_id % 2) ? 1 : 0};
    arr->array[arr->used++] = pdu;

    pthread_mutex_unlock(&arr->lock);
    arr->success_ops++;
    printf("Added PDU for UE ID: %u\n", ue_id);
    return 1;
}

int remove_crc_pdu(CRCArray *arr, unsigned int ue_id) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->used; i++) {
        if (arr->array[i].ue_id == ue_id) {
            memmove(&arr->array[i], &arr->array[i + 1], (arr->used - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            arr->used--;
            pthread_mutex_unlock(&arr->lock);
            arr->success_ops++;
            printf("Removed PDU for UE ID: %u\n", ue_id);
            return 1;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    arr->failed_ops++;
    printf("Failed to remove: UE ID not found\n");
    return 0;
}

void iterate_crc_pdu(CRCArray *arr, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->used; i++) {
