    pthread_mutex_lock(&lock);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand((unsigned int)time(NULL));  // Seed random number generator

    uint16_t rnti_values[N];
    for (size_t i = 0; i < N; ++i) {
        rnti_values[i] = i + 1;  // RNTI values from 1 to N
    }

    // Shuffle RNTI values to ensure randomness without duplicates
    for (size_t i = 0; i < N - 1; ++i) {
        size_t j = i + rand() / (RAND_MAX / (N - i) + 1);
        uint16_t temp = rnti_values[i];
        rnti_values[i] = rnti_values[j];
        rnti_values[j] = temp;
    }

    // Initialize the array
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();  // Unique identifier
        array[i].RNTI = rnti_values[i];
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & RANDOM_CRC_FLAG_PATTERN;
    }

    pthread_mutex_unlock(&lock);

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (!array) return;

    // Ensure thread-safe deallocation
    pthread_mutex_lock(&lock);
    free(array);
    pthread_mutex_unlock(&lock);
}
