    DynamicConnectionArray *array = malloc(sizeof(DynamicConnectionArray));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->count = 0;
    array->connections = malloc(initial_capacity * sizeof(ConnectionMetadata));

    if (!array->connections) {
        free(array);
        return NULL;
    }

    memset(array->connections, 0, initial_capacity * sizeof(ConnectionMetadata));
    return array;
}

void resize_connection_array(DynamicConnectionArray *array, size_t new_capacity) {
    ConnectionMetadata *new_connections = realloc(array->connections,
                                                  new_capacity * sizeof(ConnectionMetadata));

    if (!new_connections) return; // Handle failure silently for now

    memset(new_connections + array->capacity, 0, 
           (new_capacity - array->capacity) * sizeof(ConnectionMetadata));

    array->connections = new_connections;
    array->capacity = new_capacity;
}

int add_connection(DynamicConnectionArray *array, int socket_fd, const char *peer_ip,
                   ConnectionState state, time_t last_activity, double current_throughput) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity > 0 ? array->capacity * 2 : 4;
        resize_connection_array(array, new_capacity);
        if (array->connections == NULL) return -1; // Allocation failed
    }

    ConnectionMetadata *conn = &array->connections[array->count++];
    conn->socket_fd = socket_fd;
    strncpy(conn->peer_ip, peer_ip, INET_ADDRSTRLEN);
    conn->state = state;
    conn->last_activity = last_activity;
    conn->current_throughput = current_throughput;

    return 0; // Success
}

int update_connection(DynamicConnectionArray *array, int index,
                      ConnectionState state, time_t last_activity, double current_throughput) {
    if (index < 0 || index >= array->count) return -1; // Invalid index

    ConnectionMetadata *conn = &array->connections[index];
    conn->state = state;
    conn->last_activity = last_activity;
    conn->current_throughput = current_throughput;

    return 0; // Success
}

void iterate_connections(const DynamicConnectionArray *array, void (*callback)(const ConnectionMetadata*)) {
    for (size_t i = 0; i < array->count; ++i) {
        callback(&array->connections[i]);
    }
}

void free_connection_array(DynamicConnectionArray *array) {
    if (!array) return;

    free(array->connections);
    array->connections = NULL;
    free(array);
}
