typedef struct Node {
    char *key;
    int *int_array;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T nfa_api_crc_indication_pdu;
    pthread_mutex_t lock;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t node_count;
    pthread_mutex_t global_lock;
} NodeList;

NodeList* create_node_list() {
    NodeList *list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) return NULL;
    list->head = NULL;
    list->node_count = 0;
    pthread_mutex_init(&list->global_lock, NULL);
    return list;
}

int is_valid_crc(unsigned int crc_flag) {
    // Implement your CRC validation logic here
    return crc_flag % 2 == 0; // Example: valid if even
}

Node* create_node(const char *key, const int *array, size_t count) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = strdup(key);
    if (!node->key) {
        free(node);
        return NULL;
    }

    node->int_array = malloc(count * sizeof(int));
    if (!node->int_array) {
        free(node->key);
        free(node);
        return NULL;
    }
    memcpy(node->int_array, array, count * sizeof(int));

    node->count = count;

    // Initialize NFAPI_CRC_INDICATION_PDU_T
    node->nfa_api_crc_indication_pdu.RX_UE_INFORMATION_TAG = rand(); // Placeholder
    node->nfa_api_crc_indication_pdu.RNTI = 0; // To be set later

    unsigned int crc_flag;
    do {
        crc_flag = rand();
    } while (!is_valid_crc(crc_flag));
    node->nfa_api_crc_indication_pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;

    pthread_mutex_init(&node->lock, NULL);
    node->next = NULL;
    return node;
}

int add_node(NodeList *list, const char *key, const int *array, size_t count) {
    if (!list || !key || !array) return -1;

    pthread_mutex_lock(&list->global_lock);

    // Check for duplicate key
    Node *current = list->head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&current->lock);
            pthread_mutex_unlock(&list->global_lock);
            return -2; // Duplicate key
        }
        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }

    Node *new_node = create_node(key, array, count);
    if (!new_node) {
        pthread_mutex_unlock(&list->global_lock);
        return -3; // Memory allocation failed
    }

    new_node->nfa_api_crc_indication_pdu.RNTI = list->node_count + 1;

    // Insert at head for simplicity
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->global_lock);
    return 0; // Success
}

void free_node(Node *node) {
    if (!node) return;

    pthread_mutex_destroy(&node->lock);

    free(node->key);
    free(node->int_array);
    free(node);
}

void free_node_list(NodeList *list) {
    if (!list) return;

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }

    pthread_mutex_destroy(&list->global_lock);
    free(list);
}

int main() {
    srand(time(NULL));

    NodeList *node_list = create_node_list();
    if (!node_list) {
        fprintf(stderr, "Failed to create node list\n");
        return -1;
    }

    int array[] = {1, 2, 3};
    if (add_node(node_list, "key1", array, 3) != 0) {
        fprintf(stderr, "Failed to add node\n");
    }

    // Add more nodes and perform operations...

    free_node_list(node_list);
    return 0;
}
