// Initializes the list with a given memory footprint threshold (in bytes)
void initNFALIST(NFALIST *list, size_t mem_threshold) {
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list->capacity = mem_threshold / element_size;
    if (list->capacity > MAX_ELEMENTS) {
        list->capacity = MAX_ELEMENTS;
    }

    list->elements = malloc(list->capacity * element_size);
    if (!list->elements) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Frees the resources used by the NFALIST
void freeNFALIST(NFALIST *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

// Adds a new element to the list if not full and RNTI is valid
bool addElement(NFALIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (element.RNTI <= 0 || list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    // Randomly set the CRCFLAG
    element.CRCFLAG = rand() % 2;

    // Add the new element to the list
    list->elements[list->count++] = element;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Retrieves an element by index
bool getElementByIndex(NFALIST *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (index >= list->count) {
        return false;
    }

    pthread_mutex_lock(&list->lock);
    *element = list->elements[index];
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Removes an element by RNTI
bool removeElementByRNTI(NFALIST *list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i].RNTI == rnti) {
            // Shift elements down to fill the gap
            for (size_t j = i; j < list->count - 1; ++j) {
                list->elements[j] = list->elements[j + 1];
            }
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return false;
}

// Example usage
int main() {
    NFALIST nfaList;

    // Initialize with a memory threshold (example: 1 MB)
    initNFALIST(&nfaList, 1024 * 1024);

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 12345, .RNTI = 67890 };
    if (addElement(&nfaList, pdu)) {
