unsigned int hash_function(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // A simple hash function for demonstration purposes
    unsigned int hash = 0;
    hash ^= (pdu->RX_UE_INFORMATION_TAG * 2654435761u);
    hash ^= (pdu->RNTI * 374761393u);
    for (int i = 0; i < 4; ++i) {
        hash ^= (pdu->CRC_INDICATION_REL8_TAG[i] * 10395331u);
    }
    return hash;
}

void initialize_list(CRCList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

