#define MAX_STRUCTURES 5000

typedef struct {
    char *ENB_UE_SCTP_PEER;
    char *MME_HOST_NAME;
    int MME_PORT;
} LTE_ENBCONTEXT;

typedef struct {
    LTE_ENBCONTEXT *contexts[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
} DynamicArrayManager;

int allocate_memory(char **pointer, size_t size) {
    *pointer = (char *)malloc(size);
    if (*pointer == NULL) {
        perror("Memory allocation failed");
        return -1;
    }
    memset(*pointer, 0, size);
    return 0;
}

DynamicArrayManager* initialize_manager() {
    DynamicArrayManager *manager = (DynamicArrayManager *)malloc(sizeof(DynamicArrayManager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for manager\n");
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        manager->contexts[i] = NULL;
    }
    return manager;
}

int add_context(DynamicArrayManager *manager, const char *ENB_UE_SCTP_PEER, 
                const char *MME_HOST_NAME, int MME_PORT) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_STRUCTURES) {
        fprintf(stderr, "Maximum number of structures reached\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    LTE_ENBCONTEXT *context = (LTE_ENBCONTEXT *)malloc(sizeof(LTE_ENBCONTEXT));
    if (!context) {
        perror("Failed to allocate memory for context");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (allocate_memory((char **)&context->ENB_UE_SCTP_PEER, strlen(ENB_UE_SCTP_PEER) + 1) == -1 ||
        allocate_memory((char **)&context->MME_HOST_NAME, strlen(MME_HOST_NAME) + 1) == -1) {
        free(context);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    strcpy(context->ENB_UE_SCTP_PEER, ENB_UE_SCTP_PEER);
    strcpy(context->MME_HOST_NAME, MME_HOST_NAME);
    context->MME_PORT = MME_PORT;

    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void update_context(DynamicArrayManager *manager, size_t index, 
                    const char *ENB_UE_SCTP_PEER, const char *MME_HOST_NAME, int MME_PORT) {
    if (index >= manager->count) {
        fprintf(stderr, "Invalid context index\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);
    LTE_ENBCONTEXT *context = manager->contexts[index];

    free(context->ENB_UE_SCTP_PEER);
    free(context->MME_HOST_NAME);

    if (allocate_memory((char **)&context->ENB_UE_SCTP_PEER, strlen(ENB_UE_SCTP_PEER) + 1) == -1 ||
        allocate_memory((char **)&context->MME_HOST_NAME, strlen(MME_HOST_NAME) + 1) == -1) {
        fprintf(stderr, "Failed to reallocate memory for context update\n");
    } else {
        strcpy(context->ENB_UE_SCTP_PEER, ENB_UE_SCTP_PEER);
