['Below is a C implementation for managing a dynamic array of `MAC_FRAME_PDU_T` structures, along with unit tests to ensure robustness and correctness:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_FRAMES 50000

typedef struct {
    int phy_layer_information;
    char frame_type;
    unsigned int sequence_number;
} MAC_FRAME_PDU_T;

typedef struct {
    MAC_FRAME_PDU_T *frames;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
int init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        return -1;
    }
    array->frames = NULL;
    return 0;
}

// Resize the dynamic array
static int resize_dynamic_array(DynamicArray *array, size_t new_size) {
    MAC_FRAME_PDU_T *new_frames = realloc(array->frames, new_size * sizeof(MAC_FRAME_PDU_T));
    if (!new_frames) {
        return -1; // Memory allocation failed
    }
    array->frames = new_frames;
    return 0;
}

// Add a frame to the dynamic array
int add_frame(DynamicArray *array, MAC_FRAME_PDU_T frame) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_FRAMES) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array full
    }

    size_t new_size = array->count + 1;
    if (resize_dynamic_array(array, new_size)) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory allocation failed
    }

    array->frames[array->count] = frame;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Free the dynamic array resources
void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->frames != NULL) {
        free(array->frames);
        array->frames = NULL;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Unit tests
void test_dynamic_array() {
    DynamicArray array;
    init_dynamic_array(&array);

    // Test adding frames up to the limit
    for (unsigned int i = 0; i < MAX_FRAMES; ++i) {
        MAC_FRAME_PDU_T frame = { .phy_layer_information = i, .frame_type = 'A', .sequence_number = i };
        if (add_frame(&array, frame) != 0) {
            printf("Error adding frame %u\n", i);
            break;
        }
    }

    // Test adding one more frame to exceed the limit
    MAC_FRAME_PDU_T extra_frame = { .phy_layer_information = MAX_FRAMES, .frame_type = 'B', .sequence_number = MAX_FRAMES };
    if (add_frame(&array, extra_frame) == -1) {
        printf("Correctly detected array full condition.\n");
    } else {
        printf("Error: should not have added extra frame beyond limit.\n");
    }

    // Free resources
    free_dynamic_array(&array);
}

int main() {
    test_dynamic_array();
    return 0;
}
```

### Key Considerations:

- **Memory Management**: The dynamic array uses `realloc` for resizing, which helps minimize fragmentation while allowing efficient memory usage.
- **Thread Safety**: A mutex (`pthread_mutex_t`) ensures thread-safe operations when modifying the array.
- **Error Handling**: Checks are in place to handle memory allocation failures and ensure the array does not exceed its maximum capacity.
- **Modularity**: The code is structured into functions for initialization, adding frames, resizing, and cleanup, promoting maintainability.
- **Unit Tests**: A basic test function ensures that the dynamic array behaves correctly under normal conditions and edge cases.

This implementation focuses on balancing performance, memory usage, and thread safety to handle up to 50,000 `MAC_FRAME_PDU_T` structures efficiently.']

