#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_SESSION_SIZE 1024 * 1024 // 1MB max session size
#define LOG_FILE "nfa_crc_log.txt"
#define VERBOSE_LEVEL 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t element_size;
    size_t max_elements;
    void *pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t max_elements) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->element_size = element_size;
    mp->max_elements = max_elements;
    mp->pool = malloc(element_size * max_elements);
    pthread_mutex_init(&mp->lock, NULL);

    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    return mp;
}

void* pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    static size_t index = 0;

    if (index >= mp->max_elements) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }

    void *element = (char *)mp->pool + index * mp->element_size;
    index++;
    pthread_mutex_unlock(&mp->lock);

    return element;
}

void pool_free_all(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    index = 0; // Reset the index
    pthread_mutex_unlock(&mp->lock);
}

void log_event(const char *msg) {
#ifdef LOGGING_ENABLED
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now;
        time(&now);
        fprintf(log_file, "%s: %s\n", ctime(&now), msg);
        fclose(log_file);
    }
#endif
}

void* create_nfa_crc_list(int num_elements, size_t max_session_size) {
    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (element_size * num_elements > max_session_size) {
        log_event("Memory allocation error: Exceeds max session size.");
        return NULL;
    }

    MemoryPool *mp = create_memory_pool(element_size, num_elements);
    if (!mp) {
        log_event("Memory pool creation failed.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        pool_free_all(mp);
        free(mp);
        log_event("Failed to allocate memory for NFA list.");
        return NULL;
    }

    for (int i = 0; i < num_elements; ++i) {
        nfa_list[i].RX_UE_INFORMATION_TAG = rand();
        nfa_list[i].RNTI = rand() & 0xFFFF;
        nfa_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        nfa_list[i].CRCFLAG = rand() % 2;

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Created UE ID: %u, CRC Status: %d", 
                 nfa_list[i].RNTI, nfa_list[i].CRCFLAG);
        log_event(log_msg);
    }

    return (void*)nfa_list;
}

void destroy_nfa_crc_list(void *list, int num_elements) {
    free(list);
    // Log completion
    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Successfully destroyed NFA list with %d elements.", num_elements);
    log_event(log_msg);
}
```

### Key Points:
- **Memory Pooling**: A simple memory pool implementation is used to manage allocations efficiently. This reduces overhead in high-load scenarios.
- **Thread Safety**: Mutex locks ensure that allocation from the pool is thread-safe.
- **Logging**: Events are logged with timestamps, using `ctime` for formatting and a simple file-based logging mechanism.
- **Error Handling**: Checks ensure memory does not exceed maximum allowed size and handles failed allocations gracefully by cleaning up resources.

This implementation assumes you have macros and constants defined elsewhere in your codebase as necessary. Adjust logging configuration (`LOGGING_ENABLED`) based on your actual setup.']

