} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    pthread_mutex_t lock;
} PDU_Manager;

int initialize_pdu_manager(PDU_Manager *manager, size_t n) {
    if (n > MAX_N) return -1; // Error: Exceeds maximum allowed RNTI range

    manager->capacity = n;
    manager->pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) return -2; // Error: Memory allocation failed

    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < n; ++i) {
        manager->pdus[i].RX_UE_INFORMATION_TAG = rand();
        manager->pdus[i].RNTI = i + 1;
        manager->pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }

    return 0; // Success
}

void free_pdu_manager(PDU_Manager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->pdus);
}

int validate_crc_flags(const PDU_Manager *manager, const unsigned char pattern[]) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->pdus[i].CRC_INDICATION_REL8_TAG != pattern[i % sizeof(pattern)]) {
            return -1; // Error: CRC flag mismatch
        }
    }
    return 0; // Success
}

void log_performance_metrics(const PDU_Manager *manager) {
    printf("PDU Manager Performance Metrics:\n");
    printf("Number of PDUs: %zu\n", manager->capacity);
    // Additional metrics can be added here
}

int update_pdu_manager(PDU_Manager *manager, int new_rnti, unsigned char crc_flag) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->pdus[i].RNTI == new_rnti) {
            manager->pdus[i].CRC_INDICATION_REL8_TAG = crc_flag;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: RNTI not found
}

void run_unit_tests() {
    PDU_Manager manager;
    int result;

    result = initialize_pdu_manager(&manager, 10);
    if (result != 0) {
        fprintf(stderr, "Initialization failed with error code %d\n", result);
        return;
    }

    unsigned char pattern[] = {1, 0}; // Example pattern for validation
    result = validate_crc_flags(&manager, pattern);
    if (result != 0) {
        fprintf(stderr, "CRC flag validation failed with error code %d\n", result);
    } else {
        printf("CRC flag validation succeeded.\n");
    }

    log_performance_metrics(&manager);

    result = update_pdu_manager(&manager, 5, 1);
    if (result != 0) {
        fprintf(stderr, "Update failed with error code %d\n", result);
    }

    free_pdu_manager(&manager);
}

int main() {
    srand(time(NULL));
    run_unit_tests();
    return 0;
}
