// Function to check uniqueness of RNTI values
int validate_unique_rnti(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            if (pdus[i].RNTI == pdus[j].RNTI)
                return 0;
        }
    }
    return 1;
}

// Function to periodically update CRCFLAG and ensure no two consecutive PDUs have the same value
void periodic_update(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t n, int percentage) {
    size_t num_updates = (size_t)((percentage / 100.0) * n);

    for (size_t i = 0; i < num_updates; ++i) {
        // Simulate a random CRCFLAG update
        unsigned int new_crcflag = rand() % 256;

        if (pdus[i].RX_UE_INFORMATION_TAG == new_crcflag && i > 0)
            continue;

        pdus[i].RX_UE_INFORMATION_TAG = new_crcflag;

        // Ensure no two consecutive indices have the same CRCFLAG
        if ((i + 1) < n && pdus[i].RX_UE_INFORMATION_TAG == pdus[i + 1].RX_UE_INFORMATION_TAG)
            pdus[i + 1].RX_UE_INFORMATION_TAG = (new_crcflag + 1) % 256;
    }
}

// Main function to manage and populate the dynamically allocated array
NFAPI_CRC_INDICATION_PDU_T* manage_pdus(size_t N, unsigned int seed, int update_percentage) {
    srand(seed);

    // Allocate memory for PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Populate PDUs with valid data
    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pdus[i].RNTI = rand() % 65536;

        // Ensure uniqueness of RNTI during population
        size_t j;
        for (j = 0; j < i; ++j) {
            if (pdus[j].RNTI == pdus[i].RNTI)
                break;
        }
        while (j != i) { // Collision detected, generate a new RNTI
            pdus[i].RNTI = rand() % 65536;
            for (j = 0; j < i; ++j) {
                if (pdus[j].RNTI == pdus[i].RNTI)
                    break;
            }
        }

        // Simulate the CRC_INDICATION_REL8_TAG
        pdus[i].RX_UE_INFORMATION_TAG |= (i << 8);
    }

    // Validate unique RNTI values
    if (!validate_unique_rnti(pdus, N)) {
        fprintf(stderr, "Validation failed: duplicate RNTI found\n");
        free(pdus);
        return NULL;
    }

    // Periodically update PDUs based on the configuration parameter
    periodic_update(pdus, N, update_percentage);

    return pdus;
}

