// Mock class to represent external API data fetching.
class ExternalAPIClient {
public:
    std::optional<std::string> fetchMetadata(const std::string& profileName) {
        // Simulate network delay
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        if (profileName == "invalid") return std::nullopt;

        return std::string("metadata for ") + profileName;
    }
};

class ConfigurationProfile {
public:
    ConfigurationProfile(const std::string& name, int logLevel, const std::string& filePath,
                         const std::string& rotationPolicy, const std::string& metadata)
        : name(name), logLevel(logLevel), filePath(filePath), rotationPolicy(rotationPolicy),
          metadata(metadata) {}

    void updateMetadata(const std::string& newMetadata) {
        metadata = newMetadata;
    }

private:
    std::string name;
    int logLevel;
    std::string filePath;
    std::string rotationPolicy;
    std::string metadata;
};

class ConfigurationProfileManager {
public:
    // Add or update a profile.
    void addOrUpdateProfile(const std::string& name, int logLevel, const std::string& filePath,
                            const std::string& rotationPolicy) {
        std::unique_lock lock(mutex_);

        auto result = externalAPIClient_.fetchMetadata(name);
        if (!result.has_value()) {
            throw std::runtime_error("Failed to fetch metadata for profile: " + name);
        }

        profiles_[name] = ConfigurationProfile(name, logLevel, filePath,
                                               rotationPolicy, result.value());
    }

    // Retrieve a configuration profile by name.
    std::optional<ConfigurationProfile> getProfile(const std::string& name) {
        std::shared_lock lock(mutex_);

        auto it = cache_.find(name);
        if (it != cache_.end()) {
            return it->second;
        }

        auto profileIt = profiles_.find(name);
        if (profileIt == profiles_.end()) {
            return std::nullopt;
        }

        // Cache the profile for future access
        cache_[name] = profileIt->second;
        if (cache_.size() > maxCacheSize_) {
            cache_.erase(cache_.begin());
        }

        return profileIt->second;
    }

private:
    ExternalAPIClient externalAPIClient_;
    std::unordered_map<std::string, ConfigurationProfile> profiles_;
    std::unordered_map<std::string, ConfigurationProfile> cache_;
    const size_t maxCacheSize_ = 100;

    mutable std::shared_mutex mutex_;

    // Additional methods to handle stale data detection and network partition scenarios
    void validateAndRefreshProfiles() {
        std::unique_lock lock(mutex_);

        for (auto& [name, profile] : profiles_) {
            auto result = externalAPIClient_.fetchMetadata(name);
            if (!result.has_value()) {
                // Handle metadata fetching failure gracefully.
                continue;
            }

            profile.updateMetadata(result.value());
        }

        cache_.clear();  // Clear cache to ensure consistency after refresh
    }
};

// Usage example:
int main() {
    ConfigurationProfileManager manager;

    try {
        manager.addOrUpdateProfile("profile1", 3, "/var/log/profile1.log", "daily");

        auto profile = manager.getProfile("profile1");
        if (profile) {
            std::cout << "Retrieved profile: " << profile->getMetadata() << "\n";
        } else {
            std::cout << "Profile not found\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
