    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread-safety
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray *dyn_array, size_t initial_capacity) {
    dyn_array->capacity = (initial_capacity > MAX_CAPACITY) ? MAX_CAPACITY : initial_capacity;
    dyn_array->count = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);

    // Allocate memory with error handling
    dyn_array->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * dyn_array->capacity);
    if (!dyn_array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE); // Consider a more graceful recovery in real applications
    }
}

// Function to resize the dynamic array when needed
void resize_dynamic_array(DynamicArray *dyn_array, size_t new_capacity) {
    pthread_mutex_lock(&dyn_array->lock);

    if (new_capacity > MAX_CAPACITY) {
        new_capacity = MAX_CAPACITY;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed\n");
        pthread_mutex_unlock(&dyn_array->lock);
        exit(EXIT_FAILURE); // Consider a more graceful recovery
    }

    dyn_array->array = temp;
    dyn_array->capacity = new_capacity;

    pthread_mutex_unlock(&dyn_array->lock);
}

// Function to add an element to the dynamic array
void add_crc_indication_pdu(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->count == dyn_array->capacity) {
        resize_dynamic_array(dyn_array, dyn_array->capacity * 2); // Double the capacity
    }

    dyn_array->array[dyn_array->count++] = pdu;

    pthread_mutex_unlock(&dyn_array->lock);
}

// Function to initialize a CRC_INDICATION_PDU_T with random data (example)
