    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu->CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
}

// Function to initialize the dynamic array with up to N elements
void initialize_dynamic_array_with_n_elements(DynamicArray *dyn_array, size_t N) {
    init_dynamic_array(dyn_array, N > MAX_CAPACITY ? MAX_CAPACITY : N);

    for (size_t i = 0; i < N && i < dyn_array->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        init_crc_indication_pdu(&pdu);
