#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int isValidRNTI(unsigned short rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

Node* createNode(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return NULL;
    *newNode = (Node){
        .data = *data,
        .next = NULL
    };
    return newNode;
}

void insertNode(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    if (!isValidRNTI(data->RNTI)) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Invalid RNTI: %u\n", data->RNTI);
        return;
    }

    Node* newNode = createNode(data);
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void populateLinkedList(LinkedList* list, int numElements) {
    srand(time(NULL));
    for (int i = 0; i < numElements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % (RNTI_MAX + 1),
            .CRC_INDICATION_REL8_TAG = rand() % 100,
            .CRCFLAG = rand() % 2
        };
        insertNode(list, &pdu);
    }
}

void* threadFunction(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    populateLinkedList(list, MAX_ELEMENTS / 10); // Each thread populates part of the list
    return NULL;
}

int main() {
    LinkedList list;
    initLinkedList(&list);

    const int numThreads = 10;
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, threadFunction, &list)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Example usage with signal processing library would go here

    freeLinkedList(&list);

    return 0;
}
