static size_t current_capacity = MAX_CAPACITY;
static size_t peak_memory_usage = 0;
static double average_memory_usage = 0.0;

void log_memory_usage(size_t current_usage) {
    printf("Current Memory Usage: %zu bytes\n", current_usage);
    if (current_usage > peak_memory_usage) {
        peak_memory_usage = current_usage;
    }
