    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->lock, NULL);
}

int resize_if_needed(DynamicArray *da) {
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 4 : da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return -1; // Out of memory
        da->array = new_array;
        da->capacity = new_capacity;
    }
    return 0;
}

int add_element(DynamicArray *da, int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&da->lock);

    if (resize_if_needed(da) != 0) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Out of memory
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &da->array[da->size++];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    srand(time(NULL) + rand()); // Seed for randomness
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int remove_element(DynamicArray *da, size_t index) {
    pthread_mutex_lock(&da->lock);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid index
    }

    memmove(&da->array[index], &da->array[index + 1], (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size--;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int update_element(DynamicArray *da, size_t index, int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&da->lock);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Invalid index
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &da->array[index];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    srand(time(NULL) + rand()); // Seed for randomness
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    pthread_mutex_unlock(&da->lock);
    return 0;
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    free(da->array);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;

    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}
