    NetworkPacket *newPacket = &packetArray->packets[packetArray->count++];
    strncpy(newPacket->sourceIP, sourceIP, sizeof(newPacket->sourceIP) - 1);
    newPacket->sourceIP[sizeof(newPacket->sourceIP) - 1] = '\0';
