#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 100
#define EVENT_NAME_BASE "Event_"
#define TIME_RANGE_MIN 0
#define TIME_RANGE_MAX 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG; // Assuming 1 bit for the flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char* name;
    int start_time;
    int end_time;
} Event;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* nfa_api_array;
    size_t nfa_api_count;
    Event* events;
    size_t event_count;
    pthread_cond_t cond_var;
} DataStructureManager;

void log_operation(const char* message) {
    printf("%s\n", message);
}

int random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

int random_time_within_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

DataStructureManager* initialize_data_structure_manager(size_t nfa_api_count) {
    DataStructureManager* manager = malloc(sizeof(DataStructureManager));
    if (!manager) {
        log_operation("Error: Memory allocation for manager failed.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    manager->nfa_api_array = malloc(nfa_api_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->nfa_api_array) {
        log_operation("Error: Memory allocation for NFAPI array failed.");
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < nfa_api_count; ++i) {
        manager->nfa_api_array[i].RX_UE_INFORMATION_TAG = rand();
        manager->nfa_api_array[i].RNTI = rand();
        manager->nfa_api_array[i].CRCFLAG = random_crcflag();
    }

    manager->nfa_api_count = nfa_api_count;
    manager->events = malloc(MAX_EVENTS * sizeof(Event));
    if (!manager->events) {
        log_operation("Error: Memory allocation for events array failed.");
        free(manager->nfa_api_array);
        free(manager);
        return NULL;
    }

    manager->event_count = 0;

    return manager;
}

void free_data_structure_manager(DataStructureManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->event_count; ++i) {
        free(manager->events[i].name);
    }

    free(manager->nfa_api_array);
    free(manager->events);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}

int add_event(DataStructureManager* manager, const char* base_name) {
    if (!manager || manager->event_count >= MAX_EVENTS) return -1;

    pthread_mutex_lock(&manager->lock);

    Event new_event;
    size_t name_length = strlen(base_name) + 10; // Enough space for index and null terminator
    new_event.name = malloc(name_length);
    if (!new_event.name) {
        log_operation("Error: Memory allocation for event name failed.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    snprintf(new_event.name, name_length, "%s%d", base_name, manager->event_count);

    new_event.start_time = random_time_within_range(TIME_RANGE_MIN, TIME_RANGE_MAX);
    int end_time;

    do {
        end_time = random_time_within_range(TIME_RANGE_MIN, TIME_RANGE_MAX);
    } while (end_time <= new_event.start_time); // Ensure no overlap

    new_event.end_time = end_time;

    manager->events[manager->event_count++] = new_event;
    pthread_cond_signal(&manager->cond_var);

    pthread_mutex_unlock(&manager->lock);
    log_operation("Event added successfully.");
    return 0;
}

int modify_event(DataStructureManager* manager, size_t index, int new_start_time, int new_end_time) {
    if (!manager || index >= manager->event_count) return -1;

    pthread_mutex_lock(&manager->lock);

    Event* event = &manager->events[index];
    event->start_time = new_start_time;
    event->end_time = new_end_time > new_start_time ? new_end_time : new_start_time + 1; // Ensure no overlap

    pthread_cond_signal(&manager->cond_var);
    pthread_mutex_unlock(&manager->lock);

    log_operation("Event modified successfully.");
    return 0;
}

int delete_event(DataStructureManager* manager, size_t index) {
    if (!manager || index >= manager->event_count) return -1;

    pthread_mutex_lock(&manager->lock);

    free(manager->events[index].name);
    for (size_t i = index; i < manager->event_count - 1; ++i) {
        manager->events[i] = manager->events[i + 1];
    }

    --manager->event_count;
    pthread_cond_signal(&manager->cond_var);

    pthread_mutex_unlock(&manager->lock);
    log_operation("Event deleted successfully.");
    return 0;
}

int get_active_event_count(DataStructureManager* manager) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);
    int count = manager->event_count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

double calculate_average_duration(DataStructureManager* manager, int time_window_min, int time_window_max) {
    if (!manager || manager->event_count == 0) return -1.0;

    pthread_mutex_lock(&manager->lock);

    double total_duration = 0;
    size_t valid_event_count = 0;

    for (size_t i = 0; i < manager->event_count; ++i) {
        if (manager->events[i].start_time >= time_window_min && manager->events[i].end_time <= time_window_max) {
            total_duration += (manager->events[i].end_time - manager->events[i].start_time);
            valid_event_count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return valid_event_count ? total_duration / valid_event_count : 0.0;
}

int main() {
    srand(time(NULL));

    DataStructureManager* manager = initialize_data_structure_manager(10);
    if (!manager) return EXIT_FAILURE;

    add_event(manager, EVENT_NAME_BASE);
    printf("Active Events: %d\n", get_active_event_count(manager));
    printf("Average Duration: %.2f\n", calculate_average_duration(manager, 0, 100));

    free_data_structure_manager(manager);

    return EXIT_SUCCESS;
}
