int initialize_list(NFAPI_LIST *nfa_list, size_t initial_capacity) {
    nfa_list->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list->list) return -1; // Memory allocation failure
    nfa_list->size = 0;
    nfa_list->capacity = initial_capacity;
    pthread_mutex_init(&nfa_list->lock, NULL);
    return 0;
}

// Resize the list when capacity is reached
int resize_list(NFAPI_LIST *nfa_list) {
    size_t new_capacity = nfa_list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(nfa_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) return -1; // Memory allocation failure
    nfa_list->list = new_list;
    nfa_list->capacity = new_capacity;
    return 0;
}

// Insert a new structure into the list
int insert_pdu(NFAPI_LIST *nfa_list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&nfa_list->lock);

    if (nfa_list->size == nfa_list->capacity) {
        int res = resize_list(nfa_list);
        if (res != 0) {
            pthread_mutex_unlock(&nfa_list->lock);
            return -1; // Memory allocation failure
        }
    }

    nfa_list->list[nfa_list->size] = pdu;
    nfa_list->size++;
    qsort(nfa_list->list, nfa_list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    pthread_mutex_unlock(&nfa_list->lock);
    return 0;
}

// Retrieve a structure by RNTI
NFAPI_CRC_INDICATION_PDU_T *get_pdu_by_rnti(NFAPI_LIST *nfa_list, int rnti) {
    pthread_mutex_lock(&nfa_list->lock);

    NFAPI_CRC_INDICATION_PDU_T *result = NULL;
    for (size_t i = 0; i < nfa_list->size; ++i) {
        if (nfa_list->list[i].rnti == rnti) {
            result = &nfa_list->list[i];
            break;
        }
    }

    pthread_mutex_unlock(&nfa_list->lock);
    return result;
}

// Delete a structure by RNTI
int delete_pdu_by_rnti(NFAPI_LIST *nfa_list, int rnti) {
    pthread_mutex_lock(&nfa_list->lock);

    for (size_t i = 0; i < nfa_list->size; ++i) {
        if (nfa_list->list[i].rnti == rnti) {
            memmove(&nfa_list->list[i], &nfa_list->list[i + 1], (nfa_list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            nfa_list->size--;
            qsort(nfa_list->list, nfa_list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);
            pthread_mutex_unlock(&nfa_list->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&nfa_list->lock);
    return -1; // PDU not found
}

// Free the list and clean up
void free_list(NFAPI_LIST *nfa_list) {
    pthread_mutex_lock(&nfa_list->lock);

    free(nfa_list->list);
    nfa_list->size = 0;
    nfa_list->capacity = 0;

    pthread_mutex_unlock(&nfa_list->lock);
    pthread_mutex_destroy(&nfa_list->lock);
}

int main() {
    // Example usage
    NFAPI_LIST list;
    if (initialize_list(&list, 10) != 0) {
        fprintf(stderr, "Failed to initialize list\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = { .rnti = 123 };
    insert_pdu(&list, pdu);

    NFAPI_CRC_INDICATION_PDU_T *found_pdu = get_pdu_by_rnti(&list, 123);
    if (found_pdu) {
        printf("PDU found with RNTI: %d\n", found_pdu->rnti);
    }

    delete_pdu_by_rnti(&list, 123);

    free_list(&list);
    return 0;
}
