NFAPI_CRC_INDICATION_PDU_T* memory_pool[POOL_SIZE];
size_t pool_index = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Throttling mechanism
typedef struct {
    pthread_mutex_t lock;
    int tokens;
} TokenBucket;

TokenBucket bucket = {PTHREAD_MUTEX_INITIALIZER, MAX_EVENTS};

void initialize_token_bucket() {
    pthread_mutex_lock(&bucket.lock);
    bucket.tokens = MAX_EVENTS; // Initial full capacity
    pthread_mutex_unlock(&bucket.lock);
}

int consume_token() {
    pthread_mutex_lock(&bucket.lock);
    if (bucket.tokens > 0) {
        bucket.tokens--;
        pthread_mutex_unlock(&bucket.lock);
        return 1;
    }
    pthread_mutex_unlock(&bucket.lock);
    return 0; // No token available
}

void replenish_tokens(int amount) {
    pthread_mutex_lock(&bucket.lock);
    bucket.tokens += amount;
    if (bucket.tokens > MAX_EVENTS) {
        bucket.tokens = MAX_EVENTS;
    }
    pthread_mutex_unlock(&bucket.lock);
}

// Asynchronous flush to persistent storage
typedef struct FlushThreadArgs {
    DeviceEvent* list_head;
} FlushThreadArgs;

void* async_flush_to_storage(void* args) {
    FlushThreadArgs* fta = (FlushThreadArgs*)args;
    // Simulate flushing events to disk, here we just free them
    while (fta->list_head != NULL) {
        DeviceEvent* temp = fta->list_head;
        fta->list_head = fta->list_head->next;
        free(temp->payload);
        free(temp);
    }
    return NULL;
}

// Logging mechanism
void log_event(const char* message) {
    // Simple logging to stdout, can be replaced with a more sophisticated system
    printf("%s\n", message);
}

// Error handling and event management functions

NFAPI_CRC_INDICATION_PDU_T* allocate_payload(size_t count) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* payload = memory_pool[pool_index++];
        pthread_mutex_unlock(&pool_lock);
        return payload;
    }
    pthread_mutex_unlock(&pool_lock);

    // No available block in pool, allocate new
    return malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_payload(NFAPI_CRC_INDICATION_PDU_T* payload) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index > 0) {
        memory_pool[--pool_index] = payload;
    } else {
        free(payload); // Pool exhausted, no reuse
    }
    pthread_mutex_unlock(&pool_lock);
}

void add_event(EventType event_type, NFAPI_CRC_INDICATION_PDU_T* payload, size_t count) {
    if (!consume_token()) return;

    DeviceEvent* new_event = (DeviceEvent*)malloc(sizeof(DeviceEvent));
    if (!new_event) {
        log_event("Failed to allocate memory for new event");
        return;
    }

    srand(time(NULL)); // For random CRCFLAG
    for (size_t i = 0; i < count; ++i) {
