    new_event->event_type = event_type;
    new_event->timestamp = time(NULL);
    new_event->payload_size = count;
    new_event->payload = allocate_payload(count);

    if (!new_event->payload) {
        log_event("Failed to allocate payload");
        free(new_event);
        return;
    }

    memcpy(new_event->payload, payload, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_event->next = NULL;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_event;
    } else {
        DeviceEvent* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_event;
    }
    log_event("New event added");
    pthread_mutex_unlock(&list_lock);
}

void remove_events_by_type(EventType event_type) {
    pthread_mutex_lock(&list_lock);
    DeviceEvent **current = &head, *temp;
    while (*current != NULL) {
        if ((*current)->event_type == event_type) {
            temp = *current;
            *current = (*current)->next;
            free_payload(temp->payload);
            free(temp);
            log_event("Event removed by type");
        } else {
            current = &(*current)->next;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void process_and_insert_events_concurrently() {
