        pthread_t flush_thread;
        FlushThreadArgs fta = {head};

        pthread_create(&flush_thread, NULL, async_flush_to_storage, &fta);
        pthread_join(flush_thread, NULL); // Join to ensure completion before next iteration

        sleep(10); // Simulate periodic flushing
    }
}

int main() {
