    pthread_cond_t cond;
    pthread_mutex_t mutex;
} TokenBucket;

TokenBucket throttleBucket;
const size_t bucketCapacity = 10;
const double refillRate = 1.0; // Tokens added per second
double lastRefillTime = 0.0;

// Memory Pool Definitions
#define POOL_SIZE 100
NFAPI_CRC_INDICATION_PDU_T* memoryPool[POOL_SIZE];
int poolIndex = 0;

void initializeMemoryPool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        memoryPool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocatePayload(size_t size) {
    pthread_mutex_lock(&listMutex);
    NFAPI_CRC_INDICATION_PDU_T* payload;

    if (poolIndex < POOL_SIZE) {
        payload = memoryPool[poolIndex++];
    } else {
        payload = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&listMutex);

    return payload;
}

void deallocatePayload(NFAPI_CRC_INDICATION_PDU_T* payload, size_t size) {
    pthread_mutex_lock(&listMutex);
    if (poolIndex < POOL_SIZE) {
        free(payload);
        memoryPool[--poolIndex] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        poolIndex++;
        free(memoryPool[poolIndex - 1]);
        memoryPool[poolIndex - 1] = payload;
    }
    pthread_mutex_unlock(&listMutex);
}

// Throttle control
void refillTokens() {
    double now = time(NULL);
    int tokensToAdd = (int)((now - lastRefillTime) * refillRate);

    if (tokensToAdd > 0) {
        pthread_mutex_lock(&throttleBucket.mutex);
        throttleBucket.tokens = (throttleBucket.tokens + tokensToAdd >= bucketCapacity) ? 
                                bucketCapacity : throttleBucket.tokens + tokensToAdd;
        pthread_cond_broadcast(&throttleBucket.cond);
        pthread_mutex_unlock(&throttleBucket.mutex);
    }
    lastRefillTime = now;
}

int consumeToken() {
    pthread_mutex_lock(&throttleBucket.mutex);

    while (throttleBucket.tokens <= 0) {
        pthread_cond_wait(&throttleBucket.cond, &throttleBucket.mutex);
    }

    throttleBucket.tokens--;
    pthread_mutex_unlock(&throttleBucket.mutex);

    return 1;
}

// Device event management
void* handleDeviceEvent(void* eventData) {
    if (!consumeToken()) return NULL;

    // Simulating random CRCFLAG setting for demonstration
