fn initialize_nfa_pdu_list_and_user_dir(
    num_pdus: usize,
    root_directory: &str,
    session_id: &str
) -> Result<(Vec<NFAPI_CRC_INDICATION_PDU_T>, String), io::Error> {

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    let mut pdus = Vec::with_capacity(num_pdus);
