    // Check if the root directory exists; create it if necessary
    match fs::metadata(root_directory) {
        Ok(_) => (),
        Err(e) if e.kind() == ErrorKind::NotFound => {
            fs::create_dir_all(root_directory)?;
        }
        Err(e) => return Err(e),
    }

    // Check if the session directory exists; create it if necessary
