#include <time.h>

#define DEFAULT_SIZE 1000
#define MAX_SIZE 10000
#define MAX_AGE_LIMIT 60 // Age limit in seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    time_t allocation_time; // Time of allocation for age tracking
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Log function stub (should be integrated with existing logging system)
void log_message(const char *message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_array(size_t size) {
    pthread_mutex_lock(&mutex);

    if (size == 0 || size > MAX_SIZE) {
        log_message("Invalid allocation size requested.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!array) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100000; // Example valid value
        array[i].RNTI = rand() % 10000; // Example valid value
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        array[i].allocation_time = time(NULL);
    }

    log_message("Successfully allocated NFAPI_CRC_INDICATION_PDU_T structures.");
    pthread_mutex_unlock(&mutex);

    return array;
}

void free_nfaapi_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        pthread_mutex_lock(&mutex);
        free(array);
        log_message("Freed NFAPI_CRC_INDICATION_PDU_T structures.");
        pthread_mutex_unlock(&mutex);
    }
}

void evict_old_structures(NFAPI_CRC_INDICATION_PDU_T **array, size_t *current_size, size_t max_size) {
    time_t current_time = time(NULL);

    for (size_t i = 0; i < *current_size; ) {
        if ((current_time - (*array)[i].allocation_time) > MAX_AGE_LIMIT) {
            // Shift structures to "evict" the old one
            memmove(&(*array)[i], &(*array)[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((*current_size) - i - 1));
            (*current_size)--;
        } else {
            ++i;
        }
    }

    // Reallocate if needed to maintain max size
    if (*current_size < max_size) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_size);
        if (new_array) {
            pthread_mutex_lock(&mutex);
            *array = new_array;
            pthread_mutex_unlock(&mutex);
        }
    }

    log_message("Evicted old structures.");
}

int main() {
    size_t current_size = DEFAULT_SIZE;
    NFAPI_CRC_INDICATION_PDU_T *array = allocate_nfaapi_array(current_size);

    if (array) {
        // Simulate usage
        sleep(1);  // Simulating time passing

        evict_old_structures(&array, &current_size, MAX_SIZE);

        free_nfaapi_array(array);
    }

    return 0;
}
