    return (RNTI >= 1 && RNTI <= 65535);
}

unsigned int generate_CRCFLAG(unsigned int RNTI, time_t system_time, unsigned int context_param) {
    // Non-trivial algorithm example combining inputs
    return (RNTI ^ (unsigned int)(system_time % 256) ^ context_param);
}

DynamicList* initialize_dynamic_list(size_t total_entries) {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list structure.\n");
        return NULL;
    }

    size_t initial_capacity = (total_entries + 1) / 2; // Ceiling of half
    list->entries = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        fprintf(stderr, "Initial memory allocation failed for %zu entries.\n", initial_capacity);
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    printf("Dynamic list initialized with capacity of %zu\n", initial_capacity);
    return list;
}

int add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!validate_RNTI(entry.RNTI)) {
        fprintf(stderr, "Invalid RNTI value: %u\n", entry.RNTI);
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    time_t system_time = time(NULL);
    unsigned int context_param = 123; // Example parameter
    entry.CRCFLAG = generate_CRCFLAG(entry.RNTI, system_time, context_param);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            fprintf(stderr, "Memory reallocation failed for %zu entries.\n", new_capacity);
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        list->entries = new_entries;
        list->capacity = new_capacity;
        printf("List resized to new capacity of %zu\n", new_capacity);
    }

    list->entries[list->count++] = entry;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        pthread_mutex_destroy(&list->mutex);
        free(list->entries);
        free(list);
        printf("Dynamic list freed.\n");
    }
}
```

