#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    INFO,
    WARN,
    ERROR
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    char *message;
    time_t timestamp;
    struct LogEntry *next; // For linked list implementation
} LogEntry;

// Function prototypes
LogEntry* initializeLogArray();
void addLog(LogEntry **logList, LogLevel level, const char *message);
void removeLogsBySeverityAndTimeRange(LogEntry **logList, LogLevel severity, time_t start_time, time_t end_time);
LogEntry** filterLogsByKeyword(LogEntry *logList, const char *keyword, int *count);
void archiveOldLogs(LogEntry **logList, time_t threshold);

// Function implementations
LogEntry* initializeLogArray() {
    return NULL; // Initialize an empty linked list for the log entries.
}

void addLog(LogEntry **logList, LogLevel level, const char *message) {
    LogEntry *newEntry = (LogEntry *)malloc(sizeof(LogEntry));
    newEntry->level = level;
    newEntry->timestamp = time(NULL); // Use fallback current time if necessary
    newEntry->message = strdup(message);
    newEntry->next = *logList;
    *logList = newEntry; // Add to the front for O(1) insertion.
}

void removeLogsBySeverityAndTimeRange(LogEntry **logList, LogLevel severity, time_t start_time, time_t end_time) {
    LogEntry *current = *logList;
    LogEntry *prev = NULL;
    while (current != NULL) {
        if ((current->level == severity) && (current->timestamp >= start_time) && (current->timestamp <= end_time)) {
            LogEntry *toDelete = current;
            if (prev == NULL) { // Head of the list
                *logList = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(toDelete->message);
            free(toDelete);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

LogEntry** filterLogsByKeyword(LogEntry *logList, const char *keyword, int *count) {
    LogEntry **filteredLogs = NULL;
    *count = 0;
    LogEntry *current = logList;

    while (current != NULL) {
        if (strstr(current->message, keyword)) {
            filteredLogs = realloc(filteredLogs, (*count + 1) * sizeof(LogEntry *));
            filteredLogs[*count] = current;
            (*count)++;
        }
        current = current->next;
    }

    return filteredLogs;
}

void archiveOldLogs(LogEntry **logList, time_t threshold) {
    LogEntry *current = *logList;
    LogEntry *prev = NULL;

    while (current != NULL) {
        if (current->timestamp < threshold) {
            LogEntry *toArchive = current;
            if (prev == NULL) { // Head of the list
                *logList = current->next;
            } else {
                prev->next = current->next;
            }

            // Here you would archive 'toArchive', then free it.
            free(toArchive->message);
            free(toArchive);

            current = current->next; // Proceed to next element without advancing `prev`
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Example usage
int main() {
    LogEntry *logList = initializeLogArray();

    addLog(&logList, INFO, "This is an info message");
    addLog(&logList, ERROR, "This is an error message");

    // Remove logs example
    time_t currentTime = time(NULL);
    removeLogsBySeverityAndTimeRange(&logList, WARN, currentTime - 3600, currentTime);

    // Filter logs example
    int count;
    LogEntry **filteredLogs = filterLogsByKeyword(logList, "error", &count);

    // Archive old logs periodically (simulate threshold)
    archiveOldLogs(&logList, currentTime - 24 * 3600);

    // Cleanup remaining logs
    while (logList != NULL) {
        LogEntry *toFree = logList;
        logList = logList->next;
        free(toFree->message);
        free(toFree);
    }

    return 0;
}
```

This implementation uses a linked list to manage dynamic arrays of `LogEntry` structures. It is designed for efficiency, scalability, and easy extensibility:

- **Dynamic Addition**: Log entries are added to the front of the list for O(1) complexity.
- **Efficient Removal**: Specific logs can be removed based on severity and time range efficiently.
- **Filtering by Keyword**: The filtering function allocates dynamically to handle variable number of matches, returning a pointer array of filtered logs.
- **Periodic Archiving**: Implements non-blocking archiving logic for logs older than a specified duration, freeing up memory resources as needed. 

Make sure to adapt the archiving and real-time service interaction according to your application's specific requirements and infrastructure.']

