void init_connection_list(ConnectionList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new TCP connection to the list
int add_connection(ConnectionList* list, const TCPConnection* conn) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    memcpy(&newNode->connection, conn, sizeof(TCPConnection));
    newNode->connection.last_active_time = time(NULL);
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Remove a TCP connection from the list based on IP and port
int remove_connection(ConnectionList* list, const char* ip, unsigned short port, int is_client) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if ((is_client && strcmp(current->connection.client_ip, ip) == 0 && current->connection.client_port == port) ||
            (!is_client && strcmp(current->connection.server_ip, ip) == 0 && current->connection.server_port == port)) {

            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

// Cleanup connections that have been inactive for longer than the timeout period
void cleanup_connections(ConnectionList* list) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if ((now - current->connection.last_active_time) > TIMEOUT / 1000) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            current = (prev != NULL) ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Periodic cleanup thread function
void* periodic_cleanup(void* arg) {
    ConnectionList* list = (ConnectionList*)arg;

    while (1) {
        sleep(10); // Run every 10 seconds
        cleanup_connections(list);
    }

    return NULL;
}

int main() {
    ConnectionList connection_list;
    init_connection_list(&connection_list);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, &connection_list);

    // The rest of the application code goes here...

    pthread_join(cleanup_thread, NULL); // Cleanup thread will run indefinitely

    return 0;
}
```

### Notes:
- This implementation uses a linked list to manage TCP connections with a mutex for thread safety.
- It includes functions to add and remove connections based on IP/port combinations.
- A periodic cleanup function is implemented to remove inactive connections, which runs in a separate thread.
- The timeout period is defined as 30 seconds (30000 milliseconds).
- The code assumes that logging mechanisms are integrated elsewhere, focusing on connection management.']

