#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

#define MAX_STRUCTURES 5000
#define MAX_THREADS 10

typedef struct {
    int RNTI;
    time_t timestamp;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} DynamicList;

DynamicList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void log_allocation() {}
void log_removal() {}
void log_export() {}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list.lock);
    if (list.count < MAX_STRUCTURES) {
        Node* node = malloc(sizeof(Node));
        if (node) {
            node->data = new_entry;
            node->next = list.head;
            list.head = node;
            list.count++;
            log_allocation();
        }
    }
    pthread_mutex_unlock(&list.lock);
}

void remove_old_entries(time_t max_age) {
    pthread_mutex_lock(&list.lock);
    time_t current_time = time(NULL);
    Node* prev = NULL;
    Node* curr = list.head;

    while (curr) {
        if (current_time - curr->data.rx_ue_info.timestamp > max_age) {
            if (prev) {
                prev->next = curr->next;
            } else {
                list.head = curr->next;
            }
            free(curr);
            log_removal();
            list.count--;
            curr = prev ? prev->next : list.head;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&list.lock);
}

void batch_export() {
    // Implement the export logic, e.g., serialize and write to a file or database
    log_export();
}

void* manage_list(void* arg) {
    time_t max_age = *(time_t*)arg;

    while (true) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.rx_ue_info.RNTI = rand(); // Example random RNTI generation
        entry.rx_ue_info.timestamp = time(NULL);
        entry.crc_rel8_tag.CRCFLAG = rand() % 256; // Random CRCFLAG

        add_to_list(entry);

        remove_old_entries(max_age);

        batch_export();

        usleep(100000); // Simulate periodic processing delay (e.g., 100 ms)
    }
}

void initialize_list(size_t max_threads) {
    pthread_t threads[max_threads];

    for (size_t i = 0; i < max_threads; ++i) {
        time_t max_age = 60; // Example: remove entries older than 60 seconds
        pthread_create(&threads[i], NULL, manage_list, &max_age);
    }

    for (size_t i = 0; i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initialize_list(MAX_THREADS);
    return 0;
}
