}

typedef struct {
    int id;
    char network_params[256];
    char config_settings[512];
} Session;

// Global session list and mutex for thread safety
static Session *sessions = NULL;
static size_t session_count = 0;
static pthread_mutex_t sessions_mutex = PTHREAD_MUTEX_INITIALIZER;

// Serialization format: id, network_params, config_settings per line
#define SESSION_FILE "sessions.dat"

// Function prototypes
void add_session(int id, const char *network_params, const char *config_settings);
void update_session(int id, const char *network_params, const char *config_settings);
void delete_session(int id);
int save_sessions_to_file();
int load_sessions_from_file();
Session* find_session_by_id(int id);

// Implementation
void add_session(int id, const char *network_params, const char *config_settings) {
    pthread_mutex_lock(&sessions_mutex);

    // Find if session already exists
    Session *existing = find_session_by_id(id);
    if (existing != NULL) {
        log_event("Session with ID already exists.");
        pthread_mutex_unlock(&sessions_mutex);
        return;
    }

    // Allocate new memory for the additional session
    Session *new_sessions = realloc(sessions, sizeof(Session) * (session_count + 1));
    if (!new_sessions) {
        log_event("Failed to allocate memory for a new session.");
        pthread_mutex_unlock(&sessions_mutex);
        return;
    }

    sessions = new_sessions;

    // Populate new session data
    Session *new_session = &sessions[session_count];
    new_session->id = id;
    strncpy(new_session->network_params, network_params, sizeof(new_session->network_params) - 1);
    strncpy(new_session->config_settings, config_settings, sizeof(new_session->config_settings) - 1);

    session_count++;
    log_event("Session added successfully.");

    pthread_mutex_unlock(&sessions_mutex);
}

void update_session(int id, const char *network_params, const char *config_settings) {
    pthread_mutex_lock(&sessions_mutex);

    Session *session = find_session_by_id(id);
    if (session == NULL) {
        log_event("Session not found for update.");
        pthread_mutex_unlock(&sessions_mutex);
        return;
    }

    strncpy(session->network_params, network_params, sizeof(session->network_params) - 1);
    strncpy(session->config_settings, config_settings, sizeof(session->config_settings) - 1);

    log_event("Session updated successfully.");

    pthread_mutex_unlock(&sessions_mutex);
}

void delete_session(int id) {
    pthread_mutex_lock(&sessions_mutex);

    Session *session_to_delete = find_session_by_id(id);
    if (session_to_delete == NULL) {
        log_event("Session not found for deletion.");
        pthread_mutex_unlock(&sessions_mutex);
        return;
    }

    // Shift sessions down in the array
    memmove(session_to_delete, session_to_delete + 1, sizeof(Session) * (--session_count - (session_to_delete - sessions)));

    // Reallocate memory to shrink array size
    Session *new_sessions = realloc(sessions, sizeof(Session) * session_count);
    if (!new_sessions && session_count != 0) {
        log_event("Failed to reallocate memory after deletion.");
        pthread_mutex_unlock(&sessions_mutex);
        return;
    }

    sessions = new_sessions;

    log_event("Session deleted successfully.");

    pthread_mutex_unlock(&sessions_mutex);
}

int save_sessions_to_file() {
    FILE *file = fopen(SESSION_FILE, "w");
    if (!file) {
        log_event("Failed to open file for writing.");
        return -1;
    }

    pthread_mutex_lock(&sessions_mutex);

    for (size_t i = 0; i < session_count; ++i) {
        fprintf(file, "%d,%s,%s\n", sessions[i].id,
                sessions[i].network_params,
                sessions[i].config_settings);
    }

    int result = fclose(file) == 0 ? 0 : -1;

    pthread_mutex_unlock(&sessions_mutex);

    if (result != 0) {
        log_event("Failed to close file after writing.");
    } else {
        log_event("Sessions saved to file successfully.");
    }

    return result;
}

int load_sessions_from_file() {
    FILE *file = fopen(SESSION_FILE, "r");
    if (!file) {
        log_event("Failed to open file for reading.");
        return -1;
    }

    char line[1024];
    pthread_mutex_lock(&sessions_mutex);

    // Free existing sessions
    free(sessions);
    session_count = 0;

    while (fgets(line, sizeof(line), file)) {
        int id;
        char network_params[256], config_settings[512];

        if (sscanf(line, "%d,%255[^,],%511s", &id, network_params, config_settings) == 3) {
            add_session(id, network_params, config_settings);
        } else {
            log_event("Failed to parse session line from file.");
        }
    }

    int result = fclose(file) == 0 ? 0 : -1;

    pthread_mutex_unlock(&sessions_mutex);

    if (result != 0) {
        log_event("Failed to close file after reading.");
    } else {
        log_event("Sessions loaded from file successfully.");
    }

    return result;
}

Session* find_session_by_id(int id) {
    for (size_t i = 0; i < session_count; ++i) {
        if (sessions[i].id == id) {
            return &sessions[i];
        }
    }
    return NULL;
}

// Cleanup resources
void cleanup() {
    pthread_mutex_lock(&sessions_mutex);

    free(sessions);
    sessions = NULL;
    session_count = 0;

    pthread_mutex_unlock(&sessions_mutex);

    log_event("Resources cleaned up.");
}
