#define MAX_TIMERS 10000

typedef struct {
    uint32_t timer_id;
    time_t start_time;
    int stopped; // 0 for running, 1 for stopped
} LTEPHYTIMER;

typedef void (*TimerCallback)(uint32_t timer_id);

typedef struct {
    LTEPHYTIMER timers[MAX_TIMERS];
    pthread_mutex_t lock;
    TimerCallback expiration_callback;
} TimerManager;

void init_timer_manager(TimerManager *manager) {
    manager->expiration_callback = NULL;
    for (int i = 0; i < MAX_TIMERS; ++i) {
        manager->timers[i].timer_id = i + 1;
        manager->timers[i].start_time = 0;
        manager->timers[i].stopped = 1;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

void set_expiration_callback(TimerManager *manager, TimerCallback callback) {
    pthread_mutex_lock(&manager->lock);
    manager->expiration_callback = callback;
    pthread_mutex_unlock(&manager->lock);
}

int add_timer(TimerManager *manager, time_t start_time) {
    int id;
    pthread_mutex_lock(&manager->lock);
    for (id = 0; id < MAX_TIMERS; ++id) {
        if (manager->timers[id].stopped) {
            manager->timers[id].start_time = start_time;
            manager->timers[id].stopped = 0;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return id + 1; // Return timer ID, or -1 if no space
}

void stop_timer(TimerManager *manager, uint32_t timer_id) {
    int index = timer_id - 1;
    if (index >= 0 && index < MAX_TIMERS) {
        pthread_mutex_lock(&manager->lock);
        manager->timers[index].stopped = 1;
        // Log stopping event
        pthread_mutex_unlock(&manager->lock);
    }
}

void update_timer(TimerManager *manager, uint32_t timer_id, time_t new_start_time) {
    int index = timer_id - 1;
    if (index >= 0 && index < MAX_TIMERS && !manager->timers[index].stopped) {
        pthread_mutex_lock(&manager->lock);
        manager->timers[index].start_time = new_start_time;
        // Log update event
        pthread_mutex_unlock(&manager->lock);
    }
}

void check_timers(TimerManager *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_TIMERS; ++i) {
        if (!manager->timers[i].stopped && manager->timers[i].start_time + /* duration */ <= current_time) {
            // Log expiration event
            manager->timers[i].stopped = 1;
            if (manager->expiration_callback) {
                manager->expiration_callback(manager->timers[i].timer_id);
            }
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_timer_manager(TimerManager *manager) {
    pthread_mutex_destroy(&manager->lock);
}
