// Memory pool structure
typedef struct {
    LTEPHYTIMER* pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool timer_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
TimerList timer_list = {NULL, PTHREAD_RWLOCK_INITIALIZER, 0};

// Initialize memory pool
void init_memory_pool(size_t initial_size) {
    timer_pool.pool = (LTEPHYTIMER*)malloc(initial_size * sizeof(LTEPHYTIMER));
    if (!timer_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    timer_pool.capacity = initial_size;
}

// Acquire a timer from the pool
LTEPHYTIMER* acquire_timer() {
    pthread_mutex_lock(&timer_pool.mutex);
    if (timer_pool.used >= timer_pool.capacity) {
        // Expand pool if needed
        size_t new_capacity = timer_pool.capacity * 2;
        LTEPHYTIMER* new_pool = (LTEPHYTIMER*)realloc(timer_pool.pool, new_capacity * sizeof(LTEPHYTIMER));
        if (!new_pool) {
            perror("Failed to expand memory pool");
            pthread_mutex_unlock(&timer_pool.mutex);
            exit(EXIT_FAILURE);
        }
        timer_pool.pool = new_pool;
        timer_pool.capacity = new_capacity;
    }
    LTEPHYTIMER* timer = &timer_pool.pool[timer_pool.used++];
    pthread_mutex_unlock(&timer_pool.mutex);
    return timer;
}

// Release a timer back to the pool
void release_timer(LTEPHYTIMER* timer) {
    // For simplicity, this example does not implement actual release logic.
    // In practice, you might want to mark timers as reusable and free them when no longer in use.
}

// Initialize the timer list
void init_timer_list() {
    if (timer_pool.pool == NULL) {
        init_memory_pool(1000); // Initial pool size
    }
}

// Add a new timer
int add_timer(int timerID, time_t startTime, void (*callback)(LTEPHYTIMER*)) {
    pthread_rwlock_wrlock(&timer_list.lock);

    TimerNode* newNode = (TimerNode*)malloc(sizeof(TimerNode));
    if (!newNode) {
        perror("Failed to allocate timer node");
        pthread_rwlock_unlock(&timer_list.lock);
        return -1;
    }

    LTEPHYTIMER* newTimer = acquire_timer();
    newTimer->timerID = timerID;
    newTimer->startTime = startTime;
    newTimer->stopped = 0;

    newNode->data = *newTimer;
    newNode->next = timer_list.head;
    timer_list.head = newNode;
    timer_list.count++;

    pthread_rwlock_unlock(&timer_list.lock);

    // Log addition
    printf("Added timer %d at time %ld\n", timerID, startTime);

    return 0;
}

// Stop a timer
int stop_timer(int timerID) {
    pthread_rwlock_wrlock(&timer_list.lock);

    TimerNode *current = timer_list.head, *prev = NULL;
    while (current != NULL) {
        if (current->data.timerID == timerID) {
            current->data.stopped = 1;

            // Log stopping
            printf("Stopped timer %d\n", timerID);

            pthread_rwlock_unlock(&timer_list.lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_rwlock_unlock(&timer_list.lock);
    return -1; // Timer not found
}

// Update a timer
int update_timer(int timerID, time_t newStartTime) {
    pthread_rwlock_wrlock(&timer_list.lock);

    TimerNode *current = timer_list.head;
    while (current != NULL) {
        if (current->data.timerID == timerID && !current->data.stopped) {
            current->data.startTime = newStartTime;

            // Log update
            printf("Updated timer %d to start time %ld\n", timerID, newStartTime);

            pthread_rwlock_unlock(&timer_list.lock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&timer_list.lock);
    return -1; // Timer not found or stopped
}

// Expire a timer
void expire_timers(void (*callback)(LTEPHYTIMER*)) {
    time_t currentTime = time(NULL);

    pthread_rwlock_wrlock(&timer_list.lock);

    TimerNode *current = timer_list.head, *prev = NULL;
    while (current != NULL) {
        if (!current->data.stopped && current->data.startTime <= currentTime) {
            callback(&current->data);

            // Log expiration
            printf("Expired timer %d\n", current->data.timerID);

            TimerNode* toDelete = current;
            if (prev == NULL) {
                timer_list.head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;

            free(toDelete);
            timer_list.count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&timer_list.lock);
}

// Example callback function
void timer_expired(LTEPHYTIMER* timer) {
    printf("Timer %d expired\n", timer->timerID);
}

int main() {
    init_timer_list();

    add_timer(1, time(NULL) + 5); // Timer with ID 1 that expires in 5 seconds
    sleep(6); // Wait for the timer to expire

    expire_timers(timer_expired);

    return 0;
}
