}

typedef struct SessionManager {
    Session* sessions[MAX_SESSIONS];
    int count;
    pthread_rwlock_t rwlock;
} SessionManager;

SessionManager manager = {{0}, 0, PTHREAD_RWLOCK_INITIALIZER};

