void add_session(const char* id, const char* network_params, const char* config_settings) {
    pthread_rwlock_wrlock(&manager.rwlock);

    for (int i = 0; i < manager.count; ++i) {
        if (strcmp(manager.sessions[i]->id, id) == 0) {
            pthread_rwlock_unlock(&manager.rwlock);
            log_error("Session with this ID already exists");
            return;
        }
    }

    Session* session = allocate_session();
    if (!session) {
        pthread_rwlock_unlock(&manager.rwlock);
        log_error("Memory allocation failed");
        return;
    }

    strncpy(session->id, id, SESSION_ID_SIZE - 1);
    strncpy(session->network_params, network_params, NETWORK_PARAMS_SIZE - 1);
    strncpy(session->config_settings, config_settings, CONFIG_SETTINGS_SIZE - 1);

    manager.sessions[manager.count++] = session;

    log_info("Session added", id);

    pthread_rwlock_unlock(&manager.rwlock);
}

// Function to update a session
void update_session(const char* id, const char* network_params, const char* config_settings) {
    pthread_rwlock_wrlock(&manager.rwlock);

    for (int i = 0; i < manager.count; ++i) {
        if (strcmp(manager.sessions[i]->id, id) == 0) {
            strncpy(manager.sessions[i]->network_params, network_params, NETWORK_PARAMS_SIZE - 1);
            strncpy(manager.sessions[i]->config_settings, config_settings, CONFIG_SETTINGS_SIZE - 1);

            log_info("Session updated", id);
            break;
        }
    }

    pthread_rwlock_unlock(&manager.rwlock);
}

// Function to delete a session
void delete_session(const char* id) {
    pthread_rwlock_wrlock(&manager.rwlock);

    for (int i = 0; i < manager.count; ++i) {
        if (strcmp(manager.sessions[i]->id, id) == 0) {
            free_session(manager.sessions[i]);
            memmove(&manager.sessions[i], &manager.sessions[i + 1],
                    (manager.count - i - 1) * sizeof(Session*));
            --manager.count;

            log_info("Session deleted", id);
            break;
        }
    }

    pthread_rwlock_unlock(&manager.rwlock);
}

// Serialization and deserialization functions
void serialize_sessions(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

