    fwrite(&manager.count, sizeof(manager.count), 1, file);
    for (int i = 0; i < manager.count; ++i) {
        fwrite(manager.sessions[i], sizeof(Session), 1, file);
    }

    fclose(file);
    pthread_rwlock_unlock(&manager.rwlock);
}

void deserialize_sessions(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for reading");
        return;
    }

    pthread_rwlock_wrlock(&manager.rwlock);

    fread(&manager.count, sizeof(manager.count), 1, file);
    manager.sessions[0] = (Session*)malloc(manager.count * sizeof(Session));
    if (!manager.sessions[0]) {
        log_error("Memory allocation failed during deserialization");
        fclose(file);
        pthread_rwlock_unlock(&manager.rwlock);
        return;
    }

    fread(manager.sessions[0], sizeof(Session), manager.count, file);

    for (int i = 1; i < manager.count; ++i) {
        manager.sessions[i] = &manager.sessions[0][i];
    }

    fclose(file);
    pthread_rwlock_unlock(&manager.rwlock);
}

// Initialize the system
void initialize_system() {
    initialize_memory_pool(&session_pool);
    memset(manager.sessions, 0, sizeof(manager.sessions));
    manager.count = 0;
}
