#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int l2_message_tag;
    size_t payload_size;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

MessageArray* init_message_array(size_t initial_capacity) {
    MessageArray *array = malloc(sizeof(MessageArray));
    array->messages = malloc(initial_capacity * sizeof(NFAPI_MESSAGE_T));
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_message_array(MessageArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->messages);
    free(array);
}

int add_message(MessageArray *array, int l2_message_tag, size_t payload_size) {
    pthread_mutex_lock(&array->lock);

    if (array->count == sizeof(array->messages) / sizeof(NFAPI_MESSAGE_T)) {
        // Attempt to resize
        size_t new_capacity = array->count * 2;
        NFAPI_MESSAGE_T *new_messages = realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));

        if (!new_messages) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        array->messages = new_messages;
    }

    array->messages[array->count].l2_message_tag = l2_message_tag;
    array->messages[array->count].payload_size = payload_size;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

NFAPI_MESSAGE_T* get_message(MessageArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);

    if (index >= array->count) {
        pthread_mutex_unlock(&array->lock);
        return NULL; // Index out of bounds
    }

    NFAPI_MESSAGE_T *message = &array->messages[index];
    pthread_mutex_unlock(&array->lock);
    return message;
}

void process_messages(MessageArray *array, void (*process_func)(NFAPI_MESSAGE_T *)) {
    for (size_t i = 0; i < array->count; ++i) {
        NFAPI_MESSAGE_T *message = get_message(array, i);
        if (message) {
            process_func(message);
        }
    }
}

// Example processing function
void example_process(NFAPI_MESSAGE_T *message) {
    printf("Processing message with tag %d and payload size %zu\n", 
           message->l2_message_tag, message->payload_size);
}
