#include <arpa/inet.h>
#include <resolv.h>

#define MAX_TIMERS 100
#define CACHE_SIZE 10

typedef struct {
    int timer_id;
    time_t start_time;
    int stopped;
} LTEPHYTIMER;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheEntry {
    char hostname[256];
    u_char ip_address[4];
    time_t timestamp;
    struct CacheEntry *next;
} CacheEntry;

LTEPHYTIMER timers[MAX_TIMERS];
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
CacheEntry *dns_cache = NULL;
pthread_mutex_t timer_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t crc_list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t dns_cache_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_timers(int count) {
    pthread_mutex_lock(&timer_lock);
    for (int i = 0; i < count && i < MAX_TIMERS; ++i) {
        timers[i].timer_id = i + 1;
        timers[i].start_time = time(NULL);
        timers[i].stopped = 0;
    }
    pthread_mutex_unlock(&timer_lock);
}

void manage_crc_list(NFAPI_CRC_INDICATION_PDU_T *new_pdu, int add) {
    pthread_mutex_lock(&crc_list_lock);
    if (add) {
        crc_indications = realloc(crc_indications, 
            (count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&crc_indications[count], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        count++;
    } else {
        // Logic to remove the PDU by searching with a key
        for (int i = 0; i < count; ++i) {
            if (/* condition matching specific pdu */) {
                memmove(&crc_indications[i], 
                    &crc_indications[i + 1],
                    (--count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                crc_indications = realloc(crc_indications, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                break;
            }
        }
    }
    pthread_mutex_unlock(&crc_list_lock);
}

u_char* resolve_hostname(const char *hostname) {
    u_char *ip_address = NULL;

    // Check cache first
    pthread_mutex_lock(&dns_cache_lock);
    CacheEntry *current = dns_cache, *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->hostname, hostname) == 0 &&
            time(NULL) - current->timestamp < 300) { // cache valid for 5 minutes
            ip_address = malloc(4);
            memcpy(ip_address, current->ip_address, 4);
            pthread_mutex_unlock(&dns_cache_lock);
            return ip_address;
        }
        prev = current;
        current = current->next;
    }

    struct hostent *he = gethostbyname(hostname);
    if (he) {
        inet_pton(AF_INET, he->h_addr_list[0], ip_address);

        // Update cache
        CacheEntry *new_entry = malloc(sizeof(CacheEntry));
        strcpy(new_entry->hostname, hostname);
        memcpy(new_entry->ip_address, ip_address, 4);
        new_entry->timestamp = time(NULL);
        new_entry->next = dns_cache;
        dns_cache = new_entry;

        if (prev) {
            prev->next = new_entry;
        }
    } else {
        // Handle DNS resolution failure
        fprintf(stderr, "DNS Resolution Failed for %s\n", hostname);
    }

    pthread_mutex_unlock(&dns_cache_lock);

    return ip_address;
}

void log_message(const char *message, int level) {
    // Example logging function with levels (DEBUG, INFO, WARNING, ERROR)
    printf("[%d] %s\n", level, message); 
}

