int main() {
    initialize_timers(10);

    NFAPI_CRC_INDICATION_PDU_T pdu = {12345, 6789, 1, rand() % 2};
    manage_crc_list(&pdu, 1);

    u_char *ip = resolve_hostname("www.example.com");
    if (ip) {
        inet_ntop(AF_INET, ip, buffer, INET_ADDRSTRLEN);
        printf("Resolved IP: %s\n", buffer);
        free(ip);
    }

    return 0;
}
