['Below is a C implementation for managing a dynamic array of TCP connection states with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define CLEANUP_INTERVAL 5 // seconds

typedef struct {
    char client_ip[16];
    int client_port;
    char server_ip[16];
    int server_port;
    time_t last_active;
} Connection;

typedef struct {
    Connection *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t timeout;
} ConnectionManager;

ConnectionManager* init_connection_manager(time_t timeout) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    manager->connections = malloc(INITIAL_CAPACITY * sizeof(Connection));
    manager->count = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->timeout = timeout;
    return manager;
}

void free_connection_manager(ConnectionManager *manager) {
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager->manager);
}

static void resize_connections(ConnectionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Connection *new_connections = realloc(manager->connections, new_capacity * sizeof(Connection));
    if (new_connections) {
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
}

void add_connection(ConnectionManager *manager, const char *client_ip, int client_port,
                    const char *server_ip, int server_port) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        Connection *conn = &manager->connections[i];
        if (strcmp(conn->client_ip, client_ip) == 0 && conn->client_port == client_port &&
            strcmp(conn->server_ip, server_ip) == 0 && conn->server_port == server_port) {
            pthread_mutex_unlock(&manager->lock);
            return; // Duplicate connection
        }
    }

    if (manager->count == manager->capacity) {
        resize_connections(manager);
    }

    Connection *conn = &manager->connections[manager->count++];
    strncpy(conn->client_ip, client_ip, sizeof(conn->client_ip));
    conn->client_port = client_port;
    strncpy(conn->server_ip, server_ip, sizeof(conn->server_ip));
    conn->server_port = server_port;
    conn->last_active = time(NULL);

    pthread_mutex_unlock(&manager->lock);
}

void remove_connection(ConnectionManager *manager, const char *ip, int port) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        Connection *conn = &manager->connections[i];
        if ((strcmp(conn->client_ip, ip) == 0 && conn->client_port == port) ||
            (strcmp(conn->server_ip, ip) == 0 && conn->server_port == port)) {
            memmove(&manager->connections[i], &manager->connections[i + 1],
                    (manager->count - i - 1) * sizeof(Connection));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_connections(ConnectionManager *manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count;) {
        Connection *conn = &manager->connections[i];
        if (difftime(now, conn->last_active) > manager->timeout) {
            memmove(&manager->connections[i], &manager->connections[i + 1],
                    (manager->count - i - 1) * sizeof(Connection));
            manager->count--;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void* cleanup_thread(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;

    while (1) {
        sleep(CLEANUP_INTERVAL);
        cleanup_connections(manager);
    }

    return NULL;
}

void start_cleanup_thread(ConnectionManager *manager) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, cleanup_thread, manager);
    pthread_detach(thread_id);
}

void adjust_timeout(ConnectionManager *manager, time_t new_timeout) {
    pthread_mutex_lock(&manager->lock);
    manager->timeout = new_timeout;
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    ConnectionManager *manager = init_connection_manager(60); // 1-minute timeout
    start_cleanup_thread(manager);

    add_connection(manager, "192.168.1.2", 12345, "10.0.0.1", 80);
    remove_connection(manager, "192.168.1.2", 12345);

    free_connection_manager(manager);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses mutexes to ensure thread-safe operations.
- **Dynamic Array Management**: Resizes the connection array as needed.
- **Periodic Cleanup**: A separate thread periodically cleans up inactive connections.
- **Duplicate Connection Handling**: Prevents adding duplicate client-server pairs.
- **Timeout Adjustment**: Allows dynamic adjustment of timeout based on network conditions.

This implementation provides a robust foundation for managing TCP connections with considerations for scalability and performance.']

