} TransportChannelManager;

int initializeTransportChannels(TransportChannelManager *manager, size_t initialCapacity) {
    if (manager == NULL || initialCapacity == 0) return -1;

    // Initialize the mutex
    pthread_mutex_init(&manager->lock, NULL);

    // Allocate memory for transport channels array
    manager->channels = (LTE_UuPHY_TransportChannel **)malloc(initialCapacity * sizeof(LTE_UuPHY_TransportChannel *));
    if (!manager->channels) {
        pthread_mutex_destroy(&manager->lock);
        return -1;
    }

    manager->count = initialCapacity;

    // Initialize each transport channel
    for (size_t i = 0; i < initialCapacity; ++i) {
        manager->channels[i] = malloc(sizeof(LTE_UuPHY_TransportChannel));
        if (!manager->channels[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(manager->channels[j]);
            }
            free(manager->channels);
            pthread_mutex_destroy(&manager->lock);
            return -1;
        }

        // Assume these functions fetch real-time data
        manager->channels[i]->TransportChannelIdentity = getChannelIdentity(i);
        manager->channels[i]->TransportFormatCombinationType = getFormatCombinationType(i);

        size_t tbs = calculateTBS(manager->channels[i]->TransportFormatCombinationType);
        manager->channels[i]->BufferSize = (tbs > INITIAL_BUFFER_SIZE) ? tbs : INITIAL_BUFFER_SIZE;

        // Allocate buffer for transport block
        manager->channels[i]->TransportBlockBuffer = (unsigned char *)malloc(manager->channels[i]->BufferSize);
        if (!manager->channels[i]->TransportBlockBuffer) {
            free(manager->channels[i]);
            for (size_t j = 0; j < i; ++j) {
                free(manager->channels[j]);
            }
            free(manager->channels);
            pthread_mutex_destroy(&manager->lock);
            return -1;
        }

        // Monitor and log buffer usage
        logBufferUsage(i, manager->channels[i]->BufferSize);
    }

    return 0;
}

int resizeTransportChannels(TransportChannelManager *manager, size_t newCapacity) {
    if (manager == NULL || newCapacity <= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);

    LTE_UuPHY_TransportChannel **newChannels = realloc(manager->channels, newCapacity * sizeof(LTE_UuPHY_TransportChannel *));
    if (!newChannels) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->channels = newChannels;

    for (size_t i = manager->count; i < newCapacity; ++i) {
        manager->channels[i] = malloc(sizeof(LTE_UuPHY_TransportChannel));
        if (!manager->channels[i]) {
            for (size_t j = i + 1; j < newCapacity; ++j) free(manager->channels[j]);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        // Assume these functions fetch real-time data
        manager->channels[i]->TransportChannelIdentity = getChannelIdentity(i);
        manager->channels[i]->TransportFormatCombinationType = getFormatCombinationType(i);

        size_t tbs = calculateTBS(manager->channels[i]->TransportFormatCombinationType);
        manager->channels[i]->BufferSize = (tbs > INITIAL_BUFFER_SIZE) ? tbs : INITIAL_BUFFER_SIZE;

        // Allocate buffer for transport block
        manager->channels[i]->TransportBlockBuffer = (unsigned char *)malloc(manager->channels[i]->BufferSize);
        if (!manager->channels[i]->TransportBlockBuffer) {
            free(manager->channels[i]);
            for (size_t j = i + 1; j < newCapacity; ++j) free(manager->channels[j]);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        // Monitor and log buffer usage
        logBufferUsage(i, manager->channels[i]->BufferSize);
    }

    manager->count = newCapacity;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int updateTransportFormat(TransportChannelManager *manager, int channelIdentity) {
    if (manager == NULL) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->channels[i]->TransportChannelIdentity == channelIdentity) {
            int newFormatType = getNewFormatCombinationType(channelIdentity);

            if (newFormatType != manager->channels[i]->TransportFormatCombinationType) {
                size_t tbs = calculateTBS(newFormatType);
                if (tbs > manager->channels[i]->BufferSize) {
                    free(manager->channels[i]->TransportBlockBuffer);

                    manager->channels[i]->TransportBlockBuffer = malloc(tbs);
                    if (!manager->channels[i]->TransportBlockBuffer) {
                        pthread_mutex_unlock(&manager->lock);
                        return -1;
                    }
                }

                manager->channels[i]->TransportFormatCombinationType = newFormatType;

                // Log the change
                logFormatChange(channelIdentity, newFormatType);

                break;
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

