#define LOGGING_VERBOSE 1

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array = NULL;
size_t capacity = 0, size = 0;

int check_unique_rnti(RNTI new_rnti) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].rnti == new_rnti) return 0;
    }
    return 1;
}

void log_element(const NFAPI_CRC_INDICATION_PDU_T *element) {
#ifdef LOGGING_VERBOSE
    printf("Added element - RX_UE_INFORMATION_TAG valid: %d, RNTI: %u, CRCFLAG: %u\n",
           element->ue_information_tag.valid,
           element->rnti,
           element->crc_indication_rel8_tag.CRCFLAG);
#endif
}

int add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    if (new_pdu == NULL || new_pdu->ue_information_tag.valid != 1)
        return -1;

    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        size_t new_capacity = capacity > 0 ? capacity * 2 : INITIAL_CAPACITY;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&lock);
            return -1; // Memory allocation failed
        }
        array = new_array;
        capacity = new_capacity;
    }

    if (!check_unique_rnti(new_pdu->rnti)) {
        pthread_mutex_unlock(&lock);
        return -2; // Duplicate RNTI detected
    }

    memcpy(&array[size], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size++;

    log_element(new_pdu);

    pthread_mutex_unlock(&lock);
    return 0;
}

void initialize_array() {
    array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) exit(-1); // Handle memory allocation failure
    capacity = INITIAL_CAPACITY;
    size = 0;
}

void cleanup_array() {
    free(array);
    pthread_mutex_destroy(&lock);
}
