    int RNTI;
    struct {
        int CRCFLAG; // Randomly set flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    LTE_Uplink_NRCGF_Dataset *datasets;
    size_t capacity;
    size_t count;
} DatasetManager;

// DNS Resolution function
int resolve_dns(const char *hostname, u_char ip[4]) {
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        fprintf(stderr, "DNS resolution failed: %s\n", hstrerror(h_errno));
        return -1;
    }
    memcpy(ip, host->h_addr_list[0], 4);
    return 0;
}

// Logging function
void log_message(int verbosity_level, const char *message) {
    if (verbosity_level <= LOG_VERBOSITY_LEVELS) {
        printf("%s\n", message);
    }
}

// Function to initialize DatasetManager with preallocated memory
int init_dataset_manager(DatasetManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->datasets = malloc(initial_capacity * sizeof(LTE_Uplink_NRCGF_Dataset));
    if (manager->datasets == NULL) {
        perror("Failed to allocate memory for datasets");
        return -1;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    return 0;
}

// Function to add a dataset to the manager
int add_dataset(DatasetManager *manager, LTE_Uplink_NRCGF_Dataset dataset) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_Uplink_NRCGF_Dataset *new_datasets =
            realloc(manager->datasets, new_capacity * sizeof(LTE_Uplink_NRCGF_Dataset));
        if (new_datasets == NULL) {
            perror("Failed to reallocate memory for datasets");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->datasets = new_datasets;
        manager->capacity = new_capacity;
    }

    manager->datasets[manager->count++] = dataset;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to verify CRCFLAG values
int verify_crc_flags(const DatasetManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        // Assuming a simple criteria check, extend as needed.
        if (manager->datasets[i].nr_crgf_metrics == NULL || 
            (manager->datasets[i].nr_crgf_metrics->CRCFLAG != 1)) {
            return -1;
        }
    }
    return 0;
}

// Main function to manage datasets
void *manage_datasets(void *arg) {
    DatasetManager manager = *(DatasetManager *)arg;

    // Retry mechanism for transient errors
    int retry_count = 0;
    while (retry_count < MAX_RETRIES) {
        if (add_dataset(&manager, (LTE_Uplink_NRCGF_Dataset){ .rnti = rand(), /* other fields */ }) == 0) {
            log_message(1, "Dataset added successfully.");
            break;
        }
        retry_count++;
        log_message(2, "Transient error encountered. Retrying...");
    }

    if (retry_count >= MAX_RETRIES) {
        log_message(3, "Failed to add dataset after retries.");
    }

    if (verify_crc_flags(&manager) != 0) {
        log_message(3, "CRCFLAG verification failed.");
    } else {
        log_message(1, "All CRCFLAG values are valid.");
    }

    return NULL;
}

// Example usage
int main() {
    DatasetManager manager;
    if (init_dataset_manager(&manager, 10) != 0) {
        fprintf(stderr, "Failed to initialize dataset manager.\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, manage_datasets, &manager);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(manager.datasets);
    return EXIT_SUCCESS;
}
