#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe data structure for managing the list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_pdu_list(PduList* list) {
    Node *current, *next;
    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_used(PduList* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->pdu.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

void add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->pdu = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void populate_pdu_list(PduList* list, size_t count, uint8_t crc_threshold, uint8_t min_crcflag) {
    srand(time(NULL));
    uint16_t used_rntis[MAX_RNTI + 1] = {0};
    int total_crcflag = 0;

    for (size_t i = 0; i < count && total_crcflag <= crc_threshold; ++i) {
        uint8_t crcflag;
        do {
            crcflag = rand() % 256;
        } while (crcflag < min_crcflag);

        if (total_crcflag + crcflag > crc_threshold) continue;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        do {
            pdu.RNTI = rand() % (MAX_RNTI + 1);
        } while (used_rntis[pdu.RNTI] || is_rnti_used(list, pdu.RNTI));
        used_rntis[pdu.RNTI] = 1;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 10; // Example range
        pdu.CRCFLAG = crcflag;

        total_crcflag += crcflag;
        add_pdu(list, pdu);
    }
}

// Example usage
int main() {
    PduList* list = create_pdu_list();
    if (!list) return 1;

    populate_pdu_list(list, 1000, 500, 10);

    // Processing and cleanup
    free_pdu_list(list);

    return 0;
}
```

### Key Points:
- **Thread-Safety**: Uses `pthread_mutex_t` to ensure safe access to the linked list from multiple threads.
- **Memory Management**: Allocates nodes dynamically and ensures proper deallocation.
- **Unique RNTI Handling**: Maintains an array to track used RNTIs for quick checks, ensuring no duplicates.
- **Performance Considerations**: Minimizes allocations by using a simple linked list and managing memory efficiently.
- **Extensibility**: The structure `NFAPI_CRC_INDICATION_PDU_T` can be easily extended with additional fields if needed.

This implementation assumes the existence of necessary libraries for threading and random number generation. Adjustments may be required based on specific system constraints or requirements.']

