#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENB_CONTEXTS 5000
#define MAX_UE_CONTEXTS_PER_CELL 1000

typedef struct {
    int RNTI;
    float PREAMBLE_CORRELATION_RESULT;
    int MEASUREMENT_REPORT;
} UE_CONTEXT_T;

typedef struct {
    int ENB_ID;
    int CELL_ID;
    UE_CONTEXT_T *ue_contexts;
    size_t ue_count;
} LTE_ENBCONTEXT_T;

typedef struct Node {
    LTE_ENBCONTEXT_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EnbContextList;

EnbContextList enb_context_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t element_size, size_t max_elements, void** pool) {
    *pool = malloc(element_size * max_elements);
    if (!*pool) {
        fprintf(stderr, "Memory allocation failed for pool\n");
        exit(EXIT_FAILURE);
    }
}

void free_memory_pool(void* pool) {
    free(pool);
}

LTE_ENBCONTEXT_T* allocate_enb_context(void* pool) {
    static size_t next_index = 0;
    void* block = (char*)pool + sizeof(LTE_ENBCONTEXT_T) * next_index++;
    if ((char*)block - (char*)pool >= sizeof(LTE_ENBCONTEXT_T) * MAX_ENB_CONTEXTS) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }
    return block;
}

void* ue_context_pool = NULL;

void init_ue_context_pool() {
    init_memory_pool(sizeof(UE_CONTEXT_T), MAX_UE_CONTEXTS_PER_CELL * MAX_ENB_CONTEXTS, &ue_context_pool);
}

void add_enb_context(int enb_id, int cell_id) {
    pthread_mutex_lock(&enb_context_list.lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        pthread_mutex_unlock(&enb_context_list.lock);
        return;
    }

    new_node->data.ENB_ID = enb_id;
    new_node->data.CELL_ID = cell_id;
    new_node->data.ue_contexts = allocate_enb_context(ue_context_pool);
    if (!new_node->data.ue_contexts) {
        free(new_node);
        pthread_mutex_unlock(&enb_context_list.lock);
        return;
    }
    new_node->data.ue_count = 0;
    new_node->next = enb_context_list.head;
    enb_context_list.head = new_node;

    pthread_mutex_unlock(&enb_context_list.lock);
}

void delete_enb_context(int enb_id, int cell_id) {
    pthread_mutex_lock(&enb_context_list.lock);

    Node *current = enb_context_list.head, *prev = NULL;
    while (current) {
        if (current->data.ENB_ID == enb_id && current->data.CELL_ID == cell_id) {
            if (prev) prev->next = current->next;
            else enb_context_list.head = current->next;

            free(current->data.ue_contexts);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&enb_context_list.lock);
}

void iterate_enb_contexts(void (*callback)(LTE_ENBCONTEXT_T*)) {
    pthread_mutex_lock(&enb_context_list.lock);

    Node* current = enb_context_list.head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&enb_context_list.lock);
}

void cleanup() {
    pthread_mutex_lock(&enb_context_list.lock);

    Node *current = enb_context_list.head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp->data.ue_contexts);
        free(temp);
    }

    enb_context_list.head = NULL;

    pthread_mutex_unlock(&enb_context_list.lock);
    free_memory_pool(ue_context_pool);
}

int main() {
    init_ue_context_pool();

    add_enb_context(1, 101);
    add_enb_context(2, 202);

    iterate_enb_contexts([](LTE_ENBCONTEXT_T* context) {
        printf("ENB_ID: %d, CELL_ID: %d\n", context->ENB_ID, context->CELL_ID);
    });

    delete_enb_context(1, 101);

    cleanup();
    return 0;
}
```

This code defines a dynamically growing list of `LTE_ENBCONTEXT_T` structures using a custom memory pool for efficient memory management. It supports insertion, deletion, and ordered iteration with thread safety using mutex locks. The design allows for future extensions and customization while ensuring minimal performance bottlenecks under heavy load.']

