#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int USER_ID;
    time_t SESSION_START_TIME;
    time_t LAST_ACTIVE_TIME;
} USER_DATA_RECORD;

#define INITIAL_CAPACITY 1024

typedef struct {
    USER_DATA_RECORD *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} DynamicList;

// Custom memory pool structure
typedef struct MemoryPool {
    void *memory;
    size_t block_size;
    size_t num_blocks;
    size_t used_blocks;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->memory = calloc(block_size, num_blocks);
    pool->used_blocks = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->used_blocks >= pool->num_blocks) {
        pthread_mutex_unlock(&pool->mutex);
        fprintf(stderr, "Memory Pool allocation failed: Out of blocks\n");
        return NULL;
    }
    void *block = (char*)pool->memory + (pool->used_blocks++ * pool->block_size);
    pthread_mutex_unlock(&pool->mutex);
    return block;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory);
    free(pool);
}

DynamicList* create_dynamic_list() {
    DynamicList *list = malloc(sizeof(DynamicList));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);

    list->records = calloc(list->capacity, sizeof(USER_DATA_RECORD));
    if (list->records == NULL) {
        fprintf(stderr, "DynamicList allocation failed\n");
        free(list);
        return NULL;
    }
    return list;
}

int dynamic_list_insert(DynamicList *list, USER_DATA_RECORD record) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        USER_DATA_RECORD *new_records = realloc(list->records, new_capacity * sizeof(USER_DATA_RECORD));
        if (!new_records) {
            fprintf(stderr, "DynamicList reallocation failed\n");
            pthread_rwlock_unlock(&list->rwlock);
            return -1;
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }

    list->records[list->count++] = record;

    pthread_rwlock_unlock(&list->rwlock);
    return 0;
}

int dynamic_list_delete(DynamicList *list, int user_id) {
    pthread_rwlock_wrlock(&list->rwlock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].USER_ID == user_id) {
            memmove(&list->records[i], &list->records[i + 1],
                    (list->count - i - 1) * sizeof(USER_DATA_RECORD));
            --list->count;
            pthread_rwlock_unlock(&list->rwlock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&list->rwlock);
    return -1;
}

void reverse_iterate_list(DynamicList *list, void (*func)(USER_DATA_RECORD)) {
    pthread_rwlock_rdlock(&list->rwlock);

    for (int i = list->count - 1; i >= 0; --i) {
        func(list->records[i]);
    }

    pthread_rwlock_unlock(&list->rwlock);
}

void cleanup_dynamic_list(DynamicList *list, MemoryPool *pool) {
    free(list->records);
    free(list);
    free_memory_pool(pool);
}

// Example usage function for reverse iteration
void print_user_data(USER_DATA_RECORD record) {
    printf("USER_ID: %d\n", record.USER_ID);
    printf("SESSION_START_TIME: %ld\n", record.SESSION_START_TIME);
    printf("LAST_ACTIVE_TIME: %ld\n", record.LAST_ACTIVE_TIME);
}

int main() {
    MemoryPool *pool = create_memory_pool(sizeof(USER_DATA_RECORD), 10000);

    DynamicList *list = create_dynamic_list();
    if (!list) return -1;

    USER_DATA_RECORD new_record = { .USER_ID = 1, .SESSION_START_TIME = time(NULL), .LAST_ACTIVE_TIME = time(NULL) };
    dynamic_list_insert(list, new_record);

    reverse_iterate_list(list, print_user_data);

    cleanup_dynamic_list(list, pool);
    return 0;
}
```

This code provides a dynamically growing list structure in C with efficient insertion and deletion operations. It includes thread safety using read-write locks, a custom memory pool for managing allocations efficiently, and provisions to handle failures gracefully by logging errors when memory allocation fails. Additionally, it facilitates reverse iteration over the records and can be easily extended for further enhancements or integrations.']

