void add_to_hash_map(HashMap *map, LTE_RRC_CREATION_REQUEST request);
LTE_RRC_CREATION_REQUEST* get_from_hash_map(HashMap *map, int SIB1);
void update_in_hash_map(HashMap *map, int SIB1, LTE_RRC_CREATION_REQUEST new_request);

// Linked list functions
LinkedList* create_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_to_linked_list(LinkedList *list, LTE_RRC_CREATION_REQUEST request) {
    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->data = request;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

LTE_RRC_CREATION_REQUEST* get_from_linked_list(LinkedList *list, int SIB1) {
    ListNode *current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.SIB1 == SIB1) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return NULL; // Not found
}

void update_in_linked_list(LinkedList *list, int SIB1, LTE_RRC_CREATION_REQUEST new_request) {
    ListNode *current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data.SIB1 == SIB1) {
            current->data = new_request;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Hash map functions
HashMap* create_hash_map() {
    HashMap *map = malloc(sizeof(HashMap));
    map->capacity = HASH_MAP_INITIAL_CAPACITY;
    map->buckets = calloc(map->capacity, sizeof(HashMapNode *));
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

int hash_function(int key, size_t capacity) {
    return key % capacity;
}

void add_to_hash_map(HashMap *map, LTE_RRC_CREATION_REQUEST request) {
    int index = hash_function(request.SIB1, map->capacity);

    HashMapNode *new_node = malloc(sizeof(HashMapNode));
    new_node->SIB1 = request.SIB1;
    new_node->request = request;
    new_node->next = NULL;

    pthread_mutex_lock(&map->lock);
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;
    pthread_mutex_unlock(&map->lock);
}

LTE_RRC_CREATION_REQUEST* get_from_hash_map(HashMap *map, int SIB1) {
    int index = hash_function(SIB1, map->capacity);

    pthread_mutex_lock(&map->lock);
    HashMapNode *current = map->buckets[index];
    while (current != NULL) {
        if (current->SIB1 == SIB1) {
            pthread_mutex_unlock(&map->lock);
            return &current->request;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&map->lock);

    return NULL; // Not found
}

void update_in_hash_map(HashMap *map, int SIB1, LTE_RRC_CREATION_REQUEST new_request) {
    int index = hash_function(SIB1, map->capacity);

    pthread_mutex_lock(&map->lock);
    HashMapNode *current = map->buckets[index];
    while (current != NULL) {
        if (current->SIB1 == SIB1) {
            current->request = new_request;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&map->lock);
}

// Example usage
int main() {
    LinkedList *list = create_linked_list();
    HashMap *hash_map = create_hash_map();

    LTE_RRC_CREATION_REQUEST request1 = { .MAC_RLC_AM_STATUS_Report = 1, .SIB1 = 101, .NAS_MESSAGE = "Message1" };
    add_to_linked_list(list, request1);
    add_to_hash_map(hash_map, request1);

    LTE_RRC_CREATION_REQUEST *retrieved_request = get_from_hash_map(hash_map, 101);
    if (retrieved_request) {
        printf("Retrieved: %s\n", retrieved_request->NAS_MESSAGE);
    }

    // Clean up
    free(list);
    for (size_t i = 0; i < hash_map->capacity; ++i) {
        HashMapNode *current = hash_map->buckets[i];
        while (current != NULL) {
            HashMapNode *to_delete = current;
            current = current->next;
            free(to_delete);
        }
    }
    free(hash_map->buckets);
    free(hash_map);

    return 0;
}
