    void* memoryPool;
    pthread_mutex_t mutex;
    int poolSize;
} CustomAllocator;

// Hash table structure with bucket array and size
typedef struct {
    struct Node** buckets;
    int numBuckets;
    pthread_rwlock_t rwlock;
} CRCHashTable;

void* custom_malloc(CustomAllocator *allocator, size_t count) {
    pthread_mutex_lock(&allocator->mutex);
    if (count > allocator->poolSize) {
        // Resize memory pool
        allocator->memoryPool = realloc(allocator->memoryPool, 
                                        allocator->elementSize * count);
        if (!allocator->memoryPool) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        allocator->poolSize = count;
    }

    void* ptr = allocator->memoryPool;
    allocator->memoryPool += allocator->elementSize;
    pthread_mutex_unlock(&allocator->mutex);

    return ptr;
}

void custom_free(CustomAllocator *allocator, void* ptr) {
    // Custom free logic if needed
}

CRCHashTable* create_table(int numBuckets) {
    CRCHashTable* table = (CRCHashTable*)malloc(sizeof(CRCHashTable));
    table->buckets = (struct Node**)calloc(numBuckets, sizeof(struct Node*));
    table->numBuckets = numBuckets;
    pthread_rwlock_init(&table->rwlock, NULL);
    return table;
}

int hash_function(int rnti, int numBuckets) {
    return rnti % numBuckets;
}

void insert_structure(CRCHashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_rwlock_wrlock(&table->rwlock);

    int index = hash_function(data.RNTI, table->numBuckets);
    struct Node* newNode = (struct Node*)custom_malloc(customAllocator, 1);

    if (!newNode) return;

    newNode->data = data;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_rwlock_unlock(&table->rwlock);
}

NFAPI_CRC_INDICATION_PDU_T* find_structure(CRCHashTable* table, int rnti) {
