        if (node->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = &node->data;
            pthread_rwlock_unlock(&table->rwlock);
            return result;
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&table->rwlock);
    return NULL;
}

void free_table(CRCHashTable* table) {
    for (int i = 0; i < table->numBuckets; ++i) {
        struct Node* head = table->buckets[i];
        while (head) {
            struct Node* temp = head;
            head = head->next;
