NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCList(size_t numUEs, uint16_t* validRNTIs, size_t numValidRNTIs) {
    if (numUEs == 0 || validRNTIs == NULL || numValidRNTIs == 0) {
        logError("Invalid parameters for creating NFAPI CRC list.");
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T
    NFAPI_CRC_INDICATION_PDU_T* nfaPduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaPduList) {
        logError("Memory allocation failed for NFAPI CRC list.");
        return NULL;
    }

    // Populate each structure
    for (size_t i = 0; i < numUEs; ++i) {
        nfaPduList[i].rxUeInfo.rnti = validRNTIs[i % numValidRNTIs]; // Cycle through valid RNTIs

        // Ensure the RNTI is valid
        if (nfaPduList[i].rxUeInfo.rnti == 0) {
            logError("Encountered an invalid RNTI.");
            free(nfaPduList);
            return NULL;
