        nfaPduList[i].rnti = nfaPduList[i].rxUeInfo.rnti;

        // Set the CRC flag randomly
        nfaPduList[i].crcIndicationRel8.crcFlag = rand() % 2; // Randomly set to 0 or 1
    }

    return nfaPduList;
}

void freeNFAPICRCList(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}
