    CellIdentity cellId;
    int rsrp;
    int rsrpEstimate;
} UeMeasurementReport;

UeMeasurementReport* initializeAndManageMeasurementReports(size_t numReports) {
    if (numReports > MAX_MEASUREMENTS) {
        printf("Exceeded maximum allowed measurement reports.\n");
        return NULL;
    }

    UeMeasurementReport *reports = (UeMeasurementReport*)malloc(numReports * sizeof(UeMeasurementReport));
    if (!reports) {
        fprintf(stderr, "Memory allocation failed for measurement reports.\n");
        return NULL;
    }

    // Initialize reports with hypothetical data or from an external source
    for (size_t i = 0; i < numReports; ++i) {
        reports[i].cellId.cellId = i + 1;  // Example cell ID
        reports[i].rsrp = rand() % 100;    // Simulated RSRP value
        reports[i].rsrpEstimate = reports[i].rsrp;
    }

    return reports;
}

void updateRsrpEstimate(UeMeasurementReport *reports, size_t numReports) {
    if (!reports) return;

    for (size_t i = 0; i < numReports; ++i) {
        int newRsrp = rand() % 100;  // Simulated new RSRP measurement
        int rsrpChange = abs(reports[i].rsrp - newRsrp);

        if (rsrpChange <= RSRP_STABILITY_THRESHOLD) {
            reports[i].rsrpEstimate = ((reports[i].rsrpEstimate * 3) + newRsrp) / 4;
        } else {
            // Discard unstable measurements
            printf("Unstable measurement for cell ID %d. Change: %d\n", 
                   reports[i].cellId.cellId, rsrpChange);
        }
    }
}

void reinitializeReports(UeMeasurementReport *reports, size_t numReports) {
    if (!reports) return;

    // Reallocate and reinitialize the array
    free(reports);
    reports = initializeAndManageMeasurementReports(numReports);

    if (!reports) {
        fprintf(stderr, "Reinitialization failed due to memory allocation error.\n");
    }
}

void cleanup(UeMeasurementReport *reports) {
    free(reports);
}
