typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    uint8_t crcflag; // CRC_INDICATION_REL8_TAG equivalent
} NFAPI_CRC_INDICATION_PDU_T;

// Cache structure for frequently accessed items.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items[MAX_CACHE_SIZE];
    int count;
    pthread_mutex_t lock;
} Cache;

// Initialize cache with mutex
void init_cache(Cache* cache) {
    memset(cache, 0, sizeof(Cache));
    pthread_mutex_init(&cache->lock, NULL);
}

// Clean up the cache
void destroy_cache(Cache* cache) {
    for (int i = 0; i < cache->count; ++i) {
        free(cache->items[i]);
    }
    pthread_mutex_destroy(&cache->lock);
}

// Generate a random CRCFLAG
uint8_t generate_random_crcflag() {
    return rand() % 256;
}

// Check RNTI validity (implement your own logic here)
bool is_valid_rnti(RNTI rnti) {
    // Example validation: Assume any non-zero value is valid.
    return rnti != 0;
}

// Create an NFAPI_CRC_INDICATION_PDU_T item
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_pdu(RX_UE_INFORMATION_TAG rx_ue_info_tag, RNTI rnti) {
    if (!is_valid_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI: %u\n", rnti);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pdu->rx_ue_info_tag = rx_ue_info_tag;
    pdu->rnti = rnti;
    pdu->crcflag = generate_random_crcflag();
    return pdu;
}

// Add item to cache if there's space
bool add_to_cache(Cache* cache, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count < MAX_CACHE_SIZE) {
        cache->items[cache->count++] = item;
        pthread_mutex_unlock(&cache->lock);
        return true;
    }

    pthread_mutex_unlock(&cache->lock);
    free(item); // Cache full, discard new item
    return false;
}

// Function to manage and generate list of NFAPI_CRC_INDICATION_PDU_T items
void* nfa_crc_indication_manager(void *arg) {
    int num_items = *(int*)arg;
    RX_UE_INFORMATION_TAG example_rx_ue_tag = {.example_field = 123}; // Example tag

    Cache cache;
    init_cache(&cache);

    for (int i = 0; i < num_items; ++i) {
        RNTI rnti = rand() % 65536; // Example RNTI generation
        NFAPI_CRC_INDICATION_PDU_T *item = create_nfa_pi_crc_pdu(example_rx_ue_tag, rnti);

        if (item != NULL && !add_to_cache(&cache, item)) {
            free(item); // Not added to cache, so free the memory.
        }
    }

    destroy_cache(&cache);
    return NULL;
}

// Example of multi-threaded execution
int main() {
    pthread_t threads[4];
    int loads[] = {1000, 1500, 2000, 2500}; // Different load conditions

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, nfa_crc_indication_manager, &loads[i])) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```

