#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define MEMORY_LIMIT (2 * 1024 * 1024) // 2MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->size >= MAX_STRUCTS) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    pthread_mutex_lock(&list->lock);
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int generate_structures(LinkedList* list, size_t num) {
    if (!list || num > MAX_STRUCTS) return -1;

    srand(time(NULL));

    for (size_t i = 0; i < num; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
        data.RNTI = rand() % 10000; // Example RNTI
        data.CRCFLAG = rand() & 1;

        if (add_to_list(list, data) != 0) {
            fprintf(stderr, "Failed to add structure due to memory constraints.\n");
            return -1;
        }
    }

    return 0;
}

void sort_by_RNTI(LinkedList* list, int ascending) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    // Simple bubble sort for demonstration
    int swapped;
    Node *ptr1, *lptr = NULL;

    do {
        swapped = 0;
        ptr1 = list->head;

        while (ptr1->next != lptr) {
            if ((ascending && ptr1->data.RNTI > ptr1->next->data.RNTI) ||
                (!ascending && ptr1->data.RNTI < ptr1->next->data.RNTI)) {

                NFAPI_CRC_INDICATION_PDU_T temp = ptr1->data;
                ptr1->data = ptr1->next->data;
                ptr1->next->data = temp;

                swapped = 1;
            }
            ptr1 = ptr1->next;
        }
        lptr = ptr1;
    } while (swapped);

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(LinkedList* list, const char* filename) {
    if (!list || !filename) return;

    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void process_in_chunks(LinkedList* list, size_t chunk_size) {
    if (!list || !chunk_size) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && chunk_size > 0) {
        // Process the data in current
        // Example: printf("Processing RNTI: %d\n", current->data.RNTI);

        current = current->next;
        --chunk_size;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    LinkedList* list = create_list();
    if (!list) return EXIT_FAILURE;

    generate_structures(list, 5000); // Example usage
    sort_by_RNTI(list, 1); // Sort ascending

    serialize_list(list, "nfa_data.bin");

    process_in_chunks(list, 200);

    destroy_list(list);
    return EXIT_SUCCESS;
}
```

