### JavaScript Function: `copyDataChunk`

```javascript
function copyDataChunk(targetByteCount, ...buffers) {
    let totalSize = 0;
    for (const buffer of buffers) {
        if (!Buffer.isBuffer(buffer)) return null; // Validate input
        totalSize += buffer.length;
    }

    const resultLength = Math.min(totalSize, targetByteCount);
    const resultBuffer = Buffer.allocUnsafe(resultLength);

    let copiedBytes = 0;

    for (const buffer of buffers) {
        const bytesToCopy = Math.min(buffer.length, resultLength - copiedBytes);
        if (bytesToCopy > 0) {
            buffer.copy(resultBuffer, copiedBytes, 0, bytesToCopy);
            copiedBytes += bytesToCopy;
        }
        if (copiedBytes >= resultLength) break; // Stop if we've reached the target
    }

    return resultBuffer.slice(0, copiedBytes); // Return only the filled portion
}
```

