typedef struct Node {
    NFAPI_RX_FRAME_T frame;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    atomic_ulong frame_count;
} FrameList;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for managing the list
FrameList global_frame_list = {NULL, 0};

void log_event(const char* event) {
    printf("%s\n", event); // Simplified logging mechanism
}

NFAPI_RX_FRAME_T* create_rx_frame(unsigned long rnti, const RX_UE_INFORMATION_TAG* tag, const char* pdu_data, size_t pdu_size) {
    if (pdu_size > MAX_PDU_SIZE) {
        log_event("Buffer overflow detected");
        return NULL;
    }

    NFAPI_RX_FRAME_T* frame = malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!frame) {
        log_event("Memory allocation failed");
        return NULL;
    }

    frame->rnti = rnti;
    frame->ue_info_tag = *tag;
    frame->pdu_data = malloc(pdu_size);
    if (!frame->pdu_data) {
        free(frame);
        log_event("Memory allocation for PDU data failed");
        return NULL;
    }

    memcpy(frame->pdu_data, pdu_data, pdu_size);
    frame->pdu_size = pdu_size;

    return frame;
}

void add_rx_frame(unsigned long rnti, const RX_UE_INFORMATION_TAG* tag, const char* pdu_data, size_t pdu_size) {
    NFAPI_RX_FRAME_T* frame = create_rx_frame(rnti, tag, pdu_data, pdu_size);
    if (!frame) return;

    pthread_mutex_lock(&list_mutex);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation for list node failed");
        free(frame->pdu_data);
        free(frame);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->frame = *frame;
    new_node->next = global_frame_list.head;
    global_frame_list.head = new_node;

    atomic_fetch_add(&global_frame_list.frame_count, 1);
    log_event("Frame added");
    free(frame->pdu_data); // Only the frame itself needs to be freed; data is part of node
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_RX_FRAME_T* get_rx_frame(unsigned long rnti) {
    pthread_mutex_lock(&list_mutex);

    Node* current = global_frame_list.head;
    while (current != NULL) {
        if (current->frame.rnti == rnti) {
            NFAPI_RX_FRAME_T* result = malloc(sizeof(NFAPI_RX_FRAME_T));
            *result = current->frame;
            pthread_mutex_unlock(&list_mutex);
            return result;
        }
        current = current->next;
    }

    log_event("Frame not found");
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void clear_all_frames() {
    pthread_mutex_lock(&list_mutex);

    Node* current = global_frame_list.head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current->frame.pdu_data);
        free(current);
        current = next_node;
    }

    global_frame_list.head = NULL;
    atomic_store(&global_frame_list.frame_count, 0);
    log_event("All frames cleared");

    pthread_mutex_unlock(&list_mutex);
}

void destroy_global_frames() {
    clear_all_frames();
    pthread_mutex_destroy(&list_mutex);
}
