    if (log_enabled)
        printf("%s\n", message); // Simple console logging
}

CRCList* create_crc_list(int log_enabled) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate memory for CRCList");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->log_enabled = log_enabled;

    return list;
}

void destroy_crc_list(CRCList* list) {
    if (!list)
        return;

    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);

    log_message("CRCList destroyed");
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(RX_UE_INFORMATION_TAG ue_info, unsigned long rnti) {
