    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(ue_info, rnti);

    pthread_mutex_lock(&list->lock);

    pdu->next = list->head;
    list->head = pdu;

    pthread_mutex_unlock(&list->lock);

    log_message("PDU added to list");

    return pdu;
}

int serialize_list(const CRCList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    log_message("List serialized");

    return 0;
}

CRCList* deserialize_list(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return NULL;
    }

    CRCList* list = create_crc_list(1); // Enable logging during deserialization
    pthread_mutex_lock(&list->lock);

    while (true) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu || fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            free(pdu);
            break;
        }

        pdu->next = list->head;
        list->head = pdu;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    log_message("List deserialized");

    return list;
}
