    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Function prototypes
DoublyLinkedList* create_list();
int add_to_list(DoublyLinkedList *list, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI);
void remove_from_list(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node);
NFAPI_CRC_INDICATION_PDU_T* find_node(DoublyLinkedList *list, unsigned int RNTI);
void serialize_list(const DoublyLinkedList *list, FILE *file);
int deserialize_list(DoublyLinkedList *list, const char *filename);
void destroy_list(DoublyLinkedList *list);

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_to_list(DoublyLinkedList *list, unsigned int RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return -1;

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = NULL;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void remove_from_list(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    if (!list || !node) return;

    pthread_mutex_lock(&list->lock);

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (list->head == node) list->head = node->next;
    if (list->tail == node) list->tail = node->prev;

    pthread_mutex_unlock(&list->lock);

    free(node);
}

NFAPI_CRC_INDICATION_PDU_T* find_node(DoublyLinkedList *list, unsigned int RNTI) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        if (current->data.RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void serialize_list(const DoublyLinkedList *list, FILE *file) {
    if (!list || !file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        fwrite(&current->data, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

int deserialize_list(DoublyLinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    CRC_INDICATION_REL8_TAG data;
    size_t num_items;

    // Get file length to determine number of items
    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    num_items = fsize / sizeof(CRC_INDICATION_REL8_TAG);

    pthread_mutex_lock(&list->lock);

    // Clear existing list
    while (list->head) {
        remove_from_list(list, list->head);
    }

    for (size_t i = 0; i < num_items; ++i) {
        fread(&data, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        add_to_list(list, data.RX_UE_INFORMATION_TAG, data.RNTI);
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

void destroy_list(DoublyLinkedList *list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
