#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define CACHE_SIZE 100

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG *RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG *CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    pthread_mutex_t mutex;
} Cache;

NFAPI_CRC_INDICATION_PDU_T* head = NULL;
pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;
Cache cache;
int cache_hits = 0, cache_misses = 0;

void init_cache() {
    pthread_mutex_init(&cache.mutex, NULL);
    cache.head = NULL;
}

void add_to_cache(uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *data) {
    CacheNode *new_node = (CacheNode *)malloc(sizeof(CacheNode));
    if (!new_node) return;

    new_node->RNTI = rnti;
    new_node->data = data;
    new_node->next = cache.head;
    cache.head = new_node;

    pthread_mutex_lock(&cache.mutex);
    while (cache.head && cache.head->next && (new_node = cache.head)->next) {
        if (--CACHE_SIZE <= 0) {
            NFAPI_CRC_INDICATION_PDU_T *old_data = cache.head->data;
            CacheNode *to_delete = cache.head;
            cache.head = cache.head->next;
            free(to_delete);
            free(old_data->RX_UE_INFORMATION_TAG);
            free(old_data->CRC_INDICATION_REL8_TAG);
            free(old_data);
        }
    }
    pthread_mutex_unlock(&cache.mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_cache(uint16_t rnti) {
    CacheNode *current = cache.head;
    pthread_mutex_lock(&cache.mutex);

    while (current) {
        if (current->RNTI == rnti) {
            cache_hits++;
            NFAPI_CRC_INDICATION_PDU_T *data = current->data;
            // Move accessed node to front
            if (current != cache.head) {
                CacheNode *prev = NULL, *temp = cache.head;
                while (temp && temp != current) {
                    prev = temp;
                    temp = temp->next;
                }
                if (temp) {
                    prev->next = temp->next;
                    temp->next = cache.head;
                    cache.head = temp;
                }
            }
            pthread_mutex_unlock(&cache.mutex);
            return data;
        }
        current = current->next;
    }

    cache_misses++;
    pthread_mutex_unlock(&cache.mutex);
    return NULL;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_rwlock_wrlock(&list_lock);

    new_node->next = head;
    head = new_node;

    pthread_rwlock_unlock(&list_lock);
    add_to_cache(new_node->RX_UE_INFORMATION_TAG->RNTI, new_node);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *cached = get_from_cache(rnti);

    if (cached)
        return cached;

    pthread_rwlock_rdlock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        if (current->RX_UE_INFORMATION_TAG->RNTI == rnti) {
            pthread_rwlock_unlock(&list_lock);
            add_to_cache(rnti, current);
            return current;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list_lock);

    return NULL;
}

void serialize_list(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_rwlock_rdlock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        fwrite(current->RX_UE_INFORMATION_TAG, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&(current->CRC_INDICATION_REL8_TAG->CRCFLAG), sizeof(int), 1, file);
        current = current->next;
    }
    pthread_rwlock_unlock(&list_lock);

    fclose(file);
}

void deserialize_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T *current, **last_ptr = &head;
    while (1) {
        RX_UE_INFORMATION_TAG *rx_tag = malloc(sizeof(RX_UE_INFORMATION_TAG));
        CRC_INDICATION_REL8_TAG *crc_tag = malloc(sizeof(CRC_INDICATION_REL8_TAG));

        if (!rx_tag || !crc_tag || fread(rx_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file) != 1 ||
            fread(&(crc_tag->CRCFLAG), sizeof(int), 1, file) != 1)
            break;

        current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current) {
            free(rx_tag);
            free(crc_tag);
            break;
        }

        current->RX_UE_INFORMATION_TAG = rx_tag;
        current->CRC_INDICATION_REL8_TAG = crc_tag;
        current->next = NULL;

        *last_ptr = current;
        last_ptr = &current->next;
    }
    fclose(file);

    pthread_rwlock_wrlock(&list_lock);
    pthread_rwlock_unlock(&list_lock);
}

void free_list() {
    pthread_rwlock_wrlock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *current = head, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp->RX_UE_INFORMATION_TAG);
        free(temp->CRC_INDICATION_REL8_TAG);
        free(temp);
    }
    head = NULL;
    pthread_rwlock_unlock(&list_lock);

    pthread_mutex_lock(&cache.mutex);
    while (cache.head) {
        CacheNode *to_delete = cache.head;
        cache.head = to_delete->next;
        free(to_delete->data->RX_UE_INFORMATION_TAG);
        free(to_delete->data->CRC_INDICATION_REL8_TAG);
        free(to_delete->data);
        free(to_delete);
    }
    pthread_mutex_unlock(&cache.mutex);
}

int main() {
    init_cache();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->RX_UE_INFORMATION_TAG = malloc(sizeof(RX_UE_INFORMATION_TAG));
    new_pdu->CRC_INDICATION_REL8_TAG = malloc(sizeof(CRC_INDICATION_REL8_TAG));

    new_pdu->RX_UE_INFORMATION_TAG->RNTI = 1;
    new_pdu->CRC_INDICATION_REL8_TAG->CRCFLAG = rand() % 2;

    add_pdu(new_pdu);

    serialize_list("nfa_data.bin");
    deserialize_list("nfa_data.bin");

    free_list();

    return 0;
}
