typedef struct {
    Node** buckets;
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock;
} HashMap;

HashMap* create_hash_map(size_t capacity) {
    HashMap* map = malloc(sizeof(HashMap));
    map->buckets = calloc(capacity, sizeof(Node*));
    map->capacity = capacity;
    atomic_store(&map->size, 0);
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

unsigned long hash(uint16_t rnti, size_t capacity) {
    return (rnti * 2654435761UL) % capacity; // FNV-1a hash
}

int insert_to_hash_map(HashMap* map, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned long index = hash(pdu.RNTI, map->capacity);
    pthread_mutex_lock(&map->lock);

    Node* node = map->buckets[index];
    while (node != NULL) {
        if (node->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&map->lock);
            return 0; // Duplicate RNTI
        }
        node = node->next;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;

    atomic_fetch_add(&map->size, 1);
    pthread_mutex_unlock(&map->lock);

    return 1; // Inserted
}

int hashmap_size(HashMap* map) {
    return atomic_load(&map->size);
}

void free_hash_map(HashMap* map) {
    for (size_t i = 0; i < map->capacity; ++i) {
        Node* node = map->buckets[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(map->buckets);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

