    }

    log_message("PDU array successfully allocated and initialized.");
    *allocated_size = size;

    pthread_mutex_unlock(&allocation_mutex);
    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t size) {
    if (pdu_array) {
        free(pdu_array);
        log_message("PDU array successfully freed.");
    }
}

