DynamicArray* init_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_ENTRIES) {
        return NULL;
    }

    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) {
        perror("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    dyn_array->array = malloc(initial_capacity * sizeof(DataTransferObject));
    if (!dyn_array->array) {
        free(dyn_array);
        perror("Failed to allocate memory for DataTransferObjects");
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    return dyn_array;
}

void resize_dynamic_array(DynamicArray *dyn_array, size_t new_capacity) {
    if (new_capacity > MAX_ENTRIES) {
        fprintf(stderr, "Exceeded maximum allowed capacity\n");
        return;
    }

    DataTransferObject *temp = realloc(dyn_array->array, new_capacity * sizeof(DataTransferObject));
    if (!temp) {
        perror("Failed to reallocate memory for DataTransferObjects");
        exit(EXIT_FAILURE);
    }
    dyn_array->array = temp;
    dyn_array->capacity = new_capacity;
