typedef struct {
    unsigned long x, y, z;
} PRNGState;

// Initialize the PRNG state
void initPRNG(PRNGState* state, unsigned long seed) {
    state->x = seed ? seed : 123456789UL;
    state->y = 362436069UL;
    state->z = 521288629UL;
}

// Generate the next pseudo-random number
unsigned int prngNext(PRNGState* state) {
    unsigned long t;
    t = state->x ^ (state->x << 11);
    state->x = state->y; 
    state->y = state->z; 
    t ^= (t >> 8);
    state->z = t ^ (state->z >> 19);
    return (unsigned int)(t & 0xFFFFFFFFUL);
}

