    CRC_INDICATION_REL8_TAG crc_tag;
    // Additional fields can be added here easily
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    atomic_size_t size;
    atomic_size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *elements;
    pthread_mutex_t mutex;  // For resizing, if needed
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->size = 0;
    array->capacity = 10;  // Initial small capacity for growth efficiency
    array->elements = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->elements == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->mutex, NULL);
}

void free_dynamic_array(DynamicArray *array) {
    free(array->elements);
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_destroy(&array->mutex);
}

void resize_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(array->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_elements == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->mutex);
}

void add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    size_t current_size = atomic_load(&array->size);
    if (current_size >= atomic_load(&array->capacity)) {
        resize_dynamic_array(array);
    }
    array->elements[current_size] = element;
    atomic_store(&array->size, current_size + 1);
}

NFAPI_CRC_INDICATION_PDU_T create_random_pdu(uint8_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.crc_tag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu.crc_tag.RNTI = RNTI;
    srand(time(NULL) + pthread_self());  // Seed with time and thread ID
    pdu.crc_tag.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

void *thread_function(void *arg) {
    DynamicArray *array = (DynamicArray *)arg;
    for (int i = 0; i < 100; ++i) {  // Simulating 100 requests per second per thread
        NFAPI_CRC_INDICATION_PDU_T pdu = create_random_pdu(rand() % 256, rand() % 65536);
        add_element(array, pdu);
    }
    return NULL;
}

int main() {
    DynamicArray array;
    init_dynamic_array(&array);

    const int num_threads = 100;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &array)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final array size: %zu\n", atomic_load(&array.size));

    free_dynamic_array(&array);

    return 0;
}
