bool validate_tag(int tag) {
    // Placeholder for actual validation logic
    return tag >= 0 && tag <= 1000; // Example range
}

bool validate_rnti(int rnti) {
    // Placeholder for actual validation logic
    return rnti > 0 && rnti < 65535; // Example range
}

void log_message(const char* message) {
    printf("LOG: %s\n", message);
