NFALIST* create_nfa_list() {
    NFALIST* list = (NFALIST*)malloc(sizeof(NFALIST));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    log_message("NFALIST created");
    return list;
}

bool add_to_nfa_list(NFALIST* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!validate_tag(element.RX_UE_INFORMATION_TAG) || !validate_rnti(element.RNTI)) {
        log_message("Invalid tag or RNTI");
        return false;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        log_message("NFALIST full");
        return false;
    }

    element.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    list->elements[list->count++] = element;

    pthread_mutex_unlock(&list->lock);
    log_message("Element added");

    return true;
}

bool serialize_nfa_list(NFALIST* list, const char* filename) {
    if (!filename || !list) return false;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("File open failed");
        return false;
    }

    pthread_mutex_lock(&list->lock);

    size_t written = fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    bool success = (written == list->count);

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    if (!success) log_message("Serialization failed");
    else log_message("List serialized");

    return success;
}

bool deserialize_nfa_list(NFALIST* list, const char* filename) {
    if (!filename || !list) return false;

    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message("File open failed");
        return false;
    }

    pthread_mutex_lock(&list->lock);

    size_t count = fread(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ELEMENTS, file);
    list->count = (count == MAX_ELEMENTS) ? MAX_ELEMENTS : count;

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    if (ferror(file)) {
        log_message("Deserialization failed");
        return false;
    }

    log_message("List deserialized");
    return true;
}

void destroy_nfa_list(NFALIST* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    free(list->elements);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);

    log_message("NFALIST destroyed");
}

