    success = deserialize_nfa_list(new_list, filename);
    if (!success) {
        printf("Test failed: Deserialization\n");
        destroy_nfa_list(list);
        destroy_nfa_list(new_list);
        return;
    }

    printf("All tests passed!\n");

    destroy_nfa_list(list);
    destroy_nfa_list(new_list);
}

int main() {
    run_tests();
    return 0;
}
