#define MAX_MACSDU_SIZE 256 // Maximum allowed size of all MACSDUs in a PDU

typedef struct {
    unsigned int control;
    unsigned int length;
} MAC_HEADER;

typedef struct {
    unsigned char data[64]; // Arbitrary fixed size for each MACSDU element
    unsigned int size;
} MACSDU;

typedef struct {
    MAC_HEADER header;
    MACSDU *macSdus;
    unsigned int macSduCount;
    unsigned int totalMacSduSize; // Track the total size of all MACSDUs in this PDU
} MAC_PDU;

MAC_PDU* initMacPdu() {
    MAC_PDU *pdu = (MAC_PDU *)malloc(sizeof(MAC_PDU));
    if (!pdu) return NULL;

    pdu->macSdus = NULL;
    pdu->macSduCount = 0;
    pdu->totalMacSduSize = 0;

    // Initialize MAC_HEADER
    pdu->header.control = 0;     // Example control field initialization
    pdu->header.length = 0;      // Will be updated as MACSDUs are added

    return pdu;
}

int addMacSdu(MAC_PDU *pdu, const unsigned char *data, unsigned int size) {
    if (size == 0 || !pdu || pdu->totalMacSduSize + size > MAX_MACSDU_SIZE) {
        return -1; // Invalid input or would exceed maximum allowed size
    }

    // Calculate the new required capacity for MACSDUs
    unsigned int newCapacity = pdu->macSduCount + 1;

    // Allocate memory if necessary, or expand current allocation
    MACSDU *newMacSdus = (MACSDU *)realloc(pdu->macSdus, newCapacity * sizeof(MACSDU));
    if (!newMacSdus) return -2; // Memory allocation failed

    pdu->macSdus = newMacSdus;

    // Add the new MACSDU element
    pdu->macSdus[pdu->macSduCount].size = size;
    for (unsigned int i = 0; i < size && i < sizeof(pdu->macSdus[pdu->macSduCount].data); ++i) {
        pdu->macSdus[pdu->macSduCount].data[i] = data[i];
    }

    // Update PDU's total MACSDU size and header length
    pdu->totalMacSduSize += size;
    pdu->header.length = pdu->totalMacSduSize;

    // Increment the count of MACSDUs in this PDU
    pdu->macSduCount++;

    return 0; // Success
}

void freeMacPdu(MAC_PDU *pdu) {
    if (pdu) {
        free(pdu->macSdus);
        free(pdu);
    }
}
```

This code defines a `MAC_PDU` structure with methods to initialize, add MACSDU elements while respecting memory constraints, and clean up resources. It uses dynamic allocation for efficiency and handles edge cases like insufficient memory gracefully. The use of realloc helps in minimizing fragmentation by expanding the existing memory block instead of allocating new ones frequently."]

['Below is an example implementation in C using POSIX Threads (pthreads) and mutexes for managing concurrency:

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define INITIAL_SIZE 10
#define MAX_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    time_t *timestamps;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->size = 0;
    da->capacity = INITIAL_SIZE;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->timestamps = malloc(INITIAL_SIZE * sizeof(time_t));
    pthread_mutex_init(&da->lock, NULL);
    pthread_cond_init(&da->cond_var, NULL);
    return da;
}

void resize_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    size_t new_capacity = da->capacity * 2;
    if (new_capacity > MAX_SIZE) {
        pthread_mutex_unlock(&da->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    time_t *new_timestamps = realloc(da->timestamps, new_capacity * sizeof(time_t));

    if (new_array && new_timestamps) {
        da->array = new_array;
        da->timestamps = new_timestamps;
        da->capacity = new_capacity;
    }

    pthread_mutex_unlock(&da->lock);
}

void add_structure(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T structure) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        resize_dynamic_array(da);
    }

    if (da->size < da->capacity) {
        da->array[da->size] = structure;
        da->timestamps[da->size] = time(NULL);
        ++da->size;

        pthread_cond_signal(&da->cond_var);
    }

    pthread_mutex_unlock(&da->lock);
}

void clear_old_structures(DynamicArray *da, int timeout) {
    while (1) {
        sleep(timeout);

        pthread_mutex_lock(&da->lock);

        time_t now = time(NULL);
        size_t i = 0;
        for (size_t j = 0; j < da->size; ++j) {
            if (now - da->timestamps[j] > timeout) {
                memmove(&da->array[i], &da->array[j], sizeof(NFAPI_CRC_INDICATION_PDU_T));
                da->timestamps[i] = da->timestamps[j];
                ++i;
            }
        }
        da->size = i;

        pthread_mutex_unlock(&da->lock);
    }
}

void* process_structures(void *arg) {
    DynamicArray *da = (DynamicArray *)arg;
    while (1) {
        pthread_mutex_lock(&da->lock);

        while (da->size == 0) {
            pthread_cond_wait(&da->cond_var, &da->lock);
        }

        for (size_t i = 0; i < da->size; ++i) {
            // Process each structure
            printf("Processing structure with RNTI: %d\n", da->array[i].crc_tag.RNTI);
        }

        pthread_mutex_unlock(&da->lock);

        usleep(100000);  // Simulate processing time
    }
}

int main() {
    DynamicArray *da = create_dynamic_array();

    pthread_t clear_thread, process_thread;

    pthread_create(&clear_thread, NULL, (void*)clear_old_structures, da);
    pthread_create(&process_thread, NULL, (void*)process_structures, da);

    for (size_t i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T structure;
        structure.crc_tag.RX_UE_INFORMATION_TAG = rand();
        structure.crc_tag.RNTI = rand();
        structure.crc_tag.CRCFLAG = rand() % 2;

        add_structure(da, structure);
    }

    pthread_join(clear_thread, NULL);
    pthread_join(process_thread, NULL);

    free(da->array);
    free(da->timestamps);
    free(da);

    return 0;
}
```

### Key Components:
- **Dynamic Array Management**: The code handles dynamic resizing of the array using `realloc`.
- **Concurrency Control**: Mutexes and condition variables manage concurrent access to the shared data structure.
- **Background Clearing**: A separate thread periodically clears old structures based on a timeout.
- **Efficient Waiting**: Threads wait for new data using condition variables, minimizing unnecessary blocking.
- **Error Handling**: Basic checks ensure safe memory operations. Further robustness can be added as needed.

This implementation ensures that the array is dynamically resized and managed efficiently across multiple threads while addressing concurrency issues and optimizing resource usage.']

