#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// External logging library headers assumed to be included here

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    unsigned int size;
} List;

// Function prototypes
void initialize_list(List* list);
void destroy_list(List* list);
int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_pdu_by_rnti(List* list, unsigned int rnti);
void log_message(const char* message);
NFAPI_CRC_INDICATION_PDU_T create_pdu(unsigned int rx_ue_info_tag, unsigned int rnti);

// Initialize the list
void initialize_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
}

// Destroy the list and free memory
void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}

// Add a new PDU to the list
int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Error: Memory allocation failed.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // Validate integrity
    if (new_node->data.crc_tag.CRCFLAG == 0) {
        log_message("Warning: CRCFLAG is not set.");
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Remove a PDU by RNTI
int remove_pdu_by_rnti(List* list, unsigned int rnti) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        log_message("Error: PDU not found.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Log a message with a timestamp
void log_message(const char* message) {
    time_t now = time(NULL);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

    // Assume an external logging function is used here
    printf("[%s] %s\n", buffer, message);
}

// Create a new PDU with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T create_pdu(unsigned int rx_ue_info_tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu.RNTI = rnti;
    pdu.crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    List list;
    initialize_list(&list);

    for (unsigned int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(i, i);
        add_pdu(&list, pdu);
    }

    destroy_list(&list);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure that list operations are thread-safe.
- **Dynamic Memory Management**: Allocates and frees memory dynamically for each node in the linked list.
- **Logging**: Integrates a simple logging mechanism with timestamps. Replace with an external library as needed.
- **Data Integrity**: Validates CRCFLAG upon creation, logging warnings if necessary.
- **Efficient Access**: Supports adding and removing elements efficiently with minimal locking overhead.

This code is designed to handle large-scale datasets and concurrent access while minimizing performance degradation.']

