#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 65535

typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[2];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_rwlock_t lock;
    unsigned long elements_added;
    unsigned long elements_removed;
} DoublyLinkedList;

void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
    list->elements_added = 0;
    list->elements_removed = 0;
}

int validate_rnti(unsigned short rnti) {
    return rnti >= 1 && rnti <= MAX_RNTI;
}

void* get_random_crc_flag() {
    return (void*)(rand() % 2);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    *(&node->data) = *data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void add_element(DoublyLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_rwlock_wrlock(&list->lock);
    Node* new_node = create_node(data);

    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    list->elements_added++;

    pthread_rwlock_unlock(&list->lock);
}

void remove_element(DoublyLinkedList* list) {
    pthread_rwlock_wrlock(&list->lock);

    if (list->head == NULL) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    Node* node = list->head;
    list->head = list->head->next;

    if (list->head != NULL) {
        list->head->prev = NULL;
    } else {
        list->tail = NULL;
    }

    free(node);
    list->size--;
    list->elements_removed++;

    pthread_rwlock_unlock(&list->lock);
}

void clear_list(DoublyLinkedList* list) {
    pthread_rwlock_wrlock(&list->lock);

    while (list->head != NULL) {
        remove_element(list);
    }

    pthread_rwlock_unlock(&list->lock);
}

int update_rnti_from_source(unsigned short *rnti) {
    // Simulate external data source update with retry logic
