    while (retries--) {
        *rnti = (unsigned short)(rand() % MAX_RNTI + 1);
        if (validate_rnti(*rnti)) {
            return 0; // Success
        }
    }
    fprintf(stderr, "Failed to update RNTI from external source after retries\n");
    return -1;
}

void free_list(DoublyLinkedList* list) {
    clear_list(list);
    pthread_rwlock_destroy(&list->lock);
    printf("Elements added: %lu, Elements removed: %lu\n", list->elements_added, list->elements_removed);
}

int main() {
    srand(time(NULL));

    DoublyLinkedList list;
    init_list(&list);

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        if (update_rnti_from_source(&pdu.RNTI) != 0) continue; // Skip invalid RNTI
        memcpy(pdu.CRC_INDICATION_REL8_TAG, get_random_crc_flag(), sizeof(pdu.CRC_INDICATION_REL8_TAG));
        pdu.CRCFLAG = *(int*)get_random_crc_flag();

        add_element(&list, &pdu);
    }

    for (int i = 0; i < 10000 / 2; ++i) {
        remove_element(&list);
    }

    free_list(&list);

    return 0;
}
