typedef struct {
    char CLIENT_IP[16];
    char SERVER_IP[16];
    time_t CONNECTION_TIMESTAMP;
    unsigned long BYTE_COUNT;
} TCP_CONNECTION_RECORD;

#define INITIAL_CAPACITY 1000
#define LOAD_FACTOR 2

typedef struct {
    TCP_CONNECTION_RECORD *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionList;

// Function prototypes
ConnectionList* create_connection_list();
int add_record(ConnectionList *list, const char *client_ip, const char *server_ip, unsigned long byte_count);
void resize_if_needed(ConnectionList *list);
TCP_CONNECTION_RECORD* find_record_by_time(ConnectionList *list, time_t start_time, time_t end_time);

// Implementations
ConnectionList* create_connection_list() {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    list->records = malloc(INITIAL_CAPACITY * sizeof(TCP_CONNECTION_RECORD));
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_record(ConnectionList *list, const char *client_ip, const char *server_ip, unsigned long byte_count) {
    pthread_mutex_lock(&list->lock);

    if (byte_count <= 0 || strlen(client_ip) >= 16 || strlen(server_ip) >= 16) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid data
    }

    resize_if_needed(list);

    TCP_CONNECTION_RECORD *record = &list->records[list->count];
    strcpy(record->CLIENT_IP, client_ip);
    strcpy(record->SERVER_IP, server_ip);
    record->CONNECTION_TIMESTAMP = time(NULL);
    record->BYTE_COUNT = byte_count;

    list->count++;
    pthread_mutex_unlock(&list->lock);

    // Integration with external monitoring library (pseudo-code)
    // monitor_log("Record added", client_ip, server_ip, record->CONNECTION_TIMESTAMP, byte_count);

    return 0;
}

void resize_if_needed(ConnectionList *list) {
    if ((float)list->count / list->capacity >= LOAD_FACTOR - 0.5) {
        size_t new_capacity = list->capacity * LOAD_FACTOR;
        list->records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD));
        list->capacity = new_capacity;
    }
}

TCP_CONNECTION_RECORD* find_record_by_time(ConnectionList *list, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].CONNECTION_TIMESTAMP >= start_time && 
            list->records[i].CONNECTION_TIMESTAMP <= end_time) {

            // Copying the record to avoid returning a pointer to potentially reallocated memory
            TCP_CONNECTION_RECORD *result = malloc(sizeof(TCP_CONNECTION_RECORD));
            memcpy(result, &list->records[i], sizeof(TCP_CONNECTION_RECORD));

            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // No record found
}

void destroy_connection_list(ConnectionList *list) {
    if (list) {
        free(list->records);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
