                fprintf(file, "Frame %d: Success=%lu, Failures=%lu\n",
                        nfa_rx_frames[i].rx_frame_tag.frame_number,
                        nfa_rx_frames[i].phy_stats_tag.successful_decodings,
                        nfa_rx_frames[i].phy_stats_tag.failed_decodings);
            }
            fclose(file);
        }

        pthread_mutex_unlock(&mutex);

        // Simulate a delay
        sleep(10);  // Adjust the interval as needed for your application.
    }
    return NULL;
}

int main() {
    size_t n = 100;  // Example frame count

    if (init_nfa_rx_frames(n) != 0) {
        fprintf(stderr, "Failed to initialize NFA_RX_FRAME structures.\n");
        return EXIT_FAILURE;
    }

    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, flush_statistics, NULL);

    // Update statistics and simulate concurrent access
    update_statistics(10, 1, 0);
    update_statistics(20, 0, 2);

    // Join the thread to handle graceful shutdown.
    pthread_join(flush_thread, NULL);

    return EXIT_SUCCESS;
}
