    pthread_mutex_lock(&global_lock);

    if (!is_rnti_valid(rnti)) {
        log_invalid_rnti(rnti);
        pthread_mutex_unlock(&global_lock);
        return;
    }

    unsigned int index = hash_rnti(rnti);
    RNTI_MAP_ENTRY *entry = &hash_table[index];

    while (entry->node) {
        if (entry->rnti == rnti) {
            // RNTI already exists
            pthread_mutex_unlock(&global_lock);
            return;
        }
        entry++;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(rnti, crc_abstraction.generate_crc(NULL, 0));
    if (!new_node) {
        pthread_mutex_unlock(&global_lock);
        return;
    }

    // Insert into hash table
    entry->rnti = rnti;
    entry->node = new_node;

    // Link in the linked list
    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *temp = *head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&global_lock);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **head) {
    NFAPI_CRC_INDICATION_PDU_T *current = *head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
