#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint8_t *TX_PDU;
    size_t TX_PDU_len;
} MAC_TX_BUFFER_T;

typedef struct {
    MAC_TX_BUFFER_T* buffers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    uint32_t last_seq_num;  // To ensure uniqueness of SEQ_NUM
} DynamicArray;

// Initialize the dynamic array module
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    pthread_mutex_init(&da->lock, NULL);
    da->buffers = malloc(initial_capacity * sizeof(MAC_TX_BUFFER_T));
    if (!da->buffers) {
        free(da);
        return NULL;
    }

    da->count = 0;
    da->capacity = initial_capacity;
    da->last_seq_num = 0;

    return da;
}

// Ensure unique SEQ_NUM and insert a new buffer
int insert_buffer(DynamicArray* da, uint8_t *TX_PDU, size_t TX_PDU_len) {
    pthread_mutex_lock(&da->lock);

    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        MAC_TX_BUFFER_T* new_buffers = realloc(da->buffers, new_capacity * sizeof(MAC_TX_BUFFER_T));
        if (!new_buffers) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Out of memory
        }
        da->buffers = new_buffers;
        da->capacity = new_capacity;
    }

    MAC_TX_BUFFER_T* buffer = &da->buffers[da->count++];
    buffer->TX_PDU = malloc(TX_PDU_len);
    if (!buffer->TX_PDU) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Out of memory
    }
    memcpy(buffer->TX_PDU, TX_PDU, TX_PDU_len);
    buffer->TX_PDU_len = TX_PDU_len;

    uint32_t seq_num = ++da->last_seq_num;  // Generate unique SEQ_NUM

    pthread_mutex_unlock(&da->lock);

    return (int)seq_num;
}

// Retrieve a buffer by index
MAC_TX_BUFFER_T* get_buffer(DynamicArray* da, size_t index) {
    if (index >= da->count) return NULL;

    pthread_mutex_lock(&da->lock);
    MAC_TX_BUFFER_T* buffer = &da->buffers[index];
    pthread_mutex_unlock(&da->lock);

    return buffer;
}

// Free resources
void free_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        free(da->buffers[i].TX_PDU);
    }

    free(da->buffers);

    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
    free(da);
}
