    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash map structure to store RNTIs for fast lookup.
typedef struct {
    bool *map;
    size_t size;
    pthread_mutex_t lock;
} RNTI_Map;

static RNTI_Map rnti_map = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// CRC generation function abstracted for future flexibility.
int generate_crc_flag() {
    // Placeholder implementation.
    return rand() % 2;
}

// Initializes the hash map.
void init_rnti_map(size_t size) {
    pthread_mutex_lock(&rnti_map.lock);
    if (rnti_map.size == 0) {
        rnti_map.map = calloc(size, sizeof(bool));
        rnti_map.size = size;
    }
    pthread_mutex_unlock(&rnti_map.lock);
}

// Frees the hash map.
void free_rnti_map() {
    pthread_mutex_lock(&rnti_map.lock);
    if (rnti_map.map) {
        free(rnti_map.map);
        rnti_map.map = NULL;
    }
    rnti_map.size = 0;
    pthread_mutex_unlock(&rnti_map.lock);
}

// Checks if the RNTI is unique and within valid range.
bool add_rnti(RNTI rnti) {
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        printf("RNTI %u out of range.\n", rnti);
        return false;
    }

    size_t index = rnti % rnti_map.size;
    pthread_mutex_lock(&rnti_map.lock);

    if (!rnti_map.map[index]) {
        rnti_map.map[index] = true;
        pthread_mutex_unlock(&rnti_map.lock);
        return true;
    }

    pthread_mutex_unlock(&rnti_map.lock);
    return false;
}

// Adds a new entry to the linked list.
NFAPI_CRC_INDICATION_PDU_T* add_entry(NFAPI_CRC_INDICATION_PDU_T** head) {
    RNTI rnti;
    do {
        rnti = (RNTI)(rand() % (MAX_RNTI - MIN_RNTI + 1)) + MIN_RNTI;
    } while (!add_rnti(rnti));

    NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        return NULL; // Memory allocation failed.
    }

    // Initialize the fields of the new entry.
    memset(&new_entry->rx_ue_information_tag, 0, sizeof(new_entry->rx_ue_information_tag));
    new_entry->rnti = rnti;
    new_entry->crc_indication_rel8_tag.CRCFLAG = generate_crc_flag();
    new_entry->next = *head;

    pthread_mutex_t entry_lock = PTHREAD_MUTEX_INITIALIZER;
    new_entry->lock = &entry_lock; // Assign lock to the node.

    *head = new_entry;

    return new_entry;
}

// Function to periodically purge old entries.
void purge_entries(NFAPI_CRC_INDICATION_PDU_T** head) {
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current) {
        pthread_mutex_t* entry_lock = &current->lock;

        // Example condition for purging, modify as needed.
        if (current->crc_indication_rel8_tag.CRCFLAG == 0) { 
            NFAPI_CRC_INDICATION_PDU_T* to_delete = current;
            current = current->next;

            pthread_mutex_lock(entry_lock);
            free_rnti_map_entry(to_delete->rnti); // Custom function to remove RNTI from map.
            pthread_mutex_unlock(entry_lock);

            free(to_delete);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list_lock);
}

void free_rnti_map_entry(RNTI rnti) {
    size_t index = rnti % rnti_map.size;

    pthread_mutex_lock(&rnti_map.lock);
    if (rnti_map.map[index]) {
        rnti_map.map[index] = false;
    }
    pthread_mutex_unlock(&rnti_map.lock);
}

// Example usage.
int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    init_rnti_map(65536); // Initialize with a size larger than max RNTI range.

    for (int i = 0; i < 1000; ++i) { 
        add_entry(&head);
    }

    purge_entries(&head);

    free_rnti_map();

    return 0;
}
