#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define INITIAL_SIZE 10
#define MAX_BUFFER_SIZE 1024 * 1024 // Example maximum buffer size constraint
#define REALLOC_THRESHOLD 0.75

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t current_size, size_t max_size) {
    printf("Current memory usage: %zu bytes\n", current_size);
    if (current_size * 1.0 / max_size > REALLOC_THRESHOLD) {
        printf("Warning: Memory usage approaching threshold.\n");
    }
}

int allocate_nfa_list(NFAPI_CRC_INDICATION_PDU_T ***list, size_t *num_entries) {
    pthread_mutex_lock(&lock);

    if (*list == NULL) {
        *list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(INITIAL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (*list == NULL) {
            fprintf(stderr, "Memory allocation error: Initial allocation failed.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    size_t current_size = INITIAL_SIZE;

    while (current_size <= MAX_BUFFER_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        if (*num_entries >= current_size) {
            size_t new_size = current_size * 2;
            NFAPI_CRC_INDICATION_PDU_T **temp_list =
                (NFAPI_CRC_INDICATION_PDU_T **)realloc(*list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));

            if (temp_list == NULL) {
                fprintf(stderr, "Memory allocation error: Re-allocation failed.\n");
                pthread_mutex_unlock(&lock);
                return -1;
            }

            for (size_t i = current_size; i < new_size; ++i) {
                temp_list[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (temp_list[i] == NULL) {
                    fprintf(stderr, "Memory allocation error: Structure allocation failed.\n");

                    // Free previously allocated structures
                    for (size_t j = 0; j < i; ++j) {
                        free(temp_list[j]);
                    }
                    free(temp_list);
                    pthread_mutex_unlock(&lock);
                    return -1;
                }

                temp_list[i]->RX_UE_INFORMATION_TAG = rand(); // Random value for example
                temp_list[i]->RNTI = rand() % 65536;          // Random RNTI for example
                temp_list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
            }

            *list = temp_list;
            current_size = new_size;

            log_memory_usage(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_BUFFER_SIZE);
        } else {
            break;
        }
    }

    pthread_mutex_unlock(&lock);

    return 0;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_entries) {
    if (list == NULL)
        return;

    for (size_t i = 0; i < num_entries; ++i) {
        if (list[i] != NULL) {
            free(list[i]);
        }
    }

    free(list);
}

void safe_free_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *num_entries) {
    pthread_mutex_lock(&lock);

    if (*list != NULL) {
        free_nfa_list(*list, *num_entries);
        *list = NULL;
    }

    *num_entries = 0;

    pthread_mutex_unlock(&lock);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T **nfa_list = NULL;
    size_t num_entries = 0;

    if (allocate_nfa_list(&nfa_list, &num_entries) != 0) {
        fprintf(stderr, "Failed to allocate memory for NF list.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    num_entries += 1; // Add entries as needed

    safe_free_nfa_list(nfa_list, &num_entries);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
```

