#define MAX_SESSION_COUNT 10000

typedef struct {
    uint32_t rnti;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    bool crcFlag;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

