// Global variables for session management
static pthread_mutex_t rntiMutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned int currentSessionCount = 0;
static uint32_t usedRNTIs[MAX_SESSION_COUNT];
static bool initialized = false;

void init_global_variables() {
    if (!initialized) {
        pthread_mutex_lock(&rntiMutex);
        if (!initialized) { // Double-check locking
            for (int i = 0; i < MAX_SESSION_COUNT; ++i) {
                usedRNTIs[i] = 0;
            }
            initialized = true;
        }
        pthread_mutex_unlock(&rntiMutex);
    }
}

bool is_rnti_used(uint32_t rnti) {
    pthread_mutex_lock(&rntiMutex);
    bool found = false;
    for (int i = 0; i < currentSessionCount && !found; ++i) {
        if (usedRNTIs[i] == rnti) {
            found = true;
        }
    }
    pthread_mutex_unlock(&rntiMutex);
    return found;
}

void mark_rnti_as_used(uint32_t rnti) {
    pthread_mutex_lock(&rntiMutex);
    usedRNTIs[currentSessionCount++] = rnti;
    pthread_mutex_unlock(&rntiMutex);
}

int generate_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* list, int count, const char* configFile) {
    if (currentSessionCount + count > MAX_SESSION_COUNT) {
        return -1; // Error code for session limit exceeded
    }

    FILE *config = fopen(configFile, "r");
    if (!config) {
        perror("Error opening configuration file");
        return -2;
    }

    // Read configuration parameters from the file as needed

    fclose(config);

    for (int i = 0; i < count; ++i) {
        uint32_t rnti;
        bool validRNTI;

        do {
            validRNTI = false;
            // Generate a random RNTI
            rnti = rand() % 0xFFFFF; // Example range for RNTI

            if (!is_rnti_used(rnti)) {
                validRNTI = true;
                mark_rnti_as_used(rnti);
            }
        } while (!validRNTI);

        list[i].ueInfoTag.rnti = rnti;
        list[i].rnti = rnti;

        // Set CRC flag randomly
        list[i].crcTag.crcFlag = rand() % 2 == 0;

        // Log the creation of each structure
        printf("Created NFAPI_CRC_INDICATION_PDU_T with RNTI: %u\n", rnti);
    }

    return 0; // Success code
}

int main() {
    init_global_variables();

    const int numStructures = 100; // Example number of structures to generate
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        perror("Memory allocation failed");
        return -1;
    }

    int result = generate_crc_indication_pdu_list(pduList, numStructures, "config.txt");

    if (result == 0) {
        // Successfully generated the list
    } else {
        printf("Error: %d\n", result);
    }

    free(pduList);

    return 0;
}
