// Define constants for DCI size and other parameters
#define MAX_DCI_SIZE 128 // Example maximum size, can be adjusted

typedef struct {
    unsigned int UE_ID;
    char *DCI; // Dynamic array to store DCI content
} LTE_PDSCH_SchedulingInfo;

typedef struct {
    LTE_PDSCH_SchedulingInfo **info_list;
    size_t list_size;
    pthread_mutex_t lock;
    size_t capacity;
} SchedulingManager;

void initSchedulingManager(SchedulingManager *manager, size_t initial_capacity) {
    manager->info_list = malloc(initial_capacity * sizeof(LTE_PDSCH_SchedulingInfo *));
    manager->list_size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void freeSchedulingManager(SchedulingManager *manager) {
    for (size_t i = 0; i < manager->list_size; ++i) {
        free(manager->info_list[i]->DCI);
        free(manager->info_list[i]);
    }
    free(manager->info_list);
    pthread_mutex_destroy(&manager->lock);
}

void addSchedulingInfo(SchedulingManager *manager, unsigned int UE_ID, const char *dci_content, size_t dci_size) {
    pthread_mutex_lock(&manager->lock);

    if (manager->list_size == manager->capacity) {
        // Double the capacity to handle more entries
        manager->capacity *= 2;
        manager->info_list = realloc(manager->info_list, manager->capacity * sizeof(LTE_PDSCH_SchedulingInfo *));
    }

    LTE_PDSCH_SchedulingInfo *new_info = malloc(sizeof(LTE_PDSCH_SchedulingInfo));
    new_info->UE_ID = UE_ID;

    // Allocate DCI content ensuring it adheres to 3GPP standards
    size_t adjusted_dci_size = (dci_size > MAX_DCI_SIZE) ? MAX_DCI_SIZE : dci_size;
    new_info->DCI = malloc(adjusted_dci_size);
    strncpy(new_info->DCI, dci_content, adjusted_dci_size);

    manager->info_list[manager->list_size++] = new_info;

    pthread_mutex_unlock(&manager->lock);
}

void adjustDCISize(SchedulingManager *manager, unsigned int UE_ID, size_t new_dci_size) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->list_size; ++i) {
        if (manager->info_list[i]->UE_ID == UE_ID) {
            char *new_dci_content = realloc(manager->info_list[i]->DCI, new_dci_size);
            if (!new_dci_content) {
                // Handle memory allocation failure
                pthread_mutex_unlock(&manager->lock);
                return;
            }
            manager->info_list[i]->DCI = new_dci_content;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void removeSchedulingInfo(SchedulingManager *manager, unsigned int UE_ID) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->list_size; ++i) {
        if (manager->info_list[i]->UE_ID == UE_ID) {
            free(manager->info_list[i]->DCI);
            free(manager->info_list[i]);
            // Shift remaining elements
            memmove(&manager->info_list[i], &manager->info_list[i + 1],
                    (manager->list_size - i - 1) * sizeof(LTE_PDSCH_SchedulingInfo *));
            manager->list_size--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
