```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define MAX_CONNECTIONS 1000

typedef struct {
    int tcp_socket;
    char remote_address[256];
    unsigned short port_number;
} TCP_CONNECTION_INFO;

typedef struct {
    TCP_CONNECTION_INFO *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->connections = malloc(manager->capacity * sizeof(TCP_CONNECTION_INFO));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_connections(ConnectionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    if (new_capacity > MAX_CONNECTIONS) {
        printf("Max connection limit reached. Cannot resize further.\n");
        return;
    }

    TCP_CONNECTION_INFO *new_connections = realloc(manager->connections, new_capacity * sizeof(TCP_CONNECTION_INFO));
    if (!new_connections) {
        printf("Error resizing connections: %s\n", strerror(errno));
        return;
    }

    manager->connections = new_connections;
    manager->capacity = new_capacity;
}

void add_connection(ConnectionManager *manager, int tcp_socket, const char *remote_address, unsigned short port_number) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_connections(manager);
    }

    if (manager->count < manager->capacity && manager->count < MAX_CONNECTIONS) {
        TCP_CONNECTION_INFO *conn = &manager->connections[manager->count++];
        conn->tcp_socket = tcp_socket;
        strncpy(conn->remote_address, remote_address, sizeof(conn->remote_address));
        conn->port_number = port_number;
    }

    pthread_mutex_unlock(&manager->lock);
}

int find_connection_index(ConnectionManager *manager, const char *remote_address, unsigned short port_number) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->connections[i].remote_address, remote_address) == 0 &&
            manager->connections[i].port_number == port_number) {
            return i;
        }
    }
    return -1;
}

void remove_connection(ConnectionManager *manager, const char *remote_address, unsigned short port_number) {
    pthread_mutex_lock(&manager->lock);

    int index = find_connection_index(manager, remote_address, port_number);
    if (index != -1) {
        for (size_t i = index; i < manager->count - 1; ++i) {
            manager->connections[i] = manager->connections[i + 1];
        }
        manager->count--;
    }

    pthread_mutex_unlock(&manager->lock);
}

void list_connections(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        printf("Socket: %d, Address: %s, Port: %u\n",
               manager->connections[i].tcp_socket,
               manager->connections[i].remote_address,
               manager->connections[i].port_number);
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_connection_manager(ConnectionManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->connections);
    free(manager);
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure operations on the connection list are thread-safe.
- **Dynamic Resizing**: Automatically resizes the internal storage when capacity is exceeded, with a cap at `MAX_CONNECTIONS`.
- **Error Handling and Logging**: Logs resizing errors without crashing the program.
- **Resource Management**: Manages memory efficiently by reallocating space as needed.
- **Concurrency Considerations**: Locks are used to prevent race conditions during add/remove operations.

This implementation provides a robust, scalable solution for managing TCP connections in a concurrent environment.']

