    pthread_mutex_t lock;
} MemoryManager;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void initialize_memory_manager(MemoryManager* manager) {
    if (!manager) return;
    manager->entries = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

size_t get_current_usage(size_t entry_size, size_t count) {
    return entry_size * count;
}

void* allocate_entries(MemoryManager* manager, size_t new_capacity) {
    if (!manager || new_capacity == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(manager->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) {
        log_error("Memory allocation failed");
        return NULL;
    }
    memset(new_entries + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&manager->lock);
    manager->entries = new_entries;
    manager->capacity = new_capacity;
    pthread_mutex_unlock(&manager->lock);

    return new_entries;
}

int add_entry(MemoryManager* manager, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t entry_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t current_usage = get_current_usage(entry_size, manager->count);

    if (current_usage + entry_size > MAX_BUFFER_SIZE || 
        (float)current_usage / MAX_BUFFER_SIZE >= REALLOC_THRESHOLD) {
        size_t new_capacity = manager->capacity == 0 ? 10 : manager->capacity * 2;
        if ((current_usage + entry_size * new_capacity) > MAX_BUFFER_SIZE) {
            log_error("Exceeded maximum buffer size");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        void* result = allocate_entries(manager, new_capacity);
        if (!result) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* entries = manager->entries;

    if (entries[manager->count].rx_ue_information_tag.valid != 0) {
        log_error("Invalid initialization of RX_UE_INFORMATION_TAG");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    entries[manager->count].rx_ue_information_tag = tag;
    entries[manager->count].rnti = rnti;
    entries[manager->count].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void free_memory_manager(MemoryManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->entries);
    manager->entries = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

void reset_memory_manager(MemoryManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    memset(manager->entries, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->count = 0;

    pthread_mutex_unlock(&manager->lock);
}

size_t query_memory_usage(MemoryManager* manager) {
    if (!manager) return 0;

    size_t entry_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return get_current_usage(entry_size, manager->count);
}

size_t query_remaining_capacity(MemoryManager* manager) {
    if (!manager) return 0;

    size_t used_space = query_memory_usage(manager);
    return MAX_BUFFER_SIZE - used_space;
}

void check_for_leaks(MemoryManager* manager) {
    if (!manager) return;

    size_t entry_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t expected_usage = get_current_usage(entry_size, manager->count);
    size_t actual_usage = query_memory_usage(manager);

    if (expected_usage != actual_usage) {
        log_error("Potential memory leak detected");
    }
}

int main() {
    srand(time(NULL));
    MemoryManager manager;
    initialize_memory_manager(&manager);

    RX_UE_INFORMATION_TAG tag = { .valid = 1 };
    RNTI rnti = 12345;

    if (add_entry(&manager, tag, rnti) == -1) {
        log_error("Failed to add entry");
    }

    printf("Memory usage: %zu bytes\n", query_memory_usage(&manager));
    printf("Remaining capacity: %zu bytes\n", query_remaining_capacity(&manager));

    check_for_leaks(&manager);

    reset_memory_manager(&manager);

    if (add_entry(&manager, tag, rnti) == -1) {
        log_error("Failed to add entry after reset");
    }

    free_memory_manager(&manager);

    return 0;
}
