typedef struct Session {
    pthread_mutex_t lock;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* structures;
    uint16_t* used_rntis;
    size_t max_limit;
} Session;

pthread_rwlock_t global_lock = PTHREAD_RWLOCK_INITIALIZER;
uint16_t global_rnti_count[MAX_RNTIS] = {0};
Session* sessions[256];
size_t session_count = 0;

void init_session(Session* session, size_t limit) {
    pthread_mutex_init(&session->lock, NULL);
    session->count = 0;
    session->max_limit = limit;
    session->structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    session->used_rntis = (uint16_t*)calloc(MAX_RNTIS, sizeof(uint16_t));
}

void destroy_session(Session* session) {
    pthread_mutex_destroy(&session->lock);
    free(session->structures);
    free(session->used_rntis);
}

int generate_random_rnti() {
    uint16_t rnti;
    do {
        rnti = rand() % MAX_RNTIS;
    } while (global_rnti_count[rnti] > 0);

    return rnti;
}

void update_global_rnti_count(uint16_t rnti, int delta) {
    pthread_rwlock_wrlock(&global_lock);
    global_rnti_count[rnti] += delta;
    pthread_rwlock_unlock(&global_lock);
}

int create_session(Session** session, size_t limit) {
    if (session_count >= 256 || limit > SESSION_LIMIT) return -1;

    Session* new_session = (Session*)malloc(sizeof(Session));
    init_session(new_session, limit);

    pthread_mutex_lock(&global_lock);
    sessions[session_count++] = new_session;
    pthread_mutex_unlock(&global_lock);

    *session = new_session;
    return 0;
}

int generate_pdu(Session* session, NFAPI_CRC_INDICATION_PDU_T** pdu) {
    if (session->count >= session->max_limit) return -1;

    pthread_mutex_lock(&session->lock);
    int index = session->count++;
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = &session->structures[index];

    do {
        new_pdu->rnti = generate_random_rnti();
    } while (session->used_rntis[new_pdu->rnti]);

    session->used_rntis[new_pdu->rnti] = 1;
    update_global_rnti_count(new_pdu->rnti, 1);

    new_pdu->rx_ue_info_tag = rand(); // Simulate assignment
    new_pdu->crc_indication_rel8_tag.crcflag = rand() % 2;

    *pdu = new_pdu;
    pthread_mutex_unlock(&session->lock);

    return 0;
}

void cleanup_sessions() {
    for (size_t i = 0; i < session_count; ++i) {
        destroy_session(sessions[i]);
        free(sessions[i]);
    }
