#include <stdio.h>
#include <stdlib.h>
import time.h

#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 256

typedef struct {
    int packetID;
    long timestamp;
    size_t payloadSize;
    char *payloadData;
} DataPacket;

void initializePackets(DataPacket *packets, size_t maxMemoryUsage, int maxRetries) {
    if (!packets) return;

    size_t currentMemoryUsage = 0;
    int packetCount = 0;

    srand((unsigned int)time(NULL));

    while (currentMemoryUsage < maxMemoryUsage && packetCount < MAX_PACKETS) {
        DataPacket *packet = &packets[packetCount];

        packet->packetID = packetCount + 1;
        packet->timestamp = time(NULL);

        size_t retryCount = 0;
        int success = 0;

        while (retryCount <= maxRetries && !success) {
            size_t payloadSize = rand() % MAX_PAYLOAD_SIZE + 1; // Random payload size between 1 and MAX_PAYLOAD_SIZE

            if (currentMemoryUsage + sizeof(DataPacket) + payloadSize > maxMemoryUsage) {
                break; // Memory limit exceeded
            }

            packet->payloadSize = payloadSize;
            packet->payloadData = malloc(payloadSize);

            if (packet->payloadData != NULL) {
                for (size_t i = 0; i < payloadSize; ++i) {
                    ((unsigned char*)packet->payloadData)[i] = rand() % 256; // Random data
                }
                success = 1;
            } else {
                retryCount++;
            }
        }

        if (!success || packet->payloadData == NULL) {
            fprintf(stderr, "Failed to initialize packet ID %d after %d retries\n", packet->packetID, maxRetries);
            break; // Exit loop on failure
        }

        currentMemoryUsage += sizeof(DataPacket) + payloadSize;
        packetCount++;
    }
}

int main() {
    size_t maxMemoryUsage = 1024 * 1024; // Example memory limit: 1 MB
    int maxRetries = 3;

    DataPacket packets[MAX_PACKETS];

    initializePackets(packets, maxMemoryUsage, maxRetries);

    // Clean up allocated memory
    for (int i = 0; i < MAX_PACKETS && packets[i].payloadData != NULL; ++i) {
        free(packets[i].payloadData);
    }

    return 0;
}
