typedef struct {
    NetworkStats *data;
    size_t capacity;
    size_t size;
    float loss_threshold;
    float latency_threshold;
    float throughput_threshold;
} DynamicArray;

void initDynamicArray(DynamicArray *array, size_t initial_capacity) {
    array->data = (NetworkStats *)malloc(initial_capacity * sizeof(NetworkStats));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
}

void resizeArrayIfNeeded(DynamicArray *array) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkStats *new_data = realloc(array->data, new_capacity * sizeof(NetworkStats));
        if (!new_data) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

void addDataPoint(DynamicArray *array, NetworkStats point) {
    resizeArrayIfNeeded(array);

    if (point.packet_loss <= array->loss_threshold &&
        point.latency <= array->latency_threshold &&
        point.throughput >= array->throughput_threshold) {

        array->data[array->size++] = point;
    } else {
        fprintf(stderr, "Outlier detected and excluded: Loss=%f, Latency=%f, Throughput=%f\n",
                point.packet_loss, point.latency, point.throughput);
    }
}

