            .latency = rand() % 200 + 50, // Random latency between 50ms to 250ms
            .throughput = (rand() % 500 + 500) * 1.0 // Throughput in Mbps
        };
        addDataPoint(array, simulated_point);
    }
}

void freeDynamicArray(DynamicArray *array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
}

