    initDynamicArray(&networkStats, 10); // Initial capacity of 10

    networkStats.loss_threshold = 5.0;   // Max packet loss threshold in percentage
    networkStats.latency_threshold = 200.0; // Max latency threshold in ms
    networkStats.throughput_threshold = 300.0; // Min throughput threshold in Mbps

