#include <stdio.h>
#include <stdlib.h>
import "stdbool.h"
#include "stdint.h"

// Define structures as per requirement.
typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG_T ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL; // Memory allocation failure
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

bool append_to_list(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false; // Memory allocation failure

    new_node->data = pdu;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;
    return true;
}

void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

bool serialize_to_file(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return false;

    fwrite(&list->size, sizeof(int), 1, file);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return true;
}

bool deserialize_from_file(DoublyLinkedList** list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return false;

    int size;
    fread(&size, sizeof(int), 1, file);

    *list = create_list();
    if (!(*list)) {
        fclose(file);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < size; ++i) {
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        append_to_list(*list, pdu);
    }

    fclose(file);
    return true;
}

void generate_unique_crc_flags(DoublyLinkedList* list) {
    if (!list || !list->size) return;

    uint8_t used_flags[256] = {0}; // Track used CRC flags
    Node* current = list->head;

    for (int i = 0; i < list->size; ++i) {
        uint8_t crc_flag;
        do {
            crc_flag = rand() % 256;
        } while (used_flags[crc_flag]);

        current->data.crc_indication_rel8_tag.CRCFLAG = crc_flag;
        used_flags[crc_flag] = 1;

        current = current->next;
    }
}

int main() {
    DoublyLinkedList* list = create_list();
    if (!list) {
        printf("Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Example of populating the list
    for (int i = 0; i < 10000; ++i) { // Large volume data handling
        NFAPI_CRC_INDICATION_PDU_T pdu = {{ .RNTI = i }, i, {.CRCFLAG = 0}};
        if (!append_to_list(list, pdu)) {
            printf("Memory allocation failed during append.\n");
            free_list(list);
            return EXIT_FAILURE;
        }
    }

    generate_unique_crc_flags(list);

    // Serialize and deserialize operations
    if (serialize_to_file(list, "data.bin")) {
        DoublyLinkedList* deserialized_list = NULL;
        if (!deserialize_from_file(&deserialized_list, "data.bin")) {
            printf("Deserialization failed.\n");
            free_list(list);
            return EXIT_FAILURE;
        }

        // Verify and utilize `deserialized_list` as needed

        free_list(deserialized_list); // Clean up deserialized list
    } else {
        printf("Serialization failed.\n");
    }

    free_list(list);
    return EXIT_SUCCESS;
}
