int initialize_network_packets(NetworkPacket **packets, NFAPI_CRC_INDICATION_PDU_T **indication_pdu_list, int num_packets) {
    if (num_packets > MAX_PACKETS || num_packets <= 0) {
        fprintf(stderr, "Invalid number of packets.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);

    // Allocate memory for packets and indication pdu list
    *packets = malloc(num_packets * sizeof(NetworkPacket));
    *indication_pdu_list = malloc(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!*packets || !*indication_pdu_list) {
