        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Fetch string data asynchronously
    char *string_data = NULL;
    pthread_t fetch_thread;
    pthread_create(&fetch_thread, NULL, fetch_string_data_async, &string_data);
    pthread_join(fetch_thread, NULL);

