        // Populate NFAPI_CRC_INDICATION_PDU_T structure
        (*indication_pdu_list)[i].RX_UE_INFORMATION_TAG = i;
        (*indication_pdu_list)[i].RNTI = i + 1000;
        (*indication_pdu_list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Free string data after use
        free(string_data);
    }

    pthread_mutex_unlock(&lock);

    return 0;
}

void cleanup(NetworkPacket *packets, NFAPI_CRC_INDICATION_PDU_T *indication_pdu_list, int num_packets) {
