DynamicMediaArray* init_dynamic_media_array(size_t num_streams) {
    if (num_streams == 0 || num_streams > SIZE_MAX / sizeof(MediaStream*)) {
        fprintf(stderr, "Invalid number of streams\n");
        return NULL;
    }

    DynamicMediaArray *array = malloc(sizeof(DynamicMediaArray));
    if (!array) return NULL;

    array->streams = calloc(num_streams, sizeof(MediaStream*));
    if (!array->streams) {
        free(array);
        return NULL;
    }
    array->count = num_streams;
    pthread_mutex_init(&array->lock, NULL);

    for (size_t i = 0; i < num_streams; ++i) {
        MediaStream *stream = malloc(sizeof(MediaStream));
        if (!stream) continue;

        AudioFrame *audio = fetch_audio_data(i);
        VideoFrame *video = fetch_video_data(i);
        if (!audio || !video) {
            free(stream);
            continue;
        }

        stream->audio = *audio;
        stream->video = *video;
        stream->timestamp = i;

        pthread_mutex_lock(&array->lock);
        array->streams[i] = stream;
        pthread_mutex_unlock(&array->lock);

        free(audio->audioData);
        free(audio);
        free(video->videoData);
        free(video);
    }

    return array;
}

void cleanup_dynamic_media_array(DynamicMediaArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        MediaStream *stream = array->streams[i];
        if (stream) {
            free(stream->audio.audioData);
            free(stream);
        }
    }

    free(array->streams);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int main() {
    size_t num_streams = 10;
    DynamicMediaArray *media_array = init_dynamic_media_array(num_streams);

    if (media_array) {
        // Use the media array
        cleanup_dynamic_media_array(media_array);
    }

    return 0;
}
