typedef struct {
    char interfaceName[256];
    int interfaceType; // 1 for wired, 2 for wireless, etc.
    double errorRate;
    double bandwidthUsage;
} NicStats;

// Function to initialize and populate a dynamic array of NIC statistics structures
NicStats* initAndPopulateNicArray(int initialSize, int (*filterFunc)(const NicStats*), void* filterData) {
    // Allocate memory for the initial size
    NicStats* nicArray = (NicStats*)malloc(initialSize * sizeof(NicStats));
    if (!nicArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int capacity = initialSize;
    int count = 0;

    // Simulate fetching NIC data
    for (int i = 0; i < 100; ++i) { // Assume we fetch 100 interfaces as an example
        NicStats nic;
        snprintf(nic.interfaceName, sizeof(nic.interfaceName), "Interface_%d", i);
        nic.interfaceType = rand() % 3 + 1; // Random interface type between 1 and 3
        nic.errorRate = (double)rand() / RAND_MAX * 0.05; // Random error rate up to 5%
        nic.bandwidthUsage = (double)rand() / RAND_MAX * 1000; // Random bandwidth usage in Mbps

        // Apply filter function if provided
        if (!filterFunc || filterFunc(&nic, filterData)) {
            // Resize array if needed
            if (count >= capacity) {
                int newCapacity = capacity * 2;
                NicStats* tempArray = (NicStats*)realloc(nicArray, newCapacity * sizeof(NicStats));
                if (!tempArray) {
                    free(nicArray);
                    fprintf(stderr, "Memory reallocation failed\n");
                    return NULL;
                }
                nicArray = tempArray;
                capacity = newCapacity;
            }

            // Add NIC to array
            nicArray[count++] = nic;
        }
    }

    // Resize array to the actual number of elements
    NicStats* resizedArray = (NicStats*)realloc(nicArray, count * sizeof(NicStats));
    if (!resizedArray && count > 0) {
        free(nicArray);
        fprintf(stderr, "Final memory reallocation failed\n");
        return NULL;
    }

    return resizedArray;
}

// Example filter function
int filterByTypeAndErrorRate(const NicStats* nic, void* data) {
    int requiredType = *(int*)data;
    double maxErrorRate = *(double*)((char*)data + sizeof(int));

    return (nic->interfaceType == requiredType && nic->errorRate <= maxErrorRate);
}

// Example usage
