    int filterType = 1; // Filter for wired interfaces
    double maxErrorRate = 0.01; // Max error rate of 1%

    void* filterData = malloc(sizeof(int) + sizeof(double));
    memcpy(filterData, &filterType, sizeof(int));
    memcpy((char*)filterData + sizeof(int), &maxErrorRate, sizeof(double));

