#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int start_freq;
    // Add other band-specific properties if needed.
} BAND;

typedef struct {
    int grant_id;
    // Add other PUSCH grant-specific properties if needed.
} PUSCH_GRANT;

typedef struct {
    unsigned long uarfcn;
    BAND band;
    PUSCH_GRANT *pusch_grants;
    size_t grants_count;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPIMessageArray;

void init_message(NFAPI_MESSAGE_T *message) {
    message->uarfcn = rand() % 1000000; // Unique UARFCN within a range.
    message->band.start_freq = rand() % 20000; // Randomize frequency band start freq.
    message->pusch_grants = NULL;
    message->grants_count = 0;
}

void init_array(NFAPIMessageArray *array, size_t initial_capacity) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initial_capacity;
    array->count = 0;
    array->messages = (NFAPI_MESSAGE_T *)malloc(array->capacity * sizeof(NFAPI_MESSAGE_T));
    if (!array->messages) {
        fprintf(stderr, "Failed to allocate memory for NFAPI message array.\n");
        exit(EXIT_FAILURE);
    }
}

void resize_array(NFAPIMessageArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    NFAPI_MESSAGE_T *new_messages = (NFAPI_MESSAGE_T *)realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!new_messages && new_capacity > 0) {
        fprintf(stderr, "Failed to reallocate memory for NFAPI message array.\n");
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }
    array->messages = new_messages;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);
}

void add_message(NFAPIMessageArray *array) {
    if (array->count >= array->capacity) {
        resize_array(array, array->capacity * 2);
    }
    NFAPI_MESSAGE_T *message = &array->messages[array->count++];
    init_message(message);
}

void remove_message(NFAPIMessageArray *array, size_t index) {
    if (index >= array->count) return;
    free(array->messages[index].pusch_grants); // Free PUSCH grants memory.
    memmove(&array->messages[index], &array->messages[index + 1], (array->count - index - 1) * sizeof(NFAPI_MESSAGE_T));
    array->count--;
}

void deallocate_array(NFAPIMessageArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i].pusch_grants);
    }
    free(array->messages);
    pthread_mutex_destroy(&array->lock);
}

int find_message_by_uarfcn(NFAPIMessageArray *array, unsigned long uarfcn) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].uarfcn == uarfcn) {
            pthread_mutex_unlock(&array->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // UARFCN not found.
}

// Example usage
int main() {
    NFAPIMessageArray message_array;
    init_array(&message_array, 10); // Initialize with initial capacity.

    add_message(&message_array);
    add_message(&message_array);

    unsigned long search_uarfcn = message_array.messages[0].uarfcn;
    int index = find_message_by_uarfcn(&message_array, search_uarfcn);

    if (index != -1) {
        printf("UARFCN %lu found at index %d\n", search_uarfcn, index);
    } else {
        printf("UARFCN not found.\n");
    }

    deallocate_array(&message_array);
    return 0;
}
