        list->array[list->count - 1]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        pthread_cond_signal(&list->cond_non_empty);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
