        pthread_cond_wait(&list->cond_non_empty, &list->lock);
    }

    if (pdu != NULL && list->count > 0) {
        *pdu = list->array[--list->count];
        free(*pdu); // Free the memory after use
        *pdu = NULL;

        pthread_cond_signal(&list->cond_non_full);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_debug(const char* message) {
