    Node* head;
    atomic_int size;
    pthread_mutex_t lock; // Mutex for thread safety
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    atomic_store(&list->size, 0);
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_rnti_unique(List* list, int rnti) {
    pthread_mutex_lock(&list->lock);
    Node* node = list->head;
    while (node != NULL) {
        if (node->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Not unique
        }
        node = node->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 1; // Unique
}

void add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
