// Function to create and populate a list of structures.
int create_nfa_api_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T **pdu_list, int count, const Config *config) {
    if (count > config->max_struct_count) {
        log_message(config->logging_level, "Exceeded maximum structure limit.");
        return -1; // Error: Exceeds max count
    }

    pthread_mutex_lock(&global_lock);
    *pdu_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_list == NULL) {
        log_message(config->logging_level, "Memory allocation failure.");
        pthread_mutex_unlock(&global_lock);
