                     (*pdu_list)[i].crc_indication_rel8_tag.RNTI,
                     (*pdu_list)[i].crc_indication_rel8_tag.CRCFLAG);
            log_message(config->logging_level, log_msg);
        }
    }

    pthread_mutex_unlock(&global_lock);
    return 0; // Success
}

// Function for logging messages.
