} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    unsigned int crcflag; // Unique identifier
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    FILE* export_file;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
CRCList* create_crc_list();
void free_crc_list(CRCList* list);
int add_crc_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry);
void export_crc_list_to_csv(const char* filename, CRCList* list);

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    unsigned int crcflag;
    do {
        crcflag = rand() % (1 << 16); // Assuming CRCFLAG is a 16-bit value
    } while (!is_crcflag_unique(list, crcflag));

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = entry;
    new_node->crcflag = crcflag;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int is_crcflag_unique(CRCList* list, unsigned int crcflag) {
    Node* current = list->head;
    while (current) {
        if (current->crcflag == crcflag)
            return 0;
        current = current->next;
    }
    return 1;
}

void export_crc_list_to_csv(const char* filename, CRCList* list) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "w");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    Node* current = list->head;
    while (current) {
        // Assuming functions exist to serialize each field into CSV format
        fprintf(file, "%u,%u,%u\n", 
            serialize_rx_ue_info(current->data.rx_ue_info),
            serialize_rnti(current->data.rnti),
            current->crcflag);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}
```

