public interface ISerializerPlugin<T>
{
    bool TryDeserialize(Stream stream, out T obj);
}

public class CustomObjectSerializer : ISerializerPlugin<CustomObject>
{
    public bool TryDeserialize(Stream stream, out CustomObject obj)
    {
        // Implement custom deserialization logic for the proprietary binary format.
