#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1500

typedef struct {
    uint8_t sourceMAC[6];
    uint8_t destinationMAC[6];
} MACAddress;

typedef struct {
    uint16_t type;
    uint16_t length;
} PacketHeader;

typedef struct {
    PacketHeader header;
    MACAddress srcMAC;
    MACAddress dstMAC;
    uint8_t payload[MAX_PACKET_SIZE];
} NICP_Packet;

typedef struct {
    NICP_Packet *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NICP_Array;

void initializeNICPArray(NICP_Array *array, size_t initialCapacity) {
    array->packets = (NICP_Packet *)malloc(initialCapacity * sizeof(NICP_Packet));
    array->count = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->lock, NULL);
}

int addPacket(NICP_Array *array, NICP_Packet packet) {
    if (packet.header.length > MAX_PACKET_SIZE) return -1; // Invalid packet size

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NICP_Packet *newPackets = (NICP_Packet *)realloc(array->packets, newCapacity * sizeof(NICP_Packet));
        if (!newPackets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = newPackets;
        array->capacity = newCapacity;
    }

    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void freeNICPArray(NICP_Array *array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
}

// Example external data source integration function
int validateAndAddPacketFromSource(NICP_Array *array, const uint8_t *data, size_t dataSize) {
    if (dataSize < sizeof(PacketHeader)) return -1; // Not enough data for a header

    NICP_Packet packet;
    memcpy(&packet.header, data, sizeof(PacketHeader));

    if (dataSize < packet.header.length || packet.header.length > MAX_PACKET_SIZE)
        return -1; // Invalid packet length

    memcpy(packet.payload, data + sizeof(PacketHeader), packet.header.length - sizeof(PacketHeader));
    addPacket(array, packet);

    return 0;
}

int main() {
    NICP_Array nicpArray;
    initializeNICPArray(&nicpArray, 10);

    // Simulate receiving packets
    uint8_t exampleData[MAX_PACKET_SIZE];
    memset(exampleData, 0xAB, MAX_PACKET_SIZE);
    ((PacketHeader *)exampleData)->type = 1;
    ((PacketHeader *)exampleData)->length = sizeof(PacketHeader) + 100;

    if (validateAndAddPacketFromSource(&nicpArray, exampleData, sizeof(exampleData)) == 0) {
        printf("Packet added successfully.\n");
    } else {
        printf("Failed to add packet.\n");
    }

    freeNICPArray(&nicpArray);
    return 0;
}
```

This code initializes a dynamic array of NICP packets with thread safety and efficient memory management. It includes functions for adding packets, validating them, and freeing resources.']

