import <pthread.h>
#include <time.h>

typedef struct {
    unsigned int packet_id;
    unsigned char source_mac[6];
    unsigned char destination_mac[6];
    size_t size;
    int priority; // Higher value indicates higher priority
} NICPPacket;

typedef struct {
    NICPPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    FILE* log_file;
    int verbosity_level;
} NICPArray;

// Function prototypes
void init_nicp_array(NICPArray* array, size_t initial_capacity);
void add_packet(NICPArray* array, const NICPPacket* packet);
void process_packets(NICPArray* array);
void reorder_packets_by_priority(NICPArray* array);
void adjust_buffer_size(NICPArray* array);
void log_statistics(NICPArray* array);

void init_nicp_array(NICPArray* array, size_t initial_capacity) {
    pthread_mutex_init(&array->lock, NULL);
    array->packets = (NICPPacket*)malloc(initial_capacity * sizeof(NICPPacket));
    if (!array->packets) {
        perror("Failed to allocate memory for packets");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    array->log_file = fopen("packet_log.txt", "w");
    if (!array->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    array->verbosity_level = 1; // Default verbosity level
}

void add_packet(NICPArray* array, const NICPPacket* packet) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        adjust_buffer_size(array);
    }

    array->packets[array->count] = *packet;
    array->count++;

    reorder_packets_by_priority(array);

    pthread_mutex_unlock(&array->lock);
}

void process_packets(NICPArray* array) {
    time_t start_time, end_time;
    size_t processed_count = 0;

    while (processed_count < array->count) {
        // Simulate packet processing
        time(&start_time);

        for (size_t i = 0; i < array->count && processed_count < array->capacity; ++i) {
            // Process each packet here, including validation and handling

            // Log packet processing if verbosity level is high enough
            if (array->verbosity_level > 1) {
                fprintf(array->log_file, "Processed packet ID: %u\n", array->packets[i].packet_id);
            }

            processed_count++;
        }

        time(&end_time);
        double latency = difftime(end_time, start_time);

        // Log statistics
        log_statistics(array);
    }
}

void reorder_packets_by_priority(NICPArray* array) {
    for (size_t i = 0; i < array->count - 1; ++i) {
        for (size_t j = 0; j < array->count - i - 1; ++j) {
            if (array->packets[j].priority < array->packets[j + 1].priority) {
                NICPPacket temp = array->packets[j];
                array->packets[j] = array->packets[j + 1];
                array->packets[j + 1] = temp;
            }
        }
    }
}

void adjust_buffer_size(NICPArray* array) {
    size_t new_capacity = array->capacity * 2; // Double the capacity
    NICPPacket* new_packets = (NICPPacket*)realloc(array->packets, new_capacity * sizeof(NICPPacket));
    if (!new_packets) {
        perror("Failed to reallocate memory for packets");
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->capacity = new_capacity;
}

void log_statistics(NICPArray* array) {
    fprintf(array->log_file, "Total packets processed: %zu\n", array->count);
    // Additional statistics logging can be added here
}
