} LtePhyConfig;

typedef struct {
    LtePhyConfig *configs;
    size_t capacity;
    size_t count;
} LtePhyConfigManager;

LtePhyConfigManager* create_manager(size_t initial_capacity) {
    LtePhyConfigManager* manager = malloc(sizeof(LtePhyConfigManager));
    if (!manager) return NULL;
    manager->configs = calloc(initial_capacity, sizeof(LtePhyConfig));
    manager->capacity = initial_capacity;
    manager->count = 0;
    return manager;
}

void destroy_manager(LtePhyConfigManager* manager) {
    free(manager->configs);
    free(manager);
}

int validate_config(const LtePhyConfig *config) {
    // Add detailed validation based on LTE PHY standards
    if (config->bandwidth <= 0 || config->subcarrierSpacing <= 0 ||
        (config->cyclicPrefixType < CP_TYPE_1 || config->cyclicPrefixType > CP_TYPE_3)) {
        return -1; // Invalid configuration
    }
    return 0;
}

int add_config(LtePhyConfigManager* manager, const LtePhyConfig *newConfig) {
    if (validate_config(newConfig) != 0) {
        fprintf(stderr, "Invalid LTE PHY Layer configuration.\n");
        return -1;
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LtePhyConfig* new_configs = realloc(manager->configs, new_capacity * sizeof(LtePhyConfig));
        if (!new_configs) return -1; // Failed to allocate memory
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->configs[manager->count++], newConfig, sizeof(LtePhyConfig));
    return 0;
}

int remove_config(LtePhyConfigManager* manager, size_t index) {
    if (index >= manager->count) {
        fprintf(stderr, "Index out of range.\n");
        return -1;
    }

    memmove(&manager->configs[index], &manager->configs[index + 1],
            (manager->count - index - 1) * sizeof(LtePhyConfig));
    manager->count--;

    // Consider shrinking capacity if count becomes much less than capacity
    if (manager->capacity > 16 && manager->count < manager->capacity / 4) {
        size_t new_capacity = manager->capacity / 2;
        LtePhyConfig* new_configs = realloc(manager->configs, new_capacity * sizeof(LtePhyConfig));
        if (new_configs) { // Only shrink if reallocation was successful
            manager->configs = new_configs;
            manager->capacity = new_capacity;
        }
    }

    return 0;
}

int update_config(LtePhyConfigManager* manager, size_t index, const LtePhyConfig *updatedConfig) {
    if (index >= manager->count) {
        fprintf(stderr, "Index out of range.\n");
        return -1;
    }

    if (validate_config(updatedConfig) != 0) {
        fprintf(stderr, "Invalid LTE PHY Layer configuration.\n");
        return -1;
    }

    memcpy(&manager->configs[index], updatedConfig, sizeof(LtePhyConfig));
    return 0;
}

void log_error(const char *message) {
