#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NFAPI_PDU_COUNT 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initialize_linked_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_array(unsigned int count, LinkedList** list) {
    if (count > MAX_NFAPI_PDU_COUNT) {
        return NULL;
    }

    *list = malloc(sizeof(LinkedList));
    if (*list == NULL) {
        return NULL;
    }

    initialize_linked_list(*list);
    Node* current = NULL;
    for (unsigned int i = 0; i < count; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            destroy_linked_list(*list);
            free(*list);
            return NULL;
        }

        pthread_mutex_lock(&((*list)->lock));

        node->data.RX_UE_INFORMATION_TAG = i + 1; // Example tag
        node->data.RNTI = (i % 1024) + 1;         // Example RNTI
        node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (current == NULL) {
            (*list)->head = node;
        } else {
            current->next = node;
        }
        current = node;

        pthread_mutex_unlock(&((*list)->lock));
    }

    return &(*list)->head->data; // Return pointer to first element for simplicity
}

// Main function demonstrating usage
int main() {
    LinkedList* list = NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_array(100, &list);

    if (pdu_array == NULL) {
        fprintf(stderr, "Failed to allocate array\n");
        return EXIT_FAILURE;
    }

    // Example usage of data
    printf("First RX_UE_INFORMATION_TAG: %u\n", pdu_array->RX_UE_INFORMATION_TAG);

    destroy_linked_list(list);
    free(list);

    return EXIT_SUCCESS;
}
