NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_list(size_t initial_size) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **last = &head;

    for (size_t i = 0; i < initial_size; ++i) {
        pthread_mutex_lock(&lock);
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node();
        if (!new_node) {
            pthread_mutex_unlock(&lock);
            return head; // Return what we have so far
        }
        *last = new_node;
        last = &new_node->next;
        pthread_mutex_unlock(&lock);
    }

    log_memory_event("Initial list allocation completed.");
    return head;
}

NFAPI_CRC_INDICATION_PDU_T* realloc_nfa_list(NFAPI_CRC_INDICATION_PDU_T* head, size_t additional_size) {
