        pthread_mutex_lock(&lock);
        NFAPI_CRC_INDICATION_PDU_T** last = &head;

        while (*last && (*last)->next)
            last = &(*last)->next;

        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node();
        if (!new_node) {
            pthread_mutex_unlock(&lock);
            log_memory_event("Failed to allocate additional node during reallocation.");
