    struct MessageNode* next;
} MessageNode;

// Message manager structure
typedef struct {
    pthread_mutex_t lock;
    MessageNode* head;
} MessageManager;

// Initialize the message manager
void initMessageManager(MessageManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
}

// Add a new message
int addMessage(MessageManager* manager, int tag, const char* content) {
    if (!content || strlen(content) >= sizeof(LTE_DL_CCCH_Message).DL_CCCH_Message) {
        return -1; // Invalid input
    }

    MessageNode* newNode = (MessageNode*)malloc(sizeof(MessageNode));
    if (!newNode) {
        return -2; // Memory allocation failed
    }

    newNode->message.DL_CCCH_Message_Tag = tag;
    strncpy(newNode->message.DL_CCCH_Message, content, sizeof(newNode->message.DL_CCCH_Message) - 1);
    newNode->next = NULL;

    pthread_mutex_lock(&manager->lock);

    newNode->next = manager->head;
    manager->head = newNode;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Retrieve a message by tag
LTE_DL_CCCH_Message* getMessage(MessageManager* manager, int tag) {
    pthread_mutex_lock(&manager->lock);

    MessageNode* current = manager->head;
    while (current != NULL) {
        if (current->message.DL_CCCH_Message_Tag == tag) {
            pthread_mutex_unlock(&manager->lock);
            return &current->message;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Update an existing message by tag
int updateMessage(MessageManager* manager, int tag, const char* newContent) {
    if (!newContent || strlen(newContent) >= sizeof(LTE_DL_CCCH_Message).DL_CCCH_Message) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&manager->lock);

    MessageNode* current = manager->head;
    while (current != NULL) {
        if (current->message.DL_CCCH_Message_Tag == tag) {
            strncpy(current->message.DL_CCCH_Message, newContent, sizeof(current->message.DL_CCCH_Message) - 1);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return -3; // Message not found
}

// Free all messages and destroy the manager
void freeMessageManager(MessageManager* manager) {
    pthread_mutex_lock(&manager->lock);

    MessageNode* current = manager->head;
    while (current != NULL) {
        MessageNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    MessageManager manager;
    initMessageManager(&manager);

    addMessage(&manager, 1, "Hello");
    LTE_DL_CCCH_Message* msg = getMessage(&manager, 1);
    if (msg) {
        printf("Message: %s\n", msg->DL_CCCH_Message);
    }

    updateMessage(&manager, 1, "Updated Hello");
    msg = getMessage(&manager, 1);
    if (msg) {
        printf("Updated Message: %s\n", msg->DL_CCCH_Message);
    }

    freeMessageManager(&manager);

    return 0;
}
