#include <pthread.h>

typedef struct {
    unsigned int message_id;
    time_t timestamp;
    size_t payload_length;
} Message;

typedef struct {
    Message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

// Initialize the dynamically allocated array
MessageArray* init_message_array(size_t initial_capacity) {
    MessageArray *array = (MessageArray*)malloc(sizeof(MessageArray));
    if (!array) {
        perror("Failed to allocate MessageArray");
        return NULL;
    }

    array->messages = (Message*)calloc(initial_capacity, sizeof(Message));
    if (!array->messages) {
        perror("Failed to allocate messages");
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Add or update a message
int add_or_update_message(MessageArray *array, unsigned int message_id, time_t timestamp, size_t payload_length) {
    if (!array) return -1;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].message_id == message_id) {
            // Update existing
            array->messages[i].timestamp = timestamp;
            array->messages[i].payload_length = payload_length;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    // Add new
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Message* new_messages = (Message*)realloc(array->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            perror("Failed to reallocate messages");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    Message new_message = {message_id, timestamp, payload_length};
    array->messages[array->count++] = new_message;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Retrieve a message by ID
Message* get_message(MessageArray *array, unsigned int message_id) {
    if (!array) return NULL;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].message_id == message_id) {
            Message* msg = &array->messages[i];
            pthread_mutex_unlock(&array->lock);
            return msg;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

// Iterate over all messages
void iterate_messages(MessageArray *array, void (*callback)(Message*)) {
    if (!array || !callback) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        callback(&array->messages[i]);
    }

    pthread_mutex_unlock(&array->lock);
}

// Free the resources
void free_message_array(MessageArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    free(array->messages);
    array->count = 0;
    array->capacity = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example callback function
void print_message(Message *message) {
    if (message) {
        printf("Message ID: %u, Timestamp: %ld, Payload Length: %zu\n",
               message->message_id,
               message->timestamp,
               message->payload_length);
    }
}
