#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    int PARAM_ID;
    char VALUE[256];
    time_t LAST_UPDATE_TIMESTAMP;
    int SOURCE_ID;
} NFC_PARAMS_T;

typedef struct Node {
    NFC_PARAMS_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    unsigned long cache_hits;
    unsigned long cache_misses;
    unsigned long cache_evictions;
    int log_suppressed;
    time_t last_validation_time;
} LRUCache;

LRUCache cache = {0};

void initialize_cache() {
    pthread_mutex_init(&cache.lock, NULL);
    cache.head = cache.tail = NULL;
    cache.size = 0;
}

Node* create_node(NFC_PARAMS_T param) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = param;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void destroy_node(Node* node) {
    free(node);
}

void move_to_front(Node* node) {
    if (node == cache.head) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (cache.tail == node) cache.tail = node->prev;

    node->next = cache.head;
    node->prev = NULL;

    if (cache.head) cache.head->prev = node;
    cache.head = node;

    if (!cache.tail) cache.tail = node;
}

void add_node(Node* node) {
    node->next = cache.head;
    node->prev = NULL;

    if (cache.head) cache.head->prev = node;
    cache.head = node;

    if (!cache.tail) cache.tail = node;

    cache.size++;
}

Node* remove_tail() {
    if (!cache.tail) return NULL;

    Node* to_remove = cache.tail;
    if (to_remove->prev) to_remove->prev->next = NULL;
    cache.tail = to_remove->prev;

    cache.size--;
    return to_remove;
}

void evict_if_needed() {
    while (cache.size > MAX_CACHE_SIZE) {
        Node* node_to_evict = remove_tail();
        destroy_node(node_to_evict);
        if (!cache.log_suppressed) printf("Cache eviction performed.\n");
        cache.cache_evictions++;
    }
}

NFC_PARAMS_T* get_param(int param_id, int* found) {
    pthread_mutex_lock(&cache.lock);

    Node* current = cache.head;
    while (current) {
        if (current->data.PARAM_ID == param_id) {
            *found = 1;
            move_to_front(current);
            pthread_mutex_unlock(&cache.lock);
            if (!cache.log_suppressed) printf("Cache hit for PARAM_ID %d.\n", param_id);
            return &current->data;
        }
        current = current->next;
    }

    *found = 0;
    pthread_mutex_unlock(&cache.lock);
    if (!cache.log_suppressed) printf("Cache miss for PARAM_ID %d.\n", param_id);
    cache.cache_misses++;
    return NULL;
}

void insert_or_update_param(NFC_PARAMS_T param) {
    pthread_mutex_lock(&cache.lock);

    Node* current = cache.head;
    while (current) {
        if (current->data.PARAM_ID == param.PARAM_ID) {
            current->data = param;
            move_to_front(current);
            break;
        }
        current = current->next;
    }

    if (!current) { // Not found, insert new
        Node* new_node = create_node(param);
        if (!new_node) {
            pthread_mutex_unlock(&cache.lock);
            printf("Memory allocation failed for new cache entry.\n");
            return;
        }
        add_node(new_node);
        evict_if_needed();
    }

    pthread_mutex_unlock(&cache.lock);
}

void* validation_thread(void* arg) {
    while (1) {
        sleep(60); // Adjust as needed
        pthread_mutex_lock(&cache.lock);

        time_t now = time(NULL);
        Node* current = cache.head;
        while (current) {
            if (now - current->data.LAST_UPDATE_TIMESTAMP > 3600) { // Example TTL check
                // Call external validation service, assume `validate_param` is implemented
                int valid = validate_param(&current->data);
                if (!valid) {
                    Node* to_remove = current;
                    current = current->next;
                    remove_node(to_remove); // Assume remove_node is similar to move_to_front and remove_tail
                    cache.cache_evictions++;
                    continue;
                }
            }
            current = current->next;
        }

        pthread_mutex_unlock(&cache.lock);
    }
    return NULL;
}

void start_validation_thread() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, validation_thread, NULL) != 0) {
        printf("Failed to create background validation thread.\n");
    }
}

int main() {
    initialize_cache();
    start_validation_thread();

    // Simulate cache operations
    NFC_PARAMS_T param1 = {1, "value1", time(NULL), 100};
    insert_or_update_param(param1);

    int found;
    NFC_PARAMS_T* result = get_param(1, &found);
    if (found) {
        printf("Retrieved PARAM_ID %d with VALUE %s\n", result->PARAM_ID, result->VALUE);
    }

    return 0;
}
