    pthread_mutex_t lock;
    int entry_count;
} CRCList;

CRCList crc_list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

// Simulated external data processing validation
int validate_RX_UE_INFORMATION_TAG(int tag) {
    // Placeholder for actual validation logic
    return (tag % 2 == 0); // Example: valid if even
}

void log_operation(const char* message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        log_operation("Memory allocation failed for new entry.");
        return NULL;
    }
    new_entry->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->data.RNTI = RNTI;
    new_entry->data.CRCFLAG = CRCFLAG;
    new_entry->timestamp = time(NULL);
    new_entry->next = NULL;
    return new_entry;
}

void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&crc_list.lock);

    if (!validate_RX_UE_INFORMATION_TAG(RX_UE_INFORMATION_TAG)) {
        log_operation("Invalid RX_UE_INFORMATION_TAG. Entry not added.");
        pthread_mutex_unlock(&crc_list.lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_entry = create_entry(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
    if (!new_entry) {
        pthread_mutex_unlock(&crc_list.lock);
        return;
    }

    // Check for duplicates
    NFAPI_CRC_INDICATION_PDU_T* current = crc_list.head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            log_operation("Duplicate RNTI found. Entry not added.");
            free(new_entry);
            pthread_mutex_unlock(&crc_list.lock);
            return;
        }
        current = current->next;
    }

    new_entry->next = crc_list.head;
    crc_list.head = new_entry;
    crc_list.entry_count++;
    log_operation("Entry added successfully.");

    pthread_mutex_unlock(&crc_list.lock);
}

void cleanup_entries() {
    pthread_mutex_lock(&crc_list.lock);

    time_t current_time = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = crc_list.head;

    while (current) {
        if ((current_time - current->timestamp) > TTL_SECONDS) {
            if (prev) {
                prev->next = current->next;
            } else {
                crc_list.head = current->next;
            }
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next;
            free(temp);
            crc_list.entry_count--;
            log_operation("Outdated entry removed.");
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&crc_list.lock);
}

void* periodic_cleanup(void* arg) {
    while (1) {
        sleep(TTL_SECONDS / 2); // Cleanup frequency
        cleanup_entries();
    }
    return NULL;
}

int main() {
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, NULL) != 0) {
        log_operation("Failed to create cleanup thread.");
        return EXIT_FAILURE;
    }

    // Simulate adding entries
    for (int i = 0; i < 1000; ++i) {
        add_entry(i, rand() % MAX_ENTRIES, rand() % 2);
    }

    pthread_join(cleanup_thread, NULL); // In a real application, cleanup thread might run indefinitely
    return EXIT_SUCCESS;
}
