    } else {
        Node* current = head;
        while (current->next && current->next->data.RNTI >= newNode->data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&list_lock);

    logOperation("Created and populated PDU with RNTI: %u", RNTI);
    return &(newNode->data);
}

void initMemoryPool(MemoryPool* mp, size_t block_size, size_t num_blocks) {
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->pool_memory = malloc(block_size * num_blocks);
    mp->free_list = NULL;

    pthread_mutex_init(&mp->lock, NULL);

    // Initialize free list
    char* cursor = (char*)mp->pool_memory;
    for (size_t i = 0; i < num_blocks; ++i) {
        Node* node = (Node*)cursor;
        node->next = mp->free_list;
        mp->free_list = node;
        cursor += block_size;
    }
}

Node* allocateFromPool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (!mp->free_list) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }

    Node* node = mp->free_list;
    mp->free_list = node->next;
    pthread_mutex_unlock(&mp->lock);
    return node;
}

void deallocateToPool(MemoryPool* mp, Node* node) {
    pthread_mutex_lock(&mp->lock);
    node->next = mp->free_list;
    mp->free_list = node;
    pthread_mutex_unlock(&mp->lock);
}

void logOperation(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

void periodicCleanup() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list_lock);
    Node** current = &head;

    while (*current) {
        // Placeholder condition for outdated data
        if (rand() % 10 == 0) { // Simulate condition with random chance
            Node* to_delete = *current;
            *current = (*current)->next;
            deallocateToPool(&memory_pool, to_delete);
            logOperation("Cleaned up and deallocated PDU");
        } else {
            current = &(*current)->next;
        }
    }
    pthread_mutex_unlock(&list_lock);

    // Schedule next cleanup
    struct timespec ts = {5, 0}; // 5 seconds interval
    nanosleep(&ts, NULL);
}

int main() {
    initSignalFramework();

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, (void*)periodicCleanup, NULL);

    // Example usage
    for (unsigned int i = 0; i < 50; ++i) {
        createAndPopulatePDU(rand(), rand());
    }

    sleep(10); // Let the cleanup thread run

    pthread_cancel(cleanup_thread);
    pthread_join(cleanup_thread, NULL);

    return 0;
}
```

### Key Aspects Implemented:
1. **Custom Memory Pool**: The `MemoryPool` structure optimizes memory allocation and deallocation using a free list.
2. **Thread Safety**: Mutexes (`pthread_mutex_t`) ensure that the linked list operations are thread-safe.
3. **Dynamic Allocation & Cleanup**: Periodic cleanup is handled in a separate thread, removing "outdated" nodes without affecting ongoing operations.
4. **RNTI-based Prioritization**: Nodes are inserted into the list based on RNTI values to prioritize higher values.
5. **Logging**: Basic logging with minimal performance impact using `vprintf`.
6. **Extensibility**: The code is modular, allowing easy integration of new features or hardware accelerators.

This solution provides a robust framework for handling NFAPI_CRC_INDICATION_PDU_T structures while considering efficiency and extensibility.']

