// Function prototypes
LinkedList* init_list();
int add_header(LinkedList *list);
void free_list(LinkedList *list);
int serialize_list(const char *filename, const LinkedList *list);
int deserialize_list(const char *filename, LinkedList **list);

// Simulate external NAS_MESSAGE validation
int validate_NAS_MESSAGE(int nas_message) {
    // Placeholder for external validation logic
    return 1; // Assume always valid for this example
}

// Generate a unique PDUSESSIONID (for simplicity, use rand())
int generate_unique_PDUSESSIONID() {
    srand(time(NULL));
    return rand();
}

// Generate a unique RX_UE_INFORMATION_TAG
unsigned long generate_RX_UE_INFORMATION_TAG() {
    return (unsigned long)rand();
}

// Generate a unique CRCFLAG for the list
int generate_unique_CRCFLAG(LinkedList *list, int used_crcflags[]) {
    int crcflag;
    do {
        crcflag = rand() % 256; // Assuming 8-bit CRCFLAG
    } while (!used_crcflags[crcflag]);

    // Mark this CRCFLAG as used in the current list state
    for (LTE_Ngap_TransportLayerHeader *header = list->head; header != NULL; header = header->next) {
        if (header->CRCFLAG == crcflag) {
            return generate_unique_CRCFLAG(list, used_crcflags);
        }
    }
    used_crcflags[crcflag] = 1;
    return crcflag;
}

// Initialize the linked list
LinkedList* init_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    return list;
}

// Add a new LTE_Ngap_TransportLayerHeader to the list
int add_header(LinkedList *list) {
    if (!validate_NAS_MESSAGE(rand())) { // Simulating NAS_MESSAGE validation
        fprintf(stderr, "Failed to validate NAS_MESSAGE\n");
        return -1;
    }

    int used_crcflags[256] = {0};
    LTE_Ngap_TransportLayerHeader *new_header = malloc(sizeof(LTE_Ngap_TransportLayerHeader));
    if (!new_header) {
        fprintf(stderr, "Memory allocation failed for new header\n");
        return -1;
    }

    new_header->NAS_MESSAGE = rand();
    new_header->PDUSESSIONID = generate_unique_PDUSESSIONID();
    new_header->RX_UE_INFORMATION_TAG = generate_RX_UE_INFORMATION_TAG();
    new_header->CRCFLAG = generate_unique_CRCFLAG(list, used_crcflags);
    new_header->prev = list->tail;
    new_header->next = NULL;

    if (list->tail) {
        list->tail->next = new_header;
    } else {
        list->head = new_header;
    }
    list->tail = new_header;

    return 0; // Success
}

// Free the entire linked list
void free_list(LinkedList *list) {
    LTE_Ngap_TransportLayerHeader *current = list->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

// Serialize the list to a binary file
int serialize_list(const char *filename, const LinkedList *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    LTE_Ngap_TransportLayerHeader *header = list->head;
    while (header) {
        fwrite(header, sizeof(LTE_Ngap_TransportLayerHeader), 1, file);
        header = header->next;
    }

    fclose(file);
    return 0; // Success
}

// Deserialize the list from a binary file
int deserialize_list(const char *filename, LinkedList **list) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return -1;
    }

    size_t header_size = sizeof(LTE_Ngap_TransportLayerHeader);
    LTE_Ngap_TransportLayerHeader buffer;

    LinkedList *new_list = init_list();
    if (!new_list) {
        fclose(file);
        return -1;
    }

    while (fread(&buffer, header_size, 1, file)) {
        LTE_Ngap_TransportLayerHeader *header = malloc(header_size);
        if (!header) {
            fprintf(stderr, "Memory allocation failed for new header\n");
            free_list(new_list);
            fclose(file);
            return -1;
        }
        memcpy(header, &buffer, header_size);

        header->prev = new_list->tail;
        if (new_list->tail) {
            new_list->tail->next = header;
        } else {
            new_list->head = header;
        }
        new_list->tail = header;
    }

    fclose(file);
    *list = new_list; // Assign the newly created list to the output pointer
    return 0; // Success
}

int main() {
    LinkedList *list = init_list();
    if (!list) return -1;

    for (int i = 0; i < 10; ++i) {
        if (add_header(list) != 0) {
            fprintf(stderr, "Error adding header\n");
            free_list(list);
            return -1;
        }
    }

    if (serialize_list("list.bin", list) != 0) {
        fprintf(stderr, "Serialization failed\n");
        free_list(list);
        return -1;
    }

    LinkedList *loaded_list = NULL;
    if (deserialize_list("list.bin", &loaded_list) != 0) {
        fprintf(stderr, "Deserialization failed\n");
        free_list(list);
        return -1;
    }

    // Use loaded_list...

    free_list(loaded_list);
    free_list(list);

    return 0;
}
