// Define a structure for network interface statistics
typedef struct {
    int interfaceID;
    double packetLoss;      // in percentage
    double latency;         // in milliseconds
    double throughput;      // in Mbps
    time_t timestamp;
} NetworkStats;

// Mutex for thread-safe operations
pthread_mutex_t statsMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate synthetic data reflecting typical network traffic patterns
void generateSyntheticData(NetworkStats *stats) {
    static const double minPacketLoss = 0.0, maxPacketLoss = 5.0;
    static const double minLatency = 10.0, maxLatency = 100.0;
    static const double minThroughput = 50.0, maxThroughput = 1000.0;

    stats->packetLoss = minPacketLoss + (rand() % 100) / 20.0; // Random loss between 0% and 5%
    stats->latency = minLatency + (rand() % 91);               // Random latency between 10ms and 100ms
    stats->throughput = minThroughput + ((rand() % 951) * 1.05); // Random throughput between 50Mbps and 1000Mbps
}

// Function to initialize network statistics for multiple interfaces
NetworkStats* initializeNetworkStats(int numInterfaces, int *numInitialized) {
    if (numInterfaces <= 0) {
        *numInitialized = 0;
        return NULL;
    }

    NetworkStats *networkStatsArray = malloc(numInterfaces * sizeof(NetworkStats));
    if (!networkStatsArray) {
        *numInitialized = 0;
        return NULL;
    }

    pthread_mutex_lock(&statsMutex);

    int initializedCount = 0;

    for (int i = 0; i < numInterfaces; ++i) {
        networkStatsArray[i].interfaceID = i + 1; // Interface IDs start from 1
        generateSyntheticData(&networkStatsArray[i]);
        networkStatsArray[i].timestamp = time(NULL); // Current timestamp

        ++initializedCount;
    }

    pthread_mutex_unlock(&statsMutex);

    *numInitialized = initializedCount;
    return networkStatsArray;
}

// Usage example (not part of the required function)
int main() {
    int numInterfaces = 10; // Example number
    int numInitialized = 0;

    NetworkStats* statsArray = initializeNetworkStats(numInterfaces, &numInitialized);

    if (statsArray) {
        for (int i = 0; i < numInitialized; ++i) {
            printf("Interface %d: Loss=%.2f%%, Latency=%.2fms, Throughput=%.2fMbps\n",
                   statsArray[i].interfaceID,
                   statsArray[i].packetLoss,
                   statsArray[i].latency,
                   statsArray[i].throughput);
        }

        free(statsArray); // Remember to free allocated memory
    } else {
        printf("Failed to initialize network statistics.\n");
    }

    return 0;
}
```

### Key Design Considerations:
- **Memory Management**: The function dynamically allocates memory for the requested number of interfaces. It ensures that if allocation fails, an empty array is returned.
- **Concurrency Handling**: A mutex (`statsMutex`) is used to prevent race conditions when initializing network stats, ensuring thread safety in a multi-threaded environment.
- **Synthetic Data Generation**: The function generates synthetic data with predefined ranges for packet loss, latency, and throughput. This reflects typical traffic patterns without accessing external resources.
- **Error Handling**: If the requested number of interfaces is non-positive or memory allocation fails, the function handles these gracefully by returning `NULL` and setting `numInitialized` to 0.
- **Time Complexity**: The initialization process has a linear time complexity O(n), where n is the number of network interfaces. This makes it efficient for large-scale monitoring scenarios.']

