#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Structure Definitions
typedef struct {
    uint16_t value;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t rnti_value;
} RNTI;

typedef struct {
    uint8_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node of the doubly linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
    struct ListNode* prev;
} ListNode;

// Doubly Linked List Structure
typedef struct {
    ListNode* head;
    ListNode* tail;
    size_t size;
    pthread_rwlock_t lock;  // For thread-safe operations
} LinkedList;

// Function Declarations
LinkedList* createList();
void destroyList(LinkedList* list);
ListNode* insertNode(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data);
int validateList(const LinkedList* list);
void serializeList(const LinkedList* list, const char* filename);
LinkedList* deserializeList(const char* filename);
void compressAndStoreData(const uint8_t* data, size_t size, const char* filename);

// Function Implementations
LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void destroyList(LinkedList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

ListNode* insertNode(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_rwlock_wrlock(&list->lock);

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_rwlock_unlock(&list->lock);
        return NULL;
    }

    new_node->data = *data;  // Copy data
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    list->size++;
    pthread_rwlock_unlock(&list->lock);
    return new_node;
}

int validateList(const LinkedList* list) {
    pthread_rwlock_rdlock(&list->lock);

    ListNode* current = list->head;
    size_t count = 0;

    while (current && count < list->size) {
        // Validate data here if needed
        if (!current->data.rx_ue_info.value || !current->data.rnti.rnti_value || (current->data.crc_indication_rel8_tag.crcFlag > 1)) {
            pthread_rwlock_unlock(&list->lock);
            return -1;  // Validation failed
        }

        current = current->next;
        count++;
    }

    if (count != list->size) {
        pthread_rwlock_unlock(&list->lock);
        return -1;  // List size mismatch
    }

