```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure as per task description
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for a doubly linked list to manage dynamic array efficiently
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Dynamic Array Manager Structure
typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} CRCArrayManager;

// Initialize the array manager
void initCRCArrayManager(CRCArrayManager* manager) {
    manager->head = NULL;
    manager->tail = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Destroy the array manager and free resources
void destroyCRCArrayManager(CRCArrayManager* manager) {
    Node* current = manager->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
}

// Check for duplicate RNTI
int hasDuplicateRNTI(CRCArrayManager* manager, int rnti) {
    Node* current = manager->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0;
}

// Add a new element ensuring no duplicate RNTI
int addElement(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (hasDuplicateRNTI(manager, element.RNTI)) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Duplicate RNTI
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    newNode->data = element;
    newNode->prev = manager->tail;
    newNode->next = NULL;

    if (manager->tail != NULL) {
        manager->tail->next = newNode;
    } else {
        manager->head = newNode;
    }

    manager->tail = newNode;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Remove element by index
int removeElement(CRCArrayManager* manager, size_t index) {
    if (index >= manager->count) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        manager->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        manager->tail = current->prev;
    }

    free(current);
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Iterate over the array in forward direction
void iterateForward(CRCArrayManager* manager, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Iterate over the array in reverse direction
void iterateReverse(CRCArrayManager* manager, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->tail;
    while (current != NULL) {
        callback(&current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example of a callback function
void printElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           element->RX_UE_INFORMATION_TAG,
           element->RNTI,
           element->CRC_INDICATION_REL8_TAG,
           element->CRCFLAG);
}

// Main function to demonstrate functionality
int main() {
    CRCArrayManager manager;
    initCRCArrayManager(&manager);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 10, rand() % 2};
    addElement(&manager, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 1002, 20, rand() % 2};
    addElement(&manager, pdu2);

    iterateForward(&manager, printElement);

    removeElement(&manager, 0);

    iterateReverse(&manager, printElement);

    destroyCRCArrayManager(&manager);
    return 0;
}
```

