#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;  // For age-based eviction
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    const char* filename;
} LinkedList;

LinkedList* create_list(const char* filename) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->filename = filename;

    return list;
}

void destroy_list(LinkedList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return pdu && pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0;
}

void add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!is_valid(element)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = *element;
    time(&new_node->timestamp);
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL || list->count < 10000) {
        new_node->next = list->head;
        list->head = new_node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        time_t timestamp;
        memcpy(&timestamp, &current->timestamp, sizeof(time_t));
        fwrite(&timestamp, sizeof(time_t), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    fclose(file);
}

void deserialize_list(LinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    destroy_list(list);  // Clear existing data

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        time_t timestamp;

        size_t result = fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (!result || feof(file)) break;

        result = fread(&timestamp, sizeof(time_t), 1, file);
        if (!result || feof(file)) break;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) continue;

        new_node->data = pdu;
        new_node->timestamp = timestamp;
        new_node->next = NULL;

        pthread_mutex_lock(&list->lock);

        if (list->head == NULL || list->count < 10000) {
            new_node->next = list->head;
            list->head = new_node;
            list->count++;
        }

        pthread_mutex_unlock(&list->lock);
    }

    fclose(file);
}

void evict_elements(LinkedList* list, time_t age_threshold) {
    pthread_mutex_lock(&list->lock);

    Node *prev = NULL, *current = list->head;

    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > age_threshold) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }

            Node* to_delete = current;
            current = current->next;

            free(to_delete);
            list->count--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void stress_test(LinkedList* list, size_t iterations) {
    for (size_t i = 0; i < iterations; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 10000;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        add_element(list, &pdu);
    }
}

int main() {
    srand(time(NULL));

    LinkedList* list = create_list("data.bin");

    // Simulate adding data
    stress_test(list, 100000);

    // Serialize to file
    serialize_list(list, "data.bin");

    // Deserialize from file
    deserialize_list(list, "data.bin");

    // Evict old elements
    evict_elements(list, 60);  // Age threshold of 1 minute

    destroy_list(list);

    return 0;
}
```

This implementation covers:

