['Below is a C implementation of a function that manages an array of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->elements = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->elements);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

bool is_rnti_unique(DynamicArray *array, int rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

bool add_element(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T new_elem) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_ELEMENTS || !is_rnti_unique(array, new_elem.RNTI)) {
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements,
                                                           (array->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    array->elements[array->count] = new_elem;
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return true;
}

bool remove_element(DynamicArray *array, size_t index) {
    if (index >= array->count) {
        return false;
    }

    pthread_mutex_lock(&array->lock);

    memmove(&array->elements[index], &array->elements[index + 1],
            (array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count--;
    if (array->count > 0 && array->count <= MAX_ELEMENTS / 2) {
        array->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, array->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&array->lock);
    return true;
}

void iterate_array(DynamicArray *array, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        func(array->elements[i]);
    }

    pthread_mutex_unlock(&array->lock);
}

void iterate_array_reverse(DynamicArray *array, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = array->count; i > 0; --i) {
        func(array->elements[i - 1]);
    }

    pthread_mutex_unlock(&array->lock);
}

void serialize_array(DynamicArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&array->count, sizeof(size_t), 1, file);
    fwrite(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, file);

    fclose(file);
    pthread_mutex_unlock(&array->lock);
}

bool deserialize_array(DynamicArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) return false;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (count > MAX_ELEMENTS) {
        fclose(file);
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    free(array->elements);
    array->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    array->count = count;

    fclose(file);
    pthread_mutex_unlock(&array->lock);
    return true;
}

// Example usage of iterate functions
void print_element(NFAPI_CRC_INDICATION_PDU_T elem) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %s\n",
           elem.RX_UE_INFORMATION_TAG, elem.RNTI, elem.CRC_INDICATION_REL8_TAG,
           elem.CRCFLAG ? "true" : "false");
}
```

### Explanation:
- **DynamicArray Structure**: Manages a dynamic array with a mutex for thread safety.
- **add_element**: Adds elements ensuring unique `RNTI` values and handles memory reallocation.
- **remove_element**: Removes elements by index, reallocating memory if necessary to optimize space.
- **iterate_array & iterate_array_reverse**: Iterates over the array in both directions safely using a mutex.
- **serialize_array & deserialize_array**: Serializes/deserializes the array to/from a binary file for persistence.
- **Memory Management**: Ensures proper allocation, deallocation, and resizing of memory.
- **Thread Safety**: Uses mutex locks to ensure safe concurrent access.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_array() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = array->tail = NULL;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_node(Node* node) {
    free(node);
}

int find_rnti(DynamicArray* array, int rnti) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&array->lock);
            return 1; // Found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return 0; // Not found
}

int add_element(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (find_rnti(array, element.RNTI)) {
        return -1; // Duplicate RNTI
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -2; // Allocation failed

    new_node->data = element;
    pthread_mutex_lock(&array->lock);

    if (array->tail == NULL) {
        array->head = array->tail = new_node;
        new_node->next = new_node->prev = NULL;
    } else {
        array->tail->next = new_node;
        new_node->prev = array->tail;
        new_node->next = NULL;
        array->tail = new_node;
    }

    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int remove_element(DynamicArray* array, size_t index) {
    if (index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);
    Node* current = array->head;

    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Invalid index
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        array->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        array->tail = current->prev;
    }

    free_node(current);
    array->size--;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void iterate_forward(DynamicArray* array, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;

    while (current != NULL) {
        func(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void iterate_reverse(DynamicArray* array, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->tail;

    while (current != NULL) {
        func(current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free_node(current);
        current = next_node;
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG, pdu.CRCFLAG);
}

int main() {
    DynamicArray* array = create_array();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, 5, rand() % 2};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2, 1002, 6, rand() % 2};

    add_element(array, pdu1);
    add_element(array, pdu2);

    iterate_forward(array, print_pdu);

    remove_element(array, 0);

    iterate_reverse(array, print_pdu);

    free_array(array);
    return 0;
}
```

This code manages a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring unique RNTI values during insertion, with thread-safe operations for adding, removing, and iterating elements. The memory is efficiently managed and freed when no longer needed.']

