int updateEntry(DynamicArrayLTE_PHY_RX_T* dynArray, size_t index, PHY_RX_UE_TAG ue_tag, RX_TX_CONFIG_TAG config_tag);
void iterateEntries(const DynamicArrayLTE_PHY_RX_T* dynArray, void (*callback)(const LTE_PHY_RX_T* entry));
void freeDynamicArray(DynamicArrayLTE_PHY_RX_T* dynArray);

// Function implementations
void initDynamicArray(DynamicArrayLTE_PHY_RX_T* dynArray) {
    dynArray->size = 0;
    dynArray->capacity = 10; // Initial capacity, can be adjusted based on expected load
    dynArray->array = (LTE_PHY_RX_T*)malloc(dynArray->capacity * sizeof(LTE_PHY_RX_T));
    if (!dynArray->array) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
}

int addEntry(DynamicArrayLTE_PHY_RX_T* dynArray, PHY_RX_UE_TAG ue_tag, RX_TX_CONFIG_TAG config_tag) {
    if (dynArray->size >= dynArray->capacity) {
        size_t new_capacity = dynArray->capacity * 2;
        LTE_PHY_RX_T* new_array = (LTE_PHY_RX_T*)realloc(dynArray->array, new_capacity * sizeof(LTE_PHY_RX_T));
        if (!new_array) {
            perror("Failed to reallocate memory for dynamic array");
            return -1;
        }
        dynArray->array = new_array;
        dynArray->capacity = new_capacity;
    }

    LTE_PHY_RX_T* entry = &dynArray->array[dynArray->size++];
    entry->ue_tag = ue_tag;
    entry->config_tag = config_tag;

    return 0; // Success
}

int updateEntry(DynamicArrayLTE_PHY_RX_T* dynArray, size_t index, PHY_RX_UE_TAG ue_tag, RX_TX_CONFIG_TAG config_tag) {
    if (index >= dynArray->size) {
        fprintf(stderr, "Index out of bounds\n");
        return -1;
    }

    LTE_PHY_RX_T* entry = &dynArray->array[index];
    entry->ue_tag = ue_tag;
    entry->config_tag = config_tag;

    return 0; // Success
}

void iterateEntries(const DynamicArrayLTE_PHY_RX_T* dynArray, void (*callback)(const LTE_PHY_RX_T* entry)) {
    for (size_t i = 0; i < dynArray->size; ++i) {
        callback(&dynArray->array[i]);
    }
}

void freeDynamicArray(DynamicArrayLTE_PHY_RX_T* dynArray) {
    if (dynArray && dynArray->array) {
        free(dynArray->array);
        dynArray->array = NULL;
        dynArray->size = 0;
        dynArray->capacity = 0;
    }
}

// Example callback function for iteration
void printEntry(const LTE_PHY_RX_T* entry) {
    printf("UE Tag: %d, Config Tag: %d\n", entry->ue_tag.some_rx_tag, entry->config_tag.some_tx_config);
}

// Usage example
int main() {
    DynamicArrayLTE_PHY_RX_T dynArray;
    initDynamicArray(&dynArray);

    PHY_RX_UE_TAG ueTag1 = { .some_rx_tag = 1 };
    RX_TX_CONFIG_TAG configTag1 = { .some_tx_config = 100 };

    addEntry(&dynArray, ueTag1, configTag1);

    PHY_RX_UE_TAG ueTag2 = { .some_rx_tag = 2 };
    RX_TX_CONFIG_TAG configTag2 = { .some_tx_config = 200 };

    addEntry(&dynArray, ueTag2, configTag2);

    iterateEntries(&dynArray, printEntry);

    freeDynamicArray(&dynArray);
    return 0;
}
