#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 500

typedef struct {
    int CELL_ID;
    int TIME_SLICE;
    int CHANNEL_QUALITY_INDICATOR; // CQI
    float SNR;
} PHY_STATS_RECORD_T;

typedef struct Node {
    PHY_STATS_RECORD_T record;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

int is_valid_snr(float snr) {
    return snr >= -10.0 && snr <= 30.0; // Example valid SNR range
}

Node* find_node(DoublyLinkedList* list, int cell_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->record.CELL_ID == cell_id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_node(DoublyLinkedList* list, Node* node) {
    if (node->prev)
        node->prev->next = node->next;
    else
        list->head = node->next;

    if (node->next)
        node->next->prev = node->prev;
    else
        list->tail = node->prev;

    free(node);
}

void add_entry(DoublyLinkedList* list, PHY_STATS_RECORD_T new_record) {
    pthread_mutex_lock(&list->lock);

    if (!is_valid_snr(new_record.SNR)) {
        fprintf(stderr, "Error: Invalid SNR value\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* existing_node = find_node(list, new_record.CELL_ID);
    if (existing_node) {
        existing_node->record.SNR = new_record.SNR; // Update existing record
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->record = new_record;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;

    if (list->size >= MAX_ENTRIES) {
        Node* oldest = list->head;
        remove_node(list, oldest);
        free(oldest);
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_entry(DoublyLinkedList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);

    Node* node_to_remove = find_node(list, cell_id);
    if (node_to_remove) {
        remove_node(list, node_to_remove);
    } else {
        fprintf(stderr, "Error: CELL_ID not found\n");
    }

    pthread_mutex_unlock(&list->lock);
}

PHY_STATS_RECORD_T* get_entry(DoublyLinkedList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);

    Node* node = find_node(list, cell_id);
    PHY_STATS_RECORD_T* record = NULL;
    if (node) {
        // Move the accessed node to the tail
        if (node != list->tail) {
            if (node == list->head)
                list->head = node->next;

            node->prev->next = node->next;
            if (node->next)
                node->next->prev = node->prev;

            node->next = NULL;
            node->prev = list->tail;
            if (list->tail) {
                list->tail->next = node;
            }
            list->tail = node;
        }

        record = &node->record;
    } else {
        fprintf(stderr, "Error: CELL_ID not found\n");
    }

    pthread_mutex_unlock(&list->lock);
    return record;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    srand(time(NULL));
    DoublyLinkedList* stats_list = create_list();

    PHY_STATS_RECORD_T record1 = {1, 0, 10, (float)(rand() % 41 - 10)};
    add_entry(stats_list, record1);

    PHY_STATS_RECORD_T* retrieved_record = get_entry(stats_list, 1);
    if (retrieved_record) {
        printf("Retrieved CELL_ID: %d, SNR: %.2f\n", retrieved_record->CELL_ID, retrieved_record->SNR);
    }

    remove_entry(stats_list, 1);

    destroy_list(stats_list);
    return 0;
}
