#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_linked_list(LinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    Node* current = list->head;
    while (current) {
        if (fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            fclose(file);
            return -1;
        }
        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserialize_linked_list(LinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insert_node(list, data);
    }

    fclose(file);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand((unsigned int)time(NULL));

    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return pdu;
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MAX_NODES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        if (insert_node(list, pdu) != 0) {
            fprintf(stderr, "Failed to insert node\n");
            free_linked_list(list);
            return EXIT_FAILURE;
        }
    }

    if (serialize_linked_list(list, "nfa_data.bin") != 0) {
        fprintf(stderr, "Serialization failed\n");
        free_linked_list(list);
        return EXIT_FAILURE;
    }

    LinkedList* new_list = create_linked_list();
    if (!new_list || deserialize_linked_list(new_list, "nfa_data.bin") != 0) {
        fprintf(stderr, "Deserialization failed\n");
        free_linked_list(list);
        free_linked_list(new_list);
        return EXIT_FAILURE;
    }

    // Cleanup
    free_linked_list(list);
    free_linked_list(new_list);

    return EXIT_SUCCESS;
}
