#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_CRC_REQUESTS 10
#define MIN_CRC_REQUESTS 5

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint8_t *data; // Placeholder for RX_UE_INFORMATION_TAG data
    size_t length;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} CRC_DATA_T;

typedef struct {
    CRC_DATA_T *queue;
    int front, rear, capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
    int current_rate_limit;
    int successful_requests, failed_requests;
    FILE *log_file;
    pthread_t monitor_thread;
} CRC_Queue;

typedef struct {
    double packet_loss;
    double latency;
    double throughput;
} NetworkLoadMetrics;

int validate_RX_UE_INFORMATION_TAG(RX_UE_INFORMATION_TAG tag) {
    // Placeholder for actual validation logic
    return (tag.length > 0 && tag.data != NULL);
}

void adjust_rate_limit(CRC_Queue *queue, NetworkLoadMetrics metrics) {
    pthread_mutex_lock(&queue->lock);
    if (metrics.packet_loss > 0.1 || metrics.latency > 100) {
        queue->current_rate_limit = MAX(queue->current_rate_limit - 1, MIN_CRC_REQUESTS);
    } else if (metrics.throughput < 50) {
        queue->current_rate_limit = MIN(queue->current_rate_limit + 1, MAX_CRC_REQUESTS);
    }
    pthread_mutex_unlock(&queue->lock);
}

void log_message(CRC_Queue *queue, const char *level, const char *message) {
    if (queue->log_file) {
        fprintf(queue->log_file, "[%s] %s\n", level, message);
        fflush(queue->log_file);
    }
}

void* monitor_network_load(void *arg) {
    CRC_Queue *queue = (CRC_Queue *)arg;
    NetworkLoadMetrics metrics;

    while (1) {
        // Simulate fetching network load metrics
        metrics.packet_loss = 0.05; // Placeholder value
        metrics.latency = 50;       // Placeholder value
        metrics.throughput = 60;    // Placeholder value

        adjust_rate_limit(queue, metrics);
        sleep(1); // Adjust interval as needed
    }
    return NULL;
}

void initialize_queue(CRC_Queue *queue, int capacity) {
    queue->queue = (CRC_DATA_T *)malloc(capacity * sizeof(CRC_DATA_T));
    queue->capacity = capacity;
    queue->front = queue->rear = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    queue->current_rate_limit = MIN_CRC_REQUESTS;
    queue->successful_requests = 0;
    queue->failed_requests = 0;
    queue->log_file = fopen("crc_log.txt", "a");
    if (pthread_create(&queue->monitor_thread, NULL, monitor_network_load, queue) != 0) {
        perror("Failed to create monitoring thread");
        exit(EXIT_FAILURE);
    }
}

void enqueue(CRC_Queue *queue, CRC_DATA_T item) {
    pthread_mutex_lock(&queue->lock);

    while ((queue->rear + 1) % queue->capacity == queue->front && 
           queue->successful_requests >= queue->current_rate_limit) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    if (!validate_RX_UE_INFORMATION_TAG(item.ue_info)) {
        log_message(queue, "ERROR", "Invalid RX_UE_INFORMATION_TAG");
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    queue->queue[queue->rear] = item;
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->successful_requests++;

    log_message(queue, "INFO", "CRC indication enqueued");

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

CRC_DATA_T dequeue(CRC_Queue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (queue->front == queue->rear) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    CRC_DATA_T item = queue->queue[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    log_message(queue, "INFO", "CRC indication dequeued");

    pthread_mutex_unlock(&queue->lock);
    return item;
}

void cleanup_queue(CRC_Queue *queue) {
    fclose(queue->log_file);
    pthread_join(queue->monitor_thread, NULL);
    free(queue->queue);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
}
