    pthread_mutex_init(&limiter->mutex, NULL);

    // Initialize historical load metrics
    memset(limiter->historical_load, 0, sizeof(limiter->historical_load));

    log_file = fopen("crc_indications.log", "w");
    if (!log_file) {
        free(limiter->entries);
        free(limiter);
        log_message(0, "Failed to open log file.");
        return NULL;
    }

    return limiter;
}

void destroy_rate_limiter(RateLimiter* limiter) {
    if (limiter) {
        pthread_mutex_destroy(&limiter->mutex);
        free(limiter->entries);
        free(limiter);

        if (log_file) {
            fclose(log_file);
        }
    }
}
