#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_THRESHOLD 1024 * 1024 // 1MB for example

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[10];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    int sequence_number;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t current_memory_usage;
    FILE* log_file;
} DynamicLinkedList;

DynamicLinkedList* create_list() {
    DynamicLinkedList* list = (DynamicLinkedList*)malloc(sizeof(DynamicLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->current_memory_usage = 0;
    list->log_file = fopen("nfaapi_log.txt", "a");
    if (!list->log_file) {
        free(list);
        return NULL;
    }
    return list;
}

int is_memory_threshold_exceeded(DynamicLinkedList* list) {
    return (list->current_memory_usage > MEMORY_THRESHOLD);
}

void log_action(const char* action, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!data || !action) return;
    fprintf(list->log_file, "%s: RXUE=%d, RNTI=%d, CRCFLAG=%d\n", action,
            data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRCFLAG);
    fflush(list->log_file);
}

int initialize_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1;

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    pdu->RNTI = rand() % 1000;
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    pdu->CRCFLAG = rand() % 2;

    return 0;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    *(&new_node->data) = *(NFAPI_CRC_INDICATION_PDU_T*)pdu;
    new_node->sequence_number = rand() % 10000; // Example sequence number
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    return new_node;
}

int insert_node(DynamicLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    pthread_mutex_lock(&list->lock);

    Node* node = create_node(pdu);
    if (!node) {
        pthread_mutex_unlock(&list->lock);
        log_action("Memory allocation failed for new node", NULL);
        return -1;
    }

    if (is_memory_threshold_exceeded(list)) {
        free(node);
        pthread_mutex_unlock(&list->lock);
        log_action("Insertion skipped: Memory threshold exceeded", pdu);
        return -2;
    }

    node->next = list->head;
    list->head = node;

    log_action("Inserted new node", &node->data);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(DynamicLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    fclose(list->log_file);
    free(list);
}

void batch_update_nodes(DynamicLinkedList* list, int (*update_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !update_func) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        update_func(&current->data);
        log_action("Updated node", &current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int example_update_function(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1;

    // Example modification: toggle CRCFLAG
    pdu->CRCFLAG = !pdu->CRCFLAG;
    return 0;
}

void monitor_and_adjust(DynamicLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    while (is_memory_threshold_exceeded(list)) {
        if (!list->head) break;

        Node* to_delete = list->head;
        log_action("Deleted node due to memory threshold", &to_delete->data);

        list->head = to_delete->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    DynamicLinkedList* nfa_list = create_list();
    if (!nfa_list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < 100; ++i) {
        initialize_pdu(&pdu);
        insert_node(nfa_list, &pdu);

        // Monitoring and adjusting
        monitor_and_adjust(nfa_list);
    }

    batch_update_nodes(nfa_list, example_update_function);

    free_list(nfa_list);
    return 0;
}
