    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->read_cache.elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache_size);
    if (!list->read_cache.elements) {
        fprintf(stderr, "Memory allocation failed for read cache.\n");
        pthread_mutex_destroy(&list->lock);
        exit(EXIT_FAILURE);
    }
    list->read_cache.capacity = cache_size;
    list->read_cache.size = 0;
}

// Function to add a new element to the doubly linked list
