} CircularBuffer;

CircularBuffer* create_circular_buffer(size_t capacity) {
    CircularBuffer *cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) return NULL;

    cb->buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cb->buffer) {
        free(cb);
        return NULL;
    }

    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;

    pthread_mutex_init(&cb->lock, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
    pthread_cond_init(&cb->not_full, NULL);

    return cb;
}

void destroy_circular_buffer(CircularBuffer *cb) {
    if (cb) {
        free(cb->buffer);
        pthread_mutex_destroy(&cb->lock);
        pthread_cond_destroy(&cb->not_empty);
        pthread_cond_destroy(&cb->not_full);
        free(cb);
    }
}

bool is_full(CircularBuffer *cb) {
    return cb->count == cb->capacity;
}

bool is_empty(CircularBuffer *cb) {
    return cb->count == 0;
}

void enqueue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&cb->lock);

    while (is_full(cb)) {
        pthread_cond_wait(&cb->not_full, &cb->lock);
    }

    cb->buffer[cb->tail] = item;
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count++;

    pthread_cond_signal(&cb->not_empty);

    pthread_mutex_unlock(&cb->lock);
}

bool dequeue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&cb->lock);

    while (is_empty(cb)) {
        pthread_cond_wait(&cb->not_empty, &cb->lock);
    }

    *item = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % cb->capacity;
    cb->count--;

    pthread_cond_signal(&cb->not_full);

    pthread_mutex_unlock(&cb->lock);
    return true;
}

void* producer(void *arg) {
    CircularBuffer *cb = (CircularBuffer*)arg;

    for (size_t i = 0; i < BUFFER_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        enqueue(cb, pdu);
    }

    return NULL;
}

void* consumer(void *arg) {
    CircularBuffer *cb = (CircularBuffer*)arg;

    for (size_t i = 0; i < BUFFER_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        dequeue(cb, &pdu);
    }

    return NULL;
}

int main() {
    CircularBuffer *cb = create_circular_buffer(100);

    pthread_t prod_thread, cons_thread;

    pthread_create(&prod_thread, NULL, producer, cb);
    pthread_create(&cons_thread, NULL, consumer, cb);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    destroy_circular_buffer(cb);

    return 0;
}
```

This code defines a circular buffer with thread-safe operations using mutexes and condition variables to manage concurrent access. The producer-consumer pattern is implemented with threads to simulate data processing scenarios. Adjust the buffer size and capacity as needed for your specific use case.']

