#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int frequency;
    int cgi; // Cell Global Identity
} MeasurementResult_t;

typedef struct MeasurementResultNode {
    MeasurementResult_t result;
    struct MeasurementResultNode* next;
} MeasurementResultNode_t;

typedef struct {
    MeasurementResultNode_t* head;
} MeasurementReport_t;

typedef struct {
    int ue_id;
    char name[64];
} UEIdentity_t;

typedef struct {
    UEIdentity_t ue_identity;
    MeasurementReport_t report;
} LTE_UERadioMeasRepPdu_t;

#define HASH_TABLE_SIZE 1024

// A thread-safe hash table for storing MeasurementResult_t entries
static MeasurementResultNode_t* hash_table[HASH_TABLE_SIZE];
static pthread_mutex_t hash_table_locks[HASH_TABLE_SIZE];

void initialize_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_table_locks[i], NULL);
    }
}

unsigned int hash(int frequency, int cgi) {
    return ((frequency * 31 + cgi) % HASH_TABLE_SIZE);
}

// Function to add a measurement result
void add_measurement_result(LTE_UERadioMeasRepPdu_t* pdu, MeasurementResult_t new_result) {
    unsigned int index = hash(new_result.frequency, new_result.cgi);
    pthread_mutex_lock(&hash_table_locks[index]);

    // Check for duplicate entries
    MeasurementResultNode_t* current = hash_table[index];
    while (current != NULL) {
        if (current->result.frequency == new_result.frequency &&
            current->result.cgi == new_result.cgi) {
            pthread_mutex_unlock(&hash_table_locks[index]);
            return; // Duplicate found, do nothing
        }
        current = current->next;
    }

    // Add new entry to the linked list at this hash index
    MeasurementResultNode_t* new_node = malloc(sizeof(MeasurementResultNode_t));
    if (new_node == NULL) {
        pthread_mutex_unlock(&hash_table_locks[index]);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->result = new_result;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&hash_table_locks[index]);
}

// Function to remove a measurement result
void remove_measurement_result(LTE_UERadioMeasRepPdu_t* pdu, int frequency, int cgi) {
    unsigned int index = hash(frequency, cgi);
    pthread_mutex_lock(&hash_table_locks[index]);

    MeasurementResultNode_t *current = hash_table[index], *prev = NULL;
    while (current != NULL) {
        if (current->result.frequency == frequency && current->result.cgi == cgi) {
            if (prev == NULL) {
                hash_table[index] = current->next; // Remove head
            } else {
                prev->next = current->next; // Bypass the node to remove
            }
            free(current);
            pthread_mutex_unlock(&hash_table_locks[index]);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&hash_table_locks[index]); // Node not found, do nothing
}

// Function to update a measurement result (simplified as removal and addition)
void update_measurement_result(LTE_UERadioMeasRepPdu_t* pdu, MeasurementResult_t old_result, MeasurementResult_t new_result) {
    remove_measurement_result(pdu, old_result.frequency, old_result.cgi);
    add_measurement_result(pdu, new_result);
}

// Function to initialize a dynamic array of LTE_UERadioMeasRepPdu_t
LTE_UERadioMeasRepPdu_t* init_dynamic_array(size_t initial_capacity) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    LTE_UERadioMeasRepPdu_t* array = malloc(sizeof(LTE_UERadioMeasRepPdu_t) * initial_capacity);
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t array_lock;
    pthread_mutex_init(&array_lock, &attr);

    for (size_t i = 0; i < initial_capacity; ++i) {
        array[i].ue_identity.ue_id = -1; // Indicates uninitialized entry
        array[i].report.head = NULL;
    }

    return array;
}

// Ensure to call this at the end of your program or when cleaning up resources
void cleanup() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        MeasurementResultNode_t* current = hash_table[i];
        while (current != NULL) {
            MeasurementResultNode_t* temp = current;
            current = current->next;
            free(temp);
        }
        pthread_mutex_destroy(&hash_table_locks[i]);
    }
}

// Note: This is a simple implementation. Considerations for dynamic resizing and scaling
// with more advanced synchronization mechanisms (like read-write locks) can further optimize.
```

### Key Design Choices:
- **Hash Table**: Used to manage `MeasurementResult_t` entries efficiently, balancing speed of insertion, deletion, and lookup.
- **Thread Safety**: Individual mutexes per hash table bucket reduce lock contention, allowing for concurrent access while maintaining integrity.
- **Memory Management**: Dynamic allocation allows the structure array to be resized as needed. Use mutex locks for thread safety when manipulating shared data structures.

This implementation provides a starting point but can be extended with more sophisticated synchronization and memory management strategies as required by your application's specific needs.']

