#include <stdatomic.h>

#define MAX_MEMORY_USAGE 1048576 // Example max memory usage in bytes
#define BUFFER_SIZE_LIMIT 524288 // Example buffer size limit
#define RECORD_COUNT 1000        // Number of records to initialize
#define VALUE_RANGE_MIN 1        // Min value for random int generation
#define VALUE_RANGE_MAX 100      // Max value for random int generation
#define VALUE_SUM_LIMIT 50000    // Limit on the sum of random values

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    CRC_INDICATION_REL8_TAG_T crc_tag;
    uint16_t rnti;
    uint32_t rx_ue_information_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
    char *buffer;
    time_t timestamp;
} Record_T;

// Global lock for thread-safe operations
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(Record_T *records, size_t record_count) {
    srand(time(NULL));

    atomic_int current_sum = 0;
    size_t total_buffer_size = 0;

    for (size_t i = 0; i < record_count; ++i) {
        int value = VALUE_RANGE_MIN + rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1);

        // Ensure the sum does not exceed the limit
        if (atomic_fetch_add(&current_sum, value) > VALUE_SUM_LIMIT) {
            atomic_fetch_sub(&current_sum, value); // Revert addition
            continue;
        }

        size_t buffer_size = rand() % 1024 + 1; // Random buffer size between 1 and 1024 bytes

        if (total_buffer_size + buffer_size > BUFFER_SIZE_LIMIT) {
            break; // Stop if adding more buffers exceeds the limit
        }

        char *buffer = malloc(buffer_size);

        if (!buffer) {
            perror("Failed to allocate memory for buffer");
            continue;
        }

        total_buffer_size += buffer_size;

        records[i].value = value;
        records[i].buffer = buffer;
        records[i].timestamp = time(NULL);

        // Log the initialization
        printf("Record %zu initialized with value %d, buffer size %zu\n", i, value, buffer_size);
    }
}

void cleanup_records(Record_T *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].buffer);
    }
}

int main() {
    // Allocate memory for records
    Record_T *records = malloc(RECORD_COUNT * sizeof(Record_T));

    if (!records) {
        perror("Failed to allocate memory for records");
        return EXIT_FAILURE;
    }

    // Initialize records in a separate thread for concurrency
    pthread_t init_thread;
    pthread_create(&init_thread, NULL, (void *(*)(void *))initialize_records, records);
    pthread_join(init_thread, NULL);

    // Cleanup
    cleanup_records(records, RECORD_COUNT);
    free(records);

    return EXIT_SUCCESS;
}
