} LinkedList;

void initialize_list(LinkedList* list, int log_enabled) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->log_enabled = log_enabled;
}

int log_message(const char* message, LinkedList* list) {
    if (!list->log_enabled || strlen(message) >= MAX_LOG_SIZE) return 0;

    snprintf(list->log_buffer, MAX_LOG_SIZE, "%s", message);
    printf("%s\n", list->log_buffer); // Using printf for simplicity
    return 1;
}

int create_node(NFAPI_CRC_INDICATION_PDU_T* data_ptr, Node** node_out) {
    *node_out = (Node*)malloc(sizeof(Node));
    if (*node_out == NULL) return -1;

    NFAPI_CRC_INDICATION_PDU_T data = *data_ptr;
    // Randomly set CRCFLAG
    data.CRCFLAG = rand() % 2;

    (*node_out)->data = data;
    (*node_out)->next = NULL;
    (*node_out)->prev = NULL; // For doubly linked list

    return 0;
}

int insert_head(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data_ptr) {
    pthread_mutex_lock(&list->lock);

    Node* new_node;
    if (create_node(data_ptr, &new_node) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->next = list->head;
        list->head->prev = new_node;  // For doubly linked list
        list->head = new_node;
    }

    list->size++;
    if (log_message("Inserted at head", list)) {}

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int insert_tail(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data_ptr) {
    pthread_mutex_lock(&list->lock);

    Node* new_node;
    if (create_node(data_ptr, &new_node) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;  // For doubly linked list
        list->tail = new_node;
    }

    list->size++;
    if (log_message("Inserted at tail", list)) {}

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_by_rnti(LinkedList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (current->prev != NULL) current->prev->next = current->next;  // For doubly linked list
            else list->head = current->next;

            if (current->next != NULL) current->next->prev = current->prev;  // For doubly linked list
            else list->tail = current->prev;

            free(current);
            list->size--;

            if (log_message("Removed by RNTI", list)) {}
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void free_list(LinkedList* list) {
    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    memset(list, 0, sizeof(LinkedList)); // Clearing the structure
}

int main() {
    LinkedList list;
    initialize_list(&list, 1); // Enable logging for debugging

    NFAPI_CRC_INDICATION_PDU_T data = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 12345, .CRC_INDICATION_REL8_TAG = 2 };

    insert_head(&list, &data);
    insert_tail(&list, &data);

    remove_by_rnti(&list, 12345);

    free_list(&list);
    return 0;
}
