    Node* new_node = allocate_node();
    if (!new_node) return;

    pthread_mutex_lock(&manager->list.lock);

    new_node->data = structure;
    new_node->next = manager->list.head;
    manager->list.head = new_node;
    manager->list.size++;

    pthread_mutex_unlock(&manager->list.lock);

