    unsigned char* compressed_data = malloc(compressed_size);

    if (compress(compressed_data, &compressed_size, buffer, serialized_size) == Z_OK) {
        // Handle compressed data...
    }

    free(compressed_data);
}

void load_balance(NFAPIManager* manager) {
    while (!manager->work_queue.empty()) {
        Node* node = manager->work_queue.get();

        manager->executor.submit(process_structure, manager, node);

        pthread_mutex_lock(&manager->list.lock);
        if (node == manager->list.head) {
            manager->list.head = node->next;
        } else {
            Node* current = manager->list.head;
            while (current && current->next != node) {
                current = current->next;
