void save_to_disk(NFAPIManager* manager) {
    pthread_rwlock_wrlock(&manager->rwlock);

    Node* current = manager->list.head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, manager->persistence_file);
        current = current->next;
    }

    fflush(manager->persistence_file); // Ensure data is written to disk
    pthread_rwlock_unlock(&manager->rwlock);
