// Define a structure for file metadata
typedef struct UDT_FILE_METADATA_T {
    char *file_path;
    size_t file_size;
    time_t creation_timestamp;
    char access_permissions[16];
    struct UDT_FILE_METADATA_T *next;
} UDT_FILE_METADATA_T;

// Function prototypes
void log_error(const char *message);
UDT_FILE_METADATA_T* create_file_metadata_node(const char *file_path, size_t file_size,
                                               time_t creation_timestamp, const char *access_permissions);
int add_unique_file_metadata(UDT_FILE_METADATA_T **head, UDT_FILE_METADATA_T *new_node);

// Global mutex for thread safety
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    // Placeholder for integrating with an external logging system
    fprintf(stderr, "Error: %s\n", message);
}

UDT_FILE_METADATA_T* create_file_metadata_node(const char *file_path, size_t file_size,
                                               time_t creation_timestamp, const char *access_permissions) {
    UDT_FILE_METADATA_T *new_node = (UDT_FILE_METADATA_T*)malloc(sizeof(UDT_FILE_METADATA_T));
    if (!new_node) {
        log_error("Memory allocation failed for new node");
        return NULL;
    }

    // Allocate memory for file path
    new_node->file_path = strdup(file_path);
    if (!new_node->file_path) {
        free(new_node);
        log_error("Memory allocation failed for file path");
        return NULL;
    }

    new_node->file_size = file_size;
    new_node->creation_timestamp = creation_timestamp;
    strncpy(new_node->access_permissions, access_permissions, sizeof(new_node->access_permissions) - 1);
    new_node->next = NULL;

    return new_node;
}

int add_unique_file_metadata(UDT_FILE_METADATA_T **head, UDT_FILE_METADATA_T *new_node) {
    if (!*head || !new_node) {
        log_error("Invalid arguments provided to add_unique_file_metadata");
        return -1;
    }

    pthread_mutex_lock(&list_lock);

    // Check for duplicates
    UDT_FILE_METADATA_T *current = *head;
    while (current) {
        if (strcmp(current->file_path, new_node->file_path) == 0) {
            log_error("Duplicate file path detected. Skipping insertion.");
            pthread_mutex_unlock(&list_lock);
            free(new_node->file_path);
            free(new_node);
            return -1;
        }
        current = current->next;
    }

    // Add to the front of the list for O(1) insertion
    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_lock);
    return 0;
}

void free_file_metadata_list(UDT_FILE_METADATA_T **head) {
    if (!*head) return;

    pthread_mutex_lock(&list_lock);

    UDT_FILE_METADATA_T *current = *head;
    while (current) {
        UDT_FILE_METADATA_T *next_node = current->next;
        free(current->file_path);
        free(current);
        current = next_node;
    }

    *head = NULL;

    pthread_mutex_unlock(&list_lock);
}
