void generate_pdus(Config_T config) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    uint16_t recent_rntis[HISTORY_SIZE] = {0};
    int recent_index = 0;

    srand(config.seed);

    if (config.N > config.buffer_size_limit / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        config.log_function("Buffer size limit too small for the number of PDUs.");
        return;
