    uint16_t last_rnti = 0;

    for (int i = 0; i < config.N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];

        do {
            pdu->RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
            pdu->RNTI = rand() % MAX_RNTI;

            if (pdu->RNTI == last_rnti) {
                continue; // Ensure no two consecutive PDUs have the same RNTI
            }
        } while (check_recent_rnti_conflicts(recent_rntis, pdu->RNTI, HISTORY_SIZE));

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        recent_rntis[recent_index] = pdu->RNTI;
        recent_index = (recent_index + 1) % HISTORY_SIZE;

        last_rnti = pdu->RNTI;

        // Rate limiting placeholder
