            config.log_function("Rate limiting: Pausing generation.");
            // Simulate a delay or check system load here
        }

        config.log_function("Generated PDU with RNTI: ");
        printf("%u\n", pdu->RNTI);
    }

    free(pdus);
}

int main() {
