    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListElement* next;
} ListElement;

typedef struct {
    ListElement* head;
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int contains_RNTI(DynamicList* list, uint16_t RNTI) {
    ListElement* current = list->head;
    while (current) {
        if (current->data.ue_info.RNTI == RNTI) return 1;
        current = current->next;
    }
    return 0;
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (contains_RNTI(list, element.ue_info.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI
    }

    ListElement* new_element = (ListElement*)malloc(sizeof(ListElement));
    if (!new_element) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_element->data = element;
    new_element->next = list->head;
    list->head = new_element;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int get_statistics(DynamicList* list, int* unique_RNTIs, int* total_elements, size_t* memory_allocated) {
    if (!list || !unique_RNTIs || !total_elements || !memory_allocated) return -1;

    pthread_mutex_lock(&list->lock);
    *unique_RNTIs = 0;
    *total_elements = list->size;

    ListElement* current = list->head;
    uint16_t RNTI_tracker[10000] = {0}; // Adjust size as needed

    while (current) {
        if (!RNTI_tracker[current->data.ue_info.RNTI]) {
            (*unique_RNTIs)++;
            RNTI_tracker[current->data.ue_info.RNTI] = 1;
        }
        current = current->next;
    }

    *memory_allocated = sizeof(DynamicList) + list->size * sizeof(ListElement);
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    ListElement* current = list->head;
    while (current) {
        ListElement* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    DynamicList* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T element;
    element.ue_info.RNTI = 12345;
    element.CRC_INDICATION_REL8_TAG = 1;

    add_element(list, element);

    int unique_RNTIs, total_elements;
    size_t memory_allocated;
    get_statistics(list, &unique_RNTIs, &total_elements, &memory_allocated);

    printf("Unique RNTIs: %d\n", unique_RNTIs);
    printf("Total elements: %d\n", total_elements);
    printf("Memory allocated: %zu bytes\n", memory_allocated);

    free_list(list);
    return 0;
}
