static pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;
uint16_t thread_safe_random(uint16_t min, uint16_t max) {
    pthread_mutex_lock(&rand_mutex);
    static unsigned int last_seed = 0;
    if (last_seed == 0) {
        srand(time(NULL));
        last_seed = rand();
    }
    uint16_t value = (rand_r(&last_seed) % (max - min + 1)) + min;
    pthread_mutex_unlock(&rand_mutex);
    return value;
}

// Logging function prototype
void log_message(const char *message);

NFAPI_CRC_INDICATION_PDU_T* generate_PDUs(Config config, void (*log_func)(const char*)) {
    if (!config.N) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(config.N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_func("Memory allocation failed for PDUs");
        return NULL;
    }

    pthread_mutex_lock(&rand_mutex);
    srand(config.seed);
    uint16_t last_RNTI = 0;

    // Generate PDUs
    for (size_t i = 0; i < config.N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = thread_safe_random(1, 10000);

        uint16_t rnti;
        do {
            rnti = thread_safe_random(1, 65535); // Example range for RNTI
        } while (rnti == last_RNTI);

        pdus[i].RNTI = rnti;
        last_RNTI = rnti;

        pdus[i].CRCFLAG = (thread_safe_random(0, 1) != 0); // Randomly set to 0 or 1
    }

    pthread_mutex_unlock(&rand_mutex);

    log_func("PDUs generated successfully");

    return pdus;
}

void log_message(const char *message) {
    printf("%s\n", message);
}
