int dynamic_array_init(DynamicArray *darr, size_t initial_capacity) {
    if (!darr || initial_capacity == 0) return -1;

    darr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!darr->array) return -2; // Allocation failed

    darr->capacity = initial_capacity;
    darr->count = 0;
    pthread_mutex_init(&darr->lock, NULL);

