}

int dynamic_array_resize(DynamicArray *darr, size_t new_capacity) {
    if (!darr || new_capacity == 0 || new_capacity < darr->count) return -1;

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(darr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
