    // Resize if necessary
    if (darr->count == darr->capacity) {
        int res = dynamic_array_resize(darr, darr->capacity ? 2 * darr->capacity : 1);
        if (res != 0) {
            pthread_mutex_unlock(&darr->lock);
            return;
        }
    }

    // Add the item
    darr->array[darr->count++] = *item;

    pthread_mutex_unlock(&darr->lock);
}

