    char* RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_INFORMATION;

typedef struct {
    UE_INFORMATION ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool for optimization
typedef struct {
    size_t item_size;
    void *pool[MAX_POOL_SIZE];
    size_t num_items;
} MemoryPool;

void initialize_pool(MemoryPool *mp, size_t item_size) {
    mp->item_size = item_size;
    mp->num_items = 0;
}

void* pool_alloc(MemoryPool *mp) {
    if (mp->num_items >= MAX_POOL_SIZE) return NULL;
    void *ptr = malloc(mp->item_size);
    if (!ptr) return NULL;
    mp->pool[mp->num_items++] = ptr;
    return ptr;
}

void pool_free(MemoryPool *mp, void *ptr) {
    for (size_t i = 0; i < mp->num_items; ++i) {
        if (mp->pool[i] == ptr) {
            free(ptr);
            memmove(&mp->pool[i], &mp->pool[i + 1], sizeof(void*) * (mp->num_items - i - 1));
            --mp->num_items;
            break;
        }
    }
}

