```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    time_t last_clear_time;
    int max_size;
    double growth_factor;
    pthread_t cleaner_thread;
} DynamicArrayManager;

// Function prototypes
void initialize_manager(DynamicArrayManager* manager, size_t initial_capacity);
void destroy_manager(DynamicArrayManager* manager);
int add_pdu(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu);
void* periodic_clear(void* arg);

// Helper functions
static void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

static void resize_array(DynamicArrayManager* manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdus == NULL) {
        log_message("Memory allocation failed during resize.");
        return;
    }
    manager->capacity = new_capacity;
    manager->pdus = new_pdus;
}

void initialize_manager(DynamicArrayManager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->max_size = initial_capacity * 2; // Initial max size
    manager->growth_factor = 1.5;
    manager->last_clear_time = time(NULL);

    if (pthread_create(&manager->cleaner_thread, NULL, periodic_clear, manager) != 0) {
        log_message("Failed to create cleaner thread.");
    }

    manager->pdus = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->pdus == NULL) {
        log_message("Initial memory allocation failed.");
        pthread_mutex_destroy(&manager->lock);
    }
}

void destroy_manager(DynamicArrayManager* manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->pdus);
    pthread_mutex_unlock(&manager->lock);

    pthread_cancel(manager->cleaner_thread);
    pthread_join(manager->cleaner_thread, NULL);
    pthread_mutex_destroy(&manager->lock);
}

int add_pdu(DynamicArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_lock(&manager->lock) != 0) {
        log_message("Mutex lock failed.");
        return -1;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * manager->growth_factor;
        if (new_capacity > manager->max_size) {
            log_message("Maximum array size reached. Cannot add more PDUs.");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        resize_array(manager, new_capacity);
    }

    if (manager->pdus == NULL) {
        pthread_mutex_unlock(&manager->lock);
        log_message("Failed to allocate memory for PDU.");
        return -1;
    }

    manager->pdus[manager->count++] = pdu;
    log_message("PDU added successfully.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void* periodic_clear(void* arg) {
    DynamicArrayManager* manager = (DynamicArrayManager*)arg;
    while (1) {
        sleep(60); // Clear every minute
        pthread_mutex_lock(&manager->lock);

        time_t now = time(NULL);
        if (difftime(now, manager->last_clear_time) > 300) { // 5 minutes timeout
            free(manager->pdus);
            manager->count = 0;
            log_message("Periodic clear executed.");
            manager->last_clear_time = now;

            size_t new_capacity = manager->capacity / 2;
            if (new_capacity < manager->capacity / 4) {
                new_capacity = manager->capacity / 4; // Minimum shrink
            }
            resize_array(manager, new_capacity);
        }

        pthread_mutex_unlock(&manager->lock);
    }
}

int main() {
    DynamicArrayManager manager;
    initialize_manager(&manager, 10);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, {.CRCFLAG = rand() % 256}};
    add_pdu(&manager, pdu);

    destroy_manager(&manager);
    return 0;
}
```

