// Function to initialize the NFAPI_CRC_INDICATION_PDU_T array
int init_pdu_array(size_t count) {
    pthread_mutex_lock(&lock);

    pduArray = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        printf("Failed to allocate memory for PDU array.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    pduCount = count;
    for (size_t i = 0; i < count; ++i) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand();
        pduArray[i].RNTI = rand();
        pduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to add an event
int add_event(const char* base_name, time_t start_range, time_t end_range, int priority) {
    if (eventCount >= MAX_EVENTS) {
        printf("Event array is full.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);

    Event *newEvents = (Event*)memory_pool_alloc((eventCount + 1) * sizeof(Event));
    if (!newEvents) {
        printf("Failed to allocate memory for new event.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    memcpy(newEvents, eventArray, eventCount * sizeof(Event));

    char nameBuffer[256];
    snprintf(nameBuffer, sizeof(nameBuffer), "%s_%zu", base_name, eventCount);
    newEvents[eventCount].name = strdup(nameBuffer);
    if (!newEvents[eventCount].name) {
        memory_pool_free(newEvents);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    time_t start_time = (rand() % (end_range - start_range)) + start_range;
    newEvents[eventCount].start_time = start_time;
    newEvents[eventCount].end_time = start_time + rand() % (end_range - start_time);

    newEvents[eventCount].priority = priority;

    memory_pool_free(eventArray);
    eventArray = newEvents;
    ++eventCount;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to modify an event
int modify_event(size_t index, time_t new_start, time_t new_end) {
    if (index >= eventCount) {
        printf("Invalid event index.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);

    if (new_start > new_end) {
        printf("Start time must be before end time.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (size_t i = 0; i < eventCount; ++i) {
        if (i != index && 
            ((eventArray[i].start_time < new_end && eventArray[i].end_time > new_start))) {
            printf("Event time conflict detected.\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    eventArray[index].start_time = new_start;
    eventArray[index].end_time = new_end;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to cleanup resources
void cleanup() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < eventCount; ++i) {
        free(eventArray[i].name);
    }

    memory_pool_free(eventArray);
    memory_pool_free(pduArray);

    eventArray = NULL;
    pduArray = NULL;
    pduCount = 0;
    eventCount = 0;

    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    srand(time(NULL));

    if (init_pdu_array(10) == -1)
        return EXIT_FAILURE;

    add_event("EventBase", time(NULL), time(NULL) + 10000, 5);

    cleanup();

    return EXIT_SUCCESS;
}
