unsigned int generateUniqueRNTI(unsigned int existing_rntis[], size_t count, unsigned int max_rnti) {
    bool found = false;
    unsigned int new_rnti = rand() % (max_rnti + 1);

    while (!found) {
        found = true;
        for (size_t i = 0; i < count; ++i) {
            if (existing_rntis[i] == new_rnti) {
                found = false;
                break;
            }
        }
        if (!found) {
            new_rnti = rand() % (max_rnti + 1);
        }
    }

    return new_rnti;
}

