class MemoryPool {
    constructor(size) {
        this.pool = new Array(size).fill().map(() => ({ used: false }));
    }

    allocate() {
        const availableIndex = this.pool.findIndex(block => !block.used);
        if (availableIndex === -1) throw new Error("Memory pool exhausted");
        this.pool[availableIndex].used = true;
        return availableIndex;
    }

