#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Definitions of types
typedef struct {
    int valid;  // Indicates validity
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned int rnti;
} RNTI;

typedef struct {
    unsigned char crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global data and mutex
#define MAX_ELEMENTS 10000

NFAPI_CRC_INDICATION_PDU_T* pduArray[MAX_ELEMENTS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int count = 0;  // Current number of elements

void initializeRandom() {
    srand(time(NULL));
}

unsigned char generateCRCFlag() {
    return rand() % 2;  // Randomly returns 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T* createPduElement(int index) {
    if (index < 0 || index >= MAX_ELEMENTS) {
        fprintf(stderr, "Index out of bounds.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        perror("Failed to allocate memory for PDU element");
        return NULL;
    }

    element->ueInfoTag.valid = 1; // Assume valid
    element->rnti.rnti = rand() % UINT_MAX; // Random RNTI
    element->crcIndicationTag.crcFlag = generateCRCFlag(); // Random CRC flag

    pthread_mutex_lock(&lock);
    if (count < MAX_ELEMENTS) {
        pduArray[count++] = element;
        printf("Created PDU Element at index %d\n", count - 1);
    } else {
        free(element);
        fprintf(stderr, "Max elements reached.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    pthread_mutex_unlock(&lock);

    return element;
}

void deletePduElement(int index) {
    if (index < 0 || index >= count) {
        fprintf(stderr, "Index out of bounds for deletion.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    free(pduArray[index]);
    for (int i = index; i < count - 1; ++i) {
        pduArray[i] = pduArray[i + 1];
    }
    pduArray[count - 1] = NULL;
    --count;
    printf("Deleted PDU Element at index %d\n", index);
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* getPduElement(int index) {
    if (index < 0 || index >= count) {
        fprintf(stderr, "Index out of bounds for retrieval.\n");
        return NULL;
    }

    // No need to lock read-only access
    return pduArray[index];
}

int main() {
    initializeRandom();

    // Example usage
    int numElementsToCreate = 100;

    for (int i = 0; i < numElementsToCreate; ++i) {
        createPduElement(i);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = getPduElement(5);
    if (pdu) {
        printf("Retrieved PDU Element with CRCFLAG: %d\n", pdu->crcIndicationTag.crcFlag);
    }

    deletePduElement(5);

    return 0;
}
```

