#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int ue_id;
    double signal_strength;
    time_t *packet_timestamps;
    size_t num_packets;
} UEStatsRecord;

#define INITIAL_CAPACITY 10

typedef struct {
    UEStatsRecord *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} UEStatsArray;

UEStatsArray* init_UEStatsArray() {
    UEStatsArray *array = (UEStatsArray *)malloc(sizeof(UEStatsArray));
    array->records = (UEStatsRecord *)calloc(INITIAL_CAPACITY, sizeof(UEStatsRecord));
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_UEStatsArray(UEStatsArray *array) {
    size_t new_capacity = array->capacity * 2;
    UEStatsRecord *new_records = (UEStatsRecord *)realloc(array->records, new_capacity * sizeof(UEStatsRecord));
    if (new_records) {
        array->records = new_records;
        array->capacity = new_capacity;
    }
}

void add_or_update_UEStatsRecord(UEStatsArray *array, int ue_id, double signal_strength, time_t packet_timestamp) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i].ue_id == ue_id) {
            array->records[i].signal_strength = signal_strength;
            if (array->records[i].num_packets >= sizeof(time_t) * 100) { // Arbitrary max number of packets
                memmove(&array->records[i].packet_timestamps[0], &array->records[i].packet_timestamps[1],
                        sizeof(time_t) * (--array->records[i].num_packets));
            }
            array->records[i].packet_timestamps[array->records[i].num_packets++] = packet_timestamp;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    if (array->count == array->capacity) {
        resize_UEStatsArray(array);
    }

    UEStatsRecord *new_record = &array->records[array->count++];
    new_record->ue_id = ue_id;
    new_record->signal_strength = signal_strength;
    new_record->num_packets = 1;
    new_record->packet_timestamps = malloc(sizeof(time_t));
    new_record->packet_timestamps[0] = packet_timestamp;

    pthread_mutex_unlock(&array->lock);
}

void prune_inactive_UEStatsRecords(UEStatsArray *array, time_t current_time, double timeout_seconds) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count;) {
        if (current_time - array->records[i].packet_timestamps[array->records[i].num_packets - 1] > timeout_seconds) {
            free(array->records[i].packet_timestamps);
            memmove(&array->records[i], &array->records[i + 1],
                    sizeof(UEStatsRecord) * (array->count - i - 1));
            array->count--;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void log_statistics(UEStatsArray *array) {
    pthread_mutex_lock(&array->lock);

    printf("Logging UE Statistics:\n");
    for (size_t i = 0; i < array->count; ++i) {
        printf("UE ID: %d, Signal Strength: %.2f, Packet Count: %zu\n",
               array->records[i].ue_id,
               array->records[i].signal_strength,
               array->records[i].num_packets);
    }

    pthread_mutex_unlock(&array->lock);
}

void destroy_UEStatsArray(UEStatsArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->records[i].packet_timestamps);
    }
    free(array->records);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void periodic_pruning_and_logging(UEStatsArray *array, double prune_interval_seconds, double log_interval_seconds) {
    while (1) {
        time_t current_time = time(NULL);

        // Prune inactive records
        prune_inactive_UEStatsRecords(array, current_time, 60); // Example: 60 seconds timeout

        // Log statistics periodically
        static time_t last_log_time = 0;
        if (difftime(current_time, last_log_time) >= log_interval_seconds) {
            log_statistics(array);
            last_log_time = current_time;
        }

        sleep(prune_interval_seconds); // Wait before next iteration
    }
}

