```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 10000
#define BASE_ERROR_RATE 0.05

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate error based on dynamic error rate
int simulate_error(double current_error_rate) {
    return (rand() / (double)RAND_MAX) < current_error_rate;
}

// Function to get system load and adjust error rate accordingly
double calculate_error_rate(double base_memory_usage, double max_memory_usage) {
    double memory_drop = 1.0 - (base_memory_usage / max_memory_usage);
    if (memory_drop > 0.1) {
        double additional_error = fmin(memory_drop * 10, 0.1); // Increase error rate
        return fmin(BASE_ERROR_RATE + additional_error, 0.10);
    }
    return BASE_ERROR_RATE;
}

// Function to initialize a node with simulated errors
Node* create_node(int rx_ue_info_tag, int rnti, double current_error_rate) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = simulate_error(current_error_rate) ? 1 : 0;

    new_node->next = NULL;
    return new_node;
}

// Function to insert a node at the head of the list
void insert_head(int rx_ue_info_tag, int rnti, double current_error_rate) {
    Node* new_node = create_node(rx_ue_info_tag, rnti, current_error_rate);
    if (!new_node) return;

    pthread_mutex_lock(&list_mutex);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove the head of the list
void delete_head() {
    pthread_mutex_lock(&list_mutex);
    if (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_unlock(&list_mutex);
}

// Main function for testing
int main() {
    srand(time(NULL));

    double base_memory_usage = 0.7; // Assume initial memory usage is at 70%
    double max_memory_usage = 1.0; // Maximum available system resources

    // Simulate dynamic error rate based on current memory usage
    double current_error_rate = calculate_error_rate(base_memory_usage, max_memory_usage);

    for (int i = 0; i < MAX_NODES; ++i) {
        insert_head(i, rand() % 100, current_error_rate);
    }

    // Simulate deletions
    for (int i = 0; i < MAX_NODES / 2; ++i) {
        delete_head();
    }

    return 0;
}
```

