    int crcflag; // CRC_INDICATION_REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t node_count;
} LinkedList;

// Function prototypes
LinkedList* create_list();
void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
void delete_node(LinkedList* list, int rnti);
void validate_list_integrity(LinkedList* list);
NFAPI_CRC_INDICATION_PDU_T generate_pdu_with_random_game_action();
void simulate_game_action(NFAPI_CRC_INDICATION_PDU_T* pdu);

// Error rate simulation
int simulate_error_rate() {
    return (rand() % 100) < 5;
}

// Initialize list
LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->node_count = 0;
    return list;
}

// Insert node into list with error simulation
void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = pdu;
    if (simulate_error_rate()) {
        new_node->data.crcflag = 1; // Simulated error
    }
    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
}

// Delete node from list by RNTI
void delete_node(LinkedList* list, int rnti) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Not found
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    list->node_count--;

    pthread_mutex_unlock(&list->lock);
}

// Validate list integrity
void validate_list_integrity(LinkedList* list) {
    if (!list || !list->head) return;

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == 0 || current->next == NULL) { // Basic validation check
            fprintf(stderr, "Integrity issue found!\n");
        }
        current = current->next;
    }
}

// Generate PDU with random game action
