#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_TAG_VALUE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

// Helper function to initialize the random number generator
void init_random() {
    srand((unsigned int)time(NULL));
}

// Function to create a new dynamic list
DynamicList* create_dynamic_list() {
    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->data = calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;

    return list;
}

// Function to resize the dynamic list
bool resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);

    list->data = new_data;
    return true;
}

// Function to add a new element
bool add_element(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        if (!resize_dynamic_list(list, list->capacity * 2)) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[list->size];
    element->RX_UE_INFORMATION_TAG = rand() % MAX_TAG_VALUE + 1;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = rand() % MAX_TAG_VALUE + 1;
    element->CRCFLAG = (rand() % 2 == 0);

    list->size++;
    pthread_mutex_unlock(&list->lock);

    return true;
}

// Function to remove an element by index
bool remove_element(DynamicList *list, size_t index) {
    if (index >= list->size) return false;

    pthread_mutex_lock(&list->lock);

    memmove(&list->data[index], &list->data[index + 1], 
            (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    list->size--;
    if (list->size < list->capacity / 4 && list->capacity > INITIAL_CAPACITY) {
        resize_dynamic_list(list, list->capacity / 2);
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to update CRCFLAG based on a condition
void update_crc_flags(DynamicList *list, int threshold) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI > threshold) {
            list->data[i].CRCFLAG = true;
        } else {
            list->data[i].CRCFLAG = false;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the list into a binary file
bool serialize_dynamic_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return false;

    pthread_mutex_lock(&list->lock);

    fwrite(&list->size, sizeof(size_t), 1, file);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return true;
}

// Function to deserialize the list from a binary file
bool deserialize_dynamic_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return false;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    resize_dynamic_list(list, new_size);

    pthread_mutex_lock(&list->lock);

    fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    list->size = new_size;

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return true;
}

// Function to validate the integrity of the dynamic list
bool validate_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG <= 0 || 
            list->data[i].RNTI <= 0 || 
            list->data[i].CRC_INDICATION_REL8_TAG <= 0) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to free the dynamic list
void destroy_dynamic_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    free(list);
}

int main() {
    init_random();

    DynamicList *nfa_list = create_dynamic_list();
    if (!nfa_list) return EXIT_FAILURE;

    // Example usage
    add_element(nfa_list, 1001);
    add_element(nfa_list, 1002);

    update_crc_flags(nfa_list, 1000);

    serialize_dynamic_list(nfa_list, "data.bin");
    deserialize_dynamic_list(nfa_list, "data.bin");

    if (validate_dynamic_list(nfa_list)) {
        printf("Dynamic list is valid.\n");
    } else {
        printf("Dynamic list is invalid!\n");
    }

    destroy_dynamic_list(nfa_list);

    return EXIT_SUCCESS;
}
