    time_t last_access_time;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    size_t count;
    pthread_mutex_t lock;
    size_t max_size;
} LRUCache;

LRUCache cache = {0};

void load_max_cache_size() {
    // Read the configuration file to set cache.max_size
    FILE *file = fopen("config.txt", "r");
    if (file) {
        fscanf(file, "%zu", &cache.max_size);
        fclose(file);
    }
}

int is_rnti_valid(unsigned short rnti) {
    return rnti > 0 && rnti <= MAX_RNTI;
}

int populate_structure(NFAPI_CRC_INDICATION_PDU_T* structure, unsigned int metrics) {
    if (!structure) return -1;

    // Populate with dummy data for demonstration purposes
    structure->RX_UE_INFORMATION_TAG = rand() % 1000; 
    structure->RNTI = rand() % (MAX_RNTI + 1);
    structure->CRC_INDICATION_REL8_TAG = rand() % 256;
    structure->CRCFLAG = rand() & 1;

    // Enrich with real-time metrics
    // Example: structure->signal_strength = metrics >> 16;
    return 0;
}

CacheNode* allocate_cache_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) return NULL;

    memcpy(&node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->last_access_time = time(NULL);
    node->next = node->prev = NULL;
    return node;
}

void evict_lru() {
    if (cache.head && cache.tail) {
        CacheNode* lru_node = cache.tail;

        if (lru_node == cache.head) {
            cache.head = cache.tail = NULL;
        } else {
            cache.tail = lru_node->prev;
            cache.tail->next = NULL;
        }

        free(lru_node);
        cache.count--;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_from_cache(unsigned short rnti) {
    pthread_mutex_lock(&cache.lock);

    CacheNode* current = cache.head;
    while (current) {
        if (current->data.RNTI == rnti) {
            // Move the accessed node to head (most recently used)
            if (current != cache.head) {
                if (current->prev) current->prev->next = current->next;
                if (current->next) current->next->prev = current->prev;
                if (cache.tail == current) cache.tail = current->prev;

                current->next = cache.head;
                current->prev = NULL;
                if (cache.head) cache.head->prev = current;
                cache.head = current;
            }
            pthread_mutex_unlock(&cache.lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&load_max_cache_size();
    pthread_mutex_init(&cache.lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) return -1;

    unsigned short used_rntis[MAX_RNTI + 1] = {0};
    size_t allocated_count = 0;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* structure = &structures[i];

        if (populate_structure(structure, rand()) != 0 || !is_rnti_valid(structure->RNTI)) {
            free(structures);
            return -1;
        }

        unsigned short rnti = structure->RNTI;
        if (used_rntis[rnti]) {
            i--; // Retry with a new random RNTI
            continue;
        }

        used_rntis[rnti] = 1;

        CacheNode* cache_node = allocate_cache_node(structure);
        if (!cache_node) {
            free(structures);
            return -1;
        }

        pthread_mutex_lock(&cache.lock);

        if (cache.count >= cache.max_size) {
            evict_lru();
        }

        cache_node->next = cache.head;
        cache_node->prev = NULL;

        if (cache.head) {
            cache.head->prev = cache_node;
        } else {
            cache.tail = cache_node;
        }

        cache.head = cache_node;
        cache.count++;

        pthread_mutex_unlock(&cache.lock);

        allocated_count++;
    }

    printf("Successfully allocated and populated %zu structures.\n", allocated_count);

    return 0; // Success
}

void* thread_function(void* arg) {
    int result = dynamic_manage_array(10); // Example size
    if (result != 0) {
