import pthread

#define INITIAL_BUFFER_SIZE 1024
#define MAX_PACKET_SIZE 1500

typedef struct {
    int flowId;
    char sourceAddress[16];
    char destinationAddress[16];
    size_t bufferSize;
    FlowStats *stats;
} TrafficFlowConfig;

typedef struct {
    unsigned long packetsSent;
    unsigned long packetsReceived;
} FlowStats;

TrafficFlowConfig* initialize_traffic_flows(int numFlows, int *error) {
    if (numFlows <= 0) {
        *error = -1; // Invalid number of flows
        return NULL;
    }

    TrafficFlowConfig **flows = (TrafficFlowConfig **)malloc(numFlows * sizeof(TrafficFlowConfig *));
    if (!flows) {
        *error = -2; // Memory allocation failed
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < numFlows; ++i) {
        TrafficFlowConfig *flow = (TrafficFlowConfig *)malloc(sizeof(TrafficFlowConfig));
        if (!flow) {
            *error = -2; // Memory allocation failed
            free_traffic_flows(flows, i);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        flow->flowId = i + 1;
        snprintf(flow->sourceAddress, sizeof(flow->sourceAddress), "192.168.0.%d", i + 1);
        snprintf(flow->destinationAddress, sizeof(flow->destinationAddress), "10.0.0.%d", i + 1);

        // Initialize buffer size based on average packet size observed (simulated here)
        flow->bufferSize = INITIAL_BUFFER_SIZE;

        FlowStats *stats = (FlowStats *)malloc(sizeof(FlowStats));
        if (!stats) {
            *error = -2; // Memory allocation failed
            free_traffic_flows(flows, i);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
        stats->packetsSent = 0;
        stats->packetsReceived = 0;

        flow->stats = stats;
        flows[i] = flow;
    }

    pthread_mutex_unlock(&lock);
    *error = 0; // Success
    return flows;
}

void free_traffic_flows(TrafficFlowConfig **flows, int numFlows) {
    for (int i = 0; i < numFlows; ++i) {
        if (flows[i]) {
            free(flows[i]->stats);
            free(flows[i]);
        }
    }
    free(flows);
}

void adjust_buffer_size(TrafficFlowConfig *flow, size_t observedPacketSize) {
    pthread_mutex_lock(&lock);

    // Adjust buffer size based on observed packet sizes
    if (observedPacketSize > flow->bufferSize && observedPacketSize <= MAX_PACKET_SIZE) {
        flow->bufferSize = observedPacketSize;
    }

    pthread_mutex_unlock(&lock);
}

void update_flow_stats(TrafficFlowConfig *flow, int packetsSent, int packetsReceived) {
    pthread_mutex_lock(&lock);

    flow->stats->packetsSent += packetsSent;
    flow->stats->packetsReceived += packetsReceived;

    pthread_mutex_unlock(&lock);
}
