int remove_pdu(List* list, int RNTI);
void update_crcflags(List* list, void (*condition)(NFAPI_CRC_INDICATION_PDU_T*));
int serialize_list(const List* list, const char* filename);
int deserialize_list(List* list, const char* filename);
void log_error(const char* message);

// Create a new empty list
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        log_error("Memory allocation failed for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Destroy the list and free memory
void destroy_list(List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the list
int add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for node");
        return -1;
    }

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Remove a PDU from the list by RNTI
int remove_pdu(List* list, int RNTI) {
    if (!list) return -1;

    Node *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->lock);
    while (current && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Update CRC flags based on a condition
void update_crcflags(List* list, void (*condition)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !condition) return;

    Node* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current) {
        condition(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Serialize the list to a file
int serialize_list(const List* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        if (fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            log_error("Failed to write data to file");
            fclose(file);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

// Deserialize the list from a file
int deserialize_list(List* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for reading");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        add_pdu(list, pdu); // This handles node creation and linking
    }

    if (!feof(file)) {
        log_error("Failed to read data from file");
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        return -1;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

// Log an error message
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Example condition function for CRCFLAG update
void example_condition(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Randomly set CRCFLAG (for demonstration purposes)
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2;
}
```

