#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_INACTIVE_TIME 300 // 5 minutes in seconds

typedef struct {
    int connection_id;
    time_t last_activity;
    int active_status; // 1 if active, 0 otherwise
} ConnectionState;

typedef struct {
    ConnectionState *connections;
    size_t capacity;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} ConnectionArray;

void log_message(const char *message) {
    printf("%s: %s\n", time(NULL), message);
}

ConnectionArray* init_connection_array(size_t initial_capacity, size_t max_size) {
    ConnectionArray *array = (ConnectionArray *)malloc(sizeof(ConnectionArray));
    if (!array) return NULL;

    array->connections = (ConnectionState *)calloc(initial_capacity, sizeof(ConnectionState));
    if (!array->connections) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initial_capacity;
    array->size = 0;
    array->max_size = max_size;

    log_message("Initialized connection array");
    return array;
}

int find_connection_index(ConnectionArray *array, int connection_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->connections[i].connection_id == connection_id) {
            return i;
        }
    }
    return -1;
}

void ensure_capacity(ConnectionArray *array) {
    if (array->size >= array->capacity && array->capacity < array->max_size) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > array->max_size) new_capacity = array->max_size;

        ConnectionState *new_connections = realloc(array->connections, new_capacity * sizeof(ConnectionState));
        if (!new_connections) return; // Handle allocation failure

        array->connections = new_connections;
        array->capacity = new_capacity;
    }
}

int add_connection(ConnectionArray *array, int connection_id) {
    pthread_mutex_lock(&array->lock);

    int index = find_connection_index(array, connection_id);
    if (index != -1 || array->size >= array->max_size) {
        pthread_mutex_unlock(&array->lock);
        return 0; // Connection ID already exists or max size reached
    }

    ensure_capacity(array);
    ConnectionState new_conn = {connection_id, time(NULL), 1};
    array->connections[array->size++] = new_conn;

    log_message("Added new connection");
    pthread_mutex_unlock(&array->lock);
    return 1;
}

void update_connection_activity(ConnectionArray *array, int connection_id) {
    pthread_mutex_lock(&array->lock);

    int index = find_connection_index(array, connection_id);
    if (index != -1) {
        array->connections[index].last_activity = time(NULL);
        log_message("Updated connection activity");
    }

    pthread_mutex_unlock(&array->lock);
}

void close_inactive_connections(ConnectionArray *array) {
    pthread_mutex_lock(&array->lock);

    time_t current_time = time(NULL);
    size_t j = 0;

    for (size_t i = 0; i < array->size; ++i) {
        if (current_time - array->connections[i].last_activity > MAX_INACTIVE_TIME) {
            log_message("Closing inactive connection");
        } else {
            if (j != i) {
                array->connections[j] = array->connections[i];
            }
            j++;
        }
    }

    array->size = j;
    pthread_mutex_unlock(&array->lock);
}

void free_connection_array(ConnectionArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->connections);
    free(array);
}

