#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    unsigned long key; // Using RNTI as the key
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache crcCache = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_cache() {
    pthread_mutex_init(&crcCache.lock, NULL);
}

int hash_function(unsigned long key) {
    return key % MAX_ENTRIES; // Simple mod-based hashing
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data, unsigned long key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->key = key;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void move_to_front(LRUCache* cache, Node* node) {
    if (node == cache->head) return;

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (node == cache->tail) cache->tail = node->prev;

    node->next = cache->head;
    node->prev = NULL;
    if (cache->head) cache->head->prev = node;
    cache->head = node;

    if (!cache->tail) cache->tail = node;
}

Node* get_node_by_key(LRUCache* cache, unsigned long key) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current) {
        if (current->key == key) {
            move_to_front(cache, current);
            pthread_mutex_unlock(&cache->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void add_node(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&cache->lock);

    if (get_node_by_key(cache, data.RNTI)) {
        fprintf(stderr, "Duplicate RNTI detected: %lu\n", data.RNTI);
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    Node* newNode = create_node(data, data.RNTI);
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    if (cache->size == MAX_ENTRIES) {
        Node* lru = cache->tail;
        if (lru) {
            if (lru->prev) lru->prev->next = NULL;
            cache->tail = lru->prev;
            free(lru);
            cache->size--;
        }
    }

    newNode->next = cache->head;
    newNode->prev = NULL;
    if (cache->head) cache->head->prev = newNode;
    cache->head = newNode;

    if (!cache->tail) cache->tail = newNode;
    cache->size++;

    pthread_mutex_unlock(&cache->lock);
}

void remove_node_by_key(LRUCache* cache, unsigned long key) {
    pthread_mutex_lock(&cache->lock);

    Node* node = get_node_by_key(cache, key);
    if (!node) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (node == cache->head) cache->head = node->next;
    if (node == cache->tail) cache->tail = node->prev;

    free(node);
    cache->size--;

    pthread_mutex_unlock(&cache->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_node_by_key(LRUCache* cache, unsigned long key) {
    pthread_mutex_lock(&cache->lock);

    Node* node = get_node_by_key(cache, key);
    if (!node) {
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    pthread_mutex_unlock(&cache->lock);
    return &node->data;
}

void update_crc_flags(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate periodic updates
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void integrate_external_data_source(LRUCache* cache) {
    while (1) {
        sleep(5); // Periodic update every 5 seconds

        pthread_mutex_lock(&cache->lock);

        Node* current = cache->head;
        while (current) {
            update_crc_flags(&current->data);
            current = current->next;
        }

        pthread_mutex_unlock(&cache->lock);
    }
}

int main() {
    initialize_cache();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 12345, 6789, 0};
    add_node(&crcCache, pdu1);

    NFAPI_CRC_INDICATION_PDU_T* retrievedPdu = retrieve_node_by_key(&crcCache, 12345);
    if (retrievedPdu) {
        printf("Retrieved RNTI: %lu\n", retrievedPdu->RNTI);
    }

    remove_node_by_key(&crcCache, 12345);

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, (void*)integrate_external_data_source, &crcCache);
    pthread_join(update_thread, NULL);

    return 0;
}
