['Below is a C code implementation that addresses the requirements specified in your task. This code provides a framework for managing dynamic arrays of TCP connection states and NFAPI_CRC_INDICATION_PDU_T structures with thread-safe caching, LRU eviction policy, memory management, and integration hooks for external data sources.

```c
#include <stdio.h>
#include <stdlib.h>
import time.h
#include <pthread.h>

// Define the structures
typedef struct {
    int connectionID;
    time_t lastActivity;
    int activeFlag;
} TCPConnectionState;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    int signalStrength; // Placeholder for real-time metrics
    int CQI;            // Placeholder for real-time metrics
    int MCS;            // Placeholder for real-time metrics
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node structure for LRU caching
typedef struct Node {
    void *data;
    struct Node *prev;
    struct Node *next;
} Node;

// Define the cache structure
typedef struct Cache {
    int max_size;
    int current_size;
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
} Cache;

// Function prototypes
void initializeCache(Cache *cache, int max_size);
void freeNode(Node *node);
int isRNTI_Duplicate(NFAPI_CRC_INDICATION_PDU_T *data, Cache *nfaCache);
void cacheInsert(Cache *cache, void *data);
void *cacheEvict(Cache *cache);
void updateLRU(Cache *cache, Node *node);
void closeInactiveTCPConnections(TCPConnectionState **tcpArray, int size);
void enrichNFAPIData(NFAPI_CRC_INDICATION_PDU_T *data);

// Function implementations
void initializeCache(Cache *cache, int max_size) {
    cache->max_size = max_size;
    cache->current_size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

void freeNode(Node *node) {
    if (node) {
        free(node);
    }
}

int isRNTI_Duplicate(NFAPI_CRC_INDICATION_PDU_T *data, Cache *nfaCache) {
    Node *current = nfaCache->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *cachedData = (NFAPI_CRC_INDICATION_PDU_T *)current->data;
        if (cachedData->RNTI == data->RNTI) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicate
}

void cacheInsert(Cache *cache, void *data) {
    pthread_mutex_lock(&cache->lock);
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = cache->head;

    if (cache->head != NULL) {
        cache->head->prev = newNode;
    }
    cache->head = newNode;

    if (cache->tail == NULL) {
        cache->tail = newNode;
    }

    if (cache->current_size < cache->max_size) {
        cache->current_size++;
    } else {
        cacheEvict(cache);
    }

    updateLRU(cache, newNode);
    pthread_mutex_unlock(&cache->lock);
}

void *cacheEvict(Cache *cache) {
    if (cache->tail == NULL) return NULL;

    Node *nodeToFree = cache->tail;
    void *dataToReturn = nodeToFree->data;

    if (cache->tail->prev != NULL) {
        cache->tail = cache->tail->prev;
        cache->tail->next = NULL;
    } else {
        cache->head = NULL;
        cache->tail = NULL;
    }

    freeNode(nodeToFree);
    cache->current_size--;

    return dataToReturn;
}

void updateLRU(Cache *cache, Node *node) {
    if (node == cache->head) return;

    if (node->prev != NULL) node->prev->next = node->next;
    if (node->next != NULL) node->next->prev = node->prev;

    node->next = cache->head;
    node->prev = NULL;

    if (cache->head != NULL) {
        cache->head->prev = node;
    }
    cache->head = node;

    if (cache->tail == NULL) {
        cache->tail = node;
    }
}

void closeInactiveTCPConnections(TCPConnectionState **tcpArray, int size) {
    time_t currentTime = time(NULL);
    for (int i = 0; i < size; ++i) {
        if (!(*tcpArray)[i].activeFlag && (currentTime - (*tcpArray)[i].lastActivity > 300)) { // 5 minutes
            free((*tcpArray)[i].data);  // Free resources associated with the connection state
            *tcpArray = realloc(*tcpArray, (size-1) * sizeof(TCPConnectionState));
            for (int j = i; j < size - 1; ++j) {
                (*tcpArray)[j] = (*tcpArray)[j+1];
            }
            --size;
        }
    }
}

void enrichNFAPIData(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Placeholder for real-time metric enrichment
    data->signalStrength = rand() % 100;   // Simulated value
    data->CQI = rand() % 15;               // Simulated value
    data->MCS = rand() % 28;               // Simulated value
}

// Example usage
int main() {
    int tcpSize = 10;
    TCPConnectionState *tcpConnections = malloc(tcpSize * sizeof(TCPConnectionState));

    Cache nfaCache;
    initializeCache(&nfaCache, 100);

    NFAPI_CRC_INDICATION_PDU_T newNFAData = {12345, 67890, 11111, 1, 0, 0, 0};
    enrichNFAPIData(&newNFAData);

    if (!isRNTI_Duplicate(&newNFAData, &nfaCache)) {
        cacheInsert(&nfaCache, &newNFAData);
    }

    closeInactiveTCPConnections(&tcpConnections, tcpSize);

    // Clean up
    free(tcpConnections);

    return 0;
}
```

### Key Points:
- **Thread-Safety**: The caching mechanism uses a mutex to ensure thread-safe operations.
- **LRU Cache**: Nodes are moved to the front of the list upon access, with eviction from the tail when necessary.
- **Dynamic Scaling and Memory Management**: Handles resizing of TCP connection arrays dynamically and ensures efficient memory usage through realloc/free strategies.
- **Eviction Policy**: Implements an LRU strategy for managing cache space efficiently. 
- **Real-Time Metrics Enrichment**: Placeholder functions are provided to simulate real-time data integration.

This code serves as a foundation, and you can expand it further based on specific project requirements or performance constraints.']

