#include <iostream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <memory>
#include <thread>
#include <condition_variable>

// Mock external authentication service
bool authenticateUser(const std::string& token) {
    // Simulate an external call
    return !token.empty();
}

class SessionManager {
public:
    struct Session {
        std::string sessionId;
        std::string authToken;
        std::string ipAddress;
        std::chrono::steady_clock::time_point lastActivity;

        Session(const std::string& id, const std::string& token, const std::string& ip)
            : sessionId(id), authToken(token), ipAddress(ip),
              lastActivity(std::chrono::steady_clock::now()) {}
    };

    explicit SessionManager(size_t initialCapacity, size_t maxAllowedSize)
        : capacity(initialCapacity), maxSize(maxAllowedSize) {
        sessions.reserve(capacity);
    }

    bool addSession(const std::string& sessionId, const std::string& authToken, const std::string& ipAddress) {
        std::unique_lock lock(mutex_);
        if (sessions.size() >= maxSize || contains(sessionId)) {
            return false;
        }

        if (!authenticateUser(authToken)) {
            return false;
        }

        sessions.emplace_back(sessionId, authToken, ipAddress);
        logOperation("Session added: " + sessionId);
        return true;
    }

    void updateActivity(const std::string& sessionId) {
        std::unique_lock lock(mutex_);
        auto it = findSession(sessionId);
        if (it != sessions.end()) {
            it->lastActivity = std::chrono::steady_clock::now();
            logOperation("Session updated: " + sessionId);
        }
    }

    void removeInactiveSessions() {
        std::unique_lock lock(mutex_);
        auto now = std::chrono::steady_clock::now();
        auto inactiveThreshold = std::chrono::minutes(10);

        for (auto it = sessions.begin(); it != sessions.end();) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - it->lastActivity).count() > inactiveThreshold.count()) {
                logOperation("Session removed: " + it->sessionId);
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    void handleConcurrentAccess() {
        std::vector<std::thread> threads;
        for (size_t i = 0; i < 10; ++i) { // Simulate concurrent access
            threads.emplace_back([this]() {
                addSession("session_" + std::to_string(std::rand()), "token", "127.0.0.1");
                updateActivity("session_1");
                removeInactiveSessions();
            });
        }

        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

private:
    size_t capacity;
    size_t maxSize;
    std::vector<Session> sessions;
    mutable std::shared_mutex mutex_;

    bool contains(const std::string& sessionId) const {
        for (const auto& session : sessions) {
            if (session.sessionId == sessionId) {
                return true;
            }
        }
        return false;
    }

    typename std::vector<Session>::iterator findSession(const std::string& sessionId) {
        for (auto it = sessions.begin(); it != sessions.end(); ++it) {
            if (it->sessionId == sessionId) {
                return it;
            }
        }
        return sessions.end();
    }

    void logOperation(const std::string& message) const {
        // In a real application, integrate with an external logging framework
        std::cout << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())
                  << "] " << message << std::endl;
    }
};

int main() {
    SessionManager manager(100, 1000);
    manager.addSession("session_1", "token", "127.0.0.1");
    manager.updateActivity("session_1");

    // Simulate concurrent access
    manager.handleConcurrentAccess();

    return 0;
}
```

