               RX_UE_INFORMATION_TAG, RNTI, new_node->data.CRC_INDICATION_REL8_TAG.crcflag);
    }

    pthread_mutex_unlock(&list_mutex);
}

void serialize_list_to_binary(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    Node* current = head;

    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list_mutex);
}

void cleanup_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    head = NULL;

    pthread_mutex_unlock(&list_mutex);
}

