int add_nfa_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: capacity exceeded
    }

    uint64_t timestamp = get_monotonic_time();
    if (timestamp < list->last_timestamp) {
        fprintf(stderr, "Warning: Non-monotonic time detected!\n");
        timestamp = list->last_timestamp + 1;
    }

    new_entry.valid_RX_UE_INFORMATION_TAG = 1; // Assume valid
    list->entries[list->count] = new_entry;
    list->last_timestamp = timestamp;

    if (list->count == 0) {
        printf("Debug: First entry added at %llu\n", timestamp);
    } else {
        printf("Debug: Entry added at %llu\n", timestamp);
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

