    list->entries = malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = max_entries;
    pthread_mutex_init(&list->lock, NULL);
    list->last_timestamp = get_monotonic_time();

    return list;
}

void destroy_nfa_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list) {
        free(list->entries);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
