#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Pseudo-random flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t active_count;
    size_t max_active;
    uint8_t preallocated[MAX_NODES];
    int initialized;
} LinkedListManager;

void initialize_manager(LinkedListManager* manager, size_t seed) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->active_count = 0;
    manager->max_active = 0;
    manager->initialized = 1;
    srand(seed);

    // Simulate fetching configuration parameters
    for (size_t i = 0; i < MAX_NODES; ++i) {
        manager->preallocated[i] = (uint8_t)i % 256; // Dummy preallocation
    }
}

Node* get_preallocated_node(LinkedListManager* manager, uint32_t tag, uint16_t rnti, uint8_t rel8tag) {
    for (size_t i = 0; i < MAX_NODES; ++i) {
        if (!manager->preallocated[i]) { // Check availability
            NFAPI_CRC_INDICATION_PDU_T* pdu = &(Node{})->data;
            pdu->RX_UE_INFORMATION_TAG = tag;
            pdu->RNTI = rnti;
            pdu->CRC_INDICATION_REL8_TAG = rel8tag;
            pdu->CRCFLAG = rand() % 2; // Pseudo-random flag
            manager->preallocated[i] = 1; // Mark as used

            Node* node = (Node*)malloc(sizeof(Node));
            if (!node) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            node->data = *pdu;
            node->next = NULL;

            return node;
        }
    }

    fprintf(stderr, "Exceeded maximum preallocated nodes limit.\n");
    return NULL;
}

void add_node(LinkedListManager* manager, uint32_t tag, uint16_t rnti, uint8_t rel8tag) {
    if (!manager->initialized) return;

    pthread_mutex_lock(&manager->lock);
    Node* new_node = get_preallocated_node(manager, tag, rnti, rel8tag);

    if (new_node) {
        new_node->next = manager->head;
        manager->head = new_node;
        ++manager->active_count;

        if (manager->active_count > manager->max_active) {
            manager->max_active = manager->active_count;
            printf("New maximum active structures: %zu\n", manager->max_active);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_manager(LinkedListManager* manager) {
    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);

        // Reset preallocation
        for (size_t i = 0; i < MAX_NODES; ++i) {
            if ((uint8_t*)(temp->data.CRCFLAG + sizeof(temp->data)) == &(manager->preallocated[i])) {
                manager->preallocated[i] = 0;
                break;
            }
        }
    }
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    LinkedListManager manager;
    initialize_manager(&manager, time(NULL));

    for (int i = 0; i < 1050; ++i) { // Testing with more than max limit to trigger logging
        add_node(&manager, i, (uint16_t)i, (uint8_t)(i % 256));
    }

    free_manager(&manager);
    return 0;
}
