```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Additional CRC information fields can be added here.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Initialize the doubly-linked list
int init_list(DoublyLinkedList* list) {
    if (!list) return -1;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

// Add or update an event in the list
int add_event(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!list || !new_data) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == new_data.RNTI) {
            // Update existing node with new CRC information
            current->data = new_data; 
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->data = new_data;
    newNode->prev = NULL;
    newNode->next = list->head;

    if (list->head != NULL) {
        list->head->prev = newNode;
    }

    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Helper function for sorting
void swap(Node* a, Node* b) {
    NFAPI_CRC_INDICATION_PDU_T temp = a->data;
    a->data = b->data;
    b->data = temp;
}

Node* partition(Node* low, Node* high, Node** newHigh) {
    int pivotRNTI = high->data.RNTI;
    Node* i = low->prev;

    for (Node* j = low; j != high; j = j->next) {
        if (j->data.RNTI <= pivotRNTI) {
            i = (i == NULL) ? low : i->next;
            swap(i, j);
        }
    }

    i = (i == NULL) ? low : i->next;
    swap(i, high);

    *newHigh = i;
    return i;
}

void quickSortRecur(Node* low, Node* high) {
    if (!high || !low || low == high || low->next == high)
        return;

    Node* pivot = partition(low, high, &high);
    quickSortRecur(low, pivot->prev);
    quickSortRecur(pivot->next, high);
}

void sort_list(DoublyLinkedList* list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *newHead = NULL, *current = list->head;
    while (current != NULL && current->prev != NULL)
        current = current->prev;

    quickSortRecur(current, list->head->next->prev);
    newHead = list->head;
    while (newHead != NULL && newHead->prev != NULL) {
        newHead = newHead->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

// Print the linked list
void print_list(DoublyLinkedList* list) {
    if (!list || !list->head) return;

    Node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d\n", current->data.RNTI);
        current = current->next;
    }
}

// Free the linked list
void free_list(DoublyLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

```

### Explanation:
- **Initialization and Memory Management**: The `init_list`, `add_event`, and `free_list` functions handle the creation, updating, and cleanup of nodes in a thread-safe manner using mutex locks.

- **Concurrency**: Mutexes are used to ensure that concurrent modifications do not result in race conditions.

- **Sorting**: A quicksort algorithm is implemented for efficient sorting by RNTI. The choice of quicksort over mergesort or other algorithms balances between average-case performance and space complexity, which is critical given the potential size of the dataset.

- **Linear Search vs Hash Table**: For the purpose of ensuring unique `RNTI` values, a linear search was chosen to keep simplicity and minimize overhead in memory usage. Given that the list can potentially hold up to 100,000 elements, a hash table could be considered for larger datasets or higher frequency updates.

- **Modularity**: Functions are designed modularly to allow easy extension (e.g., adding more metadata fields) and maintenance.

This implementation assumes the presence of a POSIX-compliant threading library for mutex locks. Adjustments might be necessary if targeting environments without such support.']

