#include <sys/resource.h>

typedef struct {
    int RNTI;
    struct RX_UE_INFORMATION_TAG {
        int valid; // Assume this is a simple flag for validity
    } rx_ue_info_tag;
    struct CRC_INDICATION_REL8_TAG {
        unsigned char CRCFLAG; // Randomly set CRCFLAG
    } crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
} Record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void measure_and_log_memory_usage(const char *label) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    printf("%s - Resident Set Size: %ld KB\n", label, usage.ru_maxrss);
}

int allocate_records(int num_records, Record ***records_array, int **keys_array) {
    if (num_records <= 0) return -1;

    *records_array = malloc(num_records * sizeof(Record *));
    if (!*records_array) {
        log_error("Memory allocation failed for records array");
        return -1;
    }

    *keys_array = malloc(num_records * sizeof(int));
    if (!*keys_array) {
        free(*records_array);
        log_error("Memory allocation failed for keys array");
        return -1;
    }

    srand(time(NULL)); // Seed random number generator

    int range_min = 100, range_max = 200; // Example range
    int last_value = range_min - 1;

    for (int i = 0; i < num_records; ++i) {
        (*keys_array)[i] = rand() % ((range_max + 1) - range_min) + range_min;

        while ((*keys_array)[i] == last_value) { // Ensure unique consecutive values
            (*keys_array)[i] = rand() % ((range_max + 1) - range_min) + range_min;
        }

        last_value = (*keys_array)[i];

        (*records_array)[i] = malloc(sizeof(Record));
        if (!(*records_array)[i]) {
            log_error("Memory allocation failed for record");
            for (int j = 0; j < i; ++j) {
                free((*records_array)[j]);
            }
            free(*records_array);
            free(*keys_array);
            return -1;
        }

        (*records_array)[i]->value = rand() % ((range_max + 1) - range_min) + range_min;
    }

    return 0;
}

void deallocate_records(int num_records, Record **records_array, int *keys_array) {
    for (int i = 0; i < num_records; ++i) {
        free(records_array[i]);
    }
    free(records_array);
    free(keys_array);
}

void manage_dynamic_memory_allocation(int num_pdu, int record_count) {
