#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRUCTURES 500
#define INITIAL_POOL_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** pool;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    int active_count;
    int peak_usage;
} MemoryPool;

static void initialize_pool(MemoryPool* mp, size_t initial_size) {
    pthread_mutex_init(&mp->lock, NULL);
    pthread_cond_init(&mp->not_full, NULL);
    pthread_cond_init(&mp->not_empty, NULL);

    mp->pool = (Node**)malloc(initial_size * sizeof(Node*));
    for (size_t i = 0; i < initial_size; ++i) {
        mp->pool[i] = (Node*)calloc(1, sizeof(Node));
    }

    mp->current_size = initial_size;
    mp->max_size = MAX_STRUCTURES;
    mp->active_count = 0;
    mp->peak_usage = 0;
}

static void destroy_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->current_size; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);

    pthread_mutex_destroy(&mp->lock);
    pthread_cond_destroy(&mp->not_full);
    pthread_cond_destroy(&mp->not_empty);
}

static void log_event(const char* event_description) {
    printf("%s\n", event_description);
}

static bool resize_pool(MemoryPool* mp, size_t new_size) {
    if (new_size > MAX_STRUCTURES) return false;

    Node** new_pool = realloc(mp->pool, new_size * sizeof(Node*));
    if (!new_pool) return false;

    for (size_t i = mp->current_size; i < new_size; ++i) {
        new_pool[i] = (Node*)calloc(1, sizeof(Node));
    }

    mp->pool = new_pool;
    mp->current_size = new_size;
    log_event("Resized memory pool.");
    return true;
}

static void* get_structure(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    while (mp->active_count >= mp->max_size) {
        if (!resize_pool(mp, mp->current_size * 2)) {
            log_event("Memory pool reached maximum size. Cannot allocate more structures.");
            pthread_cond_wait(&mp->not_full, &mp->lock);
        }
    }

    for (size_t i = 0; i < mp->current_size; ++i) {
        if (!mp->pool[i]->next) {
            Node* node = (Node*)calloc(1, sizeof(Node));
            if (!node) {
                pthread_mutex_unlock(&mp->lock);
                return NULL;
            }
            mp->pool[i]->next = node;
            mp->active_count++;
            if (mp->active_count > mp->peak_usage)
                mp->peak_usage = mp->active_count;

            log_event("Allocated new structure.");
            pthread_cond_signal(&mp->not_empty);
            pthread_mutex_unlock(&mp->lock);

            return &(node->data);
        }
    }

    pthread_mutex_unlock(&mp->lock);
    return NULL;
}

static void release_structure(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&mp->lock);

    for (size_t i = 0; i < mp->current_size; ++i) {
        Node* node = mp->pool[i];
        while (node && node->next) {
            if (&(node->next->data) == data) {
                Node* to_free = node->next;
                node->next = node->next->next;
                free(to_free);
                mp->active_count--;
                log_event("Freed structure.");
                pthread_cond_signal(&mp->not_full);
                break;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&mp->lock);
}

static void reset_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    for (size_t i = 0; i < mp->current_size; ++i) {
        Node* current = mp->pool[i];
        while (current) {
            Node* to_free = current;
            current = current->next;
            free(to_free);
        }
        mp->pool[i] = NULL;
    }

    mp->active_count = 0;
    mp->peak_usage = 0;

    log_event("Memory pool reset.");
    pthread_mutex_unlock(&mp->lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure(MemoryPool* mp, int RX_UE_INFORMATION_TAG,
                                               uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG,
                                               unsigned int seed) {
    if (RX_UE_INFORMATION_TAG <= 0 || RNTI == 0 || CRC_INDICATION_REL8_TAG < 0) {
        log_event("Invalid parameters for structure allocation.");
        return NULL;
    }

    srand(seed);
    bool pseudo_random_flag = rand() % 2;

    NFAPI_CRC_INDICATION_PDU_T* pdu = get_structure(mp);
    if (pdu) {
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        pdu->CRCFLAG = pseudo_random_flag;

        log_event("Structure created with CRCFLAG set to:");
        printf("    %d\n", (int)pseudo_random_flag);
    }

    return pdu;
}

void deallocate_structure(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!data) {
        log_event("Attempted to deallocate NULL structure.");
        return;
    }
    release_structure(mp, data);
}
