#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10];
    uint8_t CRCFLAG;
    time_t timestamp; // Monotonic clock
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global list and mutex for thread safety
static Node* head = NULL;
static size_t current_size = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logger function pointer, can be set to NULL if logging is not needed
void (*logger)(const char*) = NULL;

int add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_mutex);

    // Check for memory and size constraints
    if (current_size >= MAX_STRUCTURES || !pdu) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Error: Max structures reached or invalid input
    }

    Node* current = head;

    while (current != NULL) {
        if (current->data.RNTI == pdu->RNTI) { 
            if (logger) logger("Duplicate RNTI detected. Ignoring entry.");
            pthread_mutex_unlock(&list_mutex);
            return 0; // Duplicate found, do not add
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return -2; // Error: Memory allocation failed
    }

    new_node->data = *pdu;
    new_node->data.timestamp = time(NULL); // Set current timestamp

    new_node->next = head;
    head = new_node;
    current_size++;

    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

void free_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
    current_size = 0;

    pthread_mutex_unlock(&list_mutex);
}

void set_logger(void (*log_func)(const char*)) {
    logger = log_func;
}

// Example logger function
void example_log(const char* message) {
    printf("Log: %s\n", message);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234, {0}, 1};

    set_logger(example_log);

    if (add_crc_indication_pdu(&pdu) == 0) {
        printf("Added successfully.\n");
    } else {
        printf("Failed to add. Error code: %d\n", -1);
    }

    free_list();
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex` ensures that concurrent access is handled safely.
- **Memory Management**: Dynamic allocation and deallocation are carefully managed, with checks for allocation failures.
- **Logging**: Optional logging functionality allows debugging information to be captured when necessary.
- **Error Handling**: Proper error codes and handling mechanisms are in place for various failure scenarios.']

