#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define SUCCESS 0
#define ERROR_MAX_REACHED -1

typedef struct {
    int ue_id;
    char rrc_state[10];
    char security_context[256];
    uint64_t timestamp;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    pthread_mutex_t lock;
} UE_Context_Manager;

uint64_t get_monotonic_timestamp() {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("Failed to get monotonic time");
        return 0;
    }
    return (uint64_t)(ts.tv_sec * 1000000000ULL + ts.tv_nsec);
}

int initialize_manager(UE_Context_Manager *manager) {
    manager->contexts = malloc(MAX_ENTRIES * sizeof(LTE_UE_Context));
    if (!manager->contexts) {
        perror("Failed to allocate memory for contexts");
        return -1;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return SUCCESS;
}

void cleanup_manager(UE_Context_Manager *manager) {
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
}

int add_context(UE_Context_Manager *manager, int ue_id, const char *rrc_state, const char *security_context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return ERROR_MAX_REACHED;
    }

    LTE_UE_Context new_context = {
        .ue_id = ue_id,
        .timestamp = get_monotonic_timestamp()
    };
    strncpy(new_context.rrc_state, rrc_state, sizeof(new_context.rrc_state) - 1);
    strncpy(new_context.security_context, security_context, sizeof(new_context.security_context) - 1);

    manager->contexts[manager->count++] = new_context;

    printf("Context created: UE ID %d at timestamp %llu\n", ue_id, new_context.timestamp);

    pthread_mutex_unlock(&manager->lock);
    return SUCCESS;
}

int update_security_context(UE_Context_Manager *manager, int ue_id, const char *new_security_context) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            strncpy(manager->contexts[i].security_context, new_security_context,
                    sizeof(manager->contexts[i].security_context) - 1);
            printf("Security context updated for UE ID %d\n", ue_id);
            pthread_mutex_unlock(&manager->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return ERROR_MAX_REACHED; // Context not found
}

