typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
} LinkedList;

LinkedList list = {NULL, PTHREAD_RWLOCK_INITIALIZER};

void log_debug(const char* message) {
    printf("[DEBUG] %s\n", message);
}

int initialize_list() {
    if (pthread_rwlock_init(&list.lock, NULL) != 0) {
        perror("Failed to initialize lock");
        return -1;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Memory allocation failed");
        return NULL;
    }
    pdu->valid_RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    return pdu;
}

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        free(pdu);
        return;
    }
    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list.lock);
    new_node->next = list.head;
    list.head = new_node;
    pthread_rwlock_unlock(&list.lock);

    log_debug("PDU added to list");
}

void free_list() {
    Node* current = list.head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_rwlock_destroy(&list.lock);
}

int read_integers(int** array, size_t* count) {
    int capacity = 10;
    *array = (int*)malloc(capacity * sizeof(int));
    if (!*array) {
        perror("Memory allocation failed");
        return -1;
    }

    int input;
    size_t index = 0;

    while (scanf("%d", &input) == 1) {
        if (index >= capacity) {
            capacity *= 2;
            *array = (int*)realloc(*array, capacity * sizeof(int));
            if (!*array) {
                perror("Memory reallocation failed");
                return -1;
            }
        }
        (*array)[index++] = input;
    }

    *count = index;
    return 0;
}

void find_largest_integer() {
    int* array;
    size_t count;

    if (read_integers(&array, &count) != 0) {
        fprintf(stderr, "Failed to read integers\n");
        return;
    }

    if (count == 0) {
        printf("No integers provided.\n");
        free(array);
        return;
    }

    int largest = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);

    free(array);
}

int main() {
    if (initialize_list() != 0) {
        return EXIT_FAILURE;
    }

    // Example usage of adding a PDU
    for (uint32_t i = 1; i <= 10000; ++i) { // Simulate 10,000 PDUs
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(i, rand() % 65535);
        if (pdu) {
            add_pdu_to_list(pdu);
        }
    }

    find_largest_integer();

    free_list();
    return EXIT_SUCCESS;
}
