    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->systemOverloaded = 0; // Assume not overloaded initially
    list->bufferHead = NULL;
    list->bufferTail = NULL;
