    newNode->data.crcIndication.ueInfoTag.rnti = rnti;
    newNode->data.crcIndication.ueInfoTag.crcFlag = rnti ^ list->size;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);

    if (!isQueueOverloaded()) {
        enqueueEvent(newNode, 0);
    } else {
        pthread_mutex_lock(&list->lock);
        if (list->bufferTail == NULL) {
            list->bufferHead = newNode;
        } else {
            list->bufferTail->next = newNode;
        }
        list->bufferTail = newNode;
        pthread_mutex_unlock(&list->lock);
    }

