int add_pdu_to_list(DynamicList* list, uint32_t RX_UE_INFORMATION_TAG, 
                    uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG);
void free_dynamic_list(DynamicList* list);

// Create a new dynamic list with initialized mutex
DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        // Log error: Memory allocation failed for the list structure.
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new PDU to the dynamic list
int add_pdu_to_list(DynamicList* list, uint32_t RX_UE_INFORMATION_TAG, 
                    uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    if (list->size >= MAX_ELEMENTS) {
        // Log warning: Maximum list size reached.
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        // Log error: Memory allocation failed for the new node.
        return -2;
    }

    uint8_t CRCFLAG = RNTI ^ list->size;  // Determine CRCFLAG

    // Constructing PDU structure
