        .RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG,
        .RNTI = RNTI,
        .CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG
    };
    new_node->data = pdu;
    new_node->next = list->head;

    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    // Log info: Successfully added PDU to the list.
    return 0; 
}

// Free all nodes in the dynamic list
void free_dynamic_list(DynamicList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    // Log info: Dynamic list has been successfully freed.
}

// Main function for demonstration purposes
