['```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <thread>
#include <algorithm>
#include <stdexcept>

// Define structures (for illustration purposes)
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

class NfarxPduGenerator {
public:
    NfarxPduGenerator(std::vector<NFAPI_CRC_INDICATION_PDU_T>& pduVector)
        : pdu_vector_(pduVector), min_crc_flag_(0), max_crc_flag_(1) {}

    void setCrcFlagRange(int min, int max) {
        if (min >= max) {
            throw std::invalid_argument("Invalid CRCFLAG range");
        }
        min_crc_flag_ = min;
        max_crc_flag_ = max;
    }

    void generatePdus(size_t count) {
        if (count == 0) return;

        // Use threads to parallelize the generation process
        size_t num_threads = std::thread::hardware_concurrency();
        size_t chunk_size = count / num_threads;

        std::vector<std::thread> threads;
        for (size_t i = 0; i < num_threads; ++i) {
            size_t start_index = i * chunk_size;
            size_t end_index = (i == num_threads - 1) ? count : start_index + chunk_size;
            threads.emplace_back([this, start_index, end_index]() {
                for (size_t j = start_index; j < end_index; ++j) {
                    generateSinglePdu(j);
                }
            });
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void releaseResources() {
        pdu_vector_.clear();
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T>& pdu_vector_;
    int min_crc_flag_;
    int max_crc_flag_;

    void generateSinglePdu(size_t index) {
        static std::mutex mtx;
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> rx_ue_dist(1, 1000000);
        std::uniform_int_distribution<> rnti_dist(1, 50000);
        std::uniform_int_distribution<> crc_flag_dist(min_crc_flag_, max_crc_flag_ - 1);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        {
            std::lock_guard<std::mutex> lock(mtx); // Ensure thread-safe access to the vector
            pdu.RX_UE_INFORMATION_TAG = rx_ue_dist(gen);
            pdu.RNTI = rnti_dist(gen);
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (crc_flag_dist(gen) % 2 == 0);
        }

        std::lock_guard<std::mutex> lock(mtx); // Ensure thread-safe access to the vector
        pdu_vector_.push_back(pdu);
    }
};

// Unit tests (example)
void testGeneratePdus() {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduVector;
    NfarxPduGenerator generator(pduVector);

    generator.setCrcFlagRange(0, 2); // CRCFLAG range between 0 and 1
    generator.generatePdus(1000000);

    if (pduVector.size() != 1000000) {
        throw std::runtime_error("Test failed: Incorrect number of PDUs generated.");
    }

    for (const auto& pdu : pduVector) {
        if (!(pdu.RX_UE_INFORMATION_TAG >= 1 && pdu.RX_UE_INFORMATION_TAG <= 1000000)) {
            throw std::runtime_error("Test failed: RX_UE_INFORMATION_TAG out of range.");
        }
        if (!(pdu.RNTI >= 1 && pdu.RNTI <= 50000)) {
            throw std::runtime_error("Test failed: RNTI out of range.");
        }
    }

    std::cout << "All tests passed!" << std::endl;
}

int main() {
    try {
        testGeneratePdus();
    } catch (const std::exception& e) {
