typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO_T;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO_T ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex; // Mutex for thread safety
} ResizableArray;

// Initialize the resizable array
void initResizableArray(ResizableArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->capacity);
    pthread_mutex_init(&array->mutex, NULL);
}

// Resize the array when needed
void resizeArray(ResizableArray *array) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

        if (new_data != NULL) {
            array->data = new_data;
            array->capacity = new_capacity;
        } else {
            perror("Failed to resize the array");
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Add a new element to the array
void addElement(ResizableArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);

    resizeArray(array);

    array->data[array->count] = element;
    array->count++;

    pthread_mutex_unlock(&array->mutex);
}

// Compute checksum for integrity check
uint8_t computeChecksum(UE_INFO_T ue_info, uint16_t rnti) {
    return (ue_info.RX_UE_INFORMATION_TAG + rnti) % 256; // Example checksum computation
}

// Verify the integrity of the array
void verifyIntegrity(ResizableArray *array) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        uint8_t expected_crc_flag = computeChecksum(array->data[i].ue_info, array->data[i].rnti);

        if (expected_crc_flag != array->data[i].crc_tag.CRCFLAG) {
            printf("Integrity check failed at index %zu\n", i);
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

// Periodic integrity verification task
void *integrityVerificationTask(void *arg) {
    ResizableArray *array = (ResizableArray *)arg;

    while (1) {
        verifyIntegrity(array);

        // Sleep for a defined period before the next check, e.g., 5 seconds
        sleep(5);
    }

    return NULL;
}

// Clean up resources
void freeResizableArray(ResizableArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->data);
}

int main() {
    ResizableArray array;
    initResizableArray(&array);

    // Example of starting the integrity verification task in a separate thread
    pthread_t verify_thread;
    pthread_create(&verify_thread, NULL, integrityVerificationTask, &array);

    // Add some elements (in real usage this would be done dynamically)
    for (int i = 0; i < 15; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        element.ue_info.RX_UE_INFORMATION_TAG = rand() % 10000;
        element.rnti = rand() % 65536;
        element.crc_tag.CRCFLAG = computeChecksum(element.ue_info, element.rnti);
        addElement(&array, element);
    }

    // Join the verification thread (in a real application this might run indefinitely)
    pthread_join(verify_thread, NULL);

    freeResizableArray(&array);

    return 0;
}
