#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_LOG_SIZE 1024 * 10 // Example log size limit (e.g., 10 KB)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node of the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Structure for managing the list and its properties
typedef struct {
    Node* head;
    uint32_t rolling_checksum;
    pthread_mutex_t lock;
    size_t log_buffer_size;
    char* error_log;
    size_t current_log_size;
} ThreadSafeList;

ThreadSafeList* create_list() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->rolling_checksum = 0;
    list->log_buffer_size = MAX_LOG_SIZE;
    list->error_log = (char*)calloc(list->log_buffer_size, sizeof(char));
    list->current_log_size = 0;

    return list;
}

void log_error(ThreadSafeList* list, const char* error_message) {
    size_t message_length = strlen(error_message);
    if ((list->current_log_size + message_length) < list->log_buffer_size) {
        pthread_mutex_lock(&list->lock);
        strcat(list->error_log, error_message);
        list->current_log_size += message_length;
        pthread_mutex_unlock(&list->lock);
    } else {
        // Handle log overflow (e.g., truncate or rotate logs)
        printf("Log overflow: %s\n", error_message);
    }
}

bool add_to_list(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == item.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return false; // RNTI already exists
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error(list, "Memory allocation failed for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = item;
    new_node->next = list->head;
    list->head = new_node;

    // Update rolling checksum
    list->rolling_checksum ^= (item.CRC_INDICATION_REL8_TAG.CRCFLAG ? 1 : 0);

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool verify_integrity(ThreadSafeList* list) {
    pthread_mutex_lock(&list->lock);

    uint32_t computed_checksum = 0;
    Node* current = list->head;

    while (current != NULL) {
        // Example checksum calculation
        computed_checksum ^= ((uint32_t)current->data.RX_UE_INFORMATION_TAG ^
                              (uint32_t)current->data.RNTI);
        if (computed_checksum != list->rolling_checksum) {
            log_error(list, "Integrity check failed.\n");
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

void free_list(ThreadSafeList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list->error_log);
    free(list);
}

// Usage Example (should be replaced with proper multithreading code for real-world usage)
int main() {
    ThreadSafeList* list = create_list();
    if (!list) return 1;

    NFAPI_CRC_INDICATION_PDU_T item;
    item.RX_UE_INFORMATION_TAG = 12345; // Example data
    item.RNTI = 6789; // Unique RNTI for each item
    item.CRC_INDICATION_REL8_TAG.CRCFLAG = true; // Randomly set

    if (add_to_list(list, item)) {
        printf("Item added successfully.\n");
    } else {
        printf("Failed to add item: RNTI may already exist.\n");
    }

    if (verify_integrity(list)) {
        printf("Integrity check passed.\n");
    } else {
        printf("Integrity check failed.\n");
    }

    free_list(list);
    return 0;
}
