    pthread_mutex_lock(&list->mutex);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove_element(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Element not found
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool update_crcflag(CRCList* list, int rnti, bool crcflag) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head;

    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current) { // Element not found
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Example usage of the implemented functions (this part can be omitted or adjusted as needed).
int main() {
    CRCList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = { .CRCFLAG = false } };
    add_element(list, pdu1);

    update_crcflag(list, 100, true);

    remove_element(list, 100);

    free_list(list);

    return EXIT_SUCCESS;
}
```

This implementation uses a simple linked list to manage the dynamic data structures. The `pthread_mutex_t` ensures that operations on the list are thread-safe. Each function locks the mutex before performing any modifications or checks and unlocks it afterward. This approach provides basic performance characteristics suitable for many use cases, but further optimization may be necessary depending on specific requirements like very high throughput or low-latency demands in a production environment.']

