#define MAX_STRUCTURES 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    uint32_t running_checksum;
} CRCArray;

// Helper function to generate a random number
int get_random() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Initialize the array structure
int initialize_crc_array(CRCArray *crc_array, size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_STRUCTURES) {
        return -1;
    }

    crc_array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        return -1; // Memory allocation failure
    }

    crc_array->capacity = initial_capacity;
    crc_array->count = 0;
    crc_array->running_checksum = 0;

    if (pthread_mutex_init(&crc_array->mutex, NULL)) {
        free(crc_array->array);
        return -1; // Mutex initialization failure
    }

    srand((unsigned int)time(NULL)); // Seed for random number generation

    return 0;
}

// Add a new structure to the array
int add_crc_pdu(CRCArray *crc_array, uint16_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&crc_array->mutex);

    if (crc_array->count == crc_array->capacity) {
        size_t new_capacity = crc_array->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -1; // Exceeded maximum capacity
        }

        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(crc_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -1; // Memory allocation failure
        }

        crc_array->array = temp;
        crc_array->capacity = new_capacity;
    }

    uint16_t RNTI = (rand() % 65535) + 1;

    for (size_t i = 0; i < crc_array->count; ++i) {
        if (crc_array->array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -2; // Duplicate RNTI
        }
    }

    NFAPI_CRC_INDICATION_PDU_T new_pdu = {RX_UE_INFORMATION_TAG, RNTI, get_random()};
    crc_array->array[crc_array->count] = new_pdu;
    crc_array->running_checksum ^= new_pdu.CRCFLAG; // Update running checksum

    ++crc_array->count;

    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}

// Periodically verify the integrity of the array
int verify_integrity(CRCArray *crc_array) {
    pthread_mutex_lock(&crc_array->mutex);

    uint32_t computed_checksum = 0;
    for (size_t i = 0; i < crc_array->count; ++i) {
        // Simulate checksum computation from RX_UE_INFORMATION_TAG and RNTI
        computed_checksum ^= crc_array->array[i].RX_UE_INFORMATION_TAG ^ crc_array->array[i].RNTI;
        if (computed_checksum % 2 != crc_array->array[i].CRCFLAG) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -1; // Integrity check failed
        }
    }

    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}

// Clean up resources
void destroy_crc_array(CRCArray *crc_array) {
    pthread_mutex_lock(&crc_array->mutex);

    free(crc_array->array);
    crc_array->array = NULL;

    pthread_mutex_unlock(&crc_array->mutex);
    pthread_mutex_destroy(&crc_array->mutex);
}
```

### Key Points:
- **Thread Safety**: Utilizes `pthread_mutex_t` for synchronization.
- **Dynamic Resizing**: Uses `realloc()` to handle array resizing.
- **Memory Management**: Checks for allocation failures and uses cleanup procedures.
- **Error Handling**: Returns error codes for different failure scenarios.
- **Checksum Verification**: Implements a simple integrity check mechanism.']

