#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define FRAME_RATE_NORMAL 10
#define FRAME_RATE_HIGH 15

typedef struct {
    int frame_num;
    int subframe_num;
    char frame_type; // 'T', 'N', etc.
    int srs_info;    // Simplified representation of SRS information
} LTE_DL_FRAMEINFO;

typedef struct {
    LTE_DL_FRAMEINFO *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} FrameArray;

void initialize_frame_array(FrameArray *array, size_t time_span) {
    array->capacity = time_span * FRAME_RATE_NORMAL; // Start with a normal frame rate
    array->frames = (LTE_DL_FRAMEINFO *)malloc(array->capacity * sizeof(LTE_DL_FRAMEINFO));
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void adjust_allocation(FrameArray *array, double load_factor) {
    pthread_mutex_lock(&array->lock);
    size_t new_capacity = (size_t)(array->capacity * load_factor);

    if (new_capacity > array->capacity) {
        LTE_DL_FRAMEINFO *temp_frames = realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
        if (temp_frames) {
            array->frames = temp_frames;
            array->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

int add_frame_info(FrameArray *array, int frame_num, int subframe_num, char frame_type, int srs_prob) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        adjust_allocation(array, 1.5); // Increase capacity by 50%
    }

    LTE_DL_FRAMEINFO *frame = &array->frames[array->count];
    frame->frame_num = frame_num;
    frame->subframe_num = subframe_num;
    frame->frame_type = frame_type;

    // Probabilistic SRS info population
    if ((rand() % 100) < srs_prob) {
        frame->srs_info = rand(); // Simulate SRS info assignment
    } else {
        frame->srs_info = 0;
    }

    array->count++;
    pthread_mutex_unlock(&array->lock);

    return 0; // Success
}

int validate_frame_array(FrameArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->frames[i].frame_num < 0 || 
            array->frames[i].subframe_num < 0 || 
            (array->frames[i].frame_type != 'T' && array->frames[i].frame_type != 'N')) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Invalid frame information
        }
    }

    pthread_mutex_unlock(&array->lock);
    return 0; // All frames are valid
}

void free_frame_array(FrameArray *array) {
    pthread_mutex_lock(&array->lock);
    if (array->frames) {
        free(array->frames);
        array->frames = NULL;
        array->capacity = 0;
        array->count = 0;
    }
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    FrameArray frame_array;
    initialize_frame_array(&frame_array, 100); // Initialize for a time span of 100 units

    // Example usage
    add_frame_info(&frame_array, 1, 0, 'T', 30); // 30% chance to populate SRS info
    add_frame_info(&frame_array, 2, 1, 'N', 50);

    if (validate_frame_array(&frame_array) == 0) {
        printf("Frame information is valid.\n");
    } else {
        printf("Invalid frame information detected.\n");
    }

    free_frame_array(&frame_array);
    return 0;
}
