#include <stdio.h>
#include <stdlib.h>
import threading

#define INITIAL_POOL_SIZE 10
#define MAC_PDU_ALIGNMENT 8

typedef struct {
    int pdu_type;
    int tag;
} MAC_PDU;

typedef struct {
    MAC_PDU *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MAC_PDU_Array;

MAC_PDU* allocate_aligned(size_t num_elements) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, MAC_PDU_ALIGNMENT, sizeof(MAC_PDU) * num_elements)) {
        return NULL;
    }
    return ptr;
}

MAC_PDU_Array* init_mac_pdu_array() {
    MAC_PDU_Array *array = malloc(sizeof(MAC_PDU_Array));
    if (!array) return NULL;

    array->capacity = INITIAL_POOL_SIZE;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->array = allocate_aligned(array->capacity);
    if (!array->array) {
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < array->capacity; ++i) {
        array->array[i].pdu_type = MAC_PDU_TYPE_RRC_RECONFIGURATION_COMPLETE;
        array->array[i].tag = MAC_RRC_RECONFIGURATION_COMPLETE_TAG;
    }

    return array;
}

int add_mac_pdu(MAC_PDU_Array *array, MAC_PDU pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDU *new_array = allocate_aligned(new_capacity);
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = 0; i < array->count; ++i) {
            new_array[i] = array->array[i];
        }

        free(array->array);
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->count++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void release_mac_pdu_array(MAC_PDU_Array *array) {
    if (!array) return;

    pthread_mutex_destroy(&array->lock);
    free(array->array);
    free(array);
}
```

Note: This code uses `posix_memalign` for alignment, which is generally available in POSIX-compliant systems. The mutex (`pthread_mutex_t`) ensures thread safety during concurrent access. The function also dynamically resizes the array when needed to accommodate more PDUs.']

