['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int frame_num;
    int subframe_num;
    int bandwidth_part;
    int channel_state_info; // 0 or 1 for simplicity
} NR_DL_FRAMEINFO;

// Function to initialize and manage a dynamic array of NR_DL_FRAMEINFO structures
NR_DL_FRAMEINFO* init_dynamic_frameinfo_array(int frame_count, int subframe_count, int bandwidth_parts, double probability) {
    if (frame_count <= 0 || subframe_count <= 0 || bandwidth_parts <= 0 || probability < 0.0 || probability > 1.0) {
        return NULL; // Validation of input parameters
    }

    NR_DL_FRAMEINFO* frame_info_array = malloc(frame_count * subframe_count * sizeof(NR_DL_FRAMEINFO));
    if (frame_info_array == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for reproducibility in this context

    for (int i = 0; i < frame_count; ++i) {
        for (int j = 0; j < subframe_count; ++j) {
            int index = i * subframe_count + j;
            NR_DL_FRAMEINFO* frame_info = &frame_info_array[index];

            frame_info->frame_num = i;
            frame_info->subframe_num = j;
            frame_info->bandwidth_part = rand() % bandwidth_parts;

            // Randomly set channel_state_info based on probability
            if ((double)rand() / RAND_MAX < probability) {
                frame_info->channel_state_info = 1; // Indicating active state
            } else {
                frame_info->channel_state_info = 0; // Indicating inactive state
            }
        }
    }

    return frame_info_array;
}

// Function to validate the integrity of the frame information
int validate_frameinfo_array(NR_DL_FRAMEINFO* array, int frame_count, int subframe_count) {
    if (array == NULL || frame_count <= 0 || subframe_count <= 0) {
        return 0; // Invalid input parameters
    }

    for (int i = 0; i < frame_count * subframe_count; ++i) {
        NR_DL_FRAMEINFO* frame_info = &array[i];

        if (frame_info->frame_num >= frame_count ||
            frame_info->subframe_num >= subframe_count ||
            frame_info->bandwidth_part <= 0 || 
            (frame_info->channel_state_info != 0 && frame_info->channel_state_info != 1)) {

            return 0; // Integrity check failed
        }
    }

    return 1; // All checks passed
}

// Example usage
int main() {
    int frame_count = 10;
    int subframe_count = 14;
    int bandwidth_parts = 5;
    double probability = 0.3;

    NR_DL_FRAMEINFO* frames = init_dynamic_frameinfo_array(frame_count, subframe_count, bandwidth_parts, probability);

    if (frames != NULL && validate_frameinfo_array(frames, frame_count, subframe_count)) {
        printf("Frame info array initialized and validated successfully.\n");
    } else {
        printf("Failed to initialize or validate the frame info array.\n");
    }

    free(frames); // Free allocated memory
    return 0;
}
