    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    int CRCFLAG; // 0 or 1, randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPILinkedList;

NFAPILinkedList* createList() {
    NFAPILinkedList* list = (NFAPILinkedList*)malloc(sizeof(NFAPILinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int sizeOfList(NFAPILinkedList* list) {
    int count = 0;
    Node* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void appendElement(NFAPILinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (sizeOfList(list) >= MAX_ELEMENTS) {
        printf("Error: List size exceeded maximum limit.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node.");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data = element;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void freeList(NFAPILinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T createRandomElement(int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFAPI_CRC_INDICATION_PDU_T element;
