        element.CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }

    // Set a random CRCFLAG
    element.CRCFLAG = rand() % 2;

    return element;
}

void* manageNFAPICRCList(void* arg) {
    NFAPILinkedList* list = createList();
    if (!list) {
        printf("Error: Failed to create the NFAPI list.\n");
        return NULL;
    }

