        unsigned short rnti = rand() % 65536;
        NFAPI_CRC_INDICATION_PDU_T element = createRandomElement(i, rnti);
        appendElement(list, element);
    }

    freeList(list);
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, manageNFAPICRCList, NULL) != 0) {
            perror("Failed to create thread");
        }
    }

