    printf("Packet ID: %d, Data: %s\n", packet->id, packet->data);
}

UDP_PACKET* manage_udp_packets(size_t N) {
    if (N == 0 || N < 1) {
        fprintf(stderr, "Invalid number of entries requested.\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t attempt = N;
    UDP_PACKET *packet_array = NULL;

    while (!packet_array && attempt > 0) {
        packet_array = allocate_packet_array(attempt);

        if (packet_array) {
            pthread_mutex_lock(&lock);

            // Process and log each packet
            for (size_t i = 0; i < attempt; ++i) {
                log_packet(&packet_array[i]);
            }

            pthread_mutex_unlock(&lock);

            break;
        } else {
            // Reduce the number of entries to retry if allocation fails.
            fprintf(stderr, "Memory allocation failed for %zu packets. Retrying with fewer entries...\n", attempt);
            attempt /= 2; // Halve the request size
        }
    }

    pthread_mutex_destroy(&lock);

    if (!packet_array) {
        fprintf(stderr, "Failed to allocate memory even after reducing packet count.\n");
        return NULL;
    }

    return packet_array;
}

void free_packet_array(UDP_PACKET *array) {
    if (array) free(array);
}
