NFAPIList* create_list() {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(NFAPIList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->size >= MAX_LIST_SIZE) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        return -1;
    }
    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_from_list(NFAPIList* list, size_t index) {
    if (!list || index >= list->size) {
        fprintf(stderr, "Invalid index access.\n");
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    if (!current) return (NFAPI_CRC_INDICATION_PDU_T){0};

    return current->data;
}

