}

void destroy_dynamic_list(DynamicList *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
        log_performance("DynamicList destroyed successfully");
    }
}

int resize_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            log_performance("Failed to reallocate memory for data");
            return -1;
        }

        list->data = new_data;
        list->capacity = new_capacity;

        log_performance("DynamicList resized successfully");
    }
    return 0;
}

int add_structure(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T structure) {
    pthread_mutex_lock(&list->lock);

    if (resize_if_needed(list) == -1) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[list->size++] = structure;

