#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_STRUCTS 10000
#define MAX_MEMORY_USAGE (2 * 1024 * 1024)
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    uint8_t rx_ue_information_tag[16];
    uint16_t rnti;
    struct {
        uint8_t crcflag;
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *prev, *next;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(DoublyLinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if ((sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size(list)) >= MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_size(DoublyLinkedList *list) {
    int size = 0;
    Node *current = list->head;
    while (current) {
        size++;
        current = current->next;
    }
    return size;
}

void sort_list(DoublyLinkedList *list, int ascending) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || !list->head->next) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node *i = list->head;
    while (i != NULL) {
        Node *j = i->next;
        while (j != NULL) {
            int cmp = ascending ? 
                      ((int)i->data.rnti - (int)j->data.rnti) : 
                      ((int)j->data.rnti - (int)i->data.rnti);
            if (cmp > 0) {
                NFAPI_CRC_INDICATION_PDU_T temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
            j = j->next;
        }
        i = i->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const char *filename, DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node *current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void update_crcflag(DoublyLinkedList *list, uint16_t rnti, uint8_t new_crcflag) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        if (current->data.rnti == rnti) {
            current->data.crc_indication_rel8_tag.crcflag = new_crcflag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void generate_nfaapi_list(DoublyLinkedList **list, int num_structs, int ascending) {
    *list = create_list();

    for (int i = 0; i < num_structs && i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Fill in rx_ue_information_tag with dummy data
        memset(pdu.rx_ue_information_tag, rand() % 256, sizeof(pdu.rx_ue_information_tag));

        pdu.rnti = (uint16_t)(rand() % 65536);
        pdu.crc_indication_rel8_tag.crcflag = rand() % 2;

        if (add_node(*list, pdu) != 0) {
            fprintf(stderr, "Failed to add node due to memory constraints.\n");
            break;
        }
    }

    sort_list(*list, ascending);
}

int main() {
    DoublyLinkedList *list;
    generate_nfaapi_list(&list, MAX_STRUCTS, 1);

    serialize_list("output.bin", list);

    update_crcflag(list, 1234, 1); // Example of real-time update

    free_list(list);
    return 0;
}
```

This code provides a basic implementation that manages the creation and manipulation of `NFAPI_CRC_INDICATION_PDU_T` structures within a thread-safe doubly linked list. It includes functions for sorting, serialization, updates, and ensures memory constraints are respected while handling concurrency.']

