#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 100

typedef struct {
    // Placeholder for actual data type
    int RX_UE_INFORMATION_TAG;
} NFAPI_RX_PDU_PAYLOAD_T;

typedef struct {
    int RNTI;
    NFAPI_RX_PDU_PAYLOAD_T payload;
    size_t payload_size;
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T *array;
    size_t capacity;
    size_t count;
} NFAPI_RX_PDU_Manager;

// Function to initialize the manager
void nfaapi_rx_pdu_manager_init(NFAPI_RX_PDU_Manager *manager) {
    if (manager == NULL) return;
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->array = (NFAPI_RX_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_RX_PDU_T));
    if (manager->array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function to resize the array
void nfaapi_rx_pdu_manager_resize(NFAPI_RX_PDU_Manager *manager) {
    if (manager == NULL || manager->capacity == 0) return;
    size_t new_capacity = manager->capacity * 2;
    NFAPI_RX_PDU_T *new_array = (NFAPI_RX_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_RX_PDU_T));
    if (new_array == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = new_capacity;
    manager->array = new_array;
}

// Function to add a PDU
void nfaapi_rx_pdu_manager_add(NFAPI_RX_PDU_Manager *manager, NFAPI_RX_PDU_T pdu) {
    if (manager == NULL) return;
    if (manager->count >= manager->capacity) {
        nfaapi_rx_pdu_manager_resize(manager);
    }
    manager->array[manager->count++] = pdu;
}

// Function to filter PDUs by RNTI
NFAPI_RX_PDU_T* nfaapi_rx_pdu_manager_filter_by_rnti(NFAPI_RX_PDU_Manager *manager, int rnti, size_t *out_count) {
    if (manager == NULL || out_count == NULL) return NULL;
    NFAPI_RX_PDU_T *filtered = malloc(manager->count * sizeof(NFAPI_RX_PDU_T));
    if (filtered == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    size_t count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == rnti) {
            filtered[count++] = manager->array[i];
        }
    }
    *out_count = count;
    return filtered;
}

// Function to free resources
void nfaapi_rx_pdu_manager_free(NFAPI_RX_PDU_Manager *manager) {
    if (manager == NULL || manager->array == NULL) return;
    for (size_t i = 0; i < manager->count; ++i) {
        // Assuming payload_size is the size of the allocated buffer
        free(manager->array[i].payload.payload);
    }
    free(manager->array);
    manager->capacity = 0;
    manager->count = 0;
}

// Function to iterate over PDUs
void nfaapi_rx_pdu_manager_iterate(NFAPI_RX_PDU_Manager *manager, void (*callback)(NFAPI_RX_PDU_T)) {
    if (manager == NULL || callback == NULL) return;
    for (size_t i = 0; i < manager->count; ++i) {
        callback(manager->array[i]);
    }
}

// Example usage
void print_pdu(NFAPI_RX_PDU_T pdu) {
    printf("RNTI: %d, Info Tag: %d\n", pdu.RNTI, pdu.payload.RX_UE_INFORMATION_TAG);
}

int main() {
    NFAPI_RX_PDU_Manager manager;
    nfaapi_rx_pdu_manager_init(&manager);

    // Example of adding PDUs
    for (int i = 0; i < 150; ++i) {
        NFAPI_RX_PDU_T pdu = { .RNTI = i % 10, .payload = { .RX_UE_INFORMATION_TAG = i } };
        nfaapi_rx_pdu_manager_add(&manager, pdu);
    }

    // Example of filtering
    size_t count;
    NFAPI_RX_PDU_T *filtered = nfaapi_rx_pdu_manager_filter_by_rnti(&manager, 5, &count);
    for (size_t i = 0; i < count; ++i) {
        print_pdu(filtered[i]);
    }
    free(filtered);

    // Example of iteration
    nfaapi_rx_pdu_manager_iterate(&manager, print_pdu);

    // Cleanup
    nfaapi_rx_pdu_manager_free(&manager);
    return 0;
}
