            break;
        }
        current = current->next;
    }
}

void free_list(ThreadSafeLinkedList* list) {
    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;
        free(temp);
        list->allocated_memory -= sizeof(Node);
    }
    pthread_mutex_destroy(&list->mutex);
}

