```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NODES 10000
#define MEMORY_LIMIT (2 * 1024 * 1024)
#define CACHE_MEMORY_THRESHOLD (0.9 * MEMORY_LIMIT)

typedef struct CRC_INDICATION_REL8_TAG {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    ASCENDING,
    DESCENDING
} SortOrder;

typedef struct DoublyLinkedList {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    size_t node_count;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->node_count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(DoublyLinkedList* list, int RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (list->node_count >= MAX_NODES || 
        sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->node_count + 1) > MEMORY_LIMIT) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return -1;

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Simulate probabilistic error
    if (rand() % 100 < 5) { // Approximately 5% chance to set CRCFLAG incorrectly
        new_node->crc_indication_rel8_tag.CRCFLAG ^= 1;
    }

    pthread_mutex_lock(&list->lock);

    new_node->prev = NULL;
    new_node->next = list->head;
    if (list->head) {
        list->head->prev = new_node;
    } else {
        list->tail = new_node;
    }
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    list->node_count++;

    return 0;
}

int sort_list(DoublyLinkedList* list, SortOrder order) {
    if (!list || !list->head) return -1;

    int swapped;
    NFAPI_CRC_INDICATION_PDU_T *ptr1, *lptr = NULL;

    do {
        swapped = 0;
        ptr1 = list->head;

        while (ptr1 && ptr1->next != lptr) {
            if ((order == ASCENDING && ptr1->RNTI > ptr1->next->RNTI) ||
                (order == DESCENDING && ptr1->RNTI < ptr1->next->RNTI)) {

                int temp_tag = ptr1->RX_UE_INFORMATION_TAG;
                uint16_t temp_rnti = ptr1->RNTI;
                uint32_t temp_crcflag = ptr1->crc_indication_rel8_tag.CRCFLAG;

                ptr1->RX_UE_INFORMATION_TAG = ptr1->next->RX_UE_INFORMATION_TAG;
                ptr1->RNTI = ptr1->next->RNTI;
                ptr1->crc_indication_rel8_tag.CRCFLAG = ptr1->next->crc_indication_rel8_tag.CRCFLAG;

                ptr1->next->RX_UE_INFORMATION_TAG = temp_tag;
                ptr1->next->RNTI = temp_rnti;
                ptr1->next->crc_indication_rel8_tag.CRCFLAG = temp_crcflag;

                swapped = 1;
            }
            ptr1 = ptr1->next;
        }
        lptr = ptr1;
    } while (swapped);

    return 0;
}

int serialize_list(DoublyLinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);

    return 0;
}

int generateNfarpcPduWithDynamicGameActions(int num_nodes) {
    if (num_nodes <= 0 || num_nodes > MAX_NODES) return -1;

    DoublyLinkedList* list = create_list();
    if (!list) return -1;

    srand(time(NULL));

    for (int i = 0; i < num_nodes; ++i) {
        int RX_UE_INFORMATION_TAG = rand() % 10000;
        uint16_t RNTI = rand() % 65536;

        if (add_node(list, RX_UE_INFORMATION_TAG, RNTI) != 0) {
            destroy_list(list);
            return -1;
        }
    }

    // Sort the list in ascending order by default
    sort_list(list, ASCENDING);

    if (serialize_list(list, "pdu_data.bin") != 0) {
        destroy_list(list);
        return -1;
    }

    destroy_list(list);

    return 0;
}

typedef struct CooldownTracker {
    time_t last_fire;
    time_t last_dash;
    time_t last_heal;
} CooldownTracker;

void init_cooldown_tracker(CooldownTracker* tracker) {
    if (!tracker) return;

    tracker->last_fire = time(NULL);
    tracker->last_dash = time(NULL);
    tracker->last_heal = time(NULL);
}

int can_execute_action(CooldownTracker* tracker, const char* action) {
    if (!tracker || !action) return 0;

    time_t current_time = time(NULL);

    int cooldown_seconds = 0;
    if (strcmp(action, "fire") == 0) cooldown_seconds = 5;
    else if (strcmp(action, "dash") == 0) cooldown_seconds = 7;
    else if (strcmp(action, "heal") == 0) cooldown_seconds = 10;

    if (!cooldown_seconds) return 1; // Invalid action

    time_t last_exec_time = 0;
    if (strcmp(action, "fire") == 0) last_exec_time = tracker->last_fire;
    else if (strcmp(action, "dash") == 0) last_exec_time = tracker->last_dash;
    else if (strcmp(action, "heal") == 0) last_exec_time = tracker->last_heal;

    return difftime(current_time, last_exec_time) >= cooldown_seconds;
}

void execute_action(CooldownTracker* tracker, const char* action) {
    if (!tracker || !action || can_execute_action(tracker, action) != 1) return;

    time_t current_time = time(NULL);

    if (strcmp(action, "fire") == 0) tracker->last_fire = current_time;
    else if (strcmp(action, "dash") == 0) tracker->last_dash = current_time;
    else if (strcmp(action, "heal") == 0) tracker->last_heal = current_time;

    printf("Executed action: %s\n", action);
}

int generateNfarpcPduWithRandomGameAction() {
    CooldownTracker tracker;
    init_cooldown_tracker(&tracker);

    const char* actions[] = {"fire", "dash", "heal"};
    size_t num_actions = sizeof(actions) / sizeof(actions[0]);

    for (size_t i = 0; i < 10; ++i) { // Simulate 10 rounds of action selection
        int rand_index = rand() % num_actions;
        const char* action = actions[rand_index];

        if (can_execute_action(&tracker, action)) {
            execute_action(&tracker, action);
        } else {
            printf("Action '%s' is on cooldown.\n", action);
        }
    }

    return 0;
}
