#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define MAX_MEMORY (1 * 1024 * 1024 * 1024) // 1GB

typedef struct {
    char ip_address[16];
    char mac_address[18]; // MAC addresses are usually represented as "XX:XX:XX:XX:XX:XX"
    int mtu;
    double bandwidth_usage;
} TCP_NODE_DIAGNOSTIC_INFO_T;

typedef struct AVLNode {
    TCP_NODE_DIAGNOSTIC_INFO_T data;
    struct AVLNode *left, *right;
    int height;
} AVLNode;

AVLNode* root = NULL;
pthread_mutex_t tree_lock = PTHREAD_MUTEX_INITIALIZER;

int height(AVLNode *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

AVLNode* newNode(TCP_NODE_DIAGNOSTIC_INFO_T data) {
    AVLNode* node = (AVLNode*)malloc(sizeof(AVLNode));
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

int max(int a, int b) {
    return (a > b)? a : b;
}

AVLNode *rightRotate(AVLNode *y) {
    AVLNode *x = y->left;
    AVLNode *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

AVLNode *leftRotate(AVLNode *x) {
    AVLNode *y = x->right;
    AVLNode *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

int getBalance(AVLNode *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

AVLNode* insert(AVLNode* node, TCP_NODE_DIAGNOSTIC_INFO_T data) {
    if (node == NULL)
        return newNode(data);

    // Assume IP addresses are strings and use strcmp for comparison
    int cmp = strcmp(data.ip_address, node->data.ip_address);
    if (cmp < 0)
        node->left = insert(node->left, data);
    else if (cmp > 0)
        node->right = insert(node->right, data);
    else // duplicate IPs are not allowed
        return node;

    node->height = 1 + max(height(node->left), height(node->right));

    int balance = getBalance(node);

    if (balance > 1 && strcmp(data.ip_address, node->left->data.ip_address) < 0)
        return rightRotate(node);
    if (balance < -1 && strcmp(data.ip_address, node->right->data.ip_address) > 0)
        return leftRotate(node);
    if (balance > 1 && strcmp(data.ip_address, node->left->data.ip_address) > 0) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }
    if (balance < -1 && strcmp(data.ip_address, node->right->data.ip_address) < 0) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

void inOrderTraversal(AVLNode *root, FILE *file, int chunk_size) {
    static int counter = 0;

    if (root != NULL) {
        inOrderTraversal(root->left, file, chunk_size);

        fwrite(&root->data, sizeof(TCP_NODE_DIAGNOSTIC_INFO_T), 1, file);

        counter++;
        if (counter % chunk_size == 0) {
            fflush(file); // Ensure data is written to the file
        }

        inOrderTraversal(root->right, file, chunk_size);
    }
}

void serializeTree(const char *filename, int ascending) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Unable to open file for writing");
        return;
    }

    pthread_mutex_lock(&tree_lock);

    AVLNode *temp_root = root;

    if (!ascending)
        // Implement descending order logic
        ; 

    inOrderTraversal(temp_root, file, 500);

    fclose(file);
    pthread_mutex_unlock(&tree_lock);
}

void updateNetworkInfo(TCP_NODE_DIAGNOSTIC_INFO_T info) {
    pthread_mutex_lock(&tree_lock);

    root = insert(root, info);

    pthread_mutex_unlock(&tree_lock);
}

// Assume a function that periodically fetches updates
void externalDataSourceUpdate() {
    while (1) {
        TCP_NODE_DIAGNOSTIC_INFO_T new_data;

        // Code to populate new_data from an external source

        updateNetworkInfo(new_data);

        sleep(5); // Simulate periodic updates, adjust as needed
    }
}

int main() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void*)&externalDataSourceUpdate, NULL) != 0) {
        perror("Thread creation failed");
        return EXIT_FAILURE;
    }

    char filename[] = "network_data.bin";
    serializeTree(filename, 1);

    pthread_join(thread_id, NULL);
    return 0;
}
