// Function to generate a random RNTI and check uniqueness
int generate_unique_rnti(uint16_t *rnti_set, uint16_t rnti) {
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        if (rnti_set[i] == rnti) {
            return 0;
        }
    }
    return 1;
}

// Function to create and populate the list
NFAPI_CRC_LIST_T *create_nfa_crc_list(size_t num_entries) {
    if (num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Requested number of entries exceeds maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_LIST_T *list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    list->entries = calloc(num_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        perror("Failed to allocate memory for entries");
        free(list);
        return NULL;
    }

    // Set up random number generation
    srand((unsigned int)time(NULL));

    uint16_t rnti_set[MAX_ENTRIES] = {0}; // To track unique RNTI values

    pthread_mutex_lock(&nfa_mutex);

    for (size_t i = 0; i < num_entries; ++i) {
        list->entries[i].RX_UE_INFORMATION_TAG = i + 1;

        uint16_t rnti;
        do {
            rnti = rand() % 0xFFFF + 1; // Ensure non-zero
        } while (!generate_unique_rnti(rnti_set, rnti));

        list->entries[i].RNTI = rnti;
        rnti_set[i] = rnti;

        list->entries[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    pthread_mutex_unlock(&nfa_mutex);

    list->count = num_entries;

    return list;
}

// Function to free the list
void free_nfa_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        if (list->entries) {
            free(list->entries);
        }
        free(list);
    }
}

int main() {
    size_t num_entries = 10000;
    NFAPI_CRC_LIST_T *crc_list = create_nfa_crc_list(num_entries);

