static int get_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

static uint16_t generate_unique_rnti(uint16_t *rnti_history) {
    uint16_t rnti;
    do {
        rnti = get_random_int(0, MAX_RNTI);
    } while (rnti_history[CHECK_WINDOW_SIZE - 1] == rnti);

    // Update history
    memmove(&rnti_history[0], &rnti_history[1], sizeof(uint16_t) * (CHECK_WINDOW_SIZE - 1));
    rnti_history[CHECK_WINDOW_SIZE - 1] = rnti;

    return rnti;
}

static void detect_rnti_conflicts(uint16_t *rnti_history, uint16_t current_rnti) {
    for (int i = 0; i < CHECK_WINDOW_SIZE - 1; i++) {
        if (current_rnti == rnti_history[i]) {
            log_message("Warning: RNTI conflict detected.");
            break;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdus(Configuration_T config) {
    srand(config.seed);
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(config.N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    uint16_t rnti_history[CHECK_WINDOW_SIZE] = {0};
    for (int i = 0; i < config.N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = get_random_int(1, 10000);

        if (i > 0) {
            pdus[i - 1].RNTI = pdus[i].RNTI;
        }

        pdus[i].RNTI = generate_unique_rnti(rnti_history);
        detect_rnti_conflicts(rnti_history, pdus[i].RNTI);

        // Simulate CRCFLAG setting
        // Example: pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return pdus;
}

void log_message(const char* message) {
    if (config.log_callback != NULL) {
        config.log_callback(message);
    } else {
        printf("%s\n", message); // Default logging
    }
}
