typedef struct {
    // Define the structure based on given context.
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* init_dynamic_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int append_to_list(DynamicList* list, unsigned int ue_info_tag, unsigned int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    // Check for reallocation
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Allocation failure
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->count];
    element->RX_UE_INFORMATION_TAG = ue_info_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    free(list->elements);
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

