#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG informationTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int rnti_count[MAX_RNTI + 1];
} LinkedList;

// Hash table functions
int hash_function(uint32_t rnti) {
    return rnti % (MAX_RNTI + 1);
}

void initialize_rnti_count(int* rnti_count) {
    for (int i = 0; i <= MAX_RNTI; ++i) {
        rnti_count[i] = 0;
    }
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    initialize_rnti_count(list->rnti_count);

    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    int index = hash_function(data.informationTag.RNTI);

    if (list->rnti_count[index] > 0) return -1; // RNTI already exists

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->rnti_count[index]++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void cleanup_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;

        int index = hash_function(temp->data.informationTag.RNTI);
        if (--list->rnti_count[index] == 0) {
            // Optionally implement a more complex cleanup strategy here
        }

        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void populate_linked_list(LinkedList* list, int n) {
