    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    bool full_callback_set;
    void (*full_callback)(void);
} DoublyLinkedList;

// Function prototypes
DoublyLinkedList* create_list(size_t max_size, void (*on_full)(void));
bool insert_node(DoublyLinkedList *list, int rx_ue_info_tag, int rnti);
NFAPI_CRC_INDICATION_PDU_T* find_node_by_rnti(DoublyLinkedList *list, int rnti);
bool delete_node(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node);
void free_list(DoublyLinkedList *list);
void garbage_collect(DoublyLinkedList *list);

// Function implementations
DoublyLinkedList* create_list(size_t max_size, void (*on_full)(void)) {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->full_callback_set = on_full != NULL;
    list->full_callback = on_full;

    return list;
}

bool insert_node(DoublyLinkedList *list, int rx_ue_info_tag, int rnti) {
    if (pthread_mutex_lock(&list->lock)) return false;

    if (list->count >= list->max_size) {
        if (list->full_callback_set && list->full_callback) {
            list->full_callback();
        }
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T *existing_node = find_node_by_rnti(list, rnti);
    if (existing_node) {
        pthread_mutex_unlock(&list->lock);
        return false; // RNTI must be unique
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->crc_tag.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->crc_tag.RNTI = rnti;
    srand(time(NULL) ^ (unsigned int)getpid());
    new_node->crc_tag.CRCFLAG = rand() % 2;

    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* find_node_by_rnti(DoublyLinkedList *list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->crc_tag.RNTI == rnti) return current;
        current = current->next;
    }
    return NULL;
}

bool delete_node(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    if (!node || pthread_mutex_lock(&list->lock)) return false;

    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    free(node);
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return true;
}

void free_list(DoublyLinkedList *list) {
    if (!list || pthread_mutex_lock(&list->lock)) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void garbage_collect(DoublyLinkedList *list) {
    // Example: Periodic cleanup could be implemented here
    // This function can remove nodes based on certain criteria, e.g., age or usage.
    if (pthread_mutex_lock(&list->lock)) return;

    // Placeholder for actual garbage collection logic
    pthread_mutex_unlock(&list->lock);
}
