#include <string.h>
#include <pthread.h>

typedef struct CRC_INDICATION_REL8_TAG {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned int RNTI;  // Unique Resource Block Identifier
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev; // For bidirectional traversal
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    pthread_mutex_t lock;
} CRCList;

// Function prototypes
CRCList* create_list(void);
void destroy_list(CRCList *list);
NFAPI_CRC_INDICATION_PDU_T* insert_node(CRCList *list, unsigned int rnti);
int is_rnti_unique(CRCList *list, unsigned int rnti);
void serialize_to_file(const char *filename, CRCList *list);
void traverse_list_forward(CRCList *list);
void traverse_list_backward(CRCList *list);

CRCList* create_list(void) {
    CRCList *list = (CRCList *)malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    return list;
}

void destroy_list(CRCList *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* insert_node(CRCList *list, unsigned int rnti) {
    if (!is_rnti_unique(list, rnti)) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }

    new_node->ue_info_tag.RNTI = rnti;
    new_node->crc_indication_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = new_node->prev = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return new_node;
}

int is_rnti_unique(CRCList *list, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->ue_info_tag.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void serialize_to_file(const char *filename, CRCList *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        fwrite(&(current->ue_info_tag.RNTI), sizeof(unsigned int), 1, file);
        fwrite(&(current->crc_indication_tag.CRCFLAG), sizeof(unsigned int), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void traverse_list_forward(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %u\n", current->ue_info_tag.RNTI, current->crc_indication_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void traverse_list_backward(CRCList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->tail;
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %u\n", current->ue_info_tag.RNTI, current->crc_indication_tag.CRCFLAG);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Example usage
    CRCList *list = create_list();
    insert_node(list, 1001);
    insert_node(list, 1002);

    traverse_list_forward(list);
    traverse_list_backward(list);

    serialize_to_file("data.bin", list);
    destroy_list(list);

    return 0;
}
```

### Explanation of Trade-offs:
- **Efficiency vs. Scalability**: Using a mutex lock ensures thread safety but can impact performance under high contention.
- **Memory Management**: Allocating nodes as needed minimizes memory usage, though it increases complexity in managing allocations and deallocations.
- **Serialization**: Writing directly to a binary file optimizes for space and speed, while ensuring cross-platform compatibility by explicitly managing data types.
- **Traversal**: Bidirectional traversal is achieved with minimal overhead by maintaining both `next` and `prev` pointers.']

