    collection->frames = (TX_FRAME_DATA **)malloc(initial_capacity * sizeof(TX_FRAME_DATA *));
    if (!collection->frames) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->count = 0;

    pthread_mutex_init(&collection->lock, NULL);
    pthread_cond_init(&collection->cond_var, NULL);
}

void destroy_collection(FrameCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->frames[i]);
    }
    free(collection->frames);

    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond_var);
}

int add_frame_data(FrameCollection *collection, TX_FRAME_DATA *frame) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        resize_collection(collection);
    }

    collection->frames[collection->count++] = frame;
    pthread_cond_signal(&collection->cond_var);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

TX_FRAME_DATA* get_frame_data(FrameCollection *collection, size_t index) {
    if (index >= collection->count) {
        return NULL;
    }

    pthread_mutex_lock(&collection->lock);
    TX_FRAME_DATA* frame = collection->frames[index];
    pthread_mutex_unlock(&collection->lock);

    return frame;
}

void resize_collection(FrameCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    TX_FRAME_DATA **new_frames = (TX_FRAME_DATA **)realloc(collection->frames, new_capacity * sizeof(TX_FRAME_DATA *));

    if (!new_frames) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        new_frames[i] = NULL;
    }

    collection->frames = new_frames;
    collection->capacity = new_capacity;
}

// Periodic cleanup strategy
