// Function to add a new network entity ensuring RNTI uniqueness and thread safety
bool add_network_entity(NetworkEntityList* list, NetworkEntity* new_entity) {
    pthread_mutex_lock(&list_lock);

    // Check for unique RNTI
    NetworkEntity* current = list->head;
    while (current != NULL) {
        if (current->nfa_pi.RNTI == new_entity->nfa_pi.RNTI) {
            log_message("Error: Duplicate RNTI found. Entity not added.");
            pthread_mutex_unlock(&list_lock);
            return false;
        }
        current = current->next;
    }

    // Add entity to the list
    new_entity->next = list->head;
    list->head = new_entity;

    pthread_mutex_unlock(&list_lock);
    log_message("Network entity added successfully.");
    return true;
}

// Function to remove a network entity by ID
bool remove_network_entity(NetworkEntityList* list, unsigned long id) {
    pthread_mutex_lock(&list_lock);

    NetworkEntity **indirect = &list->head;
    while (*indirect != NULL) {
        if ((*indirect)->id == id) {
            NetworkEntity *to_delete = *indirect;
            *indirect = to_delete->next;
            custom_free(to_delete);
            log_message("Network entity removed successfully.");
            pthread_mutex_unlock(&list_lock);
