```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;  // Randomly set this value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRC_Indication_Array;

// Function prototypes
void initialize_crc_indications(CRC_Indication_Array **result, size_t initial_capacity);
int resize_array_if_needed(CRC_Indication_Array *array);
NFAPI_CRC_INDICATION_PDU_T* allocate_structure();
void deallocate_array(CRC_Indication_Array *array);

void initialize_crc_indications(CRC_Indication_Array **result, size_t initial_capacity) {
    if (initial_capacity == 0) return;

    // Initialize the array structure
    CRC_Indication_Array *array = malloc(sizeof(CRC_Indication_Array));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for CRC_Indication_Array\n");
        *result = NULL;
        return;
    }

    pthread_mutex_init(&array->lock, NULL);

    array->capacity = initial_capacity;
    array->count = 0;

    // Allocate memory pool
    array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array\n");
        pthread_mutex_destroy(&array->lock);
        free(array);
        *result = NULL;
        return;
    }

    // Initialize the array with structures
    size_t i;
    for (i = 0; i < initial_capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure();
        if (!structure) break;
        memcpy(&array->array[i], structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(structure);
    }

    array->count = i;

    *result = array;
}

int resize_array_if_needed(CRC_Indication_Array *array) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2; // Double the capacity
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return -1;  // Indicate failure to resize
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) return NULL;

    // Initialize structure with some values and random CRCFLAG
    structure->RX_UE_INFORMATION_TAG = rand();  // Replace with actual logic as necessary
    structure->RNTI = rand();                   // Replace with actual logic as necessary
    structure->CRC_INDICATION_REL8_TAG = rand(); // Replace with actual logic as necessary
    structure->CRCFLAG = (unsigned char)(rand() % 2);  // Randomly set to 0 or 1

    return structure;
}

void deallocate_array(CRC_Indication_Array *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    free(array->array);
    array->array = NULL;
    array->capacity = 0;
    array->count = 0;

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

