#define INIT_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Assuming this is the flag to set randomly
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

// Error codes
#define SUCCESS 0
#define ALLOCATION_FAILED 1
#define INVALID_INPUT 2

MemoryPool* initialize_memory_pool(size_t initial_capacity) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;
    mp->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->capacity = initial_capacity;
    mp->count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void close_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

int resize_memory_pool(MemoryPool* mp, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* resized_pool = realloc(mp->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!resized_pool) return ALLOCATION_FAILED;

    mp->pool = resized_pool;
    mp->capacity = new_capacity;
    return SUCCESS;
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Assume CRCFLAG is a boolean or binary value
    pdu->CRCFLAG = rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T** initialize_crc_indications(int N, int* error_code, unsigned int seed) {
    if (N <= 0) {
        *error_code = INVALID_INPUT;
        return NULL;
    }

    srand(seed);

    MemoryPool* mp = initialize_memory_pool(INIT_CAPACITY);
    if (!mp) {
        *error_code = ALLOCATION_FAILED;
        return NULL;
    }

    size_t init_count = 0, attempt_count = 0;

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mp->lock);

        if (mp->count >= mp->capacity) {
            int resize_result = resize_memory_pool(mp, mp->capacity * 2);
            if (resize_result != SUCCESS) {
                pthread_mutex_unlock(&mp->lock);
                close_memory_pool(mp);
                *error_code = ALLOCATION_FAILED;
                return NULL;
            }
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = &mp->pool[mp->count++];
        pdu->RX_UE_INFORMATION_TAG = rand(); // Example initialization
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();
        set_random_crcflag(pdu);

        init_count++;
        attempt_count++;

        pthread_mutex_unlock(&mp->lock);
    }

    printf("Initialized %zu structures out of %d attempts\n", init_count, attempt_count);

    NFAPI_CRC_INDICATION_PDU_T** result_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!result_array) {
        close_memory_pool(mp);
        *error_code = ALLOCATION_FAILED;
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        result_array[i] = &mp->pool[i];
    }

    *error_code = SUCCESS;
    return result_array;
}

