void init_dynamic_array(DynamicArray* dynamic_array) {
    pthread_mutex_init(&dynamic_array->mutex, NULL);
    dynamic_array->current_size = 0;
    dynamic_array->max_size = 1000; // Initial size
    dynamic_array->array = malloc(dynamic_array->max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
