}

void free_dynamic_array(DynamicArray* dynamic_array) {
    pthread_mutex_destroy(&dynamic_array->mutex);
    free(dynamic_array->array);

    if (dynamic_array->cache) {
        free(dynamic_array->cache);
    }
}

void resize_array_if_needed(DynamicArray* dynamic_array, size_t required_size) {
    pthread_mutex_lock(&dynamic_array->mutex);

    if (required_size > dynamic_array->max_size) {
        while (dynamic_array->max_size < required_size && dynamic_array->max_size <= MAX_STRUCTS) {
            dynamic_array->max_size *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(dynamic_array->array, dynamic_array->max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            fprintf(stderr, "Memory allocation failed when resizing array\n");
            exit(EXIT_FAILURE);
        }

        dynamic_array->array = new_array;
    }

    pthread_mutex_unlock(&dynamic_array->mutex);
}

void* process_packet(void* arg) {
