    NFAPI_CRC_INDICATION_PDU_T* element;
    pthread_mutex_lock(&dynamic_array->mutex);

    if (dynamic_array->cache && dynamic_array->cache_size > 0) {
        // Use cache mechanism
        element = &dynamic_array->cache[--dynamic_array->cache_size];
        printf("Cache hit\n");
    } else {
        // Allocate from the main array
        element = &dynamic_array->array[dynamic_array->current_size++];
        printf("Cache miss, allocating new element\n");
    }

    pthread_mutex_unlock(&dynamic_array->mutex);

    // Simulate processing
    element->some_field = rand(); 

    return NULL;
}

void simulate_concurrent_processing(DynamicArray* dynamic_array, int num_threads) {
