['Below is a C implementation of the requested functionality. This example assumes you have access to threading libraries like `pthread` for thread-safety and some basic logging mechanism.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define INITIAL_SIZE 1000
#define MAX_STRUCTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    int log_level; // 0 = none, 1 = basic, 2 = verbose
} CRCManager;

// Function prototypes
void init_crc_manager(CRCManager *manager, int log_level);
void free_crc_manager(CRCManager *manager);
int resize_array(CRCManager *manager, size_t new_capacity);
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(CRCManager *manager);

// Thread-safe logging function
static void log_message(CRCManager *manager, const char *message) {
    if (manager->log_level > 0) {
        pthread_mutex_lock(&manager->lock);
        printf("%s\n", message);
        pthread_mutex_unlock(&manager->lock);
    }
}

void init_crc_manager(CRCManager *manager, int log_level) {
    manager->size = 0;
    manager->capacity = INITIAL_SIZE;
    manager->log_level = log_level;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        exit(EXIT_FAILURE);
    }

    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate initial array");
        exit(EXIT_FAILURE);
    }

    log_message(manager, "CRC Manager initialized.");
}

void free_crc_manager(CRCManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->array) {
        free(manager->array);
        log_message(manager, "Array memory freed.");
    }

    if (pthread_mutex_destroy(&manager->lock)) {
        fprintf(stderr, "Mutex destruction failed\n");
    }

    manager->size = 0;
    manager->capacity = 0;
}

int resize_array(CRCManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    if (new_capacity > MAX_STRUCTS) {
        log_message(manager, "Attempt to exceed maximum capacity. Resizing failed.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        log_message(manager, "Memory allocation for resizing failed.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->array = temp;
    manager->capacity = new_capacity;

    log_message(manager, "Array resized successfully.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(CRCManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (resize_array(manager, new_capacity)) {
            pthread_mutex_unlock(&manager->lock);
            return NULL; // Allocation failed
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->size++];

    // Populate the structure with valid data
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() & 1; // Randomly set to 0 or 1

    log_message(manager, "PDU allocated and populated.");

    pthread_mutex_unlock(&manager->lock);
    return pdu;
}
