#define MAX_POOLS 4

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Pool;

Pool memory_pools[MAX_POOLS];
int pool_count = 0;

void init_pool() {
    if (pool_count < MAX_POOLS) {
        memory_pools[pool_count].head = NULL;
        pthread_mutex_init(&memory_pools[pool_count].lock, NULL);
        pool_count++;
    }
}

Node* allocate_node(int pool_index) {
    if (pool_index < 0 || pool_index >= pool_count)
        return NULL;

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_pools[pool_index].lock);
    node->next = memory_pools[pool_index].head;
    memory_pools[pool_index].head = node;
    pthread_mutex_unlock(&memory_pools[pool_index].lock);

    return node;
}

void deallocate_node(int pool_index, Node* node) {
    if (pool_index < 0 || pool_index >= pool_count)
        return;

    pthread_mutex_lock(&memory_pools[pool_index].lock);
    node->next = memory_pools[pool_index].head;
    memory_pools[pool_index].head = node;
    pthread_mutex_unlock(&memory_pools[pool_index].lock);

    free(node);
}

void insert_pdu(Pool* pool, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = allocate_node(pool_count - 1);
    if (new_node) {
        new_node->data = pdu;
        pthread_mutex_lock(&pool->lock);
        new_node->next = pool->head;
        pool->head = new_node;
        pthread_mutex_unlock(&pool->lock);
    }
}

void delete_pdu_by_rnti(Pool* pool, unsigned int rnti) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev)
                prev->next = current->next;
            else
                pool->head = current->next;

            deallocate_node(pool_count - 1, current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

Node* search_pdu_by_rnti(Pool* pool, unsigned int rnti) {
    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&pool->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void save_to_disk(const char* filename, Pool* pool) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return;

    pthread_mutex_lock(&pool->lock);

    Node *current = pool->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
    fclose(file);
}

void load_from_disk(const char* filename, Pool* pool) {
    FILE *file = fopen(filename, "rb");
    if (!file)
        return;

    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insert_pdu(pool, pdu);
    }

    fclose(file);
}

void monitor_resources() {
    // Placeholder for resource monitoring logic
    printf("Resource usage: Monitoring in progress...\n");
}

int main() {
    Pool my_pool;
    my_pool.head = NULL;
    pthread_mutex_init(&my_pool.lock, NULL);

    init_pool();

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 2023, (unsigned char)(rand() % 2)};
    insert_pdu(&my_pool, pdu);

    save_to_disk("pdu_data.bin", &my_pool);
    load_from_disk("pdu_data.bin", &my_pool);

    Node* found_node = search_pdu_by_rnti(&my_pool, 1001);
    if (found_node)
        printf("Found PDU with RNTI: %u\n", found_node->data.RNTI);

    delete_pdu_by_rnti(&my_pool, 1001);

    monitor_resources();

    pthread_mutex_destroy(&my_pool.lock);
    return 0;
}
