    if (index >= list->size) return (NFAPI_CRC_INDICATION_PDU_T){0};  // Return a default structure

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T element = list->array[index];
    pthread_mutex_unlock(&list->lock);

    return element;
}

// Clean up the list
void free_list(CRC_Indication_List *list) {
    if (list->array) {
        free(list->array);
    }
