```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define structures as per LTE_PHY_RX_USER_DATA_T specifications.
typedef struct {
    int valid;
} RX_UE_INFORMATION_TAG;

typedef unsigned int RNTI;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} LTE_PHY_RX_USER_DATA_T;

// Define a node for the dynamic array.
typedef struct Node {
    LTE_PHY_RX_USER_DATA_T data;
    struct Node* next;
} Node;

// Dynamic Array structure
typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock; // Mutex for concurrency control
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array();
void destroy_dynamic_array(DynamicArray* array);
int append_to_dynamic_array(DynamicArray* array, LTE_PHY_RX_USER_DATA_T data);
LTE_PHY_RX_USER_DATA_T* get_by_rnti(DynamicArray* array, RNTI rnti);
int remove_by_rnti(DynamicArray* array, RNTI rnti);
void log_operation(const char* operation, RNTI rnti);
int serialize_array(const DynamicArray* array, const char* filename);
DynamicArray* deserialize_array(const char* filename);

// Function implementations
DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int append_to_dynamic_array(DynamicArray* array, LTE_PHY_RX_USER_DATA_T data) {
    pthread_mutex_lock(&array->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = data;
    new_node->next = array->head;
    array->head = new_node;
    array->size++;

    log_operation("append", data.rnti);
    pthread_mutex_unlock(&array->lock);
    return 0;
}

LTE_PHY_RX_USER_DATA_T* get_by_rnti(DynamicArray* array, RNTI rnti) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current) {
        if (current->data.rnti == rnti) {
            pthread_mutex_unlock(&array->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return NULL; // Not found
}

int remove_by_rnti(DynamicArray* array, RNTI rnti) {
    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;
    while (current) {
        if (current->data.rnti == rnti) {
            if (prev) prev->next = current->next;
            else array->head = current->next;

            free(current);
            array->size--;

            log_operation("remove", rnti);
            pthread_mutex_unlock(&array->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Not found
}

void log_operation(const char* operation, RNTI rnti) {
    printf("Operation: %s, RNTI: %u\n", operation, rnti);
}

int serialize_array(const DynamicArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    Node* current = array->head;
    while (current) {
        fwrite(&current->data, sizeof(LTE_PHY_RX_USER_DATA_T), 1, file);
        current = current->next;
    }

    fclose(file);
    return 0;
}

DynamicArray* deserialize_array(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    DynamicArray* array = create_dynamic_array();
    if (!array) {
        fclose(file);
        return NULL;
    }

    LTE_PHY_RX_USER_DATA_T data;
    while (fread(&data, sizeof(LTE_PHY_RX_USER_DATA_T), 1, file)) {
        append_to_dynamic_array(array, data);
    }

    fclose(file);
    return array;
}

// Helper function to set CRCFLAG randomly
void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    srand(time(NULL));
    tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}
