#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <syslog.h>
#include <stdbool.h>

#define MAX_ARRAY_SIZE 1000
#define COMPRESSION_LEVEL Z_BEST_COMPRESSION

typedef struct {
    int rnti;
    char *data; // Assume data is a compressed byte array
    unsigned long size;
} LTE_PHY_RX_USER_DATA_T;

typedef struct {
    LTE_PHY_RX_USER_DATA_T *array[MAX_ARRAY_SIZE];
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *dynArray = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dynArray) return NULL;

    dynArray->count = 0;
    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        dynArray->array[i] = NULL;
    }
    pthread_mutex_init(&dynArray->lock, NULL);
    syslog(LOG_INFO, "Dynamic array created.");
    return dynArray;
}

void free_dynamic_array(DynamicArray *dynArray) {
    if (!dynArray) return;

    pthread_mutex_lock(&dynArray->lock);
    for (size_t i = 0; i < dynArray->count; i++) {
        free(dynArray->array[i]->data);
        free(dynArray->array[i]);
    }
    pthread_mutex_unlock(&dynArray->lock);

    pthread_mutex_destroy(&dynArray->lock);
    free(dynArray);
    syslog(LOG_INFO, "Dynamic array destroyed.");
}

bool append_element(DynamicArray *dynArray, LTE_PHY_RX_USER_DATA_T *element) {
    if (!dynArray || dynArray->count >= MAX_ARRAY_SIZE)
        return false;

    pthread_mutex_lock(&dynArray->lock);

    int index = (int)(dynArray->count % MAX_ARRAY_SIZE);
    dynArray->array[index] = element;
    dynArray->count++;

    pthread_mutex_unlock(&dynArray->lock);
    syslog(LOG_INFO, "Element appended. Current count: %zu", dynArray->count);
    return true;
}

LTE_PHY_RX_USER_DATA_T* get_element_by_rnti(DynamicArray *dynArray, int rnti) {
    if (!dynArray) return NULL;

    pthread_mutex_lock(&dynArray->lock);

    for (size_t i = 0; i < dynArray->count; i++) {
        if (dynArray->array[i] && dynArray->array[i]->rnti == rnti) {
            pthread_mutex_unlock(&dynArray->lock);
            syslog(LOG_INFO, "Element retrieved by RNTI: %d", rnti);
            return dynArray->array[i];
        }
    }

    pthread_mutex_unlock(&dynArray->lock);
    syslog(LOG_WARNING, "Element not found for RNTI: %d", rnti);
    return NULL;
}

bool remove_element_by_rnti(DynamicArray *dynArray, int rnti) {
    if (!dynArray) return false;

    pthread_mutex_lock(&dynArray->lock);

    bool removed = false;
    for (size_t i = 0; i < dynArray->count; i++) {
        if (dynArray->array[i] && dynArray->array[i]->rnti == rnti) {
            free(dynArray->array[i]->data);
            free(dynArray->array[i]);
            dynArray->array[i] = NULL;

            // Shift elements
            for (size_t j = i; j < dynArray->count - 1; j++) {
                dynArray->array[j] = dynArray->array[j + 1];
            }
            dynArray->array[dynArray->count - 1] = NULL;
            dynArray->count--;

            removed = true;
            break;
        }
    }

    pthread_mutex_unlock(&dynArray->lock);
    if (removed) {
        syslog(LOG_INFO, "Element removed by RNTI: %d", rnti);
    } else {
        syslog(LOG_WARNING, "Element not found for removal with RNTI: %d", rnti);
    }
    return removed;
}

bool compress_data(char *inputData, unsigned long inputSize, char **outputData, unsigned long *outputSize) {
    uLongf compressedSize = compressBound(inputSize);

    *outputData = (char *)malloc(compressedSize);
    if (!*outputData)
        return false;

    int result = compress2((Bytef *)(*outputData), &compressedSize, (const Bytef *)inputData, inputSize, COMPRESSION_LEVEL);
    if (result != Z_OK) {
        free(*outputData);
        *outputData = NULL;
        return false;
    }

    *outputSize = compressedSize;
    return true;
}

bool decompress_data(char *compressedData, unsigned long compressedSize, char **decompressedData, unsigned long originalSize) {
    *decompressedData = (char *)malloc(originalSize);
    if (!*decompressedData)
        return false;

    int result = uncompress((Bytef *)(*decompressedData), &originalSize, (const Bytef *)compressedData, compressedSize);
    if (result != Z_OK) {
        free(*decompressedData);
        *decompressedData = NULL;
        return false;
    }

    return true;
}

int main() {
    openlog("lte_phy_rx", LOG_PID | LOG_CONS, LOG_USER);

    DynamicArray *dynArray = create_dynamic_array();

    // Example usage
    LTE_PHY_RX_USER_DATA_T *element = (LTE_PHY_RX_USER_DATA_T *)malloc(sizeof(LTE_PHY_RX_USER_DATA_T));
    element->rnti = 12345;

    char data[] = "Example Data";
    char *compressedData;
    unsigned long compressedSize;

    if (compress_data(data, sizeof(data), &compressedData, &compressedSize)) {
        element->data = compressedData;
        element->size = compressedSize;
        append_element(dynArray, element);
    }

    LTE_PHY_RX_USER_DATA_T *retrievedElement = get_element_by_rnti(dynArray, 12345);
    if (retrievedElement) {
        char *decompressedData;
        if (decompress_data(retrievedElement->data, retrievedElement->size, &decompressedData, sizeof(data))) {
            printf("Decompressed Data: %s\n", decompressedData);
            free(decompressedData);
        }
    }

    remove_element_by_rnti(dynArray, 12345);

    free_dynamic_array(dynArray);
    closelog();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread-safe operations.
- **Compression**: Uses zlib for data compression and decompression with a configurable level.
- **Logging**: Integrates syslog for logging purposes, providing both low-level and high-level logs.
- **Memory Management**: Handles dynamic memory allocation and deallocation carefully to prevent leaks.
- **Real-time Operations**: Ensures operations are efficient enough for real-time constraints by minimizing locking duration.

This code provides a foundation that can be expanded with additional features such as more sophisticated compression algorithms or enhanced logging mechanisms.']

