#define MAX_ENTRIES 1024

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList list = {NULL, PTHREAD_MUTEX_INITIALIZER};
unsigned int active_rntis[MAX_ENTRIES];
int rnti_count = 0;

// Function to retrieve UE information from an external source (stub)
void fetch_ue_information(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate fetching and setting data
    pdu->RX_UE_INFORMATION_TAG = rand();  // Example value
    pdu->CRCFLAG = rand() % 2;
}

// Check if RNTI is unique in the list
int is_unique_rnti(unsigned int rnti) {
    for (int i = 0; i < rnti_count; ++i) {
        if (active_rntis[i] == rnti) {
            return 0;
        }
    }
    return 1;
}

// Add a new entry to the list
int add_entry(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list.lock);

    if (rnti_count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list.lock);
        return -1; // List is full
    }

    if (!is_unique_rnti(pdu->RNTI)) {
        pthread_mutex_unlock(&list.lock);
        return -2; // RNTI not unique
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list.lock);
        return -3; // Memory allocation failed
    }

    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list.head;
    list.head = new_node;

    active_rntis[rnti_count++] = pdu->RNTI;

    pthread_mutex_unlock(&list.lock);
    return 0; // Success
}

// Function to manage the list of CRC indications
int manage_crc_indication_list(void) {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    fetch_ue_information(&pdu);

    int result = add_entry(&pdu);
    if (result != 0) {
        fprintf(stderr, "Error adding entry: %d\n", result);
        return -1; // Handle error appropriately
    }

    return 0;
}

// Example usage in a multi-threaded environment
void* process_crc_indications(void* arg) {
    while (1) {
        manage_crc_indication_list();
    }
    return NULL;
}

int main() {
    pthread_t threads[4];

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, process_crc_indications, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
