        pdus[i].RX_UE_INFORMATION_TAG = rand(); // Random tag
        do {
            pdus[i].RNTI = rand() % MAX_N;
        } while (rnti_set[pdus[i].RNTI] || rnti_set[pdus[i].RNTI] == 0); // Ensure uniqueness

