### C Code for LTE UE Context Management

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_FRAMES 100

typedef struct {
    int rnti;
    // Add additional CRC_INDICATION_REL8_TAG fields as needed
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int cellId;
    int frequencyBand;
    NFAPI_CRC_INDICATION_PDU_T* frames[MAX_FRAMES];
    size_t frameCount;
} LTE_DL_FRAME;

typedef struct {
    int uniqueCellID;
    int frequencyBand;
    LTE_DL_FRAME ueFrames[MAX_FRAMES];
    size_t frameCount;
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context* contexts;
    size_t contextCount;
    pthread_mutex_t lock;
    size_t totalFrames;
} ContextManager;

// Function prototypes
ContextManager* initializeContextManager();
void insertFrame(ContextManager* manager, int ueIndex, LTE_DL_FRAME frame);
void deleteFrame(ContextManager* manager, int ueIndex, int frameIndex);
LTE_DL_FRAME* retrieveFrame(ContextManager* manager, int ueIndex, int frameIndex);
void resetTotalFrames(ContextManager* manager);
int updateFrequencyBandAndCellID(int cellId, int frequencyBand);

ContextManager* initializeContextManager() {
    ContextManager* manager = (ContextManager*)malloc(sizeof(ContextManager));
    if (!manager) {
        perror("Failed to allocate memory for ContextManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->contexts = NULL;
    manager->contextCount = 0;
    manager->totalFrames = 0;

    // Setup and logging would be added here

    return manager;
}

void insertFrame(ContextManager* manager, int ueIndex, LTE_DL_FRAME frame) {
    pthread_mutex_lock(&manager->lock);

    if (ueIndex < 0 || ueIndex >= manager->contextCount) {
        fprintf(stderr, "Invalid UE index: %d\n", ueIndex);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    LTE_UE_Context* context = &manager->contexts[ueIndex];
    if (context->frameCount < MAX_FRAMES) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T");
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        // Initialize PDU fields
        pdu->rnti = rand(); // Example initialization
        pdu->crcflag = (rand() % 2); // Random CRCFLAG

        context->ueFrames[context->frameCount++] = frame;
        manager->totalFrames++;
    } else {
        fprintf(stderr, "Maximum frames reached for UE index: %d\n", ueIndex);
    }

    pthread_mutex_unlock(&manager->lock);
}

void deleteFrame(ContextManager* manager, int ueIndex, int frameIndex) {
    pthread_mutex_lock(&manager->lock);

    if (ueIndex < 0 || ueIndex >= manager->contextCount || frameIndex < 0 || frameIndex >= MAX_FRAMES) {
        fprintf(stderr, "Invalid indices: UE %d Frame %d\n", ueIndex, frameIndex);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    LTE_UE_Context* context = &manager->contexts[ueIndex];
    if (frameIndex < context->frameCount) {
        free(context->ueFrames[frameIndex].frames[context->ueFrames[frameIndex].frameCount - 1]);
        context->frameCount--;
        manager->totalFrames--;

        // Shift remaining frames
        for (size_t i = frameIndex; i < context->frameCount; ++i) {
