#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure
typedef struct {
    int CI; // Cell Identity
    int BWP_Configuration;
    char *DCI_Buffer; 
} LTE_ENBCONFIG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging framework placeholder
void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void init_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu);
int add_enbconfig_entry(LTE_ENBCONFIG_T **enbconfigs, int *size, LTE_ENBCONFIG_T entry);
int update_enbconfig_entry(LTE_ENBCONFIG_T *enbconfigs, int size, int CI, LTE_ENBCONFIG_T updatedEntry);
int remove_enbconfig_entry(LTE_ENBCONFIG_T **enbconfigs, int *size, int CI);

// Initialize CRC Indication PDU
void init_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand();  // Example tag generation
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG: 0 or 1
}

// Add entry to the array of LTE_ENBCONFIG_T structures
int add_enbconfig_entry(LTE_ENBCONFIG_T **enbconfigs, int *size, LTE_ENBCONFIG_T entry) {
    pthread_mutex_lock(&mutex);

    if (!enbconfigs || !entry.DCI_Buffer) {
        log_error("Invalid arguments for adding ENB config entry.");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    *enbconfigs = realloc(*enbconfigs, (*size + 1) * sizeof(LTE_ENBCONFIG_T));
    if (!*enbconfigs) {
        log_error("Memory allocation failed for adding ENB config entry.");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    (*enbconfigs)[*size] = entry;
    (*size)++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Update an existing entry
int update_enbconfig_entry(LTE_ENBCONFIG_T *enbconfigs, int size, int CI, LTE_ENBCONFIG_T updatedEntry) {
    pthread_mutex_lock(&mutex);

    if (!enbconfigs || !updatedEntry.DCI_Buffer) {
        log_error("Invalid arguments for updating ENB config entry.");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        if (enbconfigs[i].CI == CI) {
            enbconfigs[i] = updatedEntry;
            // Free old DCI buffer and allocate new one
            free(enbconfigs[i].DCI_Buffer);
            enbconfigs[i].DCI_Buffer = malloc(strlen(updatedEntry.DCI_Buffer) + 1);
            if (!enbconfigs[i].DCI_Buffer) {
                log_error("Memory allocation failed during ENB config update.");
                pthread_mutex_unlock(&mutex);
                return -1;
            }
            strcpy(enbconfigs[i].DCI_Buffer, updatedEntry.DCI_Buffer);
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    log_error("ENB config entry with specified CI not found.");
    pthread_mutex_unlock(&mutex);
    return -1;
}

// Remove an entry
int remove_enbconfig_entry(LTE_ENBCONFIG_T **enbconfigs, int *size, int CI) {
    pthread_mutex_lock(&mutex);

    if (!*enbconfigs || !size) {
        log_error("Invalid arguments for removing ENB config entry.");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < *size; i++) {
        if ((*enbconfigs)[i].CI == CI) {
            free((*enbconfigs)[i].DCI_Buffer); // Free the DCI buffer
            memmove(&(*enbconfigs)[i], &(*enbconfigs)[i + 1], (*size - i - 1) * sizeof(LTE_ENBCONFIG_T));
            *size -= 1;
            *enbconfigs = realloc(*enbconfigs, *size * sizeof(LTE_ENBCONFIG_T)); // Shrink the array
            if (!*enbconfigs && *size > 0) {
                log_error("Memory deallocation failed during ENB config removal.");
                pthread_mutex_unlock(&mutex);
                return -1;
            }
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    log_error("ENB config entry with specified CI not found for removal.");
    pthread_mutex_unlock(&mutex);
    return -1;
}

// Example usage
int main() {
    LTE_ENBCONFIG_T *enbconfigs = NULL;
    int size = 0;

    // Initialize CRC Indication PDU
    NFAPI_CRC_INDICATION_PDU_T pdu;
    init_crc_indication_pdu(&pdu);

    // Add an entry
    LTE_ENBCONFIG_T entry = {1, 100, strdup("DCI Data")};
    add_enbconfig_entry(&enbconfigs, &size, entry);

    // Update an entry
    LTE_ENBCONFIG_T updatedEntry = {1, 200, strdup("Updated DCI Data")};
    update_enbconfig_entry(enbconfigs, size, 1, updatedEntry);

    // Remove an entry
    remove_enbconfig_entry(&enbconfigs, &size, 1);

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(enbconfigs[i].DCI_Buffer);
    }
    free(enbconfigs);

    return 0;
}
```

