    if (!ip || strlen(ip) >= MAX_IP_LENGTH) return -1;

    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->stats.ip_address, ip) == 0) {
            // Update existing entry
            current->stats.port = port;
            current->stats.latency = latency;
            return 0;
        }
        current = current->next;
