#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

// Assuming these are defined elsewhere in your system.
typedef struct {
    // ... (RX_UE_INFORMATION_TAG fields)
} RX_UE_INFORMATION_TAG;

typedef uint16_t RNTI;
typedef struct {
    int CRCFLAG;  // Example field
    // Other CRC_INDICATION_REL8_TAG fields...
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp; // For garbage collection
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_rwlock_t lock;
    size_t max_size;
    size_t current_size;
    void (*memory_pool_alloc)(void** ptr, size_t size);
    void (*memory_pool_free)(void* ptr);
} NF_LIST_MANAGER;

// Function prototypes
void* garbage_collector_thread(void* arg);
int insert_pdu(NF_LIST_MANAGER* manager, RX_UE_INFORMATION_TAG* ue_info_tag, RNTI rnti, int crcflag);
int remove_stale_pdus(NF_LIST_MANAGER* manager);

// Garbage collector thread
void* garbage_collector_thread(void* arg) {
    NF_LIST_MANAGER* manager = (NF_LIST_MANAGER*)arg;
    const time_t interval = 60; // Interval in seconds for garbage collection

    while (1) {
        sleep(interval);
        if (!remove_stale_pdus(manager)) {
            fprintf(stderr, "Failed to perform garbage collection\n");
        }
    }

    return NULL;
}

// Insert a new PDU into the list
int insert_pdu(NF_LIST_MANAGER* manager, RX_UE_INFORMATION_TAG* ue_info_tag, RNTI rnti, int crcflag) {
    if (manager->current_size >= manager->max_size) {
        fprintf(stderr, "Memory budget exceeded\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pdu = NULL;
    manager->memory_pool_alloc((void**)&new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        fprintf(stderr, "Failed to allocate memory for PDU\n");
        return -1;
    }

    memcpy(&new_pdu->ue_info_tag, ue_info_tag, sizeof(RX_UE_INFORMATION_TAG));
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag.CRCFLAG = crcflag;
    time(&new_pdu->timestamp);
    new_pdu->next = NULL;

    pthread_rwlock_wrlock(&manager->lock);

    if (manager->head == NULL) {
        manager->head = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_pdu;
    }

    manager->current_size++;
    pthread_rwlock_unlock(&manager->lock);

    return 0;
}

// Remove stale PDUs from the list
int remove_stale_pdus(NF_LIST_MANAGER* manager) {
    time_t now = time(NULL);
    const time_t max_age = 120; // Max age in seconds for a PDU to be considered stale

    pthread_rwlock_wrlock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = manager->head, *prev = NULL;
    while (current != NULL) {
        if (difftime(now, current->timestamp) > max_age) {
            if (prev == NULL) { // Removing the head
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }

            manager->memory_pool_free(current);
            manager->current_size--;
            current = manager->head ? manager->head : NULL; // Restart if needed
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&manager->lock);

    return 0;
}

// Initialize the NF_LIST_MANAGER
void init_nf_list_manager(NF_LIST_MANAGER* manager, size_t max_size,
                          void (*memory_pool_alloc)(void** ptr, size_t size),
                          void (*memory_pool_free)(void* ptr)) {
    pthread_rwlock_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->max_size = max_size;
    manager->current_size = 0;
    manager->memory_pool_alloc = memory_pool_alloc;
    manager->memory_pool_free = memory_pool_free;

    pthread_t gc_thread_id;
    if (pthread_create(&gc_thread_id, NULL, garbage_collector_thread, manager) != 0) {
        fprintf(stderr, "Failed to create garbage collector thread\n");
        exit(1);
    }
}
```

This code includes a function `insert_pdu` for inserting new PDUs into the list and a separate garbage collection thread that periodically removes stale entries. The garbage collector runs independently of other operations on the linked list. Remember to define appropriate functions for memory allocation (`memory_pool_alloc`) and deallocation (`memory_pool_free`) to integrate with your existing memory pool system.

**Note:** This example assumes you have some way to allocate and free from a memory pool, as specified by `manager->memory_pool_alloc` and `manager->memory_pool_free`. You should replace these functions with actual implementations that work with your specific memory management strategy. Additionally, make sure that the logging (using `fprintf(stderr, ...)`) is replaced or integrated into your system's error handling mechanisms.

The garbage collection interval (`interval`) and maximum age for a PDU before it is considered stale (`max_age`) are configurable parameters that you will need to adjust based on your application's requirements and performance considerations.']

