// Constants for error handling
#define ALLOCATION_ERROR -1
#define SUCCESS 0

typedef struct {
    int portID;
    char tcpState[10];
    time_t timestamp;
} CIR;

typedef struct ConnectionInfoRecordNode {
    CIR cir;
    struct ConnectionInfoRecordNode *next;
} CIRNode;

typedef struct {
    unsigned char macAddress[6]; // Assuming MAC addresses are 6 bytes
    int ipConfigTag;
    CIRNode *cirListHead; // Head of the linked list of CIRs
} NICB;

// Function prototypes
NICB* createNICB(unsigned char *mac, int ipConfigTag);
int addCIR(NICB *nicb, int portID, const char *tcpState);
void removeCIR(NICB *nicb, int portID);
void freeNICB(NICB *nicb);

// Function to initialize and create a NICB
NICB* createNICB(unsigned char *mac, int ipConfigTag) {
    if (!mac) return NULL;

    NICB *nicb = (NICB*)malloc(sizeof(NICB));
    if (!nicb) return NULL;

    memcpy(nicb->macAddress, mac, 6);
    nicb->ipConfigTag = ipConfigTag;
    nicb->cirListHead = NULL;

    return nicb;
}

// Function to add a CIR
int addCIR(NICB *nicb, int portID, const char *tcpState) {
    if (!nicb || !tcpState) return ALLOCATION_ERROR;

    CIRNode *newNode = (CIRNode*)malloc(sizeof(CIRNode));
    if (!newNode) return ALLOCATION_ERROR;

    newNode->cir.portID = portID;
    strncpy(newNode->cir.tcpState, tcpState, sizeof(newNode->cir.tcpState) - 1);
    newNode->cir.tcpState[sizeof(newNode->cir.tcpState) - 1] = '\0';
    newNode->cir.timestamp = time(NULL);

    newNode->next = nicb->cirListHead;
    nicb->cirListHead = newNode;

    return SUCCESS;
}

// Function to remove a CIR
void removeCIR(NICB *nicb, int portID) {
    if (!nicb) return;

    CIRNode **current = &nicb->cirListHead;
    while (*current) {
        CIRNode *entry = *current;
        if (entry->cir.portID == portID) {
            *current = entry->next;
            free(entry);
            return;
        }
        current = &(*current)->next;
    }
}

// Function to free a NICB and its associated memory
void freeNICB(NICB *nicb) {
    if (!nicb) return;

    CIRNode *current = nicb->cirListHead;
    while (current) {
        CIRNode *temp = current;
        current = current->next;
        free(temp);
    }

    free(nicb);
}
