CRCList* crc_list_create() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->current_usage = 0;
    list->peak_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void crc_list_destroy(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pduA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pduB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return (pduA->RNTI > pduB->RNTI) - (pduA->RNTI < pduB->RNTI);
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement validation logic here
    return 1; // Assume valid for now
}

void crc_list_insert(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!is_valid(pdu)) return;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current && ((*current)->data.RNTI < pdu->RNTI)) {
        current = &(*current)->next;
    }

    // Check for duplicate RNTI
    if (*current && (*current)->data.RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = *pdu;
    new_node->next = *current;

    *current = new_node;
    list->current_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (list->current_usage > list->peak_usage) {
        list->peak_usage = list->current_usage;
    }

    pthread_mutex_unlock(&list->lock);
}

void crc_list_remove(CRCList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current && (*current)->data.RNTI != rnti) {
        current = &(*current)->next;
    }

    if (*current) {
        Node* to_delete = *current;
        *current = to_delete->next;
        free(to_delete);
        list->current_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock(&list->lock);
}

void crc_list_sort(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || !list->head->next) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node** array = (Node**)malloc(list->current_usage);
    size_t count = 0;

    for (Node* current = list->head; current; current = current->next, ++count) {
        array[count] = current;
    }

    qsort(array, count, sizeof(Node*), (int(*)(const void*, const void*))compare_rnti);

    for (size_t i = 0; i < count - 1; ++i) {
        array[i]->next = array[i + 1];
    }
    array[count - 1]->next = NULL;

    list->head = array[0];
    free(array);

    pthread_mutex_unlock(&list->lock);
}

void crc_list_report_usage(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    printf("Current Usage: %zu bytes\n", list->current_usage);
    printf("Peak Usage: %zu bytes\n", list->peak_usage);

    pthread_mutex_unlock(&list->lock);
}
