// Function to add a new entry
int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // RNTI not unique
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = pdu;
    time(&new_node->timestamp);
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to sort the list based on RNTI
void sort_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || !list->head->next) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node *i, *j;
    for (i = list->head; i != NULL; i = i->next) {
        for (j = i->next; j != NULL; j = j->next) {
            if (i->data.RNTI > j->data.RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = i->data;
                i->data = j->data;
                j->data = temp;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to purge old entries
void* purge_old_entries(void* arg) {
    CRCList* list = (CRCList*)arg;
    int purge_interval = 3600; // Example: 1 hour

    while (1) {
        sleep(purge_interval);

        pthread_mutex_lock(&list->lock);

        Node *current = list->head, *prev = NULL;
        time_t now;
        time(&now);

        while (current) {
            if (difftime(now, current->timestamp) > purge_interval) {
                if (prev) prev->next = current->next;
                else list->head = current->next;

                Node* temp = current;
                current = current->next;
                free(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
    }
}

// Function to initialize the CRCList
CRCList* init_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    pthread_create(&purge_thread, NULL, purge_old_entries, list);

    return list;
}

// Function to free the CRCList
void free_crc_list(CRCList* list) {
    Node* current = list->head;

    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    pthread_cancel(purge_thread);
}

int main() {
    CRCList* crc_list = init_crc_list();

    if (!crc_list) {
        fprintf(stderr, "Failed to initialize CRC list.\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu_example = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456 };
    pdu_example.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    int result = add_entry(crc_list, pdu_example);

    if (result != 0) {
        fprintf(stderr, "Failed to add entry: %d\n", result);
    }

    sort_list(crc_list);

    free_crc_list(crc_list);
    return 0;
}
