#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} List;

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

bool realloc_list(List* list) {
    size_t new_capacity = list->capacity * 2;
    if (new_capacity > MAX_ELEMENTS) return false;

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_error("Memory allocation failed during reallocation.");
        return false;
    }

    list->array = new_array;
    list->capacity = new_capacity;

    printf("List resized to capacity %zu.\n", list->capacity);
    return true;
}

bool add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity && !realloc_list(list)) {
        pthread_mutex_unlock(&list->lock);
        log_error("Failed to reallocate list.");
        return false;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->array[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            log_error("Duplicate RNTI encountered.");
            return false;
        }
    }

    list->array[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void initialize_list(List* list) {
    list->array = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        log_error("Memory allocation failed during initialization.");
        exit(EXIT_FAILURE);
    }

    list->size = 0;
    list->capacity = MAX_ELEMENTS;

    pthread_mutex_init(&list->lock, NULL);

    printf("List initialized with capacity %zu.\n", list->capacity);
}

void destroy_list(List* list) {
    free(list->array);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    List nfaPduList;
    initialize_list(&nfaPduList);

    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, 
                                          .RNTI = rand() % MAX_ELEMENTS + 1, 
                                          .CRC_INDICATION_REL8_TAG = { .CRCFLAG = (rand() % 2 == 0) } };
        if (!add_pdu(&nfaPduList, pdu)) {
            log_error("Failed to add PDU.");
        }
    }

    destroy_list(&nfaPduList);
    return 0;
}
