typedef struct Node {
    int key;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
} HashTable;

unsigned long hash(int RNTI, size_t cap) {
    return ((unsigned long)RNTI * 2654435761u) % cap;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    table->buckets = calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for buckets");
        return NULL;
    }
    table->capacity = capacity;
    return table;
}

void insert_hash_table(HashTable* table, int RNTI) {
    unsigned long index = hash(RNTI, table->capacity);
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->key = RNTI;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
}

int is_present(HashTable* table, int RNTI) {
    unsigned long index = hash(RNTI, table->capacity);
    Node* current = table->buckets[index];
    while (current) {
        if (current->key == RNTI) return 1;
        current = current->next;
    }
    return 0;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* head = table->buckets[i];
        while (head) {
            Node* temp = head;
            head = head->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

void log_message(const char* message) {
