    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

int validate_rnti_range(int minRNTI, int maxRNTI) {
    return (minRNTI > 0 && maxRNTI < MAX_RNTI && minRNTI <= maxRNTI);
}

void* create_pdu(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)arg;
    int rnti, count, i;
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    for (count = 0; count < 100; ++count) {
        if (pthread_mutex_lock(&mutex)) {
            perror("Mutex lock failed");
            return NULL;
        }

        do {
            rnti = rand() % (maxRNTI - minRNTI + 1) + minRNTI;
        } while (is_present(hash_table, rnti));

        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_message("Memory allocation failed for PDU");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        insert_hash_table(hash_table, rnti);
        pdu->RNTI = rnti;
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu->CRCFLAG = rand() % 2;

        (*pdus)[count] = pdu;

        log_message("Processed a structure");

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_pdus(size_t n, int minRNTI, int maxRNTI) {
    if (!validate_rnti_range(minRNTI, maxRNTI)) {
        log_message("Invalid RNTI range");
        return NULL;
    }

    srand(time(NULL));
    pthread_t threads[4];
    size_t chunk_size = n / 4;

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
        perror("Memory allocation failed for PDUs");
        return NULL;
    }

    hash_table = create_hash_table(MAX_RNTI);
    if (!hash_table) {
        free(pdus);
        log_message("Failed to create hash table");
        return NULL;
    }

    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < 4 && n > 0; ++i) {
        size_t start_index = i * chunk_size;
        if (start_index >= n) continue;

        size_t end_index = (i == 3) ? n : start_index + chunk_size;
        size_t num_pdus = end_index - start_index;

        NFAPI_CRC_INDICATION_PDU_T** pdu_chunk = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!pdu_chunk) {
            perror("Memory allocation failed for PDU chunk");
            free(pdus);
            free_hash_table(hash_table);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }

        if (pthread_create(&threads[i], NULL, create_pdu, (void*)pdu_chunk)) {
            perror("Failed to create thread");
            free(pdu_chunk);
            free(pdus);
            free_hash_table(hash_table);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
    }

    for (int i = 0; i < 4 && n > 0; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Failed to join thread");
            free(pdus);
            free_hash_table(hash_table);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }
    }

    pthread_mutex_destroy(&mutex);

    log_message("All structures processed successfully");

    return pdus;
}
