#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SAMPLES 20

typedef struct {
    int valid;
    unsigned long ue_id;
    float tx_power_level;
    float *rx_signal_strength; // dynamically allocated array for signal strengths
    size_t signal_count;
} NFAPI_MESSAGE_PDU_T;

typedef struct Node {
    NFAPI_MESSAGE_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} SignalList;

// Helper function to create a new node
Node* create_node(NFAPI_MESSAGE_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = new_node->prev = NULL;
    return new_node;
}

// Initialize the signal list
void init_signal_list(SignalList* list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Insert a new message into the list
void insert_message(SignalList* list, NFAPI_MESSAGE_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Delete a message by UE_ID
void delete_message(SignalList* list, unsigned long ue_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.ue_id == ue_id) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            if (current == list->head) list->head = current->next;
            if (current == list->tail) list->tail = current->prev;

            free(current->data.rx_signal_strength);
            free(current);

            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Retrieve a message by UE_ID
NFAPI_MESSAGE_PDU_T* get_message(SignalList* list, unsigned long ue_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.ue_id == ue_id) {
            NFAPI_MESSAGE_PDU_T* result = &current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Update signal strengths using a weighted moving average
void update_signal_strength(NFAPI_MESSAGE_PDU_T* message, float new_sample) {
    if (!message || !message->rx_signal_strength) return;

    // Shift existing samples left
    for (size_t i = 0; i < MAX_SAMPLES - 1; ++i) {
        message->rx_signal_strength[i] = message->rx_signal_strength[i + 1];
    }

    // Add new sample at the end
    message->rx_signal_strength[MAX_SAMPLES - 1] = new_sample;

    // Calculate weighted moving average
    float weight_sum = 0.0;
    float weighted_average = 0.0;
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        float weight = i + 1;
        weighted_average += message->rx_signal_strength[i] * weight;
        weight_sum += weight;
    }
    message->rx_signal_strength[MAX_SAMPLES - 1] = weighted_average / weight_sum;
}

// Export the list formatted for integration
void export_list(SignalList* list, FILE* output) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fprintf(output, "UE_ID: %lu, TX_POWER_LEVEL: %.2f, RX_SIGNAL_STRENGTH: ",
                current->data.ue_id, current->data.tx_power_level);
        for (size_t i = 0; i < MAX_SAMPLES; ++i) {
            if (i > 0) fprintf(output, " ");
            fprintf(output, "%.2f", current->data.rx_signal_strength[i]);
        }
        fprintf(output, "\n");
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup the signal list
void cleanup_signal_list(SignalList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.rx_signal_strength);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    SignalList list;
    init_signal_list(&list);

    // Example usage
    NFAPI_MESSAGE_PDU_T data1 = {1, 12345, -50.0, malloc(MAX_SAMPLES * sizeof(float)), MAX_SAMPLES};
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        data1.rx_signal_strength[i] = -70 + i;
    }
    insert_message(&list, data1);

    update_signal_strength(get_message(&list, 12345), -65.5);

    FILE* export_file = fopen("export.txt", "w");
    if (export_file) {
        export_list(&list, export_file);
        fclose(export_file);
    }

    cleanup_signal_list(&list);

    return 0;
}
```

