unsigned char* compute_md5_hash(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);
    return memcpy(malloc(MD5_DIGEST_LENGTH), digest, MD5_DIGEST_LENGTH);
