#include <pthread.h>

#define MAX_SIGNAL_SAMPLES 20

typedef struct {
    int UE_ID;
    int TX_POWER_LEVEL;
    float *RX_SIGNAL_STRENGTH; // Dynamically allocated array for signal strengths
    size_t rx_signal_count;
    pthread_mutex_t lock;
} NFAPI_MESSAGE_PDU_T;

typedef struct Node {
    NFAPI_MESSAGE_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;
} SignalList;

SignalList* create_signal_list() {
    SignalList* list = malloc(sizeof(SignalList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
    return list;
}

void destroy_signal_list(SignalList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.RX_SIGNAL_STRENGTH);
        pthread_mutex_destroy(&current->data.lock);
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

void insert_message(SignalList* list, NFAPI_MESSAGE_PDU_T message) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = message;
    pthread_mutex_init(&new_node->data.lock, NULL);

    pthread_rwlock_wrlock(&list->rwlock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->rwlock);
}

void delete_message(SignalList* list, int UE_ID) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node *current = list->head, *prev = NULL;
    while (current && current->data.UE_ID != UE_ID) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->rwlock);
        return;
    }

    if (prev)
        prev->next = current->next;
    else
        list->head = current->next;

    free(current->data.RX_SIGNAL_STRENGTH);
    pthread_mutex_destroy(&current->data.lock);
    free(current);

    pthread_rwlock_unlock(&list->rwlock);
}

NFAPI_MESSAGE_PDU_T* retrieve_message(SignalList* list, int UE_ID) {
    pthread_rwlock_rdlock(&list->rwlock);

    Node *current = list->head;
    while (current && current->data.UE_ID != UE_ID)
        current = current->next;

    NFAPI_MESSAGE_PDU_T* message = NULL;
    if (current) {
        pthread_mutex_lock(&current->data.lock);
        message = &current->data;
        pthread_mutex_unlock(&current->data.lock);
    }

    pthread_rwlock_unlock(&list->rwlock);
    return message;
}

void update_signal_strength(NFAPI_MESSAGE_PDU_T* pdu, float new_signal) {
    if (!pdu || !pdu->RX_SIGNAL_STRENGTH) return;

    pthread_mutex_lock(&pdu->lock);

    // Remove oldest signal strength and add the new one
    float *new_array = realloc(pdu->RX_SIGNAL_STRENGTH, (pdu->rx_signal_count % MAX_SIGNAL_SAMPLES + 1) * sizeof(float));
    if (!new_array) {
        pthread_mutex_unlock(&pdu->lock);
        return;
    }
    pdu->RX_SIGNAL_STRENGTH = new_array;

    // Shift existing samples
    for (size_t i = pdu->rx_signal_count % MAX_SIGNAL_SAMPLES; i > 0; --i)
        pdu->RX_SIGNAL_STRENGTH[i] = pdu->RX_SIGNAL_STRENGTH[i - 1];

    pdu->RX_SIGNAL_STRENGTH[0] = new_signal;
    if (pdu->rx_signal_count < MAX_SIGNAL_SAMPLES) {
        ++(pdu->rx_signal_count);
    }

    // Calculate weighted moving average
    float sum = 0.0, weight = 1.0;
    for (size_t i = 0; i < pdu->rx_signal_count % MAX_SIGNAL_SAMPLES; ++i) {
        sum += pdu->RX_SIGNAL_STRENGTH[i] * weight;
        weight *= 0.9; // Weight decrease factor
    }

    float average = sum / ((1 - pow(0.9, pdu->rx_signal_count)) / (1 - 0.9));
    printf("Updated RX Signal Strength: %.2f\n", average);

    pthread_mutex_unlock(&pdu->lock);
}

void initialize_lte_frames(size_t frame_span) {
    LTE_DL_FRAMEINFO* frames = malloc(frame_span * sizeof(LTE_DL_FRAMEINFO));
    if (!frames) return;

    for (size_t i = 0; i < frame_span; ++i) {
        frames[i].frame_num = i;
        frames[i].subframe_num = i % 10;
        frames[i].frame_type = (i % 2 == 0) ? 'T' : 'S';
    }

    // Implement probabilistic srs_info population
    for (size_t i = 0; i < frame_span; ++i) {
        if ((rand() / (float)RAND_MAX) > 0.1) { // 10% chance to populate SRS info
            frames[i].srs_info_present = 1;
            frames[i].srs_bandwidth_configuration = rand() % 3 + 1; // Example config range
        }
    }

    // Verify frame information
    for (size_t i = 0; i < frame_span; ++i) {
        if (frames[i].frame_num >= frame_span || frames[i].subframe_num > 9) {
            fprintf(stderr, "Frame info verification failed at index %zu\n", i);
        }
    }

    free(frames); // Assuming cleanup post-verification
}

int main() {
    SignalList* list = create_signal_list();
    NFAPI_MESSAGE_PDU_T pdu = {123, 20, malloc(sizeof(float) * MAX_SIGNAL_SAMPLES), 0};
    pthread_mutex_init(&pdu.lock, NULL);

    insert_message(list, pdu);
    update_signal_strength(&list->head->data, -70.5);

    initialize_lte_frames(100);

    NFAPI_MESSAGE_PDU_T* retrieved = retrieve_message(list, 123);
    if (retrieved) {
        printf("Retrieved UE_ID: %d\n", retrieved->UE_ID);
    }

    destroy_signal_list(list);
    return 0;
}
