#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETRIES 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    // Other fields can be added here
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for synchronizing access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random RNTI, avoiding duplicates
uint16_t generate_unique_rnti(uint16_t *existing_rntis, size_t count) {
    uint16_t rnti;
    do {
        rnti = rand() % 65536; // Assuming RNTI is 16-bit
    } while (check_duplicate(rnti, existing_rntis, count));
    return rnti;
}

// Function to check if an RNTI already exists in the list
int check_duplicate(uint16_t rnti, uint16_t *existing_rntis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (existing_rntis[i] == rnti) {
            return 1;
        }
    }
    return 0;
}

// Function to create and populate the list
NFAPI_CRC_INDICATION_PDU_T **create_nfa_list(size_t num_elements, size_t *retry_count) {
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    uint16_t *rntis = malloc(num_elements * sizeof(uint16_t));
    if (!list || !rntis) {
        perror("Failed to allocate memory");
        free(list);
        free(rntis);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    int retries = 0;

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Failed to allocate memory");
            // Free previously allocated resources
            for (size_t j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(list);
            free(rntis);
            return NULL;
        }

        pthread_mutex_lock(&mutex); // Ensure thread safety

        int success = 0;
        while (!success && retries < MAX_RETRIES) {
            pdu->crcTag.RX_UE_INFORMATION_TAG = rand(); // Random value
            pdu->crcTag.RNTI = generate_unique_rnti(rntis, i);
            pdu->crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            if (!check_duplicate(pdu->crcTag.RNTI, rntis, i)) {
                success = 1;
                list[i] = pdu;
                rntis[i] = pdu->crcTag.RNTI;
            } else {
                retries++;
            }
        }

        pthread_mutex_unlock(&mutex);

        if (!success) {
            free(pdu);
            // Free previously allocated resources
            for (size_t j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(list);
            free(rntis);
            *retry_count = retries;
            return NULL;
        }
    }

    *retry_count = retries;
    free(rntis); // No longer needed
    return list;
}

// Function to clean up the allocated list
void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        if (list[i]) {
            free(list[i]);
        }
    }
    free(list);
}
