#define SUCCESS 0
void* persistent_storage_open(const char* path, int flags) { return NULL; }
int persistent_storage_write(void* storage, const void* data, size_t size) { return SUCCESS; }
void persistent_storage_close(void* storage) {}

typedef struct {
    unsigned long rnti;
    // Add additional fields for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned long rnti;
    int error_status;
} NFAPI_MESSAGE_T;

typedef struct Node {
    NFAPI_MESSAGE_T message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MessageList;

MessageList* init_message_list() {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_message(MessageList* list, const NFAPI_MESSAGE_T* message) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    pthread_mutex_lock(&list->lock);
    memcpy(&new_node->message, message, sizeof(NFAPI_MESSAGE_T));
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

void* flush_to_persistent_storage(void* arg) {
    MessageList* list = (MessageList*)arg;
    void* storage = persistent_storage_open("storage_path", 0);
    if (!storage) return NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current) {
        int result = persistent_storage_write(storage, &current->message, sizeof(NFAPI_MESSAGE_T));
        if (result != SUCCESS) {
            // Handle write error
        }
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;  // Clear the list after flushing
    pthread_mutex_unlock(&list->lock);

    persistent_storage_close(storage);
    return NULL;
}

void start_flushing_periodically(MessageList* list, int interval_sec) {
    while (1) {
        flush_to_persistent_storage(list);
        sleep(interval_sec);
    }
}

// Call this function in a separate thread
void begin_periodic_flushing(MessageList* list, int interval_sec) {
    pthread_t flush_thread;
    if (pthread_create(&flush_thread, NULL, (void*)start_flushing_periodically, list)) {
        // Handle error
    }
    pthread_detach(flush_thread);  // Detach to allow it to run independently
}

int main() {
    MessageList* message_list = init_message_list();
    if (!message_list) return -1;

    NFAPI_MESSAGE_T new_message;
    new_message.ue_info_tag.rnti = 12345; // Example value
    new_message.rnti = 54321; // Example value
    new_message.error_status = 0; // Example status

    add_message(message_list, &new_message);

    begin_periodic_flushing(message_list, 10);  // Flush every 10 seconds

    // The main thread can continue executing other tasks...

    pthread_mutex_destroy(&message_list->lock);
    free(message_list);
    return 0;
}
```

### Key Features:
