typedef struct {
    time_t Timestamp;
    int SourceID;
    char EventDetails[256];
} TrafficEvent;

typedef enum { ASCENDING, DESCENDING } SortOrder;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void swap(TrafficEvent *a, TrafficEvent *b) {
    TrafficEvent temp = *a;
    *a = *b;
    *b = temp;
}

int compareEvents(const void *a, const void *b, SortOrder order) {
    TrafficEvent *eventA = (TrafficEvent *)a;
    TrafficEvent *eventB = (TrafficEvent *)b;
    int result = eventA->Timestamp - eventB->Timestamp;

    return (order == ASCENDING) ? result : -result;
}

void sortEvents(TrafficEvent *events, size_t count, SortOrder order) {
    qsort_r(events, count, sizeof(TrafficEvent), compareEvents, (void *)(intptr_t)(long)order);
}

size_t filterBySourceID(TrafficEvent *events, size_t count, int sourceID, TrafficEvent **filteredEvents) {
    pthread_mutex_lock(&mutex);

    size_t filteredCount = 0;
    for (size_t i = 0; i < count; ++i) {
        if (events[i].SourceID == sourceID) {
            filteredCount++;
        }
    }

    *filteredEvents = malloc(filteredCount * sizeof(TrafficEvent));
    if (!*filteredEvents) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    size_t j = 0;
    for (size_t i = 0; i < count; ++i) {
        if (events[i].SourceID == sourceID) {
            (*filteredEvents)[j++] = events[i];
        }
    }

    pthread_mutex_unlock(&mutex);
    return filteredCount;
}

void updateEvent(TrafficEvent *events, size_t index, TrafficEvent newEvent) {
    pthread_mutex_lock(&mutex);

    if (index < count) {
        events[index] = newEvent;
    }

    pthread_mutex_unlock(&mutex);
}

TrafficEvent* initializeTrafficEvents(size_t numEvents, SortOrder sortOrder) {
    TrafficEvent *events = malloc(numEvents * sizeof(TrafficEvent));
    if (!events) {
        return NULL; // Handle memory allocation failure
    }

    // Assume user input is provided elsewhere to populate the events array
    // For demonstration purposes, we'll skip this step.

    sortEvents(events, numEvents, sortOrder);

    return events;
}

void freeTrafficEvents(TrafficEvent *events) {
    pthread_mutex_lock(&mutex);
    free(events);
    pthread_mutex_unlock(&mutex);
}

int main() {
    size_t numEvents = 100; // Example size
    TrafficEvent *trafficEvents = initializeTrafficEvents(numEvents, ASCENDING);

    if (trafficEvents) {
        int sourceIDToFilter = 5;
        TrafficEvent *filteredEvents;
        size_t filteredCount = filterBySourceID(trafficEvents, numEvents, sourceIDToFilter, &filteredEvents);

        // Example update
