#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct CRC_INDICATION_REL8_TAG {
    int crc;
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    unsigned long rnti;
    CRC_INDICATION_REL8_TAG *crcTags;
    size_t crcTagCount;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG informationTag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(size_t N) {
    if (N == 0) return NULL;

    pthread_mutex_lock(&listMutex);
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **current = &head;

    for (size_t i = 0; i < N; ++i) {
        *current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*current) {
            // Cleanup on failure
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        (*current)->informationTag.rnti = rand() % 1000000; // Random RNTI for example
        size_t crcCount = rand() % 10 + 1; // Example CRC count between 1 and 10

        (*current)->informationTag.crcTags = malloc(crcCount * sizeof(CRC_INDICATION_REL8_TAG));
        if (!(*current)->informationTag.crcTags) {
            free(*current);
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        for (size_t j = 0; j < crcCount; ++j) {
            (*current)->informationTag.crcTags[j].crc = rand() % 10000; // Random CRC value
        }

        (*current)->informationTag.crcTagCount = crcCount;
        current = &((*current)->next);
    }

    *current = NULL;
    pthread_mutex_unlock(&listMutex);
    return head;
}

void validate_rnti_consistency(NFAPI_CRC_INDICATION_PDU_T* list) {
