#include <stdio.h>
#include <stdlib.h>
import stdlib.h
import pthread.h

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI; // Range: 1 to 65535
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} List;

void initList(List *list, size_t initialSize) {
    list->array = malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->used = 0;
    list->size = initialSize;
    pthread_mutex_init(&list->lock, NULL);
}

void ensureCapacity(List *list) {
    size_t new_size = list->size * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(list->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->array = new_array;
    list->size = new_size;
}

void insertList(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (element.RNTI < 1 || element.RNTI > 65535) {
        fprintf(stderr, "Invalid RNTI value: %u\n", element.RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->used == list->size) {
        ensureCapacity(list);
    }
    list->array[list->used++] = element;

    pthread_mutex_unlock(&list->lock);
}

void freeList(List *list) {
    free(list->array);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    List list;
    initList(&list, 100);

    for (size_t i = 0; i < 10500; ++i) { // Simulate high load
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = rand();
        element.RNTI = rand() % 65535 + 1;
        element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

        insertList(&list, element);
    }

    freeList(&list);
    return 0;
}
```

### Explanation:

- **Initialization**: The `initList` function initializes a list with a given initial size and sets up mutex for thread safety.

- **Dynamic Resizing**: The `ensureCapacity` function doubles the list's capacity when it becomes full, using `realloc` to minimize fragmentation.

- **Insertion**: The `insertList` function ensures that each RNTI is valid before inserting. It locks the list during insertion to ensure thread safety.

- **Memory Management**: Uses `malloc`, `realloc`, and `free` for efficient memory management.

- **Thread Safety**: Utilizes a mutex (`pthread_mutex_t`) to protect concurrent access, ensuring safe multi-threaded operations. 

This approach balances performance, memory usage, and robustness in managing dynamically resizable lists.']

