void init_memory() {
    for (int i = 0; i < 100; ++i) { // Initialize with arbitrary size
        long_offset_values[i] = rand() % 100;
        int_keys[i] = rand() % MAX_BUFFER_SIZE + 1;
    }
}

Record* initialize_record_array(size_t size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
        records[i].buffer = malloc(int_keys[i]); // Allocate buffer based on int_key
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed for record buffer\n");
            exit(EXIT_FAILURE);
        }
    }

    return records;
}

void manage_records() {
    size_t total_int_value = 0;
    size_t total_buffer_size = 0;

    pthread_mutex_lock(&record_lock);

    if (total_int_value + rand() % 100 > MAX_TOTAL_INT_VALUE) { // Fallback strategy
        printf("Requested value exceeds limit, skipping allocation\n");
        pthread_mutex_unlock(&record_lock);
        return;
    }

    record_array = initialize_record_array(RECORD_ARRAY_INITIAL_SIZE);
    record_count = RECORD_ARRAY_INITIAL_SIZE;

    for (size_t i = 0; i < record_count; ++i) {
        total_int_value += record_array[i].value;
        total_buffer_size += int_keys[i];

        if (total_buffer_size > BUFFER_MAX_THRESHOLD) {
            fprintf(stderr, "Buffer size limit exceeded\n");
            exit(EXIT_FAILURE);
        }
    }

    if (total_int_value > MAX_TOTAL_INT_VALUE || total_buffer_size > TOTAL_MAX_THRESHOLD) {
        // Handle edge cases with fallback strategies
        printf("Edge case encountered. Adjusting allocations.\n");
    }

    pthread_mutex_unlock(&record_lock);

    // Example cleanup after usage
    for (size_t i = 0; i < record_count; ++i) {
        free(record_array[i].buffer);
    }
    free(record_array);
}

void* concurrent_access(void *arg) {
    manage_records();
    return NULL;
}

int main() {
    srand(time(NULL));
    init_memory();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, concurrent_access, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
